CREATE OR REPLACE 
PACKAGE calcdublicate_pg
IS
    -- пакет для работы с расчетными точками дублирующих счетчиков
    -- дата создания 08/08/2005 Коваленко А.С.

    --------------------------------------------------------------------------------
-- Копирует данные с одной точки на другую
-- Перед копированием все данные за заданый промежуток с точки приемника удаляются
-- an_dmid - ид точки на которую копируются данные
-- an_smid - ид точки с которой копируются данные
-- ad_sdate - дата начала копирования данных (изключительно)
-- ad_edate - дата окончания копирования данных (включительно)
-- av_tablename - таблица копирования данных
    PROCEDURE copy_point_data_p (an_dmid NUMBER, an_smid NUMBER, ad_sdate DATE, ad_edate DATE, av_tablename VARCHAR2);
    --------------------------------------------------------------------------------
-- Копирует данные с одной точки на другую
-- Перед копированием все данные за заданый промежуток с точки приемника удаляются
-- an_mid - ид точки с которой копируются данные, приемник находится по родителю
-- ad_sdate - дата начала копирования данных (изключительно)
-- ad_edate - дата окончания копирования данных (включительно)
    PROCEDURE copy_point_data_p (an_mid NUMBER, ad_sdate DATE, ad_edate DATE);
    --------------------------------------------------------------------------------
-- Добавляет переключение на дублирующий счетчик
-- Перед копированием все данные за заданый промежуток с точки приемника удаляются
-- по даты an_smid, ad_sdate включительно
-- an_mid - ид точки дублирующего счетчика
-- ad_sdate - дата начала копирования данных (включительно)
-- ad_edate - дата окончания копирования данных (включительно)
    PROCEDURE add_edit_sw_p (an_mid NUMBER, ad_sdate DATE, ad_edate DATE, av_memo varchar2);
    --------------------------------------------------------------------------------
-- Удаляет переключение на дублирующий счетчик
-- an_mid - ид точки дублирующего счетчика
-- ad_sdate - дата начала интервала переключения
    PROCEDURE del_sw_p (an_mid NUMBER, ad_sdate DATE);
    --------------------------------------------------------------------------------

-- Копирует данные на расчетную точку используется в фоновом процессе
-- Перед копированием все данные за заданый промежуток с точки удаляются
-- по даты an_smid, ad_sdate включительно
-- an_mid - ид расчетной точки
-- ad_sdate - дата начала копирования данных (включительно)
-- ad_edate - дата окончания копирования данных (включительно)
-- выбор с какой точки брать данные отределяется посредством сканирования таблицы calcbyduplication

    PROCEDURE copy_point_data_backgr_p (an_mid NUMBER, ad_sdate DATE, ad_edate DATE);
    --------------------------------------------------------------------------------

-- Копирует данные на расчетные точки используется в фоновом процессе
-- Перед копированием все данные за заданый промежуток с точек удаляются
-- по даты an_smid, ad_sdate включительно
-- an_mid - ид расчетной точки
-- ad_sdate - дата начала копирования данных (включительно)
-- ad_edate - дата окончания копирования данных (включительно)

    PROCEDURE copy_points_data_backgr_p (an_maket NUMBER, ad_sdate DATE);
    --------------------------------------------------------------------------------

END;   -- Package spec
/


