PACKAGE iccp_pg IS
 ------------------------------------------------------------------------------------------------------------------------
   -- пакет обмена по iccp
   -- дата создания 19/12/2007 Сечин А.А.
------------------------------------------------------------------------------------------------------------------------
 TYPE tt_timestamp IS TABLE OF TIMESTAMP
--  TYPE tt_timestamp IS TABLE OF VARCHAR2
 INDEX BY BINARY_INTEGER;
------------------------------------------------------------------------------------------------------------------------
 -- Поцедура получения текущих значений параметра
 PROCEDURE getcurrentdata (
  av_name            VARCHAR2,   -- имя параметра;
  an_result    OUT   NUMBER,   -- код результата выполнения: ( 0  - выполнена без ошибок;  110 - параметр с заданным именем не найден; -1 - другая ошибка.)
  an_value     OUT   NUMBER,   -- значение параметра, считанное из БД;
  an_quality   OUT   NUMBER,   -- значение флагов качества параметра, считанное из БД;
  ad_date      OUT   VARCHAR2
 );   --TIMESTAMP); -- время записи параметра в БД (TimeStamp получения значения параметра).
------------------------------------------------------------------------------------------------------------------------
-- Поцедура получения текущих значений параметра для временного среза
 PROCEDURE getcurrentdatafortime (
  av_name            VARCHAR2,   -- имя параметра;
  av_time            VARCHAR2,   -- временной срез в формате "DD-ММ-YY HH:MM:SS.SSS;
  an_result    OUT   NUMBER,   -- код результата выполнения: ( 0  - выполнена без ошибок;  110 - параметр с заданным именем не найден; -1 - другая ошибка.)
  an_value     OUT   NUMBER,   -- значение параметра, считанное из БД;
  an_quality   OUT   NUMBER,   -- значение флагов качества параметра, считанное из БД;
  ad_date      OUT   VARCHAR2
 );   --TIMESTAMP); -- время записи параметра в БД (TimeStamp получения значения параметра).
------------------------------------------------------------------------------------------------------------------------
 PROCEDURE getlistcurrentdata (
  at_name                 common_pg.tt_varchar2,   -- массив имен параметров;
  an_result         OUT   NUMBER,   -- код результата выполнения: 0  - выполнена без ошибок (параметр с заданным именем найден); -1 - ошибка выполнения.
  at_namesoffound   OUT   common_pg.tt_varchar2,   -- массив имен параметров, для которых найдены значения;
  at_value          OUT   common_pg.tt_number,   -- массив значений найденных параметров;
  at_quality        OUT   common_pg.tt_number,   -- массив флагов качества значений найденных параметров;
  at_date           OUT   common_pg.tt_varchar2,  -- массив времен записи в БД для найденных параметров;
  at_namesoflost    OUT   common_pg.tt_varchar2
 );   -- массив имен параметров, для которых не найдены значения;
------------------------------------------------------------------------------------------------------------------------
 PROCEDURE getlistcurrentdataforperiod (
  av_name              VARCHAR2,   -- имя параметра;
  ad_timestart         VARCHAR2,   -- начало интервала просмотра в формате "DD-ММ-YY HH:MM:SS.SSS";
  ad_timestop          VARCHAR2,   -- окончание интервала просмотра в формате "DD-ММ-YY HH:MM:SS.SSS";
  an_result      OUT   NUMBER,   -- код результата выполнения: 0  - выполнена без ошибок (параметр с заданным именем найден); -1 - ошибка выполнения.
  at_lasttime    OUT   VARCHAR2,   -- последняя найденная метка времени в формате "DD-ММ-YY HH:MM:SS.SSS";
  at_value       OUT   common_pg.tt_number,   -- массив значений ;
  at_quality     OUT   common_pg.tt_number,   -- массив флагов качества;
  at_date        OUT   common_pg.tt_varchar2
 );   -- массив времен записи в БД;
------------------------------------------------------------------------------------------------------------------------
 PROCEDURE setcurrentdata (
  av_name            VARCHAR2,   -- имя параметра;
