  an_value           NUMBER,   -- значение параметра, считанное из БД;
  an_quality         NUMBER,   -- значение флагов качества параметра, считанное из БД;
  ad_date            VARCHAR2
 );   --TIMESTAMP); -- время записи параметра в БД (TimeStamp получения значения параметра).
------------------------------------------------------------------------------------------------------------------------
 PROCEDURE setlistcurrentdata (
  at_name            common_pg.tt_varchar2,   -- массив имен параметров;
  an_result    OUT   NUMBER,   -- код результата выполнения
  at_value           common_pg.tt_number,   -- массив значений найденных параметров;
  at_quality         common_pg.tt_number,   -- массив флагов качества значений найденных параметров;
  at_date            tt_timestamp
 );   -- массив времен записи в БД для найденных параметров;
------------------------------------------------------------------------------------------------------------------------
END;   -- Package Specification iccp_pg
