CREATE OR REPLACE 
PACKAGE monitoring_pg
  -- пакет мониторинга системы
  -- дата создания 20.02.2004 (Коваленко А.С.)
------------------------------------------------------------------------------------------------------------------------
IS
-- Проверяет по всем точкам данной группы произведен опрос на установленную дату или нет
-- Возвращает 0 если данные есть, иначе - если нет

   -- an_id - ид точки или группы

   -- если ad_control_date = NULL, то дата контроля берется с таблици feeders (ncommcontrol,ntechcontrol)

   -- an_data_control - тип контролируемых данных
-- 1 - profile
-- 2 - halfhour
-- 3 - bill
-- 4 - months

   -- an_control_type - тип контроля 0 - коммерческий 1 - технический

   -- an_table имя таблицы с которой берутся точки 0 - points 1 - groups

   -- an_flagTimeControl если 1 то реагируем на временные рамки при проверке 0 - нет
   FUNCTION get_group_point_status_f (
      an_id                NUMBER,
      ad_control_date      DATE,
      an_data_control      NUMBER,
      an_control_type      NUMBER,
      an_table             NUMBER,
      an_flagtimecontrol   NUMBER
   )
      RETURN NUMBER;

   PRAGMA RESTRICT_REFERENCES (get_group_point_status_f, WNDS, WNPS);

------------------------------------------------------------------------------------------------------------------------
-- Возвращает >0 если по каким то точкам стоит флажек отсутствия данных
-- an_role_id - Ид роли для которой производится проверка
-- an_test_type - Тип проверки 0 - комерческие данные 1 - технические
   FUNCTION get_role_beep_status_f (an_role_id NUMBER, an_test_type NUMBER)
      RETURN NUMBER;

   PRAGMA RESTRICT_REFERENCES (get_role_beep_status_f, WNDS, WNPS);
------------------------------------------------------------------------------------------------------------------------
-- Квитирует отсутсвие данных
   procedure receipt_data_absence_p (an_role_id NUMBER, an_test_type NUMBER);
------------------------------------------------------------------------------------------------------------------------

END;                                                           -- Package spec
/


