PACKAGE BODY admin_pg IS
------------------------------------------------------------------------------------------------------------------------
  -- пакет по администрированию АСКУЭ
  -- дата создания 12/10/2001 Сечин А.А.
------------------------------------------------------------------------------------------------------------------------
 lv_deftablespace   VARCHAR2 (32);
 lv_tmptablespace   VARCHAR2 (32);

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE createorauser_p (av_user VARCHAR2, av_pass VARCHAR2);

------------------------------------------------------------------------------------------------------------------------
  -- Процедура установки параметров сессии;
 PROCEDURE begin_p IS
  lb_err   BOOLEAN DEFAULT FALSE;
 BEGIN
  --установка параметров сессии
  BEGIN
   EXECUTE IMMEDIATE 'ALTER SESSION SET NLS_TERRITORY = CIS NLS_LANGUAGE = RUSSIAN NLS_NUMERIC_CHARACTERS = ''.,''';
  EXCEPTION
   WHEN OTHERS THEN
    lb_err := TRUE;
  END;

  IF lb_err THEN
   BEGIN
    EXECUTE IMMEDIATE 'ALTER SESSION SET NLS_TERRITORY = RUSSIA NLS_LANGUAGE = RUSSIAN NLS_NUMERIC_CHARACTERS = ''.,''';
   EXCEPTION
    WHEN OTHERS THEN
     lb_err := TRUE;
   END;
  END IF;

  IF lb_err THEN
   BEGIN
    EXECUTE IMMEDIATE 'ALTER SESSION SET NLS_LANGUAGE = RUSSIAN NLS_NUMERIC_CHARACTERS = ''.,''';
   EXCEPTION
    WHEN OTHERS THEN
     lb_err := TRUE;
   END;
  END IF;
 END;   -- begin_p

------------------------------------------------------------------------------------------------------------------------
  -- Процедура установки параметров сессии и проверки прав
 PROCEDURE beginadm_p IS
  ln_cnt   NUMBER;
 BEGIN
  SELECT COUNT (*)
    INTO ln_cnt
    FROM DUAL
   WHERE USER IN ('RYDA', 'SYS', 'SYSTEM') OR EXISTS (SELECT *
                                                        FROM users
                                                       WHERE UPPER (usr) = USER AND ADMIN = '*');

  IF ln_cnt = 0 THEN
   raise_application_error (-20001, 'В доступе отказано');
  END IF;

  admin_pg.begin_p;
 END;

------------------------------------------------------------------------------------------------------------------------
--Запись в журнал пользователя
 PROCEDURE fiscal_p (an_task NUMBER, an_job NUMBER, av_message VARCHAR2) IS
 BEGIN
  INSERT INTO fiscal
              (date_time, task_cod, task_job, NAME, MESSAGE
              )
       VALUES (SYSDATE, an_task, an_job, common_pg.username_f, SUBSTR (av_message, 1, 510)
              );
 END;

------------------------------------------------------------------------------------------------------------------------
--Запись в журнал системы
 PROCEDURE journal_p (an_mid NUMBER, an_state_cod NUMBER, av_message VARCHAR2, an_submit NUMBER) IS
  ln_ret   NUMBER;
 BEGIN
  ln_ret := ins_journal_p (SYSDATE, an_mid, an_state_cod, av_message, NULL, NULL);
 END;

------------------------------------------------------------------------------------------------------------------------
 --Запись в журнал системы
 FUNCTION ins_journal_p (ad_date DATE, an_mid NUMBER, an_state_cod NUMBER, av_message VARCHAR2, an_event NUMBER, av_code VARCHAR2)
  RETURN NUMBER IS
  ln_tmp   NUMBER;
 BEGIN
  IF an_event <> 0 THEN
   SELECT COUNT (*)
     INTO ln_tmp
     FROM DUAL
    WHERE EXISTS (SELECT *
                    FROM journal
                   WHERE date_time = ad_date AND mid = an_mid AND nevent = an_event AND vcode = av_code);

   IF ln_tmp = 1 THEN
    RETURN 0;
   END IF;
  END IF;

  INSERT INTO journal
              (date_time, mid, state_cod, state_descr, nevent, vcode
              )
       VALUES (ad_date, an_mid, an_state_cod, SUBSTR (av_message, 1, 512), an_event, av_code
              );

  RETURN 1;
 END;

------------------------------------------------------------------------------------------------------------------------
--Блокировка с попытками
 FUNCTION lock_p (an_timecount NUMBER, av_tablename VARCHAR2)
  RETURN NUMBER IS
  cn_wait   CONSTANT NUMBER := 4;
  ln_timecount       NUMBER DEFAULT TRUNC (an_timecount) * cn_wait;
 BEGIN
  FOR i IN 1 .. ln_timecount LOOP
   BEGIN
    EXECUTE IMMEDIATE 'LOCK TABLE ' || av_tablename || ' IN EXCLUSIVE MODE NOWAIT';

    RETURN 1;
   EXCEPTION
    WHEN OTHERS THEN
     IF SQLCODE = -54 THEN
      IF i <> ln_timecount THEN
       SYS.DBMS_LOCK.sleep (1 / cn_wait);
      END IF;
     ELSE
      RAISE;
     END IF;
   END;
  END LOOP;

  RETURN 0;
 END;

------------------------------------------------------------------------------------------------------------------------
--Запись текущих данных в архив
 PROCEDURE curr_power_arch_ins_p (an_mid NUMBER, ad_date_time DATE, an_er NUMBER, an_q1 NUMBER, an_q2 NUMBER, an_ed NUMBER, an_q3 NUMBER, an_q4 NUMBER,
 an_erm NUMBER, an_q1m NUMBER, an_q2m NUMBER, an_edm NUMBER, an_q3m NUMBER, an_q4m NUMBER, an_freq NUMBER, an_cosf NUMBER, an_volt NUMBER,   --Напряжение A
 an_currento NUMBER,   --Ток A
                    an_volt2 NUMBER,   --Напряжение B
                                    an_volt3 NUMBER,   --Напряжение C
                                                    an_curr2 NUMBER,   --Ток B
                                                                    an_curr3 NUMBER,   --Ток C
                                                                                    an_fiu1 NUMBER,   --Угол напр 1
                                                                                                   an_fiu2 NUMBER,   --Угол напр 2
                                                                                                                  an_fiu3 NUMBER,   --Угол напр 3
                                                                                                                                 an_fii1 NUMBER,   --Угол тока 1
 an_fii2 NUMBER,   --Угол тока 2
                an_fii3 NUMBER   --Угол тока 3
 ) IS
  cn_minvolt   CONSTANT NUMBER := 96.18;
  cn_maxvolt   CONSTANT NUMBER := 105.525;
  ln_needarch           NUMBER DEFAULT util_pg.getparamvalue_f (25);
 BEGIN
  IF ln_needarch = 1 OR (ln_needarch = 2 AND (an_volt > cn_maxvolt OR an_volt < cn_minvolt OR an_volt3 > cn_maxvolt OR an_volt3 < cn_minvolt)) THEN
   BEGIN
    INSERT INTO curr_power_arch
                (mid, date_time, er, q1, q2, ed, q3, q4, erm, q1m, q2m, edm, q3m, q4m, freq, cosf, volt,
                 currento, volt2, volt3, curr2, curr3, nfiu1, nfiu2, nfiu3, nfii1, nfii2, nfii3
                )
         VALUES (an_mid, ad_date_time, an_er, an_q1, an_q2, an_ed, an_q3, an_q4, an_erm, an_q1m, an_q2m, an_edm, an_q3m, an_q4m, an_freq, an_cosf, an_volt,
                 an_currento, an_volt2, an_volt3, an_curr2, an_curr3, an_fiu1, an_fiu2, an_fiu3, an_fii1, an_fii2, an_fii3
                );
   EXCEPTION
    WHEN DUP_VAL_ON_INDEX THEN
     UPDATE curr_power_arch
        SET er = NVL (an_er, er),
            q1 = NVL (an_q1, q1),
            q2 = NVL (an_q2, q2),
            ed = NVL (an_ed, ed),
            q3 = NVL (an_q3, q3),
            q4 = NVL (an_q4, q4),
            erm = NVL (an_erm, erm),
            q1m = NVL (an_q1m, q1m),
            q2m = NVL (an_q2m, q2m),
            edm = NVL (an_edm, edm),
            q3m = NVL (an_q3m, q3m),
            q4m = NVL (an_q4m, q4m),
            freq = NVL (an_freq, freq),
            cosf = NVL (an_cosf, cosf),
            volt = NVL (an_volt, volt),
            currento = NVL (an_currento, currento),
            volt2 = NVL (an_volt2, volt2),
            volt3 = NVL (an_volt3, volt3),
            curr2 = NVL (an_curr2, curr2),
            curr3 = NVL (an_curr3, curr3),
            nfiu1 = NVL (an_fiu1, nfiu1),
            nfiu2 = NVL (an_fiu2, nfiu2),
            nfiu3 = NVL (an_fiu3, nfiu3),
            nfii1 = NVL (an_fii1, nfii1),
            nfii2 = NVL (an_fii2, nfii2),
            nfii3 = NVL (an_fii3, nfii3)
      WHERE mid = an_mid AND date_time = ad_date_time;
    WHEN OTHERS THEN
     raise_application_error (-20001, 'admin_pg.curr_power_arch_ins_p: ' || SQLERRM (SQLCODE));
   END;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
--Запись события по компорту в log
 PROCEDURE set_comport_event_p (an_com NUMBER, av_event VARCHAR2) IS
  ld_sys     DATE   DEFAULT SYSDATE;
  ln_order   NUMBER;
  ln_seq     NUMBER;
 BEGIN
  IF NVL (util_pg.locksysjournal_f, 0) <> 1 THEN
   BEGIN
    INSERT INTO comportevents
                (norder, com_id, dlastevent, vlastevent
                )
         VALUES (comport_seq.NEXTVAL, an_com, ld_sys, av_event
                );
   EXCEPTION
    WHEN DUP_VAL_ON_INDEX THEN
     SELECT MAX (norder)
       INTO ln_order
       FROM comportevents;

     SELECT comport_seq.NEXTVAL
       INTO ln_seq
       FROM DUAL;

     WHILE ln_seq <= ln_order AND ln_seq > 0 LOOP
      SELECT comport_seq.NEXTVAL
        INTO ln_seq
        FROM DUAL;
     END LOOP;

     INSERT INTO comportevents
                 (norder, com_id, dlastevent, vlastevent
                 )
          VALUES (comport_seq.NEXTVAL, an_com, ld_sys, av_event
                 );
    WHEN OTHERS THEN
     RAISE;
   END;
  END IF;

  UPDATE comports
     SET dlastevent = ld_sys,
         vlastevent = av_event
   WHERE com_id = an_com;
 END;

------------------------------------------------------------------------------------------------------------------------
--Возвращает дату расчетного периода
 FUNCTION get_calcperiod
  RETURN DATE IS
  ld_ret   DATE;
 BEGIN
  SELECT MAX (TO_DATE (vvalue, 'dd.mm.yyyy'))
    INTO ld_ret
    FROM parameter
   WHERE npid = 19;

  RETURN ld_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
--Устанавливает дату расчетного периода
 PROCEDURE set_calcperiod (d DATE) IS
 BEGIN
  UPDATE parameter
     SET vvalue = TO_CHAR (d, 'dd.mm.yyyy')
   WHERE npid = 19;
 END;

------------------------------------------------------------------------------------------------------------------------
--Увеличивает дату расчетного периода
 PROCEDURE add_calcperiod (c NUMBER) IS
 BEGIN
  UPDATE parameter
     SET vvalue = TO_CHAR (TO_DATE (vvalue, 'dd.mm.yyyy') + c, 'dd.mm.yyyy')
   WHERE npid = 19;
 END;

