 PROCEDURE inslog (an_operation NUMBER, av_tablename VARCHAR2, av_colname VARCHAR2, av_newvalue VARCHAR2) IS
  ld_date    DATE;
  ln_count   NUMBER;
 BEGIN
  IF av_newvalue IS NOT NULL THEN
   INSERT INTO fulljournal
               (dsys, vuser, vtype, vterminal, noperation, vtable, vcolumn, vold, vnew
               )
        VALUES (SYSDATE, common_pg.username_f, 'I', USERENV ('TERMINAL'), an_operation, av_tablename, av_colname, NULL, av_newvalue
               );
  END IF;
 END;

