 PROCEDURE updlog (an_operation NUMBER, av_tablename VARCHAR2, av_colname VARCHAR2, av_oldvalue VARCHAR2, av_newvalue VARCHAR2, av_pk VARCHAR2) IS
 BEGIN
  IF av_oldvalue IS NOT NULL OR av_newvalue IS NOT NULL THEN
   INSERT INTO fulljournal
               (dsys, vuser, vtype, vterminal, noperation, vtable, vcolumn, vold, vnew, vpk
               )
        VALUES (SYSDATE, common_pg.username_f, 'U', USERENV ('TERMINAL'), an_operation, av_tablename, av_colname, av_oldvalue, av_newvalue, av_pk
               );
  END IF;
 END;

