  -- Возвращает основной курсор
 PROCEDURE getmschinfo (an_sort NUMBER, ret_t OUT common_pg.tcur) IS
  lv_sql                 VARCHAR2 (4000);
  cn_colcount   CONSTANT NUMBER          := 1;
 BEGIN
  lv_sql := 'SELECT NAME vname,MONITOR nmonitor,MONITOR nid FROM MONITOR_SCHEMES ORDER BY ';

  IF ABS (an_sort) > 0 AND ABS (an_sort) <= cn_colcount THEN
   lv_sql := lv_sql || ABS (an_sort);

   IF an_sort < 0 THEN
    lv_sql := lv_sql || ' desc';
   END IF;

   lv_sql := lv_sql || ',';
  END IF;

  lv_sql := lv_sql || ' 1';

  OPEN ret_t FOR lv_sql;
 END;

----------------------------------------------------------------
   -- Сохранение
 PROCEDURE updmsch_p (an_monitor IN OUT NUMBER,   --Ид схемы
                                               av_name VARCHAR2)   --название схемы
                                                                IS
  ln_ret   NUMBER;
 BEGIN
  IF (NVL (an_monitor, 0)) > 0 THEN
   UPDATE monitor_schemes
      SET NAME = av_name
    WHERE monitor = an_monitor;
  ELSE
   SELECT users_seq.NEXTVAL
     INTO ln_ret
     FROM DUAL;

   INSERT INTO monitor_schemes
               (monitor, NAME
               )
        VALUES (ln_ret, av_name
               );

   an_monitor := ln_ret;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20001, 'adminnew_pg.updmsch_p: ' || CHR (10) || SQLERRM (SQLCODE));
 END;

-------------------------------------------------------------------------------------------
    -- Удаление
 PROCEDURE delmsch_p (an_monitor NUMBER) IS
 BEGIN
  DELETE FROM monitor_schemes
        WHERE monitor = an_monitor;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20001, 'adminnew_pg.delmsch_p: ' || CHR (10) || SQLERRM (SQLCODE));
 END;

