 PROCEDURE grant_to_askue_work IS
 BEGIN
  BEGIN
   EXECUTE IMMEDIATE 'CREATE ROLE askue_work';
  EXCEPTION
   WHEN OTHERS THEN
    NULL;
  END;

  EXECUTE IMMEDIATE 'GRANT CREATE SESSION TO askue_work';

  EXECUTE IMMEDIATE 'GRANT ALTER SESSION TO askue_work';

  EXECUTE IMMEDIATE 'GRANT INSERT ON forms_ex TO askue_work';

  EXECUTE IMMEDIATE 'GRANT UPDATE ON forms_ex TO askue_work';

  FOR lc IN (SELECT 'grant select on ' || table_name || ' to ASKUE_WORK' c
               FROM user_tables
              WHERE table_name NOT IN ('USERPASS')
             UNION ALL
             SELECT 'grant select on ' || view_name || ' to ASKUE_WORK' c
               FROM user_views
             UNION ALL
             SELECT 'grant execute on ' || object_name || ' to ASKUE_WORK' c
               FROM user_objects
              WHERE object_type = 'PROCEDURE'
             UNION ALL
             SELECT 'grant execute on ' || object_name || ' to ASKUE_WORK' c
               FROM user_objects
              WHERE object_type = 'FUNCTION'
             UNION ALL
             SELECT 'grant execute on ' || object_name || ' to ASKUE_WORK' c
               FROM user_objects
              WHERE object_type = 'PACKAGE' AND object_name NOT IN ('ADMIN_PG')) LOOP
   BEGIN
    EXECUTE IMMEDIATE lc.c;
   EXCEPTION
    WHEN OTHERS THEN
     NULL;
   END;
  END LOOP;
 END;

