--Чистка БД (архивация и удаление)
 PROCEDURE save4kill (an_maket NUMBER, ad_date DATE) IS
  rec_cur      common_pg.tcur;
  col_list     VARCHAR2 (4000);
  sql_list     VARCHAR2 (4000);
  sql_text     VARCHAR2 (4000);
  file_row     VARCHAR2 (4000);
  handle       UTL_FILE.file_type;
  PATH         VARCHAR2 (100);
  ld_old       DATE;
  exist_data   NUMBER             DEFAULT 0;
  cnt          NUMBER             DEFAULT 0;
  cnt_const    NUMBER             DEFAULT 5000;
 BEGIN
  SELECT vvalue
    INTO PATH
    FROM parameter
   WHERE npid = 5;

  EXECUTE IMMEDIATE 'ALTER SESSION SET NLS_NUMERIC_CHARACTERS = '',.''';

  FOR table_cur IN (SELECT   t.*, TRIM (TO_CHAR (ROWNUM, '000')) rn
                        FROM db_term t
                    ORDER BY table_name) LOOP
   ld_old := TRUNC (ad_date) - table_cur.term;

   IF table_cur.narchived = 1 THEN
    sql_text :=
     'select count(*) from dual where exists(select * from ' || table_cur.table_name || ' where ' || table_cur.vindic_column || ' <= to_date('''
     || TO_CHAR (ld_old, 'dd.mm.yyyy hh24:mi') || ''',''dd.mm.yyyy hh24:mi'')+1 and ' || table_cur.vindic_column || ' > to_date('''
     || TO_CHAR (ld_old, 'dd.mm.yyyy hh24:mi') || ''',''dd.mm.yyyy hh24:mi'')) ';

    EXECUTE IMMEDIATE sql_text
                 INTO exist_data;

    IF exist_data = 1 THEN
     handle := UTL_FILE.fopen (PATH, 'a' || TO_CHAR (ld_old, 'yyyymmdd.') || NVL (table_cur.vextention, table_cur.rn), 'w');
     UTL_FILE.put_line (handle, 'LOAD DATA');
     UTL_FILE.put_line (handle, 'INFILE *');
     UTL_FILE.put_line (handle, 'APPEND');
     UTL_FILE.put_line (handle, 'INTO TABLE ' || table_cur.table_name);
     UTL_FILE.put_line (handle, 'FIELDS TERMINATED BY ''`'' OPTIONALLY ENCLOSED BY ''"'' ');
     col_list := '';
     sql_list := '';

     FOR col_cur IN (SELECT   *
                         FROM user_tab_columns
                        WHERE table_name = UPPER (table_cur.table_name)
                     ORDER BY column_id) LOOP
      IF col_cur.data_type = 'DATE' THEN
       col_list := col_list || ',' || col_cur.column_name || ' DATE "dd.mm.yyyy hh24:mi:ss"';
       sql_list := sql_list || '|| to_char(' || col_cur.column_name || ', ''dd.mm.yyyy hh24:mi:ss'')|| ''`'' ';
      ELSE
       col_list := col_list || ',' || col_cur.column_name;
       sql_list := sql_list || '||' || col_cur.column_name || '|| ''`'' ';
      END IF;
     END LOOP;

     col_list := '(' || SUBSTR (col_list, 2) || ')';
     sql_list := SUBSTR (sql_list, 3);
     UTL_FILE.put_line (handle, col_list);
     UTL_FILE.put_line (handle, 'BEGINDATA');
     sql_text :=
      'select ' || sql_list || ' from ' || table_cur.table_name || ' where ' || table_cur.vindic_column || ' <= to_date(''' || TO_CHAR (ld_old, 'dd.mm.yyyy')
      || ''',''dd.mm.yyyy'')+1 and ' || table_cur.vindic_column || ' > to_date(''' || TO_CHAR (ld_old, 'dd.mm.yyyy') || ''',''dd.mm.yyyy'') ';

     OPEN rec_cur FOR sql_text;

     LOOP
      FETCH rec_cur
       INTO file_row;

      EXIT WHEN rec_cur%NOTFOUND;
      UTL_FILE.put_line (handle, file_row);
     END LOOP;

     CLOSE rec_cur;

     UTL_FILE.fclose (handle);
    END IF;
   END IF;

   EXECUTE IMMEDIATE 'select count(*) from ' || table_cur.table_name || ' where ' || table_cur.vindic_column || ' <= to_date(''' || TO_CHAR (ld_old, 'dd.mm.yyyy')
                     || ''',''dd.mm.yyyy'')+1 and ' || table_cur.vindic_column || ' > to_date(''' || TO_CHAR (ld_old, 'dd.mm.yyyy') || ''',''dd.mm.yyyy'') '
                INTO cnt;

   FOR cur_col IN 1 .. FLOOR (cnt / cnt_const + 1) LOOP
    EXECUTE IMMEDIATE 'delete from ' || table_cur.table_name || ' where ' || table_cur.vindic_column || ' <= to_date(''' || TO_CHAR (ld_old, 'dd.mm.yyyy')
                      || ''',''dd.mm.yyyy'')+1 and ' || table_cur.vindic_column || ' > to_date(''' || TO_CHAR (ld_old, 'dd.mm.yyyy')
                      || ''',''dd.mm.yyyy'') and rownum <= ' || cnt_const;

    COMMIT;
   END LOOP;
  END LOOP;

  EXECUTE IMMEDIATE 'ALTER SESSION SET NLS_NUMERIC_CHARACTERS = ''.,''';
 EXCEPTION
  WHEN OTHERS THEN
   UTL_FILE.fclose (handle);

   EXECUTE IMMEDIATE 'ALTER SESSION SET NLS_NUMERIC_CHARACTERS = ''.,''';

   RAISE;
 END;   -- Procedure SAVE4KILL

