 --Чистка БД (date_time <)
 PROCEDURE killdata (an_maket NUMBER, ad_date DATE) IS
  rec_cur      common_pg.tcur;
  ld_old       DATE;
  ld_min       DATE;
  handle       UTL_FILE.file_type;
  PATH         VARCHAR2 (100);
  col_list     VARCHAR2 (4000);
  sql_list     VARCHAR2 (4000);
  sql_text     VARCHAR2 (4000);
  file_row     VARCHAR2 (4000);
  exist_data   NUMBER             DEFAULT 0;
  cnt          NUMBER             DEFAULT 0;
  cnt_const    NUMBER             DEFAULT 5000;
 BEGIN
  SELECT vvalue
    INTO PATH
    FROM parameter
   WHERE npid = 5;

  FOR table_cur IN (SELECT   TRIM (TO_CHAR (ROWNUM, '000')) rn, t.*
                        FROM db_term t
                    ORDER BY table_name) LOOP
   ld_old := TRUNC (ad_date) - table_cur.term;

   OPEN rec_cur FOR 'select trunc(min(' || table_cur.vindic_column || ')) from ' || table_cur.table_name;

   FETCH rec_cur
    INTO ld_min;

   CLOSE rec_cur;

   WHILE ld_min <= ld_old LOOP
    IF table_cur.narchived = 1 THEN
     EXECUTE IMMEDIATE 'select count(*) from dual where exists(select * from ' || table_cur.table_name || ' where ' || table_cur.vindic_column || ' <= to_date('''
                       || TO_CHAR (ld_min, 'dd.mm.yyyy') || ''',''dd.mm.yyyy'')+1 and ' || table_cur.vindic_column || ' > to_date('''
                       || TO_CHAR (ld_min, 'dd.mm.yyyy') || ''',''dd.mm.yyyy''))'
                  INTO exist_data;

     IF exist_data = 1 THEN
      handle := UTL_FILE.fopen (PATH, 'a' || TO_CHAR (ld_min, 'yyyymmdd.') || NVL (table_cur.vextention, table_cur.rn), 'w');
      UTL_FILE.put_line (handle, 'LOAD DATA');
      UTL_FILE.put_line (handle, 'INFILE *');
      UTL_FILE.put_line (handle, 'APPEND');
      UTL_FILE.put_line (handle, 'INTO TABLE ' || table_cur.table_name);
      UTL_FILE.put_line (handle, 'FIELDS TERMINATED BY ''`'' OPTIONALLY ENCLOSED BY ''"'' ');
      col_list := '';
      sql_list := '';

      FOR col_cur IN (SELECT   *
                          FROM user_tab_columns
                         WHERE table_name = UPPER (table_cur.table_name)
                      ORDER BY column_id) LOOP
       IF col_cur.data_type = 'DATE' THEN
        col_list := col_list || ',' || col_cur.column_name || ' DATE "dd.mm.yyyy hh24:mi:ss"';
        sql_list := sql_list || '|| to_char(' || col_cur.column_name || ', ''dd.mm.yyyy hh24:mi:ss'')|| ''`'' ';
       ELSE
        col_list := col_list || ',' || col_cur.column_name;
        sql_list := sql_list || '||' || col_cur.column_name || '|| ''`'' ';
       END IF;
      END LOOP;

      col_list := '(' || SUBSTR (col_list, 2) || ')';
      sql_list := SUBSTR (sql_list, 3);
      UTL_FILE.put_line (handle, col_list);
      UTL_FILE.put_line (handle, 'BEGINDATA');
      sql_text :=
       'select ' || sql_list || ' from ' || table_cur.table_name || ' where ' || table_cur.vindic_column || ' <= to_date(''' || TO_CHAR (ld_min, 'dd.mm.yyyy')
       || ''',''dd.mm.yyyy'')+1 and ' || table_cur.vindic_column || ' > to_date(''' || TO_CHAR (ld_min, 'dd.mm.yyyy') || ''',''dd.mm.yyyy'') ';

      OPEN rec_cur FOR sql_text;

      LOOP
       FETCH rec_cur
        INTO file_row;

       EXIT WHEN rec_cur%NOTFOUND;
       UTL_FILE.put_line (handle, file_row);
      END LOOP;

      CLOSE rec_cur;

      UTL_FILE.fclose (handle);
     END IF;
    END IF;

    EXECUTE IMMEDIATE 'select count(*) from ' || table_cur.table_name || ' where ' || table_cur.vindic_column || ' <= to_date(''' || TO_CHAR (ld_min, 'dd.mm.yyyy')
                      || ''',''dd.mm.yyyy'')+1 and ' || table_cur.vindic_column || ' > to_date(''' || TO_CHAR (ld_min, 'dd.mm.yyyy') || ''',''dd.mm.yyyy'') '
                 INTO cnt;

    FOR cur_col IN 1 .. FLOOR (cnt / cnt_const + 1) LOOP
     EXECUTE IMMEDIATE 'delete from ' || table_cur.table_name || ' where ' || table_cur.vindic_column || ' <= to_date(''' || TO_CHAR (ld_min, 'dd.mm.yyyy')
                       || ''',''dd.mm.yyyy'')+1 and ' || table_cur.vindic_column || ' > to_date(''' || TO_CHAR (ld_min, 'dd.mm.yyyy')
                       || ''',''dd.mm.yyyy'') and rownum <= ' || cnt_const;

     COMMIT;
    END LOOP;

    ld_min := ld_min + 1;
   END LOOP;
  END LOOP;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001, 'background01_pg.killdata: ' || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 --Копирование данных на расчетные точки
 PROCEDURE setdataunrealpoints (an_maket NUMBER, ad_date DATE) IS
  cn_step   CONSTANT NUMBER              := 1 / 48;
  ld_date            DATE                DEFAULT TRUNC (ad_date);
  lc0                common_pg.tcur;
  lc1                common_pg.tcur;
  lc2                common_pg.tcur;
  lt_er              common_pg.tt_number;
  lt_ed              common_pg.tt_number;
  lt_q1              common_pg.tt_number;
  lt_q2              common_pg.tt_number;
  lt_q3              common_pg.tt_number;
  lt_q4              common_pg.tt_number;
  ln_i               NUMBER;
  ln_er              NUMBER;
  ln_ed              NUMBER;
  ln_q1              NUMBER;
  ln_q2              NUMBER;
  ln_q3              NUMBER;
  ln_q4              NUMBER;
  ln_mid             NUMBER;
  ln_realpoint       NUMBER;
  ln_ratio           NUMBER;
  lv_er              VARCHAR2 (256);
  lv_ed              VARCHAR2 (256);
  lv_q1              VARCHAR2 (256);
  lv_q2              VARCHAR2 (256);
  lv_q3              VARCHAR2 (256);
  lv_q4              VARCHAR2 (256);
  lv_sql             VARCHAR2 (2000);
  ln_cn              NUMBER              DEFAULT util_pg.get_count_dt (ld_date, cn_step);
 BEGIN
  IF admin_pg.lock_p (cn_lock, 'halfhourtmp') <> 1 THEN
   raise_application_error (-20009,
                            'Копирование данных на расчетные точки не может быть произведен ввиду отсутствия возможности блокировки таблицы в течении ' || cn_lock
                            || ' сек.',
                            TRUE);
  END IF;

  OPEN lc0 FOR 'select distinct mid from realpoint';

  LOOP
   FETCH lc0
    INTO ln_mid;

   EXIT WHEN lc0%NOTFOUND;

   DELETE      halfhourold
         WHERE mid = ln_mid AND date_time > ld_date AND date_time <= ld_date + 1;

   DELETE FROM halfhourtmp
         WHERE mid = ln_mid;

   FOR i IN 1 .. ln_cn LOOP
    lt_er (i) := NULL;
    lt_ed (i) := NULL;
    lt_q1 (i) := NULL;
    lt_q2 (i) := NULL;
    lt_q3 (i) := NULL;
    lt_q4 (i) := NULL;
   END LOOP;

   OPEN lc1 FOR 'SELECT nrealpoint,nvl(nratio,1) nratio,nvl(er,0) er,nvl(ed,0) ed,nvl(q1,0) q1,nvl(q2,0) q2,nvl(q3,0) q3,nvl(q4,0) q4 FROM realpoint where mid='
                || ln_mid || ' order by nrealpoint';

   LOOP
    FETCH lc1
     INTO ln_realpoint, ln_ratio, lv_er, lv_ed, lv_q1, lv_q2, lv_q3, lv_q4;

    EXIT WHEN lc1%NOTFOUND;

    BEGIN
     lv_sql :=
      'select util_pg.get_num_dt(date_time - 1 / 86400, nsource,1/48,0), sum(' || lv_er || '),sum(' || lv_ed || '),sum(' || lv_q1 || '),sum(' || lv_q2 || '),sum('
      || lv_q3 || '),sum(' || lv_q4 || ') ' || 'from halfhour where mid=' || ln_realpoint || ' and date_time >to_date(' || TO_CHAR (ld_date, 'YYYYMMDD')
      || ',''YYYYMMDD'') and ' || 'date_time <=to_date(' || TO_CHAR (ld_date + 1, 'YYYYMMDD') || ',''YYYYMMDD'') '
      || 'group by util_pg.get_num_dt(date_time - 1 / 86400, nsource,1/48,0) order by 1';

     OPEN lc2 FOR lv_sql;

     LOOP
      FETCH lc2
       INTO ln_i, ln_er, ln_ed, ln_q1, ln_q2, ln_q3, ln_q4;

      EXIT WHEN lc2%NOTFOUND;
      lt_er (ln_i) := util_pg.sumn (lt_er (ln_i), ln_ratio * ln_er);
      lt_ed (ln_i) := util_pg.sumn (lt_ed (ln_i), ln_ratio * ln_ed);
      lt_q1 (ln_i) := util_pg.sumn (lt_q1 (ln_i), ln_ratio * ln_q1);
      lt_q2 (ln_i) := util_pg.sumn (lt_q2 (ln_i), ln_ratio * ln_q2);
      lt_q3 (ln_i) := util_pg.sumn (lt_q3 (ln_i), ln_ratio * ln_q3);
      lt_q4 (ln_i) := util_pg.sumn (lt_q4 (ln_i), ln_ratio * ln_q4);
     END LOOP;

     CLOSE lc2;
    EXCEPTION
     WHEN OTHERS THEN
      IF lc2%ISOPEN THEN
       CLOSE lc2;
      END IF;
    END;
   END LOOP;

   CLOSE lc1;

   FOR i IN 1 .. ln_cn LOOP
    IF (lt_er (i) IS NOT NULL) OR (lt_ed (i) IS NOT NULL) OR (lt_q1 (i) IS NOT NULL) OR (lt_q2 (i) IS NOT NULL) OR (lt_q3 (i) IS NOT NULL)
       OR (lt_q4 (i) IS NOT NULL) THEN
     das_pg.ins_halfhourtmp (ln_mid, util_pg.to_unlocaltime_if_new (ld_date) + i * cn_step, NULL, lt_er (i), lt_ed (i), lt_q1 (i), lt_q2 (i), lt_q3 (i), lt_q4 (i),
                             NULL, NULL, NULL);
    END IF;
   END LOOP;
  END LOOP;

  CLOSE lc0;

  COMMIT;
  das_pg.checkhalfhour;
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001, 'background01_pg.setdataunrealpoints: ' || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------
  --Сигнал на обновление мониторов
 PROCEDURE refreshmonitor (an_maket NUMBER, ad_date DATE) IS
 BEGIN
  admin_pg.signal (4);   --curr_power

  IF INSTR (util_pg.get_param (file_pg.gv_param, 1), '1') > 0 THEN   --bill
   admin_pg.signal (1);
  END IF;

  IF INSTR (util_pg.get_param (file_pg.gv_param, 1), '2') > 0 THEN   --halfhour
   admin_pg.signal (2);
  END IF;

  IF INSTR (util_pg.get_param (file_pg.gv_param, 1), '3') > 0 THEN   --profile
   admin_pg.signal (3);
  END IF;

  IF INSTR (util_pg.get_param (file_pg.gv_param, 1), '5') > 0 THEN   --fiscal
   admin_pg.signal (5);
  END IF;

  IF INSTR (util_pg.get_param (file_pg.gv_param, 1), '6') > 0 THEN   --journal
   admin_pg.signal (6);
  END IF;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001, 'background01_pg.refreshmonitor: ' || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
  --Повторное создание макета после поступления данных
 PROCEDURE recreatemakets (an_maket NUMBER, ad_date DATE) IS
  cn_shift   CONSTANT NUMBER          := 30 / 86400;   --Не захотел заводиться с блокировками (между sysdate и commit проходит время и мы делаем зазор в 30 сек, т.к фоновый процесс работает реже чем раз в 30 сек)
  ln_shift            NUMBER;
  ln_maket            NUMBER;
  lv_param            VARCHAR2 (2000);
 BEGIN
  --Вычисляем сдвиг ограничения (для скорости);
  ln_shift := NVL (util_pg.allnumber_f (util_pg.get_param (file_pg.gv_param, 1)), 45);

  FOR i IN 2 .. LENGTH (file_pg.gv_param) LOOP
   --хватаем текущий макет
   ln_maket := util_pg.allnumber_f (util_pg.get_param (file_pg.gv_param, i));

   IF ln_maket > 0 THEN
    SELECT MAX (nmaket), MAX (vparam)
      INTO ln_maket, lv_param
      FROM makets
     WHERE nmaket = ln_maket;

    IF ln_maket IS NULL THEN
     GOTO to_continue;
    END IF;
   ELSE
    GOTO to_continue;
   END IF;

   FOR lc IN (SELECT DISTINCT f.ddate
                         FROM makets m,
                              deportfiles f,
                              deportation d,
                              maketgroups g,
                              maketpoints p,
                              (SELECT   mid, TRUNC (date_time - 1 / 86400) dt, MAX (denter) denter
                                   FROM halfhour
                                  WHERE date_time > TRUNC (SYSDATE) - ln_shift
                               GROUP BY mid, TRUNC (date_time - 1 / 86400)) b
                        WHERE m.nmaket = ln_maket AND m.nblock = 0 AND m.nmaket = d.nmaket AND d.nblock = 0 AND m.nmaket = g.nmaket AND g.ngroup = p.ngroup
                              AND p.mid = b.mid(+) AND d.ndeportation = f.ndeportation(+) AND f.ddate = b.dt AND f.denter < b.denter + cn_shift
              UNION
              SELECT DISTINCT f.ddate
                         FROM makets m,
                              deportfiles f,
                              deportation d,
                              maketgroups g,
                              maketpoints p,
                              (SELECT   mid, TRUNC (date_time) - 1 dt, MAX (denter) denter
                                   FROM billorg
                                  WHERE date_time > TRUNC (SYSDATE) - ln_shift
                               GROUP BY mid, TRUNC (date_time)) b
                        WHERE m.nmaket = ln_maket AND m.nblock = 0 AND m.nmaket = d.nmaket AND d.nblock = 0 AND m.nmaket = g.nmaket AND g.ngroup = p.ngroup
                              AND p.mid = b.mid(+) AND d.ndeportation = f.ndeportation(+) AND f.ddate = b.dt AND f.denter < b.denter + cn_shift
                     ORDER BY 1) LOOP
    file_pg.startimmediate_p (ln_maket, lc.ddate, lv_param);
    COMMIT;
   END LOOP;

   <<to_continue>>
   NULL;
  END LOOP;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001, 'background01_pg.recreatemakets: ' || SQLERRM (SQLCODE));
 END;
------------------------------------------------------------------------------------------------------------------------
END;   -- Package Body BACKGROUND01_PG
/


-- End of DDL Script for Package Body RYDA.BACKGROUND01_PG

-- Start of DDL Script for Package Body RYDA.CALC_PG
-- Generated 14.11.2008 08:47:54 from RYDA@sesreg

CREATE OR REPLACE 
PACKAGE BODY calc_pg IS
   gn_Task_Code NUMBER DEFAULT 502;
gn_order NUMBER := 1; -- счетчик строк
gn_group NUMBER; -- id - reportgroup
gn_period NUMBER; -- Период
gd_first DATE; -- Дата окончания прошлого отчетного периода
gd_last  DATE; -- Дата окончания текущего отчетного периода
type t_number is table of number index by BINARY_INTEGER;
gt_consump t_number; -- Сумма расхода подразделения
type t_varchar is table of Varchar2(32) index by BINARY_INTEGER;
gv_type t_varchar;
gv_typeSmall t_varchar;
--==========================================================================================
 --процедура смены периода
 PROCEDURE changeperiod_p IS
  ---------------------------------------------
  ld_1 DATE;
  ld_2 DATE;
  ld_3 DATE;
 ---------------------------------------------
 BEGIN
  BEGIN
   SELECT TO_DATE(vvalue, 'dd.mm.yyyy')
     INTO ld_1
     FROM parameter
    WHERE npid = 1;
   SELECT TO_DATE(vvalue, 'dd.mm.yyyy')
     INTO ld_2
     FROM parameter
    WHERE npid = 2;
   SELECT TO_DATE(vvalue, 'dd.mm.yyyy')
     INTO ld_3
     FROM parameter
    WHERE npid = 3;
  EXCEPTION
   WHEN OTHERS THEN
    raise_application_error(-20002, 'ADMIN_PG.changeperiod_p: Ошибка заполнения таблицы PARAMETER. ');
  END;
  IF NVL(provcalc_f, 1) != 1 THEN
   raise_application_error(
    -20002, 'ADMIN_PG.changeperiod_p: В данном месяце не проведен расчет. Смена переода расчета запрещена.');
  END IF;
  UPDATE parameter
     SET vvalue = TO_CHAR(ld_3, 'dd.mm.yyyy')
   WHERE npid = 2;
  UPDATE parameter
     SET vvalue = TO_CHAR(ADD_MONTHS(ld_3, 1), 'dd.mm.yyyy')
   WHERE npid = 3;

  admin_pg.fiscal_p(gn_Task_Code,2,'Произведена смена отчетного периода');

 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'ADMIN_PG.changeperiod_p: Ошибка изменения периода. ' || CHR(10) || SQLERRM(SQLCODE));
 END; --changeperiod_p
 ------------------------------------------------------------------------------------------------------------------------
 --процедура смены дня расчета
 PROCEDURE changecalcday_p(an_day NUMBER) IS
  ---------------------------------------------
  ld_3 DATE;
 ---------------------------------------------
 BEGIN
  SAVEPOINT changecalcday_s;
  BEGIN
   SELECT TO_DATE(vvalue, 'dd.mm.yyyy')
     INTO ld_3
     FROM parameter
    WHERE npid = 3;
  EXCEPTION
   WHEN OTHERS THEN
    raise_application_error(-20002, 'ADMIN_PG.changeperiod_p: Ошибка заполнения таблицы PARAMETER. ');
  END;
  IF an_day IS NULL OR NOT (TRUNC(an_day) BETWEEN 1 AND 31) THEN
   raise_application_error(-20002, 'ADMIN_PG.changeperiod_p: Входной параметр процедуры не допустим. ');
  END IF;
  IF TO_DATE(TO_CHAR(ld_3, 'YYYYMM') * 100 + TRUNC(an_day), 'YYYYMMDD') <= SYSDATE THEN
   raise_application_error(-20002, 'ADMIN_PG.changeperiod_p: Изменяемая дата не может быть меньше системной. ');
  END IF;
  UPDATE parameter
     SET vvalue = TO_CHAR(TO_DATE(TO_CHAR(ld_3, 'YYYYMM') * 100 + TRUNC(an_day), 'YYYYMMDD'), 'dd.mm.yyyy')
   WHERE npid IN (1, 3);
  DELETE FROM detturnover
        WHERE nperiod = TO_NUMBER(TO_CHAR(ld_3, 'YYYYMM'));
  admin_pg.fiscal_p(gn_Task_Code,2,'Произведена смена расчетного дня');
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT changecalcday_s;
   raise_application_error(-20001, 'ADMIN_PG.changecalcday_p: Ошибка дня расчета. ' || CHR(10) || SQLERRM(SQLCODE));
 END; --changecalcday_p
 ------------------------------------------------------------------------------------------------------------------------
   -- Проверка проведения расчета возвращает 1- Проведен, иначе нет
 FUNCTION provcalc_f
  RETURN NUMBER IS
  ln_count NUMBER;
  ld_3     DATE;
 BEGIN
  SELECT TO_DATE(vvalue, 'dd.mm.yyyy')
    INTO ld_3
    FROM parameter
   WHERE npid = 3;
  SELECT COUNT(*)
    INTO ln_count
    FROM DUAL
   WHERE EXISTS( SELECT *
                   FROM detturnover
                  WHERE nperiod = TO_NUMBER(TO_CHAR(ld_3, 'YYYYMM')));
  RETURN ln_count;
 END;
 ------------------------------------------------------------------------------------------------------------------------

--==========================================================================================



--- Процедура вставки записей в таблицу REPORTS
PROCEDURE REPORT_INS_P( AN_REPORTGROUP  IN NUMBER,
                        AN_PERIOD       IN NUMBER,
                        AN_ORDER        IN NUMBER,
                        AV_F1           IN VARCHAR2,
                        AV_F2           IN VARCHAR2,
                        AV_F3           IN VARCHAR2,
                        AV_F4           IN VARCHAR2,
                        AV_F5           IN VARCHAR2,
                        AV_F6           IN VARCHAR2,
                        AV_F7           IN VARCHAR2,
                        AV_F8           IN VARCHAR2,
                        AV_F9           IN VARCHAR2,
                        AV_F10          IN VARCHAR2,
                        AV_F11          IN VARCHAR2,
                        AV_F12          IN VARCHAR2)
IS
BEGIN

INSERT INTO  REPORTS
      ( NREPORTGROUP , NPERIOD , NORDER , VF1 , VF2
      , VF3 , VF4 , VF5 , VF6 , VF7
      , VF8 , VF9 , VF10 , VF11 , VF12 )
VALUES( AN_REPORTGROUP , AN_PERIOD , an_order , AV_F1 , AV_F2
      , AV_F3 , AV_F4 , AV_F5 , AV_F6 , AV_F7
      , AV_F8 , AV_F9 , AV_F10 , AV_F11 , AV_F12 );
gn_order := gn_order + 1;
END;
---------------------------------------------------------
---- Функция определения, является ли группа родителем---
---------------------------------------------------------

FUNCTION Isgroup_f
     ( an_group         IN NUMBER)
     RETURN  NUMBER
IS
ln_ret NUMBER;
Begin
    Select count(0) into ln_ret from dual
    Where exists (Select * from REPORTGROUPS Where nParent = an_group);
return ln_ret;
End;


-------------------------------------------------------
------- Процедура  записи данных по точкам ------------
-------------------------------------------------------
PROCEDURE INS_POINTS(an_parent IN NUMBER, -- Группа
                     av_title  IN VARCHAR2, -- Наименование
                     an_sign   IN NUMBER, -- Знак -- "-1" - отрицательные
                                                  --  "0" - положительные
                     an_include IN BOOLEAN ) -- Вхождение в группу: true - в том числе
IS
type r_meters is record  (mtrsn VARCHAR2(20), KC NUMBER, mtype VARCHAR2(50), digits NUMBER, date_time DATE);
type t_meters is table of r_meters index by BINARY_INTEGER;
ld_first DATE;
ld_last  DATE;
ln_ind t_number;
ln_newind t_number;
ln_type t_number;
lr_meters r_meters;
lt_meters t_meters;
ln_consump t_number;
ln_consump_all t_number; -- Расход по все точкам группы
ln_diff NUMBER;
ln_digits NUMBER;
lb_found BOOLEAN :=true ;
lb_title BOOLEAN := false;
ln_i BINARY_INTEGER;
lv_title VARCHAR2(128);

lb_inst BOOLEAN;
ln_first_ind NUMBER;
ln_consump_ins NUMBER;
ln_consump_sum NUMBER;
lv_DDD VARCHAR2(16);
CURSOR lcur_point(an_parent number) IS
SELECT R.NREPORTGROUP , R.NPARENT , R.VNAME , R.NGROUPTYPE , R.VGROUPKIND
     , R.NPROCEDURE , R.NDEPARTMENT , R.MID , nvl(R.NCOEF,1) NKOEF, NVL(F.KC,1) KC
FROM REPORTGROUPS R, FEEDERS F
WHERE R.MID = F.MID(+) and R.NPARENT = an_parent and
      r.mid > 0 and nvl(R.NCOEF,1) between an_sign and an_sign + 1
ORDER BY  R.VNAME;

Cursor lcur_Indication (an_mid NUMBER, ad_first DATE, ad_last DATE) IS
SELECT /*r.er_mtrsn,r.er_kc,r.erm,r.er,
       r.q1_mtrsn,r.q1_kc,r.q1m, r.q1,
       r.ed_mtrsn,r.ed_kc,r.edm, r.ed,
       r.q3_mtrsn, r.q3_kc, r.q3m, r.q3*/
       max(r.erm), max(r.q1m), max(r.edm), max(r.q3m)
FROM bill r
Where mid = an_mid and
      date_time = (Select min(date_time) from bill
                   Where mid = an_mid and
                         date_time between ad_first and ad_last);

Cursor lcur_consumption (an_mid NUMBER, ad_first DATE, ad_last DATE) IS
SELECT sum(nvl(r.er,0)) er, sum(nvl(r.q1,0)) q1, sum(nvl(r.ed,0)) ed, sum(nvl(r.q3,0)) q3
FROM bill r
Where mid = an_mid and
      date_time between ad_first+1 and ad_last;

Cursor lcur_Meters(an_mid NUMBER, an_type NUMBER) IS
Select substr(mtrsn,1,32) mtrsn, kc, mtype, digits, date_time from Meters
Where mid = an_mid and (entype in (an_type,7) or Smart = '*') and
date_time = (Select max(date_time) from Meters
              Where mid=an_mid and date_time <= ld_last
                    and (entype in (an_type,7) or Smart = '*'));
-- Нахождение снятых счетчиков
Cursor lcur_Bill_Del(an_mid NUMBER, an_type NUMBER,
                     ad_first DATE, ad_last DATE) IS
Select date_time, decode(an_type,1,r.er_mtrsn,2, r.q1_mtrsn, 3, r.ed_mtrsn,4,r.q3_mtrsn) mtrsn,
       substr(r.remark, instr(r.remark, '[') +1, instr(r.remark, ']')- instr(r.remark, '[')-1) type,
       decode(an_type,1,r.erm,2, r.q1m, 3, r.edm,4,r.q3m) ind,
       decode(an_type,1,r.er,2, r.q1, 3, r.ed,4,r.q3) diff
from Bill r
Where mid=an_mid and
      date_time between ad_first+1 and ad_last and
      r.source = 'Снт' and
      decode(an_type,1,r.er_mtrsn,2, r.q1_mtrsn, 3, r.ed_mtrsn,4,r.q3_mtrsn) is not null and
      decode(an_type,1,r.erm,2, r.q1m, 3, r.edm,4,r.q3m) is not null and
      decode(an_type,1,r.er,2, r.q1, 3, r.ed,4,r.q3) is not null
order by date_time;
-- Расход по счетчику (если были замены)
Cursor lcur_consumption_ins(an_mid NUMBER, an_type NUMBER, ad_first DATE, ad_last DATE, AV_MTRSN VARCHAR2) IS
SELECT sum(decode(an_type,1,r.er,2, r.q1, 3, r.ed,4,r.q3)) nConsump
FROM bill r
Where mid = an_mid and
      date_time between ad_first+1 and ad_last and
      decode(an_type,1,r.er_mtrsn,2, r.q1_mtrsn, 3, r.ed_mtrsn,4,r.q3_mtrsn) = av_mtrsn;
-- Начальные показания установленных счетчиков
Cursor lcur_Bill_Ins(an_mid NUMBER, an_type NUMBER,
                     ad_first DATE, ad_last DATE, AV_MTRSN VARCHAR2) IS
Select decode(an_type,1,r1.erm,2, r1.q1m, 3, r1.edm,4,r1.q3m) ind
from Bill r1
Where mid=an_mid and
      date_time = (Select min(date_time) from Bill r
                   Where date_time between ad_first and ad_last and
                         decode(an_type,1,r.er_mtrsn,2, r.q1_mtrsn, 3, r.ed_mtrsn,4,r.q3_mtrsn) = av_mtrsn and
                         decode(an_type,1,r.erm,2, r.q1m, 3, r.edm,4,r.q3m) is not null);

BEGIN
ld_first := gd_first;
ld_last := gd_last;
FOR ln_i in 1..4 LOOP
    ln_consump_all(ln_i) := 0;
END LOOP;
--------------------------------
-- Цикл по точкам---------------
--------------------------------
FOR lc_point in lcur_point(an_parent) LOOP

    -- Старые показания
    Open lcur_Indication(lc_point.mid, gd_first, gd_last);
    Fetch lcur_Indication into ln_ind(1), ln_ind(2), ln_ind(3), ln_ind(4);
    If lcur_Indication%NOTFOUND Then lb_found := false; End IF;
    Close lcur_Indication;
    -- Новые показания
    IF lb_found Then
        Open lcur_Indication(lc_point.mid, gd_last, gd_last);
        Fetch lcur_Indication into ln_newind(1), ln_newind(2), ln_newind(3), ln_newind(4);
--        If lcur_Indication%NOTFOUND Then lb_found := false; End IF;
        Close lcur_Indication;
    End IF;
    -- Расход
    IF lb_found Then
        Open lcur_consumption(lc_point.mid, gd_first, gd_last);
        Fetch lcur_consumption into ln_consump(1), ln_consump(2), ln_consump(3), ln_consump(4);
        Close lcur_consumption;
    End IF;

    -- Данные по счетчикам
    IF lb_found Then
        ln_type(1) := 1;ln_type(2) := 3;ln_type(3) := 2;ln_type(4) := 5;
        FOR ln_i in 1..4 LOOP
            Open lcur_Meters(lc_point.mid, ln_type(ln_i));
            Fetch lcur_Meters INTO lr_meters.mtrsn, lr_meters.KC, lr_meters.mtype, lr_meters.digits, lr_meters.date_time;
            If lcur_Meters%NOTFOUND Then
                lr_meters.mtrsn:=null;
                lr_meters.KC:= 1;
                lr_meters.mtype:= '';
                lr_meters.digits := 0;
            End IF;
            lt_meters(ln_i) := lr_meters;
            Close lcur_Meters;
        END LOOP;
    End IF;
    -- Заполнение таблицы
    IF lb_found Then
       -- Заголовок
       IF not lb_title and length(av_title) > 2 Then
            REPORT_INS_P(gn_group, gn_period , gn_order , av_title ,
                          '','','','','','','','','','','');
            lb_title := True;
       END IF;
        FOR ln_i in 1..4 LOOP
            IF (ln_ind(ln_i) is not NULL and ln_newind(ln_i) is not NULL)
               or ln_consump(ln_i) > 0  Then
               lr_meters := lt_meters(ln_i);
               ---------------------------------------------------------------
               --- Проверка на вновь установленные счетчики  -----------------
               ---------------------------------------------------------------
                   lb_inst := false;
                   ln_first_ind := ln_ind(ln_i);
                   ln_consump_sum := 0;
                   lv_DDD := '';
               FOR lc_Bill_Del in lcur_Bill_Del(lc_point.mid, ln_i, gd_first, gd_last) LOOP
                   if not lb_inst then
                         lv_DDD := ' Дем.';
                   else
                        lv_DDD := ' Уст. - Дем.';
                        Open lcur_Bill_Ins(lc_point.mid, ln_i, gd_first, gd_last, lc_Bill_Del.mtrsn);
                        Fetch lcur_Bill_Ins into ln_first_ind;
                        Close lcur_Bill_Ins;
                   end if;
                   Open lcur_consumption_ins(lc_point.mid, ln_i, ld_first, gd_last, lc_Bill_Del.mtrsn);
                   Fetch lcur_consumption_ins into ln_consump_ins;
                   Close lcur_consumption_ins;
                   ln_diff := ln_consump_ins/nvl(lr_meters.KC,1);
                      REPORT_INS_P(gn_group, gn_period , gn_order , lc_point.VNAME||lv_DDD, gv_typeSmall(ln_i),
                        lc_Bill_Del.type,lc_Bill_Del.mtrsn,to_char(lc_Bill_Del.Ind),to_char(ln_first_ind)
                        ,to_char(ln_diff),to_char(lc_point.kc),round(ln_consump_ins*ABS(lc_point.NKOEF))
                        ,'','','');
                   Open lcur_Bill_Ins(lc_point.mid, ln_i, ld_first, gd_last, lc_Bill_Del.mtrsn);
                   Fetch lcur_Bill_Ins into ln_first_ind;
                   Close lcur_Bill_Ins;
                   ln_consump_sum := ln_consump_sum + ln_consump_ins;
                   lb_inst := true;
                   lv_DDD := ' Уст.';
               END LOOP;
              ------------------------------------
              --- Проверяем была ли уже запись ---
              ------------------------------------
                   if lb_inst then
                        Open lcur_Bill_Ins(lc_point.mid, ln_i, gd_first, gd_last, lr_meters.mtrsn);
                        Fetch lcur_Bill_Ins into ln_first_ind;
                        Close lcur_Bill_Ins;
                   end if;
              ------------------------------------
              --- Запись по последнему счетчику---
              ------------------------------------
                     -- Проверка на NULL показаний
                     IF ln_first_ind is NULL  THEN
                        lr_meters.mtype:= 'Уст. мощн.';
                        ln_diff := NULL;
                     ELSE
                       -- Нахождение разности показаний
                       IF ln_newind(ln_i) >= ln_first_ind Then
                           ln_diff := ln_newind(ln_i) - ln_first_ind;
                       ELSE
                           IF  lr_meters.DIGITS > 0
                           Then ln_digits := round(lr_meters.DIGITS,-1);
                           Else ln_digits := to_number(rpad('1',length(ln_first_ind)+1,'0'));
                           End if;
                           ln_diff := (ln_newind(ln_i) - ln_first_ind) + ln_digits;
                       END IF;
                     END IF;
                      REPORT_INS_P(gn_group, gn_period , gn_order , lc_point.VNAME||lv_DDD,gv_typeSmall(ln_i),
                        lr_meters.mtype,lr_meters.mtrsn,to_char(ln_newind(ln_i)),to_char(ln_first_ind)
                        ,to_char(ln_diff),to_char(lc_point.kc)
                        ,round((ln_consump(ln_i)-ln_consump_sum)*ABS(lc_point.NKOEF))
                        ,'','','');
              IF not an_include Then
                  ln_consump_all(ln_i) := ln_consump_all(ln_i) + round(ln_consump(ln_i)*ABS(lc_point.NKOEF));
                  gt_consump(ln_i) := gt_consump(ln_i) + round(ln_consump(ln_i)*lc_point.NKOEF);
              END IF;
            END IF;
        END LOOP;
    End IF;
END LOOP;
-- Итого
lb_title := false;
FOR ln_i in 1..4 LOOP
    IF ln_consump_all(ln_i) <> 0 Then
       IF not lb_title Then lv_title := 'Итого '||lower(av_title);lb_title := True;
       ELSE  lv_title := ''; END IF;
            REPORT_INS_P(gn_group, gn_period , gn_order , lv_title ,
                          '','','','',gv_type(ln_i),'','',ln_consump_all(ln_i),'','','');
    END IF;
END LOOP;
EXCEPTION
WHEN OTHERS THEN
   raise_application_error(-20001, 'calc_pg.INS_POINTS: Ошибка вставки точек. ' || chr(10) || SqlErrm(SqlCode));
END;
--------------------------------------------------------------------------------------------
---- Основная процедура расчета, вызывающая остальные процедуры    -------------------------
--------------------------------------------------------------------------------------------
PROCEDURE Calc_main_p
IS
ln_Rtn          INTEGER;
ln_Handle       INTEGER;
lv_sql          VARCHAR2(2000);
le_ErrOpenCursor EXCEPTION ;
ln_period   NUMBER;

Cursor lcur_procedure IS
SELECT P.NPROCEDURE , P.VPROCDURE , P.VNAME , P.NORDER, R.NREPORTGROUP
FROM PROCEDURES P, REPORTGROUPS R
WHERE (P.NPROCEDURE = R.NPROCEDURE)
ORDER BY P.NORDER;
BEGIN
-- Получение периода
Begin
  admin_pg.fiscal_p(gn_Task_Code,1,'Запуск расчета отчета ');
SELECT to_number(substr(VVALUE,7,4)||substr(VVALUE,4,2)) INTO ln_period
 FROM PARAMETER WHERE npid = 3;
EXCEPTION
WHEN OTHERS THEN
   raise_application_error(-20001, 'calc_pg.main_p: Не введена дата расчета значений ручников с месячным профилем. ' || chr(10) || SqlErrm(SqlCode));
End;

SAVEPOINT calc_main_p;
-- Цикл по процедурам
FOR lc_proc in lcur_procedure LOOP
    lv_sql := 'Begin '||lc_proc.VPROCDURE || '('||to_char(lc_proc.NREPORTGROUP)||','||to_char(ln_period)||');  End;';
    ln_Handle := SYS.DBMS_SQL.Open_Cursor;
    SYS.DBMS_SQL.Parse(ln_Handle,lv_sql,SYS.DBMS_SQL.V7);
    ln_Rtn :=SYS.DBMS_SQL.Execute(ln_Handle);
    IF ln_Rtn < 0 THEN
        RAISE le_ErrOpenCursor;
    END IF;
    SYS.DBMS_SQL.Close_Cursor(ln_Handle);
END LOOP;
Commit;
EXCEPTION
WHEN le_ErrOpenCursor THEN
   ROLLBACK TO SAVEPOINT calc_main_p;
     raise_application_error(-20002, 'calc_pg.main_p: Ошибка при открытии курсора. ' || chr(10) || SqlErrm(SqlCode));
WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT calc_main_p;
   raise_application_error(-20001, 'calc_pg.main_p: Ошибка при генерации отчета. ' || chr(10) || SqlErrm(SqlCode));
END;

------------------------------------------------------------------------------
----------- Процедура формирования первой ведомости --------------------------
------------------------------------------------------------------------------
PROCEDURE Calc_report_p (an_group    IN NUMBER,
                         an_period   IN NUMBER)
IS
lv_title VARCHAR2(128);
lb_title BOOLEAN;

CURSOR lcur_main_group (an_parent number) IS
SELECT R.NREPORTGROUP , R.NPARENT , R.VNAME , R.NGROUPTYPE , R.VGROUPKIND
     , R.NPROCEDURE , R.NDEPARTMENT , R.MID , R.NCOEF
FROM REPORTGROUPS R, DEPARTMENTS DP
WHERE NPARENT = an_parent and R.NDEPARTMENT > 0
      AND R.NDEPARTMENT = DP.NDEPARTMENT(+)
ORDER BY DP.NSORT;

CURSOR lcur_group (an_parent number, an_type number) IS
SELECT R.NREPORTGROUP , R.NPARENT , R.VNAME , R.NGROUPTYPE , R.VGROUPKIND
     , R.NPROCEDURE , R.NDEPARTMENT , R.MID , R.NCOEF
FROM REPORTGROUPS R
WHERE NPARENT = an_parent and DECODE(R.VGROUPKIND,'S',1,'G',2,0) = an_type
ORDER BY  DECODE(R.VGROUPKIND,'S',1,'G',2,0), R.NGROUPTYPE;

BEGIN
gn_order := 1;
gn_group := an_group;
gn_period := an_period;
gv_type(1) := 'актив';gv_type(2) := 'реактив';gv_type(3) := 'актив отдача';gv_type(4) := 'реактив отдача';
gv_typeSmall(1) := 'Апр';gv_typeSmall(2) := 'Рпр';gv_typeSmall(3) := 'Аотд';gv_typeSmall(4) := 'Рген';

-- Получение периода
Begin
SELECT to_date(VVALUE,'DD.MM.YYYY') INTO gd_first
 FROM PARAMETER WHERE npid = 2;
SELECT to_date(VVALUE,'DD.MM.YYYY') INTO gd_last
 FROM PARAMETER WHERE npid = 3;
EXCEPTION
WHEN OTHERS THEN
   raise_application_error(-20001, 'calc_pg.Calc_report_p: Не введена дата расчета. ' || chr(10) || SqlErrm(SqlCode));
End;

----- Очистка таблицы ----------
    DELETE FROM REPORTS
    WHERE NREPORTGROUP =  AN_GROUP AND NPERIOD = AN_PERIOD;
FOR lc_main in lcur_main_group(an_group) LOOP
    REPORT_INS_P( AN_GROUP , AN_PERIOD , gn_order , lc_main.VNAME ,
                  '','','','','','','','','','','');
    -- Очистка таблицы суммарного расхода группы
    FOR ln_i in 1..4 LOOP
        gt_consump(ln_i) := 0;
    END LOOP;
    INS_POINTS(lc_main.NREPORTGROUP,':',0, False);
    -- Цикл по группам (в том числе)
     FOR lc_group in lcur_group(lc_main.NREPORTGROUP,1) LOOP
         Select DECODE(lc_group.NGROUPTYPE,1,'В том числе подстанции:',
                                           2,'В том числе потребители:','') into lv_title from dual;
         INS_POINTS(lc_group.NREPORTGROUP, lv_title, 0, True);
     END LOOP;
     -- Плюс подстанции, потребители
     FOR lc_group in lcur_group(lc_main.NREPORTGROUP,2) LOOP
         Select DECODE(lc_group.NGROUPTYPE,1,'Плюс(подстанции):',2,'Плюс(потребители):','') into lv_title from dual;
         INS_POINTS(lc_group.NREPORTGROUP, lv_title, 0, False);
     END LOOP;
     -- Минус подстанции, потребители
     FOR lc_group in lcur_group(lc_main.NREPORTGROUP,2) LOOP
         Select DECODE(lc_group.NGROUPTYPE,1,'Минус(подстанции):',2,'Минус(потребители):','') into lv_title from dual;
         INS_POINTS(lc_group.NREPORTGROUP, lv_title, -1, False);
     END LOOP;
  DELETE from DetTurnOver Where NDEPARTMENT = lc_main.NDEPARTMENT and NPERIOD = gn_period;
  Insert into DetTurnOver( NDEPARTMENT , NPERIOD , NAMOUNTER ,
                          NAMOUNTQ1 , NAMOUNTED, NAMOUNTQ3 )
   Values(lc_main.NDEPARTMENT, gn_period,gt_consump(1),
                          gt_consump(2),gt_consump(3),gt_consump(4));
   -- Итого
    lb_title := false;
    FOR ln_i in 1..4 LOOP
        IF gt_consump(ln_i) <> 0 Then
           IF not lb_title Then lv_title := 'Итого '||lower(lc_main.VNAME)||':';lb_title := True;
           ELSE  lv_title := ''; END IF;
                REPORT_INS_P(gn_group, gn_period , gn_order , lv_title ,
                              '','','','',gv_type(ln_i),'','',gt_consump(ln_i),'','','');
        END IF;
END LOOP;
END LOOP;
EXCEPTION
WHEN OTHERS THEN
   raise_application_error(-20001, 'calc_pg.Calc_report_p: Ошибка формирования. ' || chr(10) || SqlErrm(SqlCode));
END;
------------------------------------------------------------------------------
---- Процедура второго отчета-------------------------------------------------
------------------------------------------------------------------------------
PROCEDURE Report_Debt_p (an_group    IN NUMBER,
                         an_period   IN NUMBER)
IS
lv_title VARCHAR2(128);
lt_consump t_number;
lt_consump_group t_number;
ln_order NUMBER;
ld_first DATE;
ld_last DATE;
lv_kind VARCHAR2(10);
ln_main_group NUMBER;
CURSOR lcur_main_group (an_parent number) IS
SELECT R.NREPORTGROUP , R.NPARENT , R.VNAME , R.NGROUPTYPE , R.VGROUPKIND
     , R.NPROCEDURE , R.NDEPARTMENT , R.MID , R.NCOEF
     , D.NAMOUNTER , D.NAMOUNTQ1 , D.NAMOUNTED, D.NAMOUNTQ3
FROM REPORTGROUPS R, DETTURNOVER D, DEPARTMENTS DP
WHERE NPARENT = an_parent and R.NDEPARTMENT > 0
      AND R.NDEPARTMENT = D.NDEPARTMENT and D.NPERIOD = an_period
      AND R.NDEPARTMENT = DP.NDEPARTMENT(+)
ORDER BY DP.NSORT;

CURSOR lcur_group (an_parent number) IS
SELECT R.NREPORTGROUP , R.NPARENT , R.VNAME , R.NGROUPTYPE ,
       nvl(R.VGROUPKIND,'G') VGROUPKIND
     , R.NPROCEDURE , R.NDEPARTMENT , R.MID , R.NCOEF
FROM REPORTGROUPS R
WHERE NPARENT = an_parent
ORDER BY  DECODE(R.VGROUPKIND,'S',1,'G',2,0), R.NGROUPTYPE;

Cursor lcur_consumption (an_group NUMBER, ad_first DATE, ad_last DATE) IS
SELECT sum(nvl(r.er,0)*nvl(g.NCOEF,1)) er, sum(nvl(r.q1,0)*nvl(g.NCOEF,1)) q1,
       sum(nvl(r.ed,0)*nvl(g.NCOEF,1)) ed, sum(nvl(r.q3,0)*nvl(g.NCOEF,1)) q3
FROM bill r, REPORTGROUPS g
Where r.mid = g.mid and (g.NPARENT = an_group or g.NREPORTGROUP = an_group)
      and r.date_time between ad_first+1 and ad_last;

BEGIN
gn_order := 1;
gn_group := an_group;
gn_period := an_period;

-- Получение периода
Begin
SELECT to_date(VVALUE,'DD.MM.YYYY') INTO ld_first
 FROM PARAMETER WHERE npid = 2;
SELECT to_date(VVALUE,'DD.MM.YYYY') INTO ld_last
 FROM PARAMETER WHERE npid = 3;
EXCEPTION
WHEN OTHERS THEN
   raise_application_error(-20001, 'calc_pg.main_p: Не введена дата расчета. ' || chr(10) || SqlErrm(SqlCode));
End;
----------- Удаление записей из таблицы отчета -----------
    DELETE FROM REPORTS
    WHERE NREPORTGROUP =  AN_GROUP AND NPERIOD = AN_PERIOD;
FOR lc_main in lcur_main_group(an_group) LOOP
    IF IsGroup_f(lc_main.NREPORTGROUP) = 0 Then
       REPORT_INS_P( AN_GROUP , AN_PERIOD , gn_order , lc_main.VNAME
                    , lc_main.NAMOUNTER , lc_main.NAMOUNTQ1 , lc_main.NAMOUNTED, lc_main.NAMOUNTQ3
                    ,'','','','','','','');
    ELSE
      REPORT_INS_P( AN_GROUP , AN_PERIOD , gn_order , lc_main.VNAME ,
                   '','','','','','','','','','','');
      ln_order := gn_order;
      gn_order := gn_order + 1;
    -- Очистка таблицы суммарного расхода группы
     FOR ln_i in 1..4 LOOP
        lt_consump_group(ln_i) := 0;
     END LOOP;
     ln_main_group := 0;
    -- Цикл по группам
     FOR lc_group in lcur_group(lc_main.NREPORTGROUP) LOOP
         Open lcur_consumption (lc_group.NREPORTGROUP, ld_first, ld_last);
         Fetch lcur_consumption into lt_consump(1), lt_consump(2), lt_consump(3), lt_consump(4);
         Close lcur_consumption;
         IF lc_group.VGROUPKIND = 'G' THEN
             FOR ln_i in 1..4 LOOP
                lt_consump_group(ln_i) := lt_consump_group(ln_i) + lt_consump(ln_i);
             END LOOP;
             lv_kind := '';
             ln_main_group := 1;
          ELSE
             lv_kind := 'В.Т.Ч.';
         END IF;
          REPORT_INS_P( AN_GROUP , AN_PERIOD , gn_order , lv_kind||lc_group.VNAME ,
                       lt_consump(1),lt_consump(2),lt_consump(3),lt_consump(4),
                       '','','','','','','');
     END LOOP;
     ---------- Сумма по группе не равна общей сумме -----------------
       IF lc_main.NAMOUNTER <> lt_consump_group(1) and ln_main_group = 1 Then
          REPORT_INS_P( AN_GROUP , AN_PERIOD , ln_order , 'Электромеханизмы' ,
                       lc_main.NAMOUNTER - lt_consump_group(1),
                       lc_main.NAMOUNTQ1 - lt_consump_group(2) ,
                       lc_main.NAMOUNTED - lt_consump_group(3),
                       lc_main.NAMOUNTQ3 - lt_consump_group(4),
                       '','','','','','','');
          gn_order := gn_order - 1;
       END IF;
       REPORT_INS_P( AN_GROUP , AN_PERIOD , gn_order , 'ИТОГО'
                    , lc_main.NAMOUNTER , lc_main.NAMOUNTQ1 , lc_main.NAMOUNTED, lc_main.NAMOUNTQ3
                    ,'','','','','','','');
END IF;
END LOOP;

END;


END; -- Package Body CALC_PG
/


-- End of DDL Script for Package Body RYDA.CALC_PG

-- Start of DDL Script for Package Body RYDA.CALCDUBLICATE_PG
-- Generated 14.11.2008 08:47:54 from RYDA@sesreg

CREATE OR REPLACE 
PACKAGE BODY calcdublicate_pg
IS
    -- пакет для работы с расчетными точками дублирующих счетчиков
    -- дата создания 08/08/2005 Коваленко А.С.

    --------------------------------------------------------------------------------
-- Копирует данные с одной точки на другую
-- Перед копированием все данные за заданый промежуток с точки приемника удаляются
-- an_dmid - ид точки на которую копируются данные
-- an_smid - ид точки с которой копируются данные
-- ad_sdate - дата начала копирования данных (изключительно)
-- ad_edate - дата окончания копирования данных (включительно)
-- av_tablename - таблица копирования данных
    PROCEDURE copy_point_data_p (an_dmid NUMBER, an_smid NUMBER, ad_sdate DATE, ad_edate DATE, av_tablename VARCHAR2)
    IS
        CURSOR lcur_col (cv_tablename VARCHAR2)
        IS
            SELECT   UPPER (column_name) cn
                FROM SYS.all_tab_columns a
               WHERE LOWER (table_name) = LOWER (cv_tablename) AND OWNER='RYDA' AND column_name <> 'MID'
            ORDER BY column_name;

        lv_table_col   VARCHAR2 (1000) := '';
        lv_sql         VARCHAR2 (2000);
    BEGIN
        -- удаляем старые данные
        lv_sql := 'delete from ' || av_tablename || ' where mid = :1 and date_time > :2 and date_time <= :3';

        EXECUTE IMMEDIATE lv_sql
                    USING an_dmid, ad_sdate, ad_edate;

        -- формируем строку с названием
        FOR lc_col IN lcur_col (av_tablename)
        LOOP
            lv_table_col := lv_table_col || ', ' || lc_col.cn;
        END LOOP;

        lv_sql :=
               'insert into '
            || av_tablename
            || ' (MID'
            || lv_table_col
            || ') (select '
            || an_dmid
            || lv_table_col
            || ' from '
            || av_tablename
            || ' where mid = :1 and date_time > :2 and date_time <= :3)';

        EXECUTE IMMEDIATE lv_sql
                    USING an_smid, ad_sdate, ad_edate;

    EXCEPTION
        WHEN OTHERS
        THEN
            raise_application_error (-20001, 'calcdublicate_pg.copy_point_data_p: Ошибка при копировании данных. ' || CHR (10) || SQLERRM (SQLCODE));
    END;

    --------------------------------------------------------------------------------
-- Копирует данные с одной точки на другую
-- Перед копированием все данные за заданый промежуток с точки приемника удаляются
-- an_mid - ид точки с которой копируются данные, приемник находится по родителю
-- ad_sdate - дата начала копирования данных (изключительно)
-- ad_edate - дата окончания копирования данных (включительно)
    PROCEDURE copy_point_data_p (an_mid NUMBER, ad_sdate DATE, ad_edate DATE)
    IS
        ln_dmid   NUMBER;
    BEGIN
        -- находим ид расчетной точки
        BEGIN
            SELECT mid
              INTO ln_dmid
              FROM points
             WHERE mid = (SELECT PARENT
                            FROM points
                           WHERE mid = an_mid) AND ind = 4;
        EXCEPTION
            WHEN NO_DATA_FOUND
            THEN
                raise_application_error (-20001,
                                            'calcdublicate_pg.copy_point_data_p: Для точки с ид '
                                         || an_mid
                                         || ' не найдена расчетная точка. '
                                         || CHR (10)
                                         || SQLERRM (SQLCODE));
        END;

        -- начинаем копировать все таблички с данными
        copy_point_data_p (ln_dmid, an_mid, ad_sdate, ad_edate, 'monthsorg');
        copy_point_data_p (ln_dmid, an_mid, ad_sdate, ad_edate, 'billorg');
        copy_point_data_p (ln_dmid, an_mid, ad_sdate, ad_edate, 'billold');
        copy_point_data_p (ln_dmid, an_mid, ad_sdate, ad_edate, 'halfhourold');
        copy_point_data_p (ln_dmid, an_mid, ad_sdate, ad_edate, 'profile');
    END;

--------------------------------------------------------------------------------
-- Добавляет переключение на дублирующий счетчик
-- Перед копированием все данные за заданый промежуток с точки приемника удаляются
-- по даты an_smid, ad_sdate включительно
-- an_mid - ид точки дублирующего счетчика
-- ad_sdate - дата начала копирования данных (включительно)
-- ad_edate - дата окончания копирования данных (включительно)
    PROCEDURE add_edit_sw_p (an_mid NUMBER, ad_sdate DATE, ad_edate DATE, av_memo VARCHAR2)
    IS
        ld_edate      DATE   DEFAULT NULL;
        ln_calc_mid   NUMBER;
    BEGIN
        -- Проверяем нет ли предыдущего незакрытого периода
        BEGIN
            SELECT dend
              INTO ld_edate
              FROM calcbyduplication
             WHERE mid = an_mid AND dstart = (SELECT MAX (dstart)
                                                FROM calcbyduplication
                                               WHERE mid = an_mid AND dstart < ad_sdate);

            BEGIN
                SELECT mid
                  INTO ln_calc_mid
                  FROM points
                 WHERE mid = (SELECT PARENT
                                FROM points
                               WHERE mid = an_mid) AND ind = 4;
            EXCEPTION
                WHEN NO_DATA_FOUND
                THEN
                    raise_application_error (-20001,
                                                'calcdublicate_pg.add_edit_sw_p: Для точки с ид '
                                             || an_mid
                                             || ' не найдена расчетная точка. '
                                             || CHR (10)
                                             || SQLERRM (SQLCODE));
            END;

            IF ld_edate IS NULL
            THEN
                raise_application_error (-20001, 'Предыдущий интервал не закрыт конечной датой. ' || SQLERRM (SQLCODE));
            END IF;
        EXCEPTION
            WHEN NO_DATA_FOUND
            THEN
                NULL;
        END;

        DELETE FROM calcbyduplication
              WHERE mid = an_mid AND dstart = ad_sdate;

        INSERT INTO calcbyduplication
                    (mid, dstart, dend, vmemo, user_id
                    )
             VALUES (an_mid, ad_sdate, ad_edate, av_memo, common_pg.userid_f
                    );

        IF ad_edate IS NULL
        THEN
            ld_edate := TRUNC (SYSDATE);
        ELSE
            ld_edate := ad_edate;
        END IF;

        copy_point_data_p (an_mid, ad_sdate, ld_edate);
        -- а теперь перелапатим все по текущую дату
        copy_point_data_backgr_p (ln_calc_mid, ad_edate, TRUNC (SYSDATE));
    EXCEPTION
        WHEN OTHERS
        THEN
            raise_application_error (-20001, 'CALCDUBLICATE_PG.add_edit_sw_p: ' || SQLERRM (SQLCODE));
    END;

    --------------------------------------------------------------------------------
-- Удаляет переключение на дублирующий счетчик
-- an_mid - ид точки дублирующего счетчика
-- ad_sdate - дата начала интервала переключения
    PROCEDURE del_sw_p (an_mid NUMBER, ad_sdate DATE)
    IS
        an_main_mid   NUMBER;
        ld_edate      DATE   DEFAULT NULL;
    BEGIN
        -- ищем ид основного счетчика
        SELECT nmainpoint
          INTO an_main_mid
          FROM feeders
         WHERE mid = an_mid;

        -- ищем конечную дату
        SELECT dend
          INTO ld_edate
          FROM calcbyduplication
         WHERE mid = an_mid AND dstart = ad_sdate;

        IF ld_edate IS NULL
        THEN
            ld_edate := TRUNC (SYSDATE);
        END IF;

        copy_point_data_p (an_main_mid, ad_sdate, ld_edate);

        DELETE FROM calcbyduplication
              WHERE mid = an_mid AND dstart = ad_sdate;
    EXCEPTION
        WHEN OTHERS
        THEN
            raise_application_error (-20001, 'CALCDUBLICATE_PG.del_sw_p: ' || SQLERRM (SQLCODE));
    END;

--------------------------------------------------------------------------------
-- Копирует данные на расчетную точку используется в фоновом процессе
-- Перед копированием все данные за заданый промежуток с точки удаляются
-- по даты an_smid, ad_sdate включительно
-- an_mid - ид расчетной точки
-- ad_sdate - дата начала копирования данных (включительно)
-- ad_edate - дата окончания копирования данных (включительно)
-- выбор с какой точки брать данные отределяется посредством сканирования таблицы calcbyduplication
    PROCEDURE copy_point_data_backgr_p (an_mid NUMBER, ad_sdate DATE, ad_edate DATE)
    IS
        CURSOR lcur_period (an_dmid NUMBER)
        IS
            SELECT   ad_sdate ddate, 1 dubl
                FROM DUAL
               WHERE EXISTS (
                         SELECT *
                           FROM calcbyduplication cd1, calcbyduplication cd2
                          WHERE cd1.dstart = cd2.dstart
                            AND cd1.mid = cd2.mid
                            AND cd1.mid = an_dmid
                            AND cd1.dstart = (SELECT MAX (dstart)
                                                FROM calcbyduplication
                                               WHERE mid = an_dmid AND dstart <= ad_sdate)
                            AND (cd2.dend = (SELECT MIN (dend)
                                               FROM calcbyduplication
                                              WHERE mid = an_dmid AND dend > ad_sdate) OR cd2.dend IS NULL))
            UNION ALL
            SELECT   ad_sdate ddate, 0 dubl
                FROM DUAL
               WHERE NOT EXISTS (
                         SELECT *
                           FROM calcbyduplication cd1, calcbyduplication cd2
                          WHERE cd1.dstart = cd2.dstart
                            AND cd1.mid = cd2.mid
                            AND cd1.mid = an_dmid
                            AND cd1.dstart = (SELECT MAX (dstart)
                                                FROM calcbyduplication
                                               WHERE mid = an_dmid AND dstart <= ad_sdate)
                            AND (cd2.dend = (SELECT MIN (dend)
                                               FROM calcbyduplication
                                              WHERE mid = an_dmid AND dend > ad_sdate) OR cd2.dend IS NULL))
            UNION ALL
            SELECT   dstart ddate, 1 dubl
                FROM calcbyduplication
               WHERE mid = an_dmid AND dstart > ad_sdate AND dstart < ad_edate
            UNION ALL
            SELECT   dend ddate, 0 dubl
                FROM calcbyduplication
               WHERE mid = an_dmid AND dend > ad_sdate AND dend < ad_edate
            UNION ALL
            SELECT   ad_edate ddate, 0 dubl
                FROM DUAL
            ORDER BY 1;

        ld_st             DATE   DEFAULT NULL;
        ld_end            DATE   DEFAULT NULL;
        ln_st_met_type    NUMBER;
        ln_end_met_type   NUMBER;
        ln_dub_mid        NUMBER;
        ln_main_mid       NUMBER;
    BEGIN
        -- исчем иду основного счетчика для иды расчетной точки
        SELECT MAX (f.mid)
          INTO ln_main_mid
          FROM feeders f, points p
         WHERE PARENT = an_mid AND f.mid = p.mid AND f.nmainpoint IS NULL;

        -- исчем иду дублирующего счетчика для иды расчетной точки
        SELECT MAX (f.mid)
          INTO ln_dub_mid
          FROM feeders f, points p
         WHERE PARENT = an_mid AND f.nmainpoint = ln_main_mid;

        FOR lc_per IN lcur_period (ln_dub_mid)
        LOOP
            IF ld_st IS NOT NULL AND ld_end IS NULL
            THEN
                ld_end := lc_per.ddate;
                ln_end_met_type := lc_per.dubl;

                IF ln_st_met_type = 0
                THEN   -- т.е. основной счетчик
                    copy_point_data_p (ln_main_mid, ld_st, ld_end);
                ELSE
                    copy_point_data_p (ln_dub_mid, ld_st, ld_end);
                END IF;

                ld_st := ld_end;
                ln_st_met_type := ln_end_met_type;
                ld_end := NULL;
            END IF;

            IF ld_st IS NULL
            THEN
                ld_st := lc_per.ddate;
                ln_st_met_type := lc_per.dubl;
            END IF;
        END LOOP;
    EXCEPTION
        WHEN OTHERS
        THEN
            raise_application_error (-20001, 'CALCDUBLICATE_PG.copy_point_data_backgr_p: ' || SQLERRM (SQLCODE));
    END;

--------------------------------------------------------------------------------
-- Копирует данные на расчетные точки используется в фоновом процессе
-- Перед копированием все данные за заданый промежуток с точек удаляются
-- по даты an_smid, ad_sdate включительно
-- an_mid - ид расчетной точки
-- ad_sdate - дата начала копирования данных (включительно)
-- ad_edate - дата окончания копирования данных (включительно)
    PROCEDURE copy_points_data_backgr_p (an_maket NUMBER, ad_sdate DATE)
    IS
        CURSOR lcur_points
        IS
            SELECT mid
              FROM points
             WHERE ind = 4;

        ld_sdate   DATE DEFAULT TRUNC (ad_sdate);
        ld_fdate   DATE DEFAULT TRUNC (SYSDATE);
    BEGIN
        FOR lc_p IN lcur_points
        LOOP
            copy_point_data_backgr_p (lc_p.mid, ld_sdate, ld_fdate);
        END LOOP;
    EXCEPTION
        WHEN OTHERS
        THEN
            raise_application_error (-20001, 'CALCDUBLICATE_PG.copy_points_data_backgr_p: ' || SQLERRM (SQLCODE));
    END;
--------------------------------------------------------------------------------

-- Enter further code below as specified in the Package spec.
END;
/


-- End of DDL Script for Package Body RYDA.CALCDUBLICATE_PG

-- Start of DDL Script for Package Body RYDA.CALCFORMULA_PG
-- Generated 14.11.2008 08:47:54 from RYDA@sesreg

CREATE OR REPLACE 
PACKAGE BODY calcformula_pg IS
------------------------------------------------------------------------------------------------------------------------
  -- пакет расчета фоормул
  -- дата создания 22/10/2008 Сечин А.А.
------------------------------------------------------------------------------------------------------------------------
 cv_d      CONSTANT VARCHAR2 (1) := '.';
 cv_cpt    CONSTANT NUMBER       := 6;   --Тип расчетной точки (по формулке)
 cn_meas   CONSTANT NUMBER       DEFAULT 6;   --кол измерений (er,ed,q1,q2,q3,q4)
 cn_step   CONSTANT NUMBER       DEFAULT 1 / 48;   --Шаг расчета

------------------------------------------------------------------------------------------------------------------------
--На вход Метка времени зима ()
 PROCEDURE ins_halfhouroldw (an_mid NUMBER, ad_date DATE, an_er NUMBER, an_ed NUMBER, an_q1 NUMBER, an_q3 NUMBER, an_q2 NUMBER, an_q4 NUMBER, an_erm NUMBER,
 an_edm NUMBER, an_q1m NUMBER, an_q3m NUMBER, an_q2m NUMBER, an_q4m NUMBER, an_status NUMBER, an_metertype NUMBER, av_qm VARCHAR2
 );

 PROCEDURE ins_halfhouroldw (an_mid NUMBER, ad_date DATE, an_er NUMBER, an_ed NUMBER, an_q1 NUMBER, an_q3 NUMBER, an_q2 NUMBER, an_q4 NUMBER, an_status NUMBER,
 an_metertype NUMBER, av_qm VARCHAR2
 );

------------------------------------------------------------------------------------------------------------------------
 --Вычисление значение по тексту
 PROCEDURE getval (av_id VARCHAR2, ad_from DATE, ad_till DATE, an_pnum NUMBER, at_ret IN OUT common_pg.tt_double, at_qm IN OUT common_pg.tt_varchar2,
 an_2hour NUMBER) IS
  lv_datatable   CONSTANT VARCHAR2 (32)       := 'HALFHOUR';
  lv_type                 VARCHAR2 (32);
  ln_id                   NUMBER;
  lv_prop                 VARCHAR2 (32);
  lv_objtable             VARCHAR2 (32);   --Таблица ограничения по объектам
  lv_inverted             VARCHAR2 (32);   --Признак инверсии
  lv_partly_er            VARCHAR2 (32);   --Частичное вхождение A+
  lv_partly_ed            VARCHAR2 (32);   --Частичное вхождение A-
  lv_objsubsel            VARCHAR2 (512);   --Ограничение по объектам
  lv_datsubsel            VARCHAR2 (512);   --Ограничение по дате
  lv_what                 VARCHAR2 (512);   --Что тянем
  lv_sql                  VARCHAR2 (4000);   --Конечный SQL
  lt_ret                  common_pg.tt_double;
  lt_ret1                 common_pg.tt_double;
 BEGIN
  at_qm (an_pnum) := qm_pg.okqm;
  --Разобрали входную строку
  lv_type := TRIM (UPPER (util_pg.get_param (av_id, 1, cv_d)));
  ln_id := TRIM (util_pg.get_param (av_id, 2, cv_d));
  lv_prop := TRIM (UPPER (util_pg.get_param (av_id, 3, cv_d)));
  lv_datsubsel :=
   ' and p.date_time>to_date(''' || TO_CHAR (ad_from, 'dd.mm.yyyy hh24:mi:ss') || ''',''dd.mm.yyyy hh24:mi:ss'') ' || ' and p.date_time<=to_date('''
   || TO_CHAR (ad_till, 'dd.mm.yyyy hh24:mi:ss') || ''',''dd.mm.yyyy hh24:mi:ss'') ';

  IF an_2hour = 1 THEN
   lv_datsubsel := lv_datsubsel || ' and p.nsource in (19, 29, 39, 49, 59)';
  ELSIF util_pg.is_dayswitch (ad_from) = -1 OR util_pg.is_dayswitch (ad_till) = -1 THEN
   lv_datsubsel := lv_datsubsel || ' and p.nsource not in (19, 29, 39, 49, 59)';
  END IF;

  IF lv_type = 'GID' THEN
   lv_objtable := 'GROUPS';
   lv_inverted := 'G.INVERTED';
   lv_partly_er := '*decode(g.NPARTLY,2,0,1)';
   lv_partly_ed := '*decode(g.NPARTLY,1,0,1)';
   lv_objsubsel :=
    'and G.gid in (select gid from groups connect by ((prior gid=parent) or (prior NROOT2=NROOT2 and prior nroot1>0 and nroot1 is null)) start with gid=' || ln_id
    || ')';
  ELSIF lv_type = 'MID' THEN
   lv_objtable := 'POINTS';
   lv_inverted := '''N''';
   lv_partly_er := '';
   lv_partly_ed := '';

   IF util_pg.isfolder (ln_id) = 1 THEN
    lv_objsubsel := 'and G.mid in (select mid from points connect by prior mid=parent and prior ind not in (3,4) start with mid=' || ln_id || ')';
   ELSE
    lv_objsubsel := 'and G.mid = ' || ln_id || ' ';
   END IF;
  ELSE
   RETURN;
  END IF;

  --Выясняем что нам нужно
  IF lv_prop IS NULL OR lv_prop = 'A' THEN
   lv_what :=
    'sum((DECODE(' || lv_inverted || ',''y'',nvl(P.ed' || lv_partly_ed || ',0),nvl(P.er' || lv_partly_er || ',0)))),' || 'sum((DECODE(' || lv_inverted
    || ',''y'',nvl(P.er' || lv_partly_er || ',0),nvl(P.ed' || lv_partly_ed || ',0)))),' || 'sum((DECODE(' || lv_inverted || ',''y'',nvl(P.q3,0),nvl(P.q1,0)))),'
    || 'sum((DECODE(' || lv_inverted || ',''y'',nvl(P.q1,0),nvl(P.q3,0)))),' || 'sum((DECODE(' || lv_inverted || ',''y'',nvl(P.q4,0),nvl(P.q2,0)))),'
    || 'sum((DECODE(' || lv_inverted || ',''y'',nvl(P.q2,0),nvl(P.q4,0)))) ';
   lv_sql := 'select ' || lv_what || ' from ' || lv_datatable || ' P,' || lv_objtable || ' G where p.mid=g.mid ' || ' ' || lv_datsubsel || ' ' || lv_objsubsel;

   EXECUTE IMMEDIATE lv_sql
                INTO at_ret ((an_pnum - 1) * cn_meas + 1), at_ret ((an_pnum - 1) * cn_meas + 2), at_ret ((an_pnum - 1) * cn_meas + 3),
                     at_ret ((an_pnum - 1) * cn_meas + 4), at_ret ((an_pnum - 1) * cn_meas + 5), at_ret ((an_pnum - 1) * cn_meas + 6);
  ELSIF lv_prop IN ('ER', 'ED', 'Q1', 'Q3', 'Q2', 'Q3', 'Q12', 'Q34', 'E', 'Q', 'EE', 'QQ') THEN
   IF lv_prop = 'ER' THEN
    lv_what := 'sum((DECODE(' || lv_inverted || ',''y'',nvl(P.ed' || lv_partly_ed || ',0),nvl(P.er' || lv_partly_er || ',0))))';
   ELSIF lv_prop = 'ED' THEN
    lv_what := 'sum(DECODE(' || lv_inverted || ',''y'',nvl(P.er' || lv_partly_er || ',0),nvl(P.ed' || lv_partly_ed || ',0)))';
   ELSIF lv_prop = 'Q1' THEN
    lv_what := 'sum(DECODE(' || lv_inverted || ',''y'',nvl(P.q3,0),nvl(P.q1,0)))';
   ELSIF lv_prop = 'Q3' THEN
    lv_what := 'sum(DECODE(' || lv_inverted || ',''y'',nvl(P.q1,0),nvl(P.q3,0)))';
   ELSIF lv_prop = 'Q2' THEN
    lv_what := 'sum(DECODE(' || lv_inverted || ',''y'',nvl(P.q4,0),nvl(P.q2,0)))';
   ELSIF lv_prop = 'Q4' THEN
    lv_what := 'sum(DECODE(' || lv_inverted || ',''y'',nvl(P.q2,0),nvl(P.q4,0)))';
   ELSIF lv_prop = 'Q12' THEN   --Свернутые Q1+Q2
    lv_what := 'sum(DECODE(' || lv_inverted || ',''y'',nvl(P.q3,0),nvl(P.q1,0)))+sum(DECODE(' || lv_inverted || ',''y'',nvl(P.q4,0),nvl(P.q2,0)))';
   ELSIF lv_prop = 'Q34' THEN   --Свернутые Q3+Q4
    lv_what := 'sum(DECODE(' || lv_inverted || ',''y'',nvl(P.q1,0),nvl(P.q3,0)))+sum(DECODE(' || lv_inverted || ',''y'',nvl(P.q2,0),nvl(P.q4,0)))';
   ELSIF lv_prop = 'E' THEN   --Переток ER-ED
    lv_what := 'sum(-util_pg.sld(P.mid,nvl(P.er' || lv_partly_er || ',0),nvl(P.ed' || lv_partly_ed || ',0))*DECODE(' || lv_inverted || ',''y'',1,-1))';
   ELSIF lv_prop = 'Q' THEN   --Переток (Q1-Q3)+(Q2-Q4)
    lv_what :=
     'sum(-util_pg.sld(P.mid,nvl(P.q1,0),nvl(P.q3,0))*DECODE(' || lv_inverted || ',''y'',1,-1))+sum(-util_pg.sld(P.mid,nvl(P.q2,0),nvl(P.q4,0))*DECODE('
     || lv_inverted || ',''y'',1,-1))';
   ELSIF lv_prop = 'EE' THEN   --Переток ER+ED
    lv_what := 'sum(-(nvl(P.er' || lv_partly_er || ',0)+nvl(P.ed' || lv_partly_ed || ',0))*DECODE(' || lv_inverted || ',''y'',1,-1))';
   ELSIF lv_prop = 'QQ' THEN   --Переток (Q1+Q3)+(Q2+Q4)
    lv_what := 'sum(-(nvl(P.q1,0)+nvl(P.q3,0)+nvl(P.q2,0)+nvl(P.q4,0))*DECODE(' || lv_inverted || ',''y'',1,-1))';
   END IF;

   lv_sql := 'select ' || lv_what || ' from ' || lv_datatable || ' P,' || lv_objtable || ' G where p.mid=g.mid ' || ' ' || lv_datsubsel || ' ' || lv_objsubsel;

   EXECUTE IMMEDIATE lv_sql
                INTO at_ret ((an_pnum - 1) * cn_meas + 1);

   FOR i IN 2 .. cn_meas LOOP
    at_ret ((an_pnum - 1) * cn_meas + i) := at_ret ((an_pnum - 1) * cn_meas + 1);
   END LOOP;
  ELSIF lv_prop = 'BALANCEP' OR (lv_type = 'GID' AND lv_prop IN ('ADBALANCE', 'ADBALANCEP', 'BALANCEDIF', 'BALANCEDIFP')) THEN
   IF lv_prop = 'BALANCEP' THEN   --Небаланс в%
    getval (lv_type || cv_d || ln_id || cv_d || 'ER', ad_from, ad_till, an_pnum, lt_ret, at_qm, an_2hour);
    getval (lv_type || cv_d || ln_id || cv_d || 'ED', ad_from, ad_till, an_pnum, lt_ret1, at_qm, an_2hour);

    IF GREATEST (lt_ret (an_pnum), lt_ret1 (an_pnum)) <> 0 THEN
     at_ret ((an_pnum - 1) * cn_meas + 1) :=
      100 * (lt_ret ((an_pnum - 1) * cn_meas + 1) - lt_ret1 ((an_pnum - 1) * cn_meas + 1))
      / GREATEST (lt_ret ((an_pnum - 1) * cn_meas + 1), lt_ret1 ((an_pnum - 1) * cn_meas + 1));
    ELSE
     at_ret ((an_pnum - 1) * cn_meas + 1) := GREATEST (lt_ret ((an_pnum - 1) * cn_meas + 1), lt_ret1 ((an_pnum - 1) * cn_meas + 1));
    END IF;
   ELSIF lv_prop = 'ADBALANCE' THEN   --Допустимый небаланс
    at_ret ((an_pnum - 1) * cn_meas + 1) := util_pg.get_ad_balance (ln_id, ad_from, ad_till, NULL);
   ELSIF lv_prop = 'ADBALANCEP' THEN   --Допустимый небаланс в%
    at_ret ((an_pnum - 1) * cn_meas + 1) := util_pg.get_ad_balance (ln_id, ad_from, ad_till, 1);
   ELSIF lv_prop = 'BALANCEDIF' THEN   --Разность факт небаланса и допустим небаланса
    getval (lv_type || cv_d || ln_id || cv_d || 'E', ad_from, ad_till, an_pnum, lt_ret, at_qm, an_2hour);
    getval (lv_type || cv_d || ln_id || cv_d || 'ADBALANCE', ad_from, ad_till, an_pnum, lt_ret1, at_qm, an_2hour);
    at_ret ((an_pnum - 1) * cn_meas + 1) :=
                        SIGN (lt_ret ((an_pnum - 1) * cn_meas + 1))
                        * GREATEST (ABS (lt_ret ((an_pnum - 1) * cn_meas + 1)) - lt_ret1 ((an_pnum - 1) * cn_meas + 1), 0);
   ELSIF lv_prop = 'BALANCEDIFP' THEN   --Разность факт небаланса и допустим небаланса в %
    getval (lv_type || cv_d || ln_id || cv_d || 'BALANCEP', ad_from, ad_till, an_pnum, lt_ret, at_qm, an_2hour);
    getval (lv_type || cv_d || ln_id || cv_d || 'ADBALANCEP', ad_from, ad_till, an_pnum, lt_ret1, at_qm, an_2hour);
    at_ret ((an_pnum - 1) * cn_meas + 1) :=
                        SIGN (lt_ret ((an_pnum - 1) * cn_meas + 1))
                        * GREATEST (ABS (lt_ret ((an_pnum - 1) * cn_meas + 1)) - lt_ret1 ((an_pnum - 1) * cn_meas + 1), 0);
   END IF;

   FOR i IN 2 .. cn_meas LOOP
    at_ret ((an_pnum - 1) * cn_meas + i) := at_ret ((an_pnum - 1) * cn_meas + 1);
   END LOOP;
  ELSIF lv_prop IN
                  ('SN', 'DPXX', 'DPKZ', 'DPBH', 'DPCH', 'DPHH', 'UBH_CH', 'UCH_HH', 'UBH_HH', 'IXX', 'UKZ', 'TN', 'TP', 'SBH', 'SCH', 'SHH', 'L', 'RO', 'XO', 'UN') THEN
   IF lv_prop = 'SN' THEN
    SELECT MAX (nsn)
      INTO at_ret ((an_pnum - 1) * cn_meas + 1)
      FROM connectionparam
     WHERE mid = ln_id;
   ELSIF lv_prop = 'DPXX' THEN
    SELECT MAX (ndeltapidling)
      INTO at_ret ((an_pnum - 1) * cn_meas + 1)
      FROM connectionparam
     WHERE mid = ln_id;
   ELSIF lv_prop = 'DPKZ' THEN
    SELECT MAX (ndeltapsc)
      INTO at_ret ((an_pnum - 1) * cn_meas + 1)
      FROM connectionparam
     WHERE mid = ln_id AND nwinding = 0;
   ELSIF lv_prop = 'DPBH' THEN
    SELECT MAX (ndeltapsc)
      INTO at_ret ((an_pnum - 1) * cn_meas + 1)
      FROM connectionparam
     WHERE mid = ln_id AND nwinding = 1;
   ELSIF lv_prop = 'DPCH' THEN
    SELECT MAX (ndeltapsc)
      INTO at_ret ((an_pnum - 1) * cn_meas + 1)
      FROM connectionparam
     WHERE mid = ln_id AND nwinding = 2;
   ELSIF lv_prop = 'DPHH' THEN
    SELECT MAX (ndeltapsc)
      INTO at_ret ((an_pnum - 1) * cn_meas + 1)
      FROM connectionparam
     WHERE mid = ln_id AND nwinding = 3;
   ELSIF lv_prop = 'UKZ' THEN
    SELECT MAX (nusc)
      INTO at_ret ((an_pnum - 1) * cn_meas + 1)
      FROM connectionparam
     WHERE mid = ln_id AND nwinding = 0;
   ELSIF lv_prop = 'UBH_CH' THEN
    SELECT MAX (nusc)
      INTO at_ret ((an_pnum - 1) * cn_meas + 1)
      FROM connectionparam
     WHERE mid = ln_id AND nwinding = 1;
   ELSIF lv_prop = 'UCH_HH' THEN
    SELECT MAX (nusc)
      INTO at_ret ((an_pnum - 1) * cn_meas + 1)
      FROM connectionparam
     WHERE mid = ln_id AND nwinding = 2;
   ELSIF lv_prop = 'UBH_HH' THEN
    SELECT MAX (nusc)
      INTO at_ret ((an_pnum - 1) * cn_meas + 1)
      FROM connectionparam
     WHERE mid = ln_id AND nwinding = 3;
   ELSIF lv_prop = 'IXX' THEN
    SELECT MAX (niidling)
      INTO at_ret ((an_pnum - 1) * cn_meas + 1)
      FROM connectionparam
     WHERE mid = ln_id;
   ELSIF lv_prop = 'TN' THEN
    SELECT MAX (nworkinghours)
      INTO at_ret ((an_pnum - 1) * cn_meas + 1)
      FROM connectionparam
     WHERE mid = ln_id;
   ELSIF lv_prop = 'TP' THEN
    SELECT MAX (nfullhours)
      INTO at_ret ((an_pnum - 1) * cn_meas + 1)
      FROM connectionparam
     WHERE mid = ln_id;
   ELSIF lv_prop = 'SBH' THEN
    SELECT MAX (nsh)
      INTO at_ret ((an_pnum - 1) * cn_meas + 1)
      FROM connectionparam
     WHERE mid = ln_id AND nwinding = 1;
   ELSIF lv_prop = 'SCH' THEN
    SELECT MAX (nsh)
      INTO at_ret ((an_pnum - 1) * cn_meas + 1)
      FROM connectionparam
     WHERE mid = ln_id AND nwinding = 2;
   ELSIF lv_prop = 'SHH' THEN
    SELECT MAX (nsh)
      INTO at_ret ((an_pnum - 1) * cn_meas + 1)
      FROM connectionparam
     WHERE mid = ln_id AND nwinding = 3;
   ELSIF lv_prop = 'L' THEN
    SELECT MAX (nl)
      INTO at_ret ((an_pnum - 1) * cn_meas + 1)
      FROM connectionparam
     WHERE mid = ln_id;
   ELSIF lv_prop = 'R0' THEN
    SELECT MAX (nro)
      INTO at_ret ((an_pnum - 1) * cn_meas + 1)
      FROM connectionparam
     WHERE mid = ln_id;
   ELSIF lv_prop = 'X0' THEN
    SELECT MAX (nxo)
      INTO at_ret ((an_pnum - 1) * cn_meas + 1)
      FROM connectionparam
     WHERE mid = ln_id;
   ELSIF lv_prop = 'UN' THEN
    SELECT MAX (nun)
      INTO at_ret ((an_pnum - 1) * cn_meas + 1)
      FROM connectionparam
     WHERE mid = ln_id;
   END IF;

   FOR i IN 2 .. cn_meas LOOP
    at_ret ((an_pnum - 1) * cn_meas + i) := at_ret ((an_pnum - 1) * cn_meas + 1);
   END LOOP;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20001, 'calcformula_pg.getval: ИД=''' || av_id || ''' ' || CHR (10) || SQLERRM);
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE calcw (ad_from DATE, ad_till DATE) IS
  ln_ret          NUMBER;
  lr_info         tcalcinfo;
  lt_info         ttcalcinfo;
  lr_param        tparaminfo;
  lt_param        ttparaminfo;
  lt_paramval     common_pg.tt_double;
  lt_qm           common_pg.tt_varchar2;
  ln_cnt          NUMBER                DEFAULT 0;
  ln_pcnt         NUMBER;
  ln_maxmeas      NUMBER;
  val             DOUBLE PRECISION;
  ld_from         DATE                  DEFAULT util_pg.trunchh24_2 (ad_from);
  ld_till         DATE                  DEFAULT util_pg.trunchh24_2 (ad_till);
  ld_date         DATE;
  ld_tmp          DATE;
  ln_2hour        NUMBER;
  ld_calcperiod   DATE                  DEFAULT admin_pg.get_calcperiod;
 BEGIN
  SAVEPOINT calcw_sp;

  --Читаем и parse
  FOR lc IN (SELECT   f.nid, f.nmeas, f.vformula, f.mid, DECODE (f.nmeas, 0, cn_meas, 1) realcnt
                 FROM pointformula f, feeders fd
                WHERE f.mid = fd.mid(+) AND fd.ncalcpointtype = cv_cpt   --AND f.nid = 297562
             ORDER BY f.norder, f.nid) LOOP
   DELETE FROM halfhourold
         WHERE mid = lc.mid AND date_time > ld_from AND date_time <= ld_till + 1 / 24 AND util_pg.to_unlocaltime (date_time, nsource) > ld_from
               AND util_pg.to_unlocaltime (date_time, nsource) <= ld_till;

   ln_cnt := ln_cnt + 1;
   lr_info.ID := lc.nid;
   lr_info.mid := lc.mid;
   lr_info.meas := lc.nmeas;
   lr_info.realcnt := lc.realcnt;
   lr_info.er := NULL;
   lr_info.ed := NULL;
   lr_info.q1 := NULL;
   lr_info.q3 := NULL;
   lr_info.q2 := NULL;
   lr_info.q4 := NULL;
   lr_info.qm := qm_pg.defqm;
   lr_info.idexpr := parser_pg.newexpression (lc.vformula);

   IF lr_info.idexpr < 0 THEN
    raise_application_error (-20001, 'Ошибка компиляции формулы. ' || parser_pg.getparsererrortext);
   END IF;

   lt_info (ln_cnt) := lr_info;
  END LOOP;

--Расчет
  FOR i IN 1 .. ln_cnt LOOP
   lr_info := lt_info (i);
   ln_pcnt := 0;

   --Сохранили все параметры
   FOR lc IN (SELECT TRIM (vname) vname, UPPER (TRIM (vparam)) vparam
                FROM formulparams
               WHERE nid = lr_info.ID) LOOP   --Цикл по всем формулам
    ln_pcnt := ln_pcnt + 1;
    lr_param.vname := lc.vname;

    IF lr_info.meas = 0 AND SUBSTR (lc.vparam, LENGTH (lc.vparam)) = 'A' THEN
     lr_param.vparam := SUBSTR (lc.vparam, 1, LENGTH (lc.vparam) - 1);
     lr_param.iscommon := 1;
    ELSE
     lr_param.vparam := lc.vparam;
     lr_param.iscommon := 0;
    END IF;

    lt_param (ln_pcnt) := lr_param;
   END LOOP;

   ld_date := ld_from + cn_step;

   WHILE ld_date <= ld_till LOOP   --Цикл по датам
    ld_tmp := util_pg.to_localtime (ld_date);

    IF util_pg.is_timeswitch (ld_date) = -1 THEN
     ln_2hour := 1;
    ELSE
     ln_2hour := 0;
    END IF;

    FOR k IN 1 .. ln_pcnt LOOP   --Ищем значения Цикл по всем параметрам формулы
     FOR j IN 1 .. cn_meas LOOP
      lt_paramval ((k - 1) * cn_meas + j) := NULL;
     END LOOP;

     getval (lt_param (k).vparam, ld_tmp - cn_step, ld_tmp, k, lt_paramval, lt_qm, ln_2hour);
    END LOOP;   --Конец цикла по всем параметрам формулы

    FOR j IN 1 .. lr_info.realcnt LOOP   --Цикл по всем измерениям (для общих формул)
     FOR k IN 1 .. ln_pcnt LOOP   --Цикл по параметрам
      val := NVL (lt_paramval ((k - 1) * cn_meas + j), 0);
      ln_ret := parser_pg.setvar (lr_info.idexpr, 0, lt_param (k).vname, val);

--insert into tmp_saa(k,j,fid,dat,val,pname) values(k,j,lr_info.ID,ld_date,val,lt_param (k).vparam||'___'||lt_param (k).vname);
      IF ln_ret <> 0 THEN
       raise_application_error (-20001, 'Ошибка задания входного параметра ''' || lr_param.vname || '''' || parser_pg.getparsererrortext (ln_ret));
      END IF;
     END LOOP;

     val := 0;
     ln_ret := parser_pg.evaluate (lr_info.idexpr, val);

     IF ln_ret <> 0 THEN
      raise_application_error (-20001, 'Ошибка вычисления формулы. ' || parser_pg.getparsererrortext (ln_ret));
     END IF;

--insert into tmp_saa(k,j,fid,dat,val,pname) values(0,j,lr_info.ID,ld_date,val,'Ret'||lr_info.meas);
     IF lr_info.meas = 1 OR (lr_info.meas = 0 AND j = 1) THEN
      lr_info.er := val;
     ELSIF lr_info.meas = 2 OR (lr_info.meas = 0 AND j = 2) THEN
      lr_info.ed := val;
     ELSIF lr_info.meas = 3 OR (lr_info.meas = 0 AND j = 3) THEN
      lr_info.q1 := val;
     ELSIF lr_info.meas = 4 OR (lr_info.meas = 0 AND j = 4) THEN
      lr_info.q2 := val;
     ELSIF lr_info.meas = 5 OR (lr_info.meas = 0 AND j = 5) THEN
      lr_info.q3 := val;
     ELSIF lr_info.meas = 6 OR (lr_info.meas = 0 AND j = 6) THEN
      lr_info.q4 := val;
     END IF;
    END LOOP;

    lt_paramval.DELETE;
    ins_halfhouroldw (lr_info.mid, ld_date, lr_info.er, lr_info.ed, lr_info.q1, lr_info.q3, lr_info.q2, lr_info.q4, NULL, comsrv_pg.cn_calc, lr_info.qm);
    ld_date := ld_date + cn_step;
   END LOOP;   --Конец цикла по датам

   lt_param.DELETE;
  END LOOP;   --Конец цикла по всем формулам

  --Очистка памяти и запись в lagging_records
  FOR i IN 1 .. ln_cnt LOOP
   --Очистка памяти
   ln_ret := parser_pg.deleteexpression (lt_info (i).idexpr);
   --Чтоб считать bill по заднему числуу
   ld_tmp := TRUNC (util_pg.to_localtime (ld_from) + cn_step - 1);

   WHILE ld_tmp < util_pg.to_localtime (ld_till) AND ld_tmp < ld_calcperiod LOOP
    INSERT INTO lagging_records
                (mid, ddate)
     SELECT lt_info (i).mid, ld_tmp
       FROM DUAL
      WHERE NOT EXISTS (SELECT *
                          FROM lagging_records
                         WHERE mid = lt_info (i).mid AND ddate = ld_tmp);

    ld_tmp := ld_tmp + 1;
   END LOOP;
  END LOOP;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT calcw_sp;
   raise_application_error (-20001, 'calcformula_pg.calc: ИД=''' || lr_info.ID || ''' ' || CHR (10) || SQLERRM);
 END;

------------------------------------------------------------------------------------------------------------------------
--Копирование на точки
 PROCEDURE copyw (ad_from DATE, ad_till DATE) IS
  ld_from         DATE          DEFAULT util_pg.trunchh24_2 (ad_from);
  ld_till         DATE          DEFAULT util_pg.trunchh24_2 (ad_till);
  lv_qm           VARCHAR2 (32);
  ld_tmp          DATE;
  ld_calcperiod   DATE          DEFAULT admin_pg.get_calcperiod;
 BEGIN
  SAVEPOINT copyw_sp;

  FOR lc IN (SELECT p.mid
               FROM feeders f, points p
              WHERE f.ncalcpointtype IS NULL AND f.mid = p.mid AND p.ind = 4 AND EXISTS (SELECT *
                                                                                           FROM points pp
                                                                                          WHERE PARENT = p.mid AND ind = 3)) LOOP
   DELETE FROM halfhourold
         WHERE mid = lc.mid AND date_time > ld_from AND date_time <= ld_till + 1 / 24 AND util_pg.to_unlocaltime (date_time, nsource) > ld_from
               AND util_pg.to_unlocaltime (date_time, nsource) <= ld_till;

   ld_tmp := ld_from;

   FOR lc1 IN (SELECT   t.date_time, t.rungqm, t.norder, t.mid, t.er, t.ed, t.q1, t.q3, t.q2, t.q4, t.erm, t.edm, t.q1m, t.q3m, t.q2m, t.q4m,
                        NVL (t.vqm, qm_pg.defqm) vqm, t.nsource, f.nmainpoint
                   FROM (SELECT   util_pg.ceilhh24_2 (util_pg.to_unlocaltime (h.date_time, h.nsource)) date_time, qm_pg.rungqm (sumqm (h.vqm)) rungqm, p.norder,
                                  p.mid, SUM (h.er) er, SUM (h.ed) ed, SUM (h.q1) q1, SUM (h.q3) q3, SUM (h.q2) q2, SUM (h.q4) q4, MAX (h.erm) erm, MAX (h.edm) edm,
                                  MAX (h.q1m) q1m, MAX (h.q3m) q3m, MAX (h.q2m) q2m, MAX (h.q4m) q4m, sumqm (h.vqm) vqm, MAX (nsource) nsource
                             FROM halfhour h, points p
                            WHERE h.mid = p.mid AND p.PARENT = lc.mid AND p.ind = 3 AND h.date_time > ld_from AND h.date_time <= ld_till + 1 / 24
                                  AND util_pg.to_unlocaltime (h.date_time, h.nsource) > ld_from AND util_pg.to_unlocaltime (h.date_time, h.nsource) <= ld_till
                         GROUP BY util_pg.ceilhh24_2 (util_pg.to_unlocaltime (h.date_time, h.nsource)), p.norder, p.mid) t,
                        feeders f
                  WHERE t.mid = f.mid(+)
               ORDER BY 1, 2, 3, 4) LOOP
    WHILE ld_tmp + cn_step < lc1.date_time LOOP   --Пустые вставки
     lv_qm := qm_pg.sbt (qm_pg.defqm, 17, qm_pg.cn_add_insuff);   --Ставим бит восстановления по первичным данным
     ins_halfhouroldw (lc.mid, ld_tmp, NULL, NULL, NULL, NULL, NULL, NULL, NULL, comsrv_pg.cn_calc, lv_qm);
     ld_tmp := ld_tmp + cn_step;
    END LOOP;

    IF ld_tmp + cn_step = lc1.date_time THEN
     IF qm_pg.gbt (lc1.vqm, 1) IN (qm_pg.cn_ok, qm_pg.cn_question, qm_pg.cn_reserv) THEN
      lv_qm := lc1.vqm;

      IF qm_pg.gbt (lv_qm, 1) = qm_pg.cn_ok THEN
       lv_qm := qm_pg.sbt (lv_qm, 17, qm_pg.cn_add_ok);   --Ставим бит восстановления по первичным данным
      ELSE
       lv_qm := qm_pg.sbt (lv_qm, 17, qm_pg.cn_add_err);   --Ставим бит восстановления по первичным данным
      END IF;

      IF lc1.nsource IN (50, 59) THEN
       lv_qm := qm_pg.sbt (lv_qm, 22, qm_pg.cn_manual);   --Ручник
      ELSIF lc1.nmainpoint <> 0 THEN
       lv_qm := qm_pg.sbt (lv_qm, 22, qm_pg.cn_add_reserv);   --Дубль
      END IF;

      ins_halfhouroldw (lc.mid, lc1.date_time, lc1.er, lc1.ed, lc1.q1, lc1.q3, lc1.q2, lc1.q4, lc1.erm, lc1.edm, lc1.q1m, lc1.q3m, lc1.q2m, lc1.q4m, NULL,
                        comsrv_pg.cn_calc, lv_qm);
     ELSE
      lv_qm := qm_pg.sbt (lc1.vqm, 17, qm_pg.cn_add_err);   --Ставим бит восстановления по первичным данным
      ins_halfhouroldw (lc.mid, lc1.date_time, NULL, NULL, NULL, NULL, NULL, NULL, NULL, comsrv_pg.cn_calc, lv_qm);
     END IF;

     ld_tmp := lc1.date_time;
    END IF;
   END LOOP;

   ld_tmp := ld_tmp + cn_step;

   WHILE ld_tmp <= ld_till LOOP   --Пустые вставки
    lv_qm := qm_pg.sbt (qm_pg.defqm, 17, qm_pg.cn_add_insuff);   --Ставим бит восстановления по первичным данным
    ins_halfhouroldw (lc.mid, ld_tmp, NULL, NULL, NULL, NULL, NULL, NULL, NULL, comsrv_pg.cn_calc, lv_qm);
    ld_tmp := ld_tmp + cn_step;
   END LOOP;

   --Чтоб считать bill по заднему числуу
   ld_tmp := TRUNC (util_pg.to_localtime (ld_from) + cn_step - 1);

   WHILE ld_tmp < util_pg.to_localtime (ld_till) AND ld_tmp < ld_calcperiod LOOP
    INSERT INTO lagging_records
                (mid, ddate)
     SELECT lc.mid, ld_tmp
       FROM DUAL
      WHERE NOT EXISTS (SELECT *
                          FROM lagging_records
                         WHERE mid = lc.mid AND ddate = ld_tmp);

    ld_tmp := ld_tmp + 1;
   END LOOP;
  END LOOP;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT copyw_sp;
   raise_application_error (-20001, 'calcformula_pg.copyw: ' || SQLERRM);
 END;

------------------------------------------------------------------------------------------------------------------------
--На вход ad_day - расчет за (trunc(ad_day)..trunc(ad_day)+1]
 PROCEDURE calc (ad_day DATE) IS
  ld_day   DATE DEFAULT TRUNC (ad_day);
 BEGIN
  copyw (util_pg.to_unlocaltime (ld_day), util_pg.to_unlocaltime (ld_day + 1));
  calcw (util_pg.to_unlocaltime (ld_day), util_pg.to_unlocaltime (ld_day + 1));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE ins_halfhouroldw (an_mid NUMBER, ad_date DATE, an_er NUMBER, an_ed NUMBER, an_q1 NUMBER, an_q3 NUMBER, an_q2 NUMBER, an_q4 NUMBER, an_erm NUMBER,
 an_edm NUMBER, an_q1m NUMBER, an_q3m NUMBER, an_q2m NUMBER, an_q4m NUMBER, an_status NUMBER, an_metertype NUMBER, av_qm VARCHAR2
 ) IS
  ln_source   NUMBER        DEFAULT comsrv_pg.cn_auto;
  lv_qm       VARCHAR2 (32) DEFAULT NVL (av_qm, qm_pg.defqm);
  ld_date     DATE          DEFAULT util_pg.to_localtime (ad_date);
 BEGIN
  IF util_pg.is_timeswitch (ad_date) = -1 THEN
   ln_source := ln_source + 9;
  END IF;

  INSERT INTO halfhourold
              (mid, date_time, nsource, er, ed, q1, q3, q2, q4, erm, edm, q1m, q3m, q2m, q4m, status, nmetertype, vqm
              )
       VALUES (an_mid, ld_date, ln_source, an_er, an_ed, an_q1, an_q3, an_q2, an_q4, an_erm, an_edm, an_q1m, an_q3m, an_q2m, an_q4m, an_status, an_metertype, lv_qm
              );
 EXCEPTION
  WHEN DUP_VAL_ON_INDEX THEN
   UPDATE halfhourold
      SET er = DECODE (an_er, NULL, er, an_er),
          ed = DECODE (an_er, NULL, ed, an_ed),
          q1 = DECODE (an_q1, NULL, q1, an_q1),
          q3 = DECODE (an_q3, NULL, q3, an_q3),
          q2 = DECODE (an_q2, NULL, q2, an_q2),
          q4 = DECODE (an_q4, NULL, q4, an_q4),
          erm = DECODE (an_erm, NULL, erm, an_erm),
          edm = DECODE (an_erm, NULL, edm, an_edm),
          q1m = DECODE (an_q1m, NULL, q1m, an_q1m),
          q3m = DECODE (an_q3m, NULL, q3m, an_q3m),
          q2m = DECODE (an_q2m, NULL, q2m, an_q2m),
          q4m = DECODE (an_q4m, NULL, q4m, an_q4m),
          status = an_status,
          nmetertype = an_metertype,
          vqm = lv_qm
    WHERE mid = an_mid AND date_time = ld_date AND nsource = ln_source;
  WHEN OTHERS THEN
   RAISE;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE ins_halfhouroldw (an_mid NUMBER, ad_date DATE, an_er NUMBER, an_ed NUMBER, an_q1 NUMBER, an_q3 NUMBER, an_q2 NUMBER, an_q4 NUMBER, an_status NUMBER,
 an_metertype NUMBER, av_qm VARCHAR2
 ) IS
 BEGIN
  ins_halfhouroldw (an_mid, ad_date, an_er, an_ed, an_q1, an_q3, an_q2, an_q4, NULL, NULL, NULL, NULL, NULL, NULL, an_status, an_metertype, av_qm);
 END;
------------------------------------------------------------------------------------------------------------------------
END;   -- Package Body CALCFORMULA_PG
/


-- End of DDL Script for Package Body RYDA.CALCFORMULA_PG

