CREATE OR REPLACE 
PACKAGE BODY change_meter IS
 -- пакет работы с задачей замены счетчиков
 -- дата создания 11.11.2003 (Коваленко А.С.)
 gn_task_code NUMBER DEFAULT 48;
 ------------------------------------------------------------------------------------------------------------------------
 PROCEDURE change_meter_p(
  an_mid         NUMBER, --Ид точки
  -- данные старого счетчика
  ad_date_time_d DATE, --DATE_TIME ( дата демонтирования счетчика )
  at_m           common_pg.tt_number, -- Новые показания демонтируемого счетчика
  -- данные нового счетчика
  an_entype      NUMBER, --ENTYPE
  av_smart       VARCHAR2, --SMART
  av_mtrsn       VARCHAR2, --MTRSN
  ad_date_time   DATE, --DATE_TIME ( дата установки счетчика )
  an_digits      NUMBER, --DIGITS
  av_mtype       VARCHAR2, --MTYPE
  an_mcurrent    NUMBER, --MCURRENT
  an_mpower      NUMBER, --MPOWER
  an_mconst      NUMBER, --MCONST
  an_mclass      NUMBER, --MCLASS
  an_myear       NUMBER, --MYEAR
  an_mquarter    NUMBER, --MQUARTER
  av_memo        VARCHAR2, --VMEMO
  at_new_m       common_pg.tt_number -- Добавленная энергия при замене и показания устанавливаемого счетчика
                                    ) IS
  i             NUMBER;
  ln_kc         NUMBER;
  ln_data_found NUMBER              DEFAULT 0;
  lt_old_m      common_pg.tt_number;
  lt_m          common_pg.tt_number;
  lt_new_m      common_pg.tt_number;
  ln_erm_h      NUMBER;
  ln_edm_h      NUMBER;
  ln_q1m_h      NUMBER;
  ln_q2m_h      NUMBER;
  ln_q3m_h      NUMBER;
  ln_q4m_h      NUMBER;
  ln_id         NUMBER;
  lv_smart      VARCHAR2(1); --SMART
  lv_mtrsn      VARCHAR2(20); --MTRSN
  ld_date_time  DATE; --DATE_TIME ( дата установки счетчика )
  ln_digits     NUMBER; --DIGITS
  lv_mtype      VARCHAR2(50); --MTYPE
  ln_mcurrent   NUMBER; --MCURRENT
  ln_mpower     NUMBER; --MPOWER
  ln_mconst     NUMBER; --MCONST
  ln_mclass     NUMBER; --MCLASS
  ln_myear      NUMBER; --MYEAR
  ln_mquarter   NUMBER; --MQUARTER
 BEGIN
  SELECT kc
    INTO ln_kc
    FROM feeders
   WHERE mid = an_mid;
  SELECT id, smart, mtrsn, date_time, digits, mtype, mcurrent, mpower, mconst, mclass,
         myear, mquarter
    INTO ln_id, lv_smart, lv_mtrsn, ld_date_time, ln_digits, lv_mtype, ln_mcurrent, ln_mpower, ln_mconst, ln_mclass,
         ln_myear, ln_mquarter
    FROM meters
   WHERE mid = an_mid AND entype = an_entype;
  DELETE FROM metershistory
        WHERE mid = an_mid AND date_time = ld_date_time AND entype = an_entype;
  INSERT INTO metershistory
              (mid, date_time, dend, entype, mtrsn, digits, mtype, mcurrent, mpower,
               mconst, mclass, myear, mquarter, kc, vmemo)
       VALUES (an_mid, ld_date_time, ad_date_time_d, an_entype, lv_mtrsn, ln_digits, lv_mtype, ln_mcurrent, ln_mpower,
               ln_mconst, ln_mclass, ln_myear, ln_mquarter, ln_kc, av_memo);
  UPDATE meters
     SET (date_time, smart, entype, mtrsn, digits, mtype, mcurrent, mpower, mconst, mclass, myear, mquarter, kc) =
          (SELECT ad_date_time, av_smart, an_entype, av_mtrsn, an_digits, av_mtype, an_mcurrent, an_mpower, an_mconst,
                  an_mclass, an_myear, an_mquarter, ln_kc
             FROM DUAL)
   WHERE mid = an_mid AND entype = an_entype;
  ln_digits := LENGTH(TRUNC(ln_digits));
  FOR i IN 1 .. at_m.COUNT LOOP
   IF at_m(i) < 0 THEN
    lt_m(i) := NULL;
   ELSE
    lt_m(i) := at_m(i);
   END IF;
  END LOOP;
  FOR i IN 1 .. at_new_m.COUNT LOOP
   IF at_new_m(i) < 0 THEN
    lt_new_m(i) := NULL;
   ELSE
    lt_new_m(i) := at_new_m(i);
   END IF;
  END LOOP;
  ---------------- monthsorg --------------------------------------------------
  lt_old_m.DELETE;
  FOR i IN 1 .. 30 LOOP
   lt_old_m(i) := NULL;
  END LOOP;
  BEGIN
   SELECT erm, aerm, berm, cerm, derm, edm, aedm, bedm,
          cedm, dedm, q1m, aq1m, bq1m, cq1m, dq1m,
          q2m, aq2m, bq2m, cq2m, dq2m, q3m, aq3m,
          bq3m, cq3m, dq3m, q4m, aq4m, bq4m, cq4m,
          dq4m
     INTO lt_old_m(1), lt_old_m(2), lt_old_m(3), lt_old_m(4), lt_old_m(5), lt_old_m(6), lt_old_m(7), lt_old_m(8),
          lt_old_m(9), lt_old_m(10), lt_old_m(11), lt_old_m(12), lt_old_m(13), lt_old_m(14), lt_old_m(15),
          lt_old_m(16), lt_old_m(17), lt_old_m(18), lt_old_m(19), lt_old_m(20), lt_old_m(21), lt_old_m(22),
          lt_old_m(23), lt_old_m(24), lt_old_m(25), lt_old_m(26), lt_old_m(27), lt_old_m(28), lt_old_m(29),
          lt_old_m(30)
     FROM monthsorg m
    WHERE mid = an_mid
      AND date_time = (SELECT MAX(date_time)
                         FROM monthsorg
                        WHERE date_time < ad_date_time_d AND mid = an_mid AND nsource <> 9 AND nsource > 0)
      AND nsource = (SELECT MAX(nsource)
                       FROM monthsorg
                      WHERE date_time = m.date_time AND mid = an_mid AND nsource <> 9 AND nsource > 0);
   ln_data_found := 1;
  EXCEPTION
   WHEN NO_DATA_FOUND THEN
    ln_data_found := 0;
  END;
  DELETE FROM monthsorg
        WHERE mid = an_mid AND date_time = ad_date_time_d;
  INSERT INTO monthsorg
              (mid, date_time, source, nsource,
               remark,
               er_mtrsn, er_kc, er,
               aer,
               ber,
               cer,
               der, erm, aerm, berm, cerm,
               derm, ed_mtrsn, ed_kc, ed,
               aed,
               bed,
               ced,
               ded, edm, aedm, bedm, cedm,
               dedm, q1_mtrsn, q1_kc, q1,
               aq1,
               bq1,
               cq1,
               dq1, q1m, aq1m, bq1m, cq1m,
               dq1m, q2_mtrsn, q2_kc, q2,
               aq2,
               bq2,
               cq2,
               dq2, q2m, aq2m, bq2m, cq2m,
               dq2m, q3_mtrsn, q3_kc, q3,
               aq3,
               bq3,
               cq3,
               dq3, q3m, aq3m, bq3m, cq3m,
               dq3m, q4_mtrsn, q4_kc, q4,
               aq4,
               bq4,
               cq4,
               dq4, q4m, aq4m, bq4m, cq4m,
               dq4m)
       VALUES (an_mid, ad_date_time_d, 'Снт', 7,
               'Счетчик [' || lv_mtype || '] № ' || lv_mtrsn || ' снят с учета оператором - ' || common_pg.username_f,
               lv_mtrsn, ln_kc, util_pg.indicoverturn(lt_m(1) - lt_old_m(1), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(2) - lt_old_m(2), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(3) - lt_old_m(3), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(4) - lt_old_m(4), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(5) - lt_old_m(5), ln_digits) * ln_kc, lt_m(1), lt_m(2), lt_m(3), lt_m(4),
               lt_m(5), lv_mtrsn, ln_kc, util_pg.indicoverturn(lt_m(6) - lt_old_m(6), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(7) - lt_old_m(7), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(8) - lt_old_m(8), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(9) - lt_old_m(9), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(10) - lt_old_m(10), ln_digits) * ln_kc, lt_m(6), lt_m(7), lt_m(8), lt_m(9),
               lt_m(10), lv_mtrsn, ln_kc, util_pg.indicoverturn(lt_m(11) - lt_old_m(11), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(12) - lt_old_m(12), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(13) - lt_old_m(13), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(14) - lt_old_m(14), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(15) - lt_old_m(15), ln_digits) * ln_kc, lt_m(11), lt_m(12), lt_m(13), lt_m(14),
               lt_m(15), lv_mtrsn, ln_kc, util_pg.indicoverturn(lt_m(16) - lt_old_m(16), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(17) - lt_old_m(17), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(18) - lt_old_m(18), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(19) - lt_old_m(19), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(20) - lt_old_m(20), ln_digits) * ln_kc, lt_m(16), lt_m(17), lt_m(18), lt_m(19),
               lt_m(20), lv_mtrsn, ln_kc, util_pg.indicoverturn(lt_m(21) - lt_old_m(21), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(22) - lt_old_m(22), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(23) - lt_old_m(23), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(24) - lt_old_m(24), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(25) - lt_old_m(25), ln_digits) * ln_kc, lt_m(21), lt_m(22), lt_m(23), lt_m(24),
               lt_m(25), lv_mtrsn, ln_kc, util_pg.indicoverturn(lt_m(26) - lt_old_m(26), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(27) - lt_old_m(27), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(28) - lt_old_m(28), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(29) - lt_old_m(29), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(30) - lt_old_m(30), ln_digits) * ln_kc, lt_m(26), lt_m(27), lt_m(28), lt_m(29),
               lt_m(30));
  INSERT INTO monthsorg
              (mid, date_time, source, nsource,
               remark,
               er_mtrsn, er_kc, er, aer, ber, cer, der, erm,
               aerm, berm, cerm, derm, ed_mtrsn, ed_kc, ed, aed,
               bed, ced, ded, edm, aedm, bedm, cedm,
               dedm, q1_mtrsn, q1_kc, q1, aq1, bq1, cq1, dq1,
               q1m, aq1m, bq1m, cq1m, dq1m, q2_mtrsn, q2_kc, q2,
               aq2, bq2, cq2, dq2, q2m, aq2m, bq2m,
               cq2m, dq2m, q3_mtrsn, q3_kc, q3, aq3, bq3, cq3,
               dq3, q3m, aq3m, bq3m, cq3m, dq3m, q4_mtrsn, q4_kc,
               q4, aq4, bq4, cq4, dq4, q4m, aq4m,
               bq4m, cq4m, dq4m)
       VALUES (an_mid, ad_date_time, 'Уст', 8,
               'Счетчик [' || av_mtype || '] № ' || av_mtrsn || ' установлен оператором - ' || common_pg.username_f,
               av_mtrsn, ln_kc, lt_new_m(1), lt_new_m(2), lt_new_m(3), lt_new_m(4), lt_new_m(5), lt_new_m(6),
               lt_new_m(7), lt_new_m(8), lt_new_m(9), lt_new_m(10), av_mtrsn, ln_kc, lt_new_m(11), lt_new_m(12),
               lt_new_m(13), lt_new_m(14), lt_new_m(15), lt_new_m(16), lt_new_m(17), lt_new_m(18), lt_new_m(19),
               lt_new_m(20), av_mtrsn, ln_kc, lt_new_m(21), lt_new_m(22), lt_new_m(23), lt_new_m(24), lt_new_m(25),
               lt_new_m(26), lt_new_m(27), lt_new_m(28), lt_new_m(29), lt_new_m(30), av_mtrsn, ln_kc, lt_new_m(31),
               lt_new_m(32), lt_new_m(33), lt_new_m(34), lt_new_m(35), lt_new_m(36), lt_new_m(37), lt_new_m(38),
               lt_new_m(39), lt_new_m(40), av_mtrsn, ln_kc, lt_new_m(41), lt_new_m(42), lt_new_m(43), lt_new_m(44),
               lt_new_m(45), lt_new_m(46), lt_new_m(47), lt_new_m(48), lt_new_m(49), lt_new_m(50), av_mtrsn, ln_kc,
               lt_new_m(51), lt_new_m(52), lt_new_m(53), lt_new_m(54), lt_new_m(55), lt_new_m(56), lt_new_m(57),
               lt_new_m(58), lt_new_m(59), lt_new_m(60));
  UPDATE monthsorg mu
     SET (remark, er, aer, ber, cer, der, ed, aed, bed, ced, ded, q1, aq1, bq1, cq1, dq1, q2, aq2, bq2, cq2, dq2, q3, aq3,
          bq3, cq3, dq3, q4, aq4, bq4, cq4, dq4) =
          (SELECT 'Расходы переcчитаны при замене счетчика № ' || lv_mtrsn || ' на № ' || av_mtrsn || ' оператор - ' ||
                  common_pg.username_f,
                  util_pg.indicoverturn(erm - lt_new_m(6), ln_digits) * ln_kc,
                  util_pg.indicoverturn(aerm - lt_new_m(7), ln_digits) * ln_kc,
                  util_pg.indicoverturn(berm - lt_new_m(8), ln_digits) * ln_kc,
                  util_pg.indicoverturn(cerm - lt_new_m(9), ln_digits) * ln_kc,
                  util_pg.indicoverturn(derm - lt_new_m(10), ln_digits) * ln_kc,
                  util_pg.indicoverturn(edm - lt_new_m(16), ln_digits) * ln_kc,
                  util_pg.indicoverturn(aedm - lt_new_m(17), ln_digits) * ln_kc,
                  util_pg.indicoverturn(bedm - lt_new_m(18), ln_digits) * ln_kc,
                  util_pg.indicoverturn(cedm - lt_new_m(19), ln_digits) * ln_kc,
                  util_pg.indicoverturn(dedm - lt_new_m(20), ln_digits) * ln_kc,
                  util_pg.indicoverturn(q1m - lt_new_m(26), ln_digits) * ln_kc,
                  util_pg.indicoverturn(aq1m - lt_new_m(27), ln_digits) * ln_kc,
                  util_pg.indicoverturn(bq1m - lt_new_m(28), ln_digits) * ln_kc,
                  util_pg.indicoverturn(cq1m - lt_new_m(29), ln_digits) * ln_kc,
                  util_pg.indicoverturn(dq1m - lt_new_m(30), ln_digits) * ln_kc,
                  util_pg.indicoverturn(q2m - lt_new_m(36), ln_digits) * ln_kc,
                  util_pg.indicoverturn(aq2m - lt_new_m(37), ln_digits) * ln_kc,
                  util_pg.indicoverturn(bq2m - lt_new_m(38), ln_digits) * ln_kc,
                  util_pg.indicoverturn(cq2m - lt_new_m(39), ln_digits) * ln_kc,
                  util_pg.indicoverturn(dq2m - lt_new_m(40), ln_digits) * ln_kc,
                  util_pg.indicoverturn(q3m - lt_new_m(46), ln_digits) * ln_kc,
                  util_pg.indicoverturn(aq3m - lt_new_m(47), ln_digits) * ln_kc,
                  util_pg.indicoverturn(bq3m - lt_new_m(48), ln_digits) * ln_kc,
                  util_pg.indicoverturn(cq3m - lt_new_m(49), ln_digits) * ln_kc,
                  util_pg.indicoverturn(dq3m - lt_new_m(50), ln_digits) * ln_kc,
                  util_pg.indicoverturn(q4m - lt_new_m(56), ln_digits) * ln_kc,
                  util_pg.indicoverturn(aq4m - lt_new_m(57), ln_digits) * ln_kc,
                  util_pg.indicoverturn(bq4m - lt_new_m(58), ln_digits) * ln_kc,
                  util_pg.indicoverturn(cq4m - lt_new_m(59), ln_digits) * ln_kc,
                  util_pg.indicoverturn(dq4m - lt_new_m(60), ln_digits) * ln_kc
             FROM monthsorg m
            WHERE mid = an_mid
              AND date_time = (SELECT MIN(date_time)
                                 FROM monthsorg
                                WHERE date_time > ad_date_time_d AND mid = an_mid AND nsource <> 9 AND nsource > 0)
              AND nsource = (SELECT MIN(nsource)
                               FROM monthsorg
                              WHERE date_time = m.date_time AND mid = an_mid AND nsource <> 9 AND nsource > 0))
   WHERE mid = an_mid
     AND date_time = (SELECT MIN(date_time)
                        FROM monthsorg
                       WHERE date_time > ad_date_time_d AND mid = an_mid AND nsource <> 9 AND nsource > 0)
     AND nsource = (SELECT MIN(nsource)
                      FROM monthsorg
                     WHERE date_time = mu.date_time AND mid = an_mid AND nsource <> 9 AND nsource > 0);
  UPDATE last_save
     SET months = ad_date_time
   WHERE mid = an_mid AND months < ad_date_time;
  ---------------- billorg --------------------------------------------------
  lt_old_m.DELETE;
  FOR i IN 1 .. 30 LOOP
   lt_old_m(i) := NULL;
  END LOOP;
  BEGIN
   SELECT erm, aerm, berm, cerm, derm, edm, aedm, bedm,
          cedm, dedm, q1m, aq1m, bq1m, cq1m, dq1m,
          q2m, aq2m, bq2m, cq2m, dq2m, q3m, aq3m,
          bq3m, cq3m, dq3m, q4m, aq4m, bq4m, cq4m,
          dq4m
     INTO lt_old_m(1), lt_old_m(2), lt_old_m(3), lt_old_m(4), lt_old_m(5), lt_old_m(6), lt_old_m(7), lt_old_m(8),
          lt_old_m(9), lt_old_m(10), lt_old_m(11), lt_old_m(12), lt_old_m(13), lt_old_m(14), lt_old_m(15),
          lt_old_m(16), lt_old_m(17), lt_old_m(18), lt_old_m(19), lt_old_m(20), lt_old_m(21), lt_old_m(22),
          lt_old_m(23), lt_old_m(24), lt_old_m(25), lt_old_m(26), lt_old_m(27), lt_old_m(28), lt_old_m(29),
          lt_old_m(30)
     FROM billorg b
    WHERE mid = an_mid
      AND date_time = (SELECT MAX(date_time)
                         FROM billorg
                        WHERE date_time < ad_date_time_d AND mid = an_mid AND nsource <> 9 AND nsource > 0)
      AND nsource = (SELECT MAX(nsource)
                       FROM billorg
                      WHERE date_time = b.date_time AND mid = an_mid AND nsource <> 9 AND nsource > 0);
   ln_erm_h := lt_old_m(1);
   ln_edm_h := lt_old_m(6);
   ln_q1m_h := lt_old_m(11);
   ln_q2m_h := lt_old_m(16);
   ln_q3m_h := lt_old_m(21);
   ln_q4m_h := lt_old_m(26);
   ln_data_found := 1;
  EXCEPTION
   WHEN NO_DATA_FOUND THEN
    ln_data_found := 0;
  END;
  /*      IF ln_data_found = 1 THEN
           FOR i IN 1..30 LOOP
             IF (lt_m(i)-lt_old_m(i))<0 THEN
                 raise_application_error(-20001, 'Предыдущие показания больше настоящих '||lt_old_m(i)||' > '||lt_m(i)||'. Индекс '||i);
              END IF;
           END LOOP;
        END IF;
  */
  DELETE FROM billorg
        WHERE mid = an_mid AND date_time = ad_date_time_d;
  INSERT INTO billorg
              (mid, date_time, source, nsource,
               remark,
               er_mtrsn, er_kc, er,
               aer,
               ber,
               cer,
               der, erm, aerm, berm, cerm,
               derm, ed_mtrsn, ed_kc, ed,
               aed,
               bed,
               ced,
               ded, edm, aedm, bedm, cedm,
               dedm, q1_mtrsn, q1_kc, q1,
               aq1,
               bq1,
               cq1,
               dq1, q1m, aq1m, bq1m, cq1m,
               dq1m, q2_mtrsn, q2_kc, q2,
               aq2,
               bq2,
               cq2,
               dq2, q2m, aq2m, bq2m, cq2m,
               dq2m, q3_mtrsn, q3_kc, q3,
               aq3,
               bq3,
               cq3,
               dq3, q3m, aq3m, bq3m, cq3m,
               dq3m, q4_mtrsn, q4_kc, q4,
               aq4,
               bq4,
               cq4,
               dq4, q4m, aq4m, bq4m, cq4m,
               dq4m)
       VALUES (an_mid, ad_date_time_d, 'Снт', 7,
               'Счетчик [' || lv_mtype || '] № ' || lv_mtrsn || ' снят с учета оператором - ' || common_pg.username_f,
               lv_mtrsn, ln_kc, util_pg.indicoverturn(lt_m(1) - lt_old_m(1), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(2) - lt_old_m(2), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(3) - lt_old_m(3), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(4) - lt_old_m(4), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(5) - lt_old_m(5), ln_digits) * ln_kc, lt_m(1), lt_m(2), lt_m(3), lt_m(4),
               lt_m(5), lv_mtrsn, ln_kc, util_pg.indicoverturn(lt_m(6) - lt_old_m(6), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(7) - lt_old_m(7), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(8) - lt_old_m(8), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(9) - lt_old_m(9), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(10) - lt_old_m(10), ln_digits) * ln_kc, lt_m(6), lt_m(7), lt_m(8), lt_m(9),
               lt_m(10), lv_mtrsn, ln_kc, util_pg.indicoverturn(lt_m(11) - lt_old_m(11), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(12) - lt_old_m(12), ln_digits) * ln_kc,
               util_pg.indicoverturn(lt_m(13) - lt_old_m(13), ln_digits) * ln_kc,
