 ------------------------------------------------------------------------------------------------------------------------
 PROCEDURE del_change_meter_p(an_mid NUMBER, ad_date DATE, an_entype NUMBER) IS
  ld_date DATE;
 BEGIN
  DELETE FROM billorg
        WHERE mid = an_mid AND date_time = ad_date AND nsource IN (7, 8);
  DELETE FROM monthsorg
        WHERE mid = an_mid AND date_time = ad_date AND nsource IN (7, 8);
  FOR lc IN (SELECT *
               FROM metershistory
              WHERE mid = an_mid AND dend = ad_date AND entype = an_entype) LOOP
   DELETE FROM metershistory
         WHERE mid = an_mid AND dend = ad_date AND entype = an_entype;
   SELECT MIN(dend)
     INTO ld_date
     FROM metershistory
    WHERE mid = an_mid AND entype = an_entype AND dend > ad_date;
   IF ld_date IS NULL THEN --Если последняя замена - то копируем в meters
    UPDATE meters
       SET date_time = lc.date_time,
           mtrsn = lc.mtrsn,
           digits = lc.digits,
           mtype = lc.mtype,
           mcurrent = lc.mcurrent,
           mpower = lc.mpower,
           mconst = lc.mconst,
           mclass = lc.mclass,
           myear = lc.myear,
           mquarter = lc.mquarter,
           kc = lc.kc
     WHERE mid = an_mid AND entype = an_entype;
   ELSE --копируем в следующую
    UPDATE metershistory
       SET date_time = lc.date_time,
           mtrsn = lc.mtrsn,
           digits = lc.digits,
           mtype = lc.mtype,
           mcurrent = lc.mcurrent,
           mpower = lc.mpower,
           mconst = lc.mconst,
           mclass = lc.mclass,
           myear = lc.myear,
           mquarter = lc.mquarter,
           kc = lc.kc
     WHERE mid = an_mid AND entype = an_entype AND dend = ld_date;
   END IF;
  END LOOP;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(
    -20001, 'change_meter_p.del_change_meter_p: Ошибка при замене счетчика. ' || CHR(10) || SQLERRM(SQLCODE));
 END;
------------------------------------------------------------------------------------------------------------------------
END; -- Package Body CHANGE_METER
/


