 PROCEDURE get_mid (an_item NUMBER, acur_t OUT common_pg.tcur) IS
 -- получение mid каналов из списка
 BEGIN
  OPEN acur_t FOR
   SELECT mid
     FROM srv
    WHERE nsrv = an_item;
 END;

-------------------------------------------------------------------------------
 PROCEDURE get_readnode (an_id NUMBER, an_acc NUMBER, acur_t OUT common_pg.tcur) IS
 -- Читает список каналов
 BEGIN
  OPEN acur_t FOR
   SELECT   DECODE (c.cid, NULL, 1, 0) is_group, (SELECT COUNT (*)
                                                    FROM points
                                                   WHERE PARENT = p.mid) has_child, NVL (c.cid, p.mid) cid, p.NAME vname, c.vnote, c.protocol_id, c.com_id,
            c.init_str, c.addr, DECODE (c.nkind, 100, c.cycle_tout2, comsrvdisp_pg.cycletout_f (c.cid)) cycle_tout, c.retries, c.retries_tout,
            NVL (DECODE (c.nkind, 100, c.blocking2, c.blocking), p.tag) blocking, caller_name, nbilldata, nbilldatadepth, ncurrdata, ncurrdatadepth, nnetparam,
            njournal, TO_CHAR (DECODE (c.nkind, 100, c.dstart2, c.dstart), 'hh24:mi') dstart, TO_CHAR (DECODE (c.nkind, 100, c.dend2, c.dend), 'hh24:mi') dend,
            nday, DECODE (c.nkind, 100, c.nparent2, c.nparent) nparent, DECODE (c.nkind, 100, c.nnotreadcurr2, c.nnotreadcurr) nnotreadcurr, nwait, c.vaccuser,
            DECODE (an_acc, 1, c.vaccpassword, NULL) eusdpassword, c.nlockcorrecttime
       FROM points p, channels c
      WHERE p.PARENT = an_id AND p.mid = c.cid(+) AND NVL (nkind, 0) <> 1
   ORDER BY is_group DESC, vname;
 END;

-------------------------------------------------------------------------------
 PROCEDURE get_combo (an_item NUMBER, an_flag NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  IF (an_flag = 1) THEN
   OPEN acur_t FOR
    SELECT   protocol_id cid, NAME vname
        FROM protocols
    ORDER BY NAME;
  ELSIF (an_flag = 2) THEN
   OPEN acur_t FOR
    SELECT   com_id cid, NAME || ' (' || TO_CHAR (baudrate) || '/' || TO_CHAR (bytesize) || '/' || TO_CHAR (parity) || '/' || TO_CHAR (stopbits) || ')' vname
        FROM comports
       WHERE nsrv = an_item
    ORDER BY com_id;
  ELSIF (an_flag = 3) THEN
   OPEN acur_t FOR
    SELECT   cid, vname
        FROM channels
    ORDER BY vname;
  END IF;
 END;

-------------------------------------------------------------------------------
 PROCEDURE get_readdata1 (an_fcid NUMBER, acur_t OUT common_pg.tcur) IS
 --
 BEGIN
  OPEN acur_t FOR
   SELECT   p.mid, util_pg.get_pointname (p.mid, 1, 0) vname, p.tag, NVL (f.canal, 0) canal, NVL (f.er_position, 0) er_position, NVL (f.q1_position, 0) q1_position,
            NVL (f.ed_position, 0) ed_position, NVL (f.q3_position, 0) q3_position, f.vinfo, util_pg.get_pointname (f.nusd, 2) p_info, f.nblock, f.ndataabsence,
            f.ncommcontrol, f.ntechcontrol, f.vimportcode, NVL (f.nlockcorrecttime, 0) nblocktime, f.ntimezonew, f.ntimezones
       FROM feeders f, points p, chanpoint c, points pp
      WHERE c.cid = an_fcid AND f.mid = p.mid AND c.mid = p.mid AND pp.mid = p.PARENT
   ORDER BY pp.NAME || ' / ' || p.NAME;
 END;

-------------------------------------------------------------------------------
 PROCEDURE get_readdata2 (av_midmass VARCHAR2, acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT   p.mid, util_pg.get_pointname (p.mid, 1, 0) vname, p.tag, NVL (f.canal, 0) canal, NVL (f.er_position, 0) er_position, NVL (f.q1_position, 0) q1_position,
            NVL (f.ed_position, 0) ed_position, NVL (f.q3_position, 0) q3_position, f.vinfo, util_pg.get_pointname (f.nusd, 2) p_info, 0 nblock, f.ndataabsence,
            f.ncommcontrol, f.ntechcontrol, f.vimportcode, NVL (f.nlockcorrecttime, 0) nblocktime, f.ntimezonew, f.ntimezones
       FROM feeders f, points p, points pp
      WHERE p.mid IN (av_midmass) AND f.mid = p.mid AND pp.mid = p.PARENT
   ORDER BY pp.NAME || ' / ' || p.NAME;
 END;

-------------------------------------------------------------------------------
 PROCEDURE save_change_points (an_mid NUMBER, acur_t OUT common_pg.tcur) IS
 -- сохранение изменений для точек(уже не используется)
 BEGIN
  OPEN acur_t FOR
   SELECT p.mid, p.PARENT, 0 ptypenenugen, p.NAME, p.short_name, f.er_position, f.ed_position, f.q1_position, f.q3_position, DECODE (f.smart, ' * ', 1, 0) smart,
          DECODE (f.q1234, ' * ', 1, 0) q1234, f.canal, f.cellnum, f.POWER, f.current1, f.current2, f.kc, p.tag, f.vinfo, f.power2, f.metkc, f.nabc, f.ncalcbill,
          f.ncalcmonths, f.ninverted, f.nswitch, f.nusd, f.nblock, f.ndataabsence, f.ncommcontrol, f.ntechcontrol, f.vimportcode, f.nlockcorrecttime, f.vcode,
          f.ntimezonew, f.ntimezones
     FROM points p, feeders f
    WHERE p.mid = f.mid(+) AND p.mid = an_mid;
 END;

-------------------------------------------------------------------------------
 PROCEDURE read_notparent (acur_t OUT common_pg.tcur) IS
 -- Читает ветку дерева без родителей
 BEGIN
  OPEN acur_t FOR
   SELECT   1 havechild, p.mid, p.NAME, 1 TYPE, tag, 0 canal, 0 er_position, 0 q1_position, 0 ed_position, 0 q3_position, NULL vinfo,
            DECODE (p.ind, 1, 1, 2, 1, 4, 4, 3), util_pg.get_pointname (p.mid, 1, 0) longname, util_pg.get_pointname (f.nusd, 2) p_info, f.nblock, f.ndataabsence,
            f.ncommcontrol, f.ntechcontrol, f.vimportcode, f.nlockcorrecttime, f.ntimezonew, f.ntimezones
       FROM points p, feeders f
      WHERE p.mid = (SELECT MIN (mid)
                       FROM enterprise) AND f.mid(+) = p.mid AND EXISTS (SELECT *
                                                                           FROM points
                                                                          WHERE PARENT = p.mid AND cod = 0 AND (ind < 3 OR mid IN (SELECT mid
                                                                                                                                     FROM feeders)))
   UNION ALL
   SELECT   0 havechild, p.mid, p.NAME, 1, tag, 0 canal, 0 er_position, 0 q1_position, 0 ed_position, 0 q3_position, NULL vinfo,
            DECODE (p.ind, 1, 1, 2, 1, 4, 4, 3), util_pg.get_pointname (p.mid, 1, 0), util_pg.get_pointname (f.nusd, 2), f.nblock, f.ndataabsence, f.ncommcontrol,
            f.ntechcontrol, f.vimportcode, f.nlockcorrecttime, f.ntimezonew, f.ntimezones
       FROM points p, feeders f
      WHERE p.mid = (SELECT MIN (mid)
                       FROM enterprise) AND f.mid(+) = p.mid AND NOT EXISTS (SELECT *
                                                                               FROM points
                                                                              WHERE PARENT = p.mid AND cod = 0 AND (ind < 3 OR mid IN (SELECT mid
                                                                                                                                         FROM feeders)))
   ORDER BY 12, 3;
 END;

-------------------------------------------------------------------------------
 PROCEDURE read_vsparent (an_mid NUMBER, acur_t OUT common_pg.tcur) IS
 -- Читает ветку дерева с родителем
 BEGIN
  OPEN acur_t FOR
   SELECT   1 havechild, p.mid, p.NAME, DECODE (p.ind, 1, 1, 2, 2, 4, 4, 3) TYPE, tag, NVL (canal, 0) canal, NVL (er_position, 0) er_position,
            NVL (q1_position, 0) q1_position, NVL (ed_position, 0) ed_position, NVL (q3_position, 0) q3_position, vinfo, DECODE (p.ind, 1, 1, 2, 1, 3),
            util_pg.get_pointname (p.mid, 1, 0) longname, util_pg.get_pointname (f.nusd, 2) p_info, f.nblock, f.ndataabsence, f.ncommcontrol, f.ntechcontrol,
            f.vimportcode, f.nlockcorrecttime, f.ntimezonew, f.ntimezones
       FROM points p, feeders f
      WHERE p.PARENT = an_mid AND p.cod = 0 AND (p.ind < 3 OR p.mid IN (SELECT mid
                                                                          FROM feeders)) AND p.mid = f.mid(+)
            AND EXISTS (SELECT *
                          FROM points
                         WHERE PARENT = p.mid AND cod = 0 AND (ind < 3 OR mid IN (SELECT mid
                                                                                    FROM feeders)))
   UNION ALL
   SELECT   0 havechild, p.mid, NAME, DECODE (p.ind, 1, 1, 2, 2, 4, 4, 3), tag, NVL (canal, 0), NVL (er_position, 0), NVL (q1_position, 0), NVL (ed_position, 0),
            NVL (q3_position, 0), vinfo, DECODE (p.ind, 1, 1, 2, 1, 3), util_pg.get_pointname (p.mid, 1, 0), util_pg.get_pointname (f.nusd, 2), f.nblock,
            f.ndataabsence, f.ncommcontrol, f.ntechcontrol, f.vimportcode, f.nlockcorrecttime, f.ntimezonew, f.ntimezones
       FROM points p, feeders f
      WHERE p.PARENT = an_mid AND p.cod = 0 AND (p.ind < 3 OR p.mid IN (SELECT mid
                                                                          FROM feeders)) AND p.mid = f.mid(+)
            AND NOT EXISTS (SELECT *
                              FROM points
                             WHERE PARENT = p.mid AND cod = 0 AND (ind < 3 OR mid IN (SELECT mid
                                                                                        FROM feeders)))
   ORDER BY 12, 3;
 END;

-------------------------------------------------------------------------------
 PROCEDURE isoperstart (an_cid NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT COUNT (*) cn
     FROM channels
    WHERE cid = an_cid AND nkind = 100;
 END;
