 PROCEDURE by_balance(an_maket NUMBER, ad_date DATE) IS
  lv_ret      VARCHAR2(50);
  ln_limit    NUMBER;
  ln_mlimit   NUMBER       DEFAULT 0;
  ln_count    NUMBER       DEFAULT 0;
  ld_date     DATE         DEFAULT TRUNC(ad_date);
  ln_typever  NUMBER;
  ln_minvalue NUMBER;
 /*Верификация по балансам суммируем прием и отдачу прием должен быть на ln_limit больше чем отдача
 */
 BEGIN
  DELETE FROM check_resultsg
        WHERE nprocedure = cn_balance AND ddate > ld_date AND ddate <= ld_date + 1;
  ---Сверка баланса с уставкой
  FOR lc IN (SELECT gid, vparam
               FROM groups
              WHERE LOWER(vparam) LIKE 'баланс%') LOOP
   BEGIN
    ln_limit :=
       NVL(TO_NUMBER(TRIM(NVL(TRIM(util_pg.get_param(lc.vparam, 2)), util_pg.get_param(file_pg.gv_param, 1)))), 2) / 100;
    ln_typever :=
         NVL(TO_NUMBER(TRIM(NVL(TRIM(util_pg.get_param(lc.vparam, 3)), util_pg.get_param(file_pg.gv_param, 2)))), 1440);
    ln_minvalue :=
            NVL(TO_NUMBER(TRIM(NVL(TRIM(util_pg.get_param(lc.vparam, 4)), util_pg.get_param(file_pg.gv_param, 3)))), 0);
   EXCEPTION
    WHEN OTHERS THEN
     raise_application_error(
      -20002, 'Параметры для верификации не корректны по группе: ' || util_pg.get_groupname(lc.gid, 2));
   END;
   INSERT INTO check_resultsg
               (ddate, gid, nprocedure, vparam, nmustbe, nindeed)
    SELECT s.dat, lc.gid, cn_balance, ln_limit * 100, s.er, s.ed
      FROM (SELECT   TRUNC(ld_date) +
                     TRUNC(
                      TO_CHAR(h.date_time - 1 / 86400, 'SSSSS') / 60 / ln_typever) *
                     60 * ln_typever / 86400 +
                     ln_typever / 1440
                       dat,
                     NVL(
                      SUM(
                       DECODE(
                        g.inverted, 'y', h.ed * DECODE(g.npartly, 1, 0, 1), h.er * DECODE(g.npartly, 2, 0, 1))), 0) er,
                     NVL(
                      SUM(
                       DECODE(
                        g.inverted, 'y', h.er * DECODE(g.npartly, 2, 0, 1), h.ed * DECODE(g.npartly, 1, 0, 1))), 0) ed
                FROM halfhour h, groups g
               WHERE h.mid = g.mid
                 AND h.date_time > ld_date
                 AND h.date_time <= ld_date + 1
                 AND g.gid IN
                      (SELECT     gid
                             FROM groups
                            WHERE mid IS NOT NULL
                       CONNECT BY PRIOR gid = parent
                       START WITH gid = lc.gid)
            GROUP BY TRUNC(
                      TO_CHAR(h.date_time - 1 / 86400, 'SSSSS') / 60 / ln_typever)) s
     WHERE (   (ln_limit > 0 AND NOT (s.er - s.ed) < ln_limit * s.er)
            OR (ln_limit < 0 AND NOT (s.ed - s.er) < -ln_limit * s.ed))
       AND ABS(s.er - s.ed) > ln_minvalue;
   IF SQL%ROWCOUNT > 0 THEN
    ln_count := ln_count + 1;
    ln_mlimit := GREATEST(ABS(ln_limit), ABS(ln_mlimit)) * SIGN(GREATEST(ABS(ln_limit), ABS(ln_mlimit)));
   END IF;
  END LOOP;
  ---Сверка баланса с допустимым небалансом
  FOR lc IN (SELECT gid, vparam
               FROM groups
              WHERE LOWER(vparam) LIKE 'небаланс%') LOOP
  NULL;
  END LOOP;
  IF ln_count > 0 THEN
   IF ln_count = 1 THEN
    lv_ret := 'одной подстанции/линии.';
   ELSE
    lv_ret := ln_count || ' подстанциям/линиям.';
   END IF;
   UPDATE check_status
      SET --одна прцедура одна строка на первичный ключ не смотри
          ddate = ld_date,
          vtext = 'Сверка по балансам: превышено допустимое отклонение ' || ln_mlimit * 100 || '% по ' ||
                  lv_ret
    WHERE nprocedure = cn_balance;
   IF SQL%ROWCOUNT = 0 THEN
    INSERT INTO check_status
                (nprocedure, ddate,
                 vtext)
         VALUES (cn_balance, ld_date,
                 'Сверка по балансам: превышено допустимое отклонение ' || ln_mlimit * 100 || '% по ' ||
                 lv_ret);
   END IF;
   admin_pg.journal_p(
    cn_balance, 1, TO_CHAR(ld_date, 'dd.mm.yyyy') || ' превышено допустимое отклонение ' ||
                   ln_mlimit * 100 || '% по ' || lv_ret);
  ELSE
   DELETE FROM check_status
         WHERE nprocedure = cn_balance;
   IF SQL%ROWCOUNT <> 0 THEN
    admin_pg.journal_p(cn_balance, 0, TO_CHAR(ld_date, 'dd.mm.yyyy') || ' cостояние: Норма');
   END IF;
  END IF;
  admin_pg.signal(6);
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'check_pg.by_balance: ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ------------------------------------------------------------------------------------------------------------------------
 PROCEDURE by_duplicatemeter(an_maket NUMBER, ad_date DATE) IS
  lv_ret       VARCHAR2(50);
  ln_limit     NUMBER;
  ln_mlimit    NUMBER         DEFAULT 0;
  ln_count     NUMBER         DEFAULT 0;
  ld_date      DATE           DEFAULT TRUNC(ad_date);
  ln_typever   NUMBER;
  ln_minvalue  NUMBER;
  lv_pointname VARCHAR2(4000);
 /* Верификация по дублям разница не должна превышать ln_limit % от MAX */
 BEGIN
  DELETE FROM check_results
        WHERE nprocedure = cn_duplicatemeter AND ddate > ld_date AND ddate <= ld_date + 1;
  FOR lc IN (SELECT nmainpoint, mid, verifyparam vparam
               FROM feeders f
              WHERE nmainpoint > 0 AND TRIM(verifyparam) IS NOT NULL) LOOP
   BEGIN
    ln_limit := ABS(
                 NVL(
                  TO_NUMBER(TRIM(NVL(TRIM(util_pg.get_param(lc.vparam, 1)), util_pg.get_param(file_pg.gv_param, 1)))),
                  2) /
                 100);
    ln_typever :=
         NVL(TO_NUMBER(TRIM(NVL(TRIM(util_pg.get_param(lc.vparam, 2)), util_pg.get_param(file_pg.gv_param, 2)))), 1440);
    ln_minvalue :=
            NVL(TO_NUMBER(TRIM(NVL(TRIM(util_pg.get_param(lc.vparam, 3)), util_pg.get_param(file_pg.gv_param, 3)))), 0);
   EXCEPTION
    WHEN OTHERS THEN
     raise_application_error(
      -20002, 'Параметры для верификации не корректны по точке: ' || util_pg.get_pointname(lc.mid, 1));
   END;
   INSERT INTO check_results
               (ddate, mid, nprocedure, vparam, nmustbe, nindeed)
    SELECT m.dat, lc.mid, cn_duplicatemeter, ln_limit * 100,
           DECODE(SIGN(ABS(m.er - d.er) - ln_limit * GREATEST(m.er, d.er)), 1, m.er, m.ed) nmustbe,
           DECODE(SIGN(ABS(m.er - d.er) - ln_limit * GREATEST(m.er, d.er)), 1, d.er, d.ed) nindeed
      FROM --(select TRUNC(ld_date)+ln_typever*rownum/1440 dat from halfhourold where rownum<=1440/ln_typever) t
           (SELECT   TRUNC(ld_date) +
                     TRUNC(
                      TO_CHAR(date_time - 1 / 86400, 'SSSSS') / 60 / ln_typever) *
                     60 * ln_typever / 86400 +
                     ln_typever / 1440
                       dat,
                     SUM(er) er, SUM(ed) ed
                FROM halfhour
               WHERE mid = lc.nmainpoint AND date_time > ld_date AND date_time <= ld_date + 1
            GROUP BY TRUNC(
                      TO_CHAR(date_time - 1 / 86400, 'SSSSS') / 60 / ln_typever)) m,
           (SELECT   TRUNC(ld_date) +
                     TRUNC(
                      TO_CHAR(date_time - 1 / 86400, 'SSSSS') / 60 / ln_typever) *
                     60 * ln_typever / 86400 +
                     ln_typever / 1440
                       dat,
                     SUM(er) er, SUM(ed) ed
                FROM halfhour
               WHERE mid = lc.mid AND date_time > ld_date AND date_time <= ld_date + 1
            GROUP BY TRUNC(
                      TO_CHAR(date_time - 1 / 86400, 'SSSSS') / 60 / ln_typever)) d
     WHERE m.dat = d.dat
       AND (   (ABS(m.er - d.er) > ln_limit * GREATEST(m.er, d.er))
            OR (ABS(m.ed - d.ed) > ln_limit * GREATEST(m.ed, d.ed)))
       AND ((ABS(m.er - d.er) > ln_minvalue) OR (ABS(m.ed - d.ed) > ln_minvalue));
   IF SQL%ROWCOUNT > 0 THEN
    ln_count := ln_count + 1;
    ln_mlimit := GREATEST(ABS(ln_limit), ABS(ln_mlimit)) * SIGN(GREATEST(ABS(ln_limit), ABS(ln_mlimit)));
   END IF;
  END LOOP;
  IF ln_count > 0 THEN
   IF ln_count = 1 THEN
    lv_ret := 'одной точке.';
   ELSE
    lv_ret := ln_count || ' точкам.';
   END IF;
   lv_pointname := '';
   FOR lc IN (SELECT DISTINCT mid
                         FROM check_results
                        WHERE nprocedure = cn_duplicatemeter AND ddate > ld_date AND ddate <= ld_date + 1) LOOP
    lv_pointname := SUBSTR(lv_pointname || util_pg.get_pointname(lc.mid, 1), 1, cn_pointname);
    admin_pg.journal_p(
     lc.mid, 1, TO_CHAR(ld_date, 'dd.mm.yyyy') || ' превышено допустимое отклонение ' || ln_mlimit * 100 ||
                '%.');
   END LOOP;
   UPDATE check_status
      SET --одна прцедура одна строка на первичный ключ не смотри
          ddate = ld_date,
          vtext = SUBSTR(
                   'Сверка по дублирующим счетчикам: превышено допустимое отклонение ' ||
                   ln_mlimit * 100 || '% по ' || lv_ret || ' ' || lv_pointname, 1, cn_pointname)
    WHERE nprocedure = cn_duplicatemeter;
   IF SQL%ROWCOUNT = 0 THEN
    INSERT INTO check_status
                (nprocedure, ddate,
                 vtext)
         VALUES (cn_duplicatemeter, ld_date,
                 SUBSTR(
                  'Сверка по дублирующим счетчикам: превышено допустимое отклонение ' ||
                  ln_mlimit * 100 || '% по ' || lv_ret || ' ' || lv_pointname, 1, cn_pointname));
   END IF;
   admin_pg.journal_p(
    cn_duplicatemeter, 1, TO_CHAR(ld_date, 'dd.mm.yyyy') || ' превышено допустимое отклонение ' ||
                          ln_mlimit * 100 || '% по ' || lv_ret);
  ELSE
   DELETE FROM check_status
         WHERE nprocedure = cn_duplicatemeter;
   IF SQL%ROWCOUNT <> 0 THEN
    admin_pg.journal_p(cn_duplicatemeter, 0, TO_CHAR(ld_date, 'dd.mm.yyyy') || ' состояние: Норма');
   END IF;
  END IF;
  admin_pg.signal(6);
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'check_pg.by_duplicatemeter: ' || CHR(10) || SQLERRM(SQLCODE));
 END;
