 PROCEDURE checkpower(an_maket NUMBER, ad_date DATE) IS
  ln_typever CONSTANT NUMBER                := 30;
  ld_date             DATE                  DEFAULT util_pg.trunc_d(ad_date, ln_typever / 1440);
  ln_proc             NUMBER;
  ln_fact             NUMBER;
  ln_limit            NUMBER;
  ln_count            NUMBER                DEFAULT 0;
  lv_ret              VARCHAR2(50);
  lt_sms              common_pg.tt_varchar2;
 BEGIN
  ln_proc := NVL(util_pg.allnumber_f(util_pg.get_param(file_pg.gv_param, 1)), 1);
  DELETE FROM check_resultsg
        WHERE nprocedure = cn_checkpower AND ddate > ld_date AND ddate <= ld_date + ln_typever / 1440;
  FOR lc IN (SELECT DISTINCT gid
                        FROM grouplimit
                       WHERE dstart <= ld_date) LOOP
   ln_fact := (60 / ln_typever) *
              util_pg.get_saldo(lc.gid, ld_date, ld_date + ln_typever / 1440);
   ln_limit := util_pg.get_grouplimit(lc.gid, ld_date + ln_typever / 1440);
   IF ln_fact > ln_proc * ln_limit THEN
    IF lt_sms.COUNT = 0 THEN
     lt_sms(1) := 'CHECKPOWER WARNING:';
    END IF;
    INSERT INTO check_resultsg
                (ddate, gid, nprocedure,
                 vparam, nmustbe, nindeed)
         VALUES (ld_date + ln_typever / 1440, lc.gid, cn_checkpower,
                 ROUND(ln_proc * 100), ln_limit, ln_fact);
    ln_count := ln_count + 1;
    lt_sms(1) := lt_sms(1) || ' G.' || lc.gid || ': ' || ROUND(ln_fact) || '/' || ROUND(ln_limit);
   END IF;
  END LOOP;
  IF ln_count > 0 THEN
   IF ln_count = 1 THEN
    lv_ret := 'одной контрольной группе.';
   ELSE
    lv_ret := ln_count || ' контрольным группам.';
   END IF;
   UPDATE check_status
      SET --одна прцедура одна строка на первичный ключ не смотри
          ddate = ld_date + ln_typever / 1440,
          vtext = 'Контроль мощности: превышена допустимая граница ' || ln_proc * 100 || '% по ' || lv_ret
    WHERE nprocedure = cn_checkpower;
   IF SQL%ROWCOUNT = 0 THEN
    INSERT INTO check_status
                (nprocedure, ddate,
                 vtext)
         VALUES (cn_checkpower, ld_date + ln_typever / 1440,
                 'Контроль мощности: превышена допустимая граница ' || ln_proc * 100 || '% по ' || lv_ret);
   END IF;
   admin_pg.journal_p(
    cn_checkpower, 1, TO_CHAR(ld_date + ln_typever / 1440, 'dd.mm.yyyy') ||
                      ' превышено допустимое отклонение ' || ln_proc * 100 || '% по ' || lv_ret);
  ELSE
   DELETE FROM check_status
         WHERE nprocedure = cn_checkpower;
   IF SQL%ROWCOUNT <> 0 THEN
    admin_pg.journal_p(cn_checkpower, 0, TO_CHAR(ld_date, 'dd.mm.yyyy') || ' cостояние: Норма');
   END IF;
  END IF;
  admin_pg.signal(6);
  COMMIT;
  IF lt_sms.COUNT > 0 THEN
   file_pg.adminevents_p(lt_sms, ld_date);
  END IF;
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'check_pg.checkpower: ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ------------------------------------------------------------------------------------------------------------------------
 PROCEDURE by_day_and_hour(an_maket NUMBER, ad_date DATE) IS
  lv_ret       VARCHAR2(50);
  ln_limit     NUMBER;
  ln_mlimit    NUMBER                DEFAULT 0;
  ln_count     NUMBER                DEFAULT 0;
  ld_date      DATE                  DEFAULT TRUNC(ad_date);
  ln_minvalue  NUMBER;
  lv_pointname VARCHAR2(4000);
  lt_sms       common_pg.tt_varchar2;
 BEGIN
  DELETE FROM check_results
        WHERE nprocedure = cn_day_and_hour AND ddate > ld_date AND ddate <= ld_date + 1;
  FOR lc IN (SELECT mid, verifyday vparam
               FROM feeders f
              WHERE TRIM(verifyday) IS NOT NULL) LOOP
   BEGIN
    ln_limit := ABS(
                 NVL(
                  TO_NUMBER(TRIM(NVL(TRIM(util_pg.get_param(lc.vparam, 1)), util_pg.get_param(file_pg.gv_param, 1)))),
                  1) /
                 100);
    ln_minvalue :=
       ABS(NVL(TO_NUMBER(TRIM(NVL(TRIM(util_pg.get_param(lc.vparam, 2)), util_pg.get_param(file_pg.gv_param, 2)))), 1));
   EXCEPTION
    WHEN OTHERS THEN
     raise_application_error(
      -20002, 'Параметры для верификации суточных расходов не корректны по точке: ' || util_pg.get_pointname(lc.mid, 1));
   END;
   INSERT INTO check_results
               (ddate, mid, nprocedure, vparam, nmustbe, nindeed)
    SELECT ld_date + 1, lc.mid, cn_day_and_hour, ln_limit * 100,
           DECODE(SIGN(ABS(h.ed - d.ed) - ABS(h.er - d.er)), 1, d.ed, d.er) de,
           DECODE(SIGN(ABS(h.ed - d.ed) - ABS(h.er - d.er)), 1, h.ed, h.er) he
      FROM (SELECT SUM(er) er, SUM(ed) ed
              FROM halfhour
             WHERE mid = lc.mid AND date_time > ld_date AND date_time <= ld_date + 1
            HAVING MAX(date_time) = ld_date + 1) h,
           (SELECT SUM(b.er) er, SUM(b.ed) ed
              FROM billorg b
             WHERE b.mid = lc.mid
               AND b.date_time = ld_date + 1
               AND EXISTS( SELECT *
                             FROM billorg
                            WHERE mid = lc.mid AND date_time = ld_date AND er_mtrsn = b.er_mtrsn)) d
     WHERE (    ABS(h.er - d.er) > ln_limit * GREATEST(h.er, d.er)
            AND ABS(h.er - d.er) > ln_minvalue)
        OR (    ABS(h.ed - d.ed) > ln_limit * GREATEST(h.ed, d.ed)
            AND ABS(h.ed - d.ed) > ln_minvalue);
   IF SQL%ROWCOUNT > 0 THEN
    ln_count := ln_count + 1;
    ln_mlimit := GREATEST(ln_limit, ln_mlimit);
   END IF;
  END LOOP;
  IF ln_count > 0 THEN
   IF ln_count = 1 THEN
    lv_ret := 'одной точке.';
   ELSE
    lv_ret := ln_count || ' точкам.';
   END IF;
   lt_sms(1) := 'CHECKDAYHOUR WARNING: ' || ln_count;
   lv_pointname := '';
   FOR lc IN (SELECT DISTINCT mid
                         FROM check_results
                        WHERE nprocedure = cn_day_and_hour AND ddate > ld_date AND ddate <= ld_date + 1) LOOP
    lv_pointname := SUBSTR(lv_pointname || util_pg.get_pointname(lc.mid, 1), 1, cn_pointname);
    admin_pg.journal_p(
     lc.mid, 1, TO_CHAR(ld_date, 'dd.mm.yyyy') || ' превышено допустимое отклонение ' || ln_mlimit * 100 ||
                '%.');
   END LOOP;
   UPDATE check_status
      SET --одна прцедура одна строка на первичный ключ не смотри
          ddate = ld_date,
          vtext = SUBSTR(
                   'Сверка суточных расходов с ГН: превышено допустимое отклонение '|| ln_mlimit * 100 ||
                   '% по ' || lv_ret || ' ' || lv_pointname, 1, cn_pointname)
    WHERE nprocedure = cn_day_and_hour;
   IF SQL%ROWCOUNT = 0 THEN
    INSERT INTO check_status
                (nprocedure, ddate,
                 vtext)
         VALUES (cn_day_and_hour, ld_date,
                 SUBSTR(
                  'Сверка суточных расходов с ГН: превышено допустимое отклонение '|| ln_mlimit * 100 ||
                  '% по ' || lv_ret || ' ' || lv_pointname, 1, cn_pointname));
   END IF;
   admin_pg.journal_p(
    cn_day_and_hour, 1, TO_CHAR(ld_date, 'dd.mm.yyyy') || ' превышено допустимое отклонение ' ||
                        ln_mlimit * 100 || '% по ' || lv_ret);
  ELSE
   DELETE FROM check_status
         WHERE nprocedure = cn_day_and_hour;
   IF SQL%ROWCOUNT <> 0 THEN
    admin_pg.journal_p(cn_day_and_hour, 0, TO_CHAR(ld_date, 'dd.mm.yyyy') || ' состояние: Норма');
   END IF;
  END IF;
  admin_pg.signal(6);
  COMMIT;
  IF lt_sms.COUNT > 0 THEN
   file_pg.adminevents_p(lt_sms, ld_date);
  END IF;
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'check_pg.by_day_and_hour: ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ------------------------------------------------------------------------------------------------------------------------
 PROCEDURE checkmtrsn(an_maket NUMBER, ad_date DATE) IS
  lv_ret       VARCHAR2(50);
  lv_pointname VARCHAR2(4000);
  ld_date      DATE                  DEFAULT TRUNC(ad_date);
  ln_count     NUMBER                DEFAULT 0;
  lt_sms       common_pg.tt_varchar2;
 BEGIN
  SELECT COUNT(distinct b.mid)
    INTO ln_count
    FROM meters m, billorg b
   WHERE b.date_time >= ld_date + 1
     AND b.date_time < ld_date + 2
     AND b.mid = m.mid
     AND m.mid IN (SELECT mid
                     FROM chanpoint)
     AND (LPAD(m.mtrsn, 100, '0') <> LPAD(b.er_mtrsn, 100, '0') OR (m.mtrsn IS NULL AND b.er_mtrsn IS NOT NULL));
  IF ln_count > 0 THEN
   IF ln_count = 1 THEN
    lv_ret := 'одной точке.';
   ELSE
    lv_ret := ln_count || ' точкам.';
   END IF;
   IF lt_sms.COUNT = 0 THEN
    lt_sms(1) := 'CHECKMTRSN WARNING: ' || ln_count;
   END IF;
   lv_pointname := '';
   UPDATE check_status
      SET --одна прцедура одна строка на первичный ключ не смотри
          ddate = ld_date,
          vtext =
           SUBSTR('Контроль номера устройства с НСИ: несоответствие по '|| lv_ret || ' ' || lv_pointname, 1,
                                                                                                           cn_pointname)
    WHERE nprocedure = cn_checkmtrsn;
   IF SQL%ROWCOUNT = 0 THEN
    INSERT INTO check_status
                (nprocedure, ddate,
                 vtext)
         VALUES (cn_checkmtrsn, ld_date,
                 SUBSTR(
                  'Контроль номера устройства с НСИ: несоответствие по '|| lv_ret || ' ' || lv_pointname, 1,
                  cn_pointname));
   END IF;
   admin_pg.journal_p(cn_checkmtrsn, 1, TO_CHAR(ld_date, 'dd.mm.yyyy') || ' выявлено несоответствие по ' || lv_ret);
  ELSE
   DELETE FROM check_status
         WHERE nprocedure = cn_checkmtrsn;
   IF SQL%ROWCOUNT <> 0 THEN
    admin_pg.journal_p(cn_checkmtrsn, 0, TO_CHAR(ld_date, 'dd.mm.yyyy') || ' состояние: Норма');
   END IF;
  END IF;
  admin_pg.signal(6);
  COMMIT;
  IF lt_sms.COUNT > 0 THEN
   file_pg.adminevents_p(lt_sms, ld_date);
  END IF;
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'check_pg.checkmtrsn: ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ------------------------------------------------------------------------------------------------------------------------
 PROCEDURE checkcomplete(an_maket NUMBER, ad_date DATE) IS
  ld_date    DATE                  DEFAULT TRUNC(ad_date);
  ln_mustcnt NUMBER                DEFAULT 48 - 2 * util_pg.is_dayswitch(ld_date);
  ln_fact    NUMBER;
  ln_limit   NUMBER;
  ln_sm      NUMBER;
  ln_count   NUMBER                DEFAULT 0;
  ln_i       NUMBER                DEFAULT 0;
  lv_ret     VARCHAR2(50);
  lt_sms     common_pg.tt_varchar2;
  ln_group   NUMBER;
  lv_add     VARCHAR2(4000);
 BEGIN
  DELETE FROM check_resultsg
        WHERE nprocedure = cn_checkcomplete AND ddate > ld_date AND ddate <= ld_date + 1;
  lt_sms(1) := '';
  LOOP
   ln_group := util_pg.allnumber_f(TRIM(util_pg.get_param(file_pg.gv_param, ln_i + 1)));
   IF NVL(ln_group, 0) = 0 THEN
    EXIT;
   ELSE
    ln_i := ln_i + 1;
   END IF;
   SELECT SUM(DECODE(h.cn, ln_mustcnt, 0, 1)) err, COUNT(*) cn, util_pg.get_saldo(ln_group, ld_date, ld_date + 1) sm
     INTO ln_fact, ln_limit, ln_sm
     FROM (SELECT   mid, COUNT(distinct util_pg.trunchh24_2(date_time - 1 / 86400)) cn
               FROM halfhour
              WHERE date_time > ld_date AND date_time <= ld_date + 1
           GROUP BY mid) h,
          points p
    WHERE p.mid IN (SELECT     mid
                          FROM groups
                         WHERE mid IS NOT NULL
                    CONNECT BY PRIOR gid = parent
                    START WITH gid = ln_group)
      AND p.mid = h.mid(+);
   IF ln_fact <> 0 THEN
    INSERT INTO check_resultsg
                (ddate, gid, nprocedure, vparam, nmustbe, nindeed)
         VALUES (ld_date + 1, ln_group, cn_checkcomplete, ln_sm, ln_limit, ln_fact);
    ln_count := ln_count + 1;
   END IF;
   lt_sms(ln_i + 1) := 'G.' || ln_group || ': ' || ln_fact || '/' || ln_limit || ';E=' || ROUND(
                                                                                           ln_sm / 1000, 3);
   lv_add := lv_add || ' E.' || ln_group || '=' || ROUND(ln_sm / 1000, 3) || ';';
  END LOOP;
  IF ln_count > 0 THEN
   lt_sms(1) := 'CHECKCOMPLETE WARNING';
   IF ln_count = 1 THEN
    lv_ret := 'одной контрольной группе.';
   ELSE
    lv_ret := ln_count || ' контрольным группам.';
   END IF;
   UPDATE check_status
      SET --одна прцедура одна строка на первичный ключ не смотри
          ddate = ld_date + 1,
          vtext = 'Контроль полноты: данные не полны по ' || lv_ret
    WHERE nprocedure = cn_checkcomplete;
   IF SQL%ROWCOUNT = 0 THEN
    INSERT INTO check_status
                (nprocedure, ddate, vtext)
         VALUES (cn_checkcomplete, ld_date + 1, 'Контроль полноты: данные не полны по ' || lv_ret);
   END IF;
   admin_pg.journal_p(cn_checkcomplete, 1, TO_CHAR(ld_date + 1, 'dd.mm.yyyy') || ' данные не полны по ' || lv_ret || lv_add);
  ELSE
   lt_sms(1) := 'CHECKCOMPLETE OK';
   DELETE FROM check_status
         WHERE nprocedure = cn_checkcomplete;
   IF SQL%ROWCOUNT <> 0 THEN
    admin_pg.journal_p(cn_checkcomplete, 0, TO_CHAR(ld_date, 'dd.mm.yyyy') || ' cостояние: Норма');
   END IF;
  END IF;
  admin_pg.signal(6);
  COMMIT;
  IF  lt_sms.COUNT > 0 AND ln_i > 0 THEN
   file_pg.adminevents_p(lt_sms, ld_date);
  END IF;
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'check_pg.checkcomplete: ' || CHR(10) || SQLERRM(SQLCODE));
 END;
