 PROCEDURE by_itekcoeff(an_maket NUMBER, ddate_ DATE) IS
  LIMIT NUMBER;
  str   VARCHAR2(50);
  n     NUMBER;
  sgn   NUMBER       DEFAULT 1;
 BEGIN
  LIMIT := TO_NUMBER(file_pg.gv_param) / 100;
  IF LIMIT < 0 THEN
   LIMIT := -LIMIT;
   sgn := -1;
  END IF;
  DELETE FROM check_results
        WHERE nprocedure = cn_itekcoeff AND ddate = ddate_;
  INSERT INTO check_results
              (ddate, mid, nprocedure, vparam, nmustbe, nindeed)
   SELECT ddate_, i.mid, cn_itekcoeff, LIMIT * 100, ker,
          f.kc / DECODE(mconst, 0, 0.000001, mconst)
     FROM itekcoeff i, feeders f, meters m
    WHERE f.mid = i.mid
      AND m.mid = i.mid
      AND m.entype IN (1, 7)
      AND ker IS NOT NULL
      AND (   NVL(ker, 1) = 0
           OR NVL(mconst, 1) = 0
           OR sgn * ABS(ker - f.kc / DECODE(mconst, 0, 1, mconst)) /
              DECODE(ker, 0, 1, ker) > LIMIT);
  n := SQL%ROWCOUNT;
  IF n = 0 THEN
   DELETE FROM check_status
         WHERE nprocedure = cn_itekcoeff;
   IF SQL%ROWCOUNT <> 0 THEN
    admin_pg.journal_p(cn_itekcoeff, 0, 'Норма при допустимом отклонении ' || LIMIT * 100 || '%');
   END IF;
  ELSE
   -- Substitute
   DELETE FROM check_status
         WHERE nprocedure = cn_itekcoeff;
   IF n = 1 THEN
    str := 'одной позиции.';
   ELSE
    str := n || ' позициям.';
   END IF;
   BEGIN
    INSERT INTO check_status
                (nprocedure, ddate,
                 vtext)
         VALUES (cn_itekcoeff, ddate_,
                 'Сверка параметров УСД Итек: превышено допустимое отклонение ' || LIMIT * 100 || '% по ' ||
                 str);
    admin_pg.journal_p(cn_itekcoeff, 1, 'Превышено допустимое отклонение ' || LIMIT * 100 || '% по ' || str);
   EXCEPTION
    WHEN OTHERS THEN
     UPDATE check_status
        SET vtext = 'Сверка параметров УСД Итек: превышено допустимое отклонение ' || LIMIT * 100 ||
                    '% по ' || str
      WHERE nprocedure = cn_itekcoeff AND ddate = ddate_;
   END;
  END IF;
  admin_pg.signal(6);
  COMMIT;
 END;
