 PROCEDURE by_mtrsn(an_maket NUMBER, ddate_ DATE) IS
  LIMIT    NUMBER;
  str      VARCHAR2(50);
  how_many NUMBER       DEFAULT 0;
 BEGIN
  DELETE FROM check_results
        WHERE nprocedure = cn_mtrsn AND ddate = ddate_;
  INSERT INTO check_results
              (ddate, mid, nprocedure, vparam, nmustbe, nindeed)
   SELECT ddate_, f.mid, cn_mtrsn, 0, m.mtrsn, f.canal
     FROM feeders f, meters m
    WHERE m.mid = f.mid
      AND m.entype = 1
      AND f.canal > 50000000
      AND TO_CHAR(f.canal) <> NVL(m.mtrsn, '-')
      AND m.mtrsn <> 'ПРЕКРАЩЕНИЕ';
  how_many := SQL%ROWCOUNT;
  IF SQL%ROWCOUNT = 0 THEN
   DELETE FROM check_status
         WHERE nprocedure = cn_mtrsn;
   IF SQL%ROWCOUNT <> 0 THEN
    admin_pg.journal_p(cn_mtrsn, 0, 'Устранены несовпадения заводских и связных номеров.');
   END IF;
  ELSE
   -- Substitute
   DELETE FROM check_status
         WHERE nprocedure = cn_mtrsn;
   IF how_many = 1 THEN
    str := 'одной позиции.';
   ELSE
    str := how_many || ' позициям.';
   END IF;
   BEGIN
    INSERT INTO check_status
                (nprocedure, ddate, vtext)
         VALUES (cn_mtrsn, ddate_, 'Сверка связных номеров: нет совпадения с з-д номерами по ' || str);
    admin_pg.journal_p(cn_mtrsn, 1, ' Нет совпадения с з-д номерами по ' || str);
   EXCEPTION
    WHEN OTHERS THEN
     UPDATE check_status
        SET vtext = 'Сверка связных номеров: нет совпадения с з-д номерами по ' || str
      WHERE nprocedure = cn_mtrsn AND ddate = ddate_;
   END;
  END IF;
  admin_pg.signal(6);
  COMMIT;
 END;
