 PROCEDURE by_month_expense(an_maket NUMBER, ddate1_ DATE) IS
  LIMIT  NUMBER;
  ddate_ DATE;
  str    VARCHAR2(50);
  n      NUMBER;
  sgn    NUMBER       DEFAULT 1;
 BEGIN
  SELECT TRUNC(ddate1_, 'mm')
    INTO ddate_
    FROM DUAL;
  LIMIT := TO_NUMBER(file_pg.gv_param) / 100;
  IF LIMIT < 0 THEN
   LIMIT := -LIMIT;
   sgn := -1;
  END IF;
  DELETE FROM check_results
        WHERE nprocedure = cn_month_expense AND ddate = ddate_;
  INSERT INTO check_results
              (ddate, mid, nprocedure, vparam, nmustbe, nindeed)
   SELECT ddate_, m.mid, cn_month_expense, LIMIT * 100, ABS(NVL(m.er, 0) - NVL(m.ed, 0)), bbb
     FROM monthsorg m,
          (SELECT   mid, nsource bsource, ABS(SUM(NVL(er, 0)) - SUM(NVL(ed, 0))) bbb
               FROM halfhourold
              WHERE date_time > ddate_ AND date_time <= ADD_MONTHS(ddate_, 1) AND nsource IN (10, 20) AND mid <
                                                                                                               100000000
           GROUP BY mid, nsource) b
    WHERE b.mid = m.mid
      AND (   (m.nsource = 10 AND bsource = 10)
           OR (m.nsource = 20 AND bsource = 20 AND m.mid IN (SELECT mid
                                                               FROM feeders
                                                              WHERE canal > 50000000))
           OR (m.nsource = 20 AND bsource = 10 AND m.mid IN (SELECT mid
                                                               FROM feeders
                                                              WHERE canal < 50000000)))
      AND m.date_time = ADD_MONTHS(ddate_, 1)
      AND sgn * ABS(ABS(NVL(m.er, 0) - NVL(m.ed, 0)) - bbb) > LIMIT * ABS(NVL(m.er, 0) - NVL(m.ed, 0));
  n := SQL%ROWCOUNT;
  IF n = 0 THEN
   DELETE FROM check_status
         WHERE nprocedure = cn_month_expense;
   IF SQL%ROWCOUNT <> 0 THEN
    admin_pg.journal_p(
     cn_month_expense, 0, TO_CHAR(ddate_, 'mm.yyyy') || ' норма при допустимом отклонении ' || LIMIT * 100 ||
                          '%');
   END IF;
  ELSE
   -- Substitute
   DELETE FROM check_status
         WHERE nprocedure = cn_month_expense;
   IF n = 1 THEN
    str := 'одной позиции.';
   ELSE
    str := n || ' позициям.';
   END IF;
   BEGIN
    INSERT INTO check_status
                (nprocedure, ddate,
                 vtext)
         VALUES (cn_month_expense, ddate_,
                 'Сверка месячных расходов: превышено допустимое отклонение ' || LIMIT * 100 || '% по ' || str);
    admin_pg.journal_p(
     cn_month_expense, 1, TO_CHAR(ddate_, 'mm.yyyy') || ' превышено допустимое отклонение ' || LIMIT * 100 ||
                          '% по ' || str);
   EXCEPTION
    WHEN OTHERS THEN
     UPDATE check_status
        SET vtext = 'Сверка месячных расходов: превышено допустимое отклонение ' || LIMIT * 100 || '% по ' ||
                    str
      WHERE nprocedure = cn_month_expense AND ddate = ddate_;
   END;
  END IF;
  admin_pg.signal(6);
  COMMIT;
 END;
