 PROCEDURE by_ov(an_maket NUMBER, ddate_ DATE) IS
  LIMIT    NUMBER;
  str      VARCHAR2(50);
  sgn      NUMBER       DEFAULT 1;
  how_many NUMBER       DEFAULT 0;
 BEGIN
  LIMIT := TO_NUMBER(file_pg.gv_param) / 100;
  IF LIMIT < 0 THEN
   LIMIT := -LIMIT;
   sgn := -1;
  END IF;
  DELETE FROM check_results
        WHERE nprocedure = cn_ov AND ddate = ddate_;
  INSERT INTO check_results
              (ddate, mid, nprocedure, vparam, nmustbe, nindeed)
   SELECT   ddate_, b.nswitch, cn_ov, 0, 0, COUNT(*)
       FROM halfhourold a, halfhourold b
      WHERE a.mid = b.mid
        AND a.date_time = b.date_time
        AND b.date_time > ddate_
        AND b.date_time <= ddate_ + 1
        AND a.nsource >= 10
        AND a.nsource < 30
        AND a.nexceptcalc IS NULL
        AND b.nsource >= 30
        AND b.nsource < 50
        AND b.nexceptcalc IS NULL
        AND NVL(a.er, 0) - NVL(a.ed, 0) <> 0
   GROUP BY b.nswitch;
  how_many := SQL%ROWCOUNT;
  IF how_many = 0 THEN
   DELETE FROM check_status
         WHERE nprocedure = cn_ov;
   IF SQL%ROWCOUNT <> 0 THEN
    admin_pg.journal_p(cn_ov, 0, TO_CHAR(ddate_, 'dd.mm.yy') || ' норма ');
   END IF;
  ELSE
   -- Substitute
   DELETE FROM check_status
         WHERE nprocedure = cn_ov;
   IF how_many = 1 THEN
    str := 'одному переключению.';
   ELSE
    str := how_many || ' переключениям.';
   END IF;
   BEGIN
    INSERT INTO check_status
                (nprocedure, ddate, vtext)
         VALUES (cn_ov, ddate_, 'Сверка ОВ: не нулевой расход точки учета по ' || str);
    admin_pg.journal_p(cn_ov, 1, TO_CHAR(ddate_, 'dd.mm.yy') || ' не нулевой расход точки учета по ' || str);
   EXCEPTION
    WHEN OTHERS THEN
     UPDATE check_status
        SET vtext = 'Сверка ОВ: не нулевой расход точки учета по ' || str
      WHERE nprocedure = cn_ov AND ddate = ddate_;
   END;
  END IF;
  admin_pg.signal(6);
  COMMIT;
 END;
