 PROCEDURE report_by_fact(an_maket NUMBER, ddate_ DATE) IS
  LIMIT    NUMBER;
  str      VARCHAR2(50);
  sgn      NUMBER       DEFAULT 1;
  how_many NUMBER       DEFAULT 0;
 BEGIN
  LIMIT := TO_NUMBER(file_pg.gv_param) / 100;
  IF LIMIT < 0 THEN
   LIMIT := -LIMIT;
   sgn := -1;
  END IF;
  DELETE FROM check_results
        WHERE nprocedure = cn_report_by_fact AND ddate = ddate_;
  INSERT INTO check_results
              (ddate, mid, nprocedure, vparam, nmustbe, nindeed)
   SELECT   ddate_, a.mid, cn_report_by_fact, LIMIT * 100, ABS(SUM(b.er) - SUM(b.ed)),
            ABS(SUM(a.er) - SUM(a.ed))
       FROM halfhourold a, halfhourold b
      WHERE b.mid = a.mid
        AND b.date_time = a.date_time
        AND a.date_time > ddate_
        AND a.date_time <= ddate_ + 1
        AND a.dclosed IS NOT NULL
        AND b.nexceptcalc IS NULL
   GROUP BY a.mid
     HAVING sgn * ABS(ABS(SUM(b.er) - SUM(b.ed)) - ABS(SUM(a.er) - SUM(a.ed))) > LIMIT * ABS(SUM(b.er) - SUM(b.ed));
  how_many := SQL%ROWCOUNT;
  IF SQL%ROWCOUNT = 0 THEN
   DELETE FROM check_status
         WHERE nprocedure = cn_report_by_fact;
   IF SQL%ROWCOUNT <> 0 THEN
    admin_pg.journal_p(
     cn_report_by_fact, 0, TO_CHAR(ddate_, 'dd.mm.yy') || ' норма при допустимом отклонении ' || LIMIT * 100 ||
                           '%');
   END IF;
  ELSE
   -- Substitute
   DELETE FROM check_status
         WHERE nprocedure = cn_report_by_fact;
   IF how_many = 1 THEN
    str := 'одной позиции.';
   ELSE
    str := how_many || ' позициям.';
   END IF;
   BEGIN
    INSERT INTO check_status
                (nprocedure, ddate,
                 vtext)
         VALUES (cn_report_by_fact, ddate_,
                 'Сверка отчетных данных по факту: превышено допустимое отклонение ' || LIMIT * 100 ||
                 '% по ' || str);
    admin_pg.journal_p(
     cn_report_by_fact, 1, TO_CHAR(ddate_, 'dd.mm.yy') || ' превышено допустимое отклонение ' || LIMIT * 100 ||
                           '% по ' || str);
   EXCEPTION
    WHEN OTHERS THEN
     UPDATE check_status
        SET vtext = 'Сверка отчетных данных по факту: превышено допустимое отклонение ' || LIMIT * 100 ||
                    '% по ' || str
      WHERE nprocedure = cn_report_by_fact AND ddate = ddate_;
   END;
  END IF;
  admin_pg.signal(6);
  COMMIT;
 END;
