 --Процедура проверки полноты заполнения БД
 PROCEDURE p(
  ad_date      DATE, -- Дата для проверки данных
  an_count OUT NUMBER, -- Число проверенных точек
  at_mids  OUT common_pg.tt_number, -- Перечень точек учета
  at_text  OUT common_pg.tt_varchar2 -- Текст с результатом проверки по каждой точке
                                         ) IS
  -- Перечень точек, для которых нужно выполнить проверку (не по УСД и не ИТЕК)
  CURSOR lcur_selpoints IS
   SELECT DISTINCT p.mid
              FROM channels c, chanpoint p, feeders f
             WHERE c.blocking <> 1
               AND c.nparent IS NULL
               AND c.protocol_id NOT IN (2, 3, 22, 23, 24, 25)
               AND p.cid = c.cid
               AND f.mid = p.mid
               AND NVL(f.canal, 0) > 0
               AND f.nblock <> 1;
  -- Перечень точек, для которых нужно выполнить проверку (по каналам ИТЕК)
  CURSOR lcur_selpoints_itek IS
   SELECT DISTINCT p.mid
              FROM channels c, chanpoint p, feeders f
             WHERE c.blocking <> 1
               AND c.nparent IS NULL
               AND c.protocol_id IN (2, 3, 22, 23, 24, 25)
               AND p.cid = c.cid
               AND f.mid = p.mid
               AND f.nblock <> 1;
  -- Число получасовых показаний по точке cn_MID за дату cn_DATE без учёта наличия позиции на матрице
  CURSOR lcur_check(cn_mid NUMBER, cn_date DATE) IS
   SELECT COUNT(*) cnt
     FROM (SELECT   COUNT(*)
               FROM halfhour
              WHERE mid = cn_mid AND date_time > TRUNC(cn_date) AND date_time <= TRUNC(cn_date + 1)
           GROUP BY util_pg.trunchh24_2(date_time - 1 / 86400));
  -- Число получасовых показаний по точке cn_MID за дату cn_DATE c учётом наличия позиции на матрице
  CURSOR lcur_check2(cn_mid NUMBER, cn_date DATE) IS
   SELECT COUNT(*) cnt
     FROM (SELECT   COUNT(*)
               FROM halfhour h, feeders p
              WHERE h.mid = cn_mid
                AND p.mid = h.mid
                AND h.date_time > TRUNC(cn_date)
                AND h.date_time <= TRUNC(cn_date + 1)
                AND DECODE(NVL(p.er_position, 0), 0, 1, DECODE(h.er, NULL, 0, 1)) = 1
                AND DECODE(NVL(p.q1_position, 0), 0, 1, DECODE(h.q1, NULL, 0, 1)) = 1
                AND DECODE(NVL(p.ed_position, 0), 0, 1, DECODE(h.ed, NULL, 0, 1)) = 1
                AND DECODE(NVL(p.q3_position, 0), 0, 1, DECODE(h.q3, NULL, 0, 1)) = 1
           GROUP BY util_pg.trunchh24_2(date_time - 1 / 86400));
  CURSOR lcur_selusdp(cn_mid NUMBER) IS
   SELECT mid
     FROM feeders f
    WHERE f.nusd = cn_mid;
  -- счётчик ошибочных точек
  ln_errcount NUMBER DEFAULT 0;
 BEGIN
  an_count := 0;
  -- проверка точек, включенных в плане опроса в каналы, отличные от ИТЕК'а, и имеющих связной номер, отличный от 0
  FOR cur IN lcur_selpoints LOOP
   an_count := an_count + 1;
   FOR cnt IN lcur_check(cur.mid, ad_date) LOOP
    IF cnt.cnt <> 48 THEN
     ln_errcount := ln_errcount + 1;
     at_mids(ln_errcount) := cur.mid;
     at_text(ln_errcount) := TO_CHAR(cnt.cnt);
    END IF;
   END LOOP;
   -- проверка точек, связанных ч/з поле NUSD
   FOR cur2 IN lcur_selusdp(cur.mid) LOOP
    an_count := an_count + 1;
    FOR cnt IN lcur_check2(cur2.mid, ad_date) LOOP
     IF cnt.cnt <> 48 THEN
      ln_errcount := ln_errcount + 1;
      at_mids(ln_errcount) := cur2.mid;
      at_text(ln_errcount) := TO_CHAR(cnt.cnt);
     END IF;
    END LOOP;
   END LOOP;
  END LOOP;
  -- проверка точек, включенных в плане опроса в каналы ИТЕК
  FOR cu IN lcur_selpoints_itek LOOP
   an_count := an_count + 1;
   FOR cn IN lcur_check2(cu.mid, ad_date) LOOP
    IF cn.cnt <> 48 THEN
     ln_errcount := ln_errcount + 1;
     at_mids(ln_errcount) := cu.mid;
     at_text(ln_errcount) := TO_CHAR(cn.cnt);
    END IF;
   END LOOP;
  END LOOP;
 END;
 -----------------------------------------------------------------------------------------------------------
 PROCEDURE by_fullness(an_maket NUMBER, ddate_ DATE) IS
  CURSOR cur(cn_proc NUMBER, cd_date DATE) IS
   SELECT mid
     FROM check_results
    WHERE nprocedure = cn_proc AND ddate = cd_date;
  check_id    NUMBER                     DEFAULT 14;
  mid         NUMBER                     DEFAULT 14;
  ln_count    NUMBER;
  ln_checked  NUMBER;
  lt_mids     common_pg.tt_number;
  lt_text     common_pg.tt_varchar2;
  ln_newcount NUMBER;
 BEGIN
  check_pg.p(ddate_, ln_checked, lt_mids, lt_text);
  ln_newcount := lt_mids.COUNT();
  IF (ln_newcount = 0) THEN
   DELETE FROM check_status
         WHERE nprocedure = check_id AND ddate = ddate_;
   admin_pg.journal_p(
    check_id, 0, 'База данных за ' || TO_CHAR(ddate_, 'dd.mm.yyyy') || ' полностью заполнена. Проверено ' ||
                 TO_CHAR(ln_checked) || ' точек.', 1);
   DELETE FROM check_results
         WHERE nprocedure = check_id AND ddate = ddate_;
  ELSE
   admin_pg.journal_p(
    check_id, 1, 'Отсутствуют данные графика нагрузки по ' || TO_CHAR(ln_newcount) || ' точкам из ' || TO_CHAR(
                                                                                                        ln_checked) ||
                 ' проверенных за ' || TO_CHAR(ddate_, 'dd.mm.yyyy') || '.', 1);
   DELETE FROM check_status
         WHERE nprocedure = check_id AND ddate = ddate_;
   INSERT INTO check_status
               (nprocedure, ddate,
                vtext)
        VALUES (check_id, ddate_,
                'Отсутствуют данные графика нагрузки по ' || TO_CHAR(ln_newcount) || ' точкам из ' || TO_CHAR(
                                                                                                       ln_checked) ||
                ' проверенных. Дата проверки: ' || TO_CHAR(SYSDATE, 'dd.mm.yyyy') || '.');
   -- появились новые точки
   FOR i IN 1 .. ln_newcount LOOP
    SELECT COUNT(*)
      INTO ln_count
      FROM check_results
     WHERE nprocedure = check_id AND ddate = ddate_ AND mid = lt_mids(i);
    IF ln_count = 0 THEN
     admin_pg.journal_p(
      lt_mids(i), 1, 'Отсутствуют ' || TO_CHAR(48 - lt_text(i)) || ' значения[й] графика нагрузки за ' ||
                     TO_CHAR(ddate_, 'dd.mm.yyyy') || '.', 1);
    END IF;
   END LOOP;
   -- обновить CHECK_RESULTS
   DELETE FROM check_results
         WHERE nprocedure = check_id AND ddate = ddate_;
   FOR i IN 1 .. lt_mids.COUNT() LOOP
    INSERT INTO check_results
                (nprocedure, ddate, mid, nmustbe, nindeed)
         VALUES (check_id, ddate_, lt_mids(i), 48, lt_text(i));
   END LOOP;
  END IF;
  admin_pg.signal(6);
  COMMIT;
 END;
 -----------------------------------------------------------------------------------------------------------
 PROCEDURE requestmonitoring_p(an_maket NUMBER, ddate_ DATE) IS
  CURSOR cl_filed_points IS
   SELECT --util_pg.node_path_f (mid, 'points', 'mid', 'parent', 'name') n,
          mid, DECODE(monitoring_pg.get_group_point_status_f(mid, NULL, 2, 0, 0, 1), 0, 0, 1) c,
          DECODE(monitoring_pg.get_group_point_status_f(mid, NULL, 2, 0, 0, 0), 0, 0, 1) cnt,
          DECODE(monitoring_pg.get_group_point_status_f(mid, NULL, 2, 1, 0, 1), 0, 0, 1) t,
          DECODE(monitoring_pg.get_group_point_status_f(mid, NULL, 2, 1, 0, 0), 0, 0, 1) tnt, ndataabsencec,
          ndataabsencect, ddataabsencec
     FROM feeders;
  ld_profile   DATE          := NULL;
  ld_halfhour  DATE          := NULL;
  ld_bill      DATE          := NULL;
  ld_months    DATE          := NULL;
  ld_last_read DATE          := NULL;
  ln_mid       NUMBER        := -1;
  ln_flag      NUMBER        := 0;
  lv_msg       VARCHAR2(500) := NULL;
 BEGIN
  RETURN; ----Это временно (процедуру необходимо исправить)
  FOR filed_points IN cl_filed_points LOOP
   IF filed_points.c > 0 OR filed_points.t > 0 THEN
    ln_mid := -1;
    ln_flag := 0;
    BEGIN
     SELECT PROFILE, halfhour, bill, months
       INTO ld_profile, ld_halfhour, ld_bill, ld_months
       FROM last_save
      WHERE mid = filed_points.mid;
    EXCEPTION
     WHEN NO_DATA_FOUND THEN
      ln_flag := -1;
    END;
    BEGIN
     SELECT ls.mid, trial
       INTO ln_mid, ld_last_read
       FROM last_save ls, chanpoint c
      WHERE c.mid = filed_points.mid
        AND ls.mid = cid
        AND trial =
                   (SELECT MAX(trial) dt
                      FROM last_save ls, chanpoint c
                     WHERE c.mid = filed_points.mid AND ls.mid = cid)
        AND ROWNUM < 2;
    EXCEPTION
     WHEN NO_DATA_FOUND THEN
      ln_mid := -1;
    END;
    IF  ln_flag < 0 AND ln_mid < 0 THEN
     lv_msg := 'Нет данных. Не включена в опрос или не разу не опрашивалась';
    ELSIF ln_flag = 0 THEN
     lv_msg := 'Нет данных ' || '( ТП:' || NVL(TO_CHAR(ld_profile, 'dd.mm.yyyy hh24:mi:ss'), 'Нет') || ' ) ( ГН:' ||
               NVL(TO_CHAR(ld_halfhour, 'dd.mm.yyyy hh24:mi:ss'), 'Нет') || ' ) ( Сут.:' ||
               NVL(TO_CHAR(ld_bill, 'dd.mm.yyyy hh24:mi:ss'), 'Нет') || ' ) ( Мес.:' ||
               NVL(TO_CHAR(ld_months, 'dd.mm.yyyy hh24:mi:ss'), 'Нет') || ' )';
    END IF;
    IF ln_mid > 0 THEN
     lv_msg := lv_msg || ' Последний опрос:' || NVL(TO_CHAR(ld_last_read, 'dd.mm.yyyy hh24:mi:ss'), 'Нет') || ' Канал:' ||
               util_pg.node_path_f(ln_mid, 'points', 'mid', 'parent', 'name');
    END IF;
    admin_pg.journal_p(filed_points.mid, 50, lv_msg);
   END IF;
   UPDATE feeders
      SET ndataabsencec = DECODE(filed_points.cnt, 0, 0, DECODE(filed_points.c, 0, filed_points.ndataabsencec, 1)),
          ndataabsencect = DECODE(filed_points.tnt, 0, 0, DECODE(filed_points.t, 0, filed_points.ndataabsencect, 1)),
          ddataabsencec = DECODE(filed_points.t, 1, SYSDATE, filed_points.ddataabsencec)
    WHERE mid = filed_points.mid;
  END LOOP;
  COMMIT;
 END;
-----------------------------------------------------------------------------------------------------------
END; -- Package Body CHECK_PG
/


-- End of DDL Script for Package Body RYDA.CHECK_PG

