PACKAGE BODY comports_pg IS
 --------------------------------------------------------------------
 -- пакет работы с таблицей COMPORTS
 -- дата создания 05/02/2004 (Сечин А.А)
 gn_task_code NUMBER DEFAULT 71;
 --------------------------------------------------------------------
   --Процедура обновления данных
 PROCEDURE upd_p(
  an_com_id      NUMBER,
  an_baudrate    NUMBER,
  an_bytesize    NUMBER,
  an_parity      NUMBER,
  an_stopbits    NUMBER,
  an_ncomtype    NUMBER,
  an_ntarifftype NUMBER) IS
 BEGIN
  UPDATE comports
     SET baudrate = an_baudrate,
         bytesize = an_bytesize,
         parity = an_parity,
         stopbits = an_stopbits,
         ncomtype = an_ncomtype,
         ntarifftype = DECODE(an_ntarifftype, 0, NULL, an_ntarifftype)
   WHERE com_id = an_com_id;
  admin_pg.fiscal_p(gn_task_code, 2, 'Изменена строка COM порта' || an_com_id);
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(
    -20001, 'COMPORTS_PG.upd_p: Ошибка изменения параметров хранения таблиц. ' || CHR(10) || SQLERRM(SQLCODE));
 END;
---------------------------------------------------------------------
 PROCEDURE read_tree (an_item NUMBER, acur_t OUT common_pg.tcur) IS
 -- используется в TFormEditCOMportList::TreeRead
  -- added 01.08.2008 Kondakov A.G.
 BEGIN
  OPEN acur_t FOR
      SELECT com_id,NAME,baudrate,bytesize,parity,stopbits,ncomtype,ntarifftype,
              (SELECT count(*) FROM dual WHERE EXISTS (SELECT * FROM channels WHERE com_id=cp.com_id)) nonlyone
       FROM comports cp WHERE cp.nsrv = an_item ORDER BY 1;
 END;
------------------------------------------------------------------------
 PROCEDURE load_types (acur_t OUT common_pg.tcur) IS
 -- используется в TFormEditCOMportList::LoadTypes
 -- added 01.08.2008 Kondakov A.G.
 BEGIN
  OPEN acur_t FOR
      SELECT NCOMTYPE, VNAME FROM COMPORTTYPE ORDER BY 2;
 END;
------------------------------------------------------------------------
 PROCEDURE load_tariff_type (acur_t OUT common_pg.tcur) IS
 -- используется в TFormEditCOMportList::LoadTariffType
 -- added 01.08.2008 Kondakov A.G.
 BEGIN
  OPEN acur_t FOR
      SELECT ntarifftype, vname FROM tarifftype ORDER BY 2;
 END;
------------------------------------------------------------------------
 PROCEDURE select_data (an_item NUMBER, acur_t OUT common_pg.tcur) IS
 -- используется в TdlgJournalPortScan::SelectData
 BEGIN
  OPEN acur_t FOR
        SELECT com_num field1
                  FROM comports
                  WHERE com_id IN ( SELECT com_id FROM channels)
                        AND nsrv = an_item
                  ORDER BY 1;
 END;
------------------------------------------------------------------------
 PROCEDURE refresh_data (an_item NUMBER, acur_t OUT common_pg.tcur) IS
 -- используется в TdlgJournalPortScan::RefreshData
 BEGIN
  OPEN acur_t FOR
        SELECT com_num field1, to_char( dlastevent, 'dd.mm.yyyy hh24:mi:ss' ) field2, vlastevent field3, name field4
        FROM comports
        WHERE com_id IN ( SELECT com_id FROM channels) AND nsrv = an_item
        ORDER BY 1;
 END;
--------------------------------------------------------------------------------------
 PROCEDURE sort_data (an_item NUMBER, an_sort NUMBER, acur_t OUT common_pg.tcur) IS
 -- используется в TdlgJournalPortScan::SortData
  lv_sql               VARCHAR2(4000);
 BEGIN
  lv_sql := 'SELECT com_num field1, dlastevent field2, vlastevent field3, name field4
                  FROM comports
                  WHERE com_id IN ( SELECT com_id FROM channels)
                   AND nsrv = '||an_item||'
                  ORDER BY ';
  IF  ABS(an_sort) > 0 THEN
   lv_sql := lv_sql || ABS(an_sort);
   IF an_sort < 0 THEN
    lv_sql := lv_sql || ' DESC';
   END IF;
   lv_sql := lv_sql || ',';
  END IF;
  lv_sql := lv_sql || ' 1';
  OPEN acur_t FOR lv_sql;
 END;
------------------------------------------------------------------------
END; -- Package Body COMPORTS_PG
/


