 -- void __fastcall TComServerThread::ConnectNextPassiveDVS(void)
 FUNCTION get_passivedvs (an_cid NUMBER, ln_cid OUT NUMBER, ln_addr OUT NUMBER, ln_vname OUT VARCHAR2, ln_protocol_id OUT NUMBER, ln_init_str OUT VARCHAR2,
 ln_retries OUT NUMBER, ln_retries_tout OUT NUMBER, ln_is_block OUT NUMBER, ln_nbilldata OUT NUMBER, ln_nbilldatadepth OUT NUMBER, ln_ncurrdata OUT NUMBER,
 ln_ncurrdatadepth OUT NUMBER, ln_njournal OUT NUMBER, ln_nnetparam OUT NUMBER, ln_vuser OUT VARCHAR2, ln_vnote OUT VARCHAR2, ln_nwait OUT NUMBER
 )
  RETURN NUMBER IS
 BEGIN
  SELECT cid, TO_NUMBER (NVL (addr, '1')), SUBSTR (NVL (vname, 'Unnamed channel'), 1, 31), protocol_id, SUBSTR (NVL (init_str, ' '), 1, 63), NVL (retries, 1),
         NVL (retries_tout, 0), channels_pg.is_block (cid, blocking), nbilldata, NVL (nbilldatadepth, -1), ncurrdata, NVL (ncurrdatadepth, -1), njournal, nnetparam,
         NVL (vuser, ' '), NVL (vnote, ' '), nwait
    INTO ln_cid, ln_addr, ln_vname, ln_protocol_id, ln_init_str, ln_retries,
         ln_retries_tout, ln_is_block, ln_nbilldata, ln_nbilldatadepth, ln_ncurrdata, ln_ncurrdatadepth, ln_njournal, ln_nnetparam,
         ln_vuser, ln_vnote, ln_nwait
    FROM channels
   WHERE cid = an_cid;

  RETURN 1;
 EXCEPTION
  WHEN NO_DATA_FOUND THEN
   RETURN 0;
  WHEN OTHERS THEN
   raise_application_error (-20001, 'COMSRVCIM_PG.get_PassiveDVS: ' || SQLERRM (SQLCODE));
 END;

