 -- bool __fastcall TZxB_Thread::ConnectNextZxB_(void)
 FUNCTION connectnextzxb (an_mid NUMBER, an_cid NUMBER, ln_mid OUT NUMBER, ln_canal OUT NUMBER, ln_name OUT VARCHAR2, ln_kc OUT NUMBER, ln_tag OUT NUMBER,
 ln_vinfo OUT VARCHAR2
 )
  RETURN NUMBER IS
 BEGIN
  SELECT f.mid, NVL (f.canal, 0), SUBSTR (NVL (p.NAME, 'Unnamed ZxB'), 1, 31), NVL (f.kc, 1), NVL (p.tag, 0), SUBSTR (NVL (f.vinfo, ' '), 1, 47)
    INTO ln_mid, ln_canal, ln_name, ln_kc, ln_tag, ln_vinfo
    FROM points p, feeders f
   WHERE f.mid = p.mid AND p.mid = (SELECT MIN (p.mid)
                                      FROM points p, channels d
                                     WHERE p.mid > an_mid AND p.mid IN (SELECT mid
                                                                          FROM chanpoint
                                                                         WHERE cid = an_cid AND nskip IS NULL) AND d.cid = an_cid AND p.ind = 3);

  RETURN 1;
 EXCEPTION
  WHEN NO_DATA_FOUND THEN
   RETURN 0;
  WHEN OTHERS THEN
   raise_application_error (-20001, 'COMSRVCIM_PG.connectNextZxB: ' || SQLERRM (SQLCODE));
 END;

