 -- void __fastcall TZxB_Thread::LoadLastSaveDates(void)
 PROCEDURE ins_lastsavemeter (an_mid NUMBER, an_clock NUMBER) IS
 BEGIN
  INSERT INTO last_save
              (mid, PROFILE, halfhour, bill, months, state_date, state_cod, state_descr, clock, luck
              )
       VALUES (an_mid, SYSDATE - 1, SYSDATE - 7, SYSDATE - 62, SYSDATE - 370, SYSDATE, 0, '(Srv: Штатный режим) ', an_clock, SYSDATE - 62
              );
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20001, 'COMSRVCIM_PG.ins_LastSaveMeter: ' || SQLERRM (SQLCODE));
 END;

