 --******************************          Декларация           ******************************************************--
------------------------------------------------------------------------------------------------------------------------
 cn_waitcanal          CONSTANT NUMBER := 120;   --Ожидание зависшего канала в мин.
 cn_max_itek_rereads   CONSTANT NUMBER := 2;   -- макс. кол-во пересчитываний Итека при несовпадении профиля и суточных
 cn_max_itek_diffs     CONSTANT NUMBER := 3;   -- допустимое расхождение в импульсах профиля и суточных у Итека
 cn_lock               CONSTANT NUMBER := 30;   --максимальное время ожидания при выполнении операции

------------------------------------------------------------------------------------------------------------------------
--Помечает точки, которые не нужно опрашивать
 PROCEDURE setskippoint_p (an_channel NUMBER, an_notreadcurr NUMBER, an_protocol_id NUMBER, ad_sys DATE DEFAULT SYSDATE);

 --Исправляем ошибки ИТЭК (когда присылает хлам и суточные не сходятся с ГН)
 PROCEDURE itekmistake (an_channel NUMBER, ad_sys DATE DEFAULT SYSDATE);

------------------------------------------------------------------------------------------------------------------------
--Данная прооцедура используется для мониторинга работы процедур диспетчеризации каналов
 PROCEDURE set_log (an_port NUMBER, an_channel NUMBER, ad_sys DATE, an_state NUMBER) IS
  ln_port   NUMBER DEFAULT an_port;
 BEGIN
  /*  IF ln_port IS NULL THEN
     SELECT MAX(com_id)
