------------------------------------------------------------------------------------------------------------------------
 --******************************          Общие процедуры      *******************************************************--
------------------------------------------------------------------------------------------------------------------------
 --Нужена ли точка (например для сброса питания)
 FUNCTION is_need_point (an_protocol NUMBER)
  RETURN NUMBER IS
 BEGIN
  IF an_protocol IN (26, 51, 52) THEN
   RETURN 0;
  END IF;

  RETURN 1;
 END;

------------------------------------------------------------------------------------------------------------------------
--Признак клиентского канала
 FUNCTION is_client_canal (an_protocol NUMBER)
  RETURN NUMBER IS
 BEGIN
  IF an_protocol IN (61, 77) THEN
   RETURN 0;
  END IF;

  RETURN 1;
 END;

------------------------------------------------------------------------------------------------------------------------
--Нужен ли канал>0 (FEEDERS.CANAL>0)
 FUNCTION is_need_canal (an_protocol NUMBER)
  RETURN NUMBER IS
 BEGIN
  IF an_protocol IN (2, 3, 24, 25, 37, 38) THEN
   RETURN 0;
  END IF;

  RETURN 1;
 END;

------------------------------------------------------------------------------------------------------------------------
 --Есть ли BILLORG
 FUNCTION is_exists_bill (an_protocol NUMBER)
  RETURN NUMBER IS
 BEGIN
  IF an_protocol IN (22, 23, 24, 25) THEN
   RETURN 0;
  END IF;

  RETURN 1;
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION get_main_channel (an_channel NUMBER)
  RETURN NUMBER IS
  ln_ret   NUMBER;
 BEGIN
  SELECT     MAX (cid)
        INTO ln_ret
        FROM channels
       WHERE nparent IS NULL
  CONNECT BY PRIOR nparent = cid
  START WITH cid = an_channel;

  RETURN NVL (ln_ret, 0);
 END;

------------------------------------------------------------------------------------------------------------------------
--Читаем дату последней удачной попытки
 FUNCTION getlasttrial_f (an_channel NUMBER, ad_sys DATE DEFAULT SYSDATE)
  RETURN DATE IS
  ld_ret       DATE;
  ln_channel   NUMBER DEFAULT get_main_channel (an_channel);
 BEGIN
  SELECT MAX (trial)
    INTO ld_ret
    FROM last_save
   WHERE mid = ln_channel;

  RETURN NVL (ld_ret, ad_sys - 1);
 END;

------------------------------------------------------------------------------------------------------------------------
--Читаем паузу между циклами опроса
 FUNCTION iscycletout_f (an_channel NUMBER, ad_sys DATE)
  RETURN NUMBER IS
  ln_ret       NUMBER;
  ln_channel   NUMBER DEFAULT get_main_channel (an_channel);
 BEGIN
  SELECT COUNT (*)
    INTO ln_ret
    FROM channels
   WHERE cid = ln_channel AND ABS (ad_sys - getlasttrial_f (cid, ad_sys)) * 86400 >= cycle_tout;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
--Возвращает паузу между циклами
 FUNCTION cycletout_f (an_channel NUMBER)
  RETURN NUMBER IS
  ln_ret       NUMBER;
  ln_channel   NUMBER DEFAULT get_main_channel (an_channel);
 BEGIN
  SELECT MAX (cycle_tout)
    INTO ln_ret
    FROM channels
   WHERE cid = ln_channel;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
--Выясняем а есть ли точка, которую нужно опросить
 FUNCTION is_existnecessarypoint (an_channel NUMBER, ad_sys DATE)
  RETURN NUMBER IS
  ln_notreadcurr   NUMBER;
  ln_protocol_id   NUMBER;
 BEGIN
  SELECT MAX (nnotreadcurr), MAX (protocol_id)
    INTO ln_notreadcurr, ln_protocol_id
    FROM channels
   WHERE cid = an_channel;

  RETURN is_existnecessarypoint (an_channel, ln_notreadcurr, ln_protocol_id, ad_sys);
 END;

------------------------------------------------------------------------------------------------------------------------
--Выясняем а есть ли точка, которую нужно опросить (быстрая)
 FUNCTION is_existnecessarypoint (an_channel NUMBER, an_notreadcurr NUMBER, an_protocol_id NUMBER, ad_sys DATE)
  RETURN NUMBER IS
  ld_sys          DATE   DEFAULT TRUNC (ad_sys);
  ln_existsbill   NUMBER;
  ln_tmp          NUMBER;

  CURSOR lcur_sel (lc_needcanal NUMBER) IS
   SELECT c.mid
     FROM feeders f, chanpoint c
    WHERE c.cid = an_channel AND c.mid = f.mid(+) AND f.nblock = 0 AND (lc_needcanal = 0 OR NVL (f.canal, 0) <> 0);
 BEGIN
  IF is_need_point (an_protocol_id) = 0 THEN
   RETURN 1;
  END IF;

  ln_existsbill := is_exists_bill (an_protocol_id);

  FOR lc IN lcur_sel (is_need_canal (an_protocol_id)) LOOP
   IF NVL (an_notreadcurr, 0) <> 1 THEN   --Если нет признака не читать тек сутки возвращаем 1
    RETURN 1;
   END IF;

   --Проверяем наличае данных за тек сутки
   IF ln_existsbill = 1 THEN   --(bill и halfhour)
    SELECT COUNT (*)
      INTO ln_tmp
      FROM DUAL
     WHERE EXISTS (SELECT 1 c
                     FROM billorg
                    WHERE mid = lc.mid AND date_time >= ld_sys)
           AND EXISTS (
                 SELECT 1 c
                   FROM halfhourold
                  WHERE mid = lc.mid AND date_time >= ld_sys AND nsource = 10
                 UNION ALL
                 SELECT 1 c
                   FROM halfhourtmp
                  WHERE mid = lc.mid AND util_pg.to_localtime_if_new (date_time) >= ld_sys AND nsource = 10);
   ELSE   --(только halfhour)
    SELECT COUNT (*)
      INTO ln_tmp
      FROM DUAL
     WHERE EXISTS (
                 SELECT 1 c
                   FROM halfhourold
                  WHERE mid = lc.mid AND date_time >= ld_sys AND nsource = 10
                 UNION ALL
                 SELECT 1 c
                   FROM halfhourtmp
                  WHERE mid = lc.mid AND util_pg.to_localtime_if_new (date_time) >= ld_sys AND nsource = 10);
   END IF;

   IF ln_tmp = 0 THEN   --Мы нашли точку у которой выяснилось что чего-то нет.
    RETURN 1;
   END IF;
  END LOOP;

  RETURN 0;
 END;

------------------------------------------------------------------------------------------------------------------------
--Возвращает можно ли опрашивать по отношению основной резервный
 FUNCTION is_need_question_by_rezerv (an_channel NUMBER, ad_sys DATE)
  RETURN NUMBER IS
  ln_mainchannel   NUMBER DEFAULT get_main_channel (an_channel);
  ln_ret           NUMBER;

  CURSOR lcur_sel IS
   SELECT     cid
         FROM channels c
        WHERE   --iscycletout_f(c.cid, ad_sys) = 1 AND --Закоментировали т.к. все равно проверяем по паузе между циклами по главному
              nready IS NULL   --Идем по обделанным каналам до тех пор покуда не встретим еще не проверенные а потом просееваем WHERE обделанные
              AND is_existnecessarypoint (c.cid, c.nnotreadcurr, c.protocol_id, ad_sys) = 1
   CONNECT BY PRIOR c.cid = c.nparent AND channels_pg.is_block (c.cid, c.blocking, c.nkind) = 0
              AND TO_CHAR (NVL (c.dstart, ad_sys), 'sssss') <= TO_CHAR (ad_sys, 'sssss') AND TO_CHAR (NVL (c.dend, ad_sys), 'sssss') >= TO_CHAR (ad_sys, 'sssss')
              AND (NVL (c.nkind, 0) = 100 OR NVL (c.nday, TO_CHAR (ad_sys, 'dd')) = TO_CHAR (ad_sys, 'dd')) AND PRIOR c.nready IS NOT NULL
   START WITH cid = ln_mainchannel AND channels_pg.is_block (c.cid, c.blocking, c.nkind) = 0
              AND TO_CHAR (NVL (c.dstart, ad_sys), 'sssss') <= TO_CHAR (ad_sys, 'sssss') AND TO_CHAR (NVL (c.dend, ad_sys), 'sssss') >= TO_CHAR (ad_sys, 'sssss')
              AND (NVL (c.nkind, 0) = 100 OR NVL (c.nday, TO_CHAR (ad_sys, 'dd')) = TO_CHAR (ad_sys, 'dd'));
 BEGIN
  --Если есть опрашиваемые каналы по принципу резервирования значит - отдохни
  SELECT COUNT (*)
    INTO ln_ret
    FROM DUAL
   WHERE EXISTS (SELECT     *
                       FROM channels
                      WHERE is_dead IS NOT NULL
                 CONNECT BY PRIOR cid = nparent
                 START WITH cid = ln_mainchannel);

  IF ln_ret > 0 THEN
   RETURN 0;
  ELSE
   ln_ret := NULL;
  END IF;

  --Просим канал
  OPEN lcur_sel;

  FETCH lcur_sel
   INTO ln_ret;

  CLOSE lcur_sel;

  IF (an_channel = ln_ret) OR (ln_ret IS NULL AND an_channel = ln_mainchannel) THEN
   RETURN 1;
  END IF;

  RETURN 0;
 END;

------------------------------------------------------------------------------------------------------------------------
   --Сброс состояния (при соединении и восстановлении)
 PROCEDURE start_p (an_restore NUMBER, an_srv NUMBER) IS
  lv_mess   VARCHAR2 (128) DEFAULT 'CSrv: Запущен сервер сбора данных.';
  ln_code   NUMBER         DEFAULT 0;
  ln_mid    NUMBER;
 BEGIN
  IF an_restore > 0 THEN
   lv_mess := 'CSrv: Восстановлено подключение к БД в ' || an_restore || ' раз.';
   ln_code := 54;
  END IF;

  SELECT NVL (MAX (mid), 1)
    INTO ln_mid
    FROM srv
   WHERE nsrv = an_srv;

  admin_pg.journal_p (ln_mid, ln_code, lv_mess);

  UPDATE channels
     SET nready = NULL,
         is_dead = NULL
   WHERE com_id IN (SELECT com_id
                      FROM comports
                     WHERE nsrv = an_srv) AND (nready IS NOT NULL OR is_dead IS NOT NULL);

  admin_pg.begin_p;

  UPDATE comports
     SET vlastevent = NULL,
         dlastevent = SYSDATE
   WHERE nsrv = an_srv AND vlastevent IS NOT NULL;

  COMMIT;
  --Копируем данные из TMP
  das_pg.checkhalfhour_without_err;
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20002, 'comsrvdisp_pg.start_p: ' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
   --Вызывается при остановке опросчика
 PROCEDURE end_p (an_srv NUMBER) IS
  lv_mess   VARCHAR2 (128) DEFAULT 'CSrv: Остановлен сервер сбора данных.';
 BEGIN
  admin_pg.journal_p (an_srv, 0, lv_mess);

  UPDATE comports
     SET vlastevent = NULL,
         dlastevent = SYSDATE
   WHERE nsrv = an_srv AND vlastevent IS NOT NULL;

  COMMIT;
  das_pg.checkhalfhour_without_err;
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20002, 'comsrvdisp_pg.end_p: ' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
--Помечает точки, которые не нужно опрашивать
 PROCEDURE setskippoint_p (an_channel NUMBER, an_notreadcurr NUMBER, an_protocol_id NUMBER, ad_sys DATE) IS
  ld_sys          DATE   DEFAULT TRUNC (ad_sys);
  ln_existsbill   NUMBER;
  ln_tmp          NUMBER;

  CURSOR lcur_sel (lc_needcanal NUMBER) IS
   SELECT c.mid
     FROM feeders f, chanpoint c
    WHERE c.cid = an_channel AND c.mid = f.mid(+) AND f.nblock = 0 AND (lc_needcanal = 0 OR NVL (f.canal, 0) <> 0);
 BEGIN
  --Можно аккуратней но я решил сначала всех исключить, а затем оставить нужных
  UPDATE chanpoint
     SET nskip = 1
   WHERE cid = an_channel AND NVL (nskip, 0) <> 1;

  IF NVL (an_notreadcurr, 0) <> 1 THEN   --Если нет признака не читать тек сутки разрешаем все
   UPDATE chanpoint
      SET nskip = NULL
    WHERE cid = an_channel AND mid IN (SELECT c.mid
                                         FROM feeders f, chanpoint c
                                        WHERE c.cid = an_channel AND c.mid = f.mid(+) AND f.nblock = 0
                                              AND (is_need_canal (an_protocol_id) = 0 OR NVL (f.canal, 0) <> 0)) AND nskip IS NOT NULL;
  ELSE   --Еесть признак не читать тек сутки
   ln_existsbill := is_exists_bill (an_protocol_id);

   FOR lc IN lcur_sel (is_need_canal (an_protocol_id)) LOOP
    --Проверяем наличае данных за тек сутки
    IF ln_existsbill = 1 THEN   --(bill и halfhour)
     SELECT COUNT (*)
       INTO ln_tmp
       FROM DUAL
      WHERE EXISTS (SELECT 1 c
                      FROM billorg
                     WHERE mid = lc.mid AND date_time >= ld_sys)
            AND EXISTS (
                 SELECT 1 c
                   FROM halfhourold
                  WHERE mid = lc.mid AND date_time >= ld_sys AND nsource = 10
                 UNION ALL
                 SELECT 1 c
                   FROM halfhourtmp
                  WHERE mid = lc.mid AND util_pg.to_localtime_if_new (date_time) >= ld_sys AND nsource = 10);
    ELSE   --(только halfhour)
     SELECT COUNT (*)
       INTO ln_tmp
       FROM DUAL
      WHERE EXISTS (
                 SELECT 1 c
                   FROM halfhourold
                  WHERE mid = lc.mid AND date_time >= ld_sys AND nsource = 10
                 UNION ALL
                 SELECT 1 c
                   FROM halfhourtmp
                  WHERE mid = lc.mid AND util_pg.to_localtime_if_new (date_time) >= ld_sys AND nsource = 10);
    END IF;

    IF ln_tmp = 0 THEN   --Мы нашли точку у которой выяснилось что чего-то нет.
     UPDATE chanpoint
        SET nskip = NULL
      WHERE cid = an_channel AND mid = lc.mid AND nskip IS NOT NULL;
    END IF;
   END LOOP;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
     --Процедура извлечения параметров порта
 FUNCTION getnextchannel_f (an_port NUMBER, av_comname OUT VARCHAR2, an_baudrate OUT NUMBER, an_bytesize OUT NUMBER, an_parity OUT NUMBER, an_stopbits OUT NUMBER,
 an_ncomtype OUT NUMBER, an_protocol OUT NUMBER
 )
  RETURN NUMBER IS
  ln_ret           NUMBER;
  ln_delivered     NUMBER;
  ln_notreadcurr   NUMBER;
  ld_sys           DATE   DEFAULT SYSDATE;

  CURSOR lcur_sel IS
   SELECT   c.cid, c.ndelivered, c.nnotreadcurr, NVL (c.protocol_id, 0)
       FROM channels c
      WHERE c.com_id = an_port AND channels_pg.is_block (c.cid, c.blocking, c.nkind) = 0 AND TO_CHAR (NVL (c.dstart, ld_sys), 'sssss') <= TO_CHAR (ld_sys, 'sssss')
            AND TO_CHAR (NVL (c.dend, ld_sys), 'sssss') >= TO_CHAR (ld_sys, 'sssss')
            AND (NVL (c.nkind, 0) = 100 OR NVL (c.nday, TO_CHAR (ld_sys, 'dd')) = TO_CHAR (ld_sys, 'dd')) AND iscycletout_f (c.cid, ld_sys) = 1
            AND is_existnecessarypoint (c.cid, c.nnotreadcurr, c.protocol_id, ld_sys) = 1 AND is_need_question_by_rezerv (c.cid, ld_sys) = 1
            AND is_client_canal (c.protocol_id) = 1
   ORDER BY c.ndelivered, DECODE (c.nkind, 1, 1, 100, 2, 3), DECODE (nparent, NULL, 1, 0), c.vname;
 BEGIN
  --Обновим визуализацию
  UPDATE comports
     SET vlastevent = NULL,
         dlastevent = SYSDATE
   WHERE com_id = an_port AND vlastevent IS NOT NULL;

  COMMIT;

  --Быстрый выход в случае свободного порта
  SELECT COUNT (*)
    INTO ln_ret
    FROM DUAL
   WHERE EXISTS (SELECT *
                   FROM channels
                  WHERE com_id = an_port);   -- AND an_port IN (4, 5);

  IF ln_ret = 0 THEN
   RETURN 0;
  ELSE
   ln_ret := NULL;
  END IF;

  --Блокируем для монопольной операции
  IF admin_pg.lock_p (cn_lock, 'parameter') <> 1 THEN
   RETURN 0;
  END IF;

  --Удаляем опрошенные временные каналы точек
  FOR lc IN (SELECT cid mid
               FROM channels
              WHERE com_id = an_port AND nkind = 1 AND ndelivered = 1) LOOP
   DELETE FROM points
         WHERE mid = lc.mid;
  END LOOP;

  --Очищаем зависшие нити (watchdog)
  UPDATE channels
     SET is_dead = NULL
   WHERE com_id = an_port AND (ld_sys - is_dead) > cn_waitcanal / 1440 AND is_dead IS NOT NULL;

  --Деактивируем оперативный опрос
  FOR lc IN (SELECT cid
               FROM channels
              WHERE com_id = an_port AND nkind = 100
                    AND NOT (TO_CHAR (NVL (dstart, ld_sys), 'sssss') <= TO_CHAR (ld_sys, 'sssss')
                             AND TO_CHAR (NVL (dend, ld_sys), 'sssss') >= TO_CHAR (ld_sys, 'sssss')
                            )) LOOP
   operscan_pg.deactive_p (lc.cid);
  END LOOP;

  --Просим канал
  OPEN lcur_sel;

  FETCH lcur_sel
   INTO ln_ret, ln_delivered, ln_notreadcurr, an_protocol;

  CLOSE lcur_sel;

  --Если что-то выбрали
  IF ln_ret > 0 THEN
   --Если выбран уже опрошенный, то сбрасываем флаги у всех
   IF ln_delivered = 1 THEN
    UPDATE channels
       SET ndelivered = 0
     WHERE com_id = an_port AND ndelivered <> 0 AND NVL (nkind, 0) <> 1;
   END IF;

   --Помечаем что канал выбран и сразу думаем что он умер (и не просто думаем а говорим что он отдан на откуп) is_dead
   UPDATE channels
      SET ndelivered = 1,
          is_dead = ld_sys,
          nready = NULL
    WHERE cid = ln_ret;

   --Метим точки которые не нужно опрашивать
   setskippoint_p (ln_ret, ln_notreadcurr, an_protocol, ld_sys);

   --Вытягиваем остальную информацию по каналу (порту) для запуска нитей опроса
   SELECT NAME, baudrate, bytesize, parity, stopbits, ncomtype
     INTO av_comname, an_baudrate, an_bytesize, an_parity, an_stopbits, an_ncomtype
     FROM comports
    WHERE com_id = an_port;
  END IF;

  set_log (an_port, ln_ret, ld_sys, NULL);
  COMMIT;
  RETURN NVL (ln_ret, 0);
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20002, 'comsrvdisp_pg.getnextchannel_f: ' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE setstatuschannel_p (an_channel NUMBER, an_status NUMBER) IS   --an_status=0 - OK,=1 - вообще не открыли сокет, иначе ERROR
  ld_sys            DATE   DEFAULT SYSDATE;
  ln_main_channel   NUMBER DEFAULT get_main_channel (an_channel);
  ln_status         NUMBER DEFAULT NVL (an_status, 1);
  ln_protocol       NUMBER;
 BEGIN
  IF admin_pg.lock_p (cn_lock, 'parameter') <> 1 THEN
   RETURN;
  END IF;

  --Удаляем опрошенные временные каналы точек
  DELETE FROM points
        WHERE mid IN (SELECT cid
                        FROM channels
                       WHERE cid = an_channel AND nkind = 1);

  IF ln_status = 0 THEN   --Все опросилось успешно
   --Если Все ОК то устанавливаем дату последней попытки
   UPDATE last_save
      SET luck = ld_sys,
          trial = DECODE (mid, ln_main_channel, ld_sys, trial)
    WHERE mid IN (SELECT     cid
                        FROM channels
                  CONNECT BY PRIOR cid = nparent
                  START WITH cid = ln_main_channel);

   --Сброс nready для всех каналов начиная с основного (мы теперь не облажались)
   UPDATE channels
      SET nready = NULL
    WHERE cid IN (SELECT     cid
                        FROM channels
                  CONNECT BY PRIOR cid = nparent
                  START WITH cid = ln_main_channel) AND nready IS NOT NULL;

   --Пишем в журнал при восстановлении.
   FOR lc IN (SELECT cid, vname
                FROM channels
               WHERE cid = an_channel AND was_dead IS NOT NULL) LOOP
    admin_pg.journal_p (lc.cid, 0, 'Восстановлена связь по каналу ' || lc.vname);
    admin_pg.signal (6);
   END LOOP;

   --Сбрасываем время смерти
   UPDATE channels
      SET was_dead = NULL,
          is_dead = NULL
    WHERE cid = an_channel;
  ELSE   --Опросилось с ошибками
   --Если не ошибка открытия порта и мы на основном канале второй раз облажались то мы двигаем trial
   IF ln_status <> 1 AND an_channel = ln_main_channel THEN
    UPDATE last_save
       SET trial = ld_sys
     WHERE mid = ln_main_channel AND EXISTS (SELECT *
                                               FROM channels
                                              WHERE cid = ln_main_channel AND was_dead IS NOT NULL);
   END IF;

   -- Записывем время последнего чтения с ошибкой для простых каналов (не Итек, Фаг и т.д.)
   SELECT MAX (protocol_id)
     INTO ln_protocol
     FROM channels
    WHERE cid = an_channel;

   IF is_need_canal (ln_protocol) > 0 THEN
    UPDATE last_save
       SET fail = ld_sys
     WHERE mid = an_channel;
   END IF;

   --Вверх все запрещены (включая самого)
   UPDATE channels
      SET nready = 1
    WHERE cid IN (SELECT     cid
                        FROM channels
                  CONNECT BY PRIOR nparent = cid
                  START WITH cid = an_channel) AND NVL (nready, 0) <> 1;

   --Вниз все разрешены
   UPDATE channels
      SET nready = NULL
    WHERE cid IN (SELECT     cid
                        FROM channels
                  CONNECT BY PRIOR cid = nparent
                  START WITH nparent = an_channel) AND nready IS NOT NULL;

   --Пишем в журнал при первом сбое.
   FOR lc IN (SELECT cid, vname
                FROM channels
               WHERE cid = an_channel AND was_dead IS NULL) LOOP
    admin_pg.journal_p (lc.cid, 6, 'Нет связи по каналу ' || lc.vname);
    admin_pg.signal (6);
   END LOOP;

   --Пишем дату смерти
   UPDATE channels
      SET was_dead = DECODE (was_dead, NULL, is_dead, was_dead),
          is_dead = NULL
    WHERE cid = an_channel;
  END IF;

  --Обновим визуализацию
  UPDATE comports
     SET vlastevent = NULL,
         dlastevent = SYSDATE
   WHERE com_id = (SELECT MAX (com_id)
                     FROM channels
                    WHERE cid = an_channel);

  --Пишем в журнал
  set_log (NULL, an_channel, ld_sys, ln_status);
  --Исправляем ошибки по ИТЭК
  itekmistake (an_channel, ld_sys);
  COMMIT;
  --Копируем данные из TMP
  das_pg.checkhalfhour_without_err (0);

  --Посылаем сообщение на обновление мониторов
  IF util_pg.getparamvalue_f (24) = 1 THEN
   admin_pg.signal (3);
   admin_pg.signal (4);
  END IF;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20002, 'comsrvdisp_pg.setstatuschannel_p: ' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 --Исправляем ошибки ИТЭК (когда присылает хлам и суточные не сходятся с ГН)
 PROCEDURE itekmistake (an_channel NUMBER, ad_sys DATE) IS
  ln_main_channel   NUMBER DEFAULT get_main_channel (an_channel);
  ln_reread         NUMBER;
  ln_tmp            NUMBER;
 BEGIN
  --Читаем необходимое
  SELECT NVL (MAX (protocol_id), 0), ABS (TRUNC (MAX (nreread)))
    INTO ln_tmp, ln_reread
    FROM channels
   WHERE cid = ln_main_channel;

  -- nreread  это YYYYMMDD||itek_rereads
  -- Мы выходим если не итек или исчерпан (или все ОК) лимит перечтений
  IF ln_tmp <> 3 OR (SUBSTR (ln_reread, 1, 8) = TO_CHAR (ad_sys, 'YYYYMMDD') AND NVL (TO_NUMBER (SUBSTR (ln_reread, 9)), 0) >= cn_max_itek_rereads) THEN
   RETURN;
  END IF;

  --Выясняем сколько раз читали
  IF SUBSTR (ln_reread, 1, 8) = TO_CHAR (ad_sys, 'YYYYMMDD') THEN
   ln_reread := NVL (TO_NUMBER (SUBSTR (ln_reread, 9)), 0);
  ELSE
   ln_reread := 0;
  END IF;

  --Копируем из TMP
  das_pg.checkhalfhour_without_err (0);

  --Выясняем а есть ли получасовки
  SELECT COUNT (*)
    INTO ln_tmp
    FROM DUAL
   WHERE EXISTS (SELECT *
                   FROM halfhourold h, chanpoint cp
                  WHERE h.date_time = TRUNC (ad_sys) AND h.nsource = 20 AND h.mid = cp.mid AND cp.cid = ln_main_channel);

  IF ln_tmp = 0 THEN   --Если еще нет получасовок, то уходим
   RETURN;
  END IF;

  --Двигаем ln_reread где все не хорошо т.е. плохо
  --Двигаем ln_reread где все не хорошо т.е. плохо
  UPDATE channels
     SET nreread = TO_CHAR (ad_sys, 'YYYYMMDD') || (ln_reread + 1)
   WHERE cid = ln_main_channel
         AND EXISTS (
             SELECT *
               FROM (SELECT   h.mid, SUM (h.er) - AVG (b.er) r, SUM (h.ed) - AVG (b.ed) d
                         FROM halfhourold h, billorg b, feeders p, chanpoint cp
                        WHERE cp.cid = ln_main_channel AND h.mid = cp.mid AND b.mid = cp.mid AND p.mid(+) = cp.mid AND h.date_time > TRUNC (ad_sys) - 1
                              AND h.date_time <= TRUNC (ad_sys) AND b.date_time = TRUNC (ad_sys)
                              AND (h.nsource = DECODE (SIGN (NVL (p.canal, 0) - 50000000), 1, 20, 10)
                                   OR h.nsource = DECODE (SIGN (NVL (p.canal, 0) - 50000000), 1, 29, 19)
                                  )
                              AND b.nsource = 20
                     GROUP BY h.mid) cc,
                    itekcoeff i
              WHERE cc.mid = i.mid(+)
                    AND (ABS (NVL (cc.r, 0)) / DECODE (i.ker, 0, 1, NULL, 1, i.ker) >= cn_max_itek_diffs
                         OR ABS (NVL (cc.d, 0)) / DECODE (i.ked, 0, 1, NULL, 1, i.ked) >= cn_max_itek_diffs
                        ));

  IF SQL%ROWCOUNT > 0 THEN
   -- откатываем last_save
   UPDATE last_save
      SET halfhour = DECODE (util_pg.newhalfhour_f, 1, util_pg.to_unlocaltime (TRUNC (ad_sys) - 1), TRUNC (ad_sys) - 1),
          bill = DECODE (util_pg.newhalfhour_f, 1, util_pg.to_unlocaltime (TRUNC (ad_sys) - 1), TRUNC (ad_sys) - 1),
          trial = TRUNC (ad_sys) - 1
    WHERE mid IN (SELECT     cid
                        FROM channels
                  CONNECT BY PRIOR cid = nparent
                  START WITH cid = ln_main_channel);

   -- отмечаем факт отката данных в журнале событий
   admin_pg.journal_p (ln_main_channel, -999, 'Откат данных Итека при несовпадении суточных');
  ELSE
   -- Ставим на cn_max_itek_rereads, чтоб больше не дергались и выходили быстро без проверки (cn_max_itek_rereads+1 чтоб заметить)
   UPDATE channels
      SET nreread = TO_CHAR (ad_sys, 'YYYYMMDD') || (cn_max_itek_rereads + 1)
    WHERE cid = ln_main_channel;
  END IF;
 END;

