     --Дай канал УППД
 FUNCTION getuppdchannel_f (av_user VARCHAR2, an_port OUT NUMBER, av_comname OUT VARCHAR2, av_pass OUT VARCHAR2, an_srv NUMBER)
  RETURN NUMBER IS
  ld_sys   DATE   DEFAULT SYSDATE;
  ln_ret   NUMBER;
 BEGIN
  FOR lc IN (SELECT   c.cid, c.com_id, c.vaccpassword
                 FROM channels c
                WHERE c.protocol_id = 61 AND UPPER (vaccuser) = UPPER (av_user) AND channels_pg.is_block (c.cid, c.blocking, c.nkind) = 0
                      AND TO_CHAR (NVL (c.dstart, ld_sys), 'sssss') <= TO_CHAR (ld_sys, 'sssss')
                      AND TO_CHAR (NVL (c.dend, ld_sys), 'sssss') >= TO_CHAR (ld_sys, 'sssss')
                      AND (NVL (c.nkind, 0) = 100 OR NVL (c.nday, TO_CHAR (ld_sys, 'dd')) = TO_CHAR (ld_sys, 'dd')) AND nparent IS NULL
                      AND c.com_id IN (SELECT com_id
                                         FROM comports
                                        WHERE nsrv = an_srv)
             ORDER BY c.cid) LOOP
   ln_ret := lc.cid;
   an_port := lc.com_id;
   av_pass := lc.vaccpassword;

   SELECT NAME
     INTO av_comname
     FROM comports
    WHERE com_id = lc.com_id;

   EXIT;
  END LOOP;

  RETURN NVL (ln_ret, 0);
 END;

------------------------------------------------------------------------------------------------------------------------
    --Дай первый канал УППД
 FUNCTION getfirstuppdserverchannel_f (an_port NUMBER, av_comname OUT VARCHAR2, an_baudrate OUT NUMBER, an_bytesize OUT NUMBER, an_parity OUT NUMBER,
 an_stopbits OUT NUMBER, an_ncomtype OUT NUMBER, an_protocol OUT NUMBER, an_srv NUMBER
 )
  RETURN NUMBER IS
  ln_ret    NUMBER;
  ln_port   NUMBER;
 BEGIN
  SELECT NVL (MAX (c.cid), 0), NVL (MAX (c.com_id), 0)
    INTO ln_ret, ln_port
    FROM channels c
   WHERE c.protocol_id = 61 AND c.com_id IN (SELECT com_id
                                               FROM comports
                                              WHERE nsrv = an_srv);

  IF ln_ret > 0 THEN
   SELECT NAME, baudrate, bytesize, parity, stopbits, ncomtype
     INTO av_comname, an_baudrate, an_bytesize, an_parity, an_stopbits, an_ncomtype
     FROM comports
    WHERE com_id = ln_port;
  END IF;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
  --По опросчику и номеру порта возвращает ид. порта
 FUNCTION getportid_f (an_comnum NUMBER, an_srv NUMBER)
  RETURN NUMBER IS
  ln_ret   NUMBER;
 BEGIN
  SELECT MAX (com_id)
    INTO ln_ret
    FROM comports
   WHERE com_num = an_comnum AND nsrv = an_srv;

  RETURN ln_ret;
 END;

