    --Вставка суточных расходов
 PROCEDURE set_bill_dllmtr (an_mid NUMBER, an_er NUMBER, an_ed NUMBER, an_q1 NUMBER, an_q3 NUMBER, an_q2 NUMBER, an_q4 NUMBER, an_aer NUMBER, an_aed NUMBER,
