 -- "Открытие доступа" к счетчику (Если возвращает 0 -- счетчик отсутствует в БД)
 FUNCTION dblink_openmtraccs (an_mid NUMBER)
  RETURN NUMBER IS
  ln_tmp   NUMBER;
 BEGIN
  SELECT COUNT (*)
    INTO ln_tmp
    FROM DUAL
   WHERE EXISTS (SELECT *
                   FROM feeders
                  WHERE mid = an_mid);

  RETURN ln_tmp;
 END;

------------------------------------------------------------------------------------------------------------------------
--Запрос серийного номера счетчика
 FUNCTION dblink_get_mtr_serno (an_mid NUMBER, av_serno OUT VARCHAR2)
  RETURN NUMBER IS
  lv_serno   VARCHAR2 (256);
 BEGIN
  SELECT TRIM (MAX (er_mtrsn))
    INTO lv_serno
    FROM billorg
   WHERE mid = an_mid AND date_time = (SELECT MAX (date_time)
                                         FROM billorg
                                        WHERE mid = an_mid);

  av_serno := NVL (lv_serno, ' ');

  IF lv_serno IS NULL THEN
   RETURN 0;
  END IF;

  RETURN 1;
 END;

