 PROCEDURE dblink_get_curr_power (an_mid NUMBER, an_erm OUT NUMBER, an_edm OUT NUMBER, an_q1m OUT NUMBER, an_q3m OUT NUMBER, an_q2m OUT NUMBER, an_q4m OUT NUMBER,
 an_freq OUT NUMBER, an_cos_fi OUT NUMBER, an_volt1 OUT NUMBER, an_volt2 OUT NUMBER, an_volt3 OUT NUMBER, an_curr1 OUT NUMBER, an_curr2 OUT NUMBER,
 an_curr3 OUT NUMBER, an_fiu1i1 OUT NUMBER, an_fiu2i2 OUT NUMBER, an_fiu3i3 OUT NUMBER, an_fiu1u2 OUT NUMBER, an_fiu1u3 OUT NUMBER, an_fiu2u3 OUT NUMBER,
 an_er OUT NUMBER, an_ed OUT NUMBER, an_q1 OUT NUMBER, an_q3 OUT NUMBER, an_q2 OUT NUMBER, an_q4 OUT NUMBER, ad_date OUT VARCHAR2
 ) IS
 BEGIN
  FOR lc IN (SELECT *
               FROM curr_power
              WHERE mid = an_mid) LOOP
   an_erm := lc.erm;
   an_edm := lc.edm;
   an_q1m := lc.q1m;
   an_q3m := lc.q3m;
   an_q2m := lc.q2m;
   an_q4m := lc.q4m;
   an_freq := lc.freq;
   an_cos_fi := lc.cosf;
   an_volt1 := lc.volt;
   an_volt2 := lc.volt2;
   an_volt3 := lc.volt3;
   an_curr1 := lc.currento;
   an_curr2 := lc.curr2;
   an_curr3 := lc.curr3;
   an_er := lc.er;
   an_ed := lc.ed;
   an_q1 := lc.q1;
   an_q3 := lc.q3;
   an_q2 := lc.q2;
   an_q4 := lc.q4;
   an_fiu1u2 := lc.nfiu1;
   an_fiu1u3 := lc.nfiu2;
   an_fiu2u3 := lc.nfiu3;
   an_fiu1i1 := lc.nfii1;
   an_fiu2i2 := lc.nfii2;
   an_fiu3i3 := lc.nfii3;
   ad_date := TO_CHAR (lc.date_time, 'dd.mm.yyyy hh24:mi');
   EXIT;
  END LOOP;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20001, 'comsrvdll_pg.dblink_get_curr_power: ' || SQLERRM (SQLCODE));
 END;

