------------------------------------------------------------------------------------------------------------------------
--Чтение ГН
 PROCEDURE dblink_get_halfhour (an_mid NUMBER, ad_cdatetime OUT common_pg.tt_varchar2, an_er OUT common_pg.tt_number, an_ed OUT common_pg.tt_number,
 an_q1 OUT common_pg.tt_number, an_q3 OUT common_pg.tt_number, an_q2 OUT common_pg.tt_number, an_q4 OUT common_pg.tt_number, an_erm OUT common_pg.tt_number,
 an_edm OUT common_pg.tt_number, an_q1m OUT common_pg.tt_number, an_q3m OUT common_pg.tt_number, an_q2m OUT common_pg.tt_number, an_q4m OUT common_pg.tt_number,
 an_status OUT common_pg.tt_number, an_metertype OUT common_pg.tt_number, av_qm OUT common_pg.tt_varchar2, ad_date DATE
 ) IS
  i   NUMBER DEFAULT 1;
 BEGIN
  FOR lc IN (SELECT   er, ed, q1, q3, q2, q4, erm, edm, q1m, q3m, q2m, q4m, status, TO_CHAR (util_pg.to_unlocaltime (date_time, nsource), 'dd.mm.yyyy hh24:mi') cdt,
                      nmetertype, vqm
                 FROM halfhour
                WHERE mid = an_mid AND date_time > ad_date - 1 / 24 AND util_pg.to_unlocaltime (date_time, nsource) > ad_date AND NOT (nsource BETWEEN 20 AND 49)
             ORDER BY util_pg.to_unlocaltime (date_time, nsource)) LOOP
   an_er (i) := lc.er;
   an_ed (i) := lc.ed;
   an_q1 (i) := lc.q1;
   an_q3 (i) := lc.q3;
   an_q2 (i) := lc.q2;
   an_q4 (i) := lc.q4;
   an_erm (i) := lc.erm;
   an_edm (i) := lc.edm;
   an_q1m (i) := lc.q1m;
   an_q3m (i) := lc.q3m;
   an_q2m (i) := lc.q2m;
   an_q4m (i) := lc.q4m;
   an_status (i) := lc.status;
   ad_cdatetime (i) := lc.cdt;
   an_metertype (i) := lc.nmetertype;
   av_qm (i) := lc.vqm;
   i := i + 1;

   IF i > cn_maxrowcounth THEN
    EXIT;
   END IF;
  END LOOP;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20001, 'comsrvdll_pg.dblink_get_halfhour: ' || SQLERRM (SQLCODE));
 END;

