------------------------------------------------------------------------------------------------------------------------
 --Возвращает тип загружаемого файла
 FUNCTION getfiletype (an_cid NUMBER, at_data common_pg.tt_varchar2)
  RETURN NUMBER IS
  lv_fileext   VARCHAR2 (256);
 BEGIN
  FOR i IN 1 .. at_data.COUNT LOOP
   IF at_data (i) LIKE '%((//_____:%:%:++%' THEN
    IF INSTR (at_data (i), '((//30817:') > 0 THEN
     RETURN cn_30817;
    ELSIF INSTR (at_data (i), '((//30818:') > 0 THEN
     RETURN cn_30818;
    ELSIF INSTR (at_data (i), '((//30917:') > 0 THEN
     RETURN cn_30917;
    ELSIF INSTR (at_data (i), '((//10015:') > 0 THEN
     RETURN cn_10015;
    ELSIF INSTR (at_data (i), '((//30900:') > 0 THEN
     RETURN cn_30900;
    END IF;
   ELSIF INSTR (at_data (i), '((//30902:') > 0 THEN
    RETURN cn_30902;
   ELSIF UPPER (at_data (i)) LIKE '##01010%' THEN
    RETURN cn_1010;
   ELSIF UPPER (at_data (i)) LIKE '< DATE=%' THEN
    RETURN cn_30817des;
   ELSIF UPPER (at_data (i)) LIKE '< REC=POINT;%' THEN
    RETURN cn_30917ses;
   ELSIF UPPER (at_data (i)) LIKE '%EDR PROGRAMM%' THEN
    RETURN cn_elvin;
   ELSIF UPPER (at_data (i)) LIKE 'DATE FROM%' THEN
    RETURN cn_zmd;
   ELSIF at_data (i) LIKE '%;%;__.__.____;%;1;_;%' THEN
    RETURN cn_smartf;
   ELSIF at_data (i) LIKE '%#%#%;__.__.____ __:__;%;0' THEN
    RETURN cn_smarth;
   ELSIF UPPER (at_data (i)) LIKE 'ARGO%' THEN
    RETURN cn_argo;
   ELSIF at_data (i) LIKE '%|__.__.____ __:__:__|%|%|%|%|%|%|%|%|%' THEN
    RETURN cn_xartep;
   END IF;
  END LOOP;

  RETURN 0;
 END;

------------------------------------------------------------------------------------------------------------------------
--Возвращает дату по строке
 FUNCTION getdatabystr (av_dat VARCHAR2)
  RETURN DATE IS
  lv_dat   VARCHAR2 (512) DEFAULT TRIM (av_dat);
 BEGIN
  IF LENGTH (lv_dat) = 8 THEN
   RETURN TO_DATE (lv_dat, 'MMDDYYYY');
  ELSIF LENGTH (lv_dat) = 6 THEN
   RETURN TO_DATE (lv_dat, 'MMDDYY');
  ELSE
   RETURN TO_DATE (TO_CHAR (util_pg.get_datebyshortdate (TO_DATE ('2004' || lv_dat, 'YYYYMMDD')), 'YYYY') || lv_dat, 'YYYYMMDD');
  END IF;

  raise_application_error (-20001, 'comsrvfile_pg.getdatabystr: Формат даты не распознан.');
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE file_chdr (an_e1 IN OUT NUMBER, an_e2 IN OUT NUMBER) IS
  ln_e1   NUMBER;
  ln_e2   NUMBER;
 BEGIN
  ln_e1 := 0;
  ln_e2 := 0;

  IF an_e1 < 0 THEN
   ln_e1 := ABS (an_e1);

   IF an_e2 IS NULL THEN
    an_e1 := NULL;
    an_e2 := 0;
   ELSE
    an_e1 := 0;
   END IF;
  END IF;

  IF an_e2 < 0 THEN
   ln_e2 := ABS (an_e2);

   IF an_e1 IS NULL THEN
    an_e2 := NULL;
    an_e1 := 0;
   ELSE
    an_e2 := 0;
   END IF;
  END IF;

  an_e1 := an_e1 + ln_e2;
  an_e2 := an_e2 + ln_e1;
 END;

------------------------------------------------------------------------------------------------------------------------
--Сохранение первичных данных
 PROCEDURE setprimarydata (an_cid NUMBER, av_filename VARCHAR2, at_data common_pg.tt_varchar2, av_err VARCHAR2) IS
  ld_dat   DATE   DEFAULT SYSDATE;
  ln_tmp   NUMBER;
 BEGIN
  SELECT NVL (MAX (nsort), 0)   --Чтоб загружать в хвост (Если ошибка по PK)
    INTO ln_tmp
    FROM lg_loadprof
   WHERE mid = an_cid AND date_time = ld_dat;

  ln_tmp := ln_tmp + 1;

  INSERT INTO lg_loadprof
              (mid, date_time, nsort, vdata
              )
       VALUES (an_cid, ld_dat, ln_tmp, 'Файл: "' || av_filename || '"'
              );

  IF av_err IS NULL THEN
   ln_tmp := ln_tmp + 1;

   INSERT INTO lg_loadprof
               (mid, date_time, nsort, vdata
               )
        VALUES (an_cid, ld_dat, ln_tmp, 'Состояние: "Загружен"'
               );
  ELSE
   ln_tmp := ln_tmp + 1;

   INSERT INTO lg_loadprof
               (mid, date_time, nsort, vdata
               )
        VALUES (an_cid, ld_dat, ln_tmp, 'Состояние: "Не загружен"'
               );

   ln_tmp := ln_tmp + 1;

   INSERT INTO lg_loadprof
               (mid, date_time, nsort, vdata
               )
        VALUES (an_cid, ld_dat, ln_tmp, 'Ошибка: ' || av_err
               );
  END IF;

  FOR i IN 1 .. at_data.COUNT LOOP
   INSERT INTO lg_loadprof
               (mid, date_time, nsort, vdata
               )
        VALUES (an_cid, ld_dat, ln_tmp + i, at_data (i)
               );
  END LOOP;
 END;

