 --Сохранение ГН
 PROCEDURE inshalfhour (an_mid NUMBER, ad_date DATE, an_er NUMBER, an_ed NUMBER, an_q1 NUMBER, an_q3 NUMBER, an_q2 NUMBER, an_q4 NUMBER) IS
 BEGIN
  das_pg.ins_halfhourtmp (an_mid, ad_date, gn_source, an_er, an_ed, an_q1, an_q3, an_q2, an_q4, NULL, comsrv_pg.cn_maket, NULL);
 END;

------------------------------------------------------------------------------------------------------------------------
-- Общая процедура загрузки файла данных
 PROCEDURE load_file (an_cid NUMBER, av_filename VARCHAR2, at_data common_pg.tt_varchar2, an_auto NUMBER) IS
  ln_type   NUMBER;
  lv_tmp    VARCHAR2 (4000);
 BEGIN
  gn_verifierr:=0;
  ln_type := getfiletype (an_cid, at_data);

  IF ln_type = cn_30817 THEN
   l_30817 (an_cid, prepare_nek (at_data));
  ELSIF ln_type = cn_30818 THEN
   l_30818 (an_cid, prepare_nek (at_data));
  ELSIF ln_type = cn_30917 THEN
   l_30917 (an_cid, prepare_nek (at_data));
  ELSIF ln_type = cn_10015 THEN
   l_10015 (an_cid, prepare_nek (at_data));
  ELSIF ln_type = cn_30900 THEN
   l_30900 (an_cid, av_filename, at_data);
  ELSIF ln_type = cn_30902 THEN
   l_30902 (an_cid, prepare_nek (at_data));
  ELSIF ln_type = cn_elvin THEN
   lp_elvin (an_cid, av_filename, at_data);
  ELSIF ln_type = cn_elvin60 THEN
   lp_elvin60 (an_cid, av_filename, at_data);
  ELSIF ln_type = cn_zmd THEN
   lp_zmd (an_cid, av_filename, at_data);
  ELSIF ln_type = cn_zmd60 THEN
   lp_zmd60 (an_cid, av_filename, at_data);
  ELSIF ln_type = cn_smartf THEN
   lp_smartf (an_cid, av_filename, at_data);
  ELSIF ln_type = cn_smarth THEN
   lp_smarth (an_cid, av_filename, at_data);
  ELSIF ln_type = cn_argo THEN
   lp_argo (an_cid, av_filename, at_data);
  ELSIF ln_type = cn_1010 THEN
   l_1010 (an_cid, at_data);
  ELSIF ln_type = cn_30817des THEN
   l_30817des (an_cid, at_data);
  ELSIF ln_type = cn_30917ses THEN
   l_30917ses (an_cid, at_data);
  ELSE
   raise_application_error (-20001, 'comsrvfile_pg.load_file: Файл не распознан.');
  END IF;

  setprimarydata (an_cid, av_filename, at_data);
  if gn_verifierr=1 THEN
    lv_tmp:='Загрузка произведена с предупреждениями процедуры верификации.';
  ELSE
    lv_tmp:='Загрузка произведена успешно.';
  END IF;
  IF an_auto = 1 THEN
   INSERT INTO journal
               (mid, date_time, state_cod, state_descr
               )
        VALUES (an_cid, SYSDATE, 0, SUBSTR ('Файл "' || av_filename || '": '||lv_tmp, 1, 512)
               );
  ELSE
   admin_pg.fiscal_p (cn_task_code, 1,
                      'Канал: "' || util_pg.node_path_f (an_cid, 'points', 'mid', 'parent') || '". Файл "' || av_filename || '": '||lv_tmp);
  END IF;

  COMMIT;

  IF an_auto <> 1 THEN
   das_pg.checkhalfhour_without_err;
   COMMIT;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   lv_tmp := SQLERRM;
   ROLLBACK;

   IF an_auto = 1 THEN
    INSERT INTO journal
                (mid, date_time, state_cod, state_descr
                )
         VALUES (an_cid, SYSDATE, 1030, SUBSTR ('Файл "' || av_filename || '": ' || lv_tmp, 1, 512)
                );

    COMMIT;
    setprimarydata (an_cid, av_filename, at_data, lv_tmp);
    COMMIT;
   END IF;

   RAISE;
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION prepare_nek (at_data common_pg.tt_varchar2)
  RETURN common_pg.tt_varchar2 IS
  lt_data   common_pg.tt_varchar2;
  lt_ret    common_pg.tt_varchar2;
  lb_find   BOOLEAN               DEFAULT FALSE;
  j         NUMBER                DEFAULT 0;
 BEGIN
  IF at_data.COUNT = 0 THEN
   raise_application_error (-20001, 'Файл не содержит данных.');
  END IF;

  FOR i IN 1 .. at_data.COUNT LOOP
   IF NOT lb_find AND at_data (i) LIKE '%((//_____:%:%:++%' THEN
    lb_find := TRUE;
    j := j + 1;
    lt_data (j) := SUBSTR (at_data (i), INSTR (at_data (i), '((//'));
   ELSIF lb_find THEN
    j := j + 1;

    IF INSTR (at_data (i), '==))') > 0 THEN
     IF TRIM (at_data (i)) = '==))' THEN
      lt_data (j) := at_data (i);
     ELSE
      lt_data (j) := SUBSTR (at_data (i), 1, INSTR (at_data (i), '==))') - 1);
      lt_data (j + 1) := '==))';
     END IF;

     EXIT;
    ELSE
     lt_data (j) := at_data (i);
    END IF;
   END IF;
  END LOOP;

  IF NOT lb_find THEN
   raise_application_error (-20001, 'Отсутствует признак начала данных.');
  END IF;

  --Копируем результат, убирая пустые строки
  j := 0;

  FOR i IN 1 .. lt_data.COUNT LOOP
   IF TRIM (lt_data (i)) IS NOT NULL THEN
    j := j + 1;
    lt_ret (j) := TRIM (lt_data (i));
   END IF;
  END LOOP;

  IF lt_ret (lt_ret.COUNT) <> '==))' THEN
   raise_application_error (-20001, 'Отсутствует признак конца данных.');
  END IF;

  RETURN lt_ret;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20001, 'comsrvfile_pg.prepare_nek: ' || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE l_30817 (an_cid NUMBER, at_data common_pg.tt_varchar2) IS
  ln_str         NUMBER              DEFAULT 0;
  ln_col         NUMBER              DEFAULT 0;
  lv_separator   VARCHAR2 (8)        DEFAULT ':';
  ln_rn          NUMBER              DEFAULT 3;
  ln_count       NUMBER              DEFAULT at_data.COUNT - 1;
  lv_ret         VARCHAR2 (4000);
  lv_tmp         VARCHAR2 (4000);
  ln_mid         NUMBER;
  ln_tmp         NUMBER;
  ld_date        DATE;
  ld_max         DATE;
  ln_e           NUMBER;
  lt_e           common_pg.tt_number;
  ln_factcnt     NUMBER;
  ln_shift       NUMBER;
  cn_cnt         NUMBER;
  ln_type        NUMBER;
  ln_tmptype     NUMBER;
  ln_block       NUMBER;
  lv_str         VARCHAR (1024);
  ln_sum         NUMBER;
 BEGIN
  --Проверяем начало
  ln_str := 1;
  ln_col := 1;
  lv_ret := at_data (1);
  ld_date := getdatabystr (util_pg.get_param (lv_ret, 2, lv_separator));

  --Пробегаемся по файлу и выписываем все ид точек
  DELETE FROM textreport;

  FOR i IN 2 .. ln_count LOOP
   ln_str := i;
   ln_col := 1;
   lv_ret := at_data (i);
   lv_tmp := TRIM (util_pg.get_param (lv_ret, 1, lv_separator));

   IF SUBSTR (lv_tmp, 1, 1) <> '(' OR SUBSTR (lv_tmp, LENGTH (lv_tmp)) <> ')' THEN
    raise_application_error (-20001, 'Отсутствует признак идентификатора точки.');
   END IF;

   --Убираем скобки
   lv_tmp := UPPER (SUBSTR (lv_tmp, 2, LENGTH (lv_tmp) - 2));

   IF lv_tmp IS NULL OR INSTR (lv_tmp, ';') > 0 THEN
    raise_application_error (-20001, 'Код точки не указан или указан не верно.');
   END IF;

   --Ищем точку
   SELECT MAX (mid), COUNT (*), MAX (nblock)
     INTO ln_mid, ln_tmp, ln_block
     FROM feeders
    WHERE mid IN (SELECT mid
                    FROM chanpoint
                   WHERE cid = an_cid) AND util_pg.get_pos_str (TRIM (UPPER (vimportcode)), lv_tmp) BETWEEN 1 AND 4;

   IF ln_tmp > 1 THEN
    raise_application_error (-20001, 'Точка определена не однозначно.');
   ELSIF ln_tmp = 1 AND ln_block = 0 THEN
    INSERT INTO textreport
                (norder
                )
         VALUES (ln_mid
                );
   END IF;
  END LOOP;

  FOR lc IN (SELECT DISTINCT norder mid
                        FROM textreport) LOOP
   --В остальных макетах мы это делаем вначале, а здесь мы этим манипулируем на каждой точке т.к из часовок делаем получасовки
   cn_cnt := 24;
   ln_factcnt := util_pg.get_count_dt (ld_date, 1 / cn_cnt);
   --Обнулили макс дату
   ld_max := ld_date - 1;

   --Очистили
   FOR i IN 1 .. ln_factcnt * 4 LOOP
    lt_e (i) := NULL;
   END LOOP;

   --Поискали нужные строки
   FOR i IN 2 .. ln_count LOOP
    ln_str := i;
    ln_col := 1;
    lv_ret := TRIM (at_data (i));
    lv_tmp := TRIM (util_pg.get_param (lv_ret, 1, lv_separator));
    --Проверяем что это нужная строка
    lv_tmp := UPPER (SUBSTR (lv_tmp, 2, LENGTH (lv_tmp) - 2));

    SELECT COUNT (*), MAX (util_pg.get_pos_str (TRIM (UPPER (vimportcode)), lv_tmp))
      INTO ln_tmp, ln_type
      FROM feeders
     WHERE mid = lc.mid AND util_pg.get_pos_str (TRIM (UPPER (vimportcode)), lv_tmp) BETWEEN 1 AND 4;

    IF ln_tmp = 1 THEN
     ln_sum := 0;
     FOR j IN 1 .. ln_factcnt LOOP
      ln_col := 2 + j;
      ln_e := REPLACE (util_pg.get_param (lv_ret, 2 + j, lv_separator), ',', '.') * 1000;   --*1000 и меняем запятую на точку
      ln_sum := ln_sum + NVL(ln_e,0); -- KAG 10.11.2008
      IF ln_e < 0 THEN   --Если <0 то инвертируем.
       IF ln_type IN (1, 3) THEN
        ln_tmptype := ln_type + 1;
       ELSE
        ln_tmptype := ln_type - 1;
       END IF;

       ln_e := -ln_e;
      ELSE
       ln_tmptype := ln_type;
      END IF;

      lt_e (ln_factcnt * (ln_tmptype - 1) + j) := ln_e;

      IF ln_e IS NOT NULL THEN
       ld_max := ld_date + j / cn_cnt;
      END IF;
     END LOOP;
     IF ln_sum <> NVL(REPLACE(util_pg.get_param (lv_ret, 2, lv_separator), ',', '.') * 1000,0) THEN -- KAG 10.11.2008 start
        gn_verifierr := 1;
     END IF; -- KAG 10.11.2008 end
    END IF;
   END LOOP;

   ln_str := 1;
   ln_col := 1;

   --А теперь 24 часа раскинем на 48 получасовок (или 25 в 50)
   FOR i IN REVERSE 1 .. 4 * ln_factcnt LOOP
    lt_e (2 * i) := TRUNC (lt_e (i) / 2, ln_rn);
    lt_e (2 * i - 1) := lt_e (i) - lt_e (2 * i);
   END LOOP;

   --А теперь у нас всего больше в 2 раза стало
   cn_cnt := 2 * cn_cnt;
   ln_factcnt := util_pg.get_count_dt (ld_date, 1 / cn_cnt);

   -- И записываем в БД
   FOR j IN 1 .. ln_factcnt LOOP
    --Если есть цифры
    IF lt_e (j) IS NOT NULL OR lt_e (1 * ln_factcnt + j) IS NOT NULL OR lt_e (2 * ln_factcnt + j) IS NOT NULL OR lt_e (3 * ln_factcnt + j) IS NOT NULL THEN
     IF ln_factcnt > cn_cnt AND j > (cn_cnt / 24) * (util_pg.switch_f + 1) AND j <= cn_cnt THEN   --больше времени сдвига добавяем час
      ln_shift := 1 / 24;
     ELSIF j > cn_cnt THEN
      ln_shift := -1 + (util_pg.switch_f + 1) / 24;
     ELSE
      ln_shift := 0;
     END IF;

     das_pg.insert_hf_in_profile (lc.mid, util_pg.to_unlocaltime_if_new (ld_date) + j / cn_cnt + ln_shift, 24 * 60 / cn_cnt, lt_e (j), lt_e (1 * ln_factcnt + j),
                                  lt_e (2 * ln_factcnt + j), NULL, lt_e (3 * ln_factcnt + j), NULL, ln_rn);
     inshalfhour (lc.mid, util_pg.to_unlocaltime_if_new (ld_date) + j / cn_cnt + ln_shift, lt_e (j), lt_e (1 * ln_factcnt + j), lt_e (2 * ln_factcnt + j),
                  lt_e (3 * ln_factcnt + j));
    END IF;
   END LOOP;

   IF util_pg.get_customer_id <> 1 AND ld_max > ld_date THEN
    editfeeders_pg.ins_last_save (lc.mid);

    UPDATE last_save
       SET halfhour = ld_max,
           state_date = SYSDATE,
           state_cod = 0,
           clock = 0
     WHERE mid = lc.mid;
   END IF;
  END LOOP;

  UPDATE last_save
     SET halfhour = GREATEST (ld_date + 1, NVL (halfhour, ld_date + 1))
   WHERE mid = an_cid;

  DELETE FROM textreport;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001, 'comsrvfile_pg.l_30817: ' || 'Ошибка загрузки данных (стр. ' || ln_str || ', столб. ' || ln_col || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE l_30817des (an_cid NUMBER, at_data common_pg.tt_varchar2) IS   -- added by KAG 23.08.2008
  ln_str         NUMBER              DEFAULT 0;
  ln_col         NUMBER              DEFAULT 0;
  lv_separator   VARCHAR2 (8)        DEFAULT ';';
  ln_rn          NUMBER              DEFAULT 0;
  ln_count       NUMBER              DEFAULT at_data.COUNT - 1;
  ln_start       NUMBER              DEFAULT 1;
  ln_end         NUMBER              DEFAULT 1;
  lv_ret         VARCHAR2 (4000);
  lv_tmp         VARCHAR2 (4000);
  ln_mid         NUMBER;
  ln_tmp         NUMBER;
  ld_date        DATE;
  ld_max         DATE;
  ln_e           NUMBER;
  lt_e           common_pg.tt_number;
  ln_factcnt     NUMBER;
  ln_shift       NUMBER;
  cn_cnt         NUMBER;
  ln_type        NUMBER;
  ln_tmptype     NUMBER;
  ln_block       NUMBER;
  lv_str         VARCHAR (1024);
  ln_cur         NUMBER;
  ln_koeff       NUMBER              DEFAULT 1;
 BEGIN
  --Ищем начало и конец файла
  FOR i IN 1 .. at_data.COUNT LOOP
   IF (TRIM (at_data (i)) LIKE '< DATE=%') THEN
    ln_start := i;
   END IF;

   IF (TRIM (at_data (i)) LIKE '%; >%') THEN   -- пока допускаем символы после '%; >'
    ln_end := i;
   END IF;
  END LOOP;

  IF (ln_start < 2) THEN
   raise_application_error (-20001, 'Не найдено начало файла.');
  END IF;

  IF (ln_end <= ln_start) THEN
   raise_application_error (-20001, 'Не найден конец файла.');
  END IF;

  --Проверяем начало
  ln_str := ln_start;
  ln_col := ln_start;
  ld_date := TO_DATE (REPLACE (util_pg.get_param (at_data (ln_start), 1, lv_separator), '< DATE='), 'DDMMYY');

  IF at_data (ln_start) LIKE '%MWT.H%' THEN
   ln_koeff := 1000;   -- если в МВт.ч то будем множить на 1000
  END IF;

  --Пробегаемся по файлу и выписываем все ид точек
  DELETE FROM textreport;

  FOR i IN ln_start + 1 .. ln_end LOOP
   ln_str := i;
   ln_col := 1;
   lv_ret := at_data (i);

   IF (lv_ret LIKE '< ID=%') THEN
    lv_ret := TRIM (REPLACE (util_pg.get_param (lv_ret, 1, lv_separator), '< ID='));   --получение кода точки

    IF lv_ret IS NULL THEN
     raise_application_error (-20001, 'Код точки не указан или указан не верно.');
    END IF;

    --Ищем точку
    SELECT MAX (mid), COUNT (*), MAX (nblock)
      INTO ln_mid, ln_tmp, ln_block
      FROM feeders
     WHERE mid IN (SELECT mid
                     FROM chanpoint
                    WHERE cid = an_cid) AND util_pg.get_pos_str (TRIM (UPPER (vimportcode)), lv_ret) BETWEEN 1 AND 4;

    IF ln_tmp > 1 THEN
     raise_application_error (-20001, 'Точка определена не однозначно.');
    ELSIF ln_tmp = 1 AND ln_block = 0 THEN
     INSERT INTO textreport
                 (norder)
          VALUES (ln_mid);
    END IF;
   END IF;
  END LOOP;

  FOR lc IN (SELECT DISTINCT norder mid
                        FROM textreport) LOOP
   --В остальных макетах мы это делаем вначале, а здесь мы этим манипулируем на каждой точке т.к из часовок делаем получасовки
   cn_cnt := 24;
   ln_factcnt := util_pg.get_count_dt (ld_date, 1 / cn_cnt);
   --Обнулили макс дату
   ld_max := ld_date - 1;

   --Очистили
   FOR i IN 1 .. ln_factcnt * 4 LOOP   -- 4 - кол-во показаний (А+,A-,R+,R-)
    lt_e (i) := NULL;
   END LOOP;

   --Поискали нужные строки
   ln_cur := ln_start;

   FOR i IN ln_start + 1 .. ln_end LOOP
    IF (ln_cur < i) THEN   --пропускаем уже рассмотренные при склевании строки
     ln_str := i;
     ln_col := 1;
     ln_cur := i;   -- номер текущей рассматриваемой строки
     lv_ret := TRIM (at_data (i));
     lv_tmp := lv_ret;

     -- ищем и клеем окончание строки при необходимости
     WHILE NOT (lv_tmp LIKE '< ID=%; >') LOOP
      ln_cur := ln_cur + 1;

      IF (ln_cur) > ln_end OR TRIM (at_data (ln_cur)) LIKE '< ID=%' THEN   --не нашли конец строки (конец файла или началась следующая точка)
       raise_application_error (-20001, 'Не найден конец ' || i || ' строки.');
      END IF;

      IF util_pg.get_param (TRIM (at_data (ln_cur)), 2, '; >') IS NOT NULL THEN   -- теперь ругаемся на символы после '%; >'
       raise_application_error (-20001, 'Неразрешенные символы в конце ' || i || ' строки: ' || util_pg.get_param (TRIM (at_data (ln_cur)), 2, '; >'));
      END IF;

      lv_tmp := lv_tmp || TRIM (at_data (ln_cur));   -- приклеиваем следующую строку
     END LOOP;

     lv_tmp := UPPER (TRIM (lv_tmp));   --здесь получили готовую целую строку для точки
     --Проверяем, что это нужная строка
     lv_ret := TRIM (REPLACE (util_pg.get_param (lv_tmp, 1, lv_separator), '< ID='));   --получение кода точки

     SELECT COUNT (*), MAX (util_pg.get_pos_str (TRIM (UPPER (vimportcode)), lv_ret))
       INTO ln_tmp, ln_type
       FROM feeders
      WHERE mid = lc.mid AND util_pg.get_pos_str (TRIM (UPPER (vimportcode)), lv_ret) BETWEEN 1 AND 4;

     IF ln_tmp = 1 THEN
      lv_ret := util_pg.get_param (util_pg.get_param (lv_tmp, 2, lv_separator), 2, ':');   -- получение часовок
      ln_col := INSTR (lv_tmp, ':');

      FOR j IN 1 .. ln_factcnt LOOP
       ln_col := ln_col + 1;
       ln_e := util_pg.get_param (lv_ret, j, ',') * ln_koeff;   -- переводим в киловатты при необходимости

       IF ln_e < 0 THEN   --Если <0 то инвертируем.
        IF ln_type IN (1, 3) THEN
         ln_tmptype := ln_type + 1;
        ELSE
         ln_tmptype := ln_type - 1;
        END IF;

        ln_e := -ln_e;
       ELSE
        ln_tmptype := ln_type;
       END IF;

       lt_e (ln_factcnt * (ln_tmptype - 1) + j) := ln_e;   -- заполняем массив значениями

       IF ln_e IS NOT NULL THEN
        ld_max := ld_date + j / cn_cnt;
       END IF;
      END LOOP;
     END IF;
    END IF;
   END LOOP;

   ln_str := 1;
   ln_col := 1;

   --А теперь 24 часа раскинем на 48 получасовок (или 25 в 50)
   FOR i IN REVERSE 1 .. 4 * ln_factcnt LOOP
    lt_e (2 * i) := TRUNC (lt_e (i) / 2, ln_rn);
    lt_e (2 * i - 1) := lt_e (i) - lt_e (2 * i);
   END LOOP;

   --А теперь у нас всего больше в 2 раза стало
   cn_cnt := 2 * cn_cnt;
   ln_factcnt := util_pg.get_count_dt (ld_date, 1 / cn_cnt);

   -- И записываем в БД
   FOR j IN 1 .. ln_factcnt LOOP
    --Если есть цифры
    IF lt_e (j) IS NOT NULL OR lt_e (1 * ln_factcnt + j) IS NOT NULL OR lt_e (2 * ln_factcnt + j) IS NOT NULL OR lt_e (3 * ln_factcnt + j) IS NOT NULL THEN
     IF ln_factcnt > cn_cnt AND j > (cn_cnt / 24) * (util_pg.switch_f + 1) AND j <= cn_cnt THEN   --больше времени сдвига добавяем час
      ln_shift := 1 / 24;
     ELSIF j > cn_cnt THEN
      ln_shift := -1 + (util_pg.switch_f + 1) / 24;
     ELSE
      ln_shift := 0;
     END IF;

     das_pg.insert_hf_in_profile (lc.mid, util_pg.to_unlocaltime_if_new (ld_date) + j / cn_cnt + ln_shift, 24 * 60 / cn_cnt, lt_e (j), lt_e (1 * ln_factcnt + j),
                                  lt_e (2 * ln_factcnt + j), NULL, lt_e (3 * ln_factcnt + j), NULL, ln_rn);
     inshalfhour (lc.mid, util_pg.to_unlocaltime_if_new (ld_date) + j / cn_cnt + ln_shift, lt_e (j), lt_e (1 * ln_factcnt + j), lt_e (2 * ln_factcnt + j),
                  lt_e (3 * ln_factcnt + j));
    END IF;
   END LOOP;

   IF util_pg.get_customer_id <> 1 AND ld_max > ld_date THEN
    editfeeders_pg.ins_last_save (lc.mid);

    UPDATE last_save
       SET halfhour = ld_max,
           state_date = SYSDATE,
           state_cod = 0,
           clock = 0
     WHERE mid = lc.mid;
   END IF;
  END LOOP;

  UPDATE last_save
     SET halfhour = GREATEST (ld_date + 1, NVL (halfhour, ld_date + 1))
   WHERE mid = an_cid;

  DELETE FROM textreport;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001,
                            'comsrvfile_pg.l_30817des: ' || 'Ошибка загрузки данных (стр. ' || ln_str || ', столб. ' || ln_col || CHR (10) || SQLERRM (SQLCODE));
 END;

