 PROCEDURE l_30917ses (an_cid NUMBER, at_data common_pg.tt_varchar2) IS   -- added by KAG 23.08.2008
  cn_cnt   CONSTANT NUMBER                DEFAULT 48;
  ln_str            NUMBER                DEFAULT 0;
  ln_col            NUMBER                DEFAULT 0;
  lv_separator      VARCHAR2 (8)          DEFAULT ';';
  ln_count          NUMBER                DEFAULT at_data.COUNT - 1;
  ln_start          NUMBER                DEFAULT 1;
  ln_end            NUMBER                DEFAULT 1;
  ln_rn             NUMBER                DEFAULT 3;
  lv_ret            VARCHAR2 (4000);
  lv_tmp            VARCHAR2 (4000);
  lv_tmp2           VARCHAR2 (4000);
  lv_point          VARCHAR2 (4000);
  ln_mid            NUMBER;
  ln_tmp            NUMBER;
  ln_cnt            NUMBER                DEFAULT 0;
  ld_date           DATE;
  ld_max            DATE;
  lt_e              common_pg.tt_number;
  ln_type           NUMBER;
  ln_factcnt        NUMBER;
  ln_shift          NUMBER;
  ln_block          NUMBER;
  ln_reverse        NUMBER;
  ln_koeff          NUMBER                DEFAULT 1;
  lt_m              common_pg.tt_varchar2;
 BEGIN
  --Ищем начало и конец файла
  FOR i IN 1 .. at_data.COUNT LOOP
   IF (TRIM (at_data (i)) LIKE '< REC=POINT;%') THEN
    ln_start := i;
    EXIT;
   END IF;
  END LOOP;

  FOR i IN REVERSE 1 .. at_data.COUNT LOOP
   IF (TRIM (at_data (i)) LIKE '%; >%') THEN   -- пока допускаем символы после '; >'
    ln_end := i;
    EXIT;
   END IF;
  END LOOP;

  IF (ln_start < 2) THEN
   raise_application_error (-20001, 'Некорректное начало файла.');
  END IF;

  IF (ln_end <= ln_start) THEN
   raise_application_error (-20001, 'Не найден конец файла.');
  END IF;

  --Пробегаемся по файлу и выписываем все ид точек
  DELETE FROM textreport;

  FOR i IN ln_start .. ln_end LOOP
   ln_str := i;
   ln_col := 1;
   lv_ret := at_data (i);

   IF lv_ret LIKE '< REC=POINT;%' THEN
    lv_tmp := TRIM (util_pg.get_param (lv_ret, 2, lv_separator));

    IF SUBSTR (lv_tmp, 1, 3) <> 'ID=' THEN
     raise_application_error (-20001, 'Отсутствует признак идентификатора точки.');
    END IF;

    --получаем код точки
    lv_point := SUBSTR (lv_tmp, 4);

    IF TRIM (lv_point) IS NULL THEN
     raise_application_error (-20001, 'Код точки не указан.');
    END IF;

    --Ищем точку
    SELECT MAX (mid), COUNT (*), MAX (nblock)
      INTO ln_mid, ln_cnt, ln_block
      FROM feeders
     WHERE mid IN (SELECT mid
                     FROM chanpoint
                    WHERE cid = an_cid) AND util_pg.get_pos_str (TRIM (UPPER (vimportcode)), lv_point) BETWEEN 1 AND 4;

    IF ln_cnt > 1 THEN
     raise_application_error (-20001, 'Точка определена неоднозначно.');
    ELSIF ln_cnt = 1 AND ln_block = 0 THEN
     INSERT INTO textreport
                 (norder
                 )
          VALUES (ln_mid
                 );
    END IF;
   END IF;
  END LOOP;

  FOR lc IN (SELECT DISTINCT norder mid
                        FROM textreport) LOOP
   --Поискали нужные строки
   FOR i IN ln_start .. ln_end LOOP
    ln_str := i;
    ln_col := 1;
    lv_ret := TRIM (at_data (i));

    IF lv_ret LIKE '< REC=POINT;%' THEN
     --получаем код точки
     lv_tmp := TRIM (util_pg.get_param (lv_ret, 2, lv_separator));
     lv_point := SUBSTR (lv_tmp, 4);
     --Проверяем, что это нужная строка
     ln_cnt := 0;

     SELECT COUNT (*), MAX (util_pg.get_pos_str (TRIM (UPPER (vimportcode)), lv_point))
       INTO ln_cnt, ln_type
       FROM feeders
      WHERE mid = lc.mid AND util_pg.get_pos_str (TRIM (UPPER (vimportcode)), lv_point) BETWEEN 1 AND 4;
    ELSIF lv_ret LIKE '< REC=DAY;%' THEN
     IF ln_cnt = 1 THEN
      ld_date := TO_DATE (REPLACE (TRIM (util_pg.get_param (lv_ret, 2, lv_separator)), 'DATE='), 'YYMMDD');
      ld_max := ld_date - 1;   --Обнулили макс дату
      ln_factcnt := util_pg.get_count_dt (ld_date, 1 / cn_cnt);

      --Очистили
      FOR i IN 1 .. ln_factcnt * 4 LOOP
       lt_e (i) := NULL;
       lt_m (i) := NULL;   -- статусы передаваемых значений данных
      END LOOP;

      lv_tmp := TRIM (util_pg.get_param (lv_ret, 3, lv_separator));

      IF lv_tmp LIKE 'FORMAT=MWT' THEN
       ln_koeff := 1000;   -- если в МВт.ч то будем множить на 1000
      ELSE
       ln_koeff := 1;
      END IF;

      lv_tmp := TRIM (REPLACE (util_pg.get_param (lv_ret, 4, lv_separator), 'P48='));   -- получение данных
      lv_tmp2 := TRIM (REPLACE (util_pg.get_param (lv_ret, 5, lv_separator), 'ST48='));   -- получений меток данных
      ln_col := INSTR (lv_ret, '=', 1, 4);

      FOR j IN 1 .. ln_factcnt LOOP   -- чтение данных
       lt_e (ln_factcnt * (ln_type - 1) + j) := util_pg.get_param (lv_tmp, j, ',') * ln_koeff;   -- переводим в кВт

       IF lt_e (ln_factcnt * (ln_type - 1) + j) IS NOT NULL THEN
        ld_max := ld_date + j / cn_cnt;
       END IF;

       ln_col := ln_col + NVL (LENGTH (lt_e (ln_factcnt * (ln_type - 1) + j)), 0) + 1;   -- +1 - длина запятой-разделителя
      END LOOP;

      ln_col := INSTR (lv_ret, '=', 1, 5);

      FOR j IN 1 .. ln_factcnt LOOP   -- чтение меток данных
       lt_m (ln_factcnt * (ln_type - 1) + j) := util_pg.get_param (lv_tmp2, j, ',');
       ln_col := ln_col + NVL (LENGTH (lt_m (ln_factcnt * (ln_type - 1) + j)), 0) + 1;   -- +1 - длина запятой-разделителя
      END LOOP;

      SELECT NVL (MAX (ed_position), 0)
        INTO ln_reverse
        FROM feeders
       WHERE mid = lc.mid;

      FOR j IN 1 .. ln_factcnt LOOP
       --Если есть цифры
       IF lt_e (j) IS NOT NULL OR lt_e (1 * ln_factcnt + j) IS NOT NULL OR lt_e (2 * ln_factcnt + j) IS NOT NULL OR lt_e (3 * ln_factcnt + j) IS NOT NULL THEN
        IF ln_factcnt > cn_cnt AND j > (cn_cnt / 24) * (util_pg.switch_f + 1) AND j <= cn_cnt THEN   --больше времени сдвига добавяем час
         ln_shift := 1 / 24;
        ELSIF j > cn_cnt THEN
         ln_shift := -1 + (util_pg.switch_f + 1) / 24;
        ELSE
         ln_shift := 0;
        END IF;

        IF util_pg.get_customer_id = 1 AND ln_reverse > 0 THEN
         util_pg.chdr (lt_e (j), lt_e (1 * ln_factcnt + j), lt_e (2 * ln_factcnt + j), lt_e (3 * ln_factcnt + j));
        END IF;

        das_pg.insert_hf_in_profile (lc.mid, util_pg.to_unlocaltime_if_new (ld_date) + j / cn_cnt + ln_shift, 24 * 60 / cn_cnt, lt_e (j), lt_e (1 * ln_factcnt + j),
                                     lt_e (2 * ln_factcnt + j), NULL, lt_e (3 * ln_factcnt + j), NULL, ln_rn);
        inshalfhour (lc.mid, util_pg.to_unlocaltime_if_new (ld_date) + j / cn_cnt + ln_shift, lt_e (j), lt_e (1 * ln_factcnt + j), lt_e (2 * ln_factcnt + j),
                     lt_e (3 * ln_factcnt + j));
       END IF;
      END LOOP;

      IF util_pg.get_customer_id <> 1 AND ld_max > ld_date THEN
       editfeeders_pg.ins_last_save (lc.mid);

       UPDATE last_save
          SET halfhour = ld_max,
              state_date = SYSDATE,
              state_cod = 0,
              clock = 0
        WHERE mid = lc.mid;
      END IF;
     END IF;
    END IF;
   END LOOP;
  END LOOP;

  UPDATE last_save
     SET halfhour = GREATEST (ld_date + 1, NVL (halfhour, ld_date + 1))
   WHERE mid = an_cid;

  DELETE FROM textreport;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001,
                            'comsrvfile_pg.l_30917ses: ' || 'Ошибка загрузки данных (стр. ' || ln_str || ', столб. ' || ln_col || CHR (10) || SQLERRM (SQLCODE));
 END;

