 PROCEDURE l_30818 (an_cid NUMBER, at_data common_pg.tt_varchar2) IS
  ln_str         NUMBER              DEFAULT 0;
  ln_col         NUMBER              DEFAULT 0;
  lv_separator   VARCHAR2 (8)        DEFAULT ':';
  ln_count       NUMBER              DEFAULT at_data.COUNT - 1;
  lv_ret         VARCHAR2 (4000);
  lv_tmp         VARCHAR2 (4000);
  ln_mid         NUMBER;
  ln_tmp         NUMBER;
  ld_date        DATE;
  ld_tmp         DATE;
  ld_max         DATE;
  lt_e           common_pg.tt_number;
  ln_type        NUMBER;
  lv_mtrsn       VARCHAR2 (4000);
  ln_block       NUMBER;
  ln_reverse     NUMBER;
 BEGIN
  --Проверяем начало
  ln_str := 1;
  ln_col := 1;
  lv_ret := at_data (1);
  ld_date := getdatabystr (util_pg.get_param (lv_ret, 2, lv_separator));

  --Пробегаемся по файлу и выписываем все ид точек
  DELETE FROM textreport;

  FOR i IN 2 .. ln_count LOOP
   ln_str := i;
   ln_col := 1;
   lv_ret := at_data (i);
   lv_tmp := TRIM (util_pg.get_param (lv_ret, 1, lv_separator));

   IF SUBSTR (lv_tmp, 1, 1) <> '(' OR SUBSTR (lv_tmp, LENGTH (lv_tmp)) <> ')' THEN
    raise_application_error (-20001, 'Отсутствует признак идентификатора точки.');
   END IF;

   --Убираем скобки
   ln_tmp := SUBSTR (lv_tmp, 2, LENGTH (lv_tmp) - 3);

   IF NVL (SUBSTR (lv_tmp, LENGTH (lv_tmp) - 1, 1), ' ') NOT IN ('1', '2', '3', '4', '5', '6') THEN
    raise_application_error (-20001, 'Номер параметра учета не распознан.');
   END IF;

   --Ищем точку
   SELECT MAX (mid), COUNT (*), MAX (nblock)
     INTO ln_mid, ln_tmp, ln_block
     FROM feeders
    WHERE mid IN (SELECT mid
                    FROM chanpoint
                   WHERE cid = an_cid) AND TRIM (UPPER (vimportcode)) = TO_CHAR (ln_tmp);

   IF ln_tmp > 1 THEN
    raise_application_error (-20001, 'Точка определена не однозначно.');
   ELSIF ln_tmp = 1 AND ln_block = 0 THEN
    INSERT INTO textreport
                (norder
                )
         VALUES (ln_mid
                );
   END IF;
  END LOOP;

  FOR lc IN (SELECT DISTINCT norder mid
                        FROM textreport) LOOP
   --Обнулили макс дату
   ld_max := ld_date - 1;

   --Очистили
   FOR i IN 1 .. 6 * 5 LOOP
    lt_e (i) := NULL;
   END LOOP;

   --Поискали нужные строки
   FOR i IN 2 .. ln_count LOOP
    ln_str := i;
    ln_col := 1;
    lv_ret := TRIM (at_data (i));
    lv_tmp := TRIM (util_pg.get_param (lv_ret, 1, lv_separator));
    --Проверяем что єто нужная строка
    ln_tmp := SUBSTR (lv_tmp, 2, LENGTH (lv_tmp) - 3);

    SELECT COUNT (*)
      INTO ln_tmp
      FROM DUAL
     WHERE EXISTS (SELECT *
                     FROM feeders
                    WHERE TRIM (UPPER (vimportcode)) = TO_CHAR (ln_tmp) AND mid = lc.mid);

    IF ln_tmp = 1 THEN
     ln_type := SUBSTR (lv_tmp, LENGTH (lv_tmp) - 1, 1);

     FOR j IN 1 .. 5 LOOP
      ln_col := 1 + j;
      lt_e (5 * (ln_type - 1) + j) := REPLACE (util_pg.get_param (lv_ret, 1 + j, lv_separator), ',', '.');   -- и меняем запятую на точку

      IF lt_e (5 * (ln_type - 1) + j) IS NOT NULL THEN
       ld_max := ld_date + 1;
      END IF;
     END LOOP;
    END IF;
   END LOOP;

   ln_str := 1;
   ln_col := 1;

   IF ld_max > ld_date THEN
    SELECT MAX (mtrsn)
      INTO lv_mtrsn
      FROM meters
     WHERE mid = lc.mid AND entype = 7;

    IF util_pg.get_customer_id = 1 THEN
     SELECT NVL (MAX (ed_position), 0)
       INTO ln_reverse
       FROM feeders
      WHERE mid = lc.mid;

     IF ln_reverse = 0 THEN
      comsrv_pg.set_bill_meter (lc.mid, lt_e (6), lt_e (1), lt_e (21), lt_e (11), lt_e (26), lt_e (16), lt_e (7), lt_e (2), lt_e (22), lt_e (12), lt_e (27),
                                lt_e (17), lt_e (8), lt_e (3), lt_e (23), lt_e (13), lt_e (28), lt_e (18), lt_e (9), lt_e (4), lt_e (24), lt_e (14), lt_e (29),
                                lt_e (19), lt_e (10), lt_e (5), lt_e (25), lt_e (15), lt_e (30), lt_e (20), lv_mtrsn, NULL, ld_max);
     ELSE
      comsrv_pg.set_bill_meter (lc.mid, lt_e (1), lt_e (6), lt_e (11), lt_e (21), lt_e (16), lt_e (26), lt_e (2), lt_e (7), lt_e (12), lt_e (22), lt_e (17),
                                lt_e (27), lt_e (3), lt_e (8), lt_e (13), lt_e (23), lt_e (18), lt_e (28), lt_e (4), lt_e (9), lt_e (14), lt_e (24), lt_e (19),
                                lt_e (29), lt_e (5), lt_e (10), lt_e (15), lt_e (25), lt_e (20), lt_e (30), lv_mtrsn, NULL, ld_max);
     END IF;
    ELSE   --Для всех остальных
     comsrv_pg.set_bill_meter (lc.mid, lt_e (1), lt_e (6), lt_e (11), lt_e (21), lt_e (16), lt_e (26), lt_e (2), lt_e (7), lt_e (12), lt_e (22), lt_e (17),
                               lt_e (27), lt_e (3), lt_e (8), lt_e (13), lt_e (23), lt_e (18), lt_e (28), lt_e (4), lt_e (9), lt_e (14), lt_e (24), lt_e (19),
                               lt_e (29), lt_e (5), lt_e (10), lt_e (15), lt_e (25), lt_e (20), lt_e (30), lv_mtrsn, NULL, ld_max);
    END IF;

    ld_tmp := indic_pg.recalcdiff (lc.mid, ld_max, 5);

    IF ld_max = TRUNC (ld_max, 'MONTH') THEN
     IF ln_reverse = 0 OR util_pg.get_customer_id <> 1 THEN
      comsrv_pg.set_months_meter (lc.mid, lt_e (1), lt_e (6), lt_e (11), lt_e (21), lt_e (16), lt_e (26), lt_e (2), lt_e (7), lt_e (12), lt_e (22), lt_e (17),
                                  lt_e (27), lt_e (3), lt_e (8), lt_e (13), lt_e (23), lt_e (18), lt_e (28), lt_e (4), lt_e (9), lt_e (14), lt_e (24), lt_e (19),
                                  lt_e (29), lt_e (5), lt_e (10), lt_e (15), lt_e (25), lt_e (20), lt_e (30), lv_mtrsn, NULL, ld_max);
     ELSE
      comsrv_pg.set_months_meter (lc.mid, lt_e (6), lt_e (1), lt_e (21), lt_e (11), lt_e (26), lt_e (16), lt_e (7), lt_e (2), lt_e (22), lt_e (12), lt_e (27),
                                  lt_e (17), lt_e (8), lt_e (3), lt_e (23), lt_e (13), lt_e (28), lt_e (18), lt_e (9), lt_e (4), lt_e (24), lt_e (14), lt_e (29),
                                  lt_e (19), lt_e (10), lt_e (5), lt_e (25), lt_e (15), lt_e (30), lt_e (20), lv_mtrsn, NULL, ld_max);
     END IF;

     ld_tmp := indic_pg.recalcdiff (lc.mid, ld_max, 6);
    END IF;

    editfeeders_pg.ins_last_save (lc.mid);

    IF util_pg.get_customer_id <> 1 THEN
     UPDATE last_save
        SET bill = GREATEST (NVL (bill, ld_max), ld_max),
            months = GREATEST (NVL (months, DECODE (ld_max, TRUNC (ld_max, 'MONTH'), ld_max, months)), DECODE (ld_max, TRUNC (ld_max, 'MONTH'), ld_max, months)),
            state_date = SYSDATE,
            state_cod = 0,
            clock = 0
      WHERE mid = lc.mid;
    END IF;
   END IF;
  END LOOP;

  UPDATE last_save
     SET bill = GREATEST (ld_date + 1, NVL (bill, ld_date + 1)),
         months = DECODE (TRUNC (ld_date + 1, 'MONTH'), ld_date + 1, GREATEST (ld_date + 1, NVL (months, ld_date + 1)), months)
   WHERE mid = an_cid;

  DELETE FROM textreport;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001, 'comsrvfile_pg.l_30818: ' || 'Ошибка загрузки данных (стр. ' || ln_str || ', столб. ' || ln_col || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE l_1010 (an_cid NUMBER, at_data common_pg.tt_varchar2) IS   -- added by KAG 22.08.2008
 cn_cnt CONSTANT NUMBER              DEFAULT 48;
  ln_str         NUMBER              DEFAULT 0;
  ln_col         NUMBER              DEFAULT 0;
  lv_separator   VARCHAR2 (8)        DEFAULT ' ';
  ln_start       NUMBER              DEFAULT 0;
  ln_end         NUMBER              DEFAULT 0;
  ln_rn          NUMBER              DEFAULT 3;
  lv_ret         VARCHAR2 (4000);
  lv_tmp         VARCHAR2 (4000);
  ln_mid         NUMBER;
  ln_tmp         NUMBER;
  ld_date        DATE;
  ld_tmp         DATE;
  ld_max         DATE;
  lt_s           common_pg.tt_number;
  lt_e           common_pg.tt_number;
  ln_s           NUMBER;
  ln_e           NUMBER;
  ln_type        NUMBER;
  ln_tmptype     NUMBER;
  lv_mtrsn       VARCHAR2 (4000);
  ln_block       NUMBER;
  ln_reverse     NUMBER;
  ln_factcnt     NUMBER;
  ln_shift       NUMBER;
 BEGIN
  --Ищем начало и конец файла
  FOR i IN 1 .. at_data.COUNT LOOP
   IF (INSTR (at_data (i), '##01010') > 0) THEN
    ln_start := i;
   END IF;

   IF (TRIM (at_data (i)) = '##') THEN
    ln_end := i;
    EXIT;
   END IF;
  END LOOP;

  IF (ln_start = 0) THEN
   raise_application_error (-20001, 'Не найдено начало файла ##01010.');
  END IF;

  IF (ln_end = 0) THEN
   raise_application_error (-20001, 'Не найден конец файла ##.');
  END IF;

  ln_str := ln_start;
  ln_col := ln_start;
  lv_ret := at_data (ln_start);   --первая корректная строка файла
  ld_date := TO_DATE (util_pg.get_param (lv_ret, 3, lv_separator), 'YYMMDD');   --извлечение даты из первой строки
  ln_factcnt := util_pg.get_count_dt (ld_date, 1 / cn_cnt);

  --Пробегаем по файлу и выписываем все ид точек
  DELETE FROM textreport;
  
  -- определяем тип файла
 IF INSTR(TRIM(at_data (ln_start+1)),lv_separator,1,5)>1 THEN ------------------ файл с показаниями

  FOR i IN ln_start + 1 .. ln_end LOOP
   ln_str := i;
   ln_col := 1;
   lv_ret := at_data (i);
   lv_tmp :=
    lv_separator || util_pg.get_param_rev (lv_ret, 3, lv_separator) || lv_separator || util_pg.get_param_rev (lv_ret, 2, lv_separator) || lv_separator
    || util_pg.get_param_rev (lv_ret, 1, lv_separator);   --получение последних трех параметров строки
   ln_tmp := INSTR (lv_ret, lv_tmp, -1);   -- начало вхождения последних трех параметров
   lv_tmp := SUBSTR (lv_ret, 1, ln_tmp - 1);
   lv_tmp := UPPER (TRIM (lv_tmp));   -- идентификатор точки

   IF (LENGTH (util_pg.get_param (lv_tmp, 1, lv_separator)) < 1) THEN
    raise_application_error (-20001, 'Отсутствует идентификатор точки.');
   END IF;

   --Ищем точку
   SELECT MAX (mid), COUNT (*), MAX (nblock)
     INTO ln_mid, ln_tmp, ln_block
     FROM feeders
    WHERE mid IN (SELECT mid
                    FROM chanpoint
                   WHERE cid = an_cid) AND util_pg.get_pos_str (TRIM (UPPER (vimportcode)), lv_tmp) BETWEEN 1 AND 4;

   IF ln_tmp > 1 THEN
    raise_application_error (-20001, 'Точка определена неоднозначно.');
   ELSIF ln_tmp = 1 AND ln_block = 0 THEN
    INSERT INTO textreport
                (norder)
         VALUES (ln_mid);
   END IF;
  END LOOP;

  FOR lc IN (SELECT DISTINCT norder mid
                        FROM textreport) LOOP
   --Обнулили макс дату
   ld_max := ld_date - 1;

   --Очистили
   FOR i IN 1 .. 6 * 5 LOOP
    lt_s (i) := NULL;
    lt_e (i) := NULL;
   END LOOP;

   --Поискали нужные строки
   FOR i IN ln_start + 1 .. ln_end LOOP
    ln_str := i;
    ln_col := 1;
    lv_ret := TRIM (at_data (i));
    lv_tmp :=
     lv_separator || util_pg.get_param_rev (lv_ret, 3, lv_separator) || lv_separator || util_pg.get_param_rev (lv_ret, 2, lv_separator) || lv_separator
     || util_pg.get_param_rev (lv_ret, 1, lv_separator);   --получение последних трех параметров строки
    ln_tmp := INSTR (lv_ret, lv_tmp, -1);   -- начало вхождения последних трех параметров
    lv_tmp := SUBSTR (lv_ret, 1, ln_tmp - 1);   -- идентификатор точки
    --Проверяем, что это нужная строка
    lv_tmp := UPPER (TRIM (lv_tmp));

    SELECT COUNT (*), MAX (util_pg.get_pos_str (TRIM (UPPER (vimportcode)), lv_tmp))
      INTO ln_tmp, ln_type
      FROM feeders
     WHERE mid = lc.mid AND util_pg.get_pos_str (TRIM (UPPER (vimportcode)), lv_tmp) BETWEEN 1 AND 4;

    IF ln_tmp = 1 THEN   --для найденной строки заносим показания на начало (1й пар-р с конца) и конец дня(2й пар-р с конца);
                         --с третьим параметром ничего не делаем

     ln_s := REPLACE (util_pg.get_param_rev (lv_ret, 1, lv_separator), ',', '.');   -- и меняем запятую на точку
     ln_e := REPLACE (util_pg.get_param_rev (lv_ret, 2, lv_separator), ',', '.');   -- и меняем запятую на точку
/*     IF ln_s<0 AND ln_e<0 THEN   -- Если <0 то инвертируем.
          IF ln_type IN (1, 3) THEN
             ln_tmptype := ln_type + 1;
          ELSE
             ln_tmptype := ln_type - 1;
          END IF;
          ln_s := -ln_s;
          ln_e := -ln_e;
     ELSE
          ln_tmptype := ln_type;
     END IF;*/ --при инверсии затираются данные для других точек
     ln_tmptype := ln_type;
     lt_s(ln_tmptype) := ln_s;
     lt_e(ln_tmptype) := ln_e;
    END IF;
   END LOOP;

    comsrv_pg.set_bill_meter (lc.mid, lt_s (1), lt_s (2), lt_s (3), lt_s (4), lt_s (5), lt_s (6), lt_s (7), lt_s (8), lt_s (9), lt_s (10), lt_s (11), lt_s (12),
                              lt_s (13), lt_s (14), lt_s (15), lt_s (16), lt_s (17), lt_s (18), lt_s (19), lt_s (20), lt_s (21), lt_s (22), lt_s (23), lt_s (24),
                              lt_s (25), lt_s (26), lt_s (27), lt_s (28), lt_s (29), lt_s (30), lv_mtrsn, NULL, ld_date);
    comsrv_pg.set_bill_meter (lc.mid, lt_e (1), lt_e (2), lt_e (3), lt_e (4), lt_e (5), lt_e (6), lt_e (7), lt_e (8), lt_e (9), lt_e (10), lt_e (11), lt_e (12),
                              lt_e (13), lt_e (14), lt_e (15), lt_e (16), lt_e (17), lt_e (18), lt_e (19), lt_e (20), lt_e (21), lt_e (22), lt_e (23), lt_e (24),
                              lt_e (25), lt_e (26), lt_e (27), lt_e (28), lt_e (29), lt_e (30), lv_mtrsn, NULL, ld_date + 1);
    ld_max := ld_date + 1;

   ln_str := ln_start;
   ln_col := ln_start;

   IF ld_max > ld_date THEN
    SELECT MAX (mtrsn)
      INTO lv_mtrsn
      FROM meters
     WHERE mid = lc.mid AND entype = 7;

    editfeeders_pg.ins_last_save (lc.mid);

    IF util_pg.get_customer_id <> 1 THEN
     UPDATE last_save
        SET bill = GREATEST (NVL (bill, ld_max), ld_max),
            months = GREATEST (NVL (months, DECODE (ld_max, TRUNC (ld_max, 'MONTH'), ld_max, months)), DECODE (ld_max, TRUNC (ld_max, 'MONTH'), ld_max, months)),
            state_date = SYSDATE,
            state_cod = 0,
            clock = 0
      WHERE mid = lc.mid;
    END IF;
   END IF;
  END LOOP;
  
   UPDATE last_save
     SET bill = GREATEST (ld_date + 1, NVL (bill, ld_date + 1)),
         months = DECODE (TRUNC (ld_date + 1, 'MONTH'), ld_date + 1, GREATEST (ld_date + 1, NVL (months, ld_date + 1)), months)
   WHERE mid = an_cid;
  
 ELSE ----------------------------------------------- файл с суточными расходами
  FOR i IN ln_start + 1 .. ln_end LOOP
   ln_str := i;
   ln_col := 1;
   lv_ret := at_data (i);
   lv_tmp := util_pg.get_param_rev (lv_ret, 1, lv_separator);   --получение последнего параметра строки
   ln_tmp := INSTR (lv_ret, lv_tmp, -1);   -- начало вхождения последнего параметра
   lv_tmp := SUBSTR (lv_ret, 1, ln_tmp - 1);
   lv_tmp := UPPER (TRIM (lv_tmp));   -- идентификатор точки

   IF (LENGTH (util_pg.get_param (lv_tmp, 1, lv_separator)) < 1) THEN
    raise_application_error (-20001, 'Отсутствует идентификатор точки.');
   END IF;

   --Ищем точку
   SELECT MAX (mid), COUNT (*), MAX (nblock)
     INTO ln_mid, ln_tmp, ln_block
     FROM feeders
    WHERE mid IN (SELECT mid
                    FROM chanpoint
                   WHERE cid = an_cid)
          AND util_pg.get_pos_str (TRIM (UPPER (vimportcode)), lv_tmp) BETWEEN 1 AND 4;

   IF ln_tmp > 1 THEN
    raise_application_error (-20001, 'Точка определена неоднозначно.');
   ELSIF ln_tmp = 1 AND ln_block = 0 THEN
    INSERT INTO textreport
                (norder)
         VALUES (ln_mid);
   END IF;
  END LOOP;

  FOR lc IN (SELECT DISTINCT norder mid
                        FROM textreport) LOOP
   --Обнулили макс дату
   ld_max := ld_date - 1;
   --Очистили
   FOR i IN 1 .. ln_factcnt * 4 LOOP
    lt_e (i) := NULL;
   END LOOP;

   --Поискали нужные строки
   FOR i IN ln_start + 1 .. ln_end LOOP
    ln_str := i;
    ln_col := 1;
    lv_ret := TRIM (at_data (i));
    lv_tmp := util_pg.get_param_rev (lv_ret, 1, lv_separator);   --получение последнего параметра строки
    ln_tmp := INSTR (lv_ret, lv_tmp, -1);   -- начало вхождения последнего параметра
    lv_tmp := SUBSTR (lv_ret, 1, ln_tmp - 1);
    lv_tmp := UPPER (TRIM (lv_tmp));   -- идентификатор точки

    --Проверяем, что это нужная строка
    SELECT COUNT (*), MAX (util_pg.get_pos_str (TRIM (UPPER (vimportcode)), lv_tmp))
      INTO ln_tmp, ln_type
      FROM feeders
     WHERE mid = lc.mid AND util_pg.get_pos_str (TRIM (UPPER (vimportcode)), lv_tmp) BETWEEN 1 AND 4;

    IF ln_tmp = 1 THEN   --для найденной строки заносим показания на начало (1й пар-р с конца) и конец дня(2й пар-р с конца);
                         --с коэффициентом ничего не делаем
     ln_e := REPLACE (util_pg.get_param_rev (lv_ret, 1, lv_separator), ',', '.');   -- и меняем запятую на точку
     --ln_e := REPLACE (util_pg.get_param_rev (lv_ret, 2, lv_separator), ',', '.');   -- и меняем запятую на точку
/*     IF ln_e<0 THEN   -- Если <0 то инвертируем.
          IF ln_type IN (1, 3) THEN
             ln_tmptype := ln_type + 1;
          ELSE
             ln_tmptype := ln_type - 1;
          END IF;
          ln_e := -ln_e;
     ELSE
          ln_tmptype := ln_type;
     END IF;*/ --при инверсии затираются данные для других строк
     ln_tmptype := ln_type;
     ln_s := ln_e;
     FOR j IN 1 .. ln_factcnt LOOP
      lt_e (ln_factcnt * (ln_tmptype - 1) + j) := TRUNC(ln_e / ln_factcnt); -- раскидываем расход на получасовки
      ln_s := ln_s - lt_e (ln_factcnt * (ln_tmptype - 1) + j); -- остаток не раскиданный по получасовкам
      IF lt_e (ln_factcnt * (ln_tmptype - 1) + j) IS NOT NULL THEN
       ld_max := ld_date + j / cn_cnt;
      END IF;
     END LOOP;
     FOR j IN 1 .. ln_factcnt LOOP -- раскидываем остаток
      IF ln_s>=1 THEN
        lt_e (ln_factcnt * (ln_tmptype - 1) + j) := lt_e (ln_factcnt * (ln_tmptype - 1) + j) + 1;
        ln_s := ln_s - 1;
      ELSE
        lt_e (ln_factcnt * (ln_tmptype - 1) + j) := lt_e (ln_factcnt * (ln_tmptype - 1) + j) + ln_s;
        EXIT;
      END IF;
     END LOOP;
    END IF;
   END LOOP;
   
   ln_str := ln_start;
   ln_col := ln_start;

   SELECT NVL (MAX (ed_position), 0)
        INTO ln_reverse
        FROM feeders
       WHERE mid = lc.mid;

   FOR j IN 1 .. ln_factcnt LOOP
    --Если есть цифры
    IF lt_e (j) IS NOT NULL OR lt_e (1 * ln_factcnt + j) IS NOT NULL OR lt_e (2 * ln_factcnt + j) IS NOT NULL OR lt_e (3 * ln_factcnt + j) IS NOT NULL THEN
     IF ln_factcnt > cn_cnt AND j > (cn_cnt / 24) * (util_pg.switch_f + 1) AND j <= cn_cnt THEN   --больше времени сдвига добавяем час
      ln_shift := 1 / 24;
     ELSIF j > cn_cnt THEN
      ln_shift := -1 + (util_pg.switch_f + 1) / 24;
     ELSE
      ln_shift := 0;
     END IF;

     IF util_pg.get_customer_id = 1 AND ln_reverse > 0 THEN
      util_pg.chdr (lt_e (j), lt_e (1 * ln_factcnt + j), lt_e (2 * ln_factcnt + j), lt_e (3 * ln_factcnt + j));
     END IF;

     das_pg.insert_hf_in_profile (lc.mid, util_pg.to_unlocaltime_if_new (ld_date) + j / cn_cnt + ln_shift, 24 * 60 / cn_cnt,
                                  lt_e (j), lt_e (1 * ln_factcnt + j), lt_e (2 * ln_factcnt + j), NULL, lt_e (3 * ln_factcnt + j), NULL, ln_rn);
     inshalfhour (lc.mid, util_pg.to_unlocaltime_if_new (ld_date) + j / cn_cnt + ln_shift,
                                  lt_e (j), lt_e (1 * ln_factcnt + j), lt_e (2 * ln_factcnt + j), lt_e (3 * ln_factcnt + j));
    END IF;
   END LOOP;

    IF util_pg.get_customer_id <> 1 AND ld_max > ld_date THEN
      editfeeders_pg.ins_last_save (lc.mid);

    UPDATE last_save
       SET halfhour = ld_max,
           state_date = SYSDATE,
           state_cod = 0,
           clock = 0
     WHERE mid = lc.mid;
    END IF;
    END LOOP;

    UPDATE last_save
     SET halfhour = GREATEST (ld_date + 1, NVL (halfhour, ld_date + 1))
    WHERE mid = an_cid;

 END IF;

 DELETE FROM textreport;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001, 'comsrvfile_pg.l_1010: ' || 'Ошибка загрузки данных (стр. ' || ln_str || ', столб. ' || ln_col || CHR (10) || SQLERRM (SQLCODE));
 END;

