 PROCEDURE l_10015 (an_cid NUMBER, at_data common_pg.tt_varchar2) IS
  cn_cnt    CONSTANT NUMBER          DEFAULT 24;
  cn_cnt2   CONSTANT NUMBER          DEFAULT 48;
  ln_str             NUMBER          DEFAULT 0;
  ln_col             NUMBER          DEFAULT 0;
  lv_separator       VARCHAR2 (8)    DEFAULT ':';
  ln_rn              NUMBER          DEFAULT 3;
  ln_count           NUMBER          DEFAULT at_data.COUNT - 1;
  lv_ret             VARCHAR2 (4000);
  lv_tmp             VARCHAR2 (4000);
  ln_mid             NUMBER;
  ln_tmp             NUMBER;
  ld_max             DATE;
  ld_date            DATE;
  ln_er              NUMBER;
  ln_ed              NUMBER;
  ln_factcnt         NUMBER;
  ln_shift           NUMBER;
  ln_block           NUMBER;
 BEGIN
  --Проверяем начало
  ln_str := 1;
  ln_col := 1;
  lv_ret := at_data (1);
  ld_date := getdatabystr (util_pg.get_param (lv_ret, 2, lv_separator));
  ln_factcnt := util_pg.get_count_dt (ld_date, 1 / cn_cnt);

  --Бегаем по файлу
  FOR i IN 2 .. ln_count LOOP
   ln_str := i;
   ln_col := 1;
   lv_ret := at_data (i);
   lv_tmp := TRIM (util_pg.get_param (lv_ret, 1, lv_separator));

   IF SUBSTR (lv_tmp, 1, 1) <> '(' OR SUBSTR (lv_tmp, LENGTH (lv_tmp)) <> ')' THEN
    raise_application_error (-20001, 'Отсутствует признак идентификатора точки.');
   END IF;

   --Убираем скобки
   lv_tmp := TRIM (SUBSTR (lv_tmp, 2, LENGTH (lv_tmp) - 2));

   IF lv_tmp IS NULL THEN
    raise_application_error (-20001, 'Код точки не указан.');
   END IF;

   --Ищем точку
   SELECT MAX (mid), COUNT (*), MAX (nblock)
     INTO ln_mid, ln_tmp, ln_block
     FROM feeders
    WHERE mid IN (SELECT mid
                    FROM chanpoint
                   WHERE cid = an_cid) AND TRIM (UPPER (vimportcode)) = lv_tmp;

   IF ln_tmp > 1 THEN
    raise_application_error (-20001, 'Точка определена не однозначно.');
   ELSIF ln_tmp = 0 OR ln_block = 1 THEN   --точки нет - выскочили
    GOTO to_continue;
   END IF;

   --Обнулили макс дату
   ld_max := ld_date - 1;

   FOR j IN 1 .. cn_cnt LOOP
    IF cn_cnt > ln_factcnt AND j = util_pg.switch_f + 1 THEN   --Весна
     GOTO to_continue1;
    END IF;

    ln_er := REPLACE (util_pg.get_param (lv_ret, 3 + j, lv_separator), ',', '.') * 1000;   --* на 1000 и меняем запятую на точку
    ln_col := j;

    IF ln_er IS NOT NULL THEN
     ld_max := ld_date + j / cn_cnt;
    END IF;

    IF SIGN (ln_er) IN (0, 1) THEN
     ln_ed := NULL;
    ELSE
     ln_ed := -ln_er;
     ln_er := NULL;
    END IF;

    IF ln_factcnt > cn_cnt AND j > (cn_cnt / 24) * (util_pg.switch_f + 1) AND j <= cn_cnt THEN   --больше времени сдвига добавяем час
     ln_shift := 1 / 24;
    ELSE
     ln_shift := 0;
    END IF;

    das_pg.insert_hf_in_profile (ln_mid, util_pg.to_unlocaltime_if_new (ld_date) + (2 * j - 1) / cn_cnt2 + ln_shift, 30, TRUNC (ln_er / 2, ln_rn),
                                 TRUNC (ln_ed / 2, ln_rn), NULL, NULL, NULL, NULL, ln_rn);
    inshalfhour (ln_mid, util_pg.to_unlocaltime_if_new (ld_date) + (2 * j - 1) / cn_cnt2 + ln_shift, TRUNC (ln_er / 2, ln_rn), TRUNC (ln_ed / 2, ln_rn));
    das_pg.insert_hf_in_profile (ln_mid, util_pg.to_unlocaltime_if_new (ld_date) + 2 * j / cn_cnt2 + ln_shift, 30, ln_er - TRUNC (ln_er / 2, ln_rn),
                                 ln_ed - TRUNC (ln_ed / 2, ln_rn), NULL, NULL, NULL, NULL, ln_rn);
    inshalfhour (ln_mid, util_pg.to_unlocaltime_if_new (ld_date) + 2 * j / cn_cnt2 + ln_shift, ln_er - TRUNC (ln_er / 2, ln_rn), ln_ed - TRUNC (ln_ed / 2, ln_rn));

    IF ln_factcnt > cn_cnt AND j = util_pg.switch_f + 1 THEN   --Зима (добавили час)
     inshalfhour (ln_mid, util_pg.to_unlocaltime_if_new (ld_date) + (2 * j - 1) / cn_cnt2 + ln_shift + 1 / 24, TRUNC (ln_er / 2, ln_rn), TRUNC (ln_ed / 2, ln_rn));
     inshalfhour (ln_mid, util_pg.to_unlocaltime_if_new (ld_date) + 2 * j / cn_cnt2 + ln_shift + 1 / 24, ln_er - TRUNC (ln_er / 2, ln_rn),
                  ln_ed - TRUNC (ln_ed / 2, ln_rn));
    END IF;

    <<to_continue1>>
    NULL;
   END LOOP;

   IF util_pg.get_customer_id <> 1 AND ld_max > ld_date THEN
    editfeeders_pg.ins_last_save (ln_mid);

    UPDATE last_save
       SET halfhour = ld_max + 1,
           state_date = SYSDATE,
           state_cod = 0,
           clock = 0
     WHERE mid = ln_mid;
   END IF;

   <<to_continue>>
   NULL;
  END LOOP;

  UPDATE last_save
     SET halfhour = GREATEST (ld_date + 1, NVL (halfhour, ld_date + 1))
   WHERE mid = an_cid;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001, 'comsrvfile_pg.l_10015: ' || 'Ошибка загрузки данных (стр. ' || ln_str || ', столб. ' || ln_col || CHR (10) || SQLERRM (SQLCODE));
 END;

