-- added SSP ......  48 получасовок
 PROCEDURE lp_elvin (an_cid NUMBER, av_filename VARCHAR2, at_data common_pg.tt_varchar2) IS
  cn_cnt    CONSTANT NUMBER          DEFAULT 24;
  cn_cnt2   CONSTANT NUMBER          DEFAULT 48;
  ln_str             NUMBER          DEFAULT 0;
  ln_col             NUMBER          DEFAULT 0;
  lv_separator       VARCHAR2 (8)    DEFAULT '|';
  lv_separator1      VARCHAR2 (8)    DEFAULT ' ';
  ln_rn              NUMBER          DEFAULT 3;
  ln_count           NUMBER          DEFAULT at_data.COUNT;
  lv_ret             VARCHAR2 (4000);
  lv_tmp             VARCHAR2 (4000);
  ln_mid             NUMBER;
  ln_tmp             NUMBER;
  ld_max             DATE;
  ld_date            DATE;
  ln_kc              NUMBER;
  ln_er              NUMBER;
  ln_ed              NUMBER;
  ln_q1              NUMBER;
  ln_q3              NUMBER;
  ln_factcnt         NUMBER;
  ln_shift           NUMBER;
  lv_date            VARCHAR2 (32);
  lv_t2              VARCHAR2 (32);
  f_dayswitch        NUMBER;
 BEGIN
  --ln_factcnt := util_pg.get_count_dt(ld_date, 1 / cn_cnt);

  --Бегаем по файлу
  FOR i IN 1 .. ln_count LOOP
   IF at_data (i) LIKE '%ID=%' THEN   -- новая точка
    lv_ret := at_data (i);
    lv_tmp := TRIM (util_pg.get_param (lv_ret, 2, lv_separator1));
    --вырезаем код
    lv_tmp := SUBSTR (lv_tmp, 5, LENGTH (lv_tmp) - 4);

    IF TRIM (lv_tmp) IS NULL THEN
     raise_application_error (-20002, 'Код точки не указан.');
    END IF;

    --Ищем точку
    SELECT MAX (mid), COUNT (*)
      INTO ln_mid, ln_tmp
      FROM feeders
     WHERE mid IN (SELECT mid
                     FROM chanpoint
                    WHERE cid = an_cid AND nskip IS NULL)   -- AND er_position = TO_NUMBER(lv_tmp);
                                                         AND canal = TO_NUMBER (lv_tmp);

    IF ln_tmp > 1 THEN
     raise_application_error (-20002, 'Точка определена не однозначно.');
    END IF;

    SELECT NVL (MAX (kc), 1)
      INTO ln_kc
      FROM feeders
     WHERE mid = ln_mid;
   END IF;

   IF at_data (i) LIKE '____/__/__%' THEN   -- новая дата
    lv_ret := at_data (i);
    lv_tmp := TRIM (util_pg.get_param (lv_ret, 1, lv_separator1));
    lv_date := REPLACE (lv_tmp, '/');
    f_dayswitch := util_pg.is_dayswitch (TO_DATE (lv_date, 'YYYYMMDD'));   -- (-1, 1, 0)
   END IF;

   IF at_data (i) LIKE '%__:__ .. __:__%' THEN   -- новая получасовка
    lv_ret := at_data (i);
    lv_tmp := TRIM (util_pg.get_param (lv_ret, 2, lv_separator));
    lv_t2 := SUBSTR (lv_tmp, LENGTH (lv_tmp) - 4);
    ln_shift := 0;

    IF f_dayswitch = -1 THEN
     IF TO_NUMBER (REPLACE (lv_t2, ':')) > util_pg.switch_f * 100 THEN
      ln_shift := -1;
     END IF;
    ELSIF f_dayswitch = 1 THEN
     IF TO_NUMBER (REPLACE (lv_t2, ':')) > util_pg.switch_f * 100 THEN
      ln_shift := 1;
     END IF;
    END IF;

    IF lv_t2 = '24:00' THEN
     ld_date := TO_DATE (lv_date, 'YYYYMMDD') + 1;
    ELSIF lv_t2 = '24:30' THEN
     ld_date := TO_DATE (lv_date || ' 00:30', 'YYYYMMDD HH24:MI') + 1;
    ELSIF lv_t2 = '25:00' THEN
     ld_date := TO_DATE (lv_date || ' 01:00', 'YYYYMMDD HH24:MI') + 1;
    ELSE
     ld_date := TO_DATE (lv_date || ' ' || lv_t2, 'YYYYMMDD HH24:MI');
    END IF;

    ln_ed := TO_NUMBER (TRIM (util_pg.get_param (lv_ret, 4, lv_separator))) * ln_kc / 1000;
    ln_er := TO_NUMBER (TRIM (util_pg.get_param (lv_ret, 5, lv_separator))) * ln_kc / 1000;
    ln_q3 := TO_NUMBER (TRIM (util_pg.get_param (lv_ret, 6, lv_separator))) * ln_kc / 1000;
    ln_q1 := TO_NUMBER (TRIM (util_pg.get_param (lv_ret, 7, lv_separator))) * ln_kc / 1000;
    das_pg.ins_halfhourtmp (ln_mid, util_pg.to_unlocaltime_if_new (ld_date) + ln_shift / 24, gn_source, TRUNC (ln_er / 2, ln_rn), TRUNC (ln_ed / 2, ln_rn),
                            TRUNC (ln_q1 / 2, ln_rn), TRUNC (ln_q3 / 2, ln_rn), NULL, NULL, NULL, comsrv_pg.cn_maket, NULL);
   END IF;
  END LOOP;   --FOR i IN 1 .. ln_count
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001, 'comsrvfile_pg.l_elvin: ' || 'Ошибка загрузки данных ' || SQLERRM (SQLCODE));
 END;   -- lp_elvin

 ---------- 19.06.2007
 -- added SSP ......  24 часовок  --
 PROCEDURE lp_elvin60 (an_cid NUMBER, av_filename VARCHAR2, at_data common_pg.tt_varchar2) IS
  cn_cnt    CONSTANT NUMBER          DEFAULT 24;
  cn_cnt2   CONSTANT NUMBER          DEFAULT 48;
  ln_str             NUMBER          DEFAULT 0;
  ln_col             NUMBER          DEFAULT 0;
  lv_separator       VARCHAR2 (8)    DEFAULT '|';
  lv_separator1      VARCHAR2 (8)    DEFAULT ' ';
  ln_rn              NUMBER          DEFAULT 3;
  ln_count           NUMBER          DEFAULT at_data.COUNT;
  lv_ret             VARCHAR2 (4000);
  lv_tmp             VARCHAR2 (4000);
  ln_mid             NUMBER;
  ln_tmp             NUMBER;
  ld_max             DATE;
  ld_date            DATE;
  ln_kc              NUMBER;
  ln_er              NUMBER;
  ln_ed              NUMBER;
  ln_q1              NUMBER;
  ln_q3              NUMBER;
  ln_factcnt         NUMBER;
  ln_shift           NUMBER;
  lv_date            VARCHAR2 (32);
  lv_t2              VARCHAR2 (32);
  f_dayswitch        NUMBER;
  ln_hour            NUMBER;
 BEGIN
  --ln_factcnt := util_pg.get_count_dt(ld_date, 1 / cn_cnt);

  --Бегаем по файлу
  FOR i IN 1 .. ln_count LOOP
   IF at_data (i) LIKE '%ID=%' THEN   -- новая точка
    lv_ret := at_data (i);
    lv_tmp := TRIM (util_pg.get_param (lv_ret, 2, lv_separator1));
    --вырезаем код
    lv_tmp := SUBSTR (lv_tmp, 5, LENGTH (lv_tmp) - 4);

    IF TRIM (lv_tmp) IS NULL THEN
     raise_application_error (-20002, 'Код точки не указан.');
    END IF;

    --Ищем точку
    SELECT MAX (mid), COUNT (*)
      INTO ln_mid, ln_tmp
      FROM feeders
     WHERE mid IN (SELECT mid
                     FROM chanpoint
                    WHERE cid = an_cid AND nskip IS NULL)   -- AND er_position = TO_NUMBER(lv_tmp);
                                                         AND canal = TO_NUMBER (lv_tmp);

    IF ln_tmp > 1 THEN
     raise_application_error (-20002, 'Точка определена не однозначно.');
    END IF;

    SELECT NVL (MAX (kc), 1)
      INTO ln_kc
      FROM feeders
     WHERE mid = ln_mid;
   END IF;

   IF at_data (i) LIKE '____/__/__%' THEN   -- новая дата
    lv_ret := at_data (i);
    lv_tmp := TRIM (util_pg.get_param (lv_ret, 1, lv_separator1));
    lv_date := REPLACE (lv_tmp, '/', '.');
    ld_date := TRUNC (TO_DATE (lv_tmp, 'YYYY.MM.DD'));
   END IF;

   IF at_data (i) LIKE '%__:__ .. __:__%' THEN   -- новая получасовка
    lv_ret := at_data (i);
    lv_tmp := TRIM (util_pg.get_param (lv_ret, 2, lv_separator));   -- --вырезаем дату
    ln_hour := TO_NUMBER (SUBSTR (lv_tmp, 1, 2)) + 1;   -- 1 .. 24
    ln_ed := TO_NUMBER (TRIM (util_pg.get_param (lv_ret, 4, lv_separator))) * ln_kc / 1000;
    ln_er := TO_NUMBER (TRIM (util_pg.get_param (lv_ret, 5, lv_separator))) * ln_kc / 1000;
    ln_q3 := TO_NUMBER (TRIM (util_pg.get_param (lv_ret, 6, lv_separator))) * ln_kc / 1000;
    ln_q1 := TO_NUMBER (TRIM (util_pg.get_param (lv_ret, 7, lv_separator))) * ln_kc / 1000;

    BEGIN
     INSERT INTO halfhourold
                 (mid, date_time, er, ed, q1, q3,
                  nsource
                 )
          VALUES (ln_mid, ld_date + (2 * ln_hour - 1) / 48, TRUNC (ln_er / 2, ln_rn), TRUNC (ln_ed / 2, ln_rn), TRUNC (ln_q1 / 2, ln_rn), TRUNC (ln_q3 / 2, ln_rn),
                  gn_source
                 );
    EXCEPTION
     WHEN DUP_VAL_ON_INDEX THEN
      UPDATE halfhourold
         SET er = TRUNC (ln_er / 2, ln_rn),
             ed = TRUNC (ln_ed / 2, ln_rn),
             q1 = TRUNC (ln_q1 / 2, ln_rn),
             q3 = TRUNC (ln_q3 / 2, ln_rn)
       WHERE mid = ln_mid AND date_time = ld_date + (2 * ln_hour - 1) / 48 AND nsource = gn_source;
    END;

    BEGIN
     INSERT INTO halfhourold
                 (mid, date_time, er, ed, q1,
                  q3, nsource
                 )
          VALUES (ln_mid, ld_date + 2 * ln_hour / 48, ln_er - TRUNC (ln_er / 2, ln_rn), ln_ed - TRUNC (ln_ed / 2, ln_rn), ln_q1 - TRUNC (ln_q1 / 2, ln_rn),
                  ln_q3 - TRUNC (ln_q3 / 2, ln_rn), gn_source
                 );
    EXCEPTION
     WHEN DUP_VAL_ON_INDEX THEN
      UPDATE halfhourold
         SET er = ln_ed - TRUNC (ln_er / 2, ln_rn),
             ed = ln_ed - TRUNC (ln_ed / 2, ln_rn),
             q1 = ln_q1 - TRUNC (ln_q1 / 2, ln_rn),
             q3 = ln_q3 - TRUNC (ln_q3 / 2, ln_rn)
       WHERE mid = ln_mid AND date_time = ld_date + 2 * ln_hour / 48 AND nsource = gn_source;
    END;
   END IF;
  END LOOP;   --FOR i IN 1 .. ln_count
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001, 'comsrvfile_pg.lp_elvin: ' || 'Ошибка загрузки данных ' || SQLERRM (SQLCODE));
 END;   -- lp_elvin60

