   lv_ret := at_data (i);

   IF lv_ret LIKE 'Clock (%' THEN   -- строка описания параметров
    --            ln_length:=length(lv_ret);
    k := 1;
    ln_separator := 0;

    LOOP
     k := INSTR (lv_ret, lv_separator, k) + 1;

     IF k > 1 THEN
      ln_separator := ln_separator + 1;
     ELSE
      EXIT;
     END IF;
    END LOOP;

    f_st := 0;
