    f_er := 0;
    f_q1 := 0;
    f_q3 := 0;
    f_edm := 0;
    f_erm := 0;
    f_q1m := 0;
    f_q3m := 0;
    ln_edm := NULL;
    ln_ed := NULL;
    ln_erm := NULL;
    ln_er := NULL;
    ln_q3m := NULL;
    ln_q3 := NULL;
    ln_q1m := NULL;
    ln_q1 := NULL;

    FOR j IN 1 .. ln_separator + 1 LOOP
     lv_tmp := TRIM (util_pg.get_param (lv_ret, j, lv_separator));

     IF lv_tmp LIKE '%Status%' THEN
      f_st := j;
     ELSIF lv_tmp LIKE '%1.5.0%' THEN
      f_ed := j;
     ELSIF lv_tmp LIKE '%2.5.0%' THEN
      f_er := j;
     ELSIF lv_tmp LIKE '%3.5.0%' THEN
      f_q3 := j;
     ELSIF lv_tmp LIKE '%4.5.0%' THEN
      f_q1 := j;
     ELSIF lv_tmp LIKE '%1.8.0%' THEN
      f_edm := j;
     ELSIF lv_tmp LIKE '%2.8.0%' THEN
      f_erm := j;
     ELSIF lv_tmp LIKE '%3.8.0%' THEN
      f_q3m := j;
     ELSIF lv_tmp LIKE '%4.8.0%' THEN
      f_q1m := j;
     END IF;
    END LOOP;

    IF f_st = 0 THEN
     raise_application_error (-20002, 'Поле статуса неопределено');
    END IF;
   END IF;

   --      IF lv_ret LIKE '__.__.____ __:__:__%' THEN   -- новая получасовка
   IF lv_ret LIKE '__.__.____ __:_0:00%' THEN   -- новая получасовка
    lv_tmp := TRIM (util_pg.get_param (lv_ret, f_st, lv_separator));

    IF SUBSTR (lv_tmp, 4, 1) = '8' THEN
     NULL;   -- >4 ?????
    ELSE
     ch_st := SUBSTR (lv_tmp, LENGTH (lv_tmp));

     IF ch_st >= '0' AND ch_st <= '8' THEN
      --        ln_st   := TO_NUMBER(substr(lv_tmp,length(lv_tmp)));
      ln_st := TO_NUMBER (ch_st);
      lv_tmp := TRIM (util_pg.get_param (lv_ret, 1, lv_separator));
      ld_date := TO_DATE (lv_tmp, 'DD.MM.YYYY HH24:MI:SS');
      f_dayswitch := util_pg.is_dayswitch (TRUNC (ld_date));   -- (-1, 1, 0)
      ln_shift := 0;

      IF f_dayswitch = -1 THEN
       IF ln_st < 8 THEN
        ln_shift := -1;
       END IF;
      ELSIF f_dayswitch = 1 THEN
       IF ln_st > 4 THEN
        ln_shift := 1;
       END IF;
      END IF;

      IF f_edm > 0 THEN
       ln_edm := TO_NUMBER (TRIM (util_pg.get_param (lv_ret, f_edm, lv_separator)));
      END IF;

      IF f_ed > 0 THEN
       ln_ed := TO_NUMBER (TRIM (util_pg.get_param (lv_ret, f_ed, lv_separator))) * ln_kc;
      END IF;

      IF f_erm > 0 THEN
       ln_erm := TO_NUMBER (TRIM (util_pg.get_param (lv_ret, f_erm, lv_separator)));
      END IF;

      IF f_er > 0 THEN
       ln_er := TO_NUMBER (TRIM (util_pg.get_param (lv_ret, f_er, lv_separator))) * ln_kc;
      END IF;

      IF f_q3m > 0 THEN
       ln_q3m := TO_NUMBER (TRIM (util_pg.get_param (lv_ret, f_q3m, lv_separator)));
      END IF;

      IF f_q3 > 0 THEN
