      das_pg.ins_halfhourtmp (ln_mid, util_pg.to_unlocaltime_if_new (ld_date) + ln_shift / 24, gn_source, TRUNC (ln_er, ln_rn), TRUNC (ln_ed, ln_rn),
                              TRUNC (ln_q1, ln_rn), TRUNC (ln_q3, ln_rn), NULL, NULL, ln_erm, ln_edm, ln_q1m, ln_q3m, NULL, NULL, ln_st, comsrv_pg.cn_lg_zxd,
