-- added SSP ......
 PROCEDURE lp_smartf (an_cid NUMBER, av_filename VARCHAR2, at_data common_pg.tt_varchar2) IS
  lv_separator   VARCHAR2 (8)    DEFAULT ';';
  ln_count       NUMBER          DEFAULT at_data.COUNT;
  lv_ret         VARCHAR2 (4000);
  lv_tmp         VARCHAR2 (4000);
  ln_tmp         NUMBER;
  ln_mid         NUMBER;
  mid_           NUMBER          := -100;
  ld_max         DATE;
  ld_date        DATE;
  ln_mtrsn       NUMBER;
  ln_type        NUMBER;
  ln_amount      NUMBER;
  ln_edm         NUMBER;
  ln_aedm        NUMBER;   -- пик
  ln_bedm        NUMBER;   -- полупик (день)
  ln_cedm        NUMBER;   -- ночь
  ln_q1m         NUMBER;
  ln_q3m         NUMBER;
  ln_bq3m        NUMBER;
 BEGIN
  --Бегаем по файлу
  FOR i IN 1 .. ln_count LOOP
   lv_ret := at_data (i);
   lv_tmp := TRIM (util_pg.get_param (lv_ret, 1, lv_separator));   --вырезаем код точки

   IF TRIM (lv_tmp) IS NULL THEN
    raise_application_error (-20002, 'Код точки не указан.');
   END IF;

           --Ищем точку
   --      select MAX(mid),count(*)  into ln_mid,ln_tmp  from points where mid = to_number(lv_tmp);
   SELECT MAX (mid), COUNT (*)
     INTO ln_mid, ln_tmp
     FROM feeders
    WHERE mid IN (SELECT mid
                    FROM chanpoint
                   WHERE cid = an_cid AND nskip IS NULL) AND vimportcode = TO_NUMBER (lv_tmp);

   IF ln_tmp > 1 THEN
    raise_application_error (-20002, 'Точка определена не однозначно.');
   ELSIF ln_tmp = 1 THEN
    IF ln_mid = mid_ THEN
     NULL;
    ELSE
     ln_edm := NULL;
     ln_q1m := NULL;
     ln_q3m := NULL;
    END IF;

    lv_tmp := TRIM (util_pg.get_param (lv_ret, 2, lv_separator));   -- --вырезаем номер счетчика
    ln_mtrsn := TO_NUMBER (lv_tmp);
    lv_tmp := TRIM (util_pg.get_param (lv_ret, 3, lv_separator));   -- --вырезаем дату
    ld_date := TO_DATE (lv_tmp, 'DD.MM.YYYY');
    lv_tmp := TRIM (util_pg.get_param (lv_ret, 6, lv_separator));   -- --вырезаем вид измерений
    ln_type := TO_NUMBER (lv_tmp);
    lv_tmp := TRIM (util_pg.get_param (lv_ret, 7, lv_separator));   -- --вырезаем показания
    ln_amount := TO_NUMBER (lv_tmp) / 1000;

    IF ln_type = 1 THEN
     ln_edm := ln_amount;
    ELSIF ln_type = 2 THEN
     ln_aedm := ln_amount;
    ELSIF ln_type = 3 THEN
     ln_bedm := ln_amount;
    ELSIF ln_type = 4 THEN
     ln_cedm := ln_amount;
    ELSIF ln_type = 6 THEN
     ln_q1m := ln_amount;
    ELSIF ln_type = 7 THEN
     ln_q3m := ln_amount;
     ln_bq3m := ln_amount;
    END IF;

    BEGIN
     INSERT INTO billorg
                 (mid, date_time, edm, q1m, q3m, bq3m, ed_mtrsn, nsource
                 )
          VALUES (ln_mid, ld_date, ln_edm, ln_q1m, ln_q3m, ln_bq3m, ln_mtrsn, gn_source
                 );
    EXCEPTION
     WHEN DUP_VAL_ON_INDEX THEN
      UPDATE billorg
         SET edm = ln_edm,
             aedm = ln_aedm,
             bedm = ln_bedm,
             cedm = ln_cedm,
             q1m = ln_q1m,
             q3m = ln_q3m,
             bq3m = ln_bq3m
       WHERE mid = ln_mid AND date_time = ld_date AND nsource = gn_source;
    END;

    mid_ := ln_mid;
   END IF;
  END LOOP;   --FOR i IN 1 .. ln_count
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001, 'comsrvfile_pg.lp_SmartF: ' || 'Ошибка загрузки данных ' || SQLERRM (SQLCODE));
 END;   -- lp_SmartF

