-- added SSP ......
 PROCEDURE lp_smarth (an_cid NUMBER, av_filename VARCHAR2, at_data common_pg.tt_varchar2) IS
  lv_separator   VARCHAR2 (8)    DEFAULT ';';
  ln_count       NUMBER          DEFAULT at_data.COUNT;
  ln_rn          NUMBER          DEFAULT 3;
  lv_ret         VARCHAR2 (4000);
  lv_tmp         VARCHAR2 (4000);
  ln_tmp         NUMBER;
  ln_mid         NUMBER;
  ln_kc          NUMBER;
  ld_max         DATE;
  ld_date        DATE;
  ln_mtrsn       NUMBER;
  ln_ed          NUMBER;
  ln_hour        NUMBER;
  ln_oldmid      NUMBER          DEFAULT 0;   -- added by EVK 28.07.2008
  ld_olddate     DATE;   -- added by EVK 28.07.2008
 BEGIN
  --Бегаем по файлу
  FOR i IN 1 .. ln_count LOOP
   lv_ret := REPLACE (at_data (i), '#', ';');   -- меняем # на ;
   lv_tmp := TRIM (util_pg.get_param (lv_ret, 1, lv_separator));   --вырезаем код точки

   IF TRIM (lv_tmp) IS NULL THEN
    raise_application_error (-20002, 'Код точки не указан.');
   END IF;

           --Ищем точку
   --      select MAX(mid),count(*)  into ln_mid,ln_tmp  from points where mid = to_number(lv_tmp);
   SELECT MAX (mid), COUNT (*)
     INTO ln_mid, ln_tmp
     FROM feeders
    WHERE mid IN (SELECT mid
                    FROM chanpoint
                   WHERE cid = an_cid AND nskip IS NULL) AND vimportcode = TO_NUMBER (lv_tmp);

   IF ln_tmp > 1 THEN
    raise_application_error (-20002, 'Точка определена не однозначно.');
   ELSIF ln_tmp = 1 THEN
    SELECT NVL (MAX (kc), 1)
      INTO ln_kc
      FROM feeders
     WHERE mid = ln_mid;

    lv_tmp := TRIM (util_pg.get_param (lv_ret, 2, lv_separator));   -- --вырезаем номер счетчика
    ln_mtrsn := TO_NUMBER (lv_tmp);
    lv_tmp := TRIM (util_pg.get_param (lv_ret, 4, lv_separator));   -- --вырезаем дату
    ld_date := TRUNC (TO_DATE (lv_tmp, 'DD.MM.YYYY HH24:MI'));
    ln_hour := TO_NUMBER (SUBSTR (lv_tmp, 12, 2)) + 1;   -- 1 .. 24
    lv_tmp := TRIM (util_pg.get_param (lv_ret, 5, lv_separator));   -- --вырезаем мощность
    ln_ed := TO_NUMBER (lv_tmp) * ln_kc;

    BEGIN
     INSERT INTO halfhourold
                 (mid, date_time, ed, er_mtrsn, nsource, nkc
                 )
          VALUES (ln_mid, ld_date + (2 * ln_hour - 1) / 48, TRUNC (ln_ed / 2, ln_rn), ln_mtrsn, gn_source, ln_kc
                 );
    EXCEPTION
     WHEN DUP_VAL_ON_INDEX THEN
      UPDATE halfhourold
         SET ed = TRUNC (ln_ed / 2, ln_rn)
       WHERE mid = ln_mid AND date_time = ld_date + (2 * ln_hour - 1) / 48 AND nsource = gn_source;
    END;

    BEGIN
     INSERT INTO halfhourold
                 (mid, date_time, ed, er_mtrsn, nsource, nkc
                 )
          VALUES (ln_mid, ld_date + 2 * ln_hour / 48, ln_ed - TRUNC (ln_ed / 2, ln_rn), ln_mtrsn, gn_source, ln_kc
                 );
    EXCEPTION
     WHEN DUP_VAL_ON_INDEX THEN
      UPDATE halfhourold
         SET ed = ln_ed - TRUNC (ln_ed / 2, ln_rn)
       WHERE mid = ln_mid AND date_time = ld_date + 2 * ln_hour / 48 AND nsource = gn_source;
    END;
   END IF;

-- added by EVK 28.07.2008
   IF NOT (ln_oldmid = ln_mid AND ld_olddate = ld_date) THEN
    INSERT INTO lagging_records
                (mid, ddate)
     SELECT ln_mid, ld_date
       FROM DUAL
      WHERE NOT EXISTS (SELECT *
                          FROM lagging_records
                         WHERE mid = ln_mid AND ddate = ld_date);
   END IF;

   ln_oldmid := ln_mid;
   ld_olddate := ld_date;
-- ***
  END LOOP;   --FOR i IN 1 .. ln_count
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001, 'comsrvfile_pg.lp_SmartF: ' || 'Ошибка загрузки данных ' || SQLERRM (SQLCODE));
 END;   -- lp_SmartH

