 PROCEDURE lp_argo (an_cid NUMBER, av_filename VARCHAR2, at_data common_pg.tt_varchar2) IS
  cn_cnt    CONSTANT NUMBER          DEFAULT 24;
  cn_cnt2   CONSTANT NUMBER          DEFAULT 48;
  lv_separator       VARCHAR2 (8)    DEFAULT '|';
  ln_rn              NUMBER          DEFAULT 3;
  ln_count           NUMBER          DEFAULT at_data.COUNT;
  lv_ret             VARCHAR2 (4000);
  lv_tmp             VARCHAR2 (4000);
  ln_mid             NUMBER;
  ln_tmp             NUMBER;
  ld_max             DATE;
  ld_date            DATE;
  ln_kc              NUMBER;
  ln_er              NUMBER;
  ln_ed              NUMBER;
  ln_q1              NUMBER;
  ln_q3              NUMBER;
  ln_shift           NUMBER;
  lv_date            VARCHAR2 (32);
  lv_t1              VARCHAR2 (32);
  lv_t2              VARCHAR2 (32);
  f_dayswitch        NUMBER;
  f_ed               NUMBER          := 0;
  f_er               NUMBER          := 0;
  f_q3               NUMBER          := 0;
  f_q1               NUMBER          := 0;
  k                  NUMBER;
  ln_separator       NUMBER          := 0;
 --  ff          number;
 BEGIN
  SELECT MAX (mid), COUNT (*)
    INTO ln_mid, ln_tmp
    FROM feeders
   WHERE mid IN (SELECT mid
                   FROM chanpoint
                  WHERE cid = an_cid AND nskip IS NULL)
                                                       --   and canal = to_number(substr(av_filename,1,8));
         AND canal = TO_NUMBER (SUBSTR (av_filename, 1, 6));

  IF ln_tmp > 1 THEN
   raise_application_error (-20002, 'Точка определена не однозначно.');
  ELSIF ln_tmp = 0 THEN   --точки нет
   raise_application_error (-20002, 'Точки нет');
  END IF;

  SELECT NVL (MAX (kc), 1)
    INTO ln_kc
    FROM feeders
   WHERE mid = ln_mid;

  --Бегаем по файлу
  FOR i IN 1 .. ln_count LOOP
   lv_ret := at_data (i);

   IF lv_ret LIKE 'ARGO%' THEN   -- строка описания параметров
    --            ln_length:=length(lv_ret);
    k := 1;
    ln_separator := 0;

    LOOP
     k := INSTR (lv_ret, lv_separator, k) + 1;

     IF k > 1 THEN
      ln_separator := ln_separator + 1;
     ELSE
      EXIT;
     END IF;
    END LOOP;

    f_ed := 0;
    f_er := 0;
    f_q1 := 0;
    f_q3 := 0;
    ln_ed := NULL;
    ln_er := NULL;
    ln_q3 := NULL;
    ln_q1 := NULL;

    FOR j IN 1 .. ln_separator + 1 LOOP
     lv_tmp := TRIM (util_pg.get_param (lv_ret, j, lv_separator));

     IF lv_tmp LIKE '%1.9.0%' THEN
      f_ed := j;
     ELSIF lv_tmp LIKE '%2.9.0%' THEN
      f_er := j;
     ELSIF lv_tmp LIKE '%3.9.0%' THEN
      f_q3 := j;
     ELSIF lv_tmp LIKE '%4.9.0%' THEN
      f_q1 := j;
     END IF;
    END LOOP;
   END IF;

   IF lv_ret LIKE '__.__.__ __:_0:00%' THEN   -- новая получасовка
    lv_tmp := TRIM (util_pg.get_param (lv_ret, 1, lv_separator));
    ld_date := TO_DATE (lv_tmp, 'DD.MM.YY HH24:MI:SS');

    IF f_ed > 0 THEN
     ln_ed := TO_NUMBER (TRIM (util_pg.get_param (lv_ret, f_ed, lv_separator))) * ln_kc / 100;
    END IF;

    IF f_er > 0 THEN
     ln_er := TO_NUMBER (TRIM (util_pg.get_param (lv_ret, f_er, lv_separator))) * ln_kc / 100;
    END IF;

    IF f_q3 > 0 THEN
     ln_q3 := TO_NUMBER (TRIM (util_pg.get_param (lv_ret, f_q3, lv_separator))) * ln_kc / 100;
    END IF;

    IF f_q1 > 0 THEN
     ln_q1 := TO_NUMBER (TRIM (util_pg.get_param (lv_ret, f_q1, lv_separator))) * ln_kc / 100;
    END IF;

    INSERT INTO halfhourold
                (mid, date_time, er, ed, q1, q3, nsource
                )
         VALUES (ln_mid, ld_date, TRUNC (ln_er, ln_rn), TRUNC (ln_ed, ln_rn), TRUNC (ln_q1, ln_rn), TRUNC (ln_q3, ln_rn), gn_source
                );
   END IF;
  END LOOP;   --FOR i IN 1 .. ln_count
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001, 'comsrvfile_pg.lp_argo: ' || ' Ошибка загр. данных ' || SQLERRM (SQLCODE));
 END;   -- lp_argo

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE l_30902 (an_cid NUMBER, at_data common_pg.tt_varchar2) IS
  ln_str         NUMBER              DEFAULT 0;
  ln_col         NUMBER              DEFAULT 0;
  lv_separator   VARCHAR2 (8)        DEFAULT ':';
  ln_rn          NUMBER              DEFAULT 0;   -- changed by EVK 09.09.08 !!!
  ln_count       NUMBER              DEFAULT at_data.COUNT - 1;
  lv_ret         VARCHAR2 (4000);
  lv_tmp         VARCHAR2 (4000);
  ln_mid         NUMBER;
  ln_tmp         NUMBER;
  ld_date        DATE;
  ld_max         DATE;
  ln_e           NUMBER;
  lt_e           common_pg.tt_number;
  ln_factcnt     NUMBER;
  ln_shift       NUMBER;
  cn_cnt         NUMBER;
  ln_type        NUMBER;
  ln_tmptype     NUMBER;
  ln_block       NUMBER;
  lv_str         VARCHAR (1024);
  lv_basemonth   VARCHAR2 (8);
  lv_basecode    VARCHAR2 (8);
 BEGIN
  --Проверяем начало
  ln_str := 1;
  ln_col := 1;
  lv_ret := at_data (1);
  lv_basemonth := util_pg.get_param (lv_ret, 2, lv_separator);
  lv_basecode := util_pg.get_param (lv_ret, 3, lv_separator);

  --Пробегаемся по файлу и выписываем все ид точек
  DELETE FROM textreport;

  FOR i IN 2 .. ln_count LOOP
   ln_str := i;
   ln_col := 1;
   lv_ret := at_data (i);
   lv_tmp := TRIM (util_pg.get_param (lv_ret, 1, lv_separator));

   IF SUBSTR (lv_tmp, 1, 1) <> '(' OR SUBSTR (lv_tmp, LENGTH (lv_tmp)) <> ')' THEN
    raise_application_error (-20001, 'Отсутствует признак идентификатора точки.');
   END IF;

   --Убираем скобки
   lv_tmp := UPPER (SUBSTR (lv_tmp, 2, LENGTH (lv_tmp) - 2));

   IF lv_tmp IS NULL OR INSTR (lv_tmp, ';') > 0 THEN
    raise_application_error (-20001, 'Код точки не указан или указан не верно.');
   END IF;

   lv_tmp := TRIM (lv_basecode) || lv_tmp;

   --Ищем точку
   SELECT MAX (mid), COUNT (*), MAX (nblock)
     INTO ln_mid, ln_tmp, ln_block
     FROM feeders
    WHERE mid IN (SELECT mid
                    FROM chanpoint
                   WHERE cid = an_cid) AND util_pg.get_pos_str (TRIM (UPPER (vimportcode)), lv_tmp) BETWEEN 1 AND 4;

   IF ln_tmp > 1 THEN
    raise_application_error (-20001, 'Точка определена не однозначно.');
   ELSIF ln_tmp = 1 AND ln_block = 0 THEN
    INSERT INTO textreport
                (norder
                )
         VALUES (ln_mid
                );
   END IF;
  END LOOP;

  FOR lc IN (SELECT DISTINCT norder mid
                        FROM textreport) LOOP
   --Поискали нужные строки
   FOR i IN 2 .. ln_count LOOP
    ln_str := i;
    ln_col := 1;
    lv_ret := TRIM (at_data (i));
    lv_tmp := TRIM (util_pg.get_param (lv_ret, 1, lv_separator));
    --Проверяем что это нужная строка
    lv_tmp := TRIM (lv_basecode) || UPPER (SUBSTR (lv_tmp, 2, LENGTH (lv_tmp) - 2));

    SELECT COUNT (*), MAX (util_pg.get_pos_str (TRIM (UPPER (vimportcode)), lv_tmp))
      INTO ln_tmp, ln_type
      FROM feeders
     WHERE mid = lc.mid AND util_pg.get_pos_str (TRIM (UPPER (vimportcode)), lv_tmp) BETWEEN 1 AND 4;

    IF ln_tmp = 1 THEN
     lv_tmp := TRIM (util_pg.get_param (lv_ret, 2, lv_separator));

     IF TO_NUMBER (lv_tmp) > 0 AND TO_NUMBER (lv_tmp) <= 31 THEN
      lv_tmp := TRIM (lv_basemonth) || TRIM (lv_tmp);
      ld_date := TO_DATE (lv_tmp, 'YYMMDD');
      cn_cnt := 24;
      ln_factcnt := util_pg.get_count_dt (ld_date, 1 / cn_cnt);
      --Обнулили макс дату
      ld_max := ld_date - 1;

      --Очистили
      FOR i IN 1 .. ln_factcnt * 4 LOOP
       lt_e (i) := NULL;
      END LOOP;

      FOR j IN 1 .. ln_factcnt LOOP
       ln_col := 2 + j;   -- ???
       ln_e := REPLACE (util_pg.get_param (lv_ret, 3 + j, lv_separator), ',', '.');   -- меняем запятую на точку

       IF ln_e < 0 THEN   --Если <0 то инвертируем.
        IF ln_type IN (1, 3) THEN
         ln_tmptype := ln_type + 1;
        ELSE
         ln_tmptype := ln_type - 1;
        END IF;

        ln_e := -ln_e;
       ELSE
        ln_tmptype := ln_type;
       END IF;

       lt_e (ln_factcnt * (ln_tmptype - 1) + j) := ln_e;

       IF ln_e IS NOT NULL THEN
        ld_max := ld_date + j / cn_cnt;
       END IF;
      END LOOP;
     END IF;
    END IF;
   END LOOP;

   ln_str := 1;
   ln_col := 1;

   --А теперь 24 часа раскинем на 48 получасовок (или 25 в 50)
   FOR i IN REVERSE 1 .. 4 * ln_factcnt LOOP
    lt_e (2 * i) := TRUNC (lt_e (i) / 2, ln_rn);
    lt_e (2 * i - 1) := lt_e (i) - lt_e (2 * i);
   END LOOP;

   --А теперь у нас всего больше в 2 раза стало
   cn_cnt := 2 * cn_cnt;
   ln_factcnt := util_pg.get_count_dt (ld_date, 1 / cn_cnt);

   -- И записываем в БД
   FOR j IN 1 .. ln_factcnt LOOP
    --Если есть цифры
    IF lt_e (j) IS NOT NULL OR lt_e (1 * ln_factcnt + j) IS NOT NULL OR lt_e (2 * ln_factcnt + j) IS NOT NULL OR lt_e (3 * ln_factcnt + j) IS NOT NULL THEN
     IF ln_factcnt > cn_cnt AND j > (cn_cnt / 24) * (util_pg.switch_f + 1) AND j <= cn_cnt THEN   --больше времени сдвига добавяем час
      ln_shift := 1 / 24;
     ELSIF j > cn_cnt THEN
      ln_shift := -1 + (util_pg.switch_f + 1) / 24;
     ELSE
      ln_shift := 0;
     END IF;

     das_pg.insert_hf_in_profile (lc.mid, util_pg.to_unlocaltime_if_new (ld_date) + j / cn_cnt + ln_shift, 24 * 60 / cn_cnt, lt_e (j), lt_e (1 * ln_factcnt + j),
                                  lt_e (2 * ln_factcnt + j), NULL, lt_e (3 * ln_factcnt + j), NULL, ln_rn);
     inshalfhour (lc.mid, util_pg.to_unlocaltime_if_new (ld_date) + j / cn_cnt + ln_shift, lt_e (j), lt_e (1 * ln_factcnt + j), lt_e (2 * ln_factcnt + j),
                  lt_e (3 * ln_factcnt + j));
    END IF;
   END LOOP;

   IF util_pg.get_customer_id <> 1 AND ld_max > ld_date THEN
    editfeeders_pg.ins_last_save (lc.mid);

    UPDATE last_save
       SET halfhour = ld_max,
           state_date = SYSDATE,
           state_cod = 0,
           clock = 0
     WHERE mid = lc.mid;
   END IF;
  END LOOP;

  UPDATE last_save
     SET halfhour = GREATEST (ld_date + 1, NVL (halfhour, ld_date + 1))
   WHERE mid = an_cid;

  DELETE FROM textreport;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001, 'comsrvfile_pg.l_30902: ' || 'Ошибка загрузки данных (стр. ' || ln_str || ', столб. ' || ln_col || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 -- Процедура отметки о копировании файла
 PROCEDURE mark_copy_files (an_cid NUMBER, av_filename VARCHAR2, av_filedate DATE) IS
 BEGIN
  INSERT INTO copyfiles
              (cid, vfilename, dfiledate
              )
       VALUES (an_cid, av_filename, av_filedate
              );
 EXCEPTION
  WHEN DUP_VAL_ON_INDEX THEN
   NULL;
  WHEN OTHERS THEN
   raise_application_error (-20001, 'comsrvfile_pg.mark_copy_files: ' || SQLERRM (SQLCODE));
 END;
------------------------------------------------------------------------------------------------------------------------
BEGIN
 IF util_pg.get_customer_id = 1 THEN
  gn_source := 20;
 ELSE
  gn_source := comsrv_pg.cn_auto;
 END IF;
------------------------------------------------------------------------------------------------------------------------
END;   -- Package Body COMSRVFILE_PG
/


