CREATE OR REPLACE 
PACKAGE BODY comsrvuppd_pg IS
------------------------------------------------------------------------------------------------------------------------
    -- Интерфейс взаимодействия БД с Носиком А.В. для УППД
    -- дата создания 23/11/2005 Сечин А.А.
------------------------------------------------------------------------------------------------------------------------
 --Возвращает следующую точку по каналу с ид.>an_mid (maket)
 FUNCTION get_next_point (an_channel NUMBER,   --Ид канала опроса
                                            an_group NUMBER,   --Ид точки maketgroups.ngroup
                                                            av_code OUT VARCHAR2,   --Код точки maketgroups.vcode (Код канала в терминах УППД)
 av_name OUT VARCHAR2   --Наименование точки maketgroups.vname (Для отображения)
 )
  RETURN NUMBER IS
  ln_maket   NUMBER;
  ln_id      NUMBER;
 BEGIN
  --Найдем ид макета
  SELECT util_pg.allnumber_f (TRIM (util_pg.get_param (MAX (init_str), 5)))
    INTO ln_maket
    FROM channels
   WHERE cid = an_channel;

  --Найдем все остальное
  SELECT MAX (ngroup), MAX (vcode), MAX (vname)
    INTO ln_id, av_code, av_name
    FROM maketgroups
   WHERE nmaket = ln_maket AND ngroup = (SELECT MIN (ngroup)
                                           FROM maketgroups
                                          WHERE ngroup > an_group AND nmaket = ln_maket);

  RETURN NVL (ln_id, 0);
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20001, 'comsrvuppd_pg.get_next_point: ' || SQLERRM (SQLCODE));
 END;

-----------------------------------------------------------------------------------------------------------------------
 --Возвращает данные ГН по точке
 PROCEDURE get_datalp (an_group NUMBER,   --Ид точки maketgroups.ngroup
                                       ad_date DATE,   --Дата, за которую необходимо получить информацию
 at_data OUT common_pg.tt_number   --Массив данных (23, 24 или 25 значений)
 ) IS
  ln_maket            NUMBER;
  ln_sign             NUMBER;
  ln_groupcode        NUMBER;
  ln_subgroupcode     NUMBER;
  ln_temp             NUMBER;
  ln_count            NUMBER;   -- кол-во часов в сутках
  ln_null             NUMBER DEFAULT 1;
  ln_needround30817   NUMBER;
 BEGIN
  ln_count := 24 - util_pg.is_dayswitch (ad_date);

  FOR i IN 1 .. ln_count LOOP
   at_data (i) := NULL;
  END LOOP;

  --Найдем ид макета
  SELECT MAX (nmaket)
    INTO ln_maket
    FROM maketgroups
   WHERE ngroup = an_group;

  IF ln_maket IS NULL THEN
   RETURN;
  END IF;

  -- Чистим временные таблицы
  DELETE FROM m30817;

  DELETE FROM makettemp;

  -- Выборка в рабочую таблицу формул расчета агрегированных макетных строк
  INSERT INTO makettemp
              (ngroup, nsubgroup, nsign)
   SELECT ngroup, nsubgroup, nsign
     FROM maketformulas
    WHERE ngroup IN (SELECT ngroup
                       FROM maketgroups
                      WHERE nmaket = ln_maket);

  -- В рабочей таблице проставляются ид всех строк макета, кроме агрегированных
  INSERT INTO m30817
              (ngroup, HOUR, kwh, err)
   SELECT ngroup, 0, DECODE (ln_null, 0, 0, NULL), 0
     FROM maketgroups
    WHERE nmaket = ln_maket AND ngroup NOT IN (SELECT ngroup
                                                 FROM makettemp);

  -- По тем строкам, где есть данные рассчитываются и сохраняются расходы без 25 часа
  INSERT INTO m30817
              (ngroup, HOUR, kwh)
   SELECT   p.ngroup, TO_CHAR (date_time - 1 / 1440, 'hh24') + 1,
            SUM (p.nkc
                 * DECODE (ntype,
                           1, h.er,
                           2, h.ed,
                           3, h.q1,
                           4, h.q3,
                           5, util_pg.sld (h.mid, NVL (h.er, 0), NVL (h.ed, 0)),
                           6, util_pg.sld (h.mid, NVL (h.q1, 0), NVL (h.q3, 0))
                          ))
       FROM maketgroups g, maketpoints p, halfhour h
      WHERE g.nmaket = ln_maket AND g.ngroup NOT IN (SELECT ngroup
                                                       FROM makettemp) AND p.ngroup = g.ngroup AND h.mid = p.mid AND h.date_time > TRUNC (ad_date)
            AND h.date_time <= TRUNC (ad_date) + 1 AND h.nsource NOT IN (19, 29, 39, 49, 59)
   GROUP BY p.ngroup, TO_CHAR (date_time - 1 / 1440, 'hh24');

  -- Отдельно сохраняется 25 час, помеченный кодом источника 19
  IF ln_count = 25 THEN
   INSERT INTO m30817
               (ngroup, HOUR, kwh)
    SELECT   p.ngroup, 25,
             SUM (p.nkc
                  * DECODE (ntype,
                            1, h.er,
                            2, h.ed,
                            3, h.q1,
                            4, h.q3,
                            5, util_pg.sld (h.mid, NVL (h.er, 0), NVL (h.ed, 0)),
                            6, util_pg.sld (h.mid, NVL (h.q1, 0), NVL (h.q3, 0))
                           ))
        FROM maketgroups g, maketpoints p, halfhour h
       WHERE g.nmaket = ln_maket AND g.ngroup NOT IN (SELECT ngroup
                                                        FROM makettemp) AND p.ngroup = g.ngroup AND h.mid = p.mid AND h.date_time > TRUNC (ad_date)
             AND h.date_time <= TRUNC (ad_date) + 1 AND h.nsource IN (19, 29, 39, 49, 59)
    GROUP BY p.ngroup;
  END IF;

  -- По строкам, где не оказалось данных проставляются нули
  FOR i IN 1 .. ln_count LOOP
   INSERT INTO m30817
               (ngroup, HOUR, kwh, err)
    (SELECT ngroup, i, DECODE (ln_null, 0, 0, NULL), 0
       FROM m30817
      WHERE HOUR = 0
     MINUS
     SELECT ngroup, i, DECODE (ln_null, 0, 0, NULL), 0
       FROM m30817
      WHERE HOUR = i);
  END LOOP;

  -- Округление с учетом ошибки предыдущего шага, запись ошибки текущего шага
  ln_needround30817 := util_pg.needround30817_f;

  FOR i IN 1 .. ln_count LOOP
   UPDATE m30817 m
      SET (kwh, err) = (SELECT ROUND (a.kwh + b.err + NVL (c.err, 0)), NVL (a.kwh, 0) + b.err + NVL (c.err, 0) - ROUND (NVL (a.kwh, 0) + b.err + NVL (c.err, 0))
                          FROM m30817 a,
                               m30817 b,
                               (SELECT me.ngroup, DECODE (ln_needround30817, 1, me.err, 0) err
                                  FROM maketerr me
                                 WHERE i = 1 AND me.ddate = TRUNC (ad_date) - 1) c
                         WHERE a.ngroup = b.ngroup AND a.HOUR = b.HOUR + 1 AND a.ngroup = m.ngroup AND a.HOUR = i AND a.ngroup = c.ngroup(+))
    WHERE HOUR = i;
  END LOOP;

  --Запоминаем остатки округления на след день
  IF ln_needround30817 = 1 THEN
   DELETE FROM maketerr
         WHERE ddate = TRUNC (ad_date) AND ngroup IN (SELECT ngroup
                                                        FROM m30817);

   INSERT INTO maketerr
               (ngroup, ddate, err)
    SELECT ngroup, TRUNC (ad_date), err
      FROM m30817
     WHERE HOUR = ln_count;
  END IF;

  -- В рабочей таблице проставляются ид агрегированных строк и все часы суток
  FOR i IN 0 .. ln_count LOOP
   INSERT INTO m30817
               (ngroup, HOUR, kwh)
    SELECT ngroup, i, DECODE (ln_null, 0, 0, NULL)
      FROM maketgroups
     WHERE nmaket = ln_maket AND ngroup IN (SELECT ngroup
                                              FROM makettemp);
  END LOOP;

  LOOP
   -- Выбираем из рабочей таблицы очередную составляющую агрегированной строки или выходим, если таблица пуста
   BEGIN
    SELECT ngroup, nsubgroup, nsign
      INTO ln_groupcode, ln_subgroupcode, ln_sign
      FROM makettemp
     WHERE nsubgroup NOT IN (SELECT ngroup
                               FROM makettemp) AND ROWNUM = 1;
   EXCEPTION
    WHEN NO_DATA_FOUND THEN
     EXIT;
   END;

   -- Расчет и аккумулирование составляющей в агрегированной строке
   FOR i IN 1 .. ln_count LOOP
    BEGIN
     SELECT ln_sign * kwh
       INTO ln_temp
       FROM m30817
      WHERE ngroup = ln_subgroupcode AND HOUR = i;
    EXCEPTION
     WHEN NO_DATA_FOUND THEN
      IF ln_null = 0 THEN
       ln_temp := 0;
      ELSE
       ln_temp := NULL;
      END IF;
    END;

    UPDATE m30817
       SET kwh = util_pg.sumn (kwh, ln_temp)
     WHERE ngroup = ln_groupcode AND HOUR = i;
   END LOOP;

   -- удаляем из временной таблицы обработанную составляющую
   DELETE FROM makettemp
         WHERE ngroup = ln_groupcode AND nsubgroup = ln_subgroupcode;
  END LOOP;

  -- По всем строкам считается расход за сутки
  UPDATE m30817 m
     SET kwh = (SELECT SUM (kwh)
                  FROM m30817
                 WHERE ngroup = m.ngroup)
   WHERE HOUR = 0;

  FOR i IN 1 .. ln_count LOOP
   SELECT SUM (kwh)
     INTO at_data (i)
     FROM m30817
    WHERE ngroup = an_group AND HOUR = i;
  END LOOP;

  -- Чистим временные таблицы
  DELETE FROM m30817;

  DELETE FROM makettemp;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20001, 'comsrvuppd_pg.get_datalp: ' || SQLERRM (SQLCODE));
 END;

-----------------------------------------------------------------------------------------------------------------------
 --Возвращает данные Энергии по точке
 PROCEDURE get_dataen (an_group NUMBER,   --Ид точки maketgroups.ngroup
                                       ad_date DATE,   --Дата, за которую необходимо получить информацию
 at_data OUT common_pg.tt_number   --Массив данных (5 значений суммарное, пик, день, ночь, резерв)
 ) IS
 BEGIN
  FOR i IN 1 .. 5 LOOP
   at_data (i) := NULL;
  END LOOP;
 --Напишу когда надо будет
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20001, 'comsrvuppd_pg.get_dataen: ' || SQLERRM (SQLCODE));
 END;

-----------------------------------------------------------------------------------------------------------------------
   --Записывает данные ГН по точке
 PROCEDURE set_datalp (an_cid NUMBER,   --Ид канала channels.cid
                                     ad_date DATE,   --Дата
                                                  an_obj NUMBER,   --Ид. объекта
                                                                an_channel NUMBER,   --Ид. канала
                                                                                  an_step NUMBER,   --Шаг профиля в минутах
                                                                                                 at_data common_pg.tt_number   --Массив данных
 ) IS
  lt_e       common_pg.tt_number;
  lv_obj     VARCHAR2 (256);
  ln_cid     NUMBER;
  ln_mid     NUMBER;
  ln_tmp     NUMBER;
  ln_block   NUMBER;
  ln_type    NUMBER;
  ld_max     DATE;
  ld_date    DATE                DEFAULT TRUNC (ad_date);
 BEGIN
  --    raise_application_error(-20001, an_cid||';'||ad_date||';'||an_obj||';'||an_channel||';'||an_step||';'||at_data.count);
  --5779;04.06.06;3025;78;60;24

  --Найдем ид канала
  SELECT     NVL (MAX (cid), 0)
        INTO ln_cid
        FROM channels
       WHERE util_pg.allnumber_f (TRIM (util_pg.get_param (init_str, 2))) = an_obj
  CONNECT BY PRIOR cid = nparent
  START WITH cid = an_cid;

  IF ln_cid = 0 OR at_data.COUNT = 0 THEN   --не то объект
   RETURN;
  END IF;

  SELECT MAX (mid), COUNT (*), MAX (nblock), MAX (util_pg.get_pos_str (TRIM (UPPER (vimportcode)), an_channel))
    INTO ln_mid, ln_tmp, ln_block, ln_type
    FROM feeders
   WHERE mid IN (SELECT mid
                   FROM chanpoint
                  WHERE cid = ln_cid) AND util_pg.get_pos_str (TRIM (UPPER (vimportcode)), an_channel) BETWEEN 1 AND 4;

  IF NOT (ln_tmp = 1 AND ln_block = 0) THEN
   RETURN;
  END IF;

  ld_max := ld_date - 1;

  --Поискали нужные строки
  FOR i IN 1 .. at_data.COUNT LOOP
   --Очистили
   FOR j IN 1 .. 4 LOOP
    lt_e (j) := NULL;
   END LOOP;

   IF ln_type = 1 AND at_data (i) >= 0 THEN
    lt_e (1) := at_data (i);
   ELSIF ln_type = 2 AND at_data (i) >= 0 THEN
    lt_e (2) := at_data (i);
   ELSIF ln_type = 3 AND at_data (i) >= 0 THEN
    lt_e (3) := at_data (i);
   ELSIF ln_type = 4 AND at_data (i) >= 0 THEN
    lt_e (4) := at_data (i);
   ELSIF ln_type = 1 AND at_data (i) < 0 THEN
    lt_e (2) := -at_data (i);
   ELSIF ln_type = 2 AND at_data (i) < 0 THEN
    lt_e (1) := -at_data (i);
   ELSIF ln_type = 3 AND at_data (i) < 0 THEN
    lt_e (4) := -at_data (i);
   ELSIF ln_type = 4 AND at_data (i) < 0 THEN
    lt_e (3) := -at_data (i);
   END IF;

   IF lt_e (1) IS NOT NULL OR lt_e (2) IS NOT NULL OR lt_e (3) IS NOT NULL OR lt_e (4) IS NOT NULL THEN
    IF an_step = 60 THEN
     das_pg.ins_halfhourtmp (ln_mid, util_pg.to_unlocaltime_if_new (ld_date) + (i * an_step - 30) / 1440, NULL, TRUNC (lt_e (1) / 2), TRUNC (lt_e (2) / 2),
                             TRUNC (lt_e (3) / 2), TRUNC (lt_e (4) / 2), NULL, NULL, NULL, comsrv_pg.cn_uppd, NULL);
     das_pg.ins_halfhourtmp (ln_mid, util_pg.to_unlocaltime_if_new (ld_date) + i * an_step / 1440, NULL, lt_e (1) - TRUNC (lt_e (1) / 2),
                             lt_e (2) - TRUNC (lt_e (2) / 2), lt_e (3) - TRUNC (lt_e (3) / 2), lt_e (4) - TRUNC (lt_e (4) / 2), NULL, NULL, NULL, comsrv_pg.cn_uppd,
                             NULL);
    ELSE
     das_pg.ins_halfhourtmp (ln_mid, util_pg.to_unlocaltime_if_new (ld_date) + i * an_step / 1440, NULL, lt_e (1), lt_e (2), lt_e (3), lt_e (4), NULL, NULL, NULL,
                             comsrv_pg.cn_uppd, NULL);
    END IF;

    ld_max := util_pg.to_unlocaltime_if_new (ld_date) + i * an_step / 1440;
   END IF;
  END LOOP;

  IF ld_max > ld_date THEN
   editfeeders_pg.ins_last_save (ln_mid);

   UPDATE last_save
      SET halfhour = ld_max,
          state_date = SYSDATE,
          state_cod = 0,
          clock = 0
    WHERE mid = ln_mid;
  END IF;

  COMMIT;
  das_pg.checkhalfhour_without_err;
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001, 'comsrvuppd_pg.set_datalp: ' || SQLERRM (SQLCODE));
 END;
-----------------------------------------------------------------------------------------------------------------------
END;   -- Package Body comsrvuppd_pg
/


-- End of DDL Script for Package Body RYDA.COMSRVUPPD_PG

