CREATE OR REPLACE 
PACKAGE BODY das_pg IS
-- Пакет Сервера сбора данных.
--
-- MODIFICATION HISTORY
-- Person      Date     Comments
-- ---------   -------- ------------------------------------------
-- Вештак      24.11.02 Создан
-- Сечин       05.04.03 Модификация
-- Вештак      23.05.03 Процедуры закрытия и отката расчетных суток
-- Сечин       24.09.03 Модификация Процедуры закрытия и отката расчетных суток (откат на несколько дней)
---------------------------------------------------------------------------------------
---------------      Interface        -------------------------------------------------
---------------------------------------------------------------------------------------
 cn_lock                 CONSTANT NUMBER := 30;
 cn_calcpointtype_cons   CONSTANT NUMBER := 1;   --Расчет по установленной мощности
 cn_calcpointtype_amm    CONSTANT NUMBER := 2;   --Расчет по среднемесячному расходу
 cn_calcpointtype_sum    CONSTANT NUMBER := 5;   --Расчетная точка (как сумма по группе)

---------------------------------------------------------------------------------------
 PROCEDURE rollbackperiod;

 PROCEDURE closeperiod;

 PROCEDURE correchalfhourtime;

 PROCEDURE correchalfhourtime (an_mid NUMBER);

 PROCEDURE checkhalfhour_old (an_commit NUMBER);

 PROCEDURE checkhalfhour_new (an_commit NUMBER);

 PROCEDURE replicator (ad_date DATE);

---------------------------------------------------------------------------------------
---------------      Implementation   -------------------------------------------------
---------------------------------------------------------------------------------------
 PROCEDURE calcday4bill IS
 BEGIN
  calconeday4bill (-1, TRUNC (SYSDATE) - 1);
  COMMIT;
 END;

---------------------------------------------------------------------------------------
 PROCEDURE calconeday4bill (an_maket NUMBER, dday DATE) IS
 BEGIN
  INSERT INTO bill_calc
              (mid, date_time)
   SELECT DISTINCT mid, TRUNC (date_time - 1 / 100) + 1
              FROM halfhourold
             WHERE nexceptcalc IS NULL
                                      --               AND dclosed IS NULL
                   AND date_time > LEAST (SYSDATE - 20, TRUNC (dday)) AND date_time <= GREATEST (TRUNC (dday) + 1, TRUNC (SYSDATE));

  --AND date_time <= TRUNC(dday) + 1;
  IF util_pg.newhalfhour_f = 0 AND util_pg.is_dayswitch (TRUNC (dday)) = 1 THEN
   correchalfhour (TRUNC (dday), NULL);
  END IF;

  processbillcalc;
 END;

---------------------------------------------------------------------------------------
 PROCEDURE calcperiod4bill (dstart DATE, dend DATE) IS
 BEGIN
  INSERT INTO bill_calc
              (mid, date_time)
   SELECT DISTINCT mid, TRUNC (date_time) + 1
              FROM halfhourold
             WHERE nexceptcalc IS NULL AND date_time > TRUNC (dstart) AND date_time <= TRUNC (dend);

  processbillcalc;
 END;

---------------------------------------------------------------------------------------
 PROCEDURE calcpoint4bill (nmid NUMBER, dstart DATE, dend DATE) IS
 BEGIN
  INSERT INTO bill_calc
              (mid, date_time)
   SELECT DISTINCT mid, TRUNC (date_time) + 1
              FROM halfhourold
             WHERE mid = nmid AND date_time > TRUNC (dstart) - 1 AND date_time <= TRUNC (dend) + 1;

  processbillcalc;
 END;

---------------------------------------------------------------------------------------
 PROCEDURE processbillcalc IS
  rid_     NUMBER;
  ln_dif   NUMBER;
 BEGIN
  SAVEPOINT processbillcalc_sp;

  DELETE FROM bill
        WHERE (mid, date_time) IN (SELECT mid, date_time
                                     FROM bill_calc);

  ln_dif := util_pg.stephalfhour_f / 1440;

  FOR cc IN (SELECT DISTINCT date_time
                        FROM bill_calc
                    ORDER BY date_time) LOOP
   SELECT MAX (rid)
     INTO rid_
     FROM rate_list
    WHERE switch_date = (SELECT MAX (switch_date)
                           FROM rate_list
                          WHERE switch_date < cc.date_time);

   IF rid_ IS NULL THEN
    raise_application_error (-20002, 'DAS_PG.ProcessBillCalc: Не задано расписание тарифных зон на ' || TO_CHAR (cc.date_time, 'dd.mm.yyyy') || '.');
   END IF;

   INSERT INTO bill
               (mid, date_time, nsource, SOURCE, er, aer, ber, cer, der, ed, aed, bed, ced, ded, q1, aq1, bq1, cq1, dq1, q2, aq2, bq2, cq2, dq2, q3, aq3, bq3, cq3,
                dq3, q4, aq4, bq4, cq4, dq4, er_kc, q1_kc, ed_kc, q3_kc, vqm)
    (SELECT   h.mid, cc.date_time, 10, 'Расч', SUM (NVL (er, 0)) ers, SUM (DECODE (rate, 0, er, 0)) aers, SUM (DECODE (rate, 1, er, 0)) bers,
              SUM (DECODE (rate, 2, er, 0)) cers, SUM (DECODE (rate, 3, er, 0)) ders, SUM (NVL (ed, 0)) eds, SUM (DECODE (rate, 0, ed, 0)) aeds,
              SUM (DECODE (rate, 1, ed, 0)) beds, SUM (DECODE (rate, 2, ed, 0)) ceds, SUM (DECODE (rate, 3, ed, 0)) deds, SUM (NVL (q1, 0)) q1s,
              SUM (DECODE (rate, 0, q1, 0)) aq1s, SUM (DECODE (rate, 1, q1, 0)) bq1s, SUM (DECODE (rate, 2, q1, 0)) cq1s, SUM (DECODE (rate, 3, q1, 0)) dq1s,
              SUM (NVL (q2, 0)) q2s, SUM (DECODE (rate, 0, q2, 0)) aq2s, SUM (DECODE (rate, 1, q2, 0)) bq2s, SUM (DECODE (rate, 2, q2, 0)) cq2s,
              SUM (DECODE (rate, 3, q2, 0)) dq2s, SUM (NVL (q3, 0)) q3s, SUM (DECODE (rate, 0, q3, 0)) aq3s, SUM (DECODE (rate, 1, q3, 0)) bq3s,
              SUM (DECODE (rate, 2, q3, 0)) cq3s, SUM (DECODE (rate, 3, q3, 0)) dq3s, SUM (NVL (q4, 0)) q4s, SUM (DECODE (rate, 0, q4, 0)) aq4s,
              SUM (DECODE (rate, 1, q4, 0)) bq4s, SUM (DECODE (rate, 2, q4, 0)) cq4s, SUM (DECODE (rate, 3, q4, 0)) dq4s, AVG (h.nkc), AVG (h.nkc), AVG (h.nkc),
              AVG (h.nkc),
              DECODE (COUNT (DISTINCT util_pg.trunc_d (h.date_time - 1 / 86400, ln_dif)),
                      ROUND (1 / ln_dif), NVL (sumqm (NVL (h.vqm, qm_pg.defqm)), qm_pg.defqm),
                      qm_pg.sumqm (NVL (sumqm (NVL (h.vqm, qm_pg.defqm)), qm_pg.defqm), qm_pg.defqm)
                     ) qm
         FROM halfhour h, rates r
        WHERE h.mid IN (SELECT mid
                          FROM bill_calc
                         WHERE date_time = cc.date_time) AND h.date_time > cc.date_time - 1 AND h.date_time <= cc.date_time AND r.rid = rid_
              AND TO_CHAR (h.date_time - 1 / 1440, 'sssss') >= TO_CHAR (r.TIME, 'sssss') AND TO_CHAR (h.date_time - 1 / 1440, 'sssss') < TO_CHAR (r.endtime, 'sssss')
     GROUP BY h.mid);
  END LOOP;

  DELETE FROM bill_calc;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT processbillcalc_sp;
   RAISE;
 END;

---------------------------------------------------------------------------------------
 PROCEDURE closeperiod (an_maket IN NUMBER, ddate_ IN DATE) IS
  ln_dif    NUMBER;
  ld_date   DATE   DEFAULT LEAST (TRUNC (ddate_), TRUNC (SYSDATE) - 1);
 BEGIN
  IF admin_pg.lock_p (cn_lock, 'halfhourtmp') <> 1 THEN
   raise_application_error (-20009, 'Закрытие периода не может быть проведено ввиду отсутствия возможности блокировки таблицы в течении ' || cn_lock || ' сек.',
                            TRUE);
  END IF;

  IF ld_date = admin_pg.get_calcperiod - 1 THEN   --Если второй раз закрываем одно и тоже, то
   rollbackperiod (an_maket, ld_date, 0);
  END IF;

  ln_dif := TRUNC (ld_date) - LEAST (TRUNC (NVL (admin_pg.get_calcperiod, SYSDATE)), TRUNC (SYSDATE)) + 1;

  FOR i IN 1 .. ln_dif LOOP
   closeperiod;
   loss_replacement_pg.run (TO_CHAR (admin_pg.get_calcperiod - 1, 'yyyymmdd'), 0);
  END LOOP;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   RAISE;
 END;

---------------------------------------------------------------------------------------
 PROCEDURE closeperiod IS
  ln_dif          NUMBER;
  ln_qm           NUMBER;
  ld_calcperiod   DATE;
  rid_            NUMBER;
  erw             NUMBER;
  edw             NUMBER;
  q1w             NUMBER;
  q3w             NUMBER;

  -- Add KAS
  CURSOR lc_selmid IS
   SELECT mid
     FROM points
    WHERE mid IN
           (1068,
            1116,
            1118,
            1156,
            1170,
            1196,
            1760,
            1766,
            1772,
            1778,
            1900,
            1901,
            1902,
            1906,
            1908,
            1910,
            1912,
            1914,
            1916,
            1929,
            1931,
            1932,
            1934,
            1936,
            1939,
            1941,
            1943,
            1948,
            1950,
            1952,
            1954,
            1956,
            1958,
            1960,
            1962,
            1963,
            1965,
            1967,
            1969,
            1971,
            1972,
            1974,
            1976,
            1978,
            1980,
            1982
           );
 -- end add
 BEGIN
  ld_calcperiod := admin_pg.get_calcperiod;

  IF ld_calcperiod = TRUNC (SYSDATE) THEN
   rollbackperiod;
   ld_calcperiod := ld_calcperiod - 1;
  ELSIF ld_calcperiod > TRUNC (SYSDATE) THEN
   RETURN;
  END IF;

  replicator (ld_calcperiod);   --Расчет ручников
  calcformula_pg.calc (ld_calcperiod);

  IF util_pg.get_customer_id = 2 AND util_pg.is_dayswitch (ld_calcperiod) <> 1 THEN
   FOR lc IN lc_selmid LOOP
    correchalfhour (ld_calcperiod, lc.mid);
   END LOOP;
  ELSIF util_pg.is_dayswitch (ld_calcperiod) = 1 AND util_pg.newhalfhour_f = 0 AND util_pg.get_customer_id <> 7 THEN
   correchalfhour (ld_calcperiod, NULL);
  END IF;

  SELECT MAX (rid)
    INTO rid_
    FROM rate_list
   WHERE switch_date = (SELECT MAX (switch_date)
                          FROM rate_list
                         WHERE switch_date < ld_calcperiod);

  IF rid_ IS NULL THEN
   raise_application_error (-20002, 'DAS_PG.ProcessBillCalc: Не задано расписание тарифных зон на ' || TO_CHAR (ld_calcperiod, 'dd.mm.yyyy') || '.');
  END IF;

  -- Считаем потери
  pointcalc_pg.calcloss (ld_calcperiod);

  -- Помечаем актуальные измерения получасовок в закрывающихся сутках
  UPDATE halfhourold
     SET dclosed = date_time
   WHERE nexceptcalc IS NULL AND date_time > ld_calcperiod AND date_time <= ld_calcperiod + 1;

  -- Расчет и разноска по зонам суточных расходов
  BEGIN
   DELETE FROM billold
         WHERE date_time = ld_calcperiod + 1;   --saa 17.06.2005

   INSERT INTO billold
               (mid, date_time, dclosed, nexceptcalc, SOURCE, nsource, er, aer, ber, cer, der, ed, aed, bed, ced, ded, q1, aq1, bq1, cq1, dq1, q2, aq2, bq2, cq2,
                dq2, q3, aq3, bq3, cq3, dq3, q4, aq4, bq4, cq4, dq4, er_kc, q1_kc, ed_kc, q3_kc)
    (SELECT   h.mid, ld_calcperiod + 1, ld_calcperiod + 1, NULL, 'Расч', SUM (nsource), SUM (NVL (er, 0)) ers, SUM (DECODE (rate, 0, er, 0)) aers,
              SUM (DECODE (rate, 1, er, 0)) bers, SUM (DECODE (rate, 2, er, 0)) cers, SUM (DECODE (rate, 3, er, 0)) ders, SUM (NVL (ed, 0)) eds,
              SUM (DECODE (rate, 0, ed, 0)) aeds, SUM (DECODE (rate, 1, ed, 0)) beds, SUM (DECODE (rate, 2, ed, 0)) ceds, SUM (DECODE (rate, 3, ed, 0)) deds,
              SUM (NVL (q1, 0)) q1s, SUM (DECODE (rate, 0, q1, 0)) aq1s, SUM (DECODE (rate, 1, q1, 0)) bq1s, SUM (DECODE (rate, 2, q1, 0)) cq1s,
              SUM (DECODE (rate, 3, q1, 0)) dq1s, SUM (NVL (q2, 0)) q2s, SUM (DECODE (rate, 0, q2, 0)) aq2s, SUM (DECODE (rate, 1, q2, 0)) bq2s,
              SUM (DECODE (rate, 2, q2, 0)) cq2s, SUM (DECODE (rate, 3, q2, 0)) dq2s, SUM (NVL (q3, 0)) q3s, SUM (DECODE (rate, 0, q3, 0)) aq3s,
              SUM (DECODE (rate, 1, q3, 0)) bq3s, SUM (DECODE (rate, 2, q3, 0)) cq3s, SUM (DECODE (rate, 3, q3, 0)) dq3s, SUM (NVL (q4, 0)) q4s,
              SUM (DECODE (rate, 0, q4, 0)) aq4s, SUM (DECODE (rate, 1, q4, 0)) bq4s, SUM (DECODE (rate, 2, q4, 0)) cq4s, SUM (DECODE (rate, 3, q4, 0)) dq4s,
              AVG (h.nkc), AVG (h.nkc), AVG (h.nkc), AVG (h.nkc)
         FROM halfhourold h, rates r
        WHERE h.nexceptcalc IS NULL AND h.nsource > 0 AND h.date_time > ld_calcperiod AND h.date_time <= ld_calcperiod + 1 AND r.rid = rid_
              AND TO_CHAR (h.date_time - 1 / 1440, 'sssss') >= TO_CHAR (r.TIME, 'sssss') AND TO_CHAR (h.date_time - 1 / 1440, 'sssss') <
                                                                                                                                        TO_CHAR (r.endtime, 'sssss')
     GROUP BY h.mid);
  EXCEPTION
   WHEN OTHERS THEN
    raise_application_error (-20002, 'das_pg.closeperiod: Расчет и разноска по зонам суточных расходов: ' || SQLERRM (SQLCODE));
  END;

  -- Расчет и разноска по зонам суточных потерь
  BEGIN
   INSERT INTO billold
               (mid, date_time, dclosed, nexceptcalc, SOURCE, nsource, er, aer, ber, cer, der, ed, aed, bed, ced, ded, q1, aq1, bq1, cq1, dq1, q2, aq2, bq2, cq2,
                dq2, q3, aq3, bq3, cq3, dq3, q4, aq4, bq4, cq4, dq4, er_kc, q1_kc, ed_kc, q3_kc)
    (SELECT   h.mid, ld_calcperiod + 1, ld_calcperiod + 1, NULL, 'Расч', AVG (nsource), SUM (NVL (er, 0)) ers, SUM (DECODE (rate, 0, er, 0)) aers,
              SUM (DECODE (rate, 1, er, 0)) bers, SUM (DECODE (rate, 2, er, 0)) cers, SUM (DECODE (rate, 3, er, 0)) ders, SUM (NVL (ed, 0)) eds,
              SUM (DECODE (rate, 0, ed, 0)) aeds, SUM (DECODE (rate, 1, ed, 0)) beds, SUM (DECODE (rate, 2, ed, 0)) ceds, SUM (DECODE (rate, 3, ed, 0)) deds,
              SUM (NVL (q1, 0)) q1s, SUM (DECODE (rate, 0, q1, 0)) aq1s, SUM (DECODE (rate, 1, q1, 0)) bq1s, SUM (DECODE (rate, 2, q1, 0)) cq1s,
              SUM (DECODE (rate, 3, q1, 0)) dq1s, SUM (NVL (q2, 0)) q2s, SUM (DECODE (rate, 0, q2, 0)) aq2s, SUM (DECODE (rate, 1, q2, 0)) bq2s,
              SUM (DECODE (rate, 2, q2, 0)) cq2s, SUM (DECODE (rate, 3, q2, 0)) dq2s, SUM (NVL (q3, 0)) q3s, SUM (DECODE (rate, 0, q3, 0)) aq3s,
              SUM (DECODE (rate, 1, q3, 0)) bq3s, SUM (DECODE (rate, 2, q3, 0)) cq3s, SUM (DECODE (rate, 3, q3, 0)) dq3s, SUM (NVL (q4, 0)) q4s,
              SUM (DECODE (rate, 0, q4, 0)) aq4s, SUM (DECODE (rate, 1, q4, 0)) bq4s, SUM (DECODE (rate, 2, q4, 0)) cq4s, SUM (DECODE (rate, 3, q4, 0)) dq4s,
              AVG (h.nkc), AVG (h.nkc), AVG (h.nkc), AVG (h.nkc)
         FROM halfhourold h, rates r
        WHERE h.nexceptcalc IS NULL AND h.nsource < 0 AND h.date_time > ld_calcperiod AND h.date_time <= ld_calcperiod + 1 AND r.rid = rid_
              AND TO_CHAR (h.date_time - 1 / 1440, 'sssss') >= TO_CHAR (r.TIME, 'sssss') AND TO_CHAR (h.date_time - 1 / 1440, 'sssss') <
                                                                                                                                        TO_CHAR (r.endtime, 'sssss')
     GROUP BY h.mid);
  EXCEPTION
   WHEN OTHERS THEN
    raise_application_error (-20002, 'das_pg.closeperiod: Расчет и разноска по зонам суточных потерь: ' || SQLERRM (SQLCODE));
  END;

  -- Считаем потери
  FOR lc IN (SELECT mid, ddate
               FROM lagging_records
              WHERE mid IN (SELECT mid
                              FROM feeders
                             WHERE nwastepercentcalc <> 0)) LOOP
   pointcalc_pg.calcloss (lc.ddate, lc.mid);
  END LOOP;

  -- перерасчет измерений
  FOR c IN (SELECT mid, ddate
              FROM lagging_records) LOOP
   -- собственно перерасчет
   INSERT INTO halfhourold
               (mid, date_time, dclosed, nsource, nexceptcalc, er, ed, q1, q3, q2, q4)
    (SELECT c.mid, h.date_time, ld_calcperiod + (h.date_time - TRUNC (c.ddate)), (TO_CHAR (ld_calcperiod, 'yymmdd')), 1, err - erc, edr - edc, q1r - q1c, q3r - q3c,
            q2r - q2c, q4r - q4c
       FROM (SELECT   date_time, SUM (er) err, SUM (ed) edr, SUM (q1) q1r, SUM (q3) q3r, SUM (q2) q2r, SUM (q4) q4r
                 FROM halfhourold
                WHERE mid = c.mid AND nexceptcalc IS NULL AND nsource > 0 AND date_time > c.ddate AND date_time <= c.ddate + 1
             GROUP BY mid, date_time) h,
            (SELECT   date_time, SUM (er) erc, SUM (ed) edc, SUM (q1) q1c, SUM (q3) q3c, SUM (q2) q2c, SUM (q4) q4c
                 FROM halfhourold
                WHERE mid = c.mid AND dclosed IS NOT NULL AND nsource > 0 AND date_time > c.ddate AND date_time <= c.ddate + 1
             GROUP BY mid, date_time) hh
      WHERE h.date_time = hh.date_time);

   DELETE FROM halfhourold
         WHERE mid = c.mid AND dclosed > ld_calcperiod AND dclosed <= ld_calcperiod + 1 AND nsource > 5000 AND NVL (er, 0) = 0 AND NVL (ed, 0) = 0 AND NVL (q1, 0) =
                                                                                                                                                                    0
               AND NVL (q3, 0) = 0 AND NVL (q2, 0) = 0 AND NVL (q4, 0) = 0;

   -- чистка суточных
   DELETE FROM billold
         WHERE mid = c.mid AND dclosed IS NULL AND date_time > c.ddate AND date_time <= c.ddate + 1;

   UPDATE billold
      SET nexceptcalc = 1
    WHERE mid = c.mid AND nexceptcalc IS NULL AND date_time > c.ddate AND date_time <= c.ddate + 1;

   SELECT MAX (rid)
     INTO rid_
     FROM rate_list
    WHERE switch_date = (SELECT MAX (switch_date)
                           FROM rate_list
                          WHERE switch_date < c.ddate);

   -- Расчет и разноска по зонам суточных расходов
   BEGIN
    DELETE FROM billold
          WHERE mid = c.mid AND date_time = c.ddate + 1;   --saa 17.06.2005

    INSERT INTO billold
                (mid, date_time, dclosed, nexceptcalc, SOURCE, nsource, er, aer, ber, cer, der, ed, aed, bed, ced, ded, q1, aq1, bq1, cq1, dq1, q2, aq2, bq2, cq2,
                 dq2, q3, aq3, bq3, cq3, dq3, q4, aq4, bq4, cq4, dq4, er_kc, q1_kc, ed_kc, q3_kc)
     (SELECT   h.mid, c.ddate + 1, NULL, NULL, 'Расч', NVL (SUM (nsource), 0), SUM (NVL (er, 0)) ers, SUM (DECODE (rate, 0, er, 0)) aers,
               SUM (DECODE (rate, 1, er, 0)) bers, SUM (DECODE (rate, 2, er, 0)) cers, SUM (DECODE (rate, 3, er, 0)) ders, SUM (NVL (ed, 0)) eds,
               SUM (DECODE (rate, 0, ed, 0)) aeds, SUM (DECODE (rate, 1, ed, 0)) beds, SUM (DECODE (rate, 2, ed, 0)) ceds, SUM (DECODE (rate, 3, ed, 0)) deds,
               SUM (NVL (q1, 0)) q1s, SUM (DECODE (rate, 0, q1, 0)) aq1s, SUM (DECODE (rate, 1, q1, 0)) bq1s, SUM (DECODE (rate, 2, q1, 0)) cq1s,
               SUM (DECODE (rate, 3, q1, 0)) dq1s, SUM (NVL (q2, 0)) q2s, SUM (DECODE (rate, 0, q2, 0)) aq2s, SUM (DECODE (rate, 1, q2, 0)) bq2s,
               SUM (DECODE (rate, 2, q2, 0)) cq2s, SUM (DECODE (rate, 3, q2, 0)) dq2s, SUM (NVL (q3, 0)) q3s, SUM (DECODE (rate, 0, q3, 0)) aq3s,
               SUM (DECODE (rate, 1, q3, 0)) bq3s, SUM (DECODE (rate, 2, q3, 0)) cq3s, SUM (DECODE (rate, 3, q3, 0)) dq3s, SUM (NVL (q4, 0)) q4s,
               SUM (DECODE (rate, 0, q4, 0)) aq4s, SUM (DECODE (rate, 1, q4, 0)) bq4s, SUM (DECODE (rate, 2, q4, 0)) cq4s, SUM (DECODE (rate, 3, q4, 0)) dq4s,
               AVG (h.nkc), AVG (h.nkc), AVG (h.nkc), AVG (h.nkc)
          FROM halfhourold h, rates r
         WHERE mid = c.mid AND h.nexceptcalc IS NULL AND h.nsource > 0 AND h.nsource <= 5000 AND h.date_time > c.ddate AND h.date_time <= c.ddate + 1
               AND r.rid = rid_ AND TO_CHAR (h.date_time - 1 / 1440, 'sssss') >= TO_CHAR (r.TIME, 'sssss')
               AND TO_CHAR (h.date_time - 1 / 1440, 'sssss') < TO_CHAR (r.endtime, 'sssss')
      GROUP BY h.mid);
   EXCEPTION
    WHEN OTHERS THEN
     raise_application_error (-20002, 'das_pg.closeperiod: Расчет и разноска по зонам суточных расходов для отставших записей: ' || SQLERRM (SQLCODE));
   END;

   -- Расчет и разноска по зонам перерасчетов измерений
   BEGIN
    INSERT INTO billold
                (mid, date_time, dclosed, nexceptcalc, SOURCE, nsource, er, aer, ber, cer, der, ed, aed, bed, ced, ded, q1, aq1, bq1, cq1, dq1, q2, aq2, bq2, cq2,
                 dq2, q3, aq3, bq3, cq3, dq3, q4, aq4, bq4, cq4, dq4, er_kc, q1_kc, ed_kc, q3_kc)
     (SELECT   h.mid, c.ddate + 1, ld_calcperiod + 1, 1, 'Расч', AVG (nsource), SUM (NVL (er, 0)) ers, SUM (DECODE (rate, 0, er, 0)) aers,
               SUM (DECODE (rate, 1, er, 0)) bers, SUM (DECODE (rate, 2, er, 0)) cers, SUM (DECODE (rate, 3, er, 0)) ders, SUM (NVL (ed, 0)) eds,
               SUM (DECODE (rate, 0, ed, 0)) aeds, SUM (DECODE (rate, 1, ed, 0)) beds, SUM (DECODE (rate, 2, ed, 0)) ceds, SUM (DECODE (rate, 3, ed, 0)) deds,
               SUM (NVL (q1, 0)) q1s, SUM (DECODE (rate, 0, q1, 0)) aq1s, SUM (DECODE (rate, 1, q1, 0)) bq1s, SUM (DECODE (rate, 2, q1, 0)) cq1s,
               SUM (DECODE (rate, 3, q1, 0)) dq1s, SUM (NVL (q2, 0)) q2s, SUM (DECODE (rate, 0, q2, 0)) aq2s, SUM (DECODE (rate, 1, q2, 0)) bq2s,
               SUM (DECODE (rate, 2, q2, 0)) cq2s, SUM (DECODE (rate, 3, q2, 0)) dq2s, SUM (NVL (q3, 0)) q3s, SUM (DECODE (rate, 0, q3, 0)) aq3s,
               SUM (DECODE (rate, 1, q3, 0)) bq3s, SUM (DECODE (rate, 2, q3, 0)) cq3s, SUM (DECODE (rate, 3, q3, 0)) dq3s, SUM (NVL (q4, 0)) q4s,
               SUM (DECODE (rate, 0, q4, 0)) aq4s, SUM (DECODE (rate, 1, q4, 0)) bq4s, SUM (DECODE (rate, 2, q4, 0)) cq4s, SUM (DECODE (rate, 3, q4, 0)) dq4s,
               AVG (h.nkc), AVG (h.nkc), AVG (h.nkc), AVG (h.nkc)
          FROM halfhourold h, rates r
         WHERE mid = c.mid AND h.nsource > 5000   --= TO_CHAR(ld_calcperiod, 'yymmdd') --> 5000
                                               AND h.date_time > c.ddate AND h.date_time <= c.ddate + 1 AND r.rid = rid_
               AND TO_CHAR (h.date_time - 1 / 1440, 'sssss') >= TO_CHAR (r.TIME, 'sssss')
               AND TO_CHAR (h.date_time - 1 / 1440, 'sssss') < TO_CHAR (r.endtime, 'sssss')
      GROUP BY h.mid);
   EXCEPTION
    WHEN OTHERS THEN
     raise_application_error (-20002, 'das_pg.closeperiod: Перерасчет и разноска по зонам суточных расходов: ' || SQLERRM (SQLCODE));
   END;
  END LOOP;

  ----------А теперь рисуем метку качества
  ln_dif := util_pg.stephalfhour_f / 1440;

  FOR lc IN (SELECT   mid, ld_calcperiod + 1 date_time,
                      DECODE (COUNT (DISTINCT util_pg.trunc_d (h.date_time - 1 / 86400, ln_dif)),
                              ROUND (1 / ln_dif), NVL (sumqm (NVL (h.vqm, qm_pg.defqm)), qm_pg.defqm),
                              qm_pg.sumqm (NVL (sumqm (NVL (h.vqm, qm_pg.defqm)), qm_pg.defqm), qm_pg.defqm)
                             ) qm
                 FROM halfhour h
                WHERE h.date_time > ld_calcperiod AND h.date_time <= ld_calcperiod + 1
             GROUP BY mid) LOOP
   UPDATE bill
      SET vqm = lc.qm
    WHERE mid = lc.mid AND date_time = lc.date_time;
  END LOOP;

  FOR lc IN (SELECT mid, ddate
               FROM lagging_records) LOOP
   SELECT DECODE (COUNT (DISTINCT util_pg.trunc_d (h.date_time - 1 / 86400, ln_dif)),
                  ROUND (1 / ln_dif), NVL (sumqm (NVL (h.vqm, qm_pg.defqm)), qm_pg.defqm),
                  qm_pg.sumqm (NVL (sumqm (NVL (h.vqm, qm_pg.defqm)), qm_pg.defqm), qm_pg.defqm)
                 ) qm
     INTO ln_qm
     FROM halfhour h
    WHERE h.mid = lc.mid AND h.date_time > lc.ddate AND h.date_time <= lc.ddate + 1;

   UPDATE bill
      SET vqm = ln_qm
    WHERE mid = lc.mid AND date_time = lc.ddate + 1;
  END LOOP;

  ----------Нарисовали
  DELETE FROM lagging_records;

  admin_pg.add_calcperiod (1);
 END;

---------------------------------------------------------------------------------------
 PROCEDURE rollbackperiod (an_maket NUMBER, ddate_ DATE, an_commit NUMBER) IS
  ln_dif   NUMBER;
 BEGIN
  IF admin_pg.lock_p (cn_lock, 'halfhourtmp') <> 1 THEN
   raise_application_error (-20009, 'Закрытие периода не может быть проведено ввиду отсутствия возможности блокировки таблицы в течении ' || cn_lock || ' сек.',
                            TRUE);
  END IF;

  ln_dif := LEAST (TRUNC (NVL (admin_pg.get_calcperiod, SYSDATE)), TRUNC (SYSDATE)) - TRUNC (ddate_);

  FOR i IN 1 .. ln_dif LOOP
   rollbackperiod;
  END LOOP;

  IF an_commit = 1 THEN
   COMMIT;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   RAISE;
 END;

---------------------------------------------------------------------------------------
 PROCEDURE rollbackperiod IS
  ld_calcperiod   DATE;
 BEGIN
  ld_calcperiod := admin_pg.get_calcperiod;

  DELETE FROM billold
        WHERE date_time = ld_calcperiod;

  FOR lc IN (SELECT mid, date_time
               FROM billold
              WHERE dclosed = ld_calcperiod AND date_time <> dclosed) LOOP
   BEGIN
    INSERT INTO lagging_records
                (mid, ddate)
     SELECT lc.mid, TRUNC (lc.date_time - 1 / 1440)
       FROM DUAL
      WHERE NOT EXISTS (SELECT *
                          FROM lagging_records
                         WHERE mid = lc.mid AND ddate = TRUNC (lc.date_time - 1 / 1440));
   EXCEPTION
    WHEN OTHERS THEN
     NULL;
   END;
  END LOOP;

  DELETE FROM lagging_records
        WHERE ddate = ld_calcperiod - 1;

  DELETE FROM halfhourold
        WHERE (dclosed > ld_calcperiod - 1 AND (nsource > 5000 OR nsource < -5000))
              OR (date_time > ld_calcperiod - 1 AND date_time <= ld_calcperiod AND (nsource < 0 OR nsource = 9));

  UPDATE halfhourold
     SET dclosed = NULL
   WHERE dclosed > ld_calcperiod - 1;

  FOR lc IN (SELECT mid, ddate
               FROM lagging_records) LOOP
   DELETE FROM halfhourold
         WHERE mid = lc.mid AND date_time > lc.ddate AND date_time <= lc.ddate + 1 AND dclosed IS NULL AND nsource < 0;

   DELETE FROM billold
         WHERE mid = lc.mid AND date_time = lc.ddate + 1 AND (dclosed = ld_calcperiod OR dclosed IS NULL);
  END LOOP;

  admin_pg.add_calcperiod (-1);
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20002, 'das_pg.rollbackperiod: ' || SQLERRM (SQLCODE));
 END;

---------------------------------------------------------------------------------------
 FUNCTION getholeinhalfhour (ad_date DATE, an_mid NUMBER, an_ret48 NUMBER, an_type NUMBER)
  RETURN common_pg.tt_number IS
  lt_ret   common_pg.tt_number;
  i        NUMBER;

  CURSOR lcur_sel IS
   SELECT   ROWNUM dt
       FROM halfhourold
      WHERE ROWNUM < 49
   MINUS
   SELECT   TRUNC (TO_CHAR (date_time - 1 / 86400, 'SSSSS') / 1800) + 1 dt
       FROM halfhour
      WHERE mid = an_mid AND date_time > TRUNC (ad_date) AND date_time <= TRUNC (ad_date) + 1
   GROUP BY TRUNC (TO_CHAR (date_time - 1 / 86400, 'SSSSS') / 1800)
     HAVING ((an_type IS NULL
              AND (SUM (er) IS NOT NULL OR SUM (ed) IS NOT NULL OR SUM (q1) IS NOT NULL OR SUM (q2) IS NOT NULL OR SUM (q3) IS NOT NULL OR SUM (q4) IS NOT NULL)
             )
             OR (an_type IS NOT NULL AND DECODE (an_type, 1, SUM (er), 2, SUM (ed), 3, SUM (q1), 5, SUM (q3), 4, SUM (q2), 6, SUM (q4)) IS NOT NULL)
            )
   MINUS
   SELECT   util_pg.switch_f * 2 + 1
       FROM DUAL
      WHERE util_pg.is_dayswitch (ad_date) = 1
   MINUS
   SELECT   util_pg.switch_f * 2 + 2
       FROM DUAL
      WHERE util_pg.is_dayswitch (ad_date) = 1
   ORDER BY 1;
 BEGIN
  i := 0;

  FOR lc IN lcur_sel LOOP
   i := i + 1;
   lt_ret (i) := lc.dt;
  END LOOP;

  IF an_ret48 = 1 AND lt_ret.COUNT = 0 THEN
   IF util_pg.is_dayswitch (ad_date) = 1 THEN
    FOR i IN 1 .. 46 LOOP
     IF i > util_pg.switch_f * 2 THEN
      lt_ret (i) := i + 2;
     ELSE
      lt_ret (i) := i;
     END IF;
    END LOOP;
   ELSE
    FOR i IN 1 .. 48 LOOP
     lt_ret (i) := i;
    END LOOP;
   END IF;
  END IF;

  RETURN lt_ret;
 END;

---------------------------------------------------------------------------------------
 PROCEDURE correchalfhour (ad_date DATE, an_mid NUMBER) IS
  ln_source   NUMBER              DEFAULT 9;
  ld_date     DATE                DEFAULT TRUNC (ad_date);
  ln_dg       NUMBER;
  ld_tmp      DATE;
  ln_cn       NUMBER;
  ln_k        NUMBER;
  ln_cnreal   NUMBER;
  ln_ser      NUMBER;
  ln_sed      NUMBER;
  ln_sq1      NUMBER;
  ln_sq3      NUMBER;
  ln_sq2      NUMBER;
  ln_sq4      NUMBER;
  lt_er       common_pg.tt_number;
  lt_ed       common_pg.tt_number;
  lt_q1       common_pg.tt_number;
  lt_q3       common_pg.tt_number;
  lt_q2       common_pg.tt_number;
  lt_q4       common_pg.tt_number;
  lt_hole     common_pg.tt_number;
  ln_er       NUMBER;
  ln_ed       NUMBER;
  ln_q1       NUMBER;
  ln_q3       NUMBER;
  ln_q2       NUMBER;
  ln_q4       NUMBER;
  z           NUMBER;

  CURSOR lc_selmid IS
   SELECT f.mid, NVL (f.kc, 1) kc, LENGTH (TRUNC (digits)) dg
     FROM feeders f, meters m
    WHERE f.mid = m.mid(+) AND m.entype(+) = 7 AND (an_mid IS NULL OR an_mid = f.mid);

  CURSOR lc_selmindt (lc_mid NUMBER, lc_mtrsn VARCHAR2) IS
   SELECT   date_time dt, nsource, 0 b, erm, edm, q1m, q3m, q2m, q4m
       FROM halfhour
      WHERE mid = lc_mid AND er_mtrsn = lc_mtrsn AND NVL (erm, edm) IS NOT NULL AND date_time = ld_date
   UNION ALL
   SELECT   date_time dt, nsource, 1 b, erm, edm, q1m, q3m, q2m, q4m
       FROM monthsorg
      WHERE mid = lc_mid AND NVL (er_mtrsn, ed_mtrsn) = lc_mtrsn AND NVL (erm, edm) IS NOT NULL
            AND date_time =
                (SELECT MAX (date_time) dt
                   FROM monthsorg
                  WHERE mid = lc_mid AND date_time BETWEEN ADD_MONTHS (ld_date, -2) AND ld_date AND TRUNC (date_time) = date_time
                        AND NVL (er_mtrsn, ed_mtrsn) = lc_mtrsn AND NVL (erm, edm) IS NOT NULL)
   UNION ALL
   SELECT   date_time dt, nsource, 2 b, erm, edm, q1m, q3m, q2m, q4m
       FROM billorg
      WHERE mid = lc_mid AND NVL (er_mtrsn, ed_mtrsn) = lc_mtrsn AND NVL (erm, edm) IS NOT NULL
            AND date_time =
                (SELECT MAX (date_time) dt
                   FROM billorg
                  WHERE mid = lc_mid AND date_time BETWEEN ADD_MONTHS (ld_date, -2) AND ld_date AND TRUNC (date_time) = date_time
                        AND NVL (er_mtrsn, ed_mtrsn) = lc_mtrsn AND NVL (erm, edm) IS NOT NULL)
   ORDER BY 1 DESC, 2 DESC, 3;

  CURSOR lc_selmaxdt (lc_mid NUMBER) IS
   SELECT   date_time dt, nsource, erm, edm, q1m, q3m, q2m, q4m, er_mtrsn mtrsn
       FROM halfhour
      WHERE mid = lc_mid AND er_mtrsn IS NOT NULL AND NVL (erm, edm) IS NOT NULL AND date_time = ld_date + 1
   UNION ALL
   SELECT   date_time dt, nsource, erm, edm, q1m, q3m, q2m, q4m, NVL (er_mtrsn, ed_mtrsn) mtrsn
       FROM monthsorg
      WHERE mid = lc_mid AND NVL (er_mtrsn, ed_mtrsn) IS NOT NULL AND NVL (erm, edm) IS NOT NULL
            AND date_time = (SELECT MIN (date_time) dt
                               FROM monthsorg
                              WHERE mid = lc_mid AND date_time >= ld_date + 1 AND NVL (er_mtrsn, ed_mtrsn) IS NOT NULL AND NVL (erm, edm) IS NOT NULL)
   UNION ALL
   SELECT   date_time dt, nsource, erm, edm, q1m, q3m, q2m, q4m, NVL (er_mtrsn, ed_mtrsn) mtrsn
       FROM billorg
      WHERE mid = lc_mid AND NVL (er_mtrsn, ed_mtrsn) IS NOT NULL AND NVL (erm, edm) IS NOT NULL
            AND date_time = (SELECT MIN (date_time) dt
                               FROM billorg
                              WHERE mid = lc_mid AND date_time >= ld_date + 1 AND NVL (er_mtrsn, ed_mtrsn) IS NOT NULL AND NVL (erm, edm) IS NOT NULL)
   ORDER BY 1, 2;
 BEGIN
  IF an_mid IS NULL THEN
   DELETE FROM halfhourold
         WHERE date_time > ld_date AND date_time <= ld_date + 1 AND nsource = ln_source;

   IF util_pg.is_dayswitch (ld_date) = 1 THEN
    DELETE FROM halfhourold
          WHERE date_time > ld_date + util_pg.switch_f / 24 AND date_time <= ld_date + (util_pg.switch_f + 1) / 24;
   END IF;
  ELSE
   DELETE FROM halfhourold
         WHERE mid = an_mid AND date_time > ld_date AND date_time <= ld_date + 1 AND nsource = ln_source;

   IF util_pg.is_dayswitch (ld_date) = 1 THEN
    DELETE FROM halfhourold
          WHERE mid = an_mid AND date_time > ld_date + util_pg.switch_f / 24 AND date_time <= ld_date + (util_pg.switch_f + 1) / 24;
   END IF;
  END IF;

  FOR lc IN lc_selmid LOOP
   FOR lc1 IN lc_selmaxdt (lc.mid) LOOP
    FOR lc2 IN lc_selmindt (lc.mid, lc1.mtrsn) LOOP
     DELETE FROM halfhourold
           WHERE mid = lc.mid AND date_time > ld_date + 1 AND date_time <= util_pg.ceilhh24_2 (lc1.dt) AND nsource = ln_source;

     SELECT NVL (ROUND (util_pg.indicoverturn (lc1.erm - lc2.erm, ln_dg) * lc.kc), 0) - NVL (SUM (er), 0) er,
            NVL (ROUND (util_pg.indicoverturn (lc1.edm - lc2.edm, ln_dg) * lc.kc), 0) - NVL (SUM (ed), 0) ed,
            NVL (ROUND (util_pg.indicoverturn (lc1.q1m - lc2.q1m, ln_dg) * lc.kc), 0) - NVL (SUM (q1), 0) q1,
            NVL (ROUND (util_pg.indicoverturn (lc1.q3m - lc2.q3m, ln_dg) * lc.kc), 0) - NVL (SUM (q3), 0) q3,
            NVL (ROUND (util_pg.indicoverturn (lc1.q2m - lc2.q2m, ln_dg) * lc.kc), 0) - NVL (SUM (q2), 0) q2,
            NVL (ROUND (util_pg.indicoverturn (lc1.q4m - lc2.q4m, ln_dg) * lc.kc), 0) - NVL (SUM (q4), 0) q4
       INTO ln_er,
            ln_ed,
            ln_q1,
            ln_q3,
            ln_q2,
            ln_q4
       FROM halfhour
      WHERE mid = lc.mid AND date_time > lc2.dt AND date_time <= util_pg.ceilhh24_2 (lc1.dt) AND (NVL (nsource, 0) < 30 OR NVL (nsource, 0) > 49);

     IF ld_date + 1 <> lc1.dt THEN   --(-) Только на последний день ()
      ln_er := GREATEST (ln_er, 0);
      ln_ed := GREATEST (ln_ed, 0);
      ln_q1 := GREATEST (ln_q1, 0);
      ln_q3 := GREATEST (ln_q3, 0);
      ln_q2 := GREATEST (ln_q2, 0);
      ln_q4 := GREATEST (ln_q4, 0);
     END IF;

     IF ln_er = 0 AND ln_ed = 0 AND ln_q1 = 0 AND ln_q3 = 0 AND ln_q2 = 0 AND ln_q4 = 0 THEN
      EXIT;
     END IF;

     ln_cn := 48 * (util_pg.ceilhh24_2 (lc1.dt) - ld_date);

     IF util_pg.is_dayswitch (ld_date) = 1 THEN   --При переходе на лето -2
      lt_hole := getholeinhalfhour (ld_date, lc.mid, 1);   --Ищем дырки
      ln_cnreal := lt_hole.COUNT;
     ELSE
      ln_cnreal := ln_cn;
     END IF;

     ln_ser := ln_er;
     ln_sed := ln_ed;
     ln_sq1 := ln_q1;
     ln_sq3 := ln_q3;
     ln_sq2 := ln_q2;
     ln_sq4 := ln_q4;
     ln_k := 1;

     FOR i IN 1 .. ln_cn LOOP
      IF lt_hole.COUNT = 0 OR (ln_k <= lt_hole.COUNT AND lt_hole (ln_k) = i) THEN   --Или
       ln_k := ln_k + 1;
       lt_er (i) := TRUNC (ln_er / ln_cnreal);
       ln_ser := ln_ser - lt_er (i);
       lt_ed (i) := TRUNC (ln_ed / ln_cnreal);
       ln_sed := ln_sed - lt_ed (i);
       lt_q1 (i) := TRUNC (ln_q1 / ln_cnreal);
       ln_sq1 := ln_sq1 - lt_q1 (i);
       lt_q3 (i) := TRUNC (ln_q3 / ln_cnreal);
       ln_sq3 := ln_sq3 - lt_q3 (i);
       lt_q2 (i) := TRUNC (ln_q2 / ln_cnreal);
       ln_sq2 := ln_sq2 - lt_q2 (i);
       lt_q4 (i) := TRUNC (ln_q4 / ln_cnreal);
       ln_sq4 := ln_sq4 - lt_q4 (i);
      ELSE
       lt_er (i) := 0;
       lt_ed (i) := 0;
       lt_q1 (i) := 0;
       lt_q3 (i) := 0;
       lt_q2 (i) := 0;
       lt_q4 (i) := 0;
      END IF;
     END LOOP;

     IF ld_date + 1 <> lc1.dt THEN
      ln_ser := 0;
      ln_sed := 0;
      ln_sq1 := 0;
      ln_sq3 := 0;
      ln_sq2 := 0;
      ln_sq4 := 0;
     END IF;

     --ln_ser:=trunc(ln_ser*48/ln_cnreal);--Пропорционально и ошибки округления !!!!!!!!!!!!!
     --ln_sed:=trunc(ln_sed*48/ln_cnreal);--Пропорционально и ошибки округления !!!!!!!!!!!!!
     --ln_sq1:=trunc(ln_sq1*48/ln_cnreal);--Пропорционально и ошибки округления !!!!!!!!!!!!!
     --ln_sq3:=trunc(ln_sq3*48/ln_cnreal);--Пропорционально и ошибки округления !!!!!!!!!!!!!
     ln_k := 1;

     FOR i IN 1 .. 48 LOOP
      IF lt_hole.COUNT = 0 OR (ln_k <= lt_hole.COUNT AND lt_hole (ln_k) = i) THEN
       ln_k := ln_k + 1;

       IF ABS (ln_ser) >= 1 THEN
        lt_er (i) := lt_er (i) + SIGN (ln_ser);
        ln_ser := ln_ser - SIGN (ln_ser);
       END IF;

       IF ABS (ln_sed) >= 1 THEN
        lt_ed (i) := lt_ed (i) + SIGN (ln_sed);
        ln_sed := ln_sed - SIGN (ln_sed);
       END IF;

       IF ABS (ln_sq1) >= 1 THEN
        lt_q1 (i) := lt_q1 (i) + SIGN (ln_sq1);
        ln_sq1 := ln_sq1 - SIGN (ln_sq1);
       END IF;

       IF ABS (ln_sq3) >= 1 THEN
        lt_q3 (i) := lt_q3 (i) + SIGN (ln_sq3);
        ln_sq3 := ln_sq3 - SIGN (ln_sq3);
       END IF;

       IF ABS (ln_sq2) >= 1 THEN
        lt_q2 (i) := lt_q2 (i) + SIGN (ln_sq2);
        ln_sq2 := ln_sq2 - SIGN (ln_sq2);
       END IF;

       IF ABS (ln_sq4) >= 1 THEN
        lt_q4 (i) := lt_q4 (i) + SIGN (ln_sq4);
        ln_sq4 := ln_sq4 - SIGN (ln_sq4);
       END IF;
      END IF;
     END LOOP;

     IF util_pg.is_dayswitch (ld_date) = -1 THEN   --день перевода времени осенью (все подгоняем на 02:30 03:00)
      FOR i IN 1 .. 48 LOOP
       z := 2 * (util_pg.switch_f + 1);

       IF i <> z THEN
        lt_er (z) := lt_er (z) + lt_er (i);
        lt_ed (z) := lt_ed (z) + lt_ed (i);
        lt_q1 (z) := lt_q1 (z) + lt_q1 (i);
        lt_q3 (z) := lt_q3 (z) + lt_q3 (i);
        lt_q2 (z) := lt_q2 (z) + lt_q2 (i);
        lt_q4 (z) := lt_q4 (z) + lt_q4 (i);
        lt_er (i) := 0;
        lt_ed (i) := 0;
        lt_q1 (i) := 0;
        lt_q3 (i) := 0;
        lt_q2 (i) := 0;
        lt_q4 (i) := 0;
       END IF;
      END LOOP;

      lt_er (z - 1) := TRUNC (lt_er (z) / 2);
      lt_er (z) := lt_er (z) - lt_er (z - 1);
      lt_ed (z - 1) := TRUNC (lt_ed (z) / 2);
      lt_ed (z) := lt_ed (z) - lt_ed (z - 1);
      lt_q1 (z - 1) := TRUNC (lt_q1 (z) / 2);
      lt_q1 (z) := lt_q1 (z) - lt_q1 (z - 1);
      lt_q3 (z - 1) := TRUNC (lt_q3 (z) / 2);
      lt_q3 (z) := lt_q3 (z) - lt_q3 (z - 1);
      lt_q2 (z - 1) := TRUNC (lt_q2 (z) / 2);
      lt_q2 (z) := lt_q2 (z) - lt_q2 (z - 1);
      lt_q4 (z - 1) := TRUNC (lt_q4 (z) / 2);
      lt_q4 (z) := lt_q4 (z) - lt_q4 (z - 1);
     END IF;

     FOR i IN 1 .. 48 LOOP   ------Считаем больше а пишем на сутки
      IF lt_er (i) <> 0 OR lt_ed (i) <> 0 OR lt_q1 (i) <> 0 OR lt_q3 (i) <> 0 OR lt_q2 (i) <> 0 OR lt_q4 (i) <> 0 THEN
       INSERT INTO halfhourold
                   (mid, date_time, nsource, er, ed, q1, q3, q2, q4, nkc
                   )
            VALUES (lc.mid, ld_date + i / 48, ln_source, lt_er (i), lt_ed (i), lt_q1 (i), lt_q3 (i), lt_q2 (i), lt_q4 (i), lc.kc
                   );
      END IF;
     END LOOP;

     EXIT;
    END LOOP;

    EXIT;
   END LOOP;

   lt_hole.DELETE;
  END LOOP;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20002, 'das_pg.correchalfhour: ' || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE checkhalfhour (an_commit NUMBER) IS
 BEGIN
  IF (util_pg.newhalfhour_f = 1) OR (util_pg.locksummertime_f = 1) THEN
   checkhalfhour_new (an_commit);
  ELSE
   checkhalfhour_old (an_commit);
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE checkhalfhour_without_err (an_commit NUMBER) IS
 BEGIN
  checkhalfhour (an_commit);
 EXCEPTION
  WHEN OTHERS THEN
   NULL;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE checkhalfhour_new (an_commit NUMBER) IS
  -- Переносит получасоки из временной таблицы в Halfhour
  -- попутно расставляя код источника данных (основной, дубль и т.п.)
  -- дублируя записи ОВ на замещаемые точки
  --
  ln_needrounderr   NUMBER        DEFAULT util_pg.needrounderr_f;
  destmid           NUMBER;
  src               NUMBER;
  prevsrc           NUMBER;
  rowid_            ROWID;
  nexceptcalc_      NUMBER;
  er_               NUMBER;
  ed_               NUMBER;
  q1_               NUMBER;
  q2_               NUMBER;
  q3_               NUMBER;
  q4_               NUMBER;
  ld_calcperiod     DATE;
  ln_oldmid         NUMBER        DEFAULT -1;
  ln_olddestmid     NUMBER        DEFAULT -1;
  ln_olddate        DATE          DEFAULT TO_DATE ('190001', 'YYYYMM');
  lv_qm             VARCHAR2 (32);
 BEGIN
  SAVEPOINT checkhalfhour_sp;

  IF admin_pg.lock_p (cn_lock, 'halfhourtmp') <> 1 THEN
   raise_application_error (-20009,
                            'Расчет получасовых расходов не может быть проведен ввиду отсутствия возможности блокировки таблицы в течении ' || cn_lock || ' сек.',
                            TRUE);
  END IF;

  ld_calcperiod := admin_pg.get_calcperiod;

  FOR c IN (SELECT   h.mid, util_pg.to_localtime (util_pg.convertmeterdate_f (h.date_time, f.ntimezonew, f.ntimezones)) date_time, h.er, h.ed, h.q1, h.q2, h.q3,
                     h.q4, h.erm, h.edm, h.q1m, h.q2m, h.q3m, h.q4m, h.er_mtrsn, h.status, h.nsource, NVL (f.kc, 1) nkc,
                     util_pg.is_timeswitch (util_pg.convertmeterdate_f (h.date_time, f.ntimezonew, f.ntimezones)) istmw, NVL (f.canal, 0) canal,
                     NVL (f.nswitch, 0) nswitch, NVL (vqm, qm_pg.cv_okqm) vqm, nmetertype
                FROM halfhourtmp h, feeders f
               WHERE h.mid = f.mid(+)
            ORDER BY h.date_time, h.mid) LOOP
   lv_qm := c.vqm;

   IF c.nsource IN (50, 59) THEN   --Ручники
    lv_qm := qm_pg.sbt (lv_qm, 22, qm_pg.cn_manual);
   ELSIF c.nmetertype IN (comsrv_pg.cn_maket, comsrv_pg.cn_uppd) THEN   --Макет
    lv_qm := qm_pg.sbt (lv_qm, 22, qm_pg.cn_maket);
   END IF;

   destmid := c.nswitch;

   IF c.nsource = 20 THEN
    src := 20;
   ELSE
    src := 10;
   END IF;   -- по коду нити и связному номеру определяем дубль / не дубль

   IF destmid <> 0 THEN
    SELECT NVL (MAX (mid), 0)
      INTO destmid
      FROM switches
     WHERE nswitch = c.mid AND c.date_time > dswitch AND c.date_time <= descape;

    IF destmid = c.mid THEN
     destmid := 0;
    END IF;
   END IF;   -- если это ОВ, то выбираем id точки переключения и 0, если ОВ сам на себя

   IF ln_needrounderr = 1 THEN
    -- производим округление с переносом остатков
    er_ := 0;
    ed_ := 0;
    q1_ := 0;
    q2_ := 0;
    q3_ := 0;
    q4_ := 0;

    BEGIN
     SELECT NVL (er, 0), NVL (ed, 0), NVL (q1, 0), NVL (q2, 0), NVL (q3, 0), NVL (q4, 0)
       INTO er_, ed_, q1_, q2_, q3_, q4_
       FROM round_errors
      WHERE mid = c.mid AND nsource = src;
    EXCEPTION
     WHEN OTHERS THEN
      INSERT INTO round_errors
                  (mid, nsource, er, ed, q1, q2, q3, q4
                  )
           VALUES (c.mid, src, 0, 0, 0, 0, 0, 0
                  );
    END;

    er_ := TRUNC (c.er + er_);
    ed_ := TRUNC (c.ed + ed_);
    q1_ := TRUNC (c.q1 + q1_);
    q2_ := TRUNC (c.q2 + q2_);
    q3_ := TRUNC (c.q3 + q3_);
    q4_ := TRUNC (c.q4 + q4_);

    -- сохраняем в БД остатки
    UPDATE round_errors
       SET er = NVL (er, 0) + NVL (c.er, 0) - NVL (er_, 0),
           ed = NVL (ed, 0) + NVL (c.ed, 0) - NVL (ed_, 0),
           q1 = NVL (q1, 0) + NVL (c.q1, 0) - NVL (q1_, 0),
           q2 = NVL (q2, 0) + NVL (c.q2, 0) - NVL (q2_, 0),
           q3 = NVL (q3, 0) + NVL (c.q3, 0) - NVL (q3_, 0),
           q4 = NVL (q4, 0) + NVL (c.q4, 0) - NVL (q4_, 0)
     WHERE mid = c.mid AND nsource = src;
   ELSE
    er_ := c.er;
    ed_ := c.ed;
    q1_ := c.q1;
    q2_ := c.q2;
    q3_ := c.q3;
    q4_ := c.q4;
   END IF;

   nexceptcalc_ := 0;   -- предполагаем включение в расчет

   IF c.istmw = -1 THEN   --Время перехода с лета на зиму (nsource=19,29)
    src := src + 9;

    --Вычисляем признак включения в расчет для данной записи
    SELECT COUNT (*)
      INTO nexceptcalc_
      FROM DUAL
     WHERE EXISTS (SELECT *
                     FROM halfhourold
                    WHERE mid = c.mid AND date_time = c.date_time AND nsource IN (19, 29) AND nsource < src);

    --Убираем признак включения в расчет для записей с бльшем кодом источника
    UPDATE halfhourold
       SET nexceptcalc = 1
     WHERE mid = c.mid AND date_time = c.date_time AND nsource IN (19, 29) AND nsource > src;
   ELSE
    -- уточняем код источника для вставки повторных записей
    SELECT NVL (MAX (nsource), 0)
      INTO prevsrc
      FROM halfhourold
     WHERE mid = c.mid AND date_time = c.date_time AND nsource >= src AND nsource < src + 9;

    IF prevsrc <> 0 THEN   -- в БД уже есть запись с этим кодом источника
     prevsrc := prevsrc + 1;   --   увеличиваем на единицу код повторной записи

     IF prevsrc = src + 9 THEN
      prevsrc := prevsrc - 1;
     END IF;   -- допускается только 8 повторных записей

     src := prevsrc;
    END IF;

    -- проставляется признак включения в расчет с учетом кода имеющейся в БД записи
    FOR lc1 IN (SELECT ROWID rw, nsource   ---Курсор максимум по одной записи
                  FROM halfhourold
                 WHERE mid = c.mid AND date_time = c.date_time
                       AND nsource =
                           (SELECT MIN (nsource)
                              FROM halfhourold
                             WHERE mid = c.mid AND date_time = c.date_time AND nsource > 0   -- корректировки и
                                   AND (nsource < 30 OR nsource >= util_pg.cn_manualinput)   --   ОВ на расстановку признака не влияют
                                   AND nsource NOT IN (19, 29, 59) AND nexceptcalc IS NULL)) LOOP
     rowid_ := lc1.rw;
     prevsrc := lc1.nsource;

     IF FLOOR (prevsrc / 10) >= FLOOR (src / 10) THEN   -- если код в БД хуже, снимаем в БД признак включения в расчет
      UPDATE halfhourold
         SET nexceptcalc = 1
       WHERE ROWID = rowid_;
     ELSE
      nexceptcalc_ := 1;   -- иначе, исключим из расчета текущую запись
     END IF;
    END LOOP;
   END IF;

   BEGIN
    IF nexceptcalc_ = 0 THEN
     nexceptcalc_ := NULL;
    END IF;

    INSERT INTO halfhourold
                (mid, date_time, nsource, er, ed, q1, q2, q3, q4, erm, edm, q1m, q2m, q3m, q4m, er_mtrsn, status, nexceptcalc, nkc, vqm
                )
         VALUES (c.mid, c.date_time, src, er_, ed_, q1_, q2_, q3_, q4_, c.erm, c.edm, c.q1m, c.q2m, c.q3m, c.q4m, c.er_mtrsn, c.status, nexceptcalc_, c.nkc, lv_qm
                );
   EXCEPTION
    WHEN DUP_VAL_ON_INDEX THEN   --если есть запись по этой точке на это время - производим UPDATE
     UPDATE halfhourold
        SET (er, ed, q1, q2, q3, q4, erm, edm, q1m, q2m, q3m, q4m, er_mtrsn, status, nexceptcalc, nkc, vqm) =
             (SELECT er_, ed_, q1_, q2_, q3_, q4_, c.erm, c.edm, c.q1m, c.q2m, c.q3m, c.q4m, c.er_mtrsn, c.status, nexceptcalc_, c.nkc, lv_qm
                FROM DUAL)
      WHERE mid = c.mid AND date_time = c.date_time AND nsource = src;
   END;

   IF destmid <> 0 THEN   -- дублируем данные по ОВ на точку
    IF c.istmw = -1 THEN
     --Убираем признак включения в расчет для записей с бльшем кодом источника
     UPDATE halfhourold
        SET nexceptcalc = 1
      WHERE mid = destmid AND date_time = c.date_time AND nsource IN (39, 49) AND nsource > src + 20;
    ELSE
     IF nexceptcalc_ IS NULL THEN
      FOR lc1 IN (SELECT ROWID rw, nsource   ---Курсор максимум по одной записи
                    FROM halfhourold
                   WHERE mid = destmid AND date_time = c.date_time
                         AND nsource =
                             (SELECT MIN (nsource)
                                FROM halfhourold
                               WHERE mid = destmid AND date_time = c.date_time AND nsource >= 30 AND nsource < util_pg.cn_manualinput   --   рассматриваются только ОВ
                                     AND nsource NOT IN (39, 49)   --без лета-зимы
                                                                AND nexceptcalc IS NULL)) LOOP
       rowid_ := lc1.rw;
       prevsrc := lc1.nsource;

       IF prevsrc > src THEN   -- если код в БД хуже, снимаем в БД признак включения в расчет
        UPDATE halfhourold
           SET nexceptcalc = 1
         WHERE ROWID = rowid_;
       END IF;
      END LOOP;
     END IF;
    END IF;

    BEGIN
     INSERT INTO halfhourold
                 (mid, date_time, nsource, nswitch, er, ed, q1, q2, q3, q4, erm, edm, q1m, q2m, q3m, q4m, er_mtrsn, status,
                  nexceptcalc, nkc, vqm
                 )
          VALUES (destmid, c.date_time, src + 20, c.mid, er_, ed_, q1_, q2_, q3_, q4_, c.erm, c.edm, c.q1m, c.q2m, c.q3m, c.q4m, c.er_mtrsn, c.status,
                  nexceptcalc_, c.nkc, qm_pg.sbt (lv_qm, 22, qm_pg.cn_ov)
                 );
    EXCEPTION
     WHEN DUP_VAL_ON_INDEX THEN   --если есть запись по этой точке на это время - производим UPDATE
      UPDATE halfhourold
         SET (nswitch, er, ed, q1, q2, q3, q4, erm, edm, q1m, q2m, q3m, q4m, er_mtrsn, status, nexceptcalc, nkc, vqm) =
              (SELECT c.mid, er_, ed_, q1_, q2_, q3_, q4_, c.erm, c.edm, c.q1m, c.q2m, c.q3m, c.q4m, c.er_mtrsn, c.status, nexceptcalc_, c.nkc,
                      qm_pg.sbt (lv_qm, 22, qm_pg.cn_ov)
                 FROM DUAL)
       WHERE mid = destmid AND date_time = c.date_time AND nsource = src + 20;
    END;
   END IF;

   IF (nexceptcalc_ IS NULL) AND (c.date_time <= ld_calcperiod) THEN
    IF NOT (ln_oldmid = c.mid AND TRUNC (ln_olddate - 1 / 1440) = TRUNC (c.date_time - 1 / 1440)) THEN
     INSERT INTO lagging_records
                 (mid, ddate)
      SELECT c.mid, TRUNC (c.date_time - 1 / 1440)
        FROM DUAL
       WHERE NOT EXISTS (SELECT *
                           FROM lagging_records
                          WHERE mid = c.mid AND ddate = TRUNC (c.date_time - 1 / 1440));
    END IF;

    IF destmid <> 0 AND NOT (ln_olddestmid = destmid AND ln_oldmid = c.mid AND TRUNC (ln_olddate - 1 / 1440) = TRUNC (c.date_time - 1 / 1440)) THEN
     INSERT INTO lagging_records
                 (mid, ddate)
      SELECT destmid, TRUNC (c.date_time - 1 / 1440)
        FROM DUAL
       WHERE NOT EXISTS (SELECT *
                           FROM lagging_records
                          WHERE mid = destmid AND ddate = TRUNC (c.date_time - 1 / 1440));
    END IF;
   END IF;

   ln_oldmid := c.mid;
   ln_olddestmid := destmid;
   ln_olddate := c.date_time;
  END LOOP;

  DELETE FROM halfhourtmp;

  IF an_commit = 1 THEN
   COMMIT;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT checkhalfhour_sp;
   raise_application_error (-20001, 'das_pg.checkhalfhour_new: ' || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE checkhalfhour_old (an_commit NUMBER) IS
-- Переносит получасоки из временной таблицы в Halfhour
-- попутно расставляя код источника данных (основной, дубль и т.п.)
-- дублируя записи ОВ на замещаемые точки
--
-- MODIFICATION HISTORY
-- Person      Date      Comments
-- ---------   --------  -------------------------------------------
-- Вештак      04.12.02
-- Вештак      12.03.03  полная переделка
-- Вештак      23.05.03  учет "опоздавших" записей
-- Вештак      10.06.03  повторные записи одного источника перетягивают
--                       на себя признак включения в расчет
  destmid         NUMBER;
  canal_          NUMBER;
  src             NUMBER;
  prevsrc         NUMBER;
  sum1            NUMBER;
  rowid_          ROWID;
  nexceptcalc_    NUMBER;
  er_             NUMBER;
  ed_             NUMBER;
  q1_             NUMBER;
  q2_             NUMBER;
  q3_             NUMBER;
  q4_             NUMBER;
  ld_calcperiod   DATE;
 BEGIN
  SAVEPOINT checkhalfhour_sp;
  ld_calcperiod := admin_pg.get_calcperiod;

  IF admin_pg.lock_p (cn_lock, 'halfhourtmp') <> 1 THEN
   raise_application_error (-20009,
                            'Расчет получасовых расходов не может быть проведен ввиду отсутствия возможности блокировки таблицы в течении ' || cn_lock || ' сек.',
                            TRUE);
  END IF;

  --  IF util_pg.get_customer_id = 6 THEN
  --   correchalfhourtime;
  --  END IF;
  FOR c IN (SELECT   h.*, NVL (f.kc, 1) nkc
                FROM halfhourtmp h, feeders f
               WHERE h.mid = f.mid(+)
            ORDER BY h.date_time) LOOP
   SELECT NVL (MAX (canal), 0), NVL (MAX (nswitch), 0)
     INTO canal_, destmid
     FROM feeders
    WHERE mid = c.mid;

   IF c.nsource = 20 AND canal_ > 50000000 THEN
    src := 20;
   ELSE
    src := 10;
   END IF;   -- по коду нити и связному номеру определяем дубль / не дубль

   IF destmid <> 0 THEN
    BEGIN
     SELECT NVL (mid, 0)
       INTO destmid
       FROM switches
      WHERE nswitch = c.mid AND c.date_time > dswitch AND c.date_time <= descape;

     IF destmid = c.mid THEN
      destmid := 0;
     END IF;
    EXCEPTION
     WHEN OTHERS THEN
      destmid := 0;
    END;
   END IF;   -- если это ОВ, то выбираем id точки переключения и 0, если ОВ сам на себя

   IF util_pg.needrounderr_f = 1 THEN
    -- производим округление с переносом остатков
    er_ := 0;
    ed_ := 0;
    q1_ := 0;
    q2_ := 0;
    q3_ := 0;
    q4_ := 0;

    BEGIN
     SELECT NVL (er, 0), NVL (ed, 0), NVL (q1, 0), NVL (q2, 0), NVL (q3, 0), NVL (q4, 0)
       INTO er_, ed_, q1_, q2_, q3_, q4_
       FROM round_errors
      WHERE mid = c.mid AND nsource = src;
    EXCEPTION
     WHEN OTHERS THEN
      INSERT INTO round_errors
                  (mid, nsource, er, ed, q1, q2, q3, q4
                  )
           VALUES (c.mid, src, 0, 0, 0, 0, 0, 0
                  );
    END;

    er_ := TRUNC (c.er + er_);
    ed_ := TRUNC (c.ed + ed_);
    q1_ := TRUNC (c.q1 + q1_);
    q2_ := TRUNC (c.q2 + q2_);
    q3_ := TRUNC (c.q3 + q3_);
    q4_ := TRUNC (c.q4 + q4_);

    -- сохраняем в БД остатки
    UPDATE round_errors
       SET er = NVL (er, 0) + NVL (c.er, 0) - NVL (er_, 0),
           ed = NVL (ed, 0) + NVL (c.ed, 0) - NVL (ed_, 0),
           q1 = NVL (q1, 0) + NVL (c.q1, 0) - NVL (q1_, 0),
           q2 = NVL (q2, 0) + NVL (c.q2, 0) - NVL (q2_, 0),
           q3 = NVL (q3, 0) + NVL (c.q3, 0) - NVL (q3_, 0),
           q4 = NVL (q4, 0) + NVL (c.q4, 0) - NVL (q4_, 0)
     WHERE mid = c.mid AND nsource = src;
   ELSE
    er_ := c.er;
    ed_ := c.ed;
    q1_ := c.q1;
    q2_ := c.q2;
    q3_ := c.q3;
    q4_ := c.q4;
   END IF;

   nexceptcalc_ := 0;   -- предполагаем включение в расчет
   -- уточняем код источника для вставки повторных записей
   prevsrc := 0;

   BEGIN
    SELECT MAX (nsource)
      INTO prevsrc
      FROM halfhourold
     WHERE mid = c.mid AND date_time = c.date_time AND nsource >= src AND nsource < src + 10;

    IF prevsrc IS NULL THEN
     prevsrc := 0;
    END IF;
   EXCEPTION
    WHEN OTHERS THEN
     prevsrc := 0;
   END;

   IF prevsrc <> 0 THEN   -- в БД уже есть запись с этим кодом источника
    prevsrc := prevsrc + 1;   --   увеличиваем на единицу код повторной записи

    --   nexceptcalc_ := 1; -- Раньше повторные записи в расчет не включались. Теперь наоборот!
    IF prevsrc = src + 10 THEN
     prevsrc := prevsrc - 1;
    END IF;   -- допускается только 9 повторных записей

    src := prevsrc;
   END IF;

   -- проставляется признак включения в расчет с учетом кода имеющейся в БД записи
   IF nexceptcalc_ = 0 THEN
    BEGIN
     SELECT ROWID, nsource
       INTO rowid_, prevsrc
       FROM halfhourold
      WHERE mid = c.mid AND date_time = c.date_time
            AND nsource =
                (SELECT MIN (nsource)
                   FROM halfhourold
                  WHERE mid = c.mid AND date_time = c.date_time AND nsource > 0   -- корректировки и
                        AND (nsource < 30 OR nsource >= util_pg.cn_manualinput)   --   ОВ на расстановку признака не влияют
                                                                               AND nexceptcalc IS NULL);

     IF FLOOR (prevsrc / 10) >= FLOOR (src / 10) THEN   -- если код в БД хуже, снимаем в БД признак включения в расчет
      UPDATE halfhourold
         SET nexceptcalc = 1
       WHERE ROWID = rowid_;
     ELSE
      nexceptcalc_ := 1;   -- иначе, исключим из расчета текущую запись
     END IF;
    EXCEPTION
     WHEN OTHERS THEN
      NULL;
    END;
   END IF;

   BEGIN
    IF nexceptcalc_ = 0 THEN
     nexceptcalc_ := NULL;
    END IF;

    INSERT INTO halfhourold
                (mid, date_time, nsource, er, ed, q1, q2, q3, q4, erm, edm, q1m, q2m, q3m, q4m, er_mtrsn, status, nexceptcalc, nkc
                )
         VALUES (c.mid, c.date_time, src, er_, ed_, q1_, q2_, q3_, q4_, c.erm, c.edm, c.q1m, c.q2m, c.q3m, c.q4m, c.er_mtrsn, c.status, nexceptcalc_, c.nkc
                );
   EXCEPTION
    WHEN OTHERS THEN
     NULL;
   END;

   IF destmid <> 0 THEN   -- дублируем данные по ОВ на точку
    IF nexceptcalc_ IS NULL THEN
     BEGIN
      SELECT ROWID, nsource
        INTO rowid_, prevsrc
        FROM halfhourold
       WHERE mid = destmid AND date_time = c.date_time
             AND nsource =
                 (SELECT MIN (nsource)
                    FROM halfhourold
                   WHERE mid = destmid AND date_time = c.date_time AND nsource >= 30 AND nsource < util_pg.cn_manualinput   --   рассматриваются только ОВ
                         AND nexceptcalc IS NULL);

      IF prevsrc > src THEN   -- если код в БД хуже, снимаем в БД признак включения в расчет
       UPDATE halfhourold
          SET nexceptcalc = 1
        WHERE ROWID = rowid_;
      END IF;
     EXCEPTION
      WHEN OTHERS THEN
       NULL;
     END;
    END IF;

    BEGIN
     INSERT INTO halfhourold
                 (mid, date_time, nsource, nswitch, er, ed, q1, q2, q3, q4, erm, edm, q1m, q2m, q3m, q4m, er_mtrsn, status,
                  nexceptcalc, nkc
                 )
          VALUES (destmid, c.date_time, src + 20, c.mid, er_, ed_, q1_, q2_, q3_, q4_, c.erm, c.edm, c.q1m, c.q2m, c.q3m, c.q4m, c.er_mtrsn, c.status,
                  nexceptcalc_, c.nkc
                 );
    EXCEPTION
     WHEN OTHERS THEN
      NULL;
    END;
   END IF;

   IF (nexceptcalc_ IS NULL) AND (c.date_time <= ld_calcperiod) THEN
    BEGIN
     INSERT INTO lagging_records
                 (mid, ddate
                 )
          VALUES (c.mid, TRUNC (c.date_time - 1 / 1440)
                 );

     IF destmid <> 0 THEN
      INSERT INTO lagging_records
                  (mid, ddate
                  )
           VALUES (destmid, TRUNC (c.date_time - 1 / 1440)
                  );
     END IF;
    EXCEPTION
     WHEN OTHERS THEN
      NULL;
    END;
   END IF;
  END LOOP;

  DELETE FROM halfhourtmp;

  IF an_commit = 1 THEN
   COMMIT;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT checkhalfhour_sp;
   raise_application_error (-20002, 'das_pg.checkhalfhour_old: ' || SQLERRM (SQLCODE));
 END;   -- Procedure CHECKHALFHOUR

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE correchalfhourtime IS
  CURSOR lcur_sel IS
   SELECT DISTINCT mid
              FROM halfhourtmp
             WHERE util_pg.trunchh24_2 (date_time) <> date_time
          GROUP BY mid;
 BEGIN
  FOR lc IN lcur_sel LOOP
   correchalfhourtime (lc.mid);
  END LOOP;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE correchalfhourtime (an_mid NUMBER) IS
  ln_source   CONSTANT NUMBER                := 10;
  ln_rn                NUMBER                DEFAULT 8;
  ln_cn                NUMBER                DEFAULT 0;
  ln_cnn               NUMBER                DEFAULT 0;
  ld_min               DATE;
  ld_max               DATE;
  lt_dt                common_pg.tt_date;
  lt_er                common_pg.tt_number;
  lt_ed                common_pg.tt_number;
  lt_q1                common_pg.tt_number;
  lt_q2                common_pg.tt_number;
  lt_q3                common_pg.tt_number;
  lt_q4                common_pg.tt_number;
  lt_mtrsn             common_pg.tt_varchar2;
  lt_ndt               common_pg.tt_date;
  lt_ner               common_pg.tt_number;
  lt_ned               common_pg.tt_number;
  lt_nq1               common_pg.tt_number;
  lt_nq2               common_pg.tt_number;
  lt_nq3               common_pg.tt_number;
  lt_nq4               common_pg.tt_number;
  lt_nmtrsn            common_pg.tt_varchar2;
  ln_ser               NUMBER                DEFAULT 0;
  ln_sed               NUMBER                DEFAULT 0;
  ln_sq1               NUMBER                DEFAULT 0;
  ln_sq2               NUMBER                DEFAULT 0;
  ln_sq3               NUMBER                DEFAULT 0;
  ln_sq4               NUMBER                DEFAULT 0;
  ld_tmp               DATE;
  ln_i                 NUMBER;
  ln_k                 NUMBER;

  CURSOR lcur_sel (lc_min DATE, lc_max DATE) IS
   SELECT   date_time dt, NVL (SUM (er), 0) er, NVL (SUM (ed), 0) ed, NVL (SUM (q1), 0) q1, NVL (SUM (q2), 0) q2, NVL (SUM (q3), 0) q3, NVL (SUM (q4), 0) q4,
            MAX (er_mtrsn) mtrsn
       FROM halfhourold
      WHERE mid = an_mid AND date_time > lc_min AND date_time <= lc_max AND nsource = ln_source
   GROUP BY date_time
   UNION ALL
   SELECT   date_time dt, NVL (SUM (er), 0) er, NVL (SUM (ed), 0) ed, NVL (SUM (q1), 0) q1, NVL (SUM (q2), 0) q2, NVL (SUM (q3), 0) q3, NVL (SUM (q4), 0) q4,
            MAX (er_mtrsn) mtrsn
       FROM halfhourtmp
      WHERE mid = an_mid
   GROUP BY date_time
   ORDER BY 1;
 BEGIN
  SELECT MIN (date_time) mindt, MAX (date_time) maxdt
    INTO ld_min, ld_max
    FROM halfhourtmp
   WHERE mid = an_mid;

  --Удалим на всякий случай
  DELETE FROM halfhourold
        WHERE mid = an_mid AND date_time >= ld_min AND date_time <= ld_max AND nsource = ln_source;

  --Ищем дату до которой (включительно) все ок!
  SELECT util_pg.trunchh24_2 (NVL (MAX (date_time), ld_min - 1 / 86400)) mindt
    INTO lt_dt (0)
    FROM halfhourold
   WHERE mid = an_mid AND date_time < ld_min AND nsource = ln_source;

  FOR lc IN lcur_sel (ld_min, ld_max) LOOP
   ln_cn := ln_cn + 1;
   ln_ser := ln_ser + lc.er;   --Собираем общую сумму
   ln_sed := ln_sed + lc.ed;
   ln_sq1 := ln_sq1 + lc.q1;
   ln_sq2 := ln_sq2 + lc.q2;
   ln_sq3 := ln_sq3 + lc.q3;
   ln_sq4 := ln_sq4 + lc.q4;
   lt_dt (ln_cn) := lc.dt;
   lt_er (ln_cn) := lc.er / (lt_dt (ln_cn) - lt_dt (ln_cn - 1));   --перевели в мощность суточную (на начальную границу (начиная с такая))
   lt_ed (ln_cn) := lc.ed / (lt_dt (ln_cn) - lt_dt (ln_cn - 1));
   lt_q1 (ln_cn) := lc.q1 / (lt_dt (ln_cn) - lt_dt (ln_cn - 1));
   lt_q2 (ln_cn) := lc.q2 / (lt_dt (ln_cn) - lt_dt (ln_cn - 1));
   lt_q3 (ln_cn) := lc.q3 / (lt_dt (ln_cn) - lt_dt (ln_cn - 1));
   lt_q4 (ln_cn) := lc.q4 / (lt_dt (ln_cn) - lt_dt (ln_cn - 1));
   lt_mtrsn (ln_cn) := lc.mtrsn;
  END LOOP;

  --удаляем все что было
  DELETE FROM halfhourold
        WHERE mid = an_mid AND date_time > ld_min AND date_time <= ld_max AND nsource = ln_source;

  DELETE FROM halfhourtmp
        WHERE mid = an_mid AND nsource = ln_source;

  ld_tmp := LEAST (lt_dt (0) + 1 / 48, ld_max);
  ln_i := 1;

  WHILE ld_tmp <= ld_max LOOP
   ln_cnn := ln_cnn + 1;
   lt_ndt (ln_cnn) := ld_tmp;
   lt_ner (ln_cnn) := 0;
   lt_ned (ln_cnn) := 0;
   lt_nq1 (ln_cnn) := 0;
   lt_nq2 (ln_cnn) := 0;
   lt_nq3 (ln_cnn) := 0;
   lt_nq4 (ln_cnn) := 0;

   WHILE lt_dt (ln_i) < ld_tmp - 1 / 48 AND ln_i < ln_cn LOOP   --сдвиг для след.
    ln_i := ln_i + 1;
    raise_application_error (-20001, 'das_pg.Correchalfhourtime: Интересно, я сюда не ожидал попасть.');
   END LOOP;

   LOOP
    ln_k := LEAST (GREATEST (LEAST (lt_dt (ln_i), ld_tmp) - GREATEST (lt_dt (ln_i - 1), ld_tmp - 1 / 48), 0), 1 / 48);
    lt_ner (ln_cnn) := lt_ner (ln_cnn) + TRUNC (lt_er (ln_i) * ln_k, ln_rn);
    lt_ned (ln_cnn) := lt_ned (ln_cnn) + TRUNC (lt_ed (ln_i) * ln_k, ln_rn);
    lt_nq1 (ln_cnn) := lt_nq1 (ln_cnn) + TRUNC (lt_q1 (ln_i) * ln_k, ln_rn);
    lt_nq2 (ln_cnn) := lt_nq2 (ln_cnn) + TRUNC (lt_q2 (ln_i) * ln_k, ln_rn);
    lt_nq3 (ln_cnn) := lt_nq3 (ln_cnn) + TRUNC (lt_q3 (ln_i) * ln_k, ln_rn);
    lt_nq4 (ln_cnn) := lt_nq4 (ln_cnn) + TRUNC (lt_q4 (ln_i) * ln_k, ln_rn);
    lt_nmtrsn (ln_cnn) := lt_mtrsn (ln_i);

    IF lt_dt (ln_i) < ld_tmp AND ln_i < ln_cn THEN
     ln_i := ln_i + 1;
    ELSE
     EXIT;
    END IF;
   END LOOP;

   IF ld_tmp = ld_max THEN   --Для подгонки
    lt_ner (ln_cnn) := TRUNC (ln_ser, ln_rn);
    lt_ned (ln_cnn) := TRUNC (ln_sed, ln_rn);
    lt_nq1 (ln_cnn) := TRUNC (ln_sq1, ln_rn);
    lt_nq2 (ln_cnn) := TRUNC (ln_sq2, ln_rn);
    lt_nq3 (ln_cnn) := TRUNC (ln_sq3, ln_rn);
    lt_nq4 (ln_cnn) := TRUNC (ln_sq4, ln_rn);
    EXIT;
   ELSE
    ln_ser := ln_ser - lt_ner (ln_cnn);
    ln_sed := ln_sed - lt_ned (ln_cnn);
    ln_sq1 := ln_sq1 - lt_nq1 (ln_cnn);
    ln_sq2 := ln_sq2 - lt_nq2 (ln_cnn);
    ln_sq3 := ln_sq3 - lt_nq3 (ln_cnn);
    ln_sq4 := ln_sq4 - lt_nq4 (ln_cnn);
   END IF;

   ld_tmp := LEAST (ld_tmp + 1 / 48, ld_max);   --чтоб учесть последнюю
  END LOOP;

  FOR i IN 1 .. ln_cnn LOOP
   INSERT INTO halfhourtmp
               (mid, date_time, er, ed, q1, q2, q3, q4, er_mtrsn, nsource
               )
        VALUES (an_mid, lt_ndt (i), lt_ner (i), lt_ned (i), lt_nq1 (i), lt_nq2 (i), lt_nq3 (i), lt_nq4 (i), lt_nmtrsn (i), ln_source
               );
  END LOOP;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20001, 'das_pg.correchalfhourtime: ' || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE insert_hf_in_profile (an_mid NUMBER, ad_date DATE,   --ad_date передавать по зиме
                                                             an_period NUMBER, an_er NUMBER, an_ed NUMBER, an_q1 NUMBER, an_q2 NUMBER, an_q3 NUMBER, an_q4 NUMBER,
 an_rn NUMBER
 ) IS
  ln_stepprofile   NUMBER              DEFAULT util_pg.stepprofile_f;
  ln_cnprf         NUMBER              DEFAULT 24 * 60 / an_period;
  ln_tmp           NUMBER;
  ln_ser           NUMBER;
  ln_sed           NUMBER;
  ln_sq1           NUMBER;
  ln_sq2           NUMBER;
  ln_sq3           NUMBER;
  ln_sq4           NUMBER;
  ln_ter           common_pg.tt_number;
  ln_ted           common_pg.tt_number;
  ln_tq1           common_pg.tt_number;
  ln_tq2           common_pg.tt_number;
  ln_tq3           common_pg.tt_number;
  ln_tq4           common_pg.tt_number;
  ld_date          DATE;
  ln_source        NUMBER;
 BEGIN
  IF /*Доп проверка*/ an_period > ln_stepprofile AND MOD (an_period, ln_stepprofile) = 0 AND util_pg.get_typekeephalfhour (an_mid) = 2 THEN   --Расчитывать PROFILE по ГН счетчика
   ln_ser := an_er;
   ln_sed := an_ed;
   ln_sq1 := an_q1;
   ln_sq2 := an_q2;
   ln_sq3 := an_q3;
   ln_sq4 := an_q4;
   ln_tmp := an_period / ln_stepprofile;

   --Рисуем профиль PROFILE
   FOR i IN 1 .. ln_tmp LOOP   --Сначала целочисленно
    ln_ter (i) := TRUNC (an_er / ln_tmp, an_rn);
    ln_ted (i) := TRUNC (an_ed / ln_tmp, an_rn);
    ln_tq1 (i) := TRUNC (an_q1 / ln_tmp, an_rn);
    ln_tq2 (i) := TRUNC (an_q2 / ln_tmp, an_rn);
    ln_tq3 (i) := TRUNC (an_q3 / ln_tmp, an_rn);
    ln_tq4 (i) := TRUNC (an_q4 / ln_tmp, an_rn);
    ln_ser := ln_ser - ln_ter (i);
    ln_sed := ln_sed - ln_ted (i);
    ln_sq1 := ln_sq1 - ln_tq1 (i);
    ln_sq2 := ln_sq2 - ln_tq2 (i);
    ln_sq3 := ln_sq3 - ln_tq3 (i);
    ln_sq4 := ln_sq4 - ln_tq4 (i);
   END LOOP;

   FOR i IN 1 .. ln_tmp LOOP   --Затем расскидываем 1
    IF ln_ser > 0 THEN
     ln_ter (i) := ln_ter (i) + LEAST (1, ln_ser);
     ln_ser := ln_ser - LEAST (1, ln_ser);
    END IF;

    IF ln_sed > 0 THEN
     ln_ted (i) := ln_ted (i) + LEAST (1, ln_sed);
     ln_sed := ln_sed - LEAST (1, ln_sed);
    END IF;

    IF ln_sq1 > 0 THEN
     ln_tq1 (i) := ln_tq1 (i) + LEAST (1, ln_sq1);
     ln_sq1 := ln_sq1 - LEAST (1, ln_sq1);
    END IF;

    IF ln_sq2 > 0 THEN
     ln_tq2 (i) := ln_tq2 (i) + LEAST (1, ln_sq2);
     ln_sq2 := ln_sq2 - LEAST (1, ln_sq2);
    END IF;

    IF ln_sq3 > 0 THEN
     ln_tq3 (i) := ln_tq3 (i) + LEAST (1, ln_sq3);
     ln_sq3 := ln_sq3 - LEAST (1, ln_sq3);
    END IF;

    IF ln_sq4 > 0 THEN
     ln_tq4 (i) := ln_tq4 (i) + LEAST (1, ln_sq4);
     ln_sq4 := ln_sq4 - LEAST (1, ln_sq4);
    END IF;
   END LOOP;

   FOR i IN 1 .. ln_tmp LOOP   --теперь записываем
    ld_date := ad_date - 1 / ln_cnprf + i / (ln_cnprf * ln_tmp);

    IF util_pg.newhalfhour_f = 1 AND util_pg.is_timeswitch (ld_date) = -1 THEN   --Время перехода с лета на зиму (nsource=19,29)
     ln_source := 19;
    ELSE
     ln_source := 10;
    END IF;

    ld_date := util_pg.to_localtime_if_new (ld_date);

    BEGIN
     INSERT INTO PROFILE
                 (mid, date_time, nsource, er, ed, q1, q2, q3, q4
                 )
          VALUES (an_mid, ld_date, ln_source, ln_ter (i), ln_ted (i), ln_tq1 (i), ln_tq2 (i), ln_tq3 (i), ln_tq4 (i)
                 );
    EXCEPTION
     WHEN DUP_VAL_ON_INDEX THEN
      UPDATE PROFILE
         SET er = ln_ter (i),
             ed = ln_ted (i),
             q1 = ln_tq1 (i),
             q2 = ln_tq2 (i),
             q3 = ln_tq3 (i),
             q4 = ln_tq4 (i)
       WHERE mid = an_mid AND date_time = ld_date AND nsource = ln_source;
    END;
   END LOOP;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20001, 'das_pg.insert_hf_in_profile: ' || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 --Вычисяем Профиль по curr_power_arch
 PROCEDURE insert_cp_in_profile (an_mid NUMBER) IS
  ln_stepprofile   NUMBER;
  ln_rn   CONSTANT NUMBER              := 5;
  ld_start         DATE;
  ld_end           DATE;
  ld_tmp           DATE;
  lt_ras           common_pg.tt_number;
  k1               NUMBER;
  k2               NUMBER;
 BEGIN
  --Если не ведем архив параметров сети то выходим
  IF NVL (util_pg.is_calc_profile_by_cp (an_mid), 0) <> 1 THEN
   RETURN;
  END IF;

  ln_stepprofile := util_pg.stepprofile_f;

  SELECT date_time, er, ed, q1, q2, q3, q4
    INTO ld_end, lt_ras (7), lt_ras (8), lt_ras (9), lt_ras (10), lt_ras (11), lt_ras (12)
    FROM curr_power
   WHERE mid = an_mid;

  SELECT date_time, er, ed, q1, q2, q3, q4
    INTO ld_start, lt_ras (1), lt_ras (2), lt_ras (3), lt_ras (4), lt_ras (5), lt_ras (6)
    FROM curr_power_arch
   WHERE mid = an_mid AND date_time = (SELECT MAX (date_time)
                                         FROM curr_power_arch
                                        WHERE mid = an_mid AND date_time < ld_end);

  ld_tmp := util_pg.ceil_d (ld_start + 1 / 86400, 60 * ln_stepprofile / 86400);

  WHILE ld_tmp <= ld_end LOOP
   IF (ld_tmp - ld_start) < 60 * ln_stepprofile / 86400 THEN
    k1 := (ld_tmp - ld_start) * 24;
   ELSE
    k1 := 0;
   END IF;

   k2 := (60 * ln_stepprofile / 86400) * 24 - k1;

   BEGIN
    INSERT INTO PROFILE
                (mid, date_time, er, ed,
                 q1, q2,
                 q3, q4
                )
         VALUES (an_mid, ld_tmp, ROUND (k1 * lt_ras (1) + k2 * lt_ras (7), ln_rn), ROUND (k1 * lt_ras (2) + k2 * lt_ras (8), ln_rn),
                 ROUND (k1 * lt_ras (3) + k2 * lt_ras (9), ln_rn), ROUND (k1 * lt_ras (4) + k2 * lt_ras (10), ln_rn),
                 ROUND (k1 * lt_ras (5) + k2 * lt_ras (11), ln_rn), ROUND (k1 * lt_ras (6) + k2 * lt_ras (12), ln_rn)
                );
   EXCEPTION
    WHEN DUP_VAL_ON_INDEX THEN
     UPDATE PROFILE
        SET er = ROUND (k1 * lt_ras (1) + k2 * lt_ras (7), ln_rn),
            ed = ROUND (k1 * lt_ras (2) + k2 * lt_ras (8), ln_rn),
            q1 = ROUND (k1 * lt_ras (3) + k2 * lt_ras (9), ln_rn),
            q2 = ROUND (k1 * lt_ras (4) + k2 * lt_ras (10), ln_rn),
            q3 = ROUND (k1 * lt_ras (5) + k2 * lt_ras (11), ln_rn),
            q4 = ROUND (k1 * lt_ras (6) + k2 * lt_ras (12), ln_rn)
      WHERE mid = an_mid AND date_time = ld_tmp;
   END;

   ld_tmp := ld_tmp + 60 * ln_stepprofile / 86400;
  END LOOP;
 EXCEPTION
  WHEN NO_DATA_FOUND THEN
   NULL;
  WHEN OTHERS THEN
   raise_application_error (-20001, 'das_pg.insert_cp_in_profile: ' || SQLERRM (SQLCODE));
 END;

