 PROCEDURE recalcperiod (an_maket NUMBER, ddate_ DATE) IS
  ld_date   DATE DEFAULT TRUNC (LEAST (ddate_, SYSDATE - 1));
 BEGIN
  IF admin_pg.lock_p (cn_lock, 'halfhourtmp') <> 1 THEN
   raise_application_error (-20009,
                            'Перерасчет суточных расходов не может быть проведен ввиду отсутствия возможности блокировки таблицы в течении ' || cn_lock || ' сек.',
                            TRUE);
  END IF;

  DELETE FROM halfhourold
        WHERE date_time > ld_date AND (nsource < 0 OR nsource > util_pg.cn_manualinputw);

  DELETE FROM billold
        WHERE date_time > ld_date;

  admin_pg.set_calcperiod (ld_date);
  closeperiod (an_maket, TRUNC (SYSDATE) - 1);
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001, 'das_pg.recalcperiod: ' || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE replicator (ad_date DATE) IS
  cn_step   CONSTANT NUMBER := 1 / 48;
  ld_date            DATE   DEFAULT TRUNC (LEAST (ad_date, SYSDATE));
  ln_source          NUMBER DEFAULT 10;
  ln_kc              NUMBER;

  CURSOR lcur_sel IS
   SELECT f.mid, f.ncalcpointtype, util_pg.get_curr_power (f.mid, ld_date) ncurrpower, util_pg.get_months_consumpt (f.mid, ld_date) nconsumpt,
          util_pg.get_workhours (f.mid, TO_CHAR (ld_date, 'YYYYMM')) / (24 * TO_CHAR (LAST_DAY (ld_date), 'DD')) nworkhours,
          NVL (util_pg.get_multiplier (f.mid, ld_date), 1) nkc, c.gid
     FROM feeders f, calcpointbygroup c
    WHERE f.ncalcpointtype IN (cn_calcpointtype_cons, cn_calcpointtype_amm, cn_calcpointtype_sum) AND f.mid = c.mid(+);

  ln_cn              NUMBER DEFAULT util_pg.get_count_dt (ld_date, cn_step);
 BEGIN
  SAVEPOINT replicator_sp;

  FOR lc IN lcur_sel LOOP
   IF util_pg.get_customer_id = 10 AND lc.nkc <> 0 THEN   --Захотели
    ln_kc := 1 / lc.nkc;
   ELSE
    ln_kc := lc.nkc;
   END IF;

   DELETE FROM bill
         WHERE mid = lc.mid AND date_time = ld_date;

   DELETE FROM halfhourtmp
         WHERE mid = lc.mid;

   DELETE FROM halfhourold
         WHERE mid = lc.mid AND date_time > ld_date AND date_time <= ld_date + 1;

   IF lc.ncalcpointtype = cn_calcpointtype_cons THEN
    FOR i IN 1 .. ln_cn LOOP
     INSERT INTO halfhourtmp
                 (mid, date_time, nsource, er,
                  ed
                 )
          VALUES (lc.mid, util_pg.to_unlocaltime_if_new (ld_date) + i * cn_step, ln_source, DECODE (SIGN (lc.ncurrpower), -1, 0, lc.ncurrpower * lc.nworkhours / 2),
                  DECODE (SIGN (lc.ncurrpower), 1, 0, ABS (lc.ncurrpower * lc.nworkhours / 2))
                 );
    END LOOP;
   ELSIF lc.ncalcpointtype = cn_calcpointtype_amm THEN
    FOR i IN 1 .. ln_cn LOOP
     INSERT INTO halfhourtmp
                 (mid, date_time, nsource,
                  er,
                  ed
                 )
          VALUES (lc.mid, util_pg.to_unlocaltime_if_new (ld_date) + i * cn_step, ln_source,
                  DECODE (SIGN (lc.nconsumpt), -1, 0, lc.nconsumpt / (24 * TO_CHAR (LAST_DAY (ld_date), 'DD')) / 2),
                  DECODE (SIGN (lc.nconsumpt), 1, 0, ABS (lc.nconsumpt / (24 * TO_CHAR (LAST_DAY (ld_date), 'DD')) / 2))
                 );
    END LOOP;
   ELSIF lc.ncalcpointtype = cn_calcpointtype_sum AND lc.gid > 0 THEN
    FOR lc1 IN (SELECT   util_pg.trunc_d (util_pg.to_unlocaltime (p.date_time, p.nsource) - 1 / 86400, cn_step) + cn_step dat,
                         SUM (DECODE (g.inverted, 'y', p.ed * DECODE (g.npartly, 1, 0, 1), p.er * DECODE (g.npartly, 2, 0, 1))) er,
                         SUM (DECODE (g.inverted, 'y', p.er * DECODE (g.npartly, 2, 0, 1), p.ed * DECODE (g.npartly, 1, 0, 1))) ed,
                         SUM (DECODE (g.inverted, 'y', p.q3 * DECODE (g.npartly, 1, 0, 1), p.q1 * DECODE (g.npartly, 2, 0, 1))) q1,
                         SUM (DECODE (g.inverted, 'y', p.q1 * DECODE (g.npartly, 2, 0, 1), p.q3 * DECODE (g.npartly, 1, 0, 1))) q3,
                         SUM (DECODE (g.inverted, 'y', p.q4 * DECODE (g.npartly, 1, 0, 1), p.q2 * DECODE (g.npartly, 2, 0, 1))) q2,
                         SUM (DECODE (g.inverted, 'y', p.q2 * DECODE (g.npartly, 2, 0, 1), p.q4 * DECODE (g.npartly, 1, 0, 1))) q4
                    FROM halfhour p, GROUPS g
                   WHERE p.mid = g.mid AND p.date_time > ld_date AND p.date_time <= ld_date + 1
                         AND g.gid IN (SELECT     gid
                                             FROM GROUPS
                                       CONNECT BY ((PRIOR gid = PARENT) OR (PRIOR nroot2 = nroot2 AND PRIOR nroot1 > 0 AND nroot1 IS NULL))
                                       START WITH gid = lc.gid)
                GROUP BY util_pg.trunc_d (util_pg.to_unlocaltime (p.date_time, p.nsource) - 1 / 86400, cn_step) + cn_step) LOOP
     ins_halfhourtmp (lc.mid, lc1.dat, NULL, lc1.er * ln_kc, lc1.ed * ln_kc, lc1.q1 * ln_kc, lc1.q3 * ln_kc, lc1.q2 * ln_kc, lc1.q4 * ln_kc, NULL,
                      comsrv_pg.cn_calc, NULL);
    END LOOP;
   END IF;
  END LOOP;

  das_pg.checkhalfhour (0);
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT replicator_sp;
   raise_application_error (-20001, 'das_pg.replicator: ' || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------
 PROCEDURE ins_halfhourtmp (an_mid NUMBER, ad_date DATE, an_source NUMBER, an_er NUMBER, an_ed NUMBER, an_q1 NUMBER, an_q3 NUMBER, an_q2 NUMBER, an_q4 NUMBER,
 an_status NUMBER, an_metertype NUMBER, av_qm VARCHAR2, av_mtrsn VARCHAR2
 ) IS
 BEGIN
  ins_halfhourtmp (an_mid, ad_date, an_source, an_er, an_ed, an_q1, an_q3, an_q2, an_q4, NULL, NULL, NULL, NULL, NULL, NULL, an_status, an_metertype, av_qm,
                   av_mtrsn);
 END;

-----------------------------------------------------------------------------------------------------------------------
 PROCEDURE ins_halfhourtmp (an_mid NUMBER, ad_date DATE, an_source NUMBER, an_er NUMBER, an_ed NUMBER, an_q1 NUMBER, an_q3 NUMBER, an_q2 NUMBER, an_q4 NUMBER,
 an_erm NUMBER, an_edm NUMBER, an_q1m NUMBER, an_q3m NUMBER, an_q2m NUMBER, an_q4m NUMBER, an_status NUMBER, an_metertype NUMBER, av_qm VARCHAR2, av_mtrsn VARCHAR2
 ) IS
  ln_source   NUMBER DEFAULT NVL (an_source, comsrv_pg.cn_auto);
 BEGIN
  INSERT INTO halfhourtmp
              (mid, date_time, nsource, er, ed, q1, q3, q2, q4, erm, edm, q1m, q3m, q2m, q4m, status, nmetertype,
               vqm, er_mtrsn
              )
       VALUES (an_mid, ad_date, ln_source, an_er, an_ed, an_q1, an_q3, an_q2, an_q4, an_erm, an_edm, an_q1m, an_q3m, an_q2m, an_q4m, an_status, an_metertype,
               av_qm, av_mtrsn
              );
 EXCEPTION
  WHEN DUP_VAL_ON_INDEX THEN
   UPDATE halfhourtmp
      SET er = an_er,
          ed = an_ed,
          q1 = an_q1,
          q3 = an_q3,
          q2 = an_q2,
          q4 = an_q4,
          erm = an_erm,
          edm = an_edm,
          q1m = an_q1m,
          q3m = an_q3m,
          q2m = an_q2m,
          q4m = an_q4m,
          status = an_status,
          nmetertype = an_metertype,
          vqm = av_qm,
          er_mtrsn = av_mtrsn
    WHERE mid = an_mid AND date_time = ad_date AND nsource = ln_source;
  WHEN OTHERS THEN
   raise_application_error (-20002, 'das_pg.ins_halfhourtmp: an_mid=' || an_mid || ' ' || SQLERRM (SQLCODE));
 END;
-----------------------------------------------------------------------------------------------------------------------
END;
