-------------------------------------------------------------------------------------------
  -- Определение параметров загрузки данных
 PROCEDURE getparamslg (av_name VARCHAR2,   -- строка - имя файла
                                         av_lines common_pg.tt_varchar2,   -- массив строк - содержимое файла
                                                                        an_mid OUT NUMBER,   -- mid точки
                                                                                          av_descr OUT VARCHAR2,   -- описание точки
 an_interval OUT NUMBER   -- Период интеграции счётчика [мин]
 ) IS
  ld_date       DATE           DEFAULT NULL;
  ld_pdate      DATE           DEFAULT NULL;
  ln_cnt_03     NUMBER         DEFAULT 0;
  ln_cnt_05     NUMBER         DEFAULT 0;
  ln_cnt_10     NUMBER         DEFAULT 0;
  ln_cnt_15     NUMBER         DEFAULT 0;
  ln_cnt_30     NUMBER         DEFAULT 0;
  ln_cnt_60     NUMBER         DEFAULT 0;
  ln_interval   NUMBER;
  ln_mtrsn      VARCHAR2 (256);
  ln_b          NUMBER;
  ln_e          NUMBER;
 BEGIN
  ln_b := INSTR (av_name, '\', -1) + 1;
  ln_e := INSTR (av_name, '.', -1);
  ln_mtrsn := SUBSTR (av_name, ln_b, ln_e - ln_b);

  BEGIN
   SELECT m.mid, util_pg.get_pointname (m.mid, 2)
     INTO an_mid, av_descr
     FROM meters m
    WHERE mtrsn = ln_mtrsn AND ROWNUM = 1;
  EXCEPTION
   WHEN NO_DATA_FOUND THEN
    an_mid := 0;
    av_descr := 'Для файла не найденна соответствующая точка в БД.';
   WHEN OTHERS THEN
    RAISE;
  END;

  FOR i IN av_lines.FIRST .. av_lines.LAST LOOP
   IF INSTR (av_lines (i), ' | ') <> 0 AND INSTR (av_lines (i), 'Current Average Demand') = 0 THEN
    ld_pdate := ld_date;
    ld_date := TO_DATE (TRIM (' ' FROM util_pg.get_param (av_lines (i), 1, ' | ')), 'dd.mm.yyyy hh24:mi:ss');

    IF ld_pdate IS NOT NULL THEN
     ln_interval := TO_CHAR (ld_date, 'sssss') - TO_CHAR (ld_pdate, 'sssss');

     IF ln_interval = (3 * 60) THEN   -- 3
      ln_cnt_03 := ln_cnt_03 + 1;
     ELSIF ln_interval = (5 * 60) THEN   -- 5
      ln_cnt_05 := ln_cnt_05 + 1;
     ELSIF ln_interval = (10 * 60) THEN   -- 10
      ln_cnt_10 := ln_cnt_10 + 1;
     ELSIF ln_interval = (15 * 60) THEN   -- 15
      ln_cnt_15 := ln_cnt_15 + 1;
     ELSIF ln_interval = (30 * 60) THEN   -- 30
      ln_cnt_30 := ln_cnt_30 + 1;
     ELSIF ln_interval = (60 * 60) THEN   -- 60
      ln_cnt_60 := ln_cnt_60 + 1;
     END IF;
    END IF;
   END IF;
  END LOOP;

  an_interval := GREATEST (ln_cnt_60, ln_cnt_30, ln_cnt_15, ln_cnt_10, ln_cnt_05, ln_cnt_03);

  IF an_interval = ln_cnt_30 THEN
   an_interval := 30;
  ELSIF an_interval = ln_cnt_15 THEN
   an_interval := 15;
  ELSIF an_interval = ln_cnt_10 THEN
   an_interval := 10;
  ELSIF an_interval = ln_cnt_60 THEN
   an_interval := 60;
  ELSIF an_interval = ln_cnt_05 THEN
   an_interval := 5;
  ELSIF an_interval = ln_cnt_03 THEN
   an_interval := 3;
  ELSE
   an_interval := 0;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20001, 'DATA_IMPORT_PG.GetParamsLG: ' || CHR (10) || SQLERRM (SQLCODE));
 END;

-------------------------------------------------------------------------------------------
-- Загрузка файла с разделителями " | "
 PROCEDURE importlg (an_mid NUMBER, av_lines common_pg.tt_varchar2, an_interval NUMBER, av_result OUT VARCHAR2) IS
  lv_state      VARCHAR2 (20);
  ln_er         NUMBER              DEFAULT 0;
  ln_ed         NUMBER              DEFAULT 0;
  ln_q1         NUMBER              DEFAULT 0;
  ln_q3         NUMBER              DEFAULT 0;
  ln_mer        NUMBER              DEFAULT 0;
  ln_med        NUMBER              DEFAULT 0;
  ln_mq1        NUMBER              DEFAULT 0;
  ln_mq3        NUMBER              DEFAULT 0;
  ld_date       DATE;
  ld_date_min   DATE                DEFAULT NULL;
  ld_date_max   DATE                DEFAULT NULL;
  ln_kc         NUMBER;
  ln_source     NUMBER              DEFAULT 10;
  ln_count      NUMBER              DEFAULT 0;
  ln_currline   NUMBER;
  ln_currcol    NUMBER;
  ln_digits     NUMBER;
  lv_mtrsn      VARCHAR2 (100);
  lt_idx        common_pg.tt_number;
  lv_tmp        VARCHAR2 (2000);
  ln_trunc      NUMBER              DEFAULT 3;
 BEGIN
  SAVEPOINT importlg_sp;

  IF an_interval NOT IN (3, 5, 10, 15, 30, 60) THEN
   raise_application_error (-20001, 'Неверно значение периода интеграции счётчика');
  END IF;

  SELECT NVL (MAX (f.kc), 1)
    INTO ln_kc
    FROM feeders f
   WHERE f.mid = an_mid;

  /* заполненеие массива с перечнем индексов:
      1эл - индекс даты
      2эл - индекс статуса
      3эл - индекс мощьности A+
      4эл - индекс мощьности A-
      5эл - индекс мощьности R+
      6эл - индекс мощьности R-
      7эл - показания A+
      8эл - показания A-
      9эл - показания R+
      10эл- показания R-                      */
  FOR n IN av_lines.FIRST .. av_lines.LAST LOOP
   IF INSTR (av_lines (n), ' | ') <> 0 AND INSTR (av_lines (n), 'Clock') <> 0 THEN
    FOR idx IN 1 .. 10 LOOP
     lv_tmp := TRIM (' ' FROM util_pg.get_param (av_lines (n), idx, ' | '));

     IF INSTR (lv_tmp, 'Clock') <> 0 THEN
      lt_idx (1) := idx;
     ELSIF INSTR (lv_tmp, 'Number') <> 0 THEN
      lt_idx (2) := idx;
     ELSIF INSTR (lv_tmp, 'Current Average Demand +A') <> 0 THEN
      lt_idx (3) := idx;
     ELSIF INSTR (lv_tmp, 'Current Average Demand -A') <> 0 THEN
      lt_idx (4) := idx;
     ELSIF INSTR (lv_tmp, 'Current Average Demand +R') <> 0 THEN
      lt_idx (5) := idx;
     ELSIF INSTR (lv_tmp, 'Current Average Demand -R') <> 0 THEN
      lt_idx (6) := idx;
     ELSIF INSTR (lv_tmp, 'Energy +A') <> 0 THEN
      lt_idx (7) := idx;
     ELSIF INSTR (lv_tmp, 'Energy -A') <> 0 THEN
      lt_idx (8) := idx;
     ELSIF INSTR (lv_tmp, 'Energy +R') <> 0 THEN
      lt_idx (9) := idx;
     ELSIF INSTR (lv_tmp, 'Energy -R') <> 0 THEN
      lt_idx (10) := idx;
     END IF;
    END LOOP;

    EXIT;
   END IF;
  END LOOP;

  -- загрузка данных
  FOR i IN av_lines.FIRST .. av_lines.LAST LOOP
   ln_currline := i;

   IF INSTR (av_lines (i), ' | ') <> 0 AND INSTR (av_lines (i), 'Clock') = 0 THEN
    IF lt_idx.COUNT < 10 THEN
     ln_currcol := lt_idx (1);
     ld_date := TO_DATE (TRIM (' ' FROM util_pg.get_param (av_lines (i), lt_idx (1), ' | ')), 'dd.mm.yyyy hh24:mi:ss');
     ln_currcol := lt_idx (2);
     lv_state := TRIM (' ' FROM util_pg.get_param (av_lines (i), lt_idx (2), ' | '));

     IF SUBSTR (lv_state, 8, 1) IN ('8', '9', 'A', 'B', 'C', 'D', 'E', 'F') THEN   --Метка лето
      ld_date := ld_date - 1 / 24;
     END IF;

     ln_currcol := lt_idx (3);
     ln_er := TO_NUMBER (REPLACE (TRIM (' ' FROM util_pg.get_param (av_lines (i), lt_idx (3), ' | ')), ',', '.'));
     ln_currcol := lt_idx (4);
     ln_ed := TO_NUMBER (REPLACE (TRIM (' ' FROM util_pg.get_param (av_lines (i), lt_idx (4), ' | ')), ',', '.'));
     ln_currcol := lt_idx (5);
     ln_q1 := TO_NUMBER (REPLACE (TRIM (' ' FROM util_pg.get_param (av_lines (i), lt_idx (5), ' | ')), ',', '.'));
     ln_currcol := lt_idx (6);
     ln_q3 := TO_NUMBER (REPLACE (TRIM (' ' FROM util_pg.get_param (av_lines (i), lt_idx (6), ' | ')), ',', '.'));
     util_pg.chdr (an_mid, ln_er, ln_ed, ln_q1, ln_q3);
     ln_er := ln_er * an_interval / 60 * ln_kc;
     ln_ed := ln_ed * an_interval / 60 * ln_kc;
     ln_q1 := ln_q1 * an_interval / 60 * ln_kc;
     ln_q3 := ln_q3 * an_interval / 60 * ln_kc;
     comsrv_pg.set_halfhour_zxb (an_mid, ln_er, ln_ed, ln_q1, ln_q3, NULL, ld_date);

     -- определение max и min даты
     IF ld_date_min IS NULL THEN
      ld_date_min := ld_date;
     ELSIF ld_date_min > ld_date THEN
      ld_date_min := ld_date;
     END IF;

     IF ld_date_max IS NULL THEN
      ld_date_max := ld_date;
     ELSIF ld_date_max < ld_date THEN
      ld_date_max := ld_date;
     END IF;

     ln_count := ln_count + 1;
    ELSE   -- загрузка файла нового формата
     ln_currcol := lt_idx (1);
     ld_date := TO_DATE (TRIM (' ' FROM util_pg.get_param (av_lines (i), lt_idx (1), ' | ')), 'dd.mm.yyyy hh24:mi:ss');
     ln_currcol := lt_idx (2);
     lv_state := TRIM (' ' FROM util_pg.get_param (av_lines (i), lt_idx (2), ' | '));

     IF SUBSTR (lv_state, 8, 1) IN ('8', '9', 'A', 'B', 'C', 'D', 'E', 'F') THEN   --Метка лето
      ld_date := ld_date - 1 / 24;
     END IF;

     ln_currcol := lt_idx (3);
     ln_er := TO_NUMBER (REPLACE (TRIM (' ' FROM util_pg.get_param (av_lines (i), lt_idx (3), ' | ')), ',', '.'));
     ln_currcol := lt_idx (4);
     ln_ed := TO_NUMBER (REPLACE (TRIM (' ' FROM util_pg.get_param (av_lines (i), lt_idx (4), ' | ')), ',', '.'));
     ln_currcol := lt_idx (5);
     ln_q1 := TO_NUMBER (REPLACE (TRIM (' ' FROM util_pg.get_param (av_lines (i), lt_idx (5), ' | ')), ',', '.'));
     ln_currcol := lt_idx (6);
     ln_q3 := TO_NUMBER (REPLACE (TRIM (' ' FROM util_pg.get_param (av_lines (i), lt_idx (6), ' | ')), ',', '.'));
     ln_currcol := lt_idx (7);
     ln_mer := TRUNC (TO_NUMBER (REPLACE (TRIM (' ' FROM util_pg.get_param (av_lines (i), lt_idx (7), ' | ')), ',', '.')), ln_trunc);
     ln_currcol := lt_idx (8);
     ln_med := TRUNC (TO_NUMBER (REPLACE (TRIM (' ' FROM util_pg.get_param (av_lines (i), lt_idx (8), ' | ')), ',', '.')), ln_trunc);
     ln_currcol := lt_idx (9);
     ln_mq1 := TRUNC (TO_NUMBER (REPLACE (TRIM (' ' FROM util_pg.get_param (av_lines (i), lt_idx (9), ' | ')), ',', '.')), ln_trunc);
     ln_currcol := lt_idx (10);
     ln_mq3 := TRUNC (TO_NUMBER (REPLACE (TRIM (' ' FROM util_pg.get_param (av_lines (i), lt_idx (10), ' | ')), ',', '.')), ln_trunc);
     -- вычисление расхода
     ln_er := ln_er * an_interval / 60 * ln_kc;
     ln_ed := ln_ed * an_interval / 60 * ln_kc;
     ln_q1 := ln_q1 * an_interval / 60 * ln_kc;
     ln_q3 := ln_q3 * an_interval / 60 * ln_kc;

     SELECT TRIM (MAX (mtrsn)), MAX (DIGITS)
       INTO lv_mtrsn, ln_digits
       FROM meters
      WHERE mid = an_mid;

     IF lv_mtrsn IS NULL THEN
      raise_application_error (-20001, 'Для загрузки ГН необходимо задать номер счетчика в БД точек учета.');
     END IF;

     comsrv_pg.set_halfhour_zxb (an_mid, ln_er, ln_ed, ln_q1, ln_q3, ln_mer, ln_med, ln_mq1, ln_mq3, lv_mtrsn, ln_digits, NULL, ld_date);

     -- определение max и min даты
     IF ld_date_min IS NULL THEN
      ld_date_min := ld_date;
     ELSIF ld_date_min > ld_date THEN
      ld_date_min := ld_date;
     END IF;

     IF ld_date_max IS NULL THEN
      ld_date_max := ld_date;
     ELSIF ld_date_max < ld_date THEN
      ld_date_max := ld_date;
     END IF;

     ln_count := ln_count + 1;
    END IF;
   END IF;
  END LOOP;

  IF ln_count = 0 THEN
   raise_application_error (-20001, 'Файл не содержит данных.');
  END IF;

  admin_pg.fiscal_p (cn_task_code, 1,
                     'Произведена загрузка ГН по точке ' || util_pg.node_path_f (an_mid, 'points', 'mid', 'parent') || ' Дата с '
                     || TO_CHAR (ld_date_min, 'dd.mm.yyyy hh24:mi:ss') || ' по ' || TO_CHAR (ld_date_max, 'dd.mm.yyyy hh24:mi:ss'));
  das_pg.checkhalfhour;

  IF util_pg.newcalcday_f = 0 THEN
   das_pg.calcperiod4bill (TRUNC (ld_date_min), LEAST (TRUNC (ld_date_max) + 1, TRUNC (SYSDATE)));
  ELSE
   das_pg.closeperiod (1, SYSDATE);
  END IF;

  COMMIT;
  av_result :=
   'Загрузка файла прошла успешно.' || CHR (10) || CHR (10) || 'Загрузка графика нагрузки за период' || CHR (10) || ' с : '
   || TO_CHAR (ld_date_min, 'dd month yyyy hh24:mi') || CHR (10) || 'по : ' || TO_CHAR (ld_date_max, 'dd month yyyy hh24:mi') || CHR (10) || 'Ид. точки : ' || an_mid
   || CHR (10) || 'Загруженно ' || ln_count || ' строк.';
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT importlg_sp;
   raise_application_error (-20001,
                            'DATA_IMPORT_PG.ImportLG: ' || CHR (10) || 'Ошибка загрузки данных (стр. ' || ln_currline || ', столб. ' || ln_currcol || ').'
                            || CHR (10) || SQLERRM (SQLCODE));
 END;

-------------------------------------------------------------------------------------------
-- Загрузка файла с разделителями "Tab"
 PROCEDURE import (an_mid NUMBER, av_lines common_pg.tt_varchar2, an_interval NUMBER, av_result OUT VARCHAR2) IS
  ln_er         NUMBER DEFAULT 0;
  ln_ed         NUMBER DEFAULT 0;
  ln_q1         NUMBER DEFAULT 0;
  ln_q3         NUMBER DEFAULT 0;
  ld_date       DATE;
  ld_date_min   DATE   DEFAULT NULL;
  ld_date_max   DATE   DEFAULT NULL;
  ln_kc         NUMBER;
  ln_source     NUMBER DEFAULT 10;
  ln_count      NUMBER DEFAULT 0;
  ln_currline   NUMBER;
  ln_currcol    NUMBER;
  ln_rn         NUMBER DEFAULT 0;
 BEGIN
  IF an_interval NOT IN (3, 5, 10, 15, 30, 60) THEN
   raise_application_error (-20001, 'Неверно значение периода интеграции счётчика');
  END IF;

  SAVEPOINT import_sp;

  SELECT MAX (f.kc)
    INTO ln_kc
    FROM feeders f
   WHERE f.mid = an_mid;

  FOR i IN av_lines.FIRST .. av_lines.LAST LOOP
   ln_currline := i;

   IF INSTR (av_lines (i), CHR (9)) <> 0 AND INSTR (av_lines (i), 'Current Average Demand') = 0 THEN
    ln_currcol := 1;
    ld_date := TO_DATE (TRIM (' ' FROM util_pg.get_param (av_lines (i), 1, CHR (9))), 'yy.mm.dd hh24:mi');
    ln_currcol := 3;
    ln_er := TO_NUMBER (REPLACE (TRIM (' ' FROM util_pg.get_param (av_lines (i), 2, CHR (9))), ',', '.'));
    ln_currcol := 4;
    ln_ed := TO_NUMBER (REPLACE (TRIM (' ' FROM util_pg.get_param (av_lines (i), 4, CHR (9))), ',', '.'));
    ln_currcol := 5;
    ln_q1 := TO_NUMBER (REPLACE (TRIM (' ' FROM util_pg.get_param (av_lines (i), 6, CHR (9))), ',', '.'));
    ln_currcol := 6;
    ln_q3 := TO_NUMBER (REPLACE (TRIM (' ' FROM util_pg.get_param (av_lines (i), 8, CHR (9))), ',', '.'));
    util_pg.chdr (an_mid, ln_er, ln_ed, ln_q1, ln_q3);
    /*              if to_char(ld_DATE,'MM')=10 and ld_DATE>trunc(util_pg.last_dayw(ld_DATE,7))+2/24 and ld_DATE<=trunc(util_pg.last_dayw(ld_DATE,7))+3/24 then
                        ln_SOURCE := 11;
                    END IF;  */
    ln_er := ROUND (ln_er * an_interval / 600 * ln_kc, ln_rn);
    ln_ed := ROUND (ln_ed * an_interval / 600 * ln_kc, ln_rn);
    ln_q1 := ROUND (ln_q1 * an_interval / 600 * ln_kc, ln_rn);
    ln_q3 := ROUND (ln_q3 * an_interval / 600 * ln_kc, ln_rn);
    das_pg.ins_halfhourtmp (an_mid, util_pg.to_unlocaltime_if_new (ld_date), NULL, ln_er, ln_ed, ln_q1, ln_q3, NULL, NULL, NULL, comsrv_pg.cn_maket, NULL);

    -- определение max и min даты
    IF ld_date_min IS NULL THEN
     ld_date_min := ld_date;
    ELSIF ld_date_min > ld_date THEN
     ld_date_min := ld_date;
    END IF;

    IF ld_date_max IS NULL THEN
     ld_date_max := ld_date;
    ELSIF ld_date_max < ld_date THEN
     ld_date_max := ld_date;
    END IF;

    ln_count := ln_count + 1;
   END IF;
  END LOOP;

  IF ln_count = 0 THEN
   raise_application_error (-20001, 'Файл не содержит данных.');
  END IF;

  DELETE FROM halfhourold
        WHERE mid = an_mid AND date_time >= ld_date_min AND date_time <= ld_date_max;

  --    delete from halfhourold where NSWITCH = an_mid and date_time >= ld_date_min AND date_time <= ld_date_max;
  admin_pg.fiscal_p (cn_task_code, 1,
                     'Произведена загрузка ГН по точке ' || util_pg.node_path_f (an_mid, 'points', 'mid', 'parent') || ' Дата с '
                     || TO_CHAR (ld_date_min, 'dd.mm.yyyy hh24:mi:ss') || ' по ' || TO_CHAR (ld_date_max, 'dd.mm.yyyy hh24:mi:ss'));
  das_pg.checkhalfhour;

  IF util_pg.newcalcday_f = 0 THEN
   das_pg.calcperiod4bill (TRUNC (ld_date_min), LEAST (TRUNC (ld_date_max) + 1, TRUNC (SYSDATE)));
  ELSE
   das_pg.closeperiod (1, SYSDATE);
  END IF;

  COMMIT;
  av_result :=
   'Загрузка файла прошла успешно.' || CHR (10) || CHR (10) || 'Загрузка графика нагрузки за период' || CHR (10) || ' с : '
   || TO_CHAR (ld_date_min, 'dd month yyyy hh24:mi') || CHR (10) || 'по : ' || TO_CHAR (ld_date_max, 'dd month yyyy hh24:mi') || CHR (10) || 'Ид. точки : ' || an_mid
   || CHR (10) || 'Загруженно ' || ln_count || ' строк.';
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT import_sp;
   raise_application_error (-20001,
                            'DATA_IMPORT_PG.Import: ' || CHR (10) || 'Ошибка загрузки данных (стр. ' || ln_currline || ', столб. ' || ln_currcol || ').' || CHR (10)
                            || SQLERRM (SQLCODE));
 END;

-------------------------------------------------------------------------------------------
  -- Загрузка данных за сутки (для SL7000)
 PROCEDURE loaddatabybill (an_mid NUMBER,   -- mid точки учёта
                                         av_dateformat VARCHAR2,   --формат даты
                                                                av_date VARCHAR2,   --дата
                                                                                 av_times common_pg.tt_varchar2,   -- массив временем показаний в формате 'hh24:mi:ss'
 av_chann1 common_pg.tt_varchar2,   -- массив данных по 1 каналу
                                 av_chann2 common_pg.tt_varchar2,   -- массив данных по 2 каналу
                                                                 av_chann3 common_pg.tt_varchar2,   -- массив данных по 3 каналу
                                                                                                 av_chann4 common_pg.tt_varchar2,   -- массив данных по 4 каналу
 av_chann5 common_pg.tt_varchar2,   -- массив данных по 5 каналу
                                 av_chann6 common_pg.tt_varchar2,   -- массив данных по 6 каналу
                                                                 av_chann7 common_pg.tt_varchar2,   -- массив данных по 7 каналу
                                                                                                 av_chann8 common_pg.tt_varchar2,   -- массив данных по 8 каналу
 an_type NUMBER   -- тип расшифровки данных
 -- an_TYPE=1  - CHANN1=A+, CHANN2=A-, CHANN3=R+, CHANN4=R-, CHANN5..8 - не используются
 ) IS
  ln_source   NUMBER;
  ln_str      NUMBER            DEFAULT 0;
  ld_date     DATE;
  lv_date     VARCHAR2 (32);
  ln_kc       NUMBER;
  ln_col      NUMBER;
  ln_chann1   NUMBER;
  ln_chann2   NUMBER;
  ln_chann3   NUMBER;
  ln_chann4   NUMBER;
  lt_date     common_pg.tt_date;
 BEGIN
  IF an_type NOT IN (1, 2) THEN
   raise_application_error (-20001, 'Тип загрузки не поддерживается');
  END IF;

  BEGIN   --пробуем AMERICAN
   EXECUTE IMMEDIATE 'ALTER SESSION SET NLS_LANGUAGE = AMERICAN';

   ld_date := TO_DATE (av_date, av_dateformat);
  EXCEPTION
   WHEN OTHERS THEN
    NULL;
  END;

  IF ld_date IS NULL THEN   --пробуем UKRAINIAN
   BEGIN
    EXECUTE IMMEDIATE 'ALTER SESSION SET NLS_LANGUAGE = UKRAINIAN';

    ld_date := TO_DATE (av_date, av_dateformat);
   EXCEPTION
    WHEN OTHERS THEN
     NULL;
   END;
  END IF;

  IF ld_date IS NULL THEN   --пробуем RUSSIAN
   BEGIN
    EXECUTE IMMEDIATE 'ALTER SESSION SET NLS_LANGUAGE = RUSSIAN';

    ld_date := TO_DATE (av_date, av_dateformat);
   EXCEPTION
    WHEN OTHERS THEN
     NULL;
   END;
  END IF;

  EXECUTE IMMEDIATE 'ALTER SESSION SET NLS_LANGUAGE = RUSSIAN';

  IF ld_date IS NULL THEN
   raise_application_error (-20001, 'Формат даты не распознан');
  END IF;

  lv_date := TO_CHAR (ld_date, 'YYYYMMDD');
  admin_pg.fiscal_p (cn_task_code, 1,
                     'Произведена загрузка суточных данных по точке ' || util_pg.node_path_f (an_mid, 'points', 'mid', 'parent') || ' Дата '
                     || TO_DATE (ld_date, 'dd.mm.yyyy hh24:mi:ss'));

  SELECT NVL (MAX (f.kc), 1)
    INTO ln_kc
    FROM feeders f
   WHERE f.mid = an_mid;

  IF an_type = 2 THEN
   ln_kc := ln_kc / 1000;
  END IF;

  ln_str := 1;

  FOR i IN 1 .. av_times.COUNT LOOP
   ln_col := 1;
   ld_date := TO_DATE (lv_date || '-' || av_times (i), 'YYYYMMDD-HH24:MI:SS');

   IF av_times (i) = '00:00:00' THEN
    ld_date := ld_date + 1;
   END IF;

   ln_col := 2;
   ln_chann1 := REPLACE (av_chann1 (i), ',', '.') * ln_kc;
   ln_col := 3;
   ln_chann2 := REPLACE (av_chann2 (i), ',', '.') * ln_kc;
   ln_col := 4;
   ln_chann3 := REPLACE (av_chann3 (i), ',', '.') * ln_kc;
   ln_col := 5;
   ln_chann4 := REPLACE (av_chann4 (i), ',', '.') * ln_kc;
   ln_source := comsrv_pg.cn_auto;

   IF util_pg.is_timeswitch (ld_date) = -1 THEN   --Осенний переход
    FOR z IN 1 .. lt_date.COUNT LOOP
     IF lt_date (z) = ld_date THEN
      ln_source := comsrv_pg.cn_auto + 9;
      EXIT;
     END IF;
    END LOOP;

    IF ln_source = comsrv_pg.cn_auto THEN   --Не повторная дата
     lt_date (lt_date.COUNT + 1) := ld_date;
    END IF;
   END IF;

   DELETE FROM halfhourtmp
         WHERE mid = an_mid AND date_time = util_pg.to_unlocaltime_if_new (ld_date, ln_source);

   DELETE FROM halfhourold
         WHERE mid = an_mid AND date_time = ld_date AND nsource = ln_source;

   DELETE FROM billold
         WHERE mid = an_mid AND date_time = TRUNC (ld_date - 1 / 86400) + 1;

   das_pg.ins_halfhourtmp (an_mid, util_pg.to_unlocaltime_if_new (ld_date, ln_source), NULL, ln_chann1, ln_chann2, ln_chann3, ln_chann4, NULL, NULL, NULL,
                           comsrv_pg.cn_maket, NULL);
   ln_str := ln_str + 1;
  END LOOP;

  lt_date.DELETE;
  das_pg.checkhalfhour;

  IF util_pg.newcalcday_f = 0 THEN
   das_pg.calcperiod4bill (TRUNC (ld_date), TRUNC (ld_date) + 1);
  ELSE
   das_pg.closeperiod (1, SYSDATE);
  END IF;

  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001,
                            'data_import_pg.loaddatabybill: ' || CHR (10) || 'Ошибка загрузки данных (стр. ' || ln_str || ', столб. ' || ln_col || ', Дата: '
                            || av_date || ').' || CHR (10) || SQLERRM (SQLCODE));
 END;
-------------------------------------------------------------------------------------------
 -- Загрузка файла с разделителями " " "
 -- Kondakov A.G. 4.11.2008
 PROCEDURE import_alpha (an_mid NUMBER, av_lines common_pg.tt_varchar2, an_interval NUMBER, av_result OUT VARCHAR2) IS
  lv_state      VARCHAR2 (20);
  ln_er         NUMBER              DEFAULT 0;
  ln_ed         NUMBER              DEFAULT 0;
  ln_q1         NUMBER              DEFAULT 0;
  ln_q3         NUMBER              DEFAULT 0;
  ln_mer        NUMBER              DEFAULT 0;
  ln_med        NUMBER              DEFAULT 0;
  ln_mq1        NUMBER              DEFAULT 0;
  ln_mq3        NUMBER              DEFAULT 0;
  ld_date       DATE;
  ld_date_min   DATE                DEFAULT NULL;
  ld_date_max   DATE                DEFAULT NULL;
  ln_kc         NUMBER;
  ln_source     NUMBER              DEFAULT 10;
  ln_count      NUMBER              DEFAULT 0;
  ln_currline   NUMBER;
  ln_currcol    NUMBER;
  ln_digits     NUMBER;
  lv_mtrsn      VARCHAR2(100);
  lt_idx        common_pg.tt_number;
  lv_tmp        VARCHAR2 (2000);
  ln_sub_from   NUMBER;
  ln_sub_to     NUMBER;
  lv_param      VARCHAR2(2000);
  ln_period     NUMBER;
  ln_trunc      NUMBER              DEFAULT 3;
  
 BEGIN
  SAVEPOINT importlg_sp;

  SELECT NVL (MAX (f.kc), 1)
    INTO ln_kc
    FROM feeders f
   WHERE f.mid = an_mid;
  
  -- загрузка данных
  FOR i IN av_lines.FIRST .. av_lines.LAST LOOP
   ln_currline := i;
   IF av_lines(i) IS NOT NULL THEN
     
     lv_tmp := av_lines(i);
     ln_sub_from := INSTR(lv_tmp,'"',1,3)+1;
     ln_sub_to := INSTR(lv_tmp,'"',1,6);
     ln_currcol := ln_sub_from;
     IF (ln_sub_to-ln_sub_from)<9 THEN
        raise_application_error (-20001, 'Не найдена дата показаний');
     END IF;
     lv_param := REPLACE(SUBSTR(lv_tmp,ln_sub_from,ln_sub_to-ln_sub_from),'"');
     IF INSTR(lv_param,'24:')<>0  THEN
        lv_param := REPLACE(lv_param,'24:','00:');    
        ld_date := TO_DATE(lv_param,'dd/mm/yy hh24:mi')+1;     -- дата показаний
     ELSE
        ld_date := TO_DATE(lv_param,'dd/mm/yy hh24:mi');       -- дата показаний
     END IF;

     FOR j IN 1..5 LOOP
         ln_sub_from := ln_sub_to+1;
         ln_currcol := ln_sub_from;
         lv_tmp := TRIM(SUBSTR(av_lines(i),ln_sub_from));   -- находим все после предыдущего параметра
         lv_param := util_pg.get_param(lv_tmp,1,' ');       -- получение нового параметра
         IF j=1 THEN
             ln_period := TO_NUMBER(lv_param);                  -- период интеграции
         ELSIF j=2 THEN
             ln_er := TO_NUMBER(REPLACE(lv_param,',','.'));     -- er
         ELSIF j=3 THEN
             ln_ed := TO_NUMBER(REPLACE(lv_param,',','.'));     -- ed
         ELSIF j=4 THEN
             ln_q1 := TO_NUMBER(REPLACE(lv_param,',','.'));     -- q1
         ELSIF j=5 THEN
             ln_q3 := TO_NUMBER(REPLACE(lv_param,',','.'));     -- q3
         END IF; 
            ln_sub_to := INSTR(av_lines(i),lv_tmp) + LENGTH(lv_param);
     END LOOP;
     
     util_pg.chdr (an_mid, ln_er, ln_ed, ln_q1, ln_q3);
     ln_er := ln_er * ln_period / 60 * ln_kc;
     ln_ed := ln_ed * ln_period / 60 * ln_kc;
     ln_q1 := ln_q1 * ln_period / 60 * ln_kc;
     ln_q3 := ln_q3 * ln_period / 60 * ln_kc;
     
     comsrv_pg.set_halfhour_zxb (an_mid, ln_er, ln_ed, ln_q1, ln_q3, NULL, ld_date);
     
     -- определение max и min даты
     IF ld_date_min IS NULL THEN
      ld_date_min := ld_date;
     ELSIF ld_date_min > ld_date THEN
      ld_date_min := ld_date;
     END IF;

     IF ld_date_max IS NULL THEN
      ld_date_max := ld_date;
     ELSIF ld_date_max < ld_date THEN
      ld_date_max := ld_date;
     END IF;
     
     ln_count := ln_count + 1;
   END IF;  
  END LOOP;

  IF ln_count = 0 THEN
   raise_application_error (-20001, 'Файл не содержит данных.');
  END IF;

  admin_pg.fiscal_p (cn_task_code, 1,
                     'Произведена загрузка ГН по точке ' || util_pg.node_path_f (an_mid, 'points', 'mid', 'parent') || ' Дата с '
                     || TO_CHAR (ld_date_min, 'dd.mm.yyyy hh24:mi:ss') || ' по ' || TO_CHAR (ld_date_max, 'dd.mm.yyyy hh24:mi:ss'));
  das_pg.checkhalfhour;

  IF util_pg.newcalcday_f = 0 THEN
   das_pg.calcperiod4bill (TRUNC (ld_date_min), LEAST (TRUNC (ld_date_max) + 1, TRUNC (SYSDATE)));
  ELSE
   das_pg.closeperiod (1, SYSDATE);
  END IF;

  COMMIT;
  av_result :=
   'Загрузка файла прошла успешно.' || CHR (10) || CHR (10) || 'Загрузка графика нагрузки за период' || CHR (10) || ' с : '
   || TO_CHAR (ld_date_min, 'dd month yyyy hh24:mi') || CHR (10) || 'по : ' || TO_CHAR (ld_date_max, 'dd month yyyy hh24:mi') || CHR (10) || 'Ид. точки : ' || an_mid
   || CHR (10) || 'Загруженно ' || ln_count || ' строк.';
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT importlg_sp;
   raise_application_error (-20001,
                            'DATA_IMPORT_PG.import_alpha: ' || CHR (10) || 'Ошибка загрузки данных (стр. ' || ln_currline || ', столб. ' || ln_currcol || ').'
                            || CHR (10) || SQLERRM (SQLCODE));
 END;
-------------------------------------------------------------------------------------------
END;   -- Package Body DATA_IMPORT_PG
/


