-- Start of DDL Script for Package Body RYDA.DEPORTATION_PG
-- Generated 14.11.2008 08:47:56 from RYDA@sesreg

CREATE OR REPLACE 
PACKAGE BODY deportation_pg IS
 -- пакет работы с каналами экспорта данных
 -- дата создания 26/07/2002 (Сечин А.А.)
 gn_task_code NUMBER DEFAULT 506;
 ------------------------------------------------------------------------------------------------------------------------
    -- Процедура вставки
 PROCEDURE ins_p(
  av_name             VARCHAR2, --Название
  av_note             VARCHAR2, --Примечание
  an_maket            NUMBER, --Ид макета
  an_type             NUMBER, --Тип отсылки
  av_address          VARCHAR2, --Адрес
  an_parent           NUMBER, --Ид основного канала
  ad_from             DATE, --Отсылать с
  ad_till             DATE, --Отсылать по
  an_block            NUMBER, --Блокировка
  an_retries_tout     NUMBER, --Пауза между попытками мин
  an_retries          NUMBER, --Количество попыток
  av_param            VARCHAR2, -- Параметры отсылки
  an_deportation  OUT NUMBER --Ид канала
                            ) IS
  ln_mid   NUMBER;
  lv_mname VARCHAR2(200);
 BEGIN
  SAVEPOINT deportation_ins;
  SELECT points_seq.NEXTVAL
    INTO ln_mid
    FROM DUAL;
  INSERT INTO points
              (mid, parent, cod, ind, name, short_name, ptype, implement_date)
       VALUES (ln_mid, 3, 0, 2, av_name, '', 1, SYSDATE);
  INSERT INTO deportation
              (ndeportation, vname, vnote, nmaket, ntype, vaddress, nparent,
               dfrom, dtill, nblock, nretries_tout, nretries, vparam)
       VALUES (ln_mid, av_name, av_note, DECODE(an_parent, NULL, an_maket, NULL), an_type, av_address, an_parent,
               ad_from, ad_till, an_block, an_retries_tout, an_retries, TRIM(av_param));
  an_deportation := ln_mid;
  SELECT MAX(vname)
    INTO lv_mname
    FROM makets
   WHERE nmaket = an_maket;
  admin_pg.fiscal_p(gn_task_code, 1, 'Добавлен канал отсылки ' || av_name || ' для макета ' || lv_mname);
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT deportation_ins;
   raise_application_error(
    -20001, 'DEPORTATION_pg.ins_p: Ошибка добавления каналами экспорта. ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ------------------------------------------------------------------------------------------------------------------------
    -- Процедура обновления
 PROCEDURE upd_p(
  an_deportation  NUMBER, --Ид канала
  av_name         VARCHAR2, --Название
  av_note         VARCHAR2, --Примечание
  an_maket        NUMBER, --Ид макета
  an_type         NUMBER, --Тип отсылки
  av_address      VARCHAR2, --Адрес
  an_parent       NUMBER, --Ид основного канала
  ad_from         DATE, --Отсылать с
  ad_till         DATE, --Отсылать по
  an_block        NUMBER, --Блокировка
  an_retries_tout NUMBER, --Пауза между попытками мин
  an_retries      NUMBER, --Количество попыток
  av_param        VARCHAR2 -- Параметры отсылки
                          ) IS
  lv_mname   VARCHAR2(200);
  lv_oldname VARCHAR2(200);
 BEGIN
  SAVEPOINT deportation_upd;
  --   SELECT vname INTO lv_mName FROM makets WHERE nmaket = an_maket;
  SELECT vname
    INTO lv_oldname
    FROM deportation
   WHERE ndeportation = an_deportation;
  IF lv_oldname = av_name THEN
   lv_oldname := 'Изменены атрибуты канала отсылки ' || av_name || ' Адрес:' || av_address || ' Для макета ' || lv_mname;
  ELSE
   lv_oldname := 'Изменены атрибуты канала отсылки ' || lv_oldname || ' - ' || av_name || ' Адрес:' || av_address ||
                 ' Для макета ' || lv_mname;
  END IF;
  admin_pg.fiscal_p(gn_task_code, 2, lv_oldname);
  UPDATE points
     SET name = av_name
   WHERE mid = an_deportation;
  UPDATE deportation
     SET vname = av_name,
         vnote = av_note,
         nmaket = DECODE(an_parent, NULL, an_maket, NULL),
         ntype = an_type,
         vaddress = av_address,
         nparent = an_parent,
         dfrom = ad_from,
         dtill = ad_till,
         nblock = an_block,
         nretries_tout = an_retries_tout,
         nretries = an_retries,
         vparam = TRIM(av_param)
   WHERE ndeportation = an_deportation;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT deportation_upd;
   raise_application_error(
    -20001, 'DEPORTATION_pg.upd_p: Ошибка обновления каналами экспорта. ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ------------------------------------------------------------------------------------------------------------------------
   -- Процедура удаления данных
 PROCEDURE del_p(an_deportation NUMBER --Ид канала
                                      ) IS
  lv_oldname VARCHAR2(200);
 BEGIN
  SAVEPOINT deportation_del;
  SELECT vname
    INTO lv_oldname
    FROM deportation
   WHERE ndeportation = an_deportation;
  lv_oldname := 'Удален канал отсылки ' || lv_oldname;
  admin_pg.fiscal_p(gn_task_code, 3, lv_oldname);
  UPDATE deportation
     SET nparent = NULL,
         nblock = 1
   WHERE nparent = an_deportation;
  DELETE FROM points
        WHERE mid = an_deportation;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT deportation_del;
   raise_application_error(
    -20001, 'DEPORTATION_pg.del_p: Ошибка удаления каналами экспорта. ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ------------------------------------------------------------------------------------------------------------------------
     -- Фиксации статуса отправки файла макета (используется в службе отправки макетов)
 PROCEDURE setdeportstatus_p(
  an_maindeportation NUMBER,
  an_deportation     NUMBER,
  ad_date            DATE,
  av_file            VARCHAR2,
  an_state           NUMBER,
  av_error           VARCHAR2) IS
  ln_state NUMBER;
  ld_sys   DATE          DEFAULT SYSDATE;
  ln_send  NUMBER        DEFAULT 0;
  lv_name  VARCHAR2(256);
 BEGIN
  editfeeders_pg.ins_last_save(an_deportation, 'Отсылка не проводилась');
  UPDATE deportfiles
     SET nstate = an_state,
         verror = av_error,
         dsend = DECODE(NVL(an_state, 0), 1, ld_sys, NULL)
   WHERE ndeportation = an_maindeportation AND ddate = ad_date;
  IF NVL(an_state, 0) <> 1 THEN --Если ошибка то пишем ln_state:=1
   ln_state := 1;
  ELSE
   ln_state := 0;
  END IF;
  FOR lc IN (SELECT DECODE(ln_state, 1, 6, ln_state) nstate,
                    DECODE(ln_state, 1, 'Нет связи по каналу. ' || av_error, 'Восстановлена связь по каналу ' || p.name) vstate
               FROM last_save l, points p
              WHERE l.mid = an_deportation AND NVL(l.state_cod, 0) <> ln_state AND l.mid = p.mid(+)) LOOP --Если прошла смена состояния
   admin_pg.journal_p(an_deportation, lc.nstate, lc.vstate);
   ln_send := 1;
  END LOOP;
  IF ln_state = 0 THEN --Пишем что макет отправлен
   SELECT MAX(m.vname)
     INTO lv_name
     FROM deportation d, makets m
    WHERE d.ndeportation = an_maindeportation AND d.nmaket = m.nmaket(+);
   admin_pg.journal_p(
    an_deportation, 0, 'Отправлен макет: ''' || lv_name || ''' за ' || TO_CHAR(ad_date, 'dd.mm.yyyy hh24:mi') ||
                       '. Файл:''' || av_file || '''.');
   ln_send := 1;
  END IF;
  UPDATE last_save
     SET state_date = DECODE(NVL(state_cod, 0), ln_state, state_date, ld_sys),
         state_cod = ln_state,
         state_descr = DECODE(ln_state, 1, SUBSTR(av_error, 1, 150), ' Штатный режим:  '),
         luck = DECODE(ln_state, 0, ld_sys, luck),
         fail = DECODE(ln_state, 1, ld_sys, fail),
         trial = ld_sys
   WHERE mid = an_deportation;
  IF ln_send = 1 THEN --Если что-то писали в журнал
   admin_pg.signal(6);
  END IF;
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(
    -20001, 'DEPORTATION_pg.setdeportstatus_p: Ошибка фиксации состояния отправки файла. ' || CHR(10) || SQLERRM(
                                                                                                          SQLCODE));
 END;
------------------------------------------------------------------------------------------------------------------------
END; -- Package Body
/


-- End of DDL Script for Package Body RYDA.DEPORTATION_PG

-- Start of DDL Script for Package Body RYDA.DIAGRAM_PG
-- Generated 14.11.2008 08:47:56 from RYDA@sesreg

CREATE OR REPLACE 
PACKAGE BODY diagram_pg IS
 ------------------------------------------------------------------------------------------------------------------------
   -- пакет для работы с диаграмами и схемами сети
   -- дата создания 12/06/2004 Сечин А.А.
 ------------------------------------------------------------------------------------------------------------------------
 -- Процедура используется для схемы сети (Modus) Возвращает значение цвет и направление по ид объекта
 /*
declare
an_value NUMBER;
an_arrow NUMBER;
an_color NUMBER;
lv_par VARCHAR2(4000) default 'MID.45199.R';
begin
diagram_pg.get_modusinfo_byid(lv_par,an_value,an_arrow,an_color);
dbms_output.put_line('an_value='||an_value||'; an_arrow='||an_arrow||'; an_color='||an_color);
dbms_output.put_line(lv_par);
end;
*/
 PROCEDURE get_modusinfo_byid(
  av_id        VARCHAR2,
  ad_date      DATE,
  an_value OUT NUMBER,
  an_arrow OUT NUMBER,
  an_color OUT NUMBER,
  an_type  OUT NUMBER) IS
  cv_halfhour   CONSTANT VARCHAR2(32)   := 'HALFHOUR';
  cv_curr_power CONSTANT VARCHAR2(32)   := 'CURR_POWER';
  lv_type                VARCHAR2(32);
  ln_id                  NUMBER;
  lv_prop                VARCHAR2(32);
  lv_objtable            VARCHAR2(32); --Таблица ограничения по объектам
  lv_datatable           VARCHAR2(32); --Таблица с данными
  lv_inverted            VARCHAR2(32); --Признак инверсии
  lv_partly_er           VARCHAR2(32); --Частичное вхождение A+
  lv_partly_ed           VARCHAR2(32); --Частичное вхождение A-
  lv_objsubsel           VARCHAR2(512); --Ограничение по объектам
  lv_datsubsel           VARCHAR2(512); --Ограничение по дате
  lv_what                VARCHAR2(512); --Что тянем
  lv_sql                 VARCHAR2(4000); --Конечный SQL
  lv_obsolescence        VARCHAR2(512); --Устаревание данных
  ln_ret                 NUMBER;
  ln_ret1                NUMBER;
  lv_dat                 VARCHAR2(32); --Устаревание данных
  ld_date                DATE; --Дата показа (NULL когда текущие)
  ln_arrow               NUMBER;
 BEGIN
  --Занулили от греха подальше
  an_value := 0;
  an_arrow := cn_modus_arrow_null;
  an_color := cn_cl_green;
  an_type := 0;
  --Разобрали входную строку
  lv_type := TRIM(UPPER(util_pg.get_param(av_id, 1, '.')));
  ln_id := TRIM(util_pg.get_param(av_id, 2, '.'));
  lv_prop := TRIM(UPPER(util_pg.get_param(av_id, 3, '.')));
  --Сейчас умеем не только тек мощность
  IF SUBSTR(lv_prop, LENGTH(lv_prop), 1) = '_' THEN
   lv_datatable := cv_halfhour;
   ld_date := util_pg.trunchh24_2(NVL(ad_date, SYSDATE - 10 / 1440));
   lv_datsubsel :=
             ' and p.date_time=to_date(''' || TO_CHAR(ld_date, 'dd.mm.yyyy hh24:mi:ss') || ''',''dd.mm.yyyy hh24:mi:ss'') ';
   lv_dat := '_';
   lv_prop := SUBSTR(lv_prop, 1, LENGTH(lv_prop) - 1);
  ELSE
   lv_datatable := cv_curr_power;
  END IF;
  IF lv_datatable = cv_curr_power THEN
   lv_obsolescence := 'decode(sign(' || util_pg.obsolescence_f || '/1440-abs(sysdate-p.date_time)),1,1,NULL)*';
  END IF;
  IF lv_type = 'GID' THEN
   lv_objtable := 'GROUPS';
   lv_inverted := 'G.INVERTED';
   lv_partly_er := '*decode(g.NPARTLY,2,0,1)';
   lv_partly_ed := '*decode(g.NPARTLY,1,0,1)';
   lv_objsubsel :=
     'and G.gid in (select gid from groups connect by ((prior gid=parent) or (prior NROOT2=NROOT2 and prior nroot1>0 and nroot1 is null)) start with gid=' ||
     ln_id || ')';
  ELSIF lv_type = 'MID' THEN
   lv_objtable := 'POINTS';
   lv_inverted := '''N''';
   lv_partly_er := '';
   lv_partly_ed := '';
   IF util_pg.isfolder (ln_id) = 1 THEN
   lv_objsubsel := 'and G.mid in (select mid from points connect by prior mid=parent start with mid=' || ln_id || ')';
   ELSE
    lv_objsubsel := 'and G.mid = ' || ln_id || ' ';
   END IF;
  ELSIF lv_type = 'DATE' THEN --Дата
   an_value := util_pg.trunchh24_2(NVL(ad_date, SYSDATE - 10 / 1440)) - TO_DATE('18991230', 'YYYYMMDD');
   an_type := 1;
   RETURN;
  ELSIF lv_type = 'SYSDATE' THEN --Дата
   an_value := SYSDATE - TO_DATE('18991230', 'YYYYMMDD');
   an_type := 1;
   RETURN;
  END IF;
  --Выясняем что нам нужно
  IF lv_prop = 'ER' THEN
   lv_what := 'sum(' || lv_obsolescence || '(DECODE(' || lv_inverted || ',''y'',nvl(P.ed' || lv_partly_ed || ',0),nvl(P.er' ||
              lv_partly_er || ',0))))';
  ELSIF lv_prop = 'ED' THEN
   lv_what := 'sum(' || lv_obsolescence || '(DECODE(' || lv_inverted || ',''y'',nvl(P.er' || lv_partly_er || ',0),nvl(P.ed' ||
              lv_partly_ed || ',0))))';
  ELSIF lv_prop = 'Q1' THEN
   lv_what := 'sum(' || lv_obsolescence || '(DECODE(' || lv_inverted || ',''y'',nvl(P.q3,0),nvl(P.q1,0))))';
  ELSIF lv_prop = 'Q3' THEN
   lv_what := 'sum(' || lv_obsolescence || '(DECODE(' || lv_inverted || ',''y'',nvl(P.q1,0),nvl(P.q3,0))))';
  ELSIF lv_prop = 'Q2' THEN
   lv_what := 'sum(' || lv_obsolescence || '(DECODE(' || lv_inverted || ',''y'',nvl(P.q4,0),nvl(P.q2,0))))';
  ELSIF lv_prop = 'Q4' THEN
   lv_what := 'sum(' || lv_obsolescence || '(DECODE(' || lv_inverted || ',''y'',nvl(P.q2,0),nvl(P.q4,0))))';
  ELSIF lv_prop = 'Q12' THEN --Свернутые Q1+Q2
   lv_what := 'sum(' || lv_obsolescence || '(DECODE(' || lv_inverted || ',''y'',nvl(P.q3,0),nvl(P.q1,0))))+sum(' ||
              lv_obsolescence || '(DECODE(' || lv_inverted || ',''y'',nvl(P.q4,0),nvl(P.q2,0))))';
  ELSIF lv_prop = 'Q34' THEN --Свернутые Q3+Q4
   lv_what := 'sum(' || lv_obsolescence || '(DECODE(' || lv_inverted || ',''y'',nvl(P.q1,0),nvl(P.q3,0))))+sum(' ||
              lv_obsolescence || '(DECODE(' || lv_inverted || ',''y'',nvl(P.q2,0),nvl(P.q4,0))))';
  ELSIF lv_prop = 'E' THEN --Переток ER-ED
   lv_what := 'sum(' || lv_obsolescence || '(-util_pg.sld(P.mid,nvl(P.er' || lv_partly_er || ',0),nvl(P.ed' ||
              lv_partly_ed || ',0))*DECODE(' || lv_inverted || ',''y'',1,-1)))';
  ELSIF lv_prop = 'Q' THEN --Переток (Q1-Q3)+(Q2-Q4)
   lv_what := 'sum(' || lv_obsolescence || '(-util_pg.sld(P.mid,nvl(P.q1,0),nvl(P.q3,0))*DECODE(' || lv_inverted ||
              ',''y'',1,-1)))+sum(' || lv_obsolescence || '(-util_pg.sld(P.mid,nvl(P.q2,0),nvl(P.q4,0))*DECODE(' ||
              lv_inverted || ',''y'',1,-1)))';
  ELSIF lv_prop IN ('PROC', 'BALANCEP') THEN --Небаланс в%
   ln_ret := get_modusinfo_byid(lv_type || '.' || ln_id || '.' || 'ER' || lv_dat);
   ln_ret1 := get_modusinfo_byid(lv_type || '.' || ln_id || '.' || 'ED' || lv_dat);
   IF GREATEST(ln_ret, ln_ret1) <> 0 THEN
    ln_ret := 100 * (ln_ret - ln_ret1) / GREATEST(ln_ret, ln_ret1);
   ELSE
    ln_ret := GREATEST(ln_ret, ln_ret1);
   END IF;
  ELSIF  lv_type = 'GID' AND lv_prop = 'ADBALANCE' THEN --Допустимый небаланс
   an_value := ROUND(util_pg.get_ad_balance(ln_id, ld_date - 1 / 48, ld_date, NULL) / 1000, 3);
   RETURN;
  ELSIF  lv_type = 'GID' AND lv_prop = 'ADBALANCEP' THEN --Допустимый небаланс в%
   an_value := util_pg.get_ad_balance(ln_id, ld_date - 1 / 48, ld_date, 1);
   RETURN;
  ELSIF  lv_type = 'GID' AND lv_prop = 'BALANCEDIF' THEN --Разность факт небаланса и допустим небаланса
   ln_ret := get_modusinfo_byid(lv_type || '.' || ln_id || '.' || 'E' || lv_dat);
   ln_ret1 := get_modusinfo_byid(lv_type || '.' || ln_id || '.' || 'ADBALANCE' || lv_dat);
   ln_ret := SIGN(ln_ret) * GREATEST(ABS(ln_ret) - ln_ret1, 0);
  ELSIF  lv_type = 'GID' AND lv_prop = 'BALANCEDIFP' THEN --Разность факт небаланса и допустим небаланса в %
   ln_ret := get_modusinfo_byid(lv_type || '.' || ln_id || '.' || 'BALANCEP' || lv_dat);
   ln_ret1 := get_modusinfo_byid(lv_type || '.' || ln_id || '.' || 'ADBALANCEP' || lv_dat);
   ln_ret := SIGN(ln_ret) * GREATEST(ABS(ln_ret) - ln_ret1, 0);
  END IF;
  IF  lv_datatable IS NOT NULL AND lv_objtable IS NOT NULL AND lv_what IS NOT NULL THEN
   lv_sql := 'select ' || lv_what || ' from ' || lv_datatable || ' P,' || lv_objtable || ' G where p.mid=g.mid ' || ' ' ||
             lv_datsubsel || ' ' || lv_objsubsel;
   EXECUTE IMMEDIATE lv_sql
    INTO ln_ret;
   ln_ret := ROUND(ln_ret / 1000, 3);
  END IF;
  ln_ret := NVL(ln_ret, 0);
  IF ln_ret < 0 THEN
   ln_ret := -ln_ret;
   an_arrow := NVL(ln_arrow, cn_modus_arrow_down);
   an_color := cn_cl_green;
  ELSIF ln_ret > 0 THEN
   an_arrow := NVL(ln_arrow, cn_modus_arrow_up);
   an_color := cn_cl_red;
  END IF;
  an_value := ln_ret;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'diagram_pg.get_modusinfo_byid: ИД='''||av_id||''' ' || CHR(10) || SQLERRM);
 END;
 ------------------------------------------------------------------------------------------------------------------------
   -- Процедура используется для схемы сети (Modus) Возвращает значение цвет и направление по ид объекта
 FUNCTION get_modusinfo_byid(av_id VARCHAR2)
  RETURN NUMBER IS
  ln_value NUMBER;
  ln_arrow NUMBER;
  ln_color NUMBER;
  ln_type  NUMBER;
 BEGIN
  get_modusinfo_byid(av_id, ln_value, ln_arrow, ln_color, ln_type);
  RETURN ln_value;
 END;
 ------------------------------------------------------------------------------------------------------------------------
    -- Используется для автоопределения даты (последняя получасовка)
 PROCEDURE get_modusinfo_byid(
  av_id        VARCHAR2,
  an_value OUT NUMBER,
  an_arrow OUT NUMBER,
  an_color OUT NUMBER,
  an_type  OUT NUMBER) IS
  ln_value NUMBER;
  ln_arrow NUMBER;
  ln_color NUMBER;
  ln_type  NUMBER;
 BEGIN
  get_modusinfo_byid(av_id, NULL, ln_value, ln_arrow, ln_color, ln_type);
  an_value := ln_value;
  an_arrow := ln_arrow;
  an_color := ln_color;
  an_type := ln_type;
 END;
