                                                                                            an_current1 NUMBER,   --Напряжение перв
                                                                                                               an_current2 NUMBER,   --Напряжение вторич
                                                                                                                                  an_kc NUMBER,   --Коэфф
 an_point NUMBER,   --Ид точки АСРПП
                 an_power2 NUMBER,   --Мощность вторич кВ
                                  an_mid OUT NUMBER   --Ид точки
 ) IS
  ln_mid   NUMBER;
