CREATE OR REPLACE 
PACKAGE BODY editforms_pg IS
 -- пакет работы с группами
 -- дата создания 29/10/2001 (Сечин А.А.)
 gn_task_code   NUMBER DEFAULT 51;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура вставки
 PROCEDURE ins_p (an_parent NUMBER,   --
                                   an_monitor NUMBER,   --
                                                     an_codetemplate NUMBER,   --
                                                                            av_nameform VARCHAR2,   --
                                                                                                 av_commentform VARCHAR2,   --
                                                                                                                         av_enablecontrols VARCHAR2,   --
 an_stepprofile NUMBER,   --
                       av_namealert VARCHAR2,   --
                                             av_procname VARCHAR2,   --
                                                                  at_gid common_pg.tt_number,   --
                                                                                             an_mid NUMBER, an_fid OUT NUMBER   --
 ) IS
  ln_fid   NUMBER;
 BEGIN
  SAVEPOINT editforms_ins;

  SELECT forms_seq.NEXTVAL
    INTO ln_fid
    FROM DUAL;

  an_fid := ln_fid;

  INSERT INTO forms
              (fid, PARENT, monitor, codetemplate, nameform, commentform, enablecontrols, stepprofile, namealert, vprocname, mid
              )
       VALUES (ln_fid, an_parent, an_monitor, an_codetemplate, av_nameform, av_commentform, av_enablecontrols, an_stepprofile, av_namealert, av_procname, an_mid
              );

  IF at_gid.COUNT > 0 AND at_gid (1) <> 0 THEN
   FOR i IN 1 .. at_gid.COUNT LOOP
    INSERT INTO form_group
                (fid, gid
                )
         VALUES (ln_fid, at_gid (i)
                );
   END LOOP;
  END IF;

  admin_pg.fiscal_p (gn_task_code, 1, 'Добавлена группа форм (форма) ' || util_pg.node_path_f (an_fid, 'forms', 'fid', 'parent', 'nameform'));
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT editforms_ins;
   raise_application_error (-20001, 'editforms_pg.ins_p: Ошибка вставки формы монитора. ' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура обновления данных
 PROCEDURE upd_p (an_fid NUMBER,   --
                                an_parent NUMBER,   --
                                                 an_monitor NUMBER,   --
                                                                   an_codetemplate NUMBER,   --
                                                                                          av_nameform VARCHAR2,   --
                                                                                                               av_commentform VARCHAR2,   --
                                                                                                                                       av_enablecontrols VARCHAR2,   --
 an_stepprofile NUMBER,   --
                       av_namealert VARCHAR2,   --
                                             av_procname VARCHAR2,   --
                                                                  at_gid common_pg.tt_number, an_mid NUMBER   --
 ) IS
 BEGIN
  SAVEPOINT editforms_upd;

  UPDATE forms
     SET PARENT = an_parent,
         monitor = an_monitor,
         codetemplate = an_codetemplate,
         nameform = av_nameform,
         commentform = av_commentform,
         enablecontrols = av_enablecontrols,
         stepprofile = an_stepprofile,
         namealert = av_namealert,
         vprocname = av_procname,
         mid = an_mid
   WHERE fid = an_fid;

  DELETE FROM form_group
        WHERE fid = an_fid;

  IF at_gid.COUNT > 0 AND at_gid (1) <> 0 THEN
   FOR i IN 1 .. at_gid.COUNT LOOP
    INSERT INTO form_group
                (fid, gid
                )
         VALUES (an_fid, at_gid (i)
                );
   END LOOP;
  END IF;

  admin_pg.fiscal_p (gn_task_code, 2, 'Изменены атрибуты группы форм (формы) ' || util_pg.node_path_f (an_fid, 'forms', 'fid', 'parent', 'nameform'));
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT editforms_upd;
   raise_application_error (-20001, 'editforms_pg.upd_p: Ошибка обновления формы монитора. ' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура удаления данных
 PROCEDURE del_p (an_fid NUMBER   --
                               ) IS
 BEGIN
  admin_pg.fiscal_p (gn_task_code, 3, 'Удалена группа форм (форма) ' || util_pg.node_path_f (an_fid, 'forms', 'fid', 'parent', 'nameform'));

  DELETE FROM forms
        WHERE fid = an_fid;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20001, 'editforms_pg.del_p: Ошибка удаления формы монитора. ' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура копирования форм из одной схемы в другую
  -- Add by KSS (12.08.2004)
 PROCEDURE copyschema_p (an_srcsid NUMBER,   -- ид исходной схемы
                                          an_dstsid NUMBER,   -- ид схемы назначения
                                                           ab_groupcopy NUMBER,   -- признак копирования доступных групп
 ab_filecopy NUMBER   -- признак копирования присоединенных файлов (ограничение на размер файла < 32кБ)
 ) IS
  /*  CURSOR lc_tree IS
     SELECT     x.*
           FROM (SELECT   a.fid, a.parent, a.monitor, a.codetemplate, a.nameform, a.commentform, a.enablecontrols,
                          a.stepprofile, a.namealert, a.vprocname, a.mid
                     FROM forms a
                    WHERE a.monitor = an_srcsid
                 ORDER BY a.parent, a.nameform) x
     CONNECT BY PRIOR x.fid = x.parent
     START WITH x.parent IS NULL;*/
  CURSOR lc_tree IS
   SELECT     a.fid, a.PARENT, a.monitor, a.codetemplate, a.nameform, a.commentform, a.enablecontrols, a.stepprofile, a.namealert, a.vprocname, a.mid
         FROM forms a
   CONNECT BY PRIOR a.fid = a.PARENT AND a.monitor = an_srcsid
   START WITH a.PARENT IS NULL AND a.monitor = an_srcsid;

  CURSOR lc_file (cn_fid NUMBER) IS
   SELECT *
     FROM forms_ex
    WHERE fid = cn_fid;

  lt_parentfids   common_pg.tt_number;
  ln_fid          NUMBER;
  ln_parent       NUMBER;
  lr_filebody     LONG RAW;
  lv_name         VARCHAR2 (2000);
 BEGIN
  SAVEPOINT copy_schema;

  DELETE FROM forms
        WHERE monitor = an_dstsid;

  FOR cr IN lc_tree LOOP
   SELECT forms_seq.NEXTVAL
     INTO ln_fid
     FROM DUAL;

   lt_parentfids (cr.fid) := ln_fid;

   IF cr.PARENT IS NULL THEN
    ln_parent := NULL;
   ELSE
    ln_parent := lt_parentfids (cr.PARENT);
   END IF;

   INSERT INTO forms
               (fid, PARENT, monitor, codetemplate, nameform, commentform, enablecontrols, stepprofile, namealert, vprocname, mid
               )
        VALUES (ln_fid, ln_parent, an_dstsid, cr.codetemplate, cr.nameform, cr.commentform, cr.enablecontrols, cr.stepprofile, cr.namealert, cr.vprocname, cr.mid
               );

   IF ab_groupcopy = 1 THEN
    INSERT INTO form_group
     (SELECT ln_fid, gid
        FROM form_group
       WHERE fid = cr.fid);
   END IF;

   IF ab_filecopy = 1 THEN
    -- Копирование привязанных файлов (нельзя преобразовать BLOB в LONG RAW)
    BEGIN
     SELECT MAX (f.nameform)
       INTO lv_name
       FROM forms f, forms_ex e
      WHERE e.fid = cr.fid AND e.fid = f.fid;

     IF (lv_name IS NOT NULL) THEN
      SELECT filebody
        INTO lr_filebody
        FROM forms_ex
       WHERE fid = cr.fid;

      INSERT INTO forms_ex
                  (fid, fname, fdatechange, fsize, filebody)
       SELECT ln_fid, fname, fdatechange, fsize, lr_filebody
         FROM forms_ex
        WHERE fid = cr.fid;
     END IF;
    EXCEPTION
     WHEN OTHERS THEN
      raise_application_error (-20001,
                               'Ошибка копирования привязанного файла к форме "' || lv_name || '".' || CHR (10)
                               || '(Размер файла не может превышать 32кБ(32767 байтов). Иначе перенос файла следует производить вручную.)' || CHR (10)
                               || SQLERRM (SQLCODE));
    END;
   END IF;
  END LOOP;

  admin_pg.fiscal_p (gn_task_code, 1, 'Произведено копирование форм из схемы  в схему');
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT copy_schema;
   raise_application_error (-20001, 'editforms_pg.copyschema_p: Ошибка при копировании форм в схему. ' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION get_formname (an_fid NUMBER)
  RETURN VARCHAR2 IS
  lv_ret   VARCHAR2 (256);
 BEGIN
  SELECT MAX (nameform)
    INTO lv_ret
    FROM forms
   WHERE fid = an_fid;

  RETURN lv_ret;
 END;
------------------------------------------------------------------------------------------------------------------------
END;   -- Package Bod
/


