PACKAGE BODY editgroups_pg IS
 -- пакет работы с группами
 -- дата создания 29/10/2001 (Сечин А.А.)
 gn_task_code NUMBER DEFAULT 10;
 ------------------------------------------------------------------------------------------------------------------------
   -- Процедура вставки (общая)
 PROCEDURE ins_p_all(
  an_askue                 NUMBER, --1-изменения из АСКУЭ, иначе из АСРПП
  an_parent                NUMBER, --Родитель
  av_name                  VARCHAR2, --Название
  av_short_name            VARCHAR2, --Краткое название
  an_mid                   NUMBER, --Ид точки
  an_limit_id              NUMBER, --Ид лимита
  an_inverted              NUMBER, --Признак инвертирования
  an_group_total           NUMBER, --Признак суммирования по группе
  an_root1                 NUMBER, --Ид группы прома
  an_root2                 NUMBER, --Ид группы прома
  an_emergencyreserve      NUMBER, --Аварийная бронь
  an_technologyreserve     NUMBER, --Технологическая бронь
  av_param                 VARCHAR2, --Доп параметр
  an_partly                NUMBER, --Признак частичного вхожд
  an_fromperiod            NUMBER, --Период с
  an_tillperiod            NUMBER, --Период по
  an_gid               OUT NUMBER --Ид группы
                                 ) IS
  ln_gid NUMBER;
 BEGIN
  SELECT groups_seq.NEXTVAL
    INTO ln_gid
    FROM DUAL;
  an_gid := ln_gid;
  INSERT INTO groups
              (gid, parent, name, short_name, mid,
               inverted,
               group_total, nroot1,
               nroot2, nemergencyreserve, ntechnologyreserve, vparam, npartly, nfromperiod,
               ntillperiod)
       VALUES (ln_gid, an_parent, av_name, av_short_name, an_mid,
               DECODE(an_mid, NULL, 'n', DECODE(an_inverted, 1, 'y', 'n')),
               DECODE(ABS(SIGN(an_mid)), 1, 'n', DECODE(an_askue, 1, DECODE(an_group_total, 1, 'y', 'n'), 'y')), an_root1,
               an_root2, an_emergencyreserve, an_technologyreserve, av_param, an_partly, NVL(an_fromperiod, 190001),
               an_tillperiod);
 /*  IF an_parent IS NULL THEN
    INSERT INTO form_group
                (gid, fid)
     (SELECT ln_gid, fid
        FROM forms
       WHERE codetemplate <> 0);
   END IF;*/
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'editgroups_pg.ins_p: Ошибка вставки группы учета. ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ------------------------------------------------------------------------------------------------------------------------
   -- Процедура обновления данных (общая)
 PROCEDURE upd_p_all(
  an_askue             NUMBER, --1-изменения из АСКУЭ, иначе из АСРПП
  an_gid               NUMBER, --Ид группы
  an_parent            NUMBER, --Родитель
  av_name              VARCHAR2, --Название
  av_short_name        VARCHAR2, --Краткое название
  an_limit_id          NUMBER, --Ид лимита
  an_inverted          NUMBER, --Признак инвертирования
  an_group_total       NUMBER, --Признак суммирования по группе
  an_emergencyreserve  NUMBER, --Аварийная бронь
  an_technologyreserve NUMBER, --Технологическая бронь
  av_param             VARCHAR2, --Доп параметр
  an_partly            NUMBER, --частичное вхождение
  an_fromperiod        NUMBER, --Период с
  an_tillperiod        NUMBER --Период по
                             ) IS
 BEGIN
  IF  util_pg.get_customer_id = 1 AND an_askue = 1 THEN --ХЭС
   UPDATE groups
      SET group_total =
                     DECODE(ABS(SIGN(mid)), 1, 'n', DECODE(an_askue, 1, DECODE(an_group_total, 1, 'y', 'n'),
                                                                                                           group_total)),
          vparam = av_param
    WHERE gid = an_gid;
  ELSE
   UPDATE groups
      SET parent = an_parent,
          name = av_name,
          short_name = av_short_name,
          inverted = DECODE(mid, NULL, 'n', DECODE(an_inverted, 1, 'y', 'n')),
          group_total =
                     DECODE(ABS(SIGN(mid)), 1, 'n', DECODE(an_askue, 1, DECODE(an_group_total, 1, 'y', 'n'),
                                                                                                           group_total)),
          nemergencyreserve = DECODE(an_askue, 1, an_emergencyreserve, nemergencyreserve),
          ntechnologyreserve = DECODE(an_askue, 1, an_technologyreserve, ntechnologyreserve),
          vparam = DECODE(an_askue, 1, av_param, vparam),
          npartly = an_partly,
          nfromperiod = NVL(an_fromperiod, 190001),
          ntillperiod = an_tillperiod
    WHERE gid = an_gid;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'editgroups_pg.upd_p: Ошибка обновления группы учета. ' || CHR(10) || SQLERRM(
                                                                                                          SQLCODE));
 END;
 ------------------------------------------------------------------------------------------------------------------------
   -- Процедура вставки
 PROCEDURE ins_p(
  an_parent                NUMBER, --Ро7дитель
  av_name                  VARCHAR2, --Название
  av_short_name            VARCHAR2, --Краткое название
  an_mid                   NUMBER, --Ид точки
  an_limit_id              NUMBER, --Ид лимита
  an_inverted              NUMBER, --Признак инвертирования
  an_group_total           NUMBER, --Признак суммирования по группе
  an_emergencyreserve      NUMBER, --Аварийная бронь
  an_technologyreserve     NUMBER, --Технологическая бронь
  av_param                 VARCHAR2, --Доп параметр
  an_partly                NUMBER, --Признак частичного вхожд
  an_fromperiod            NUMBER, --Период с
  an_tillperiod            NUMBER, --Период по
  an_gid               OUT NUMBER --Ид группы
                                 ) IS
 BEGIN
  SAVEPOINT editgroups_ins;
  ins_p_all(
   1, an_parent, av_name, av_short_name, an_mid, an_limit_id, an_inverted, an_group_total, NULL, NULL,
   an_emergencyreserve, an_technologyreserve, av_param, an_partly, an_fromperiod, an_tillperiod, an_gid);
  IF an_mid IS NULL THEN
   admin_pg.fiscal_p(
    gn_task_code, 1, 'Добавлена группа учета ' || util_pg.node_path_f(an_gid, 'groups', 'gid', 'parent'));
  ELSE
   admin_pg.fiscal_p(
    gn_task_code, 1, 'Добавлена точка в группу ' || util_pg.node_path_f(an_gid, 'groups', 'gid', 'parent') || ' C ' ||
                     util_pg.node_path_f(an_mid, 'points', 'mid', 'parent'));
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT editgroups_ins;
   RAISE;
 END;
 ------------------------------------------------------------------------------------------------------------------------
   -- Процедура вставки
 PROCEDURE ins_p(
  an_parent                NUMBER, --Родитель
  av_name                  VARCHAR2, --Название
  av_short_name            VARCHAR2, --Краткое название
