   NULL, NULL, an_fromperiod, an_tillperiod);
 END;
 ------------------------------------------------------------------------------------------------------------------------
  -- Процедура удаления данных
 PROCEDURE del_p(an_gid NUMBER --Ид группы
                              ) IS
 BEGIN
  admin_pg.fiscal_p(
   gn_task_code, 3, 'Удалена группа учета (точка в группе) ' || util_pg.node_path_f(an_gid, 'groups', 'gid', 'parent'));
  DELETE FROM groups
        WHERE gid = an_gid;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'editgroups_pg.del_p: Ошибка удаления группы учета. ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ------------------------------------------------------------------------------------------------------------------------
    -- Процедура изменения лимитов по группе
 PROCEDURE updlimit_p(
  an_gid       NUMBER, --Ид группы
  at_start     common_pg.tt_varchar2, --Дата ввода в действие
  at_limitcons common_pg.tt_number, --Потребление
  at_limitcapm common_pg.tt_number, --Нагрузка утро
  at_limitcape common_pg.tt_number --Нагрузка вечер
                                  ) IS
  lt_tmp common_pg.tt_varchar2;
 BEGIN
  FOR i IN 1 .. at_start.COUNT LOOP
   lt_tmp(i) := NULL;
  END LOOP;
  updlimit_p(an_gid, at_start, at_limitcons, at_limitcapm, at_limitcape, lt_tmp, lt_tmp, lt_tmp, lt_tmp);
 END;
 ------------------------------------------------------------------------------------------------------------------------
      -- Процедура изменения лимитов по группе
 PROCEDURE updlimit_p(
  an_gid           NUMBER, --Ид группы
  at_start         common_pg.tt_varchar2, --Дата ввода в действие
  at_limitcons     common_pg.tt_number, --Потребление
  at_limitcapm     common_pg.tt_number, --Нагрузка утро
  at_limitcape     common_pg.tt_number, --Нагрузка вечер
  at_morning_start common_pg.tt_varchar2, --Утро нач
  at_morning_end   common_pg.tt_varchar2, --Утро кон
  at_evening_start common_pg.tt_varchar2, --Вечер нач
  at_evening_end   common_pg.tt_varchar2 --Вечер кон
                                        ) IS
 BEGIN
  SAVEPOINT editgroups_updlimit;
  DELETE FROM grouplimit
        WHERE gid = an_gid;
  IF  at_start.COUNT > 0 AND LENGTH(at_start(1)) > 0 THEN
   FOR i IN 1 .. at_start.COUNT LOOP
    INSERT INTO grouplimit
                (gid, dstart, nlimitcons, nlimitcapm, nlimitcape,
                 morning_start,
                 morning_end,
                 evening_start,
                 evening_end)
         VALUES (an_gid, TO_DATE(at_start(i), 'dd.mm.yyyy'), at_limitcons(i), at_limitcapm(i), at_limitcape(i),
                 TO_DATE(at_morning_start(i), 'dd.mm.yyyy hh24:mi:ss'),
                 TO_DATE(at_morning_end(i), 'dd.mm.yyyy hh24:mi:ss'),
                 TO_DATE(at_evening_start(i), 'dd.mm.yyyy hh24:mi:ss'),
                 TO_DATE(at_evening_end(i), 'dd.mm.yyyy hh24:mi:ss'));
   END LOOP;
  END IF;
  admin_pg.fiscal_p(
   gn_task_code, 2, 'Изменены лимиты для группы ' || util_pg.node_path_f(an_gid, 'groups', 'gid', 'parent'));
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT editgroups_updlimit;
   RAISE;
 END;
------------------------------------------------------------------------------------------------------------------------
END; -- Package Body
/


