CREATE OR REPLACE 
PACKAGE BODY evid_terme_pg
IS
--- пакет для работы с терминалом показаний
-- 10.07.2008 Виленская Н.Б.

--------------------------------------------------------------------
PROCEDURE get_MetersTreeRoot(acur_t OUT common_pg.tcur)is -- первичное дерево(SelectPoint->OraQuery1)
BEGIN
  OPEN acur_t FOR
   select 1 HaveChild, p.mid, decode(p.ind,3,1,4,1,0) type, p.name,f.kc,nvl(f.ninverted,0)ninverted
                  FROM points p,feeders f
                  WHERE p.cod=0 and p.mid=(select max(mid) from enterprise)
       and exists (select * from points where parent=p.mid and cod=0) and p.mid=f.mid(+)
                  union all
                  select 0 HaveChild, p.mid, decode(p.ind,3,1,4,1,0) type, p.name ,f.kc,nvl(f.ninverted,0)ninverted
                  FROM points p ,feeders f
                  WHERE p.cod=0 and p.mid=(select max(mid) from enterprise)
          and not exists (select * from points where parent=p.mid and cod=0) and p.mid=f.mid(+)
                  order by 3,4;
end;
-----------------------------------------------------------------------------
 PROCEDURE get_MetersTreeChilds(an_parent NUMBER,--ид.родителя
                                acur_t OUT common_pg.tcur) is -- при раскрытии дерева(SelectPoint->OraQuery3)

 BEGIN

OPEN acur_t FOR
 select 1 HaveChild,p. mid, decode(p.ind,3,1,4,1,0) type,p.name,f.kc, nvl(f.ninverted,0)ninverted
                  FROM points p,feeders f
                  WHERE p.cod=0 and p.parent=an_parent
                        and exists (select * from points where parent=p.mid and cod=0)  and p.mid=f.mid(+)
                  union all
                  select 0 HaveChild, p.mid, decode(p.ind,3,1,4,1,0) type, p.name,f.kc, nvl(f.ninverted,0)ninverted
                  FROM points p,feeders f
                  WHERE p.cod=0 and p.parent=an_parent
                        and not exists (select * from points where parent=p.mid and cod=0) and p.mid=f.mid(+)
                  order by 3,4;

  
end;
 -----------------------------------------------------------------------
  PROCEDURE get_MidMeters(an_mid NUMBER,--ид.точки
                           acur_t OUT common_pg.tcur) is -- при поиске ветки в дереве(SelectPoint->OraQuery2)
 
 BEGIN
 OPEN acur_t FOR
 select mid from points connect by prior parent=mid and cod=0 start with mid=an_mid and cod=0;
  end;
 -----------------------------------------------------------------------
 PROCEDURE get_PointsList(acur_t OUT common_pg.tcur) IS -- список счетчиков(TMainWin1702->OQryPointsList)
 BEGIN
  OPEN acur_t FOR
   select p1.Name, p2.Name, p2.mid,f.kc, nvl(f.ninverted,0)ninverted
   from points p1, points p2,feeders f
   where f.mid=p2.mid(+) and p2.parent=p1.mid(+)
   order by p1.Name, p2.Name;
 END;
--------------------------------------------------------------------------------------
 PROCEDURE get_PassPoints(acur_t OUT common_pg.tcur) IS -- список счетчиков(TMainWin1702->OQryPassPoints)
 BEGIN
  OPEN acur_t FOR
   select
  p1.Name, p2.Name, p1.mid, p2.mid
  from
    points p1, points p2, feeders f
  where
    f.mid=p2.mid(+) and p2.parent = p1.mid(+)
  order by p1.Name, p2.Name;
 END;
 --------------------------------------------------------------------------
  PROCEDURE get_PassGroups(acur_t OUT common_pg.tcur) IS -- список групп счетчиков(TMainWin1702->OQryPassGroups)
 BEGIN
  OPEN acur_t FOR
  select
  distinct
    p1.Name, p1.mid
  from
    points p1, points p2, feeders f
  where
   f.mid=p2.mid(+) and p2.parent = p1.mid(+)
  order by p1.Name;
 END;
 -----------------------------------------------------------------------------------------------------------
  PROCEDURE get_CurrPower(an_WilBiAdd NUMBER,--если значение = 1 Q1 = Q1 иначе Q1=Q1+Q2 тоже с Q3
                           acur_t OUT common_pg.tcur) IS -- на момент врремени текущие(TMainWin1702->OQryCurrPower)
 BEGIN
  OPEN acur_t FOR
   
  select
  p1.Name, p2.Name, c.date_time, c.mid, c.er,
  decode(an_WilBiAdd, 1, c.q1,util_pg.sumn(c.q1,c.q2)) q1,
  c.ed,
  decode(an_WilBiAdd, 1, c.q3, util_pg.sumn(c.q3,c.q4)) q3,
  c.q2, c.q4, c.erm, c.q1m, c.edm, c.q3m, c.q2m, c.q4m,
  c.freq, c.cosf, c.volt, c.volt2, c.volt3, c.currento, c.curr2, c.curr3
  from
    curr_power c, points p1, points p2
  where
  c.mid=p2.mid(+) and p2.parent=p1.mid(+)
  order by p1.Name, p2.Name;
 
 
  
 END;
 --------------------------------------------------------------------
  PROCEDURE get_Profile(ad_prDT DATE,--временная точка среза на осн верхн гран
                        an_WilBiAdd NUMBER,--если значение = 1 Q1 = Q1 иначе Q1=Q1+Q2 тоже с Q3
                        av_Table NUMBER,--таблица для минутных -1 "minutemeas"("profileevid"), для ГН - 2  "hourmeas"("halfhourevid")
                        acur_t OUT common_pg.tcur) IS
   -- на момент врремени минутные или ГН(TMainWin1702->OQryProfile,OQryHH)
   lv_tablename VARCHAR2(100);
   lv_sql VARCHAR2(4000);
 BEGIN
 if(av_Table=1) then
     lv_tablename:=' profile ';--название таблицы
 else lv_tablename:=' halfhourold ';--название таблицы
 end if;
 
  
   -- ad_prDT;//временная точка среза на осн верхн гран
  -- an_WilBiAdd; //если значение = 1 Q1 = Q1 иначе Q1=Q1+Q2 тоже с Q3
  -- av_Table;//таблица для минутных - "minutemeas"("profileevid"), для ГН - "hourmeas"("halfhourevid")
  -- Name - Группа учёта (подстанция)
  -- Name_1 - Точка учёта
  -- date_time - Дата, время
  -- mid -- ид.точки
  -- er - Расход A+ [кВтч]
  -- q1 - Расход R+ [кВАрч]
  -- ed - Расход A- [кВтч]
  -- q3 - Расход R- [кВАрч]
  -- q2 - Расход Q2 [кВАрч]
  -- q4 - Расход Q4 [кВАрч]
  -- erm - Показания A+ [кВтч]
  -- q1m - Показания R+ [кВАрч]
  -- edm - Показания A- [кВтч]
  -- q3m - Показания R- [кВАрч]
  -- q2m - Показания Q2M [кВАрч]
  -- q4m - Показания  Q4M [кВАрч]
  -- kc - К. трансф.
lv_sql:= 'select  p1.Name, p2.Name, h.mid,
  h.er, h.ed,
  decode(:par2, 1, h.q1, util_pg.sumn(h.q1, h.q2)) q1,
  decode(:par2, 1, h.q3, util_pg.sumn(h.q3, h.q4)) q3,
  h.q2, h.q4, h.erm, h.edm,
  decode(:par2, 1, h.q1m, util_pg.sumn(h.q1m, h.q2m)) q1m,
  decode(:par2, 1, h.q3m, util_pg.sumn(h.q3m, h.q4m)) q3m,
  h.q2m, h.q4m,
  f.kc
  from
   '|| lv_tablename|| ' h , points p1, points p2, feeders f
  where
    f.mid = h.mid and h.date_time = :par1 and
    f.mid=p2.mid(+) and p2.parent=p1.mid(+)
  order by p1.Name, p2.Name';
 OPEN acur_t FOR lv_sql
  using an_WilBiAdd,an_WilBiAdd,an_WilBiAdd,an_WilBiAdd,ad_prDT;

 END;
  ------------------------------------------------------------------------
  PROCEDURE get_BillorMonth(ad_prLBDT DATE,-- floor( prDT )время начало
                            ad_prHBDT DATE,--prLBDT+1 время конец
                            an_ChBZone NUMBER,-- тарифные зоны
                            an_WilBiAdd NUMBER,-- если значение = 1 Q1 = Q1 иначе Q1=Q1+Q2 тоже с Q3
                            av_table NUMBER,-- таблица 3- суточные "bill" или 4-месячные "month"
                            acur_t OUT common_pg.tcur) IS
            -- на момент врремени суточные или месячные(TMainWin1702->OQryBill,OQryMonth)
   lv_dattime VARCHAR2(200);
   lv_tablename VARCHAR2(2000);--название таблицы
   lv_sql VARCHAR2(10000);
BEGIN
 if(av_table=3) then
   lv_tablename:=' (select b.date_time,p1.Name p1Name, p2.Name p2Name, b.mid,b.er, b.q1, b.ed, b.q3, b.q2, b.q4, b.erm, b.q1m, b.edm, b.q3m, b.q2m, b.q4m,
b.aer, b.aq1, b.aed, b.aq3, b.aq2, b.aq4, b.aerm, b.aq1m, b.aedm, b.aq3m, b.aq2m, b.aq4m,b.ber, b.bq1, b.bed, b.bq3, b.bq2, b.bq4, b.berm, b.bq1m, b.bedm, b.bq3m, b.bq2m, b.bq4m
,b.cer, b.cq1, b.ced, b.cq3, b.cq2, b.cq4, b.cerm, b.cq1m, b.cedm, b.cq3m, b.cq2m, b.cq4m,b.der, b.dq1, b.ded, b.dq3, b.dq2, b.dq4, b.derm, b.dq1m, b.dedm, b.dq3m, b.dq2m, b.dq4m
,f.kc, b.er_mtrsn,b.denter from  billorg b, points p1, points p2, feeders f where f.mid=p2.mid(+) and p2.parent=p1.mid(+) and f.mid=b.mid) t ';--название таблицы
   lv_dattime:=' to_char( date_time, '' hh24:mi '')  ';--заглушка вместо sysdate д.б.столбец таблицы ddatetime
   
 else
   lv_tablename:=' (select b.date_time,p1.Name p1Name, p2.Name p2Name, b.mid,b.er, b.q1, b.ed, b.q3, b.q2, b.q4, b.erm, b.q1m, b.edm, b.q3m, b.q2m, b.q4m,b.aer, b.aq1, b.aed, b.aq3, 
b.aq2, b.aq4, b.aerm, b.aq1m, b.aedm, b.aq3m, b.aq2m, b.aq4m,b.ber, b.bq1, b.bed, b.bq3, b.bq2, b.bq4, b.berm, b.bq1m, b.bedm, b.bq3m, b.bq2m, b.bq4m,
b.cer, b.cq1, b.ced, b.cq3, b.cq2, b.cq4, b.cerm, b.cq1m, b.cedm, b.cq3m, b.cq2m, b.cq4m,b.der, b.dq1, b.ded, b.dq3, b.dq2, b.dq4, b.derm, b.dq1m, b.dedm, b.dq3m, b.dq2m, b.dq4m,
f.kc, b.er_mtrsn, b.denter from  MONTHSORG b, points p1, points p2, feeders f where f.mid=p2.mid(+) and p2.parent=p1.mid(+) and f.mid=b.mid) t ';
   lv_dattime:= ' to_char( date_time, '' dd hh24:mi '') ';
 end if;
 
lv_sql:='select p1Name p11Name, p2Name p21Name, p1Name, p2Name, mid , ''S'', 1, er,
 decode(:par4, 1, q1, util_pg.sumn(q1, q2)) q1,ed, decode(:par4, 1, q3, util_pg.sumn(q3, q4)) q3,
 q2, q4, erm, decode(:par4, 1, q1m, util_pg.sumn(q1m, q2m)) q1m,  edm,  decode(:par4, 1, q3m, util_pg.sumn(q3m, q4m)) q3m, 
 q2m, q4m,TO_CHAR(kc, ''99999990.000'') kc ,er_mtrsn ,'||lv_dattime|| ' date_time_str from '||lv_tablename ||
 ' where t.date_time >= :par1 and t.date_time < :par2 union all
 select '''', '''', p1Name, p2Name, mid, ''A'', 2,aer,decode(:par4, 1, aq1, util_pg.sumn(aq1, aq2)) aq1,      aed,
 decode(:par4, 1, aq3, util_pg.sumn(aq3, aq4)) aq3,aq2, aq4,aerm,decode(:par4, 1, aq1m, util_pg.sumn(aq1m, aq2m)) aq1m,      aedm,
 decode(:par4, 1, aq3m, util_pg.sumn(aq3m, aq4m)) aq3m,      aq2m, aq4m,'''', '''', '''' from '||lv_tablename||
 ' where t.date_time >= :par1 and t.date_time < :par2  and 1=:par3 union all
 select '''', '''', p1Name, p2Name, mid , ''B'', 3 , ber, decode(:par4, 1, bq1, util_pg.sumn(bq1, bq2)) bq1,      bed,
 decode(:par4, 1, bq3, util_pg.sumn(bq3, bq4)) bq3,bq2, bq4, berm,decode(:par4, 1, bq1m, util_pg.sumn(bq1m, bq2m)) bq1m,      bedm,
 decode(:par4, 1, bq3m, util_pg.sumn(bq3m, bq4m)) bq3m,      bq2m, bq4m , '''', '''', ''''	from '||lv_tablename||
 ' where t.date_time >= :par1 and t.date_time < :par2 and 1=:par3 union all
 select '''', '''', p1Name, p2Name, mid, ''C'', 4,cer,decode(:par4, 1, cq1, util_pg.sumn(cq1, cq2)) cq1,ced,
 decode(:par4, 1, cq3, util_pg.sumn(cq3, cq4)) cq3,cq2, cq4, cerm,decode(:par4, 1, cq1m, util_pg.sumn(cq1m, cq2m)) cq1m,cedm,
 decode(:par4, 1, cq3m, util_pg.sumn(cq3m, cq4m)) cq3m,cq2m, cq4m ,'''', '''', ''''	from '||lv_tablename||
 ' where t.date_time >= :par1 and  t.date_time < :par2 and 1=:par3 union all
 select '''', '''', p1Name, p2Name, mid,''D'', 5, der,decode(:par4, 1, dq1, util_pg.sumn(dq1, dq2)) dq1,ded,
 decode(:par4, 1, dq3, util_pg.sumn(dq3, dq4)) dq3,dq2,dq4, derm,decode(:par4, 1, dq1m, util_pg.sumn(dq1m, dq2m)) dq1m,
 dedm,decode(:par4, 1, dq3m, util_pg.sumn(dq3m, dq4m)) dq3m,dq2m, dq4m      ,      '''', '''', ''''	from     '||lv_tablename||
 ' where t.date_time >= :par1 and t.date_time < :par2 and 1=:par3 order by 3, 4, 7';
     OPEN acur_t FOR lv_sql
     using an_WilBiAdd,an_WilBiAdd,an_WilBiAdd,an_WilBiAdd,ad_prLBDT,ad_prHBDT,
           an_WilBiAdd,an_WilBiAdd,an_WilBiAdd,an_WilBiAdd,ad_prLBDT,ad_prHBDT,an_ChBZone,
           an_WilBiAdd,an_WilBiAdd,an_WilBiAdd,an_WilBiAdd,ad_prLBDT,ad_prHBDT,an_ChBZone,
           an_WilBiAdd,an_WilBiAdd,an_WilBiAdd,an_WilBiAdd,ad_prLBDT,ad_prHBDT,an_ChBZone,
           an_WilBiAdd,an_WilBiAdd,an_WilBiAdd,an_WilBiAdd,ad_prLBDT,ad_prHBDT,an_ChBZone;
 
   end;
   --ad_prLBDT - floor( prDT )время начало
   --ad_prHBDT -prLBDT+1 время конец
   --an_ChBZone - тарифные зоны
   --an_WilBiAdd - если значение = 1 Q1 = Q1 иначе Q1=Q1+Q2 тоже с Q3
   --av_table - таблица 3- суточные "bill" или 4-месячные "month"
   --------------------------------
 

  ----------------------------------------------------------------------------------------------------------
 PROCEDURE get_MaxDT(an_Table NUMBER,--имя таблицы
                     an_ChBSrezIsHBound NUMBER,--(ChBSrezIsHBound->Checked)?an_ChBSrezIsHBound=1:an_ChBSrezIsHBound=0 показать для
                     ad_prLBDT DATE,--период от; если an_ChBSrezIsHBound==0 параметр NULL
                     ad_prHBDT DATE,--период до;если an_ChBSrezIsHBound==0 параметр NULL
                     acur_t OUT common_pg.tcur) IS -- возвращает мах дату в таблице в периоде от-до(TMainWin1702->MaxDT)
   
 lv_tablename varchar2(40);--имя таблицы
 
 BEGIN

  if(an_Table=1)then lv_tablename:=' profile ';
  elsif(an_Table=2)then lv_tablename:=' halfhourold ';
  elsif(an_Table=3)then lv_tablename:=' billorg ';
  elsif(an_Table=4)then lv_tablename:=' monthsorg ';
  end if;

   if an_ChBSrezIsHBound=1 then
    OPEN acur_t FOR
     'select max( date_time ) from '
    ||lv_tablename
     ||' where  date_time >:par3  and  date_time <=:par4'
       using ad_prLBDT ,ad_prHBDT;
   else
   OPEN acur_t FOR
     'select max( date_time ) from '
     ||lv_tablename;
   end if;
    end;
  -------------------------------------------------------------------------------------
  PROCEDURE get_PassDT(an_id NUMBER,--ид.точки
                      ad_prLBDT DATE,-- период от
                      ad_prHBDT DATE  ,-- период до
                      an_table NUMBER,--имя таблицы 0-"profileevid",1-"halfhourevid",2-"billevid",3-"monthsevid"
                      acur_t OUT common_pg.tcur) IS -- возвращает  дату в периоде от-до для точки(TMainWin1702->OQryPass)
    lv_tablename VARCHAR2(100);
    lv_sql VARCHAR2(2000);
    BEGIN
    if(an_table=0)then lv_tablename:=' profile ';
    elsif (an_table=1)then lv_tablename:=' halfhourold ';
    elsif (an_table=2)then lv_tablename:=' billorg ';
    elsif (an_table=3)then lv_tablename:=' monthsorg ';
    end if;
    
   lv_sql:= 'select
     h.date_time
     from '||lv_tablename||'
        h
     where
       ( h.mid = :par1 )
    and
    ( h.date_time >= :par2 )
  	and
    ( h.date_time <= :par3 )
  order by
    h.date_time';
  OPEN acur_t FOR lv_sql
    using an_id,ad_prLBDT,ad_prHBDT;
     end;
-------------------------------------------------------------------------------------------------------
 PROCEDURE get_HistProfile(an_id NUMBER,--ид.точки
                           ad_prLBDT DATE,--период от
                           ad_prHBDT DATE,--период до
                           an_WilBiAdd NUMBER,-- если значение = 1 Q1 = Q1 иначе Q1=Q1+Q2 тоже с Q3
                           acur_t OUT common_pg.tcur) IS
   -- в глубину по времени минутные(TMainWin1702->OQryHistProfile)
    BEGIN
    OPEN acur_t FOR
       'select
  h.date_time,
  h.mid, h.er, h.ed,
  decode(:par4, 1, h.q1, util_pg.sumn(h.q1, h.q2)) q1,
  decode(:par4, 1, h.q3, util_pg.sumn(h.q3,h.q4)) q3,
  h.q2, h.q4, h.erm, h.edm,
  decode(:par4, 1, h.q1m, util_pg.sumn(h.q1m, h.q2m)) q1m,
  decode(:par4, 1, h.q3m, util_pg.sumn(h.q3m,h.q4m)) q3m,
  h.q2m, h.q4m, to_char(h.denter, ''dd.mm.yyyy hh24:mi'') denter,
  TO_NUMBER(NULL) status, h.vqm, '''' metername
  from
    profile h
  where
    ( h.mid = :par1 )
    and
    ( h.date_time >= :par2 )
  	and
    ( h.date_time <= :par3 )
  order by
    h.date_time desc'
    using an_WilBiAdd,an_WilBiAdd,an_WilBiAdd,an_WilBiAdd,an_id,ad_prLBDT,ad_prHBDT;
     end;
----------------------------------------------------------------------------------------------------------------
 PROCEDURE get_HistHH(     an_id NUMBER,--ид.точки
                           ad_prLBDT DATE,--период от
                           ad_prHBDT DATE,--период до
                           an_WilBiAdd NUMBER,-- если значение = 1 Q1 = Q1 иначе Q1=Q1+Q2 тоже с Q3
                           an_MemShowP NUMBER,-- if(!cbShowP->Checked)an_MemShowP=0 отображать потери
                           an_MemOnlyCalc NUMBER,--if(ParamsF->MemOnlyCalc)an_MemOnlyCalc=1 только расчетные данные
                           acur_t OUT common_pg.tcur) IS
   -- в глубину по времени ГН(TMainWin1702->OQryHistHH)
 lv_nsource VARCHAR2(400);
 lv_nexccalc VARCHAR2(400);
    BEGIN
    if(an_MemShowP=0) then
      lv_nsource:=' and ((nsource>=0 or nsource<-5000) and nsource<>100) ';
    else lv_nsource:=' ';
    end if;
    if (an_MemOnlyCalc=1) then
     lv_nexccalc:=' and nexceptcalc is null ';
    else lv_nexccalc:=' ';
    end if;
    OPEN acur_t FOR
    'select h.date_time,h.nsource,h.nexceptcalc, h.mid, h.er, h.ed,
                             decode(:par4, 1, h.q1, util_pg.sumn(h.q1, h.q2)) q1,
                             decode(:par4, 1, h.q3, util_pg.sumn(h.q3, h.q4)) q3,
                             h.q2, h.q4, h.erm, h.edm,
                             decode(:par4, 1, h.q1m, util_pg.sumn(h.q1m, h.q2m)) q1m,
                             decode(:par4, 1, h.q3m, util_pg.sumn(h.q3m, h.q4m)) q3m,
                              h.q2m, h.q4m,
                             to_char(h.denter, ''dd.mm.yyyy hh24:mi'') denter,
                             h.status, h.vqm, t.vname metername
                              from halfhourold h, metertype t
                             where h.nmetertype=t.nmetertype(+)
                             and ( h.mid = :par1 )
                             and ( h.date_time >= :par2 ) and ( h.date_time <= :par3 )'||lv_nsource||
                             lv_nexccalc||' order by h.date_time desc'
   using an_WilBiAdd,an_WilBiAdd,an_WilBiAdd,an_WilBiAdd,an_id,ad_prLBDT,ad_prHBDT;
                             
     end;
------------------------------------------------------------------------------------------------------------------------
 PROCEDURE get_NPTerm(     an_id NUMBER,--ид.точки
                           ad_prLBDT DATE,--период от
                           ad_prHBDT DATE,--период до
                           an_WilBiAdd NUMBER,-- если значение = 1 Q1 = Q1 иначе Q1=Q1+Q2 тоже с Q3
                           an_MemShowP NUMBER,-- if(!cbShowP->Checked)an_MemShowP=0 отображать потери
                           an_MemOnlyCalc NUMBER,--if(ParamsF->MemOnlyCalc)an_MemOnlyCalc=1 только расчетные данные
                           acur_t OUT common_pg.tcur) IS
   -- терминал профиля нагрузки(TMainWin1702->NPTermOQry)
 lv_nsource VARCHAR2(400);
 lv_nexccalc VARCHAR2(400);
    BEGIN
    if(an_MemShowP=0) then
      lv_nsource:=' and ((nsource>=0 or nsource<-5000) and nsource<>100) ';
    else lv_nsource:=' ';
    end if;
    if (an_MemOnlyCalc=1) then
     lv_nexccalc:=' and nexceptcalc is null ';
    else lv_nexccalc:=' ';
    end if;
    OPEN acur_t FOR
    'select h.date_time, h.NSOURCE, h.NEXCEPTCALC, h.mid, h.er,
                             decode(:par4, 1, h.q1, util_pg.sumn(h.q1, h.q2)) q1, h.ed,
                             decode(:par4, 1, h.q3, util_pg.sumn(h.q3, h.q4)) q3,h.status, h.dclosed
                             from halfhourold h
                             where ( h.mid = :par1 ) and ( h.date_time >= :par2 ) and ( h.date_time <= :par3 ) '
                             ||lv_nsource||lv_nexccalc|| ' order by h.date_time'

    using an_WilBiAdd,an_WilBiAdd,an_id,ad_prLBDT,ad_prHBDT;
     end;
-----------------------------------------------------------------------------------------------------------------------------
 PROCEDURE get_HistBillorMonth(   an_id NUMBER,--ид.точки
                                  ad_prLBDT DATE,--период от
                                  ad_prHBDT DATE,--период до
                                  an_ChBZone NUMBER,-- тарифные зоны    ParamsF->ChBZone->Checked
                                  an_WilBiAdd NUMBER,-- если значение = 1 Q1 = Q1 иначе Q1=Q1+Q2 тоже с Q3
                                  an_TableName NUMBER,--имя таблицы 2-"billevid" , 3-"monthsevid"
                                 acur_t OUT common_pg.tcur) IS
   -- в глубину по времени суточные(TMainWin1702->OQryHistBill)
  ln_TableName VARCHAR2(100);
  BEGIN
  if (an_TableName=2)then ln_TableName:=' billorg ';
  else ln_TableName:=' monthsorg ';
  end if;
  
  OPEN acur_t FOR
   'select
      to_char( date_time, ''dd.mm.yy   hh24:mi'' ), date_time
   	  ,
      ''S'', 1
      ,
      er,
      decode(:par5, 1, q1, util_pg.sumn(q1, q2)) q1,
      ed,
      decode(:par5, 1, q3, util_pg.sumn(q3, q4)) q3,
      q2, q4, erm,
      decode(:par5, 1, q1m, util_pg.sumn(q1m, q2m)) q1m,
      edm,
      decode(:par5, 1, q3m, util_pg.sumn(q3m, q4m)) q3m,
      q2m, q4m, to_char(denter, ''dd.mm.yyyy hh24:mi'') denter
      ,
      er_mtrsn
	from
      '||ln_TableName||'
	where
        ( mid = :par1 )
        and
        (  date_time >= :par2 )
        and
        (  date_time <= :par3 )
union all
select
      '''', date_time
      , ''A'', 2
      ,
      aer,
      decode(:par5, 1, aq1, util_pg.sumn(aq1, aq2)) aq1,
      aed,
      decode(:par5, 1, aq3, util_pg.sumn(aq3, aq4)) aq3,
