CREATE OR REPLACE 
PACKAGE BODY file_pg IS
 -------------------------------------------------------------------------------------------
 --****                         Interface                                             ****--
 -------------------------------------------------------------------------------------------
 gr_file      sys.UTL_FILE.file_type;
 gvcurr_param VARCHAR2(2000);
 gn_task_code NUMBER;
 gn_immediate NUMBER;
 gn_currpos   NUMBER;
 gn_outtype   NUMBER;
 -------------------------------------------------------------------------------------------
 --****                       Implementation                                          ****--
 -------------------------------------------------------------------------------------------
 FUNCTION gv_param
  RETURN VARCHAR2 IS
 BEGIN
  RETURN gvcurr_param;
 END;
 -------------------------------------------------------------------------------------------
  --Возвращает запущен ли процесс вручную
 FUNCTION is_immediate
  RETURN NUMBER IS
 BEGIN
  RETURN NVL(gn_immediate, 0);
 END;
 ------------------------------------------------------------------------------------------------------------------------
 /*Управляет потоком вывода - файл или переменная*/
 PROCEDURE setout_p(an_out NUMBER) IS --an_out -1 выводим в переменную иначе в файл
 BEGIN
  gn_outtype := an_out;
 END;
 ------------------------------------------------------------------------------------------------------------------------
 PROCEDURE out_p(av_str VARCHAR2) IS
 BEGIN
  IF gn_outtype = 1 THEN
   filereport_pg.put_p(av_str);
  ELSE
   sys.UTL_FILE.put_line(gr_file, av_str);
  END IF;
  gn_currpos := gn_currpos + 1;
 END;
 -------------------------------------------------------------------------------------------------
 FUNCTION open_f(av_fpath VARCHAR2, av_fname VARCHAR2, av_type VARCHAR2 DEFAULT 'w')
  RETURN sys.UTL_FILE.file_type IS
 BEGIN
  gn_currpos := 0;
  setout_p();
  RETURN sys.UTL_FILE.fopen(av_fpath, av_fname, av_type);
 END;
 -------------------------------------------------------------------------------------------------
 PROCEDURE remove_p(av_fpath VARCHAR2, av_fname VARCHAR2) IS
 BEGIN
  EXECUTE IMMEDIATE 'begin sys.UTL_FILE.fremove(:1,:2); end;' USING av_fpath, av_fname;
 EXCEPTION
  WHEN OTHERS THEN
   NULL;
 END;
 -------------------------------------------------------------------------------------------------
 PROCEDURE main_p IS
  CURSOR lcur_sel(lc_sys DATE) IS
   SELECT   p.nprocedure, p.ntype, m.vparam, m.nmaket, p.vname, p.vprocedure, m.ncycle, m.nshift, p.nperiod,
            DECODE(
             m.doldcreated, NULL, DECODE(
                                   p.nperiod, 0, lc_sys, 1, TRUNC(lc_sys - m.nshift / 1440, 'HH24') -
                                                            1 / 24, 2, TRUNC(
                                                                        lc_sys - m.nshift / 1440, 'DD') -
                                                                       1, 3, TRUNC(
                                                                              lc_sys - m.nshift / 1440, 'D') -
                                                                             7, 4,
                                   util_pg.add_dec(util_pg.truncdec(lc_sys - m.nshift / 1440), -1), 5,
                                   ADD_MONTHS(TRUNC(lc_sys - m.nshift / 1440, 'MM'), -1), 6,
                                   util_pg.trunc_d(lc_sys - m.nshift / 1440, 1 / 96) -
                                   1 / 96, 8, util_pg.trunc_d(lc_sys - m.nshift / 1440, 1 / 48) -
                                              1 / 48),
             DECODE(
              p.nperiod, 0, lc_sys, 1, DECODE(
                                        m.ncycle, 1, TRUNC(m.doldcreated, 'HH24') + 1 / 24,
                                        TRUNC(lc_sys - m.nshift / 1440, 'HH24') - 1 / 24), 2,
              DECODE(
               m.ncycle, 1, TRUNC(m.doldcreated, 'DD') + 1, TRUNC(lc_sys - m.nshift / 1440, 'DD') - 1), 3,
              DECODE(m.ncycle, 1, TRUNC(m.doldcreated, 'D') + 7, TRUNC(lc_sys - m.nshift / 1440, 'D') - 7), 4,
              DECODE(
               m.ncycle, 1, util_pg.add_dec(util_pg.truncdec(m.doldcreated), 1),
               util_pg.add_dec(util_pg.truncdec(lc_sys - m.nshift / 1440), -1)), 5,
              DECODE(
               m.ncycle, 1, ADD_MONTHS(TRUNC(m.doldcreated, 'MM'), 1), ADD_MONTHS(
                                                                        TRUNC(
                                                                         lc_sys - m.nshift / 1440, 'MM'), -1)), 6,
              DECODE(
               m.ncycle, 1, util_pg.trunc_d(m.doldcreated, 1 / 96) + 1 / 96, util_pg.trunc_d(
                                                                              lc_sys - m.nshift / 1440, 1 / 96) -
                                                                             1 / 96), 8,
              DECODE(
               m.ncycle, 1, util_pg.trunc_d(m.doldcreated, 1 / 48) + 1 / 48, util_pg.trunc_d(
                                                                              lc_sys - m.nshift / 1440, 1 / 48) -
                                                                             1 / 48))) doldcreated,
            m.vname mname
       FROM deportprocedures p, makets m
      WHERE p.nprocedure = m.nprocedure
        AND (p.ntype <> 0 OR EXISTS(
                                SELECT *
                                  FROM deportation
                                 WHERE nmaket = m.nmaket /*AND nblock = 0*/ AND nparent IS NULL))
        AND m.nblock = 0
        AND (   m.doldcreated IS NULL
             OR DECODE(
                 p.nperiod, 0, m.doldcreated, 1, TRUNC(m.doldcreated, 'HH24') + 2 / 24, 2, TRUNC(m.doldcreated, 'DD') + 2,
                 3, TRUNC(m.doldcreated, 'D') + 14, 4, util_pg.add_dec(util_pg.truncdec(m.doldcreated), 2), 5,
                 ADD_MONTHS(TRUNC(m.doldcreated, 'MM'), 2), 6, util_pg.trunc_d(m.doldcreated, 1 / 96) +
                                                               2 / 96, 8, util_pg.trunc_d(m.doldcreated, 1 / 48) +
                                                                          2 / 48) <=
                                                                               lc_sys - m.nshift / 1440)
   ORDER BY 1, 2;
  CURSOR lcur_deport(lc_maket NUMBER) IS
   SELECT ndeportation, vparam
     FROM deportation
    WHERE nmaket = lc_maket AND nparent IS NULL /*AND nblock = 0*/;
  ld_sys      DATE           DEFAULT SYSDATE;
  lv_seqfname VARCHAR2(128);
  lv_orgfname VARCHAR2(128);
  lv_tmpname  VARCHAR2(128);
  lv_fname    VARCHAR2(2000);
  lv_fpath    VARCHAR2(2000);
  ld_counter  DATE;
  ln_handle   INTEGER;
  ln_ret      NUMBER;
  ln_code     NUMBER;
  lv_error    VARCHAR2(2000);
  ln_step     NUMBER;
 BEGIN
  admin_pg.begin_p;
  gn_immediate := 0;
  SELECT MAX(vvalue)
    INTO lv_fpath
    FROM parameter
   WHERE npid = 10;
  IF lv_fpath IS NULL THEN
   raise_application_error(-20002, 'Не задан каталог для хранения файлов рассылки в таблице конфигураций.');
  END IF;
  ln_handle := sys.DBMS_SQL.open_cursor;
  FOR lc IN lcur_sel(ld_sys) LOOP
   ld_counter := lc.doldcreated;
   gvcurr_param := lc.vparam;
   ln_step := 0;
   WHILE (lc.nperiod = 0)
      OR (lc.nperiod = 1 AND ld_counter + 1 / 24 <= ld_sys - lc.nshift / 1440)
      OR (lc.nperiod = 2 AND ld_counter + 1 <= ld_sys - lc.nshift / 1440)
      OR (lc.nperiod = 3 AND ld_counter + 7 <= ld_sys - lc.nshift / 1440)
      OR (lc.nperiod = 4 AND util_pg.add_dec(ld_counter, 1) <= ld_sys - lc.nshift / 1440)
      OR (lc.nperiod = 5 AND ADD_MONTHS(ld_counter, 1) <= ld_sys - lc.nshift / 1440)
      OR (lc.nperiod = 6 AND ld_counter + 1 / 96 <= ld_sys - lc.nshift / 1440)
      OR (lc.nperiod = 8 AND ld_counter + 1 / 48 <= ld_sys - lc.nshift / 1440) LOOP
    BEGIN
     BEGIN
      IF lc.ntype = 0 THEN --Макет
       IF ln_step > 0 THEN --Чтоб файлы с названием по тек времени отличались
        sys.DBMS_LOCK.sleep(1);
       END IF;
       SELECT TO_CHAR(deportation_seq.NEXTVAL) || '.txt'
         INTO lv_seqfname
         FROM DUAL;
       lv_orgfname := lv_seqfname;
       lv_fname := lv_fpath || lv_seqfname;
       gr_file := open_f(lv_fpath, lv_fname);
       sys.DBMS_SQL.parse(
        ln_handle, 'BEGIN ' || lc.vprocedure || '(:lc_maket,:lc_dat,:lc_fname); END;', sys.DBMS_SQL.native);
       sys.DBMS_SQL.bind_variable(ln_handle, 'lc_maket', lc.nmaket);
       sys.DBMS_SQL.bind_variable(ln_handle, 'lc_dat', ld_counter);
       sys.DBMS_SQL.bind_variable(ln_handle, 'lc_fname', lv_orgfname, 128);
       IF sys.DBMS_SQL.EXECUTE(ln_handle) < 0 THEN
        raise_application_error(-20002, 'Ошибка запуска макета.');
       END IF;
       sys.DBMS_SQL.variable_value(ln_handle, 'lc_fname', lv_orgfname);
       sys.UTL_FILE.fclose(gr_file);
       admin_pg.journal_p(
        lc.nmaket, 0, 'Выполнено формирование макета: ''' || lc.mname || ''' за ''' ||
                      TO_CHAR(ld_counter, 'dd.mm.yyyy hh24:mi') || '''.');
       FOR lc1 IN lcur_deport(lc.nmaket) LOOP
        IF gn_currpos = 0 THEN --пустой файл
         remove_p(lv_fpath, lv_fname);
         DELETE FROM deportfiles
               WHERE ndeportation = lc1.ndeportation AND ddate = ld_counter;
        ELSE --делаем что надо
         IF lv_orgfname = lv_seqfname THEN
          BEGIN
           IF  TRIM(util_pg.get_param(lc1.vparam, 1)) = '2' AND TRIM(util_pg.get_param(lc1.vparam, 2)) IS NOT NULL THEN
            lv_tmpname := TO_CHAR(ld_counter, util_pg.get_param(lc1.vparam, 2));
           ELSIF  TRIM(util_pg.get_param(lc1.vparam, 1)) = '3' AND TRIM(util_pg.get_param(lc1.vparam, 2)) IS NOT NULL THEN
            lv_tmpname := TO_CHAR(SYSDATE, util_pg.get_param(lc1.vparam, 2));
           ELSE
            lv_tmpname := NVL(util_pg.get_param(lc1.vparam, 2), lv_orgfname);
           END IF;
          EXCEPTION
           WHEN OTHERS THEN
            lv_tmpname := NVL(util_pg.get_param(lc1.vparam, 2), lv_orgfname);
          END;
         ELSE
          lv_tmpname := lv_orgfname;
         END IF;
         lv_tmpname := TRANSLATE(lv_tmpname, '/*\"', '....');
         UPDATE deportfiles
            SET vfile = lv_seqfname,
                vfilename = lv_tmpname,
                nattach = DECODE(util_pg.get_param(lc1.vparam, 1), '1', 1, '2', 1, '3', 1, 0),
                nstate = 0,
                verror = NULL,
                denter = SYSDATE
          WHERE ndeportation = lc1.ndeportation AND ddate = ld_counter;
         IF SQL%ROWCOUNT = 0 THEN
          INSERT INTO deportfiles
                      (ndeportation, ddate, vfile, vfilename,
                       nattach, nstate, verror)
               VALUES (lc1.ndeportation, ld_counter, lv_seqfname, lv_tmpname,
                       DECODE(util_pg.get_param(lc1.vparam, 1), '1', 1, '2', 1, '3', 1, 0), 0, NULL);
         END IF;
        END IF;
       END LOOP;
      ELSE --Процедура верификации
       sys.DBMS_SQL.parse(ln_handle, 'BEGIN ' || lc.vprocedure || '(:lc_maket,:lc_dat); END;', sys.DBMS_SQL.native);
       sys.DBMS_SQL.bind_variable(ln_handle, 'lc_maket', lc.nmaket);
       sys.DBMS_SQL.bind_variable(ln_handle, 'lc_dat', ld_counter);
       IF sys.DBMS_SQL.EXECUTE(ln_handle) < 0 THEN
        raise_application_error(-20002, 'Ошибка запуска фонового процесса.');
       END IF;
       IF NVL(lc.nprocedure, 0) NOT IN (31) THEN
        admin_pg.journal_p(
         lc.nmaket, 0, 'Выполнен фоновый процесс: ''' || lc.mname || ''' за ''' ||
                       TO_CHAR(ld_counter, 'dd.mm.yyyy hh24:mi') || '''.');
       END IF;
      END IF;
      UPDATE makets
         SET verror = NULL,
             doldcreated = ld_counter,
             dlastcreated = SYSDATE
       WHERE nmaket = lc.nmaket;
      COMMIT;
      ln_step := ln_step + 1;
      IF lc.nperiod = 1 THEN
       ld_counter := ld_counter + 1 / 24;
      ELSIF lc.nperiod = 2 THEN
       ld_counter := ld_counter + 1;
      ELSIF lc.nperiod = 3 THEN
       ld_counter := ld_counter + 7;
      ELSIF lc.nperiod = 4 THEN
       ld_counter := util_pg.add_dec(ld_counter, 1);
      ELSIF lc.nperiod = 5 THEN
       ld_counter := ADD_MONTHS(ld_counter, 1);
      ELSIF lc.nperiod = 6 THEN
       ld_counter := ld_counter + 1 / 96;
      ELSIF lc.nperiod = 8 THEN
       ld_counter := ld_counter + 1 / 48;
      ELSE
       EXIT;
      END IF;
     EXCEPTION
      WHEN sys.UTL_FILE.invalid_path THEN
       raise_application_error(-20001, common_pg.geterrtext(1) || lv_fname);
      WHEN sys.UTL_FILE.invalid_operation THEN
       raise_application_error(-20001, common_pg.geterrtext(2) || lv_fname);
      WHEN sys.UTL_FILE.invalid_filehandle THEN
       raise_application_error(-20001, common_pg.geterrtext(3) || lv_fname);
      WHEN sys.UTL_FILE.write_error THEN
       raise_application_error(-20001, common_pg.geterrtext(4) || lv_fname);
      WHEN OTHERS THEN
       RAISE;
     END;
    EXCEPTION
     WHEN OTHERS THEN
      lv_error := SUBSTR('file_pg.main_p: '|| SQLERRM, 1, 2000);
      ln_code := SQLCODE;
      sys.UTL_FILE.fclose_all;
      ROLLBACK;
      UPDATE makets
         SET verror = lv_error
       WHERE nmaket = lc.nmaket;
      COMMIT;
      IF ln_code = -28 OR ln_code = -1089 THEN
       RAISE;
      ELSE
       EXIT;
      END IF;
    END;
    IF lc.nperiod = 0 THEN --Выходим для периодических
     EXIT;
    END IF;
   END LOOP;
  END LOOP;
  sys.DBMS_SQL.close_cursor(ln_handle);
  INSERT INTO jobs
              (njob, date_time)
       VALUES (2, SYSDATE);
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   lv_error := SUBSTR('file_pg.main_p: '|| SQLERRM, 1, 2000);
   ROLLBACK;
   IF sys.DBMS_SQL.is_open(ln_handle) THEN
    sys.DBMS_SQL.close_cursor(ln_handle);
   END IF;
   INSERT INTO jobs
               (njob, date_time, errortext)
        VALUES (2, SYSDATE, lv_error);
   COMMIT;
 END;
 ------------------------------------------------------------------------------------------------------------------------
 PROCEDURE startimmediate_p(an_maket NUMBER, ad_date DATE, av_param VARCHAR2) IS
  CURSOR lcur_sel IS
   SELECT m.nmaket, p.ntype, p.vprocedure,
          DECODE(
           p.nperiod, 0, ad_date, 1, TRUNC(ad_date, 'HH24'), 2, TRUNC(ad_date, 'DD'), 3, TRUNC(ad_date, 'D'), 4,
           util_pg.truncdec(ad_date), 5, TRUNC(ad_date, 'MM'), 6, util_pg.trunc_d(ad_date, 1 / 96), 8,
           util_pg.trunc_d(ad_date, 1 / 48)) doldcreated,
          m.vname mname
     FROM deportprocedures p, makets m
    WHERE m.nmaket = an_maket
      AND m.nprocedure = p.nprocedure(+)
      AND (p.ntype <> 0 OR EXISTS(
                                SELECT *
                                  FROM deportation
                                 WHERE nmaket = an_maket /*AND nblock = 0*/ AND nparent IS NULL));
  CURSOR lcur_deport(lc_maket NUMBER) IS
   SELECT ndeportation, vparam
     FROM deportation
    WHERE nmaket = lc_maket AND nparent IS NULL /*AND nblock = 0*/;
  lv_seqfname    VARCHAR2(128);
  lv_orgfname    VARCHAR2(128);
  lv_tmpname     VARCHAR2(128);
  lv_fname       VARCHAR2(2000);
  lv_fpath       VARCHAR2(2000);
  ln_handle      INTEGER;
  ln_ret         NUMBER;
  ln_code        NUMBER;
  lv_error       VARCHAR2(2000);
  lc             lcur_sel%ROWTYPE;
  lv_mname       VARCHAR2(200);
  lv_oldprocname VARCHAR2(200);
 BEGIN
  gn_task_code := 606;
  gn_immediate := 1;
  SELECT vname
    INTO lv_oldprocname
    FROM deportprocedures
   WHERE nprocedure = (SELECT nprocedure
                         FROM makets
                        WHERE nmaket = an_maket);
  SELECT vname
    INTO lv_mname
    FROM makets
   WHERE nmaket = an_maket;
  admin_pg.fiscal_p(
   gn_task_code, 2, 'Запущен фоновый процесс ' || lv_mname || ' Процедура ' || lv_oldprocname || ' Дата ' ||
                    TO_CHAR(ad_date, 'dd.mm.yyyy hh24:mi:ss') || ' Параметр ' || av_param);
  gvcurr_param := av_param;
  OPEN lcur_sel;
  FETCH lcur_sel INTO lc;
  IF lcur_sel%NOTFOUND THEN
   CLOSE lcur_sel;
   raise_application_error(-20002, 'Задание не найдено или нет доступных адресатов для получения макета.');
  END IF;
  CLOSE lcur_sel;
  ln_handle := sys.DBMS_SQL.open_cursor;
  IF lc.ntype = 0 THEN --Макет
   SELECT MAX(vvalue)
     INTO lv_fpath
     FROM parameter
    WHERE npid = 10;
   IF lv_fpath IS NULL THEN
    raise_application_error(-20002, 'Не задан каталог для хранения файлов рассылки в таблице конфигураций.');
   END IF;
   BEGIN
    SELECT TO_CHAR(deportation_seq.NEXTVAL) || '.txt'
      INTO lv_seqfname
      FROM DUAL;
    lv_orgfname := lv_seqfname;
    lv_fname := lv_fpath || lv_seqfname;
    gr_file := open_f(lv_fpath, lv_fname);
    sys.DBMS_SQL.parse(ln_handle, 'BEGIN ' || lc.vprocedure || '(:lc_maket,:lc_dat,:lc_fname); END;',
                                                                                                    sys.DBMS_SQL.native);
    sys.DBMS_SQL.bind_variable(ln_handle, 'lc_maket', lc.nmaket);
    sys.DBMS_SQL.bind_variable(ln_handle, 'lc_dat', lc.doldcreated);
    sys.DBMS_SQL.bind_variable(ln_handle, 'lc_fname', lv_orgfname, 128);
    IF sys.DBMS_SQL.EXECUTE(ln_handle) < 0 THEN
     raise_application_error(-20002, 'Ошибка запуска макета.');
    END IF;
    sys.DBMS_SQL.variable_value(ln_handle, 'lc_fname', lv_orgfname);
    sys.UTL_FILE.fclose(gr_file);
    admin_pg.journal_p(
     lc.nmaket, 0, 'Выполнено формирование макета: ''' || lc.mname || ''' за ''' ||
                   TO_CHAR(lc.doldcreated, 'dd.mm.yyyy hh24:mi') || '''.');
    FOR lc1 IN lcur_deport(lc.nmaket) LOOP
     IF gn_currpos = 0 THEN --пустой файл
      remove_p(lv_fpath, lv_fname);
      DELETE FROM deportfiles
            WHERE ndeportation = lc1.ndeportation AND ddate = lc.doldcreated;
     ELSE --делаем что надо
      IF lv_orgfname = lv_seqfname THEN
       BEGIN
        IF  TRIM(util_pg.get_param(lc1.vparam, 1)) = '2' AND TRIM(util_pg.get_param(lc1.vparam, 2)) IS NOT NULL THEN
         lv_tmpname := TO_CHAR(lc.doldcreated, util_pg.get_param(lc1.vparam, 2));
        ELSIF  TRIM(util_pg.get_param(lc1.vparam, 1)) = '3' AND TRIM(util_pg.get_param(lc1.vparam, 2)) IS NOT NULL THEN
         lv_tmpname := TO_CHAR(SYSDATE, util_pg.get_param(lc1.vparam, 2));
        ELSE
         lv_tmpname := NVL(util_pg.get_param(lc1.vparam, 2), lv_orgfname);
        END IF;
       EXCEPTION
        WHEN OTHERS THEN
         lv_tmpname := NVL(util_pg.get_param(lc1.vparam, 2), lv_orgfname);
       END;
      ELSE
       lv_tmpname := lv_orgfname;
      END IF;
      lv_tmpname := TRANSLATE(lv_tmpname, '/*\"', '....');
      UPDATE deportfiles
         SET vfile = lv_seqfname,
             vfilename = lv_tmpname,
             nattach = DECODE(util_pg.get_param(lc1.vparam, 1), '1', 1, '2', 1, '3', 1, 0),
             nstate = 0,
             verror = NULL,
             denter = SYSDATE,
             user_id = common_pg.userid_f
       WHERE ndeportation = lc1.ndeportation AND ddate = lc.doldcreated;
      IF SQL%ROWCOUNT = 0 THEN
       INSERT INTO deportfiles
                   (ndeportation, ddate, vfile, vfilename,
                    nattach, nstate, verror, user_id)
            VALUES (lc1.ndeportation, lc.doldcreated, lv_seqfname, lv_tmpname,
                    DECODE(util_pg.get_param(lc1.vparam, 1), '1', 1, '2', 1, '3', 1, 0), 0, NULL, common_pg.userid_f);
      END IF;
     END IF;
    END LOOP;
   EXCEPTION
    WHEN sys.UTL_FILE.invalid_path THEN
     raise_application_error(-20001, common_pg.geterrtext(1) || lv_fname);
    WHEN sys.UTL_FILE.invalid_operation THEN
     raise_application_error(-20001, common_pg.geterrtext(2) || lv_fname);
    WHEN sys.UTL_FILE.invalid_filehandle THEN
     raise_application_error(-20001, common_pg.geterrtext(3) || lv_fname);
    WHEN sys.UTL_FILE.write_error THEN
     raise_application_error(-20001, common_pg.geterrtext(4) || lv_fname);
    WHEN OTHERS THEN
     RAISE;
   END;
  ELSE
   sys.DBMS_SQL.parse(ln_handle, 'BEGIN ' || lc.vprocedure || '(:lc_maket,:lc_dat); END;', sys.DBMS_SQL.native);
   sys.DBMS_SQL.bind_variable(ln_handle, 'lc_maket', lc.nmaket);
   sys.DBMS_SQL.bind_variable(ln_handle, 'lc_dat', lc.doldcreated);
   IF sys.DBMS_SQL.EXECUTE(ln_handle) < 0 THEN
    raise_application_error(-20002, 'Ошибка фонового процесса.');
   END IF;
   admin_pg.journal_p(
    lc.nmaket, 0, 'Выполнен фоновый процесс: ''' || lc.mname || ''' за ''' || TO_CHAR(
                                                                               lc.doldcreated, 'dd.mm.yyyy hh24:mi') ||
                  '''.');
  END IF;
  sys.DBMS_SQL.close_cursor(ln_handle);
  UPDATE makets
     SET dlastcreated = SYSDATE
   WHERE nmaket = an_maket;
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   sys.UTL_FILE.fclose_all;
   IF sys.DBMS_SQL.is_open(ln_handle) THEN
    sys.DBMS_SQL.close_cursor(ln_handle);
   END IF;
   RAISE;
 END;
 -------------------------------------------------------------------------------------------------
 PROCEDURE startbyevents_p(an_procedure NUMBER, an_id NUMBER, ad_date DATE, ad_till DATE) IS
  CURSOR lcur_deport(lc_maket NUMBER) IS
   SELECT ndeportation, vparam
     FROM deportation
    WHERE nmaket = lc_maket AND nparent IS NULL /*AND nblock = 0*/;
  lv_seqfname VARCHAR2(128);
  lv_orgfname VARCHAR2(128);
  lv_tmpname  VARCHAR2(128);
  lv_fname    VARCHAR2(2000);
  lv_fpath    VARCHAR2(2000);
  ln_handle   INTEGER;
  ln_ret      NUMBER;
  ln_code     NUMBER;
  lv_error    VARCHAR2(2000);
 BEGIN
  gn_task_code := 606;
  gn_immediate := 1;
  SELECT MAX(vvalue)
    INTO lv_fpath
    FROM parameter
   WHERE npid = 10;
  FOR lc IN (SELECT m.nmaket, m.vparam, m.vname, p.vprocedure
               FROM deportprocedures p, makets m
              WHERE p.nprocedure = an_procedure
                AND p.nprocedure = m.nprocedure
                AND p.ntype = 0
                AND EXISTS( SELECT *
                              FROM deportation
                             WHERE nmaket = m.nmaket /*AND nblock = 0*/ AND nparent IS NULL)) LOOP
   gvcurr_param := lc.vparam;
   ln_handle := sys.DBMS_SQL.open_cursor;
   IF lv_fpath IS NULL THEN
    raise_application_error(-20002, 'Не задан каталог для хранения файлов рассылки в таблице конфигураций.');
   END IF;
   BEGIN
    SELECT TO_CHAR(deportation_seq.NEXTVAL) || '.txt'
      INTO lv_seqfname
      FROM DUAL;
    lv_orgfname := lv_seqfname;
    lv_fname := lv_fpath || lv_seqfname;
    gr_file := open_f(lv_fpath, lv_fname);
    IF ad_till IS NULL THEN
     sys.DBMS_SQL.parse(ln_handle, 'BEGIN ' || lc.vprocedure || '(:lc_id,:lc_dat,:lc_fname); END;', sys.DBMS_SQL.native);
    ELSE
     sys.DBMS_SQL.parse(
      ln_handle, 'BEGIN ' || lc.vprocedure || '(:lc_id,:lc_dat,:lc_dat1,:lc_fname); END;', sys.DBMS_SQL.native);
     sys.DBMS_SQL.bind_variable(ln_handle, 'lc_dat1', ad_till);
    END IF;
    sys.DBMS_SQL.bind_variable(ln_handle, 'lc_id', an_id);
    sys.DBMS_SQL.bind_variable(ln_handle, 'lc_dat', ad_date);
    sys.DBMS_SQL.bind_variable(ln_handle, 'lc_fname', lv_orgfname, 128);
    IF sys.DBMS_SQL.EXECUTE(ln_handle) < 0 THEN
     raise_application_error(-20002, 'Ошибка запуска макета.');
    END IF;
    sys.DBMS_SQL.variable_value(ln_handle, 'lc_fname', lv_orgfname);
    sys.UTL_FILE.fclose(gr_file);
    FOR lc1 IN lcur_deport(lc.nmaket) LOOP
     IF gn_currpos = 0 THEN --пустой файл
      remove_p(lv_fpath, lv_fname);
      DELETE FROM deportfiles
            WHERE ndeportation = lc1.ndeportation AND ddate = ad_date;
     ELSE --делаем что надо
      IF lv_orgfname = lv_seqfname THEN
       BEGIN
        IF  TRIM(util_pg.get_param(lc1.vparam, 1)) = '2' AND TRIM(util_pg.get_param(lc1.vparam, 2)) IS NOT NULL THEN
         lv_tmpname := TO_CHAR(ad_date, util_pg.get_param(lc1.vparam, 2));
        ELSIF  TRIM(util_pg.get_param(lc1.vparam, 1)) = '3' AND TRIM(util_pg.get_param(lc1.vparam, 2)) IS NOT NULL THEN
         lv_tmpname := TO_CHAR(SYSDATE, util_pg.get_param(lc1.vparam, 2));
        ELSE
         lv_tmpname := NVL(util_pg.get_param(lc1.vparam, 2), lv_orgfname);
        END IF;
       EXCEPTION
        WHEN OTHERS THEN
         lv_tmpname := NVL(util_pg.get_param(lc1.vparam, 2), lv_orgfname);
       END;
      ELSE
       lv_tmpname := lv_orgfname;
      END IF;
      lv_tmpname := TRANSLATE(lv_tmpname, '/*\"', '....');
      UPDATE deportfiles
         SET vfile = lv_seqfname,
             vfilename = lv_tmpname,
             nattach = DECODE(util_pg.get_param(lc1.vparam, 1), '1', 1, '2', 1, '3', 1, 0),
             nstate = 0,
             verror = NULL,
             denter = SYSDATE,
             user_id = common_pg.userid_f
       WHERE ndeportation = lc1.ndeportation AND ddate = ad_date;
      IF SQL%ROWCOUNT = 0 THEN
       INSERT INTO deportfiles
                   (ndeportation, ddate, vfile, vfilename,
                    nattach, nstate, verror, user_id)
            VALUES (lc1.ndeportation, ad_date, lv_seqfname, lv_tmpname,
                    DECODE(util_pg.get_param(lc1.vparam, 1), '1', 1, '2', 1, '3', 1, 0), 0, NULL, common_pg.userid_f);
      END IF;
     END IF;
    END LOOP;
   EXCEPTION
    WHEN sys.UTL_FILE.invalid_path THEN
     raise_application_error(-20001, common_pg.geterrtext(1) || lv_fname);
    WHEN sys.UTL_FILE.invalid_operation THEN
     raise_application_error(-20001, common_pg.geterrtext(2) || lv_fname);
    WHEN sys.UTL_FILE.invalid_filehandle THEN
     raise_application_error(-20001, common_pg.geterrtext(3) || lv_fname);
    WHEN sys.UTL_FILE.write_error THEN
     raise_application_error(-20001, common_pg.geterrtext(4) || lv_fname);
    WHEN OTHERS THEN
     RAISE;
   END;
   sys.DBMS_SQL.close_cursor(ln_handle);
   UPDATE makets
      SET dlastcreated = SYSDATE
    WHERE nmaket = lc.nmaket;
  END LOOP;
 EXCEPTION
  WHEN OTHERS THEN
   sys.UTL_FILE.fclose_all;
   IF sys.DBMS_SQL.is_open(ln_handle) THEN
    sys.DBMS_SQL.close_cursor(ln_handle);
   END IF;
   RAISE;
 END;
