 PROCEDURE data_init(an_procedure NUMBER, acur_t OUT common_pg.tcur) IS
 -- added 31.07.2008  Kondakov A.G.
 -- используется в TfmDeportProcRun::DataInit
 BEGIN
  OPEN acur_t FOR
    SELECT m.vname, nvl( d.vmemo, '' )vmemo, d.vprocedure,
           file_pg.getdeportprocperiod_n_f(d.nperiod)nperiod, m.nshift, d.ntype, nvl( m.vparam, '' )vparam
    FROM deportprocedures d, makets m WHERE d.nprocedure = m.nprocedure AND m.nmaket = an_procedure AND d.NPERIOD<>7
    ORDER BY 1;
 END;
------------------------------------------------------------------------------------------------------------------------
 PROCEDURE read_processes_sh(acur_t OUT common_pg.tcur) IS
 -- added 31.07.2008  Kondakov A.G.
 -- используется в TfmDeportProcsSched::ReadProcesses
 BEGIN
  OPEN acur_t FOR
    SELECT dp.ntype, m.nmaket, m.vname, m.nprocedure, m.vnote,
           file_pg.getdeportprocperiod_v_f(dp.nperiod)nperiod, m.nshift, m.vparam, m.verror,
           to_char(m.doldcreated + 2*file_pg.getdeportprocperiod_n_f(dp.nperiod) + m.nshift/1440,'dd.mm.yyyy hh24:mi:ss') NextCreated,
           m.ncycle, m.nblock, dp.vname vProcedure,to_char(m.dlastcreated,'dd.mm.yyyy hh24:mi:ss') vLastCreated
    FROM makets m, deportprocedures dp
    WHERE dp.nprocedure = m.nprocedure ORDER BY m.nshift,m.vname;
 END;
------------------------------------------------------------------------------------------------------------------------
 PROCEDURE read_processes(acur_t OUT common_pg.tcur) IS
 -- added 31.07.2008  Kondakov A.G.
 -- используется в TfmDeportProcs::ReadProcesses
 BEGIN
  OPEN acur_t FOR
    SELECT dp.ntype, m.nmaket, m.vname, m.nprocedure, m.vnote,
                file_pg.getdeportprocperiod_v_f(dp.nperiod)nperiod,
                m.nshift, m.vparam, m.verror,
                to_char(m.doldcreated + 2*file_pg.getdeportprocperiod_n_f(dp.nperiod) + m.nshift/1440,'dd.mm.yyyy hh24:mi:ss') NextCreated,
                m.ncycle, m.nblock,to_char(DLASTCREATED,'dd.mm.yyyy hh24:mi:ss') LastCreated
                FROM makets m, deportprocedures dp
                WHERE dp.nprocedure = m.nprocedure ORDER BY m.nshift;
 END;
------------------------------------------------------------------------------------------------------------------------
 PROCEDURE read_combo(acur_t OUT common_pg.tcur) IS
 -- added 31.07.2008  Kondakov A.G.
 -- используется в TfmDeportProcs::ReadCombo
 BEGIN
  OPEN acur_t FOR
   SELECT nprocedure, vname, file_pg.getdeportprocperiod_v_f(dp.nperiod)nperiod
   FROM deportprocedures dp ORDER BY vname;
 END;
------------------------------------------------------------------------------------------------------------------------
END; -- Package Body file_pg

