 PROCEDURE main_p(an_form NUMBER, an_group NUMBER, ad_from DATE, ad_till DATE, is_point NUMBER, av_procname VARCHAR2) IS
  lv_procname VARCHAR2(2000);
  ln_handle   INTEGER;
  ln_ret      NUMBER;
  ln_root1    NUMBER;
  ln_root2    NUMBER;
  lv_time     VARCHAR2(8);
  lv_rdat     VARCHAR2(8);
 BEGIN
  gn_currid := an_group;
  gn_currispoint := NVL(is_point, 0);
  gd_currfrom := ad_from;
  gd_currtill := ad_till;
  gn_currline := 0;
  IF gn_currispoint = 1 THEN --точка
   SELECT MAX(name)
     INTO gv_currname
     FROM points
    WHERE mid = an_group;
  ELSE --группа
   SELECT MAX(name), MAX(nroot1), MAX(nroot2)
     INTO gv_currname, ln_root1, ln_root2
     FROM groups
    WHERE gid = an_group;
   IF  ln_root1 > 1 AND ln_root2 IS NOT NULL THEN
    SELECT MAX(gid)
      INTO gn_currid
      FROM groups
     WHERE nroot1 IS NULL AND nroot2 = ln_root2;
   END IF;
  END IF;
  DELETE FROM textreport;
  COMMIT;
  IF av_procname IS NULL THEN
   SELECT RTRIM(LTRIM(MAX(vprocname))), NVL(MAX(SUBSTR(enablecontrols, 2, 1)), '0'),
          NVL(MAX(SUBSTR(enablecontrols, 3, 1)), '0')
     INTO lv_procname, lv_time,
          lv_rdat
     FROM forms
    WHERE fid = an_form;
   IF lv_procname IS NULL THEN
    raise_application_error(-20002, 'filereport_pg.main_p: Не задана отчетная процедура.');
   END IF;
  ELSE
   lv_procname := av_procname;
   lv_time := '1';
   lv_rdat := '1';
  END IF;
  --Если время не учитываем то отсекаем
  IF lv_time = '0' THEN
   gd_currtill := TRUNC(gd_currtill);
   gd_currfrom := TRUNC(gd_currfrom);
  END IF;
  --Если дату 'по' не учитываем то +1
  IF lv_rdat = '0' THEN
   gd_currtill := gd_currfrom + 1;
  END IF;
  file_pg.setout_p(1);
  ln_handle := sys.DBMS_SQL.open_cursor;
  sys.DBMS_SQL.parse(ln_handle, 'begin ' || lv_procname || '; end;', sys.DBMS_SQL.native);
  ln_ret := sys.DBMS_SQL.EXECUTE(ln_handle);
  sys.DBMS_SQL.close_cursor(ln_handle);
  COMMIT;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   IF sys.DBMS_SQL.is_open(ln_handle) THEN
    sys.DBMS_SQL.close_cursor(ln_handle);
   END IF;
   RAISE;
 END;
 ------------------------------------------------------------------------------------------------------------------------
 PROCEDURE put_p(av_text VARCHAR2) IS
 BEGIN
  gn_currline := gn_currline + 1;
  INSERT INTO textreport
              (norder, vtext)
       VALUES (gn_currline, av_text);
 END;
 ------------------------------------------------------------------------------------------------------------------------
 PROCEDURE setheaderrow_p(av_headerrow VARCHAR2, an_pos NUMBER) IS
 BEGIN
  IF an_pos > 0 THEN
   gt_header(an_pos) := av_headerrow;
   gb_useheader := TRUE;
  END IF;
 END;
 ------------------------------------------------------------------------------------------------------------------
 PROCEDURE setuseheader_p(tf BOOLEAN) IS
 BEGIN
  gb_useheader := tf;
  IF NOT tf THEN
   gt_header.DELETE;
  END IF;
 END;
 ------------------------------------------------------------------------------------------------------------------
 PROCEDURE printheader_p IS
 BEGIN
  FOR i IN gt_header.FIRST .. gt_header.LAST LOOP
   IF gt_header.EXISTS(i) THEN
    put_p(gt_header(i));
   END IF;
  END LOOP;
 END;
 ------------------------------------------------------------------------------------------------------------------
 PROCEDURE clear_table IS
 BEGIN
  DELETE FROM textreport;
  COMMIT;
 END;
------------------------------------------------------------------------------------------------------------------
END; -- Package Body REPORTS1_PG
/


