  -- Дата следующих (показаний an_kind=1 или расхода an_kind=2 иначе записи)
 FUNCTION getnextdate (an_mid NUMBER, ad_date DATE, an_ntype NUMBER, an_zone NUMBER, an_table NUMBER,   -- an_table =1 BILL,=2 HALFHOUR,=3 PROFILE иначе MONTHSORG
 an_kind NUMBER
 )
  RETURN DATE IS
  ld_ret   DATE;
 BEGIN
  IF an_table = 1 THEN   --BILL
   IF an_kind = 1 THEN   --Показаний
    SELECT MIN (date_time)
      INTO ld_ret
      FROM bill
     WHERE mid = an_mid AND date_time > ad_date
           AND DECODE (an_zone,
                       1, DECODE (an_ntype, 2, aedm, 3, aq1m, 4, aq2m, 5, aq3m, 6, aq4m, aerm),
                       2, DECODE (an_ntype, 2, bedm, 3, bq1m, 4, bq2m, 5, bq3m, 6, bq4m, berm),
                       3, DECODE (an_ntype, 2, cedm, 3, cq1m, 4, cq2m, 5, cq3m, 6, cq4m, cerm),
                       4, DECODE (an_ntype, 2, dedm, 3, dq1m, 4, dq2m, 5, dq3m, 6, dq4m, derm),
                       DECODE (an_ntype, 2, edm, 3, q1m, 4, q2m, 5, q3m, 6, q4m, erm)
                      ) IS NOT NULL;
   ELSIF an_kind = 2 THEN   --Расхода
    SELECT MIN (date_time)
      INTO ld_ret
      FROM bill
     WHERE mid = an_mid AND date_time > ad_date
           AND DECODE (an_zone,
                       1, DECODE (an_ntype, 2, aed, 3, aq1, 4, aq2, 5, aq3, 6, aq4, aer),
                       2, DECODE (an_ntype, 2, bed, 3, bq1, 4, bq2, 5, bq3, 6, bq4, ber),
                       3, DECODE (an_ntype, 2, ced, 3, cq1, 4, cq2, 5, cq3, 6, cq4, cer),
                       4, DECODE (an_ntype, 2, ded, 3, dq1, 4, dq2, 5, dq3, 6, dq4, der),
                       DECODE (an_ntype, 2, ed, 3, q1, 4, q2, 5, q3, 6, q4, er)
                      ) IS NOT NULL;
   ELSE   --Записей
    SELECT MIN (date_time)
      INTO ld_ret
      FROM bill
     WHERE mid = an_mid AND date_time > ad_date
           AND (DECODE (an_zone,
                        1, DECODE (an_ntype, 2, aedm, 3, aq1m, 4, aq2m, 5, aq3m, 6, aq4m, aerm),
                        2, DECODE (an_ntype, 2, bedm, 3, bq1m, 4, bq2m, 5, bq3m, 6, bq4m, berm),
                        3, DECODE (an_ntype, 2, cedm, 3, cq1m, 4, cq2m, 5, cq3m, 6, cq4m, cerm),
                        4, DECODE (an_ntype, 2, dedm, 3, dq1m, 4, dq2m, 5, dq3m, 6, dq4m, derm),
                        DECODE (an_ntype, 2, edm, 3, q1m, 4, q2m, 5, q3m, 6, q4m, erm)
                       ) IS NOT NULL
                OR DECODE (an_zone,
                           1, DECODE (an_ntype, 2, aed, 3, aq1, 4, aq2, 5, aq3, 6, aq4, aer),
                           2, DECODE (an_ntype, 2, bed, 3, bq1, 4, bq2, 5, bq3, 6, bq4, ber),
                           3, DECODE (an_ntype, 2, ced, 3, cq1, 4, cq2, 5, cq3, 6, cq4, cer),
                           4, DECODE (an_ntype, 2, ded, 3, dq1, 4, dq2, 5, dq3, 6, dq4, der),
                           DECODE (an_ntype, 2, ed, 3, q1, 4, q2, 5, q3, 6, q4, er)
                          ) IS NOT NULL
               );
   END IF;
  ELSIF an_table = 2 THEN   --HALFHOUR
   IF an_kind = 1 THEN   --Показаний
    SELECT MIN (date_time)
      INTO ld_ret
      FROM halfhour
     WHERE mid = an_mid AND date_time > ad_date AND DECODE (an_ntype, 2, edm, 3, q1m, 4, q2m, 5, q3m, 6, q4m, erm) IS NOT NULL;
   ELSIF an_kind = 2 THEN   --Расхода
    SELECT MIN (date_time)
      INTO ld_ret
      FROM halfhour
     WHERE mid = an_mid AND date_time > ad_date AND DECODE (an_ntype, 2, ed, 3, q1, 4, q2, 5, q3, 6, q4, er) IS NOT NULL;
   ELSE   --Записей
    SELECT MIN (date_time)
      INTO ld_ret
      FROM halfhour
     WHERE mid = an_mid AND date_time > ad_date
           AND (DECODE (an_ntype, 2, edm, 3, q1m, 4, q2m, 5, q3m, 6, q4m, erm) IS NOT NULL OR DECODE (an_ntype, 2, ed, 3, q1, 4, q2, 5, q3, 6, q4, er) IS NOT NULL);
   END IF;
  ELSIF an_table = 3 THEN   --PROFILE
   IF an_kind = 1 THEN   --Показаний
    SELECT MIN (date_time)
      INTO ld_ret
      FROM PROFILE
     WHERE mid = an_mid AND date_time > ad_date AND DECODE (an_ntype, 2, edm, 3, q1m, 4, q2m, 5, q3m, 6, q4m, erm) IS NOT NULL;
   ELSIF an_kind = 2 THEN   --Расхода
    SELECT MIN (date_time)
      INTO ld_ret
      FROM PROFILE
     WHERE mid = an_mid AND date_time > ad_date AND DECODE (an_ntype, 2, ed, 3, q1, 4, q2, 5, q3, 6, q4, er) IS NOT NULL;
   ELSE   --Записей
    SELECT MIN (date_time)
      INTO ld_ret
      FROM PROFILE
     WHERE mid = an_mid AND date_time > ad_date
           AND (DECODE (an_ntype, 2, edm, 3, q1m, 4, q2m, 5, q3m, 6, q4m, erm) IS NOT NULL OR DECODE (an_ntype, 2, ed, 3, q1, 4, q2, 5, q3, 6, q4, er) IS NOT NULL);
   END IF;
  ELSIF an_table IN (5, 6, 7, 8, 9) THEN   --BILLORG
   IF an_kind = 1 THEN   --Показаний
    SELECT MIN (date_time)
      INTO ld_ret
      FROM billorg
     WHERE mid = an_mid AND date_time > ad_date
           AND DECODE (an_zone,
                       1, DECODE (an_ntype, 2, aedm, 3, aq1m, 4, aq2m, 5, aq3m, 6, aq4m, aerm),
                       2, DECODE (an_ntype, 2, bedm, 3, bq1m, 4, bq2m, 5, bq3m, 6, bq4m, berm),
                       3, DECODE (an_ntype, 2, cedm, 3, cq1m, 4, cq2m, 5, cq3m, 6, cq4m, cerm),
                       4, DECODE (an_ntype, 2, dedm, 3, dq1m, 4, dq2m, 5, dq3m, 6, dq4m, derm),
                       DECODE (an_ntype, 2, edm, 3, q1m, 4, q2m, 5, q3m, 6, q4m, erm)
                      ) IS NOT NULL
           AND nsource <> 8;
   ELSIF an_kind = 2 THEN   --Расхода
    SELECT MIN (date_time)
      INTO ld_ret
      FROM billorg
     WHERE mid = an_mid AND date_time > ad_date
           AND DECODE (an_zone,
                       1, DECODE (an_ntype, 2, aed, 3, aq1, 4, aq2, 5, aq3, 6, aq4, aer),
                       2, DECODE (an_ntype, 2, bed, 3, bq1, 4, bq2, 5, bq3, 6, bq4, ber),
                       3, DECODE (an_ntype, 2, ced, 3, cq1, 4, cq2, 5, cq3, 6, cq4, cer),
                       4, DECODE (an_ntype, 2, ded, 3, dq1, 4, dq2, 5, dq3, 6, dq4, der),
                       DECODE (an_ntype, 2, ed, 3, q1, 4, q2, 5, q3, 6, q4, er)
                      ) IS NOT NULL
           AND nsource <> 8;
   ELSE   --Записей
    SELECT MIN (date_time)
      INTO ld_ret
      FROM billorg
     WHERE mid = an_mid AND date_time > ad_date
           AND (DECODE (an_zone,
                        1, DECODE (an_ntype, 2, aedm, 3, aq1m, 4, aq2m, 5, aq3m, 6, aq4m, aerm),
                        2, DECODE (an_ntype, 2, bedm, 3, bq1m, 4, bq2m, 5, bq3m, 6, bq4m, berm),
                        3, DECODE (an_ntype, 2, cedm, 3, cq1m, 4, cq2m, 5, cq3m, 6, cq4m, cerm),
                        4, DECODE (an_ntype, 2, dedm, 3, dq1m, 4, dq2m, 5, dq3m, 6, dq4m, derm),
                        DECODE (an_ntype, 2, edm, 3, q1m, 4, q2m, 5, q3m, 6, q4m, erm)
                       ) IS NOT NULL
                OR DECODE (an_zone,
                           1, DECODE (an_ntype, 2, aed, 3, aq1, 4, aq2, 5, aq3, 6, aq4, aer),
                           2, DECODE (an_ntype, 2, bed, 3, bq1, 4, bq2, 5, bq3, 6, bq4, ber),
                           3, DECODE (an_ntype, 2, ced, 3, cq1, 4, cq2, 5, cq3, 6, cq4, cer),
                           4, DECODE (an_ntype, 2, ded, 3, dq1, 4, dq2, 5, dq3, 6, dq4, der),
                           DECODE (an_ntype, 2, ed, 3, q1, 4, q2, 5, q3, 6, q4, er)
                          ) IS NOT NULL
               );
   END IF;
  ELSE   ---MONTHSORG
   IF an_kind = 1 THEN   --Показаний
    SELECT MIN (date_time)
      INTO ld_ret
      FROM monthsorg
     WHERE mid = an_mid AND date_time > ad_date
           AND DECODE (an_zone,
                       1, DECODE (an_ntype, 2, aedm, 3, aq1m, 4, aq2m, 5, aq3m, 6, aq4m, aerm),
                       2, DECODE (an_ntype, 2, bedm, 3, bq1m, 4, bq2m, 5, bq3m, 6, bq4m, berm),
                       3, DECODE (an_ntype, 2, cedm, 3, cq1m, 4, cq2m, 5, cq3m, 6, cq4m, cerm),
                       4, DECODE (an_ntype, 2, dedm, 3, dq1m, 4, dq2m, 5, dq3m, 6, dq4m, derm),
                       DECODE (an_ntype, 2, edm, 3, q1m, 4, q2m, 5, q3m, 6, q4m, erm)
                      ) IS NOT NULL;
   ELSIF an_kind = 2 THEN   --Расхода
    SELECT MIN (date_time)
      INTO ld_ret
      FROM monthsorg
     WHERE mid = an_mid AND date_time > ad_date
           AND DECODE (an_zone,
                       1, DECODE (an_ntype, 2, aed, 3, aq1, 4, aq2, 5, aq3, 6, aq4, aer),
                       2, DECODE (an_ntype, 2, bed, 3, bq1, 4, bq2, 5, bq3, 6, bq4, ber),
                       3, DECODE (an_ntype, 2, ced, 3, cq1, 4, cq2, 5, cq3, 6, cq4, cer),
                       4, DECODE (an_ntype, 2, ded, 3, dq1, 4, dq2, 5, dq3, 6, dq4, der),
                       DECODE (an_ntype, 2, ed, 3, q1, 4, q2, 5, q3, 6, q4, er)
                      ) IS NOT NULL;
   ELSE   --Записей
    SELECT MIN (date_time)
      INTO ld_ret
      FROM monthsorg
     WHERE mid = an_mid AND date_time > ad_date
           AND (DECODE (an_zone,
                        1, DECODE (an_ntype, 2, aedm, 3, aq1m, 4, aq2m, 5, aq3m, 6, aq4m, aerm),
                        2, DECODE (an_ntype, 2, bedm, 3, bq1m, 4, bq2m, 5, bq3m, 6, bq4m, berm),
                        3, DECODE (an_ntype, 2, cedm, 3, cq1m, 4, cq2m, 5, cq3m, 6, cq4m, cerm),
                        4, DECODE (an_ntype, 2, dedm, 3, dq1m, 4, dq2m, 5, dq3m, 6, dq4m, derm),
                        DECODE (an_ntype, 2, edm, 3, q1m, 4, q2m, 5, q3m, 6, q4m, erm)
                       ) IS NOT NULL
                OR DECODE (an_zone,
                           1, DECODE (an_ntype, 2, aed, 3, aq1, 4, aq2, 5, aq3, 6, aq4, aer),
                           2, DECODE (an_ntype, 2, bed, 3, bq1, 4, bq2, 5, bq3, 6, bq4, ber),
                           3, DECODE (an_ntype, 2, ced, 3, cq1, 4, cq2, 5, cq3, 6, cq4, cer),
                           4, DECODE (an_ntype, 2, ded, 3, dq1, 4, dq2, 5, dq3, 6, dq4, der),
                           DECODE (an_ntype, 2, ed, 3, q1, 4, q2, 5, q3, 6, q4, er)
                          ) IS NOT NULL
               );
   END IF;
  END IF;

  RETURN ld_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Последние показания
 FUNCTION getlastindic (an_mid NUMBER, ad_date DATE, an_ntype NUMBER, an_zone NUMBER, an_table NUMBER)   -- an_table =1 BILL,=2 HALFHOUR,=3 PROFILE иначе MONTHSORG
  RETURN NUMBER IS
  ln_ret    NUMBER;
  ld_date   DATE;
 BEGIN
  ld_date := getlastdate (an_mid, ad_date, an_ntype, NULL /*an_zone*/, an_table, 1);

  IF ld_date IS NULL THEN
   RETURN NULL;
  END IF;

  IF an_table = 1 THEN   --BILL
   SELECT DECODE (an_zone,
                  1, DECODE (an_ntype, 2, aedm, 3, aq1m, 4, aq2m, 5, aq3m, 6, aq4m, aerm),
                  2, DECODE (an_ntype, 2, bedm, 3, bq1m, 4, bq2m, 5, bq3m, 6, bq4m, berm),
                  3, DECODE (an_ntype, 2, cedm, 3, cq1m, 4, cq2m, 5, cq3m, 6, cq4m, cerm),
                  4, DECODE (an_ntype, 2, dedm, 3, dq1m, 4, dq2m, 5, dq3m, 6, dq4m, derm),
                  DECODE (an_ntype, 2, edm, 3, q1m, 4, q2m, 5, q3m, 6, q4m, erm)
                 )
     INTO ln_ret
     FROM bill
    WHERE mid = an_mid AND date_time = ld_date;
  ELSIF an_table IN (5, 6, 7, 8, 9) THEN   --BILLORG
   SELECT DECODE (an_zone,
                  1, DECODE (an_ntype, 2, aedm, 3, aq1m, 4, aq2m, 5, aq3m, 6, aq4m, aerm),
                  2, DECODE (an_ntype, 2, bedm, 3, bq1m, 4, bq2m, 5, bq3m, 6, bq4m, berm),
                  3, DECODE (an_ntype, 2, cedm, 3, cq1m, 4, cq2m, 5, cq3m, 6, cq4m, cerm),
                  4, DECODE (an_ntype, 2, dedm, 3, dq1m, 4, dq2m, 5, dq3m, 6, dq4m, derm),
                  DECODE (an_ntype, 2, edm, 3, q1m, 4, q2m, 5, q3m, 6, q4m, erm)
                 )
     INTO ln_ret
     FROM billorg
    WHERE mid = an_mid AND date_time = ld_date AND NVL (nsource, 0) = (SELECT NVL (MAX (nsource), 0)
                                                                         FROM billorg
                                                                        WHERE mid = an_mid AND date_time = ld_date);
  ELSIF an_table = 2 THEN   --HALFHOUR
   SELECT DECODE (an_ntype, 2, edm, 3, q1m, 4, q2m, 5, q3m, 6, q4m, erm)
     INTO ln_ret
     FROM halfhour
    WHERE mid = an_mid AND date_time = ld_date AND ROWNUM = 1;
  --chig
  ELSIF an_table = man_inp_hhour_code THEN   --MAN_INP_HHOUR
   SELECT DECODE (an_ntype, 2, edm, 3, q1m, 4, q2m, 5, q3m, 6, q4m, erm)
     INTO ln_ret
     FROM man_inp_hhour
    WHERE mid = an_mid AND date_time = ld_date;
  --e chig
  ELSIF an_table = 3 THEN   --PROFILE
   SELECT DECODE (an_ntype, 2, edm, 3, q1m, 4, q2m, 5, q3m, 6, q4m, erm)
     INTO ln_ret
     FROM PROFILE
    WHERE mid = an_mid AND date_time = ld_date;
  ELSE   --MONTHSORG
   SELECT DECODE (an_zone,
                  1, DECODE (an_ntype, 2, aedm, 3, aq1m, 4, aq2m, 5, aq3m, 6, aq4m, aerm),
                  2, DECODE (an_ntype, 2, bedm, 3, bq1m, 4, bq2m, 5, bq3m, 6, bq4m, berm),
                  3, DECODE (an_ntype, 2, cedm, 3, cq1m, 4, cq2m, 5, cq3m, 6, cq4m, cerm),
                  4, DECODE (an_ntype, 2, dedm, 3, dq1m, 4, dq2m, 5, dq3m, 6, dq4m, derm),
                  DECODE (an_ntype, 2, edm, 3, q1m, 4, q2m, 5, q3m, 6, q4m, erm)
                 )
     INTO ln_ret
     FROM monthsorg
    WHERE mid = an_mid AND date_time = ld_date;
  END IF;

  RETURN ln_ret;
 END;

