  ELSIF an_table = 3 THEN   --PROFILE
   SELECT DECODE (an_ntype, 2, ed, 3, q1, 4, q2, 5, q3, 6, q4, er)
     INTO ln_ret
     FROM PROFILE
    WHERE mid = an_mid AND date_time = ld_date;
  ELSE   --MONTHSORG
   SELECT DECODE (an_zone,
                  1, DECODE (an_ntype, 2, aed, 3, aq1, 4, aq2, 5, aq3, 6, aq4, aer),
