------------------------------------------------------------------------------------------------------------------------
--Ins Upd Del показаний короткая
 PROCEDURE setindic (an_mid NUMBER, ad_date DATE, an_ntype NUMBER, an_table NUMBER,   -- an_table =1 BILL,=2 HALFHOUR,=3 PROFILE иначе MONTHSORG
                                                                                   an_needupdlast NUMBER,   -- needupdlast=1, если в случае Upd производит Upd следующего расхода
 av_source VARCHAR2, av_remark VARCHAR2, av_mtrsn VARCHAR2, an_kc NUMBER, an_rm NUMBER,   --показания
                                                                                       an_r NUMBER   --расход
 ) IS
  ln_rm             NUMBER          DEFAULT ROUND (an_rm, gn_1);
  ln_r              NUMBER          DEFAULT ROUND (an_r, gn_2);
  ln_next_rm        NUMBER;   --Следующие показания
  ln_next_r         NUMBER;   --Следующие расход
  ld_next_rm        DATE;   --Дата следующих показаний
  ln_dig            NUMBER;
  ln_handle         INTEGER;
  ln_ret            NUMBER;
  lv_sqlupd         VARCHAR2 (2000) DEFAULT 'UPDATE ';
  lv_sqlins         VARCHAR2 (2000) DEFAULT 'INSERT INTO ';
  lv_table          VARCHAR2 (30);
  lb_det            BOOLEAN         DEFAULT TRUE;
  lv_add            VARCHAR2 (10);
  lv_kc             VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (an_kc), 'NULL');
  lv_rm             VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (ROUND (an_rm, gn_1)), 'NULL');
  lv_r              VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (ROUND (an_r, gn_2)), 'NULL');
  ln_ptype          NUMBER          := 0;
  ln_lockhalfhour   NUMBER          DEFAULT util_pg.getparamvalue_f (32);
 BEGIN
  IF an_table = 1 THEN
   gn_task_code := 204;
  ELSIF an_table = 2 THEN
   gn_task_code := 604;
  ELSIF an_table = 5 THEN
   gn_task_code := 608;
  ELSIF an_table = 6 THEN
   gn_task_code := 611;
  ELSIF an_table = 7 THEN
   gn_task_code := 614;
  ELSIF an_table = 8 THEN
   gn_task_code := 615;
  ELSIF an_table = 9 THEN
   gn_task_code := 621;
  ELSIF an_table = 13 THEN
   gn_task_code := 605;
  END IF;

  SAVEPOINT setindic_s_sp;

  SELECT NVL (ncalcpointtype, 0)
    INTO ln_ptype
    FROM feeders
   WHERE mid = an_mid;   -- KAS

  IF ln_ptype = 3 THEN
   setindicdiff (an_mid, ad_date, an_ntype, av_source, av_remark, av_mtrsn, an_kc, an_rm, an_r);
  ELSE
   ln_handle := SYS.DBMS_SQL.open_cursor;

   IF an_table = 1 THEN
    lv_table := 'BILL';
   ELSIF an_table IN (5, 6, 7, 8, 9) THEN
    lv_table := 'BILLORG';
   ELSIF an_table = 2 THEN
    lv_table := 'HALFHOUR';
    lb_det := FALSE;
   --chig
   ELSIF an_table = man_inp_hhour_code THEN
    lv_table := 'MAN_INP_HHOUR';
    lb_det := FALSE;
   --e
   ELSIF an_table = 3 THEN
    lv_table := 'PROFILE';
    lb_det := FALSE;
   ELSE
    lv_table := 'MONTHSORG';
   END IF;

   IF an_ntype = 2 THEN
    lv_add := 'ed';
   ELSIF an_ntype = 3 THEN
    lv_add := 'q1';
   ELSIF an_ntype = 4 THEN
    lv_add := 'q2';
   ELSIF an_ntype = 5 THEN
    lv_add := 'q3';
   ELSIF an_ntype = 6 THEN
    lv_add := 'q4';
   ELSE
    lv_add := 'er';
   END IF;

   --chig
   IF an_table = man_inp_hhour_code THEN
    lv_sqlins :=
     lv_sqlins || lv_table || '(mid,date_time,' || lv_add || 'm,' || lv_add || ') VALUES(' || an_mid || ',to_date(' || TO_CHAR (ad_date, 'YYYYMMDDHH24MISS')
     || ',''YYYYMMDDHH24MISS''),' || lv_rm || ',' || lv_r || ')';
    lv_sqlupd :=
     lv_sqlupd || lv_table || ' SET ' || lv_add || 'm=' || lv_rm || ',' || lv_add || '=' || lv_r || ',' || 'date_time=to_date('
     || TO_CHAR (ad_date, 'YYYYMMDDHH24MISS') || ',''YYYYMMDDHH24MISS'')' || ' where mid=' || an_mid;

    BEGIN
     --Попытка выполнить всавку
     SAVEPOINT do_insert;
     SYS.DBMS_SQL.parse (ln_handle, lv_sqlins, SYS.DBMS_SQL.native);
     ln_ret := SYS.DBMS_SQL.EXECUTE (ln_handle);
    --e Попытка выполнить всавку
    EXCEPTION
     WHEN DUP_VAL_ON_INDEX THEN
      ROLLBACK TO do_insert;
      SYS.DBMS_SQL.parse (ln_handle, lv_sqlupd, SYS.DBMS_SQL.native);
      ln_ret := SYS.DBMS_SQL.EXECUTE (ln_handle);
    END;
   ELSE
    --e chig
    IF an_table = 2 THEN   --HALFHOUR
     lv_sqlupd :=
      lv_sqlupd || lv_table || ' SET ' || lv_add || 'm=' || lv_rm || ',' || lv_add || '=' || lv_r || ', NKC=' || lv_kc || ' where mid=' || an_mid
      || ' and date_time=to_date(' || TO_CHAR (ad_date, 'YYYYMMDDHH24MISS') || ',''YYYYMMDDHH24MISS'')';
     lv_sqlins :=
      lv_sqlins || lv_table || '(mid,date_time,' || lv_add || 'm,' || lv_add || ',NKC) VALUES(' || an_mid || ',to_date(' || TO_CHAR (ad_date, 'YYYYMMDDHH24MISS')
      || ',''YYYYMMDDHH24MISS''),' || lv_rm || ',' || lv_r || ',' || lv_kc || ')';
    ELSIF lb_det THEN
     lv_sqlupd :=
      lv_sqlupd || lv_table || ' SET ' || 'source=' || '''' || av_source || ''',' || 'remark=' || '''' || av_remark || ''',' || lv_add || '_MTRSN=''' || av_mtrsn
      || ''',' || lv_add || '_KC=' || lv_kc || ',' || lv_add || 'm=' || lv_rm || ',' || lv_add || '=' || lv_r || ' where mid=' || an_mid
      || ' and date_time=to_date(' || TO_CHAR (ad_date, 'YYYYMMDDHH24MISS') || ',''YYYYMMDDHH24MISS'')';
     lv_sqlins :=
      lv_sqlins || lv_table || '(mid,date_time,' || 'source,remark,' || lv_add || '_MTRSN,' || lv_add || '_KC,' || lv_add || 'm,' || lv_add || ') VALUES(' || an_mid
      || ',to_date(' || TO_CHAR (ad_date, 'YYYYMMDDHH24MISS') || ',''YYYYMMDDHH24MISS''),' || '''' || av_source || ''',''' || av_remark || ''',''' || av_mtrsn
      || ''',' || lv_kc || ',' || lv_rm || ',' || lv_r || ')';
    ELSE
     lv_sqlupd :=
      lv_sqlupd || lv_table || ' SET ' || lv_add || 'm=' || lv_rm || ',' || lv_add || '=' || lv_r || ' where mid=' || an_mid || ' and date_time=to_date('
      || TO_CHAR (ad_date, 'YYYYMMDDHH24MISS') || ',''YYYYMMDDHH24MISS'')';
     lv_sqlins :=
      lv_sqlins || lv_table || '(mid,date_time,' || lv_add || 'm,' || lv_add || ') VALUES(' || an_mid || ',to_date(' || TO_CHAR (ad_date, 'YYYYMMDDHH24MISS')
      || ',''YYYYMMDDHH24MISS''),' || lv_rm || ',' || lv_r || ')';
    END IF;

    SYS.DBMS_SQL.parse (ln_handle, lv_sqlupd, SYS.DBMS_SQL.native);

    IF SYS.DBMS_SQL.EXECUTE (ln_handle) = 0 THEN   --UPDATE не удался, значит INSERT
     SYS.DBMS_SQL.parse (ln_handle, lv_sqlins, SYS.DBMS_SQL.native);
     ln_ret := SYS.DBMS_SQL.EXECUTE (ln_handle);
    END IF;

    IF an_table IN (5, 6, 7, 8, 9) THEN
     BEGIN
      SAVEPOINT try_halfhour;
      calc_hh24 (an_mid, an_table, 1, ad_date, an_ntype, an_r);
     EXCEPTION
      WHEN OTHERS THEN
       IF SQLCODE < -20000 AND ln_lockhalfhour = 1 THEN
        ROLLBACK TO SAVEPOINT try_halfhour;
       ELSE
        RAISE;
       END IF;
     END;
    END IF;

    IF an_needupdlast = 1 THEN   --Необходимо Upd  следующих показаний
     ld_next_rm := getnextdate (an_mid, ad_date, an_ntype, NULL /*an_zone*/, an_table, 1);   --Дата след показаний

     IF ld_next_rm IS NOT NULL THEN   --Есть следующие показания
      ln_next_rm := getlastindic (an_mid, ld_next_rm + 1 / (24 * 60 * 60), an_ntype, NULL, an_table);   --Следующие показания (вычисляем как предыдущие, для их даты+ 1 сек)

      IF ln_rm IS NULL THEN   --Если текущие удалили, то для следующих предидущими будут предидущие от текущих
       ln_rm := getlastindic (an_mid, ad_date, an_ntype, NULL, an_table);
      END IF;

      IF ln_rm IS NOT NULL THEN   --Замечу, что уже ln_rm is not null и ln_next_rm is not null
       IF ln_next_rm >= ln_rm THEN
        ln_next_r := (ln_next_rm - ln_rm) * NVL (an_kc, 1);
       ELSE
        SELECT MAX (digits)
          INTO ln_dig
          FROM meters
         WHERE mid = an_mid AND DECODE (entype, 7, an_ntype, entype) = an_ntype;

        ln_dig := POWER (10, LENGTH (TRUNC (ln_dig)));

        IF ln_dig IS NULL OR ln_dig <= ln_rm THEN
         ln_dig := POWER (10, LENGTH (TRUNC (ln_rm)));
        END IF;

        ln_next_r := (ln_dig + ln_next_rm - ln_rm) * NVL (an_kc, 1);
       END IF;
      END IF;

      setdebit (an_mid, ld_next_rm, an_ntype, an_table, av_source, av_remark, av_mtrsn, an_kc, ln_next_r);
     END IF;
    END IF;
   --chig
   END IF;

   --e
   SYS.DBMS_SQL.close_cursor (ln_handle);

   IF an_table = 2 THEN   --HALFHOUR
    das_pg.calcpoint4bill (an_mid, ad_date, ad_date);
   END IF;
  END IF;

  admin_pg.fiscal_p (gn_task_code, 1,
                          'Произведен ввод показаний по точке ' || util_pg.node_path_f (an_mid, 'points', 'mid', 'parent') || ' на '
                          || TO_CHAR (ad_date, 'dd.mm.yyyy hh24:mi:ss'));
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT setindic_s_sp;

   IF SYS.DBMS_SQL.is_open (ln_handle) THEN
    SYS.DBMS_SQL.close_cursor (ln_handle);
   END IF;

   raise_application_error (-20001, 'indic_pg.setindic: Ошибка вставки показаний. ' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
--Ins Upd Del показаний длинная (зоны)
-- Показания всегда пишутся в BILLORG, а расходы в HALFHOUROLD
 PROCEDURE setindic (an_mid NUMBER, ad_date DATE, an_ntype NUMBER, an_table NUMBER,   --  an_table =1 BILL,=2 HALFHOUR,=3 PROFILE иначе MONTHSORG
                                                                                   an_needupdlast NUMBER,   -- needupdlast=1, если в случае Upd производит Upd следующего расхода
 av_source VARCHAR2, av_remark VARCHAR2, av_mtrsn VARCHAR2, an_kc NUMBER, an_rm NUMBER,   --показания
                                                                                       an_arm NUMBER,   --показания 1 зона
                                                                                                     an_brm NUMBER, an_crm NUMBER, an_drm NUMBER, an_r NUMBER,   --расход
 an_ar NUMBER,   --расход 1 зона
              an_br NUMBER, an_cr NUMBER, an_dr NUMBER
 ) IS
  ln_rm         NUMBER          DEFAULT ROUND (an_rm, gn_1);
  ln_r          NUMBER          DEFAULT ROUND (an_r, gn_2);
  ln_arm        NUMBER          DEFAULT ROUND (an_arm, gn_1);
  ln_ar         NUMBER          DEFAULT ROUND (an_ar, gn_2);
  ln_brm        NUMBER          DEFAULT ROUND (an_brm, gn_1);
  ln_br         NUMBER          DEFAULT ROUND (an_br, gn_2);
  ln_crm        NUMBER          DEFAULT ROUND (an_crm, gn_1);
  ln_cr         NUMBER          DEFAULT ROUND (an_cr, gn_2);
  ln_drm        NUMBER          DEFAULT ROUND (an_drm, gn_1);
  ln_dr         NUMBER          DEFAULT ROUND (an_dr, gn_2);
  ln_next_rm    NUMBER;   --Следующие показания
  ln_next_r     NUMBER;   --Следующие расход
  ln_next_arm   NUMBER;   --Следующие показания a
  ln_next_ar    NUMBER;   --Следующие расход a
  ln_next_brm   NUMBER;   --Следующие показания b
  ln_next_br    NUMBER;   --Следующие расход b
  ln_next_crm   NUMBER;   --Следующие показания c
  ln_next_cr    NUMBER;   --Следующие расход c
  ln_next_drm   NUMBER;   --Следующие показания d
  ln_next_dr    NUMBER;   --Следующие расход d
  ld_next_rm    DATE;   --Дата следующих показаний
  ln_dig        NUMBER;
  ln_handle     INTEGER;
  ln_ret        NUMBER;
  lv_sqlupd     VARCHAR2 (2000) DEFAULT 'UPDATE ';
  lv_sqlins     VARCHAR2 (2000) DEFAULT 'INSERT INTO ';
  lv_table      VARCHAR2 (30);
  lv_add        VARCHAR2 (10);
  lv_kc         VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (an_kc), 'NULL');
  lv_rm         VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (ROUND (an_rm, gn_1)), 'NULL');
  lv_r          VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (ROUND (an_r, gn_2)), 'NULL');
  lv_arm        VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (ROUND (an_arm, gn_1)), 'NULL');
  lv_ar         VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (ROUND (an_ar, gn_2)), 'NULL');
  lv_brm        VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (ROUND (an_brm, gn_1)), 'NULL');
  lv_br         VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (ROUND (an_br, gn_2)), 'NULL');
  lv_crm        VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (ROUND (an_crm, gn_1)), 'NULL');
  lv_cr         VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (ROUND (an_cr, gn_2)), 'NULL');
  lv_drm        VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (ROUND (an_drm, gn_1)), 'NULL');
  lv_dr         VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (ROUND (an_dr, gn_2)), 'NULL');
 BEGIN
  gn_task_code := 200;
  SAVEPOINT setindic_l_sp;

  IF an_table IN (2, 3) THEN   --Если HALFHOUR или PROFILE то вызываем короткую процедуру
   setindic (an_mid, ad_date, an_ntype, an_table, an_needupdlast, av_source, av_remark, av_mtrsn, an_kc, an_rm, an_r);
   RETURN;
  END IF;

  ln_handle := SYS.DBMS_SQL.open_cursor;

  IF an_table = 1 THEN
   lv_table := 'BILL';
  ELSIF an_table IN (5, 6, 7, 8, 9) THEN
   lv_table := 'BILLORG';
  ELSE
   lv_table := 'MONTHSORG';
  END IF;

  IF an_ntype = 2 THEN
   lv_add := 'ed';
  ELSIF an_ntype = 3 THEN
   lv_add := 'q1';
  ELSIF an_ntype = 4 THEN
   lv_add := 'q2';
  ELSIF an_ntype = 5 THEN
   lv_add := 'q3';
  ELSIF an_ntype = 6 THEN
   lv_add := 'q4';
  ELSE
   lv_add := 'er';
  END IF;

  lv_sqlupd :=
   lv_sqlupd || lv_table || ' SET ' || 'source=' || '''' || av_source || ''',' || 'remark=' || '''' || av_remark || ''',' || lv_add || '_MTRSN=''' || av_mtrsn
   || ''',' || lv_add || '_KC=' || lv_kc || ',' || lv_add || 'm=' || lv_rm || ',' || lv_add || '=' || lv_r || ',a' || lv_add || 'm=' || lv_arm || ',a' || lv_add
   || '=' || lv_ar || ',b' || lv_add || 'm=' || lv_brm || ',b' || lv_add || '=' || lv_br || ',c' || lv_add || 'm=' || lv_crm || ',c' || lv_add || '=' || lv_cr
   || ',d' || lv_add || 'm=' || lv_drm || ',d' || lv_add || '=' || lv_dr || ' where mid=' || an_mid || ' and date_time=to_date('
   || TO_CHAR (ad_date, 'YYYYMMDDHH24MISS') || ',''YYYYMMDDHH24MISS'')';
  lv_sqlins :=
   lv_sqlins || lv_table || '(mid,date_time,' || 'source,remark,' || lv_add || '_MTRSN,' || lv_add || '_KC,' || lv_add || 'm,' || lv_add || ',a' || lv_add || 'm,a'
   || lv_add || ',b' || lv_add || 'm,b' || lv_add || ',c' || lv_add || 'm,c' || lv_add || ',d' || lv_add || 'm,d' || lv_add || ') VALUES(' || an_mid || ',to_date('
   || TO_CHAR (ad_date, 'YYYYMMDDHH24MISS') || ',''YYYYMMDDHH24MISS''),' || '''' || av_source || ''',''' || av_remark || ''',''' || av_mtrsn || ''',' || lv_kc || ','
   || lv_rm || ',' || lv_r || ',' || lv_arm || ',' || lv_ar || ',' || lv_brm || ',' || lv_br || ',' || lv_crm || ',' || lv_cr || ',' || lv_drm || ',' || lv_dr || ')';
  SYS.DBMS_SQL.parse (ln_handle, lv_sqlupd, SYS.DBMS_SQL.native);

  IF SYS.DBMS_SQL.EXECUTE (ln_handle) = 0 THEN   --UPDATE не удался, значит INSERT
   SYS.DBMS_SQL.parse (ln_handle, lv_sqlins, SYS.DBMS_SQL.native);
   ln_ret := SYS.DBMS_SQL.EXECUTE (ln_handle);
  END IF;


  IF an_needupdlast = 1 THEN   --Необходимо Upd  следующих показаний
   ld_next_rm := getnextdate (an_mid, ad_date, an_ntype, NULL /*an_zone*/, an_table, 1);   --Дата след показаний

   IF ld_next_rm IS NOT NULL THEN   --Есть следующие показания
    ln_next_rm := getlastindic (an_mid, ld_next_rm + 1 / (24 * 60 * 60), an_ntype, NULL, an_table);   --Следующие показания (вычисляем как предыдущие, для их даты+ 1 сек)
    ln_next_arm := getlastindic (an_mid, ld_next_rm + 1 / (24 * 60 * 60), an_ntype, 1, an_table);   --Следующие показания (вычисляем как предыдущие, для их даты+ 1 сек)
    ln_next_brm := getlastindic (an_mid, ld_next_rm + 1 / (24 * 60 * 60), an_ntype, 2, an_table);   --Следующие показания (вычисляем как предыдущие, для их даты+ 1 сек)
    ln_next_crm := getlastindic (an_mid, ld_next_rm + 1 / (24 * 60 * 60), an_ntype, 3, an_table);   --Следующие показания (вычисляем как предыдущие, для их даты+ 1 сек)
    ln_next_drm := getlastindic (an_mid, ld_next_rm + 1 / (24 * 60 * 60), an_ntype, 4, an_table);   --Следующие показания (вычисляем как предыдущие, для их даты+ 1 сек)

    IF ln_rm IS NULL THEN   --Если текущие удалили, то для следующих предидущими будут предидущие от текущих
     ln_rm := getlastindic (an_mid, ad_date, an_ntype, NULL, an_table);
     ln_arm := getlastindic (an_mid, ad_date, an_ntype, 1, an_table);
     ln_brm := getlastindic (an_mid, ad_date, an_ntype, 2, an_table);
     ln_crm := getlastindic (an_mid, ad_date, an_ntype, 3, an_table);
     ln_drm := getlastindic (an_mid, ad_date, an_ntype, 4, an_table);
    END IF;

    IF ln_rm IS NOT NULL THEN   --Замечу, что уже ln_rm is not null и ln_next_rm is not null
     SELECT MAX (digits)
       INTO ln_dig
       FROM meters
      WHERE mid = an_mid AND DECODE (entype, 7, an_ntype, entype) = an_ntype;

     ln_dig := POWER (10, LENGTH (TRUNC (ln_dig)));

     IF ln_dig IS NULL OR ln_dig <= ln_rm THEN
      ln_dig := POWER (10, LENGTH (TRUNC (ln_rm)));
     END IF;

     IF ln_next_rm >= ln_rm THEN
      ln_next_r := (ln_next_rm - ln_rm) * NVL (an_kc, 1);
     ELSE
      ln_next_r := (ln_dig + ln_next_rm - ln_rm) * NVL (an_kc, 1);
     END IF;

     IF ln_next_arm >= ln_arm THEN   --Зона A
      ln_next_ar := (ln_next_arm - ln_arm) * NVL (an_kc, 1);
     ELSE
      ln_next_ar := (ln_dig + ln_next_arm - ln_arm) * NVL (an_kc, 1);
     END IF;

     IF ln_next_brm >= ln_brm THEN   --Зона B
      ln_next_br := (ln_next_brm - ln_brm) * NVL (an_kc, 1);
     ELSE
      ln_next_br := (ln_dig + ln_next_brm - ln_brm) * NVL (an_kc, 1);
     END IF;

     IF ln_next_crm >= ln_crm THEN   --Зона C
      ln_next_cr := (ln_next_crm - ln_crm) * NVL (an_kc, 1);
     ELSE
      ln_next_cr := (ln_dig + ln_next_crm - ln_crm) * NVL (an_kc, 1);
     END IF;

     IF ln_next_drm >= ln_drm THEN   --Зона D
      ln_next_dr := (ln_next_drm - ln_drm) * NVL (an_kc, 1);
     ELSE
      ln_next_dr := (ln_dig + ln_next_drm - ln_drm) * NVL (an_kc, 1);
     END IF;
    END IF;

    IF ABS (NVL (ln_next_r, 0) - (NVL (ln_next_ar, 0) + NVL (ln_next_br, 0) + NVL (ln_next_cr, 0) + NVL (ln_next_dr, 0))) <= 4 THEN   --Разница в расходах <4
     setdebit (an_mid, ld_next_rm, an_ntype, an_table, av_source, av_remark, av_mtrsn, an_kc, ln_next_r, ln_next_ar, ln_next_br, ln_next_cr, ln_next_dr);
    ELSE   --Не трогаем зоны
     setdebit (an_mid, ld_next_rm, an_ntype, an_table, av_source, av_remark, av_mtrsn, an_kc, ln_next_r);
    END IF;
   END IF;
  END IF;

  SYS.DBMS_SQL.close_cursor (ln_handle);
  admin_pg.fiscal_p (gn_task_code, 1,
                          'Произведен ввод показаний по точке ' || util_pg.node_path_f (an_mid, 'points', 'mid', 'parent') || ' на '
                          || TO_CHAR (ad_date, 'dd.mm.yyyy hh24:mi:ss'));
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT setindic_l_sp;

   IF SYS.DBMS_SQL.is_open (ln_handle) THEN
    SYS.DBMS_SQL.close_cursor (ln_handle);
   END IF;

   raise_application_error (-20001, 'indic_pg.setindic: Ошибка вставки показаний. ' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
-- Самая последняя
--Ins Upd Del показаний длинная (зоны)
-- Показания всегда пишутся в BILLORG, а расходы в HALFHOUROLD
 PROCEDURE setindic (an_mid NUMBER, ad_date DATE, an_ntype NUMBER, av_source VARCHAR2, av_remark VARCHAR2, av_mtrsn VARCHAR2, an_kc NUMBER, an_rm NUMBER,   --показания
 an_arm NUMBER,   --показания 1 зона
               an_brm NUMBER, an_crm NUMBER, an_drm NUMBER, an_r NUMBER,   --расход
                                                                        an_ar NUMBER,   --расход 1 зона
                                                                                     an_br NUMBER, an_cr NUMBER, an_dr NUMBER
 ) IS
  ln_rm         NUMBER          DEFAULT ROUND (an_rm, gn_1);
  ln_r          NUMBER          DEFAULT ROUND (an_r, gn_2);
  ln_arm        NUMBER          DEFAULT ROUND (an_arm, gn_1);
  ln_ar         NUMBER          DEFAULT ROUND (an_ar, gn_2);
  ln_brm        NUMBER          DEFAULT ROUND (an_brm, gn_1);
  ln_br         NUMBER          DEFAULT ROUND (an_br, gn_2);
  ln_crm        NUMBER          DEFAULT ROUND (an_crm, gn_1);
  ln_cr         NUMBER          DEFAULT ROUND (an_cr, gn_2);
  ln_drm        NUMBER          DEFAULT ROUND (an_drm, gn_1);
  ln_dr         NUMBER          DEFAULT ROUND (an_dr, gn_2);
  ln_next_rm    NUMBER;   --Следующие показания
  ln_next_r     NUMBER;   --Следующие расход
  ln_next_arm   NUMBER;   --Следующие показания a
  ln_next_ar    NUMBER;   --Следующие расход a
  ln_next_brm   NUMBER;   --Следующие показания b
  ln_next_br    NUMBER;   --Следующие расход b
  ln_next_crm   NUMBER;   --Следующие показания c
  ln_next_cr    NUMBER;   --Следующие расход c
  ln_next_drm   NUMBER;   --Следующие показания d
  ln_next_dr    NUMBER;   --Следующие расход d
  ld_next_rm    DATE            DEFAULT NULL;   --Дата следующих показаний
  ln_dig        NUMBER;
  ln_handle     INTEGER;
  ln_ret        NUMBER;
  lv_sqlupd     VARCHAR2 (2000) DEFAULT 'UPDATE ';
  lv_sqlins     VARCHAR2 (2000) DEFAULT 'INSERT INTO ';
  lv_table      VARCHAR2 (30);
  lv_add        VARCHAR2 (10);
  lv_kc         VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (an_kc), 'NULL');
  lv_rm         VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (ROUND (an_rm, gn_1)), 'NULL');
  lv_r          VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (ROUND (an_r, gn_2)), 'NULL');
  lv_arm        VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (ROUND (an_arm, gn_1)), 'NULL');
  lv_ar         VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (ROUND (an_ar, gn_2)), 'NULL');
  lv_brm        VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (ROUND (an_brm, gn_1)), 'NULL');
  lv_br         VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (ROUND (an_br, gn_2)), 'NULL');
  lv_crm        VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (ROUND (an_crm, gn_1)), 'NULL');
  lv_cr         VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (ROUND (an_cr, gn_2)), 'NULL');
  lv_drm        VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (ROUND (an_drm, gn_1)), 'NULL');
  lv_dr         VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (ROUND (an_dr, gn_2)), 'NULL');
  an_table      NUMBER          := 5;
  ld_last_rm    DATE            DEFAULT NULL;   --Дата предыдущих показаний
 BEGIN
  lv_table := 'BILLORG';
  gn_task_code := 200;
  SAVEPOINT setindic_l_sp;
  ln_handle := SYS.DBMS_SQL.open_cursor;

  IF an_ntype = 2 THEN
   lv_add := 'ed';
  ELSIF an_ntype = 3 THEN
   lv_add := 'q1';
  ELSIF an_ntype = 4 THEN
   lv_add := 'q2';
  ELSIF an_ntype = 5 THEN
   lv_add := 'q3';
  ELSIF an_ntype = 6 THEN
   lv_add := 'q4';
  ELSE
   lv_add := 'er';
  END IF;

  lv_sqlupd :=
   lv_sqlupd || lv_table || ' SET ' || 'source=' || '''' || av_source || ''',' || 'remark=' || '''' || av_remark || ''',' || lv_add || '_MTRSN=''' || av_mtrsn
   || ''',' || lv_add || '_KC=' || lv_kc || ',' || lv_add || 'm=' || lv_rm || ',' || lv_add || '=' || lv_r || ',a' || lv_add || 'm=' || lv_arm || ',a' || lv_add
   || '=' || lv_ar || ',b' || lv_add || 'm=' || lv_brm || ',b' || lv_add || '=' || lv_br || ',c' || lv_add || 'm=' || lv_crm || ',c' || lv_add || '=' || lv_cr
   || ',d' || lv_add || 'm=' || lv_drm || ',d' || lv_add || '=' || lv_dr || ' where mid=' || an_mid || ' and date_time=to_date('
   || TO_CHAR (ad_date, 'YYYYMMDDHH24MISS') || ',''YYYYMMDDHH24MISS'')';
  lv_sqlins :=
   lv_sqlins || lv_table || '(mid,date_time,' || 'source,remark,' || lv_add || '_MTRSN,' || lv_add || '_KC,' || lv_add || 'm,' || lv_add || ',a' || lv_add || 'm,a'
   || lv_add || ',b' || lv_add || 'm,b' || lv_add || ',c' || lv_add || 'm,c' || lv_add || ',d' || lv_add || 'm,d' || lv_add || ') VALUES(' || an_mid || ',to_date('
   || TO_CHAR (ad_date, 'YYYYMMDDHH24MISS') || ',''YYYYMMDDHH24MISS''),' || '''' || av_source || ''',''' || av_remark || ''',''' || av_mtrsn || ''',' || lv_kc || ','
   || lv_rm || ',' || lv_r || ',' || lv_arm || ',' || lv_ar || ',' || lv_brm || ',' || lv_br || ',' || lv_crm || ',' || lv_cr || ',' || lv_drm || ',' || lv_dr || ')';
  SYS.DBMS_SQL.parse (ln_handle, lv_sqlupd, SYS.DBMS_SQL.native);

  IF SYS.DBMS_SQL.EXECUTE (ln_handle) = 0 THEN   --UPDATE не удался, значит INSERT
   SYS.DBMS_SQL.parse (ln_handle, lv_sqlins, SYS.DBMS_SQL.native);
   ln_ret := SYS.DBMS_SQL.EXECUTE (ln_handle);
  END IF;

  ld_next_rm := getnextdate (an_mid, ad_date, an_ntype, NULL /*an_zone*/, an_table, 1);   --Дата след показаний
  ld_last_rm := getlastdate (an_mid, ad_date, an_ntype, NULL /*an_zone*/, an_table, 1);   --Дата пред показаний
  -- вставляем расходы в получасовки
  -- С предыдущей по текущую
  sethalfhouroldzone (an_mid, ld_last_rm, ad_date, an_ntype, av_source, av_mtrsn, an_kc, an_r, an_ar, an_br, an_cr, an_dr);

  IF ld_next_rm IS NOT NULL THEN   -- Если есть следующие показания то получаем их
   ln_next_rm := getlastindic (an_mid, ld_next_rm + 1 / (24 * 60 * 60), an_ntype, NULL, an_table);   --Следующие показания (вычисляем как предыдущие, для их даты+ 1 сек)
   ln_next_arm := getlastindic (an_mid, ld_next_rm + 1 / (24 * 60 * 60), an_ntype, 1, an_table);   --Следующие показания (вычисляем как предыдущие, для их даты+ 1 сек)
   ln_next_brm := getlastindic (an_mid, ld_next_rm + 1 / (24 * 60 * 60), an_ntype, 2, an_table);   --Следующие показания (вычисляем как предыдущие, для их даты+ 1 сек)
   ln_next_crm := getlastindic (an_mid, ld_next_rm + 1 / (24 * 60 * 60), an_ntype, 3, an_table);   --Следующие показания (вычисляем как предыдущие, для их даты+ 1 сек)
   ln_next_drm := getlastindic (an_mid, ld_next_rm + 1 / (24 * 60 * 60), an_ntype, 4, an_table);   --Следующие показания (вычисляем как предыдущие, для их даты+ 1 сек)

   --    DELETE FROM halfhourold WHERE mid = an_mid AND date_time
   IF ln_rm IS NULL THEN   --Если текущие удалили, то для следующих предидущими будут предидущие от текущих
    ln_rm := getlastindic (an_mid, ad_date, an_ntype, NULL, an_table);
    ln_arm := getlastindic (an_mid, ad_date, an_ntype, 1, an_table);
    ln_brm := getlastindic (an_mid, ad_date, an_ntype, 2, an_table);
    ln_crm := getlastindic (an_mid, ad_date, an_ntype, 3, an_table);
    ln_drm := getlastindic (an_mid, ad_date, an_ntype, 4, an_table);
   END IF;

   IF ln_rm IS NOT NULL THEN   --Замечу, что уже ln_rm is not null и ln_next_rm is not null
    SELECT MAX (digits)
      INTO ln_dig
      FROM meters
     WHERE mid = an_mid AND DECODE (entype, 7, an_ntype, entype) = an_ntype;

    ln_dig := POWER (10, LENGTH (TRUNC (ln_dig)));

    IF ln_dig IS NULL OR ln_dig <= ln_rm THEN
     ln_dig := POWER (10, LENGTH (TRUNC (ln_rm)));
    END IF;

    IF ln_next_rm >= ln_rm THEN
     ln_next_r := (ln_next_rm - ln_rm) * NVL (an_kc, 1);
    ELSE
     ln_next_r := (ln_dig + ln_next_rm - ln_rm) * NVL (an_kc, 1);
    END IF;

    IF ln_next_arm >= ln_arm THEN   --Зона A
     ln_next_ar := (ln_next_arm - ln_arm) * NVL (an_kc, 1);
    ELSE
     ln_next_ar := (ln_dig + ln_next_arm - ln_arm) * NVL (an_kc, 1);
    END IF;

    IF ln_next_brm >= ln_brm THEN   --Зона B
     ln_next_br := (ln_next_brm - ln_brm) * NVL (an_kc, 1);
    ELSE
     ln_next_br := (ln_dig + ln_next_brm - ln_brm) * NVL (an_kc, 1);
    END IF;

    IF ln_next_crm >= ln_crm THEN   --Зона C
     ln_next_cr := (ln_next_crm - ln_crm) * NVL (an_kc, 1);
    ELSE
     ln_next_cr := (ln_dig + ln_next_crm - ln_crm) * NVL (an_kc, 1);
    END IF;

    IF ln_next_drm >= ln_drm THEN   --Зона D
     ln_next_dr := (ln_next_drm - ln_drm) * NVL (an_kc, 1);
    ELSE
     ln_next_dr := (ln_dig + ln_next_drm - ln_drm) * NVL (an_kc, 1);
    END IF;
   END IF;

    --   IF ABS(NVL(ln_next_r, 0) - (NVL(ln_next_ar, 0) + NVL(ln_next_br, 0) + NVL(ln_next_cr, 0) + NVL(ln_next_dr, 0))) <= 4 THEN --Разница в расходах <4
   --   raise_application_error(-20001, ln_next_r || CHR(10) || SQLERRM(SQLCODE));
   setdebit (an_mid, ld_next_rm, an_ntype, an_table, av_source, av_remark, av_mtrsn, an_kc, ln_next_r, ln_next_ar, ln_next_br, ln_next_cr, ln_next_dr);
  --   ELSE --Не трогаем зоны
   --   setdebit(an_mid, ld_next_rm, an_ntype, an_table, av_source, av_remark, av_mtrsn, an_kc, ln_next_r);
  --   END IF;
  END IF;

  SYS.DBMS_SQL.close_cursor (ln_handle);
  -- вставляем расходы в получасовки
  -- С предыдущей по текущую
  --      setHalfhourOldZone(an_mid, ld_last_rm, ad_date, an_ntype, av_source, av_mtrsn, an_kc,
  --                         an_r, an_ar, an_br, an_cr, an_dr);
  -- С текущей по следующую
  --      setHalfhourOldZone(an_mid, ad_date, ld_next_rm, an_ntype, av_source, av_mtrsn, an_kc,
  --                        ln_next_r, ln_next_ar, ln_next_br, ln_next_cr, ln_next_dr);
  admin_pg.fiscal_p (gn_task_code, 1,
                          'Произведен ввод показаний по точке ' || util_pg.node_path_f (an_mid, 'points', 'mid', 'parent') || ' на '
                          || TO_CHAR (ad_date, 'dd.mm.yyyy hh24:mi:ss'));
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT setindic_l_sp;

   IF SYS.DBMS_SQL.is_open (ln_handle) THEN
    SYS.DBMS_SQL.close_cursor (ln_handle);
   END IF;

   raise_application_error (-20001, 'indic_pg.setindic: Ошибка вставки показаний. ' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
--Ins Upd Del расхода короткая
 PROCEDURE setdebit (an_mid NUMBER, ad_date DATE, an_ntype NUMBER, an_table NUMBER,   -- an_table =1 BILL,=2 HALFHOUR,=3 PROFILE иначе MONTHSORG
                                                                                   av_source VARCHAR2, av_remark VARCHAR2, av_mtrsn VARCHAR2, an_kc NUMBER,
 an_r NUMBER   --расход
 ) IS
  ln_r              NUMBER          DEFAULT ROUND (an_r, gn_2);
  ln_handle         INTEGER;
  ln_ret            NUMBER;
  lv_sqlupd         VARCHAR2 (2000) DEFAULT 'UPDATE ';
  lv_sqlins         VARCHAR2 (2000) DEFAULT 'INSERT INTO ';
  lv_table          VARCHAR2 (30);
  lb_det            BOOLEAN         DEFAULT TRUE;
  lv_add            VARCHAR2 (10);
  lv_kc             VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (an_kc), 'NULL');
  lv_r              VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (ROUND (an_r, gn_2)), 'NULL');
  ln_ptype          NUMBER          := 0;
  ln_lockhalfhour   NUMBER          DEFAULT util_pg.getparamvalue_f (32);
 BEGIN
  IF an_table = 1 THEN
   gn_task_code := 203;
  ELSIF an_table = 2 THEN
   gn_task_code := 603;
  ELSIF an_table = 5 THEN
   gn_task_code := 616;
  ELSIF an_table = 6 THEN
   gn_task_code := 612;
  ELSIF an_table = 7 THEN
   gn_task_code := 617;
  ELSIF an_table = 8 THEN
   gn_task_code := 609;
  ELSIF an_table = 9 THEN
   gn_task_code := 621;
  END IF;

  SELECT NVL (ncalcpointtype, 0)
    INTO ln_ptype
    FROM feeders
   WHERE mid = an_mid;   -- KAS

  IF ln_ptype = 3 THEN
   setdebitdiff (an_mid, ad_date, an_ntype, av_source, av_remark, av_mtrsn, an_kc, NULL, an_r);
  ELSE
   SAVEPOINT setdebit_s_sp;
   ln_handle := SYS.DBMS_SQL.open_cursor;

   IF an_table = 1 THEN
    lv_table := 'BILL';
   ELSIF an_table = 2 THEN
    lv_table := 'HALFHOUR';
    lb_det := FALSE;
   ELSIF an_table = 3 THEN
    lv_table := 'PROFILE';
    lb_det := FALSE;
   ELSIF an_table IN (5, 6, 7, 8, 9) THEN
    lv_table := 'BILLORG';
   ELSE
    lv_table := 'MONTHSORG';
   END IF;

   IF an_ntype = 2 THEN
    lv_add := 'ed';
   ELSIF an_ntype = 3 THEN
    lv_add := 'q1';
   ELSIF an_ntype = 4 THEN
    lv_add := 'q2';
   ELSIF an_ntype = 5 THEN
    lv_add := 'q3';
   ELSIF an_ntype = 6 THEN
    lv_add := 'q4';
   ELSE
    lv_add := 'er';
   END IF;

   IF an_table = 2 THEN
    lv_sqlupd :=
     lv_sqlupd || lv_table || ' SET ' || lv_add || '=' || lv_r || ', NKC=' || lv_kc || ' where mid=' || an_mid || ' and date_time=to_date('
     || TO_CHAR (ad_date, 'YYYYMMDDHH24MISS') || ',''YYYYMMDDHH24MISS'')';
    lv_sqlins :=
     lv_sqlins || lv_table || '(mid,date_time,' || lv_add || ',NKC) VALUES(' || an_mid || ',to_date(' || TO_CHAR (ad_date, 'YYYYMMDDHH24MISS')
     || ',''YYYYMMDDHH24MISS''),' || lv_r || ',' || lv_kc || ')';
   ELSIF lb_det THEN
    lv_sqlupd :=
     lv_sqlupd || lv_table || ' SET ' || 'source=' || '''' || av_source || ''',' || 'remark=' || '''' || av_remark || ''',' || lv_add || '_MTRSN=''' || av_mtrsn
     || ''',' || lv_add || '_KC=' || lv_kc || ',' || lv_add || '=' || lv_r || ' where mid=' || an_mid || ' and date_time=to_date('
     || TO_CHAR (ad_date, 'YYYYMMDDHH24MISS') || ',''YYYYMMDDHH24MISS'')';
    lv_sqlins :=
     lv_sqlins || lv_table || '(mid,date_time,' || 'source,remark,' || lv_add || '_MTRSN,' || lv_add || '_KC,' || lv_add || ') VALUES(' || an_mid || ',to_date('
     || TO_CHAR (ad_date, 'YYYYMMDDHH24MISS') || ',''YYYYMMDDHH24MISS''),' || '''' || av_source || ''',''' || av_remark || ''',''' || av_mtrsn || ''',' || lv_kc
     || ',' || lv_r || ')';
   ELSE
    lv_sqlupd :=
     lv_sqlupd || lv_table || ' SET ' || lv_add || '=' || lv_r || ' where mid=' || an_mid || ' and date_time=to_date(' || TO_CHAR (ad_date, 'YYYYMMDDHH24MISS')
     || ',''YYYYMMDDHH24MISS'')';
    lv_sqlins :=
     lv_sqlins || lv_table || '(mid,date_time,' || lv_add || ') VALUES(' || an_mid || ',to_date(' || TO_CHAR (ad_date, 'YYYYMMDDHH24MISS')
     || ',''YYYYMMDDHH24MISS''),' || lv_r || ')';
   END IF;

   SYS.DBMS_SQL.parse (ln_handle, lv_sqlupd, SYS.DBMS_SQL.native);

   IF SYS.DBMS_SQL.EXECUTE (ln_handle) = 0 THEN   --UPDATE не удался, значит INSERT
    SYS.DBMS_SQL.parse (ln_handle, lv_sqlins, SYS.DBMS_SQL.native);
    ln_ret := SYS.DBMS_SQL.EXECUTE (ln_handle);
   END IF;

   IF an_table IN (5, 6, 7, 8, 9) THEN
    BEGIN
     SAVEPOINT try_halfhour;
     calc_hh24 (an_mid, an_table, 2, ad_date, an_ntype, an_r);
    EXCEPTION
     WHEN OTHERS THEN
      IF SQLCODE < -20000 AND ln_lockhalfhour = 1 THEN
       ROLLBACK TO SAVEPOINT try_halfhour;
      ELSE
       RAISE;
      END IF;
    END;
   END IF;

   SYS.DBMS_SQL.close_cursor (ln_handle);

   IF an_table = 2 THEN   --HALFHOUR
    das_pg.calcpoint4bill (an_mid, ad_date, ad_date);
   END IF;
  END IF;

  admin_pg.fiscal_p (gn_task_code, 1,
                          'Произведен ввод расхода по точке ' || util_pg.node_path_f (an_mid, 'points', 'mid', 'parent') || ' на '
                          || TO_CHAR (ad_date, 'dd.mm.yyyy hh24:mi:ss'));
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT setdebit_s_sp;

   IF SYS.DBMS_SQL.is_open (ln_handle) THEN
    SYS.DBMS_SQL.close_cursor (ln_handle);
   END IF;

   raise_application_error (-20001, 'indic_pg.setdebit: Ошибка вставки расхода. ' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
--Ins Upd Del расхода длинная (зоны)
 PROCEDURE setdebit (an_mid NUMBER, ad_date DATE, an_ntype NUMBER, an_table NUMBER,   -- an_table =1 BILL,=2 HALFHOUR,=3 PROFILE иначе MONTHSORG
                                                                                   av_source VARCHAR2, av_remark VARCHAR2, av_mtrsn VARCHAR2, an_kc NUMBER,
 an_r NUMBER,   --расход
             an_ar NUMBER,   --расход 1 зона
                          an_br NUMBER, an_cr NUMBER, an_dr NUMBER
 ) IS
  ln_r         NUMBER          DEFAULT ROUND (an_r, gn_2);
  ln_ar        NUMBER          DEFAULT ROUND (an_ar, gn_2);
  ln_br        NUMBER          DEFAULT ROUND (an_br, gn_2);
  ln_cr        NUMBER          DEFAULT ROUND (an_cr, gn_2);
  ln_dr        NUMBER          DEFAULT ROUND (an_dr, gn_2);
  ln_handle    INTEGER;
  ln_ret       NUMBER;
  lv_sqlupd    VARCHAR2 (2000) DEFAULT 'UPDATE ';
  lv_sqlins    VARCHAR2 (2000) DEFAULT 'INSERT INTO ';
  lv_table     VARCHAR2 (30);
  lv_add       VARCHAR2 (10);
  lv_kc        VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (an_kc), 'NULL');
  lv_r         VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (ROUND (an_r, gn_2)), 'NULL');
  lv_ar        VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (ROUND (an_ar, gn_2)), 'NULL');
  lv_br        VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (ROUND (an_br, gn_2)), 'NULL');
  lv_cr        VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (ROUND (an_cr, gn_2)), 'NULL');
  lv_dr        VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (ROUND (an_dr, gn_2)), 'NULL');
  ld_next_r    DATE            DEFAULT NULL;   --Дата следующего расхода
  ld_last_r    DATE            DEFAULT NULL;   --Дата предыдущего расхода
  ln_next_r    NUMBER;   --Следующие расход
  ln_next_ar   NUMBER;   --Следующие расход a
  ln_next_br   NUMBER;   --Следующие расход b
  ln_next_cr   NUMBER;   --Следующие расход c
  ln_next_dr   NUMBER;   --Следующие расход d
 BEGIN
  gn_task_code := 201;
  SAVEPOINT setdebit_l_sp;
  ld_next_r := getnextdate (an_mid, ad_date, an_ntype, NULL /*an_zone*/, an_table, 2);   --Дата след показаний
  ld_last_r := getlastdate (an_mid, ad_date, an_ntype, NULL /*an_zone*/, an_table, 2);   --Дата пред показаний
  --  IF an_table IN (2, 3) THEN --Если HALFHOUR или PROFILE то вызываем короткую процедуру
  --   setdebit(an_mid, ad_date, an_ntype, an_table, av_source, av_remark, av_mtrsn, an_kc, an_r);
  --   RETURN;
  --  END IF;
  ln_handle := SYS.DBMS_SQL.open_cursor;

  IF an_table = 1 THEN
   lv_table := 'BILL';
  ELSIF an_table IN (5, 6, 7, 8, 9) THEN
   lv_table := 'BILLORG';
  ELSE
   lv_table := 'MONTHSORG';
  END IF;

  IF an_ntype = 2 THEN
   lv_add := 'ed';
  ELSIF an_ntype = 3 THEN
   lv_add := 'q1';
  ELSIF an_ntype = 4 THEN
   lv_add := 'q2';
  ELSIF an_ntype = 5 THEN
   lv_add := 'q3';
  ELSIF an_ntype = 6 THEN
   lv_add := 'q4';
  ELSE
   lv_add := 'er';
  END IF;

  lv_sqlupd :=
   lv_sqlupd || lv_table || ' SET ' || 'source=' || '''' || av_source || ''',' || 'remark=' || '''' || av_remark || ''',' || lv_add || '_MTRSN=''' || av_mtrsn
   || ''',' || lv_add || '_KC=' || lv_kc || ',' || lv_add || '=' || lv_r || ',a' || lv_add || '=' || lv_ar || ',b' || lv_add || '=' || lv_br || ',c' || lv_add || '='
   || lv_cr || ',d' || lv_add || '=' || lv_dr || ' where mid=' || an_mid || ' and date_time=to_date(' || TO_CHAR (ad_date, 'YYYYMMDDHH24MISS')
   || ',''YYYYMMDDHH24MISS'')';
  lv_sqlins :=
   lv_sqlins || lv_table || '(mid,date_time,' || 'source,remark,' || lv_add || '_MTRSN,' || lv_add || '_KC,' || lv_add || ',a' || lv_add || ',b' || lv_add || ',c'
   || lv_add || ',d' || lv_add || ') VALUES(' || an_mid || ',to_date(' || TO_CHAR (ad_date, 'YYYYMMDDHH24MISS') || ',''YYYYMMDDHH24MISS''),' || '''' || av_source
   || ''',''' || av_remark || ''',''' || av_mtrsn || ''',' || lv_kc || ',' || lv_r || ',' || lv_ar || ',' || lv_br || ',' || lv_cr || ',' || lv_dr || ')';
  SYS.DBMS_SQL.parse (ln_handle, lv_sqlupd, SYS.DBMS_SQL.native);

  IF SYS.DBMS_SQL.EXECUTE (ln_handle) = 0 THEN   --UPDATE не удался, значит INSERT
   SYS.DBMS_SQL.parse (ln_handle, lv_sqlins, SYS.DBMS_SQL.native);
   ln_ret := SYS.DBMS_SQL.EXECUTE (ln_handle);
  END IF;

  SYS.DBMS_SQL.close_cursor (ln_handle);

  IF ld_next_r IS NOT NULL THEN   -- Если есть следующие показания то получаем их
   ln_next_r := getlastdebit (an_mid, ld_next_r + 1 / (24 * 60 * 60), an_ntype, NULL, an_table);   --Следующие показания (вычисляем как предыдущие, для их даты+ 1 сек)
   ln_next_ar := getlastdebit (an_mid, ld_next_r + 1 / (24 * 60 * 60), an_ntype, 1, an_table);   --Следующие показания (вычисляем как предыдущие, для их даты+ 1 сек)
   ln_next_br := getlastdebit (an_mid, ld_next_r + 1 / (24 * 60 * 60), an_ntype, 2, an_table);   --Следующие показания (вычисляем как предыдущие, для их даты+ 1 сек)
   ln_next_cr := getlastdebit (an_mid, ld_next_r + 1 / (24 * 60 * 60), an_ntype, 3, an_table);   --Следующие показания (вычисляем как предыдущие, для их даты+ 1 сек)
   ln_next_dr := getlastdebit (an_mid, ld_next_r + 1 / (24 * 60 * 60), an_ntype, 4, an_table);   --Следующие показания (вычисляем как предыдущие, для их даты+ 1 сек)
  --    DELETE FROM halfhourold WHERE mid = an_mid AND date_time
  END IF;

  IF an_r IS NULL THEN   --Если текущие удалили, то для следующих предидущими будут предидущие от текущих
   --   raise_application_error(-20001, 'орпываолырпа' || CHR(10) || SQLERRM(SQLCODE));
   sethalfhouroldzone (an_mid, ld_last_r, ld_next_r, an_ntype, av_source, av_mtrsn, an_kc, ln_next_r, ln_next_ar, ln_next_br, ln_next_cr, ln_next_dr);
  ELSE
   -- вставляем расходы в получасовки
   -- С предыдущей по текущую
   --   raise_application_error(-20001, '2323424234234' || CHR(10) || SQLERRM(SQLCODE));
   sethalfhouroldzone (an_mid, ld_last_r, ad_date, an_ntype, av_source, av_mtrsn, an_kc, an_r, an_ar, an_br, an_cr, an_dr);
   -- С текущей по следующую
   sethalfhouroldzone (an_mid, ad_date, ld_next_r, an_ntype, av_source, av_mtrsn, an_kc, ln_next_r, ln_next_ar, ln_next_br, ln_next_cr, ln_next_dr);
  END IF;

  admin_pg.fiscal_p (gn_task_code, 1,
                          'Произведен ввод расхода по точке ' || util_pg.node_path_f (an_mid, 'points', 'mid', 'parent') || ' на '
                          || TO_CHAR (ad_date, 'dd.mm.yyyy hh24:mi:ss'));
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT setdebit_l_sp;

   IF SYS.DBMS_SQL.is_open (ln_handle) THEN
    SYS.DBMS_SQL.close_cursor (ln_handle);
   END IF;

   raise_application_error (-20001, 'indic_pg.setdebit: Ошибка вставки расхода. ' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE setpower (an_mid NUMBER, ad_date DATE, an_er NUMBER, an_ed NUMBER, an_q1 NUMBER, an_q3 NUMBER) IS
 --Только для 15 минуток
 BEGIN
  UPDATE curr_power
     SET date_time = SYSDATE,
         er = NVL (4 * an_er, er),
         ed = NVL (4 * an_ed, ed),
         q1 = NVL (4 * an_q1, q1),
         q3 = NVL (4 * an_q3, q3)
   WHERE mid = an_mid;

  IF SQL%ROWCOUNT = 0 THEN
   INSERT INTO curr_power
               (mid, date_time, obsolete, er, ed, q1, q3
               )
        VALUES (an_mid, SYSDATE, 1, 4 * an_er, 4 * an_ed, 4 * an_q1, 4 * an_q3
               );
  END IF;

  FOR i IN 0 .. 4 LOOP
   UPDATE PROFILE
      SET er = NVL (an_er / 5, er),
          ed = NVL (an_ed / 5, ed),
          q1 = NVL (an_q1 / 5, q1),
          q3 = NVL (an_q3 / 5, q3)
    WHERE mid = an_mid AND date_time = ad_date - i / 480;

   IF SQL%ROWCOUNT = 0 THEN
    INSERT INTO PROFILE
                (mid, date_time, er, ed, q1, q3
                )
         VALUES (an_mid, ad_date - i / 480, an_er / 5, an_ed / 5, an_q1 / 5, an_q3 / 5
                );
   END IF;
  END LOOP;
 END;

