 --Возвращает ид группы точек с разбивкой графика поровну
 FUNCTION getoutputgroup
  RETURN NUMBER IS
 BEGIN
  RETURN gn_outputgroup;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE create_right_cons (an_mid NUMBER, ad_date DATE, an_type NUMBER, an_clear NUMBER) IS
  ln_source   NUMBER              DEFAULT 9;
  ld_date     DATE                DEFAULT TRUNC (ad_date);
  ln_dif      NUMBER              DEFAULT 0.0001;
  ln_er       NUMBER;
  ln_ed       NUMBER;
  ln_q1       NUMBER;
  ln_q2       NUMBER;
  ln_q3       NUMBER;
  ln_q4       NUMBER;
  ln_ser      NUMBER;
  ln_sed      NUMBER;
  ln_sq1      NUMBER;
  ln_sq2      NUMBER;
  ln_sq3      NUMBER;
  ln_sq4      NUMBER;
  ln_mer      NUMBER;
  ln_med      NUMBER;
  ln_mq1      NUMBER;
  ln_mq2      NUMBER;
  ln_mq3      NUMBER;
  ln_mq4      NUMBER;
  ln_sm       NUMBER;
  lt_n        common_pg.tt_number;
  lt_er       common_pg.tt_number;
  lt_ed       common_pg.tt_number;
  lt_q1       common_pg.tt_number;
  lt_q2       common_pg.tt_number;
  lt_q3       common_pg.tt_number;
  lt_q4       common_pg.tt_number;

  CURSOR lcur_sel IS
   SELECT mid, NVL (kc, 1) kc
     FROM feeders
    WHERE mid = an_mid OR an_mid IS NULL;

  CURSOR lcur_sel1 (lc_mid NUMBER, lc_date DATE) IS
   SELECT   ROWNUM dt
       FROM halfhourold
      WHERE ROWNUM < 49
   MINUS
   SELECT   TRUNC (TO_CHAR (date_time - 1 / 86400, 'SSSSS') / 1800) + 1 dt
       FROM halfhour
      WHERE mid = lc_mid AND date_time > lc_date AND date_time <= lc_date + 1
   GROUP BY TRUNC (TO_CHAR (date_time - 1 / 86400, 'SSSSS') / 1800)
     HAVING SUM (er) IS NOT NULL OR SUM (ed) IS NOT NULL OR SUM (q1) IS NOT NULL OR SUM (q2) IS NOT NULL OR SUM (q3) IS NOT NULL OR SUM (q4) IS NOT NULL
   ORDER BY 1;
 BEGIN
  IF an_type = 1 THEN
   ld_date := TO_DATE (TO_CHAR (ld_date, 'YYYY') || '10' || TO_CHAR (util_pg.last_dayw (ld_date, 7), 'DD'), 'YYYYMMDD');
  END IF;

  IF an_clear = 1 THEN
   IF an_mid IS NULL THEN
    DELETE FROM halfhourold
          WHERE date_time > ld_date AND date_time <= ld_date + 1 AND nsource = ln_source;
   ELSE
    DELETE FROM halfhourold
          WHERE mid = an_mid AND date_time > ld_date AND date_time <= ld_date + 1 AND nsource = ln_source;
   END IF;
  END IF;

  FOR lc IN lcur_sel LOOP
   SELECT MAX (er), MAX (ed), MAX (q1), MAX (q2), MAX (q3), MAX (q4)
     INTO ln_er, ln_ed, ln_q1, ln_q2, ln_q3, ln_q4
     FROM billorg
    WHERE mid = lc.mid AND date_time = ld_date + 1;

   SELECT GREATEST (ln_er - NVL (SUM (er), 0), 0), GREATEST (ln_ed - NVL (SUM (ed), 0), 0), GREATEST (ln_q1 - NVL (SUM (q1), 0), 0),
          GREATEST (ln_q2 - NVL (SUM (q2), 0), 0), GREATEST (ln_q3 - NVL (SUM (q3), 0), 0), GREATEST (ln_q4 - NVL (SUM (q4), 0), 0)
     INTO ln_er, ln_ed, ln_q1,
          ln_q2, ln_q3, ln_q4
     FROM halfhour
    WHERE mid = lc.mid AND date_time > ld_date AND date_time <= ld_date + 1;

   IF NVL (ln_er, 0) < ln_dif AND NVL (ln_ed, 0) < ln_dif AND NVL (ln_q1, 0) < ln_dif AND NVL (ln_q2, 0) < ln_dif AND NVL (ln_q3, 0) < ln_dif
      AND NVL (ln_q4, 0) < ln_dif THEN
    GOTO to_continue;
   END IF;

   IF an_type = 1 THEN
    IF (TRUNC (ln_er / 2) >= ln_dif OR TRUNC (ln_ed / 2) >= ln_dif OR TRUNC (ln_q1 / 2) >= ln_dif OR TRUNC (ln_q2 / 2) >= ln_dif OR TRUNC (ln_q3 / 2) >= ln_dif
        OR TRUNC (ln_q4 / 2) >= ln_dif
       ) THEN
     INSERT INTO halfhour
                 (mid, date_time, nsource, er, ed, q1, q2, q3,
                  q4, nkc
                 )
          VALUES (lc.mid, ld_date + 5 / 48, ln_source, TRUNC (ln_er / 2), TRUNC (ln_ed / 2), TRUNC (ln_q1 / 2), TRUNC (ln_q2 / 2), TRUNC (ln_q3 / 2),
                  TRUNC (ln_q4 / 2), lc.kc
                 );
    END IF;

    IF (ln_er - TRUNC (ln_er / 2) >= ln_dif OR ln_ed - TRUNC (ln_ed / 2) >= ln_dif OR ln_q1 - TRUNC (ln_q1 / 2) >= ln_dif OR ln_q2 - TRUNC (ln_q2 / 2) >= ln_dif
        OR ln_q3 - TRUNC (ln_q3 / 2) >= ln_dif OR ln_q4 - TRUNC (ln_q4 / 2) >= ln_dif
       ) THEN
     INSERT INTO halfhour
                 (mid, date_time, nsource, er, ed, q1, q2,
                  q3, q4, nkc
                 )
          VALUES (lc.mid, ld_date + 6 / 48, ln_source, ln_er - TRUNC (ln_er / 2), ln_ed - TRUNC (ln_ed / 2), ln_q1 - TRUNC (ln_q1 / 2), ln_q2 - TRUNC (ln_q2 / 2),
                  ln_q3 - TRUNC (ln_q3 / 2), ln_q4 - TRUNC (ln_q4 / 2), lc.kc
                 );
    END IF;
   ELSE
    lt_n.DELETE;
    lt_er.DELETE;
    lt_ed.DELETE;
    lt_q1.DELETE;
    lt_q2.DELETE;
    lt_q3.DELETE;
    lt_q4.DELETE;
    ln_sm := 0;

    FOR lc1 IN lcur_sel1 (lc.mid, ld_date) LOOP
     ln_sm := ln_sm + 1;
     lt_n (ln_sm) := lc1.dt;
    END LOOP;

    IF ln_sm = 0 THEN
     GOTO to_continue;
    END IF;

    ln_ser := ln_er;
    ln_sed := ln_ed;
    ln_sq1 := ln_q1;
    ln_sq2 := ln_q2;
    ln_sq3 := ln_q3;
    ln_sq4 := ln_q4;

    FOR i IN 1 .. ln_sm LOOP
     lt_er (i) := TRUNC (ln_er / ln_sm);
     ln_ser := ln_ser - lt_er (i);
     lt_ed (i) := TRUNC (ln_ed / ln_sm);
     ln_sed := ln_sed - lt_ed (i);
     lt_q1 (i) := TRUNC (ln_q1 / ln_sm);
     ln_sq1 := ln_sq1 - lt_q1 (i);
     lt_q2 (i) := TRUNC (ln_q2 / ln_sm);
     ln_sq2 := ln_sq2 - lt_q2 (i);
     lt_q3 (i) := TRUNC (ln_q3 / ln_sm);
     ln_sq3 := ln_sq3 - lt_q3 (i);
     lt_q4 (i) := TRUNC (ln_q4 / ln_sm);
     ln_sq4 := ln_sq4 - lt_q4 (i);
    END LOOP;   --abs и sign остался для поддержки отрицательной подгонки

    ln_mer := SIGN (ln_ser);
    ln_med := SIGN (ln_sed);
    ln_mq1 := SIGN (ln_sq1);
    ln_mq2 := SIGN (ln_sq2);
    ln_mq3 := SIGN (ln_sq3);
    ln_mq4 := SIGN (ln_sq4);
    ln_ser := ABS (ln_ser);
    ln_sed := ABS (ln_sed);
    ln_sq1 := ABS (ln_sq1);
    ln_sq2 := ABS (ln_sq2);
    ln_sq3 := ABS (ln_sq3);
    ln_sq4 := ABS (ln_sq4);

    FOR i IN 1 .. ln_sm LOOP
     IF ln_ser > 0 THEN
      lt_er (i) := lt_er (i) + ln_mer * LEAST (1, ln_ser);
      ln_ser := ln_ser - LEAST (1, ln_ser);
     END IF;

     IF ln_sed > 0 THEN
      lt_ed (i) := lt_ed (i) + ln_med * LEAST (1, ln_sed);
      ln_sed := ln_sed - LEAST (1, ln_sed);
     END IF;

     IF ln_sq1 > 0 THEN
      lt_q1 (i) := lt_q1 (i) + ln_mq1 * LEAST (1, ln_sq1);
      ln_sq1 := ln_sq1 - LEAST (1, ln_sq1);
     END IF;

     IF ln_sq2 > 0 THEN
      lt_q2 (i) := lt_q2 (i) + ln_mq2 * LEAST (1, ln_sq2);
      ln_sq2 := ln_sq2 - LEAST (1, ln_sq2);
     END IF;

     IF ln_sq3 > 0 THEN
      lt_q3 (i) := lt_q3 (i) + ln_mq3 * LEAST (1, ln_sq3);
      ln_sq3 := ln_sq3 - LEAST (1, ln_sq3);
     END IF;

     IF ln_sq4 > 0 THEN
      lt_q4 (i) := lt_q4 (i) + ln_mq4 * LEAST (1, ln_sq4);
      ln_sq4 := ln_sq4 - LEAST (1, ln_sq4);
     END IF;

     IF ABS (lt_er (i)) < ln_dif THEN
      lt_er (i) := 0;
     END IF;

     IF ABS (lt_ed (i)) < ln_dif THEN
      lt_ed (i) := 0;
     END IF;

     IF ABS (lt_q1 (i)) < ln_dif THEN
      lt_q1 (i) := 0;
     END IF;

     IF ABS (lt_q2 (i)) < ln_dif THEN
      lt_q2 (i) := 0;
     END IF;

     IF ABS (lt_q3 (i)) < ln_dif THEN
      lt_q3 (i) := 0;
     END IF;

     IF ABS (lt_q4 (i)) < ln_dif THEN
      lt_q4 (i) := 0;
     END IF;
    END LOOP;

    FOR i IN 1 .. ln_sm LOOP
     INSERT INTO halfhour
                 (mid, date_time, nsource, er, ed, q1, q2, q3, q4, nkc
                 )
          VALUES (lc.mid, ld_date + lt_n (i) / 48, ln_source, lt_er (i), lt_ed (i), lt_q1 (i), lt_q2 (i), lt_q3 (i), lt_q4 (i), lc.kc
                 );
    END LOOP;
   END IF;

   das_pg.calcpoint4bill (an_mid, ld_date, ld_date + 1);

   <<to_continue>>
   NULL;
  END LOOP;
 END;

------------------------------------------------------------------------------------------------------------------------
 --Возвращает доступность ручного ввода по измерению
 FUNCTION is_availability (an_measure NUMBER, an_q1234 NUMBER, an_er_position NUMBER, an_ed_position NUMBER, an_q1_position NUMBER, an_q3_position NUMBER)
  RETURN NUMBER IS
 BEGIN
  IF an_measure = 1 AND an_er_position > 0 THEN
   RETURN 1;
  ELSIF an_measure = 2 AND an_ed_position > 0 THEN
   RETURN 1;
  ELSIF an_measure = 3 AND an_q1_position > 0 THEN
   RETURN 1;
  ELSIF an_measure = 4 AND an_q1_position > 0 AND an_q1234 = 1 THEN
   RETURN 1;
  ELSIF an_measure = 5 AND an_q3_position > 0 THEN
   RETURN 1;
  ELSIF an_measure = 6 AND an_q3_position > 0 AND an_q1234 = 1 THEN
   RETURN 1;
  END IF;

  RETURN 0;
 END;

------------------------------------------------------------------------------------------------------------------------
  --Возвращает название измерения
 FUNCTION measurename (an_measure NUMBER, an_q1234 NUMBER)
  RETURN VARCHAR2 IS
 BEGIN
  IF an_measure = 1 THEN
   RETURN 'А птр.';
  ELSIF an_measure = 2 THEN
   RETURN 'А выд.';
  ELSIF an_measure = 3 THEN
   IF an_q1234 = 1 THEN
    RETURN 'Q1';
   ELSE
    RETURN 'Р птр.';
   END IF;
  ELSIF an_measure = 4 THEN
   RETURN 'Q2';
  ELSIF an_measure = 5 THEN
   IF an_q1234 = 1 THEN
    RETURN 'Q3';
   ELSE
    RETURN 'Р выд.';
   END IF;
  ELSIF an_measure = 6 THEN
   RETURN 'Q4';
  END IF;

  RETURN ' ';
 END;

------------------------------------------------------------------------------------------------------------------------
 -- Вставляет значения расходов в HalfhourOld по зонам
 PROCEDURE sethalfhouroldzone (an_mid NUMBER, ad_datestart DATE, ad_datefin DATE, an_ntype NUMBER, av_source VARCHAR2, av_mtrsn VARCHAR2, an_kc NUMBER, an_r NUMBER,   --расход
 an_ar NUMBER,   --расход 1 зона
              an_br NUMBER, an_cr NUMBER, an_dr NUMBER
 ) IS
  ln_all_falf_hour_count       NUMBER     DEFAULT 0;
  ln_a_falf_hour_count         NUMBER     DEFAULT 0;
  ln_b_falf_hour_count         NUMBER     DEFAULT 0;
  ln_c_falf_hour_count         NUMBER     DEFAULT 0;
  ln_d_falf_hour_count         NUMBER     DEFAULT 0;
  ln_all_falf_hour_day_count   NUMBER     DEFAULT 0;
  ln_a_falf_hour_day_count     NUMBER     DEFAULT 0;
  ln_b_falf_hour_day_count     NUMBER     DEFAULT 0;
  ln_c_falf_hour_day_count     NUMBER     DEFAULT 0;
  ln_d_falf_hour_day_count     NUMBER     DEFAULT 0;
  ld_curr_data                 DATE       DEFAULT ad_datestart;
  ln_currval                   NUMBER     DEFAULT 0;
  i                            NUMBER;
  j                            NUMBER;

  /*  debugDate DATE;
    debugNUM number;
    debugDate1 DATE;
    lv_d1       VARCHAR2(10);
    lv_d2       VARCHAR2(10);
    lv_d3       VARCHAR2(10);
    lv_d4       VARCHAR2(10);
    */
  TYPE rrateattr IS RECORD (
   dtime      DATE,
   dendtime   DATE,
   nval_inc   NUMBER
  );

  TYPE trates IS TABLE OF rrateattr
   INDEX BY BINARY_INTEGER;

  lt_rates                     trates;

  TYPE rrate IS RECORD (
   ddate   DATE,
   nrid    NUMBER
  );

  TYPE trate_list IS TABLE OF rrate
   INDEX BY BINARY_INTEGER;

  lt_rate_list                 trate_list;

  CURSOR cr_rate_list IS
   SELECT   a.rid, a.switch_date
       FROM rate_list a
      WHERE switch_date >= ad_datestart AND switch_date < ad_datefin
   UNION
   SELECT   a.rid, a.switch_date
       FROM rate_list a
      WHERE switch_date = (SELECT MAX (switch_date)
                             FROM rate_list
                            WHERE switch_date < ad_datestart)
   ORDER BY 2;

  CURSOR cr_rateattr (arid NUMBER) IS
   SELECT   a.TIME, a.rate, a.endtime
       FROM rates a
      WHERE rid = arid
   ORDER BY TIME;
 BEGIN
  IF ad_datestart IS NULL OR ad_datefin IS NULL THEN
   RETURN;
  END IF;

  lt_rate_list.DELETE;
  ln_all_falf_hour_count := (ad_datefin - ad_datestart) * 48;
  i := 1;

  FOR cr IN cr_rate_list LOOP
   --  debugNUM :=cr.rid;
   --  debugDate:=cr.switch_date;
   lt_rate_list (i).nrid := cr.rid;
   lt_rate_list (i).ddate := cr.switch_date;
   i := i + 1;
  END LOOP;

  FOR ii IN 1 .. lt_rate_list.COUNT LOOP
   SELECT NVL (ROUND (SUM (a.endtime - a.TIME) * 48), 0)
     INTO ln_a_falf_hour_day_count
     FROM rates a
    WHERE rid = lt_rate_list (ii).nrid AND rate = 0;

   SELECT NVL (ROUND (SUM (a.endtime - a.TIME) * 48), 0)
     INTO ln_b_falf_hour_day_count
     FROM rates a
    WHERE rid = lt_rate_list (ii).nrid AND rate = 1;

   SELECT NVL (ROUND (SUM (a.endtime - a.TIME) * 48), 0)
     INTO ln_c_falf_hour_day_count
     FROM rates a
    WHERE rid = lt_rate_list (ii).nrid AND rate = 2;

   SELECT NVL (ROUND (SUM (a.endtime - a.TIME) * 48), 0)
     INTO ln_d_falf_hour_day_count
     FROM rates a
    WHERE rid = lt_rate_list (ii).nrid AND rate = 3;

   WHILE ld_curr_data < ad_datefin LOOP
    ln_a_falf_hour_count := ln_a_falf_hour_count + ln_a_falf_hour_day_count;
    ln_b_falf_hour_count := ln_b_falf_hour_count + ln_b_falf_hour_day_count;
    ln_c_falf_hour_count := ln_c_falf_hour_count + ln_c_falf_hour_day_count;
    ln_d_falf_hour_count := ln_d_falf_hour_count + ln_d_falf_hour_day_count;
    ld_curr_data := ld_curr_data + 1;

    IF ii + 1 <= lt_rate_list.COUNT AND ld_curr_data >= lt_rate_list (ii + 1).ddate THEN
     EXIT;
    END IF;
   END LOOP;
  END LOOP;

  -- Вычисляем приращение на каждые полчаса
  ln_all_falf_hour_day_count := an_r / ln_all_falf_hour_count;
  ln_a_falf_hour_day_count := an_ar / ln_a_falf_hour_count;
  ln_b_falf_hour_day_count := an_br / ln_b_falf_hour_count;
  ln_c_falf_hour_day_count := an_cr / ln_c_falf_hour_count;
  ln_d_falf_hour_day_count := an_dr / ln_d_falf_hour_count;
  ld_curr_data := ad_datestart;

  FOR ii IN 1 .. lt_rate_list.COUNT LOOP   -- Шуршим по всем тарифным зонам которые былы
   lt_rates.DELETE;
   j := 1;

   FOR cr IN cr_rateattr (lt_rate_list (ii).nrid) LOOP   -- Заносим параметры текущей тарифной зоны
    --        debugDate :=cr.time;
    --        debugDate1 :=cr.endtime;
    lt_rates (j).dtime := cr.TIME;
    lt_rates (j).dendtime := cr.endtime;

    SELECT DECODE (cr.rate, 0, ln_a_falf_hour_day_count, 1, ln_b_falf_hour_day_count, 2, ln_c_falf_hour_day_count, ln_d_falf_hour_day_count)
      INTO lt_rates (j).nval_inc
      FROM DUAL;

    --          debugNUM := lt_Rates(j).nVal_Inc;
    j := j + 1;
   END LOOP;

   WHILE ld_curr_data < ad_datefin LOOP   -- Пагнали вставлять значения
    ld_curr_data := ld_curr_data + 1 / 48;
    j := 1;

    FOR jj IN 1 .. lt_rates.COUNT LOOP   -- Находим приращение которое нужно вставлять
     /*            lv_d1 := to_char(ld_curr_data,'hh24mi');
                 lv_d2 := to_char(lt_Rates(jj).dTime,'hh24mi');
                 lv_d3 := to_char(lt_Rates(jj).dEndTime,'hh24mi');
                 lv_d4 := to_char(ld_curr_data-1/86400,'hh24mi');
       */
     IF TO_CHAR (ld_curr_data, 'hh24mi') > TO_CHAR (lt_rates (jj).dtime, 'hh24mi')
        AND TO_CHAR (ld_curr_data - 1 / 86400, 'hh24mi') <= TO_CHAR (lt_rates (jj).dendtime, 'hh24mi') THEN
      EXIT;
     END IF;

     IF TO_CHAR (ld_curr_data - 1 / 86400, 'yymmdd') < TO_CHAR (ld_curr_data, 'yymmdd')
        AND TO_CHAR (ld_curr_data - 1 / 86400, 'hh24mi') > TO_CHAR (lt_rates (jj).dtime, 'hh24mi')
        AND TO_CHAR (ld_curr_data - 1 / 86400, 'hh24mi') <= TO_CHAR (lt_rates (jj).dendtime, 'hh24mi') THEN
      EXIT;
     END IF;

     j := j + 1;
    END LOOP;

    ln_currval := lt_rates (j).nval_inc;
    -- Вставляем
    insupdhalfhourold (an_mid, ld_curr_data, an_ntype, an_kc, ln_currval);

--   raise_application_error(-20001, to_char(ld_curr_data, 'dd.mm.yy hh24:mi:ss')||'  '||to_char(ad_dateFin, 'dd.mm.yy hh24:mi:ss') || CHR(10) || SQLERRM(SQLCODE));
--------------------
    IF ii + 1 <= lt_rate_list.COUNT AND ld_curr_data >= lt_rate_list (ii + 1).ddate THEN
     EXIT;
    END IF;
   END LOOP;
  END LOOP;
 END;

------------------------------------------------------------------------------------------------------------------------
 -- Вставляет значение расхода в HalfhourOld
 PROCEDURE insupdhalfhourold (an_mid NUMBER, ad_date DATE, an_ntype NUMBER, an_kc NUMBER, an_r NUMBER) IS
  lv_add       VARCHAR2 (10);
  lv_sql_ins   VARCHAR2 (200);
  lv_sql_upd   VARCHAR2 (200);
  ln_handle    INTEGER;
  ln_ret       NUMBER;
  lv_r         VARCHAR2 (200) := NVL (TO_CHAR (an_r), 'NULL');
 BEGIN
  IF an_r IS NOT NULL THEN
   lv_r := an_r;
  END IF;

  ln_handle := SYS.DBMS_SQL.open_cursor;

  IF an_ntype = 2 THEN
   lv_add := 'ed';
  ELSIF an_ntype = 3 THEN
   lv_add := 'q1';
  ELSIF an_ntype = 4 THEN
   lv_add := 'q2';
  ELSIF an_ntype = 5 THEN
   lv_add := 'q3';
  ELSIF an_ntype = 6 THEN
   lv_add := 'q4';
  ELSE
   lv_add := 'er';
  END IF;

  lv_sql_ins :=
   'INSERT INTO halfhourold (mid, date_time,nsource,nkc,' || lv_add || ') values(' || an_mid || ',to_date(''' || TO_CHAR (ad_date, 'ddmmyyyyhh24miss')
   || ''',''ddmmyyyyhh24miss''),' || util_pg.cn_manualinput || ',' || an_kc || ',' || lv_r || ')';
  lv_sql_upd :=
   'UPDATE halfhourold SET ' || lv_add || '=' || lv_r || ', nsource=' || util_pg.cn_manualinput || ' WHERE mid = ' || an_mid || ' AND date_time = to_date('''
   || TO_CHAR (ad_date, 'ddmmyyyyhh24miss') || ''',''ddmmyyyyhh24miss'')';
  --  raise_application_error(-20001, lv_sql_ins || CHR(10) || SQLERRM(SQLCODE));
  SYS.DBMS_SQL.parse (ln_handle, lv_sql_upd, SYS.DBMS_SQL.native);

  IF SYS.DBMS_SQL.EXECUTE (ln_handle) = 0 THEN
   SYS.DBMS_SQL.parse (ln_handle, lv_sql_ins, SYS.DBMS_SQL.native);
   ln_ret := SYS.DBMS_SQL.EXECUTE (ln_handle);
  END IF;

  SYS.DBMS_SQL.close_cursor (ln_handle);
 EXCEPTION
  WHEN OTHERS THEN
   IF SYS.DBMS_SQL.is_open (ln_handle) THEN
    SYS.DBMS_SQL.close_cursor (ln_handle);
   END IF;

   raise_application_error (-20001, 'indic_pg.InsUpdHalfhourOld: Ошибка вставки расхода. ' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION getdatepercent (an_mid NUMBER, ad_date DATE, an_ntype NUMBER, an_zonetype NUMBER, an_datetype NUMBER)
  RETURN DATE IS
  ret        DATE           DEFAULT NULL;
  lv_field   VARCHAR2 (5);
  lv_sql     VARCHAR2 (200);
 BEGIN
  IF an_zonetype = 1 THEN
   lv_field := 'a';
  ELSIF an_zonetype = 2 THEN
   lv_field := 'b';
  ELSE
   lv_field := 'c';
  END IF;

  IF an_ntype = 2 THEN
   lv_field := lv_field || 'ed';
  ELSIF an_ntype = 3 THEN
   lv_field := lv_field || 'q1';
  ELSIF an_ntype = 4 THEN
   lv_field := lv_field || 'q2';
  ELSIF an_ntype = 5 THEN
   lv_field := lv_field || 'q3';
  ELSIF an_ntype = 6 THEN
   lv_field := lv_field || 'q4';
  ELSE
   lv_field := lv_field || 'er';
  END IF;

  IF an_datetype = 1 THEN
   lv_sql :=
    'SELECT max(date_time) FROM diftariff WHERE mid = ' || an_mid || ' and date_time <= to_date(''' || TO_CHAR (ad_date, 'ddmmyyyyhh24miss')
    || ''',''ddmmyyyyhh24miss'') and ' || lv_field || ' is not null ';
  ELSIF an_datetype = 2 THEN
   lv_sql :=
    'SELECT min(date_time) FROM diftariff WHERE mid = ' || an_mid || ' and date_time > to_date(''' || TO_CHAR (ad_date, 'ddmmyyyyhh24miss')
    || ''',''ddmmyyyyhh24miss'') and ' || lv_field || ' is not null ';
  END IF;

  EXECUTE IMMEDIATE lv_sql
               INTO ret;

  RETURN ret;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE setdebitindicdiff (an_mid NUMBER, ad_date DATE, an_ntype NUMBER, av_source VARCHAR2, av_remark VARCHAR2, av_mtrsn VARCHAR2, an_kc NUMBER, an_rm NUMBER,   --показания
 an_r NUMBER,   --расход
             an_debindic NUMBER   -- 1 показания 2 расход
 ) IS
  ln_handle       INTEGER;
  ln_ret          NUMBER;
  lv_sqlupd       VARCHAR2 (2000) DEFAULT 'UPDATE ';
  lv_sqlins       VARCHAR2 (2000) DEFAULT 'INSERT INTO ';
  lv_r            VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (ROUND (an_r, gn_2)), 'NULL');
  lv_rm           VARCHAR2 (200)  DEFAULT NVL (TO_CHAR (an_rm), 'NULL');
  i               NUMBER;
  ln_inc          NUMBER;
  lv_inc          VARCHAR2 (200);
  ln_a            NUMBER;
  ln_b            NUMBER;
  ln_c            NUMBER;
  lv_a            VARCHAR2 (200);
  lv_b            VARCHAR2 (200);
  lv_c            VARCHAR2 (200);
  ld_start_date   DATE            := indic_pg.getlastdate (an_mid, ad_date, an_ntype, NULL, 5, an_debindic);
  ld_fin_date     DATE            := ad_date;
  lv_add          VARCHAR2 (5);

  TYPE rpercentdata IS RECORD (
   ddate_time   DATE,
   naer         NUMBER,
   nber         NUMBER,
   ncer         NUMBER
  );

  TYPE tpercents IS TABLE OF rpercentdata
   INDEX BY BINARY_INTEGER;

  lt_percents     tpercents;

  CURSOR cr_percents_list IS
   SELECT   a.date_time, a.aer, a.ber, a.cer
       FROM diftariff a
      WHERE mid = an_mid AND date_time >= indic_pg.getdatepercent (an_mid, ad_date, 1, 1, 1) AND date_time < ad_date
   ORDER BY date_time;
 BEGIN
  IF an_ntype <> 1 THEN
   raise_application_error (-20001, 'Диффтаррифные акты поддерживаются только для актива' || CHR (10) || SQLERRM (SQLCODE));
  END IF;

  --  IF an_rm IS NULL THEN
    --   ld_Start_date := INDIC_PG.getlastdate(an_mid, ad_date, an_ntype, NULL, 5, 2);
  --  END IF;
  lt_percents.DELETE;
  i := 1;

  FOR cr IN cr_percents_list LOOP
   lt_percents (i).ddate_time := cr.date_time;
   lt_percents (i).naer := cr.aer;
   lt_percents (i).nber := cr.ber;
   lt_percents (i).ncer := cr.cer;
   i := i + 1;
  END LOOP;

  IF lt_percents.COUNT < 1 THEN
   raise_application_error (-20001, 'Не введена процентовка' || CHR (10) || SQLERRM (SQLCODE));
  END IF;

  IF lt_percents (1).ddate_time > ld_start_date THEN
   raise_application_error (-20001,
                            'Ввод данных невозможен. Дата первой процентовки больше чем дата последнего ввода данных '
                            || TO_CHAR (ld_start_date, 'dd.mm.yyyy hh24:mi:ss') || CHR (10) || SQLERRM (SQLCODE));
  END IF;

  --      raise_application_error(-20001, 'dfgdfgdfgdfg'|| CHR(10) || SQLERRM(SQLCODE));
  ln_inc := an_r / lt_percents.COUNT;
  lv_inc := NVL (TO_CHAR (ln_inc), 'NULL');
  ln_handle := SYS.DBMS_SQL.open_cursor;

  IF an_ntype = 2 THEN
   lv_add := 'ed';
  ELSIF an_ntype = 3 THEN
   lv_add := 'q1';
  ELSIF an_ntype = 4 THEN
   lv_add := 'q2';
  ELSIF an_ntype = 5 THEN
   lv_add := 'q3';
  ELSIF an_ntype = 6 THEN
   lv_add := 'q4';
  ELSE
   lv_add := 'er';
  END IF;

  FOR ii IN 1 .. lt_percents.COUNT LOOP   -- Шуршим по процентовке
   IF ld_start_date < lt_percents (ii).ddate_time THEN
    ld_start_date := lt_percents (ii).ddate_time;
   END IF;

   IF ii + 1 <= lt_percents.COUNT AND ld_fin_date > lt_percents (ii + 1).ddate_time THEN
    ld_fin_date := lt_percents (ii + 1).ddate_time;
   ELSE
    ld_fin_date := ad_date;
   END IF;

   ln_a := (ln_inc * lt_percents (ii).naer) / 100;
   ln_b := (ln_inc * lt_percents (ii).nber) / 100;
   ln_c := (ln_inc * lt_percents (ii).ncer) / 100;
   lv_a := NVL (TO_CHAR (ln_a), 'NULL');
   lv_b := NVL (TO_CHAR (ln_b), 'NULL');
   lv_c := NVL (TO_CHAR (ln_c), 'NULL');

   IF ld_fin_date = ad_date THEN
    lv_sqlupd :=
     lv_sqlupd || 'billorg SET ' || 'source=' || '''' || av_source || ''',' || 'remark=' || '''' || av_remark || ''',' || lv_add || '_MTRSN=''' || av_mtrsn || ''','
     || lv_add || '_KC=' || an_kc || ',' || lv_add || 'm = ' || lv_rm || ',' || lv_add || '=' || lv_inc || ',a' || lv_add || '=' || lv_a || ',b' || lv_add || '='
     || lv_b || ',c' || lv_add || '=' || lv_c || ' where mid=' || an_mid || ' and date_time=to_date(' || TO_CHAR (ad_date, 'YYYYMMDDHH24MISS')
     || ',''YYYYMMDDHH24MISS'')';
    lv_sqlins :=
     lv_sqlins || 'billorg (mid,date_time,' || 'source,remark,' || lv_add || '_MTRSN,' || lv_add || '_KC,' || lv_add || 'm,' || lv_add || ',a' || lv_add || ',b'
     || lv_add || ',c' || lv_add || ') VALUES(' || an_mid || ',to_date(' || TO_CHAR (ad_date, 'YYYYMMDDHH24MISS') || ',''YYYYMMDDHH24MISS''),' || '''' || av_source
     || ''',''' || av_remark || ''',''' || av_mtrsn || ''',' || an_kc || ',' || lv_rm || ',' || lv_inc || ',' || lv_a || ',' || lv_b || ',' || lv_c || ')';
   ELSE
    lv_sqlupd :=
     lv_sqlupd || 'billorg SET ' || 'source=' || '''' || av_source || ''',' || 'remark=' || '''' || av_remark || ''',' || lv_add || '_MTRSN=''' || av_mtrsn || ''','
     || lv_add || '_KC=' || an_kc || ',' || lv_add || '=' || lv_inc || ',a' || lv_add || '=' || lv_a || ',b' || lv_add || '=' || lv_b || ',c' || lv_add || '='
     || lv_c || ' where mid=' || an_mid || ' and date_time=to_date(' || TO_CHAR (ad_date, 'YYYYMMDDHH24MISS') || ',''YYYYMMDDHH24MISS'')';
    lv_sqlins :=
     lv_sqlins || 'billorg (mid,date_time,' || 'source,remark,' || lv_add || '_MTRSN,' || lv_add || '_KC,' || lv_add || ',a' || lv_add || ',b' || lv_add || ',c'
     || lv_add || ') VALUES(' || an_mid || ',to_date(' || TO_CHAR (ad_date, 'YYYYMMDDHH24MISS') || ',''YYYYMMDDHH24MISS''),' || '''' || av_source || ''','''
     || av_remark || ''',''' || av_mtrsn || ''',' || an_kc || ',' || lv_inc || ',' || lv_a || ',' || lv_b || ',' || lv_c || ')';
   END IF;

   SYS.DBMS_SQL.parse (ln_handle, lv_sqlupd, SYS.DBMS_SQL.native);

   IF SYS.DBMS_SQL.EXECUTE (ln_handle) = 0 THEN   --UPDATE не удался, значит INSERT
    SYS.DBMS_SQL.parse (ln_handle, lv_sqlins, SYS.DBMS_SQL.native);
    ln_ret := SYS.DBMS_SQL.EXECUTE (ln_handle);
   END IF;

   sethalfhouroldzone (an_mid, ld_start_date, ld_fin_date, an_ntype, av_source, av_mtrsn, an_kc, ln_inc, ln_a, ln_b, ln_c, NULL);
  END LOOP;
 EXCEPTION
  WHEN OTHERS THEN
   IF SYS.DBMS_SQL.is_open (ln_handle) THEN
    SYS.DBMS_SQL.close_cursor (ln_handle);
   END IF;

   raise_application_error (-20001, 'indic_pg.setDebitIndicDIFF: Ошибка вставки расхода. ' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
   -- Заносит расход по зонам дробля его по процентам поддерживает перерасчет следующего расхода
 PROCEDURE setdebitdiff (an_mid NUMBER, ad_date DATE, an_ntype NUMBER, av_source VARCHAR2, av_remark VARCHAR2, av_mtrsn VARCHAR2, an_kc NUMBER, an_rm NUMBER,   --показания
 an_r NUMBER
 )   --расход
  IS
  ln_handle    INTEGER;
  ld_next      DATE;
  ln_r         NUMBER;
  ln_rm        NUMBER  := an_rm;
  ln_next_r    NUMBER;
  ln_next_rm   NUMBER;
  ln_dig       NUMBER;
 BEGIN
  setdebitindicdiff (an_mid, ad_date, an_ntype, av_source, av_remark, av_mtrsn, an_kc, NULL, an_r, 2);
  -- Перещитываем следующий расход (если он канэчно эсть)
  ld_next := getnextdate (an_mid, ad_date, an_ntype, NULL /*an_zone*/, 5, 2);   --Дата след расхода

  IF ld_next IS NOT NULL THEN
   ln_next_r := getlastdebit (an_mid, ld_next + 1 / (24 * 60 * 60), an_ntype, NULL, 5);   --Следующие показания (вычисляем как предыдущие, для их даты+ 1 сек)
   setdebitindicdiff (an_mid, ld_next, an_ntype, av_source, av_remark, av_mtrsn, an_kc, NULL, ln_next_r, 2);
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   IF SYS.DBMS_SQL.is_open (ln_handle) THEN
    SYS.DBMS_SQL.close_cursor (ln_handle);
   END IF;

   raise_application_error (-20001, 'indic_pg.setdebitDIFF: Ошибка вставки расхода. ' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE setindicdiff (an_mid NUMBER, ad_date DATE, an_ntype NUMBER, av_source VARCHAR2, av_remark VARCHAR2, av_mtrsn VARCHAR2, an_kc NUMBER, an_rm NUMBER,   --показания
 an_r NUMBER
 )   --расход
  IS
  ln_handle    INTEGER;
  ld_next      DATE;
  ln_r         NUMBER;
  ln_rm        NUMBER  := an_rm;
  ln_next_r    NUMBER;
  ln_next_rm   NUMBER;
  ln_dig       NUMBER;
 BEGIN
  setdebitindicdiff (an_mid, ad_date, an_ntype, av_source, av_remark, av_mtrsn, an_kc, an_rm, an_r, 1);
  -- Перещитываем следующий расход (если он канэчно эсть)
  ld_next := getnextdate (an_mid, ad_date, an_ntype, NULL /*an_zone*/, 5, 1);   --Дата след показаний

  IF ld_next IS NOT NULL THEN
   ln_next_rm := getlastindic (an_mid, ld_next + 1 / (24 * 60 * 60), an_ntype, NULL, 5);   --Следующие показания (вычисляем как предыдущие, для их даты+ 1 сек)

   IF ln_rm IS NULL THEN   --Если текущие удалили, то для следующих предидущими будут предыдущие от текущих
    ln_rm := getlastindic (an_mid, ad_date, an_ntype, NULL, 5);
   END IF;

   SELECT MAX (digits)
     INTO ln_dig
     FROM meters
    WHERE mid = an_mid AND DECODE (entype, 7, an_ntype, entype) = an_ntype;

   ln_dig := POWER (10, LENGTH (TRUNC (ln_dig)));

   IF ln_dig IS NULL OR ln_dig <= ln_rm THEN
    ln_dig := POWER (10, LENGTH (TRUNC (ln_rm)));
   END IF;

   IF ln_next_rm >= ln_rm THEN
    ln_next_r := (ln_next_rm - ln_rm) * NVL (an_kc, 1);
   ELSE
    ln_next_r := (ln_dig + ln_next_rm - ln_rm) * NVL (an_kc, 1);
   END IF;

   setdebitindicdiff (an_mid, ld_next, an_ntype, av_source, av_remark, av_mtrsn, an_kc, ln_next_rm, ln_next_r, 1);
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   IF SYS.DBMS_SQL.is_open (ln_handle) THEN
    SYS.DBMS_SQL.close_cursor (ln_handle);
   END IF;

   raise_application_error (-20001, 'indic_pg.setIndicDIFF: Ошибка вставки расхода. ' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 /* Пересчитывает расход по показаниям (ad_date - стартовая дата > больше которой нужно пересчитать,
    возвращает дату следующих показаний или NULL - если дошли до конца)
    an_table =5 BILLORG иначе MONTHS
 */
 FUNCTION recalcdiff (an_mid NUMBER, ad_date DATE, an_table NUMBER DEFAULT 5)
  RETURN DATE IS
  ld_date     DATE;
  ln_digits   NUMBER;
  ln_erm      NUMBER;
  ln_edm      NUMBER;
  ln_q1m      NUMBER;
  ln_q3m      NUMBER;
  ln_q2m      NUMBER;
  ln_q4m      NUMBER;
  ln_aerm     NUMBER;
  ln_aedm     NUMBER;
  ln_aq1m     NUMBER;
  ln_aq3m     NUMBER;
  ln_aq2m     NUMBER;
  ln_aq4m     NUMBER;
  ln_berm     NUMBER;
  ln_bedm     NUMBER;
  ln_bq1m     NUMBER;
  ln_bq3m     NUMBER;
  ln_bq2m     NUMBER;
  ln_bq4m     NUMBER;
  ln_cerm     NUMBER;
  ln_cedm     NUMBER;
  ln_cq1m     NUMBER;
  ln_cq3m     NUMBER;
  ln_cq2m     NUMBER;
  ln_cq4m     NUMBER;
  ln_derm     NUMBER;
  ln_dedm     NUMBER;
  ln_dq1m     NUMBER;
  ln_dq3m     NUMBER;
  ln_dq2m     NUMBER;
  ln_dq4m     NUMBER;
 BEGIN
  SELECT LENGTH (TRUNC (MAX (digits)))
    INTO ln_digits
    FROM meters
   WHERE mid = an_mid AND entype = 7;

  IF an_table = 5 THEN   --Мы инвертируем, потому что знаем что set_bill_meter вернет назад
   FOR lc IN (SELECT *
                FROM billorg
               WHERE mid = an_mid AND date_time = (SELECT MIN (date_time)
                                                     FROM billorg
                                                    WHERE mid = an_mid AND date_time > ad_date)) LOOP
    ln_erm := lc.erm;
    ln_edm := lc.edm;
    ln_q1m := lc.q1m;
    ln_q3m := lc.q3m;
    ln_q2m := lc.q2m;
    ln_q4m := lc.q4m;
    ln_aerm := lc.aerm;
    ln_aedm := lc.aedm;
    ln_aq1m := lc.aq1m;
    ln_aq3m := lc.aq3m;
    ln_aq2m := lc.aq2m;
    ln_aq4m := lc.aq4m;
    ln_berm := lc.berm;
    ln_bedm := lc.bedm;
    ln_bq1m := lc.bq1m;
    ln_bq3m := lc.bq3m;
    ln_bq2m := lc.bq2m;
    ln_bq4m := lc.bq4m;
    ln_cerm := lc.cerm;
    ln_cedm := lc.cedm;
    ln_cq1m := lc.cq1m;
    ln_cq3m := lc.cq3m;
    ln_cq2m := lc.cq2m;
    ln_cq4m := lc.cq4m;
    ln_derm := lc.derm;
    ln_dedm := lc.dedm;
    ln_dq1m := lc.dq1m;
    ln_dq3m := lc.dq3m;
    ln_dq2m := lc.dq2m;
    ln_dq4m := lc.dq4m;
    util_pg.chdr (lc.mid, ln_erm, ln_edm, ln_q1m, ln_q3m, ln_q2m, ln_q4m);
    util_pg.chdr (lc.mid, ln_aerm, ln_aedm, ln_aq1m, ln_aq3m, ln_aq2m, ln_aq4m);
    util_pg.chdr (lc.mid, ln_berm, ln_bedm, ln_bq1m, ln_bq3m, ln_bq2m, ln_bq4m);
    util_pg.chdr (lc.mid, ln_cerm, ln_cedm, ln_cq1m, ln_cq3m, ln_cq2m, ln_cq4m);
    util_pg.chdr (lc.mid, ln_derm, ln_dedm, ln_dq1m, ln_dq3m, ln_dq2m, ln_dq4m);
    comsrv_pg.set_bill_meter (lc.mid, ln_erm, ln_edm, ln_q1m, ln_q3m, ln_q2m, ln_q4m, ln_aerm, ln_aedm, ln_aq1m, ln_aq3m, ln_aq2m, ln_aq4m, ln_berm, ln_bedm,
                              ln_bq1m, ln_bq3m, ln_bq2m, ln_bq4m, ln_cerm, ln_cedm, ln_cq1m, ln_cq3m, ln_cq2m, ln_cq4m, ln_derm, ln_dedm, ln_dq1m, ln_dq3m, ln_dq2m,
                              ln_dq4m, lc.er_mtrsn, ln_digits, lc.date_time);
    ld_date := lc.date_time;
   END LOOP;
  ELSE
   FOR lc IN (SELECT *
                FROM monthsorg
               WHERE mid = an_mid AND date_time = (SELECT MIN (date_time)
                                                     FROM monthsorg
                                                    WHERE mid = an_mid AND date_time > ad_date)) LOOP
    ln_erm := lc.erm;
    ln_edm := lc.edm;
    ln_q1m := lc.q1m;
    ln_q3m := lc.q3m;
    ln_q2m := lc.q2m;
    ln_q4m := lc.q4m;
    ln_aerm := lc.aerm;
    ln_aedm := lc.aedm;
    ln_aq1m := lc.aq1m;
    ln_aq3m := lc.aq3m;
    ln_aq2m := lc.aq2m;
    ln_aq4m := lc.aq4m;
    ln_berm := lc.berm;
    ln_bedm := lc.bedm;
    ln_bq1m := lc.bq1m;
    ln_bq3m := lc.bq3m;
    ln_bq2m := lc.bq2m;
    ln_bq4m := lc.bq4m;
    ln_cerm := lc.cerm;
    ln_cedm := lc.cedm;
    ln_cq1m := lc.cq1m;
    ln_cq3m := lc.cq3m;
    ln_cq2m := lc.cq2m;
    ln_cq4m := lc.cq4m;
    ln_derm := lc.derm;
    ln_dedm := lc.dedm;
    ln_dq1m := lc.dq1m;
    ln_dq3m := lc.dq3m;
    ln_dq2m := lc.dq2m;
    ln_dq4m := lc.dq4m;
    util_pg.chdr (lc.mid, ln_erm, ln_edm, ln_q1m, ln_q3m, ln_q2m, ln_q4m);
    util_pg.chdr (lc.mid, ln_aerm, ln_aedm, ln_aq1m, ln_aq3m, ln_aq2m, ln_aq4m);
    util_pg.chdr (lc.mid, ln_berm, ln_bedm, ln_bq1m, ln_bq3m, ln_bq2m, ln_bq4m);
    util_pg.chdr (lc.mid, ln_cerm, ln_cedm, ln_cq1m, ln_cq3m, ln_cq2m, ln_cq4m);
    util_pg.chdr (lc.mid, ln_derm, ln_dedm, ln_dq1m, ln_dq3m, ln_dq2m, ln_dq4m);
    comsrv_pg.set_months_meter (lc.mid, ln_erm, ln_edm, ln_q1m, ln_q3m, ln_q2m, ln_q4m, ln_aerm, ln_aedm, ln_aq1m, ln_aq3m, ln_aq2m, ln_aq4m, ln_berm, ln_bedm,
                                ln_bq1m, ln_bq3m, ln_bq2m, ln_bq4m, ln_cerm, ln_cedm, ln_cq1m, ln_cq3m, ln_cq2m, ln_cq4m, ln_derm, ln_dedm, ln_dq1m, ln_dq3m,
                                ln_dq2m, ln_dq4m, lc.er_mtrsn, ln_digits, lc.date_time);
    ld_date := lc.date_time;
   END LOOP;
  END IF;

  RETURN ld_date;
 END;

------------------------------------------------------------------------------------------------------------------------
   -- Устанавливает признак включения, исключения из расчета.
 PROCEDURE setexceptcalc (an_mid NUMBER, ad_date DATE, an_source NUMBER, an_exceptcalc NUMBER) IS
  lv_state   VARCHAR2 (16);
 BEGIN
  gn_task_code := 630;

  IF an_exceptcalc IS NULL THEN
   lv_state := 'ВКЛЮЧЕН';
  ELSE
   lv_state := 'ИСКЛЮЧЕН';
  END IF;

  UPDATE halfhourold
     SET nexceptcalc = an_exceptcalc
   WHERE mid = an_mid AND date_time = ad_date AND nsource = an_source;

  admin_pg.fiscal_p (gn_task_code, 2,
                     'Изменено состояние включения в расчет на ''' || lv_state || ''' за ' || TO_CHAR (ad_date, 'DD.MM.YYYY HH24:MI:SS') || ' по точке учета '
                     || util_pg.node_path_f (an_mid, 'points', 'mid', 'parent'));
 END;

------------------------------------------------------------------------------------------------------------------------
    -- Ввод поправок.
 PROCEDURE setcorrection (an_mid NUMBER, ad_from DATE, ad_till DATE, an_er NUMBER, an_ed NUMBER, an_q1 NUMBER, an_q2 NUMBER, an_q3 NUMBER, an_q4 NUMBER) IS
  cn_step   CONSTANT NUMBER              DEFAULT 1 / 48;
  ld_from            DATE                DEFAULT ad_from + 1 / 86400;
  ld_till            DATE                DEFAULT ad_till;
  ln_kc              NUMBER;
  lt_info            averrate_pg.ttinfo;
  lt_val             common_pg.tt_number;
  ln_tmp             NUMBER;
 BEGIN
  SELECT MAX (kc)
    INTO ln_kc
    FROM feeders
   WHERE mid = an_mid;

  DELETE FROM halfhour
        WHERE mid = an_mid AND date_time > ld_from AND date_time <= util_pg.ceil_d (ld_till, cn_step)
              AND nsource IN (util_pg.cn_manualinput, util_pg.cn_manualinputw);

  lt_val (1) := an_er;
  lt_val (2) := an_ed;
  lt_val (3) := an_q1;
  lt_val (4) := an_q2;
  lt_val (5) := an_q3;
  lt_val (6) := an_q4;

  FOR j IN 1 .. 6 LOOP
   IF lt_val (j) IS NOT NULL THEN
    averrate_pg.createtinfo (an_mid, ld_from, ld_till, j, 0, lt_val (j), lt_info);

    FOR i IN 1 .. lt_info.COUNT LOOP
     ln_tmp := lt_info (i).e;

     UPDATE halfhour
        SET er = DECODE (j, 1, ln_tmp, er),
            ed = DECODE (j, 2, ln_tmp, ed),
            q1 = DECODE (j, 3, ln_tmp, q1),
            q2 = DECODE (j, 4, ln_tmp, q2),
            q3 = DECODE (j, 5, ln_tmp, q3),
            q4 = DECODE (j, 6, ln_tmp, q4),
            nkc = ln_kc
      WHERE mid = an_mid AND date_time = lt_info (i).d AND nsource = lt_info (i).src;

     IF SQL%ROWCOUNT = 0 THEN
      INSERT INTO halfhour
                  (mid, date_time, nsource, er, ed, q1,
                   q2, q3, q4, nkc
                  )
           VALUES (an_mid, lt_info (i).d, lt_info (i).src, DECODE (j, 1, ln_tmp, NULL), DECODE (j, 2, ln_tmp, NULL), DECODE (j, 3, ln_tmp, NULL),
                   DECODE (j, 4, ln_tmp, NULL), DECODE (j, 5, ln_tmp, NULL), DECODE (j, 6, ln_tmp, NULL), ln_kc
                  );
     END IF;
    END LOOP;
   END IF;
  END LOOP;

  file_pg.startbyevents_p (47, an_mid, ld_from, ld_till);
  das_pg.calcpoint4bill (an_mid, TRUNC (ld_from), util_pg.ceil_d (ld_till, 1));
  admin_pg.fiscal_p (gn_task_code, 1,
                     'Произведен ввод поправки за период с ' || TO_CHAR (ad_from, 'DD.MM.YYYY HH24:MI') || ' по ' || TO_CHAR (ad_till, 'DD.MM.YYYY HH24:MI')
                     || ' по точке учета ' || util_pg.node_path_f (an_mid, 'points', 'mid', 'parent'));
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20001, 'indic_pg.setcorrection: Ошибка ввода поправки. ' || CHR (10) || SQLERRM (SQLCODE));
 END;
------------------------------------------------------------------------------------------------------------------------
BEGIN
 BEGIN
  SELECT TO_NUMBER (MAX (vvalue))
    INTO gn_outputgroup
    FROM parameter
   WHERE npid = 13;
 EXCEPTION
  WHEN OTHERS THEN
   gn_outputgroup := NULL;
 END;
END;   -- Package Body INDIC_PG
/


