  --возвращает сдвиг в часах согласно временной зоне
 FUNCTION get_hourtimezone
  RETURN NUMBER IS
 BEGIN
  RETURN gn_timezoneshift;
 END;

-------------------------------------------------------------------------------------------------------------
  --возвращает  an_midTimeZone;
 PROCEDURE set_timezone (an_midtimezone NUMBER) IS
 BEGIN
  gn_timezone := an_midtimezone;

  SELECT -NVL (MAX (nshift) / 24, 0)
    INTO gn_timezoneshift
    FROM timezones
   WHERE nid = an_midtimezone;
 END;

 ---------------------------------------------------------------------------------------------------------------
--// Для перемещения по спискам
 PROCEDURE interior_groupjump (an_groupislist NUMBER, an_stepprofile NUMBER, an_id_group NUMBER, an_period NUMBER, an_periodstart NUMBER, an_periodfinish NUMBER,
 acur_t OUT common_pg.tcur
 )   --TInterior::GroupJump(long value) // Для перемещения по спискам
  IS
  lv_sql         VARCHAR (4000);
  lv_subselect   VARCHAR (1000);
 BEGIN
  subselect_p (an_stepprofile, lv_subselect);

  IF (an_groupislist = 2) THEN
   lv_sql := ' SELECT nvl(max(g.gid),0) gid FROM groups g1, groups g
       WHERE g1.gid=:par1 AND g1.nroot2 = g.nroot2 AND g.nroot1 IS NULL  ' || lv_subselect;
  ELSE
   lv_sql := ' SELECT nvl(sum(decode(nroot2, NULL, 1, 2)),0) GroupIsList
     FROM groups g WHERE gid = :par1 AND nroot1 > 10  ' || lv_subselect;
  END IF;

  IF (an_stepprofile = gn_stpmonth) THEN
   OPEN acur_t FOR lv_sql USING an_id_group, an_periodfinish, an_periodstart;
  ELSE
   OPEN acur_t FOR lv_sql USING an_id_group, an_period;
  END IF;
 END;

