--возвращает кусок SQL-кода в зависимости от входящих параметров
 PROCEDURE takeofpartquerifornsorse_p (an_ispoints NUMBER, an_stepprofile NUMBER, av_rowcount VARCHAR2, ad_firstdate DATE, ad_lastdate DATE,
 av_decnsourcesec OUT VARCHAR2, av_decnsourcef OUT VARCHAR2
 ) IS
  cv_sm   CONSTANT VARCHAR2 (256) := 'qm_pg.sumqm(nvl(SUMQM(nvl(p.vqm,qm_pg.defqm)),qm_pg.defqm),qm_pg.defqm),nvl(SUMQM(nvl(p.vqm,qm_pg.defqm)),qm_pg.defqm)';
  lv_rc1           VARCHAR2 (400);
  lv_rc2           VARCHAR2 (400);
 BEGIN
  lv_rc1 := ' ';
  lv_rc2 := ' ';

  IF gn_timezoneshift <> 0 THEN   --для таблицы halfhour
   lv_rc1 := '*48+max(decode((to_char(date_time-1/86400- interior_pg.get_hourtimezone, ''mm'' )),3,-2,10,2,0))';
   lv_rc2 := ' * max(util_pg.get_count_dt (date_time-1/86400- interior_pg.get_hourtimezone, 1/48 ))';
  ELSE
   lv_rc1 := ' ';
   lv_rc2 := ' ';
  END IF;

  IF (an_stepprofile = gn_stpmonth) THEN   --год
   av_decnsourcef :=
    ' ,decode(sign(util_pg.get_countpoint_f(:par3, ' || an_ispoints
    || ' )
   *to_char(trunc(add_months(:par1,0+to_char(date_time-1/86400- interior_pg.get_hourtimezone, ''mm'' )))
   -1/86400,''dd'' )' || lv_rc1 || '-count(*)),1,' || cv_sm || ') ';
   av_decnsourcesec := ' ,decode(sign(util_pg.get_countpoint_f(:par3, ' || an_ispoints || ' )*round(:par2-:par1)*48
    -count(*)),1,' ||  cv_sm || ') ';
  ELSIF (an_stepprofile = gn_stpday) THEN   --месяц
   av_decnsourcef := ' ,decode(sign(util_pg.get_countpoint_f(:par3, ' || an_ispoints || ' )
   ' ||              lv_rc2 || '-count(*)),1,' || cv_sm || ') ';
   av_decnsourcesec := ' ,decode(sign(util_pg.get_countpoint_f(:par3, ' || an_ispoints || ' )*
   ' ||                av_rowcount || lv_rc1 || '-count(*)),1,' || cv_sm || ') ';
  ELSE   -- получасовки и сутки
   av_decnsourcef := ' ,decode(sign(util_pg.get_countpoint_f(:par3, ' || an_ispoints || ' )-count(*)),1,' || cv_sm || ') ';
   av_decnsourcesec := ' ,decode(sign(util_pg.get_countpoint_f(:par3, ' || an_ispoints || ' ) * ' || av_rowcount || '-count(*)),1,' || cv_sm || ') ';
  END IF;
