   av_decnsourcef :=  ' ,decode(sign(util_pg.get_countpoint_f(:par3, ' || an_ispoints || ' )*to_char(trunc(add_months(:par1,0+to_char(date_time-1/86400+ interior_pg.get_hourtimezone, ''mm'' )))-1/86400,''dd'' )'||lv_rc||'-count(*)),1,'||cv_sm||') ';
   av_decnsourcesec :=' ,decode(sign(util_pg.get_countpoint_f(:par3, ' || an_ispoints || ' )*round(:par2-:par1)'||lv_rc||' -count(*)),1,'||cv_sm||') ';
  ELSIF (an_stepprofile = gn_stpday) THEN
   av_decnsourcef :=  ' ,decode(sign(util_pg.get_countpoint_f(:par3, ' || an_ispoints || ' )'||lv_rc||'-count(*)),1,'||cv_sm||') ';
   av_decnsourcesec :=' ,decode(sign(util_pg.get_countpoint_f(:par3, ' || an_ispoints || ' )*'|| av_rowcount || lv_rc ||'-count(*)),1,'||cv_sm||') ';
  ELSE
