   av_decnsourcesec :=' ,decode(sign(util_pg.get_countpoint_f(:par3, ' || an_ispoints || ' ) * ' || av_rowcount ||'-count(*)),1,'||cv_sm||') ';
  END IF;*/
 END;

-------------------------------------------------------------------------------------------------------------
 PROCEDURE subselect_p (an_stepprofile NUMBER, av_subselect OUT VARCHAR2) IS
 BEGIN
  IF (an_stepprofile = gn_stpmonth) THEN
   av_subselect := ' AND ( nvl(nfromperiod,0)<=:par51 OR nvl(ntillperiod,299912)>=:par50) ';
  ELSE
   av_subselect := ' AND (:par50 BETWEEN  nvl(nfromperiod,0) AND nvl(ntillperiod,299912)) ';
  END IF;
 END;

-----------------------------------------------------------------------------------------------------------------------------
 PROCEDURE grouping_p (an_stepprofile NUMBER, av_grouping OUT VARCHAR2) IS
 BEGIN
  IF (an_stepprofile = gn_stpmonth) THEN
   av_grouping := ' 0+to_char(date_time-1/86400- interior_pg.get_hourtimezone,''mm'') ';
  ELSIF (an_stepprofile = gn_stpday) THEN
   av_grouping := ' 0+to_char(date_time-1/86400- interior_pg.get_hourtimezone,''dd'') ';
  ELSIF (an_stepprofile = gn_stphour) THEN
   /* av_grouping := ' 1+FLOOR((date_time+ interior_pg.get_hourtimezone-:par1)*86400/:par4) ';*/
   av_grouping := ' util_pg.get_num_dt (date_time-1/86400,nsource, 1/:par4 ,0,interior_pg.get_hourtimezone) ';
  ELSIF (an_stepprofile = gn_stpminute) THEN
   av_grouping := ' 1+FLOOR((date_time-interior_pg.get_hourtimezone-:par1)*86400/:par4) ';
  END IF;
 END;

---------------------------------------------------------------------------------------------------------------------
-- возвращает имя таблицы
 PROCEDURE interior2_choiceoftable_p (an_bird NUMBER, an_stepprofile NUMBER, av_oracletable OUT VARCHAR2) IS
 BEGIN
  IF (an_stepprofile = gn_stpmonth OR an_stepprofile = gn_stpday) AND gn_timezoneshift = 0 THEN
   av_oracletable := ' bill ';
  ELSIF (an_stepprofile = gn_stphour OR an_stepprofile = gn_stpmonth OR an_stepprofile = gn_stpday) THEN
   av_oracletable := ' halfhour ';
  ELSIF (an_stepprofile = gn_stpminute) THEN
   av_oracletable := ' profile ';
  END IF;

  IF (an_bird = 1) THEN
   av_oracletable := av_oracletable || '_l';
  ELSIF (an_bird = 2) THEN
   av_oracletable := av_oracletable || '_ol';
  END IF;
 END;

-----------------------------------------------------------------------------------------------------------------------
 PROCEDURE ispoint_p (an_mid NUMBER, an_ind OUT NUMBER) IS
 BEGIN
  SELECT MAX (p.ind)
    INTO an_ind
    FROM points p
   WHERE p.mid = an_mid;
 END;

----------------------------------------------------------------------------------------------------------------------------
 PROCEDURE interior1_selectdata_p (an_ispoints NUMBER, an_stepprofile NUMBER, an_codetemplate NUMBER, av_rowcount VARCHAR2, an_bird NUMBER, an_powerprofile NUMBER,   --// Количество строк при выводе графика нагрузки
 an_stepprof NUMBER,   --//Минимальный шаг профиля в секундах
                    av_firstdate VARCHAR2, av_lastdate VARCHAR2, an_idgroup NUMBER, an_periodforyearstart NUMBER, an_periodforyearfinish NUMBER, an_period NUMBER,
 acur_t OUT common_pg.tcur
 ) IS
  lv_powkoef         VARCHAR2 (200);   -- // Коэффициент для перевода в мощность Для ГН и Тех. профиля
  lv_inverted        VARCHAR2 (150);
  lv_subsel          VARCHAR2 (400);
  lv_subselect       VARCHAR2 (400);
  lv_table           VARCHAR2 (150);
  lv_partly_er       VARCHAR2 (400);
  lv_partly_ed       VARCHAR2 (400);
  lv_decnsourcesec   VARCHAR2 (1000);
  lv_decnsourcef     VARCHAR2 (1000);
  lv_decperiod       VARCHAR2 (400);
  lv_paramlist       VARCHAR2 (2000);
  lv_grouping        VARCHAR2 (200);
  lv_oracletable     VARCHAR2 (150);
  lv_firstdate       DATE;
  lv_lastdate        DATE;
  lv_sql             VARCHAR2 (10000);
  lv_sql1            VARCHAR2 (4000);
  lv_sql2            VARCHAR2 (4000);
  lv_sql3            VARCHAR2 (4000);
  lv_sql4            VARCHAR2 (4000);
-----------------------------------
 BEGIN
  lv_firstdate := TO_DATE (av_firstdate, 'dd.mm.yyyy hh24:mi:ss') + interior_pg.get_hourtimezone;
  lv_lastdate := TO_DATE (av_lastdate, 'dd.mm.yyyy hh24:mi:ss') + interior_pg.get_hourtimezone;
  takeofpartquerifornsorse_p (an_ispoints, an_stepprofile, av_rowcount, lv_firstdate, lv_lastdate, lv_decnsourcesec, lv_decnsourcef);
  decperiod_p (an_ispoints, lv_decperiod);
  interior2_choiceoftable_p (an_bird, an_stepprofile, lv_oracletable);
  subselect_p (an_stepprofile, lv_subselect);
  grouping_p (an_stepprofile, lv_grouping);
  lv_powkoef := ' ';

  IF (an_ispoints = 1) THEN
   lv_inverted := ' ''n'' ';

   IF util_pg.isfolder (an_idgroup) = 1 THEN
    lv_subsel := ' G.mid in (select mid from points connect by prior mid=parent and prior ind not in (3,4) start with mid=:par3) ';
   ELSE
    lv_subsel := ' G.mid=:par3 ';
   END IF;

   lv_table := ' points ';
   lv_partly_er := ' ';
   lv_partly_ed := ' ';
  ELSE
   lv_inverted := 'G.inverted';
   lv_subsel :=
    ' G.gid in (select gid from groups connect by ((prior gid=parent) or (prior NROOT2=NROOT2 and prior nroot1>0 and nroot1 is null) ' || lv_subselect
    || ') start with gid=:par3 ' || lv_subselect || ') ';
   lv_table := ' groups ';
   lv_partly_er := ' *decode(g.NPARTLY,2,0,1) ';
   lv_partly_ed := ' *decode(g.NPARTLY,1,0,1) ';
  END IF;

  IF (an_codetemplate = gn_aebo_pow_f OR an_codetemplate = gn_aero_pow_f OR an_codetemplate = gn_aedo_pow_f OR an_codetemplate = gn_rebo_pow_f
      OR an_codetemplate = gn_rero_pow_f OR an_codetemplate = gn_redo_pow_f
     ) THEN
   IF (an_stepprofile = gn_stphour) THEN
    lv_powkoef := '* ' || (60 / an_powerprofile);
   ELSIF (an_stepprofile = gn_stpminute) THEN
    lv_powkoef := '* ' || (3600 / an_stepprof);
   END IF;
  END IF;

  IF (an_codetemplate = gn_aebo_f OR an_codetemplate = gn_aebo_pow_f OR an_codetemplate = gn_aebo_sum_f) THEN
   lv_paramlist :=
    ' ,sum( -util_pg.sld( P.mid, nvl(P.er ' || lv_powkoef || lv_partly_er || ' ,0), (nvl(P.ed ' || lv_powkoef || lv_partly_ed || ' ,0) )) *DECODE( ' || lv_inverted
    || ' ,''y'',1,-1) ' || lv_decperiod || ' )/1000 ';
  ELSIF (an_codetemplate = gn_aero_f OR an_codetemplate = gn_aero_pow_f OR an_codetemplate = gn_aero_sum_f OR an_codetemplate = gn_water_f
         OR an_codetemplate = gn_heat_f OR an_codetemplate = gn_gas_f
        ) THEN
   lv_paramlist :=
    ' ,sum(DECODE( ' || lv_inverted || ' ,''y'',nvl(P.ed ' || lv_powkoef || lv_partly_ed || ' ,0),nvl(P.er ' || lv_powkoef || lv_partly_er || ' ,0)) '
    || lv_decperiod || ' )/1000  ';
  ELSIF (an_codetemplate = gn_aedo_f OR an_codetemplate = gn_aedo_pow_f OR an_codetemplate = gn_aedo_sum_f) THEN
   lv_paramlist :=
    ' ,sum(DECODE( ' || lv_inverted || ' ,''y'',nvl(P.er ' || lv_powkoef || lv_partly_er || ' ,0), nvl(P.ed ' || lv_powkoef || lv_partly_ed || ' ,0)) '
    || lv_decperiod || ' )/1000 ';
  ELSIF (an_codetemplate = gn_rebo_f OR an_codetemplate = gn_rebo_pow_f OR an_codetemplate = gn_rebo_sum_f) THEN
   lv_paramlist :=
    ' ,(sum(( -util_pg.sld( P.mid, nvl(P.q1 ' || lv_powkoef || ' ,0), nvl(P.q3 ' || lv_powkoef || ' ,0)))*DECODE( ' || lv_inverted || ' ,''y'',1,-1) '
    || lv_decperiod || ' ) + sum(( -util_pg.sld( P.mid, nvl(P.q2 ' || lv_powkoef || ' ,0), nvl(P.q4 ' || lv_powkoef || ' ,0)))*DECODE( ' || lv_inverted
    || ' ,''y'',1,-1) ' || lv_decperiod || ' ))/1000 ';
  ELSIF (an_codetemplate = gn_rero_f OR an_codetemplate = gn_rero_pow_f OR an_codetemplate = gn_rero_sum_f) THEN
   lv_paramlist :=
    ' ,(sum(DECODE( ' || lv_inverted || ' ,''y'',nvl(P.q3 ' || lv_powkoef || ' ,0),nvl(P.q1 ' || lv_powkoef || ' ,0)) ' || lv_decperiod || ' ) + sum(DECODE( '
    || lv_inverted || ' ,''y'',nvl(P.q4 ' || lv_powkoef || ' ,0),nvl(P.q2 ' || lv_powkoef || ' ,0)) ' || lv_decperiod || ' ))/1000 ';
  ELSIF (an_codetemplate = gn_redo_f OR an_codetemplate = gn_redo_pow_f OR an_codetemplate = gn_redo_sum_f) THEN
   lv_paramlist :=
    ' ,(sum(DECODE( ' || lv_inverted || ' ,''y'',nvl(P.q1 ' || lv_powkoef || ' ,0),nvl(P.q3 ' || lv_powkoef || ' ,0)) ' || lv_decperiod || ' ) + sum(DECODE( '
    || lv_inverted || ' ,''y'',nvl(P.q2 ' || lv_powkoef || ' ,0),nvl(P.q4 ' || lv_powkoef || ' ,0)) ' || lv_decperiod || ' ))/1000 ';
  END IF;

  lv_sql :=
   'select ' || lv_grouping || ' BGroup ' || lv_paramlist || ' AParam ' || lv_decnsourcef || ' decnsour from  ' || lv_oracletable || '  P, ' || lv_table
   || '  G where P.mid=G.mid AND date_time>= :par1 and   date_time <= :par2 and ' || lv_subsel || '  group by ' || lv_grouping || ' union all select 0 BGroup '
   || lv_paramlist || ' AParam ' || lv_decnsourcesec || ' decnsour from  ' || lv_oracletable || '  P, ' || lv_table
   || '  G where P.mid=G.mid AND date_time >= :par1 and   date_time <= :par2 and  ' || lv_subsel || '  order by 1 ';

  IF (an_stepprofile = gn_stpmonth) THEN   --Месяц
   IF (an_ispoints = 1) THEN
    OPEN acur_t FOR lv_sql
    USING an_idgroup, lv_firstdate, lv_firstdate, lv_lastdate, an_idgroup, an_idgroup, lv_lastdate, lv_firstdate, lv_firstdate, lv_lastdate, an_idgroup;
   ELSE
    OPEN acur_t FOR lv_sql
    USING an_idgroup, lv_firstdate, lv_firstdate, lv_lastdate, an_periodforyearfinish, an_periodforyearstart, an_idgroup, an_periodforyearfinish,
          an_periodforyearstart, an_idgroup, lv_lastdate, lv_firstdate, lv_firstdate, lv_lastdate, an_periodforyearfinish, an_periodforyearstart, an_idgroup,
          an_periodforyearfinish, an_periodforyearstart;
   END IF;
  ELSIF (an_stepprofile = gn_stpday) THEN   --День
   IF (an_ispoints = 1) THEN
    OPEN acur_t FOR lv_sql USING an_idgroup, lv_firstdate, lv_lastdate, an_idgroup, an_idgroup, lv_firstdate, lv_lastdate, an_idgroup;
   ELSE
    OPEN acur_t FOR lv_sql
    USING an_idgroup, lv_firstdate, lv_lastdate, an_period, an_idgroup, an_period, an_idgroup, lv_firstdate, lv_lastdate, an_period, an_idgroup, an_period;
   END IF;
  ELSIF (an_stepprofile = gn_stphour) THEN   --Час
   IF (an_ispoints = 1) THEN
    OPEN acur_t FOR lv_sql
--    USING lv_firstdate, an_powerprofile * 60, an_idgroup, lv_firstdate, lv_lastdate, an_idgroup, lv_firstdate, an_powerprofile * 60, an_idgroup, lv_firstdate,
--          lv_lastdate, an_idgroup;
    USING an_stepprof, an_idgroup, lv_firstdate, lv_lastdate, an_idgroup, an_stepprof, an_idgroup, lv_firstdate, lv_lastdate, an_idgroup;
   ELSE
    OPEN acur_t FOR lv_sql
    -- USING lv_firstdate, an_powerprofile * 60, an_idgroup, lv_firstdate, lv_lastdate, an_period, an_idgroup, an_period, lv_firstdate, an_powerprofile * 60,
     --      an_idgroup, lv_firstdate, lv_lastdate, an_period, an_idgroup, an_period;
    USING an_stepprof, an_idgroup, lv_firstdate, lv_lastdate, an_period, an_idgroup, an_period, an_stepprof, an_idgroup, lv_firstdate, lv_lastdate, an_period,
          an_idgroup, an_period;
   END IF;
  ELSIF (an_stepprofile = gn_stpminute) THEN   --Минуты
   IF (an_ispoints = 1) THEN
    OPEN acur_t FOR lv_sql
    USING lv_firstdate, an_stepprof, an_idgroup, lv_firstdate, lv_lastdate, an_idgroup, lv_firstdate, an_stepprof, an_idgroup, lv_firstdate, lv_lastdate,
          an_idgroup;
   ELSE
    OPEN acur_t FOR lv_sql
    USING lv_firstdate, an_stepprof, an_idgroup, lv_firstdate, lv_lastdate, an_period, an_idgroup, an_period, lv_firstdate, an_stepprof, an_idgroup, lv_firstdate,
          lv_lastdate, an_period, an_idgroup, an_period;
   END IF;
  END IF;
--  insert into tmp_vil values('par4='||an_powerprofile * 60||' '||lv_sql);
--  commit;
 END;

-----------------------------------------------------------------------------------------------------------------------------
 PROCEDURE interior2_selectdata_p (an_ispoints NUMBER,   --группа или точка fd-> IsPoints
                                                      an_stepprofile NUMBER,   -- детализация fd->StepProfile
                                                                            an_codetemplate NUMBER,   --код монитора fd->CodeTemplate
                                                                                                   av_rowcount VARCHAR2,   -- RowCount
                                                                                                                        an_bird NUMBER,   --//переменная состояния. задается на форме fd->bird
 an_powerprofile NUMBER,   --// Количество строк при выводе графика нагрузки
                        an_stepprof NUMBER,   --//Минимальный шаг профиля в секундах
                                           av_firstdate VARCHAR2, av_lastdate VARCHAR2, an_idgroup NUMBER, an_periodforyearstart NUMBER,
 an_periodforyearfinish NUMBER, an_period NUMBER, acur_t OUT common_pg.tcur
 ) IS
  lv_powkoef         VARCHAR2 (400);   -- // Коэффициент для перевода в мощность Для ГН и Тех. профиля
  lv_inverted        VARCHAR2 (150);
  lv_subsel          VARCHAR2 (1000);
  lv_subselect       VARCHAR2 (1000);
  lv_table           VARCHAR2 (150);
  lv_partly_er       VARCHAR2 (600);
  lv_partly_ed       VARCHAR2 (600);
  lv_decnsourcesec   VARCHAR2 (1000);
  lv_decnsourcef     VARCHAR2 (1000);
  lv_decperiod       VARCHAR2 (600);
  lv_paramlist       VARCHAR2 (2000);
  lv_grouping        VARCHAR2 (600);
  lv_oracletable     VARCHAR2 (150);
  lv_firstdate       DATE;
  lv_lastdate        DATE;
  lv_sql             VARCHAR2 (8000);
-----------------------------------
 BEGIN
  lv_firstdate := (TO_DATE (av_firstdate, 'dd.mm.yyyy hh24:mi:ss') + interior_pg.get_hourtimezone);
  lv_lastdate := (TO_DATE (av_lastdate, 'dd.mm.yyyy hh24:mi:ss') + interior_pg.get_hourtimezone);
  takeofpartquerifornsorse_p (an_ispoints,   --группа или точка
                              an_stepprofile,   -- детализация
                              av_rowcount,   --
                              lv_firstdate, lv_lastdate, lv_decnsourcesec, lv_decnsourcef);
  decperiod_p (an_ispoints,   --группа или точка
               lv_decperiod);
  interior2_choiceoftable_p (an_bird, an_stepprofile, lv_oracletable);
  subselect_p (an_stepprofile, lv_subselect);
  grouping_p (an_stepprofile, lv_grouping);
  lv_powkoef := ' ';

  IF (an_ispoints = 1) THEN
   lv_inverted := ' ''n'' ';

   IF util_pg.isfolder (an_idgroup) = 1 THEN
    lv_subsel := ' G.mid in (select mid from points connect by prior mid=parent and prior ind not in (3,4) start with mid=:par3) ';
   ELSE
    lv_subsel := ' G.mid=:par3 ';
   END IF;
   lv_table := ' points ';
   lv_partly_er := ' ';
   lv_partly_ed := ' ';
  ELSE
   lv_inverted := 'G.inverted';
   lv_subsel :=
    ' G.gid in (select gid from groups connect by ((prior gid=parent) or
          (prior NROOT2=NROOT2 and prior nroot1>0 and nroot1 is null) ' || lv_subselect || ') start with gid=:par3 ' || lv_subselect || ') ';
   lv_table := ' groups ';
   lv_partly_er := ' *decode(g.NPARTLY,2,0,1) ';
   lv_partly_ed := ' *decode(g.NPARTLY,1,0,1) ';
  END IF;

  IF (an_codetemplate = gn_aebo_rebo_pow_f OR an_codetemplate = gn_aero_aedo_pow_f OR an_codetemplate = gn_rero_redo_pow_f OR an_codetemplate = gn_rq2_rq3_pow_f
      OR an_codetemplate = gn_rq1_rq4_pow_f
     ) THEN
   IF (an_stepprofile = gn_stphour) THEN
    lv_powkoef := '* ' || TO_CHAR (60.0 / an_powerprofile);
   ELSIF (an_stepprofile = gn_stpminute) THEN
    lv_powkoef := '* ' || TO_CHAR (3600.0 / an_stepprof);
   END IF;
  END IF;

  IF (an_codetemplate = gn_aebo_rebo_f OR an_codetemplate = gn_aebo_rebo_pow_f OR an_codetemplate = gn_aebo_rebo_sum_f) THEN
   lv_paramlist :=
    ' ,sum((-util_pg.sld( P.mid,nvl(P.er ' || lv_powkoef || lv_partly_er || ',0),nvl(P.ed ' || lv_powkoef || lv_partly_ed || ' ,0)))
             *DECODE( ' || lv_inverted || ' ,''y'',1,-1) ' || lv_decperiod || ' )/1000 AParam,
			 (sum((-util_pg.sld(P.mid,nvl(P.q1 ' || lv_powkoef || ' ,0),nvl(P.q3 ' || lv_powkoef || ' ,0)))
             *DECODE( ' || lv_inverted || ' ,''y'',1,-1) ' || lv_decperiod || ' ) +
             sum((-util_pg.sld(P.mid,nvl(P.q2 ' || lv_powkoef || ' ,0),nvl(P.q4 ' || lv_powkoef || ' ,0)))
             *DECODE( ' || lv_inverted || ' ,''y'',1,-1) ' || lv_decperiod || ' ))/1000 BParam ';
  ELSIF (an_codetemplate = gn_aero_aedo_f OR an_codetemplate = gn_aero_aedo_pow_f OR an_codetemplate = gn_aero_aedo_sum_f) THEN
   lv_paramlist :=
    ' ,sum(DECODE( ' || lv_inverted || ' ,''y'',nvl(P.ed ' || lv_powkoef || lv_partly_ed || ',0),
                  nvl(P.er ' || lv_powkoef || lv_partly_er || ' ,0)) ' || lv_decperiod || ' )/1000 AParam,
			 sum(DECODE( ' || lv_inverted || ' ,''y'',nvl(P.er ' || lv_powkoef || lv_partly_er || ' ,0),
             nvl(P.ed ' || lv_powkoef || lv_partly_ed || ' ,0)) ' || lv_decperiod || ' )/1000 BParam ';
  ELSIF (an_codetemplate = gn_rero_redo_f OR an_codetemplate = gn_rero_redo_pow_f OR an_codetemplate = gn_rero_redo_sum_f) THEN
   lv_paramlist :=
    ',sum(DECODE( ' || lv_inverted || ',''y'',nvl(P.q3 ' || lv_powkoef || ' ,0)+nvl(P.q4 ' || lv_powkoef || ' ,0)
                    ,nvl(P.q1 ' || lv_powkoef || ' ,0)+nvl(P.q2 ' || lv_powkoef || ' ,0)) ' || lv_decperiod || ' )/1000 AParam,
                      sum(DECODE( ' || lv_inverted || ' ,''y'',nvl(P.q1 ' || lv_powkoef || ' ,0)+nvl(P.q2 ' || lv_powkoef
    || ' ,0)
                      ,nvl(P.q3 ' || lv_powkoef || ' ,0)+nvl(P.q4 ' || lv_powkoef || ' ,0)) ' || lv_decperiod || ' )/1000 BParam ';
  ELSIF (an_codetemplate = gn_rq1_rq4_f OR an_codetemplate = gn_rq1_rq4_pow_f) THEN
   lv_paramlist :=
    ' ,sum(DECODE( ' || lv_inverted || ' ,''y'',nvl(P.q4 ' || lv_powkoef || ' ,0)
     ,nvl(P.q1 ' || lv_powkoef || ' ,0)) ' || lv_decperiod || ' )/1000 AParam,
    	 sum(DECODE( ' || lv_inverted || ' ,''y'',nvl(P.q1 ' || lv_powkoef || ' ,0)
         ,nvl(P.q4 ' || lv_powkoef || ' ,0)) ' || lv_decperiod || ' )/1000 BParam ';
  ELSIF (an_codetemplate = gn_rq2_rq3_f OR an_codetemplate = gn_rq2_rq3_pow_f) THEN
   lv_paramlist :=
    ' ,sum(DECODE( ' || lv_inverted || ' ,''y'',nvl(P.q3 ' || lv_powkoef || ' ,0)
                     ,nvl(P.q2 ' || lv_powkoef || ' ,0)) ' || lv_decperiod || ' )/1000 AParam,
                      sum(DECODE( ' || lv_inverted || ' ,''y'',nvl(P.q2 ' || lv_powkoef || ' ,0)
                      ,nvl(P.q3 ' || lv_powkoef || ' ,0)) ' || lv_decperiod || ' )/1000 BParam ';
  END IF;

  lv_sql :=
   'select ' || lv_grouping || ' BGroup ' || lv_paramlist || lv_decnsourcef || ' decnsour from  
               ' || lv_oracletable || ' P, ' || lv_table
   || 'G  where P.mid=G.mid AND
                date_time >= :par1 and date_time <= :par2
                 and  ' || lv_subsel || '
                group by ' || lv_grouping || '
         union ALL 
	      select 0 BGroup ' || lv_paramlist || lv_decnsourcesec || ' decnsour from ' || lv_oracletable || ' P,' || lv_table
   || ' G
                where P.mid=G.mid AND 
        	date_time >= :par1
	         and   date_time <= :par2
            and ' || lv_subsel || ' order by 1';

  IF (an_ispoints = 1) THEN
   IF (an_stepprofile = gn_stpminute) THEN
    OPEN acur_t FOR lv_sql
    USING lv_firstdate, an_stepprof, an_idgroup, lv_firstdate, lv_lastdate, an_idgroup, lv_firstdate, an_stepprof, an_idgroup, lv_firstdate, lv_lastdate,
          an_idgroup;
   ELSIF (an_stepprofile = gn_stphour) THEN
    OPEN acur_t FOR lv_sql USING an_stepprof, an_idgroup, lv_firstdate, lv_lastdate, an_idgroup, an_stepprof, an_idgroup, lv_firstdate, lv_lastdate, an_idgroup;
   --  USING lv_firstdate, an_powerprofile * 60, an_idgroup, lv_firstdate, lv_lastdate, an_idgroup, lv_firstdate, an_powerprofile * 60, an_idgroup, lv_firstdate,
   --        lv_lastdate, an_idgroup;
   ELSIF (an_stepprofile = gn_stpmonth) THEN
    OPEN acur_t FOR lv_sql
    USING an_idgroup, lv_firstdate, lv_firstdate, lv_lastdate, an_idgroup, an_idgroup, lv_lastdate, lv_firstdate, lv_firstdate, lv_lastdate, an_idgroup;
   ELSIF (an_stepprofile = gn_stpday) THEN
    OPEN acur_t FOR lv_sql USING an_idgroup, lv_firstdate, lv_lastdate, an_idgroup, an_idgroup, lv_firstdate, lv_lastdate, an_idgroup;
   END IF;
  ELSIF (an_ispoints = 0) THEN
   IF (an_stepprofile = gn_stpmonth) THEN
    OPEN acur_t FOR lv_sql
    USING an_idgroup, lv_firstdate, lv_firstdate, lv_lastdate, an_periodforyearfinish, an_periodforyearstart, an_idgroup, an_periodforyearfinish,
          an_periodforyearstart, an_idgroup, lv_lastdate, lv_firstdate, lv_firstdate, lv_lastdate, an_periodforyearfinish, an_periodforyearstart, an_idgroup,
          an_periodforyearfinish, an_periodforyearstart;
   ELSIF (an_stepprofile = gn_stpminute) THEN
    OPEN acur_t FOR lv_sql
    USING lv_firstdate, an_stepprof, an_idgroup, lv_firstdate, lv_lastdate, an_period, an_idgroup, an_period, lv_firstdate, an_stepprof, an_idgroup, lv_firstdate,
          lv_lastdate, an_period, an_idgroup, an_period;
   ELSIF (an_stepprofile = gn_stphour) THEN
    OPEN acur_t FOR lv_sql
    USING an_stepprof, an_idgroup, lv_firstdate, lv_lastdate, an_period, an_idgroup, an_period, an_stepprof, an_idgroup, lv_firstdate, lv_lastdate, an_period,
          an_idgroup, an_period;
   -- USING lv_firstdate, an_powerprofile * 60, an_idgroup, lv_firstdate, lv_lastdate, an_period, an_idgroup, an_period, lv_firstdate, an_powerprofile * 60,
   --       an_idgroup, lv_firstdate, lv_lastdate, an_period, an_idgroup, an_period;
   ELSIF (an_stepprofile = gn_stpday) THEN
    OPEN acur_t FOR lv_sql
    USING an_idgroup, lv_firstdate, lv_lastdate, an_period, an_idgroup, an_period, an_idgroup, lv_firstdate, lv_lastdate, an_period, an_idgroup, an_period;
   END IF;
  END IF;
 END;

---------------------------------------------------------------------------------------------------------------------------
--T2xDrawTableChartInterior::clickComposition
 PROCEDURE interior_clickcomp1_p (an_ispoints NUMBER,   --группа или точка fd-> IsPoints
                                                     an_stepprofile NUMBER,   -- детализация fd->StepProfile
                                                                           an_idgroup NUMBER, an_periodforyearstart NUMBER, an_periodforyearfinish NUMBER,
 an_period NUMBER, acur_t OUT common_pg.tcur
 ) IS
  lv_subselect   VARCHAR2 (200);
  lv_sql         VARCHAR2 (4000);
 BEGIN
  IF (an_ispoints = 1) THEN
   lv_sql := ' select nvl(parent,0)IdGroup from points where mid = :par1 ';
  ELSIF (an_ispoints = 0) THEN
   subselect_p (an_stepprofile, lv_subselect);
   lv_sql := 'select nvl(parent,0)IdGroup from groups where gid = :par1 ' || lv_subselect;
  END IF;

  IF (an_ispoints = 1) THEN
   OPEN acur_t FOR lv_sql USING an_idgroup;
  ELSIF (an_ispoints = 0) THEN
   IF (an_stepprofile = gn_stpmonth) THEN
    OPEN acur_t FOR lv_sql USING an_idgroup, an_periodforyearfinish, an_periodforyearstart;
   ELSE
    OPEN acur_t FOR lv_sql USING an_idgroup, an_period;
   END IF;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------------
--T2xDrawTableChartInterior::clickComposition
 PROCEDURE interior_clickcomp2_p (an_ispoints NUMBER,   --группа или точка fd-> IsPoints
                                                     an_stepprofile NUMBER,   -- детализация fd->StepProfile
                                                                           an_idgroup NUMBER, an_periodforyearstart NUMBER, an_periodforyearfinish NUMBER,
 an_period NUMBER, acur_t OUT common_pg.tcur
 ) IS
  lv_subselect   VARCHAR2 (200);
  lv_sql         VARCHAR2 (4000);
 BEGIN
  IF (an_ispoints = 1) THEN
   lv_sql :=
    ' select nvl(UTIL_PG.GET_NAME_F(name,MID), UTIL_PG.GET_SHORTNAME_F(short_name,MID))Name,
                    nvl(UTIL_PG.GET_SHORTNAME_F(short_name,MID), UTIL_PG.GET_NAME_F(name,MID))ShortName, ''y'' GROUP_TOTAL
                    from points where mid = :par1 ';
  ELSIF (an_ispoints = 0) THEN
   subselect_p (an_stepprofile, lv_subselect);
   lv_sql :=
    'select nvl(UTIL_PG.GET_NAME_F(name,MID), UTIL_PG.GET_SHORTNAME_F(short_name,MID))Name,
                    nvl(UTIL_PG.GET_SHORTNAME_F(short_name,MID), UTIL_PG.GET_NAME_F(name,MID))ShortName, nvl(GROUP_TOTAL,''n'') GROUP_TOTAL
               from groups where gid = :par1 '
    || lv_subselect;
  END IF;

  IF (an_ispoints = 1) THEN
   OPEN acur_t FOR lv_sql USING an_idgroup;
  ELSIF (an_ispoints = 0) THEN
   IF (an_stepprofile = gn_stpmonth) THEN
    OPEN acur_t FOR lv_sql USING an_idgroup, an_periodforyearfinish, an_periodforyearstart;
   ELSE
    OPEN acur_t FOR lv_sql USING an_idgroup, an_period;
   END IF;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------------
 PROCEDURE interior4_selectdata_p (an_ispoints NUMBER,   --группа или точка fd-> IsPoints
                                                      an_stepprofile NUMBER,   -- детализация fd->StepProfile
                                                                            an_codetemplate NUMBER,   --код монитора fd->CodeTemplate
                                                                                                   av_rowcount VARCHAR2,   -- RowCount
                                                                                                                        an_bird NUMBER,   --//переменная состояния. задается на форме fd->bird
 an_powerprofile NUMBER,   --// Количество строк при выводе графика нагрузки
                        an_stepprof NUMBER,   --//Минимальный шаг профиля в секундах
                                           av_firstdate VARCHAR2, av_lastdate VARCHAR2, an_idgroup NUMBER, an_periodforyearstart NUMBER,
 an_periodforyearfinish NUMBER, an_period NUMBER, acur_t OUT common_pg.tcur
 ) IS
  lv_powkoef         VARCHAR2 (400);   -- // Коэффициент для перевода в мощность Для ГН и Тех. профиля
  lv_inverted        VARCHAR2 (150);
  lv_subsel          VARCHAR2 (1000);
  lv_subselect       VARCHAR2 (1000);
  lv_table           VARCHAR2 (150);
  lv_partly_er       VARCHAR2 (600);
  lv_partly_ed       VARCHAR2 (600);
  lv_decnsourcesec   VARCHAR2 (1000);
  lv_decnsourcef     VARCHAR2 (1000);
  lv_decperiod       VARCHAR2 (600);
  lv_paramlist       VARCHAR2 (4000);
  lv_grouping        VARCHAR2 (600);
  lv_oracletable     VARCHAR2 (150);
  lv_firstdate       DATE;
  lv_lastdate        DATE;
  lv_sql             VARCHAR2 (10000);
  lv_dbalans         VARCHAR2 (150);
-----------------------------------
 BEGIN
  lv_firstdate := TO_DATE (av_firstdate, 'dd.mm.yyyy hh24:mi:ss') + interior_pg.get_hourtimezone;
  lv_lastdate := TO_DATE (av_lastdate, 'dd.mm.yyyy hh24:mi:ss') + interior_pg.get_hourtimezone;
  takeofpartquerifornsorse_p (an_ispoints,   --группа или точка
                              an_stepprofile,   -- детализация
                              av_rowcount,   --
                              lv_firstdate, lv_lastdate, lv_decnsourcesec, lv_decnsourcef);
  decperiod_p (an_ispoints,   --группа или точка
               lv_decperiod);
  subselect_p (an_stepprofile, lv_subselect);
  grouping_p (an_stepprofile, lv_grouping);
  lv_powkoef := ' ';

  IF (an_ispoints = 1) THEN
   lv_inverted := ' ''n'' ';

   IF util_pg.isfolder (an_idgroup) = 1 THEN
    lv_subsel := ' G.mid in (select mid from points connect by prior mid=parent and prior ind not in (3,4) start with mid=:par3) ';
   ELSE
    lv_subsel := ' G.mid=:par3 ';
   END IF;
   lv_table := ' points ';
   lv_partly_er := ' ';
   lv_partly_ed := ' ';
  ELSE
   lv_inverted := 'G.inverted';
   lv_subsel :=
    ' G.gid in (select gid from groups connect by ((prior gid=parent) or
          (prior NROOT2=NROOT2 and prior nroot1>0 and nroot1 is null) ' || lv_subselect || ') start with gid=:par3 ' || lv_subselect || ') ';
   lv_table := ' groups ';
   lv_partly_er := ' *decode(g.NPARTLY,2,0,1) ';
   lv_partly_ed := ' *decode(g.NPARTLY,1,0,1) ';
  END IF;

  IF (an_codetemplate = gn_balance_pow_f OR an_codetemplate = gn_re_balance_pow_f) THEN
   IF (an_stepprofile = gn_stphour) THEN
    lv_powkoef := '* ' || TO_CHAR (60.0 / an_powerprofile);
   ELSIF (an_stepprofile = gn_stpminute) THEN
    lv_powkoef := '* ' || TO_CHAR (3600.0 / an_stepprof);
   END IF;
  END IF;

  IF (an_codetemplate = gn_aero_aera_aerb_aerc_f) THEN
   lv_paramlist :=
    ' ,sum(DECODE( ' || lv_inverted || ' ,''y'',nvl(P.ed ' || lv_partly_ed || ' ,0),nvl(P.er' || lv_partly_er || ',0)) ' || lv_decperiod
    || ' )/1000 AParam,
			    	 sum(DECODE(' || lv_inverted || ',''y'',nvl(P.aed ' || lv_partly_ed || ' ,0),nvl(P.aer ' || lv_partly_er || ' ,0)) ' || lv_decperiod
    || ' )/1000 BParam,
				     sum(DECODE(' || lv_inverted || ',''y'',nvl(P.bed' || lv_partly_ed || ',0),nvl(P.ber' || lv_partly_er || ',0))' || lv_decperiod
    || ')/1000 CParam,
    				 sum(DECODE(' || lv_inverted || ',''y'',nvl(P.ced' || lv_partly_ed || ',0),nvl(P.cer' || lv_partly_er || ',0))' || lv_decperiod || ')/1000 DParam ';
   interior2_choiceoftable_p (an_bird, gn_stpmonth, lv_oracletable);
  ELSIF (an_codetemplate = gn_aedo_aeda_aedb_aedc_f) THEN
   lv_paramlist :=
    ',sum(DECODE(' || lv_inverted || ',''y'',nvl(P.er' || lv_partly_er || ',0),nvl(P.ed' || lv_partly_ed || ',0))' || lv_decperiod
    || ')/1000 AParam,
			    	 sum(DECODE(' || lv_inverted || ',''y'',nvl(P.aer' || lv_partly_er || ',0),nvl(P.aed' || lv_partly_ed || ',0))' || lv_decperiod
    || ')/1000 BParam,
				     sum(DECODE(' || lv_inverted || ',''y'',nvl(P.ber' || lv_partly_er || ',0),nvl(P.bed' || lv_partly_ed || ',0))' || lv_decperiod
    || ')/1000 CParam,
    				 sum(DECODE(' || lv_inverted || ',''y'',nvl(P.cer' || lv_partly_er || ',0),nvl(P.ced' || lv_partly_ed || ',0))' || lv_decperiod || ')/1000 DParam ';
   interior2_choiceoftable_p (an_bird, gn_stpmonth, lv_oracletable);
  ELSIF (an_codetemplate = gn_rero_rera_rerb_rerc_f) THEN
   lv_paramlist :=
    ',(sum(DECODE(' || lv_inverted || ',''y'',nvl(P.q3,0),nvl(P.q1,0))' || lv_decperiod || ') +
			    	 sum(DECODE(' || lv_inverted || ',''y'',nvl(P.q4,0),nvl(P.q2,0))' || lv_decperiod || '))/1000 AParam,
				     (sum(DECODE(' || lv_inverted || ',''y'',nvl(P.aq3,0),nvl(P.aq1,0))' || lv_decperiod || ') +
    				 sum(DECODE(' || lv_inverted || ',''y'',nvl(P.aq4,0),nvl(P.aq2,0))' || lv_decperiod || '))/1000 BParam,
	    			 (sum(DECODE(' || lv_inverted || ',''y'',nvl(P.bq3,0),nvl(P.bq1,0))' || lv_decperiod || ') +
		    		 sum(DECODE(' || lv_inverted || ',''y'',nvl(P.bq4,0),nvl(P.bq2,0))' || lv_decperiod || '))/1000 CParam,
			    	 (sum(DECODE(' || lv_inverted || ',''y'',nvl(P.cq3,0),nvl(P.cq1,0))' || lv_decperiod || ') +
				     sum(DECODE(' || lv_inverted || ',''y'',nvl(P.cq4,0),nvl(P.cq2,0))' || lv_decperiod || '))/1000 DParam ';
   interior2_choiceoftable_p (an_bird, gn_stpmonth, lv_oracletable);
  ELSIF (an_codetemplate = gn_redo_reda_redb_redc_f) THEN
   lv_paramlist :=
    ' ,(sum(DECODE(' || lv_inverted || ',''y'',nvl(P.q1,0),nvl(P.q3,0))' || lv_decperiod || ') +
		    		 sum(DECODE(' || lv_inverted || ',''y'',nvl(P.q2,0),nvl(P.q4,0))' || lv_decperiod || '))/1000 AParam,
			    	 (sum(DECODE(' || lv_inverted || ',''y'',nvl(P.aq1,0),nvl(P.aq3,0))' || lv_decperiod || ') +
				     sum(DECODE(' || lv_inverted || ',''y'',nvl(P.aq2,0),nvl(P.aq4,0))' || lv_decperiod || '))/1000 BParam,
    				 (sum(DECODE(' || lv_inverted || ',''y'',nvl(P.bq1,0),nvl(P.bq3,0))' || lv_decperiod || ') +
	    			 sum(DECODE(' || lv_inverted || ',''y'',nvl(P.bq2,0),nvl(P.bq4,0))' || lv_decperiod || '))/1000 CParam,
		    		 (sum(DECODE(' || lv_inverted || ',''y'',nvl(P.cq1,0),nvl(P.cq3,0))' || lv_decperiod || ') +
			    	 sum(DECODE(' || lv_inverted || ',''y'',nvl(P.cq2,0),nvl(P.cq4,0))' || lv_decperiod || '))/1000 DParam ';
   interior2_choiceoftable_p (an_bird, gn_stpmonth, lv_oracletable);
  ELSIF (an_codetemplate = gn_aera_aerb_aerc_aerd_f) THEN
   lv_paramlist :=
    ' ,sum(DECODE(' || lv_inverted || ',''y'',nvl(P.aed' || lv_partly_ed || ',0),nvl(P.aer' || lv_partly_er || ',0))' || lv_decperiod
    || ')/1000 AParam,
			    	 sum(DECODE(' || lv_inverted || ',''y'',nvl(P.bed' || lv_partly_ed || ',0),nvl(P.ber' || lv_partly_er || ',0))' || lv_decperiod
    || ')/1000 BParam,
				     sum(DECODE(' || lv_inverted || ',''y'',nvl(P.ced' || lv_partly_ed || ',0),nvl(P.cer' || lv_partly_er || ',0))' || lv_decperiod
    || ')/1000 CParam,
    				 sum(DECODE(' || lv_inverted || ',''y'',nvl(P.ded' || lv_partly_ed || ',0),nvl(P.der' || lv_partly_er || ',0))' || lv_decperiod || ')/1000 DParam ';
   interior2_choiceoftable_p (an_bird, gn_stpmonth, lv_oracletable);
  ELSIF (an_codetemplate = gn_aeda_aedb_aedc_aedd_f) THEN
   lv_paramlist :=
    ' ,sum(DECODE(' || lv_inverted || ',''y'',nvl(P.aer' || lv_partly_er || ',0),nvl(P.aed' || lv_partly_ed || ',0))' || lv_decperiod
    || ')/1000 AParam,
			    	 sum(DECODE(' || lv_inverted || ',''y'',nvl(P.ber' || lv_partly_er || ',0),nvl(P.bed' || lv_partly_ed || ',0))' || lv_decperiod
    || ')/1000 BParam,
				     sum(DECODE(' || lv_inverted || ',''y'',nvl(P.cer' || lv_partly_er || ',0),nvl(P.ced' || lv_partly_ed || ',0))' || lv_decperiod
    || ')/1000 CParam,
    				 sum(DECODE(' || lv_inverted || ',''y'',nvl(P.der' || lv_partly_er || ',0),nvl(P.ded' || lv_partly_ed || ',0))' || lv_decperiod || ')/1000 DParam ';
   interior2_choiceoftable_p (an_bird, gn_stpmonth, lv_oracletable);
  ELSIF (an_codetemplate = gn_rera_rerb_rerc_rerd_f) THEN
   lv_paramlist :=
    '  ,(sum(DECODE(' || lv_inverted || ',''y'',nvl(P.aq3,0),nvl(P.aq1,0))' || lv_decperiod || ') +
			    	 sum(DECODE(' || lv_inverted || ',''y'',nvl(P.aq4,0),nvl(P.aq2,0))' || lv_decperiod || '))/1000 AParam,
				     (sum(DECODE(' || lv_inverted || ',''y'',nvl(P.bq3,0),nvl(P.bq1,0))' || lv_decperiod || ') +
    				 sum(DECODE(' || lv_inverted || ',''y'',nvl(P.bq4,0),nvl(P.bq2,0))' || lv_decperiod || '))/1000 BParam,
	    			 (sum(DECODE(' || lv_inverted || ',''y'',nvl(P.cq3,0),nvl(P.cq1,0))' || lv_decperiod || ') +
		    		 sum(DECODE(' || lv_inverted || ',''y'',nvl(P.cq4,0),nvl(P.cq2,0))' || lv_decperiod || '))/1000 CParam,
			    	 (sum(DECODE(' || lv_inverted || ',''y'',nvl(P.dq3,0),nvl(P.dq1,0))' || lv_decperiod || ') +
				     sum(DECODE(' || lv_inverted || ',''y'',nvl(P.dq4,0),nvl(P.dq2,0))' || lv_decperiod || '))/1000 DParam ';
   interior2_choiceoftable_p (an_bird, gn_stpmonth, lv_oracletable);
  ELSIF (an_codetemplate = gn_reda_redb_redc_redd_f) THEN
   lv_paramlist :=
    ',(sum(DECODE(' || lv_inverted || ',''y'',nvl(P.aq1,0),nvl(P.aq3,0))' || lv_decperiod || ') +
			    	 sum(DECODE(' || lv_inverted || ',''y'',nvl(P.aq2,0),nvl(P.aq4,0))' || lv_decperiod || '))/1000 AParam,
				     (sum(DECODE(' || lv_inverted || ',''y'',nvl(P.bq1,0),nvl(P.bq3,0))' || lv_decperiod || ') +
    				 sum(DECODE(' || lv_inverted || ',''y'',nvl(P.bq2,0),nvl(P.bq4,0))' || lv_decperiod || '))/1000 BParam,
	    			 (sum(DECODE(' || lv_inverted || ',''y'',nvl(P.cq1,0),nvl(P.cq3,0))' || lv_decperiod || ') +
		    		 sum(DECODE(' || lv_inverted || ',''y'',nvl(P.cq2,0),nvl(P.cq4,0))' || lv_decperiod || '))/1000 CParam,
			    	 (sum(DECODE(' || lv_inverted || ',''y'',nvl(P.dq1,0),nvl(P.dq3,0))' || lv_decperiod || ') +
				     sum(DECODE(' || lv_inverted || ',''y'',nvl(P.dq2,0),nvl(P.dq4,0))' || lv_decperiod || '))/1000 DParam ';
   interior2_choiceoftable_p (an_bird, gn_stpmonth, lv_oracletable);
  ELSIF (an_codetemplate = gn_aebo_aeba_aebb_aebc_f) THEN   --// 921 Переток активной э/э (общая и по тарифам) [кВтч]
   lv_paramlist :=
    ',sum((-util_pg.sld(P.mid,nvl(P.er' || lv_partly_er || ',0),nvl(P.ed' || lv_partly_ed || ',0)))*DECODE(' || lv_inverted || ',''y'',1,-1)' || lv_decperiod
    || ')/1000 AParam
			        ,sum((-util_pg.sld(P.mid,nvl(P.aer' || lv_partly_er || ',0),nvl(P.aed' || lv_partly_ed || ',0)))*DECODE(' || lv_inverted || ',''y'',1,-1)'
    || lv_decperiod || ')/1000 BParam
				     ,sum((-util_pg.sld(P.mid,nvl(P.ber' || lv_partly_er || ',0),nvl(P.bed' || lv_partly_ed || ',0)))*DECODE(' || lv_inverted || ',''y'',1,-1)' || lv_decperiod
    || ')/1000 CParam
    				 ,sum((-util_pg.sld(P.mid,nvl(P.cer' || lv_partly_er || ',0),nvl(P.ced' || lv_partly_ed || ',0)))*DECODE(' || lv_inverted || ',''y'',1,-1)' || lv_decperiod
    || ')/1000 DParam ';
   interior2_choiceoftable_p (an_bird, gn_stpmonth, lv_oracletable);
  ELSIF (an_codetemplate = gn_rebo_reba_rebb_rebc_f) THEN   --//941 Переток реактивной э/э (общая и по тарифам) [кВарч]
   lv_paramlist :=
    ',(sum((-util_pg.sld(P.mid,nvl(P.q1,0),nvl(P.q3,0)))*DECODE(' || lv_inverted || ',''y'',1,-1)' || lv_decperiod
    || ') +
			    	 sum((-util_pg.sld(P.mid,nvl(P.q2,0),nvl(P.q4,0)))*DECODE(' || lv_inverted || ',''y'',1,-1)' || lv_decperiod
    || '))/1000 AParam
				     ,(sum((-util_pg.sld(P.mid,nvl(P.aq1,0),nvl(P.aq3,0)))*DECODE(' || lv_inverted || ',''y'',1,-1)' || lv_decperiod
    || ') +
    				 sum((-util_pg.sld(P.mid,nvl(P.aq2,0),nvl(P.aq4,0)))*DECODE(' || lv_inverted || ',''y'',1,-1)' || lv_decperiod
    || '))/1000 BParam
	    			 ,(sum((-util_pg.sld(P.mid,nvl(P.bq1,0),nvl(P.bq3,0)))*DECODE(' || lv_inverted || ',''y'',1,-1)' || lv_decperiod
    || ') +
		    		 sum((-util_pg.sld(P.mid,nvl(P.bq2,0),nvl(P.bq4,0)))*DECODE(' || lv_inverted || ',''y'',1,-1)' || lv_decperiod
    || '))/1000 CParam
			    	 ,(sum((-util_pg.sld(P.mid,nvl(P.cq1,0),nvl(P.cq3,0)))*DECODE(' || lv_inverted || ',''y'',1,-1)' || lv_decperiod
    || ') +
				     sum((-util_pg.sld(P.mid,nvl(P.cq2,0),nvl(P.cq4,0)))*DECODE(' || lv_inverted || ',''y'',1,-1)' || lv_decperiod || '))/1000 DParam ';
   interior2_choiceoftable_p (an_bird, gn_stpmonth, lv_oracletable);
  ELSIF (an_codetemplate = gn_balance_f OR an_codetemplate = gn_balance_pow_f OR an_codetemplate = gn_balance_sum_f) THEN
   lv_paramlist :=
    ',sum(DECODE(' || lv_inverted || ',''y'',nvl(P.ed' || lv_powkoef || lv_partly_ed || ',0),nvl(P.er' || lv_powkoef || lv_partly_er || ',0))' || lv_decperiod
    || ')/1000 AParam ' ||   -- //Приём Активной энергии
                          ' ,sum(DECODE(' || lv_inverted || ',''y'',nvl(P.er' || lv_powkoef || lv_partly_er || ',0),nvl(P.ed' || lv_powkoef || lv_partly_ed
    || ',0))' || lv_decperiod || ')/1000 BParam ' ||   -- //Отдача Активной энергии [кВтч]
                                                    ' ,sum( -util_pg.sld( P.mid, nvl(P.er' || lv_powkoef || lv_partly_er || ',0), (nvl(P.ed' || lv_powkoef
    || lv_partly_ed || ',0) ) )*DECODE(' || lv_inverted || ',''y'',1,-1)' || lv_decperiod || ')/1000 CParam ' ||   --//Переток Активной энергии [кВтч]
                                                                                                                ' ,DECODE(sum(DECODE(' || lv_inverted
    || ',''y'',nvl(P.ed' || lv_powkoef || lv_partly_ed || ',0),nvl(P.er' || lv_powkoef || lv_partly_er || ',0))' || lv_decperiod
    || '),0,0,
                sum( -util_pg.sld( P.mid, nvl(P.er' || lv_powkoef || lv_partly_er || ',0), (nvl(P.ed' || lv_powkoef || lv_partly_ed || ',0) ) )*DECODE('
    || lv_inverted || ',''y'',1,-1)' || lv_decperiod || ')/
                sum(DECODE(' || lv_inverted || ',''y'',nvl(P.ed' || lv_powkoef || lv_partly_ed || ',0),nvl(P.er' || lv_powkoef || lv_partly_er || ',0))'
    || lv_decperiod || ')*100) DParam ';   --//процент
   interior2_choiceoftable_p (an_bird, an_stepprofile, lv_oracletable);
  ELSIF (an_codetemplate = gn_not_balance_f) THEN
   --lv_dbalans:=to_char(nvl(get_ad_balance2 (an_idgroup, to_date(av_firstdate,'dd.mm.yyyy hh24:mi:ss'), to_date(av_lastdate,'dd.mm.yyyy hh24:mi:ss'), 1,an_ispoints,an_periodforyearstart,an_periodforyearfinish,an_period,an_stepprofile ,lv_grouping ),-1));
   lv_dbalans := TO_CHAR (NVL (util_pg.get_ad_balance (an_idgroup, lv_firstdate, lv_lastdate, 1), -1));
   lv_paramlist :=
    ' ,sum( -util_pg.sld( P.mid, nvl(P.er' || lv_powkoef || lv_partly_er || ',0), (nvl(P.ed' || lv_powkoef || lv_partly_ed || ',0) ) )*DECODE(' || lv_inverted
    || ',''y'',1,-1)' || lv_decperiod || ')/1000 AParam ' ||   --//Фактический небаланс Активной энергии [кВтч]
                                                            ' ,DECODE(sum(DECODE(' || lv_inverted || ',''y'',nvl(P.ed' || lv_powkoef || lv_partly_ed
    || ',0),nvl(P.er' || lv_powkoef || lv_partly_er || ',0))' || lv_decperiod || '),0,0,
    sum( -util_pg.sld( P.mid, nvl(P.er' || lv_powkoef || lv_partly_er || ',0), (nvl(P.ed' || lv_powkoef || lv_partly_ed || ',0) ) )*DECODE(' || lv_inverted
    || ',''y'',1,-1)' || lv_decperiod || ')/
    sum(DECODE(' || lv_inverted || ',''y'',nvl(P.ed' || lv_powkoef || lv_partly_ed || ',0),nvl(P.er' || lv_powkoef || lv_partly_er || ',0))' || lv_decperiod
    || ')*100) BParam ,   ' ||   --// небаланс активной фактический процент
                              lv_dbalans || '   CParam ,' ||   --// небаланс активной допустимый процент
                                                            ' 0 DParam ';   --// разница допустимого и фактического баланса в процентах
   interior2_choiceoftable_p (an_bird, an_stepprofile, lv_oracletable);
  ELSIF (an_codetemplate = gn_re_balance_f OR an_codetemplate = gn_re_balance_pow_f OR an_codetemplate = gn_re_balance_sum_f) THEN
   lv_paramlist :=
    ' ,sum(DECODE(' || lv_inverted || ',''y'',nvl(P.q3' || lv_powkoef || ',0)+nvl(P.q4' || lv_powkoef || ',0),nvl(P.q1' || lv_powkoef || ',0)+nvl(P.q2'
    || lv_powkoef || ',0))' || lv_decperiod || ')/1000 AParam,
                 sum(DECODE(' || lv_inverted || ',''y'',nvl(P.q1' || lv_powkoef || ',0)+nvl(P.q2' || lv_powkoef || ',0),nvl(P.q3' || lv_powkoef || ',0)+nvl(P.q4'
    || lv_powkoef || ',0))' || lv_decperiod || ')/1000 BParam, ' ||   --//Приём / Отдача Реактивной энергии [МВАрч]
                                                                   ' (sum(( -util_pg.sld( P.mid, nvl(P.q1' || lv_powkoef || ',0), nvl(P.q3' || lv_powkoef
    || ',0)))*DECODE(' || lv_inverted || ',''y'',1,-1)' || lv_decperiod || ') +
		       sum(( -util_pg.sld( P.mid, nvl(P.q2' || lv_powkoef || ',0), nvl(P.q4' || lv_powkoef || ',0)))*DECODE(' || lv_inverted || ',''y'',1,-1)' || lv_decperiod
    || '))/1000 CParam ' ||   -- //Переток Реактивной энергии [кВАрч]
                           ' ,DECODE(sum(DECODE(' || lv_inverted || ',''y'',nvl(P.q3' || lv_powkoef || ',0)+nvl(P.q4' || lv_powkoef || ',0),nvl(P.q1' || lv_powkoef
    || ',0)+nvl(P.q2' || lv_powkoef || ',0))' || lv_decperiod || '),0,0,
                 (sum(( -util_pg.sld( P.mid, nvl(P.q1' || lv_powkoef || ',0), nvl(P.q3' || lv_powkoef || ',0)))*DECODE(' || lv_inverted || ',''y'',1,-1)'
    || lv_decperiod || ') +
		       sum(( -util_pg.sld( P.mid, nvl(P.q2' || lv_powkoef || ',0), nvl(P.q4' || lv_powkoef || ',0)))*DECODE(' || lv_inverted || ',''y'',1,-1)' || lv_decperiod
    || '))
                  /sum(DECODE(' || lv_inverted || ',''y'',nvl(P.q3' || lv_powkoef || ',0)+nvl(P.q4' || lv_powkoef || ',0),nvl(P.q1' || lv_powkoef || ',0)+nvl(P.q2'
    || lv_powkoef || ',0))' || lv_decperiod || '*100))DParam ';
   interior2_choiceoftable_p (an_bird, an_stepprofile, lv_oracletable);
  END IF;

  lv_sql :=
   'select ' || lv_grouping || 'BGroup' || lv_paramlist || lv_decnsourcef || 'decnsour  from  ' || lv_oracletable || ' P, ' || lv_table
   || ' G
               where P.mid=G.mid AND date_time >= :par1
               and   date_time<= :par2
               and ' || lv_subsel || ' group by ' || lv_grouping || '
           union ALL
	     select 0 BGroup' || lv_paramlist || lv_decnsourcesec || 'decnsour from  ' || lv_oracletable || ' P, ' || lv_table
   || ' G
    		 where P.mid=G.mid AND date_time >= :par1
		 and   date_time <= :par2
            and ' || lv_subsel || ' order by 1';

  IF (an_ispoints = 1) THEN
   IF (an_stepprofile = gn_stpminute) THEN
    OPEN acur_t FOR lv_sql
    USING lv_firstdate, an_stepprof, an_idgroup, lv_firstdate, lv_lastdate, an_idgroup, lv_firstdate, an_stepprof, an_idgroup, lv_firstdate, lv_lastdate,
          an_idgroup;
   ELSIF (an_stepprofile = gn_stphour) THEN
    OPEN acur_t FOR lv_sql USING an_stepprof, an_idgroup, lv_firstdate, lv_lastdate, an_idgroup, an_stepprof, an_idgroup, lv_firstdate, lv_lastdate, an_idgroup;
   --  USING lv_firstdate, an_powerprofile * 60, an_idgroup, lv_firstdate, lv_lastdate, an_idgroup, lv_firstdate, an_powerprofile * 60, an_idgroup, lv_firstdate,
   --        lv_lastdate, an_idgroup;
   ELSIF (an_stepprofile = gn_stpmonth) THEN
    OPEN acur_t FOR lv_sql
    USING an_idgroup, lv_firstdate, lv_firstdate, lv_lastdate, an_idgroup, an_idgroup, lv_lastdate, lv_firstdate, lv_firstdate, lv_lastdate, an_idgroup;
   ELSIF (an_stepprofile = gn_stpday) THEN
    OPEN acur_t FOR lv_sql USING an_idgroup, lv_firstdate, lv_lastdate, an_idgroup, an_idgroup, lv_firstdate, lv_lastdate, an_idgroup;
   END IF;
  ELSIF (an_ispoints = 0) THEN
   IF (an_stepprofile = gn_stpmonth) THEN
    OPEN acur_t FOR lv_sql
    USING an_idgroup, lv_firstdate, lv_firstdate, lv_lastdate, an_periodforyearfinish, an_periodforyearstart, an_idgroup, an_periodforyearfinish,
          an_periodforyearstart, an_idgroup, lv_lastdate, lv_firstdate, lv_firstdate, lv_lastdate, an_periodforyearfinish, an_periodforyearstart, an_idgroup,
          an_periodforyearfinish, an_periodforyearstart;
   ELSIF (an_stepprofile = gn_stpminute) THEN
    OPEN acur_t FOR lv_sql
    USING lv_firstdate, an_stepprof, an_idgroup, lv_firstdate, lv_lastdate, an_period, an_idgroup, an_period, lv_firstdate, an_stepprof, an_idgroup, lv_firstdate,
          lv_lastdate, an_period, an_idgroup, an_period;
   ELSIF (an_stepprofile = gn_stphour) THEN
    OPEN acur_t FOR lv_sql
    USING an_stepprof, an_idgroup, lv_firstdate, lv_lastdate, an_period, an_idgroup, an_period, an_stepprof, an_idgroup, lv_firstdate, lv_lastdate, an_period,
          an_idgroup, an_period;
   --   USING lv_firstdate, an_powerprofile * 60, an_idgroup, lv_firstdate, lv_lastdate, an_period, an_idgroup, an_period, lv_firstdate, an_powerprofile * 60,
   --         an_idgroup, lv_firstdate, lv_lastdate, an_period, an_idgroup, an_period;
   ELSIF (an_stepprofile = gn_stpday) THEN
    OPEN acur_t FOR lv_sql
    USING an_idgroup, lv_firstdate, lv_lastdate, an_period, an_idgroup, an_period, an_idgroup, lv_firstdate, lv_lastdate, an_period, an_idgroup, an_period;
   END IF;
  END IF;
 END;

-----------------------------------------------------------------------------------------------------------------------------
 PROCEDURE interiordu2chart_formdescr_p (an_ispoints NUMBER,   --группа или точка fd-> IsPoints
                                                            an_stepprofile NUMBER,   -- детализация fd->StepProfile
                                                                                  an_idgroup NUMBER, av_datest VARCHAR2, av_dateen VARCHAR2,
 an_periodforyearstart NUMBER, an_periodforyearfinish NUMBER, an_period NUMBER, acur_t OUT common_pg.tcur
 ) IS
  lv_subselect   VARCHAR2 (200);
  lv_datest      DATE;
  lv_dateen      DATE;
  lv_sql         VARCHAR2 (4000);
 BEGIN
  lv_datest := TO_DATE (av_datest, 'dd.mm.yyyy hh24:mi:ss') + interior_pg.get_hourtimezone;
  lv_dateen := TO_DATE (av_dateen, 'dd.mm.yyyy hh24:mi:ss') + interior_pg.get_hourtimezone;

  IF (an_ispoints = 1) THEN
   lv_sql :=
    'select TO_CHAR (date_time, ''dd.mm.yyyy hh24:mi:ss'')dattime,date_time from
           (
           SELECT date_time FROM curr_power WHERE mid = :par1
           UNION
           SELECT date_time FROM curr_power_arch WHERE mid = :par1 AND
            date_time >= :par2 AND date_time <= :par3
              )
             ORDER BY 2 desc';
  ELSE
   subselect_p (an_stepprofile, lv_subselect);
   lv_sql :=
    'select TO_CHAR (date_time, ''dd.mm.yyyy hh24:mi:ss'')dattime,date_time
                  from
                    (
                      SELECT date_time FROM curr_power WHERE mid = (SELECT MID FROM GROUPS WHERE GID=:par1
                      '
    || lv_subselect
    || ' ) 
                      UNION
                      SELECT date_time FROM curr_power_arch WHERE mid = (SELECT MID FROM GROUPS WHERE GID=:par1
                      '
    || lv_subselect || ' ) AND
                             date_time >= :par2 AND date_time <= :par3
                    )
                  ORDER BY 2 desc';
  END IF;

  IF (an_ispoints = 1) THEN
   OPEN acur_t FOR lv_sql USING an_idgroup, an_idgroup, lv_datest, lv_dateen;
  ELSIF (an_ispoints = 0) THEN
   IF (an_stepprofile = gn_stpmonth) THEN
    OPEN acur_t FOR lv_sql
    USING an_idgroup, an_periodforyearfinish, an_periodforyearstart, an_idgroup, an_periodforyearfinish, an_periodforyearstart, lv_datest, lv_dateen;
   ELSE
    OPEN acur_t FOR lv_sql USING an_idgroup, an_period, an_idgroup, an_period, lv_datest, lv_dateen;
   END IF;
  END IF;
 END;

-----------------------------------------------------------------------------------------------------------------------------
 PROCEDURE interiordu2chart_selectdata_p (an_ispoints NUMBER,   --группа или точка fd-> IsPoints
                                                             an_stepprofile NUMBER,   -- детализация fd->StepProfile
                                                                                   an_idgroup NUMBER, av_date VARCHAR2, an_periodforyearstart NUMBER,
 an_periodforyearfinish NUMBER, an_period NUMBER, acur_t OUT common_pg.tcur
 ) IS
  lv_subselect   VARCHAR2 (1000);
  lv_sql         VARCHAR2 (10000);
-----------------------------------
 BEGIN
  IF (an_ispoints = 1) THEN
   lv_sql :=
    ' select * from
                   (
                      SELECT   mid, (er-ed)/1000 na, (q1-q3)/1000 nr, ACOS(cosf)*180/3.1415926 an, cosf, volt ua,
                          volt2 ub, volt3 uc, NFIU1 an_ua, NFIU2 an_ub, NFIU3 an_uc, currento ia,
                          curr2 ib, curr3 ic, NFII1 an_ia, NFII2 an_ib, NFII3 an_ic,
                          util_pg.convert_conner(1,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3) U1U2,
                          util_pg.convert_conner(2,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3) U1U3,
                          util_pg.convert_conner(3,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3) U2U3,
                          util_pg.convert_conner(4,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3,(er-ed)) U1I1,
                          util_pg.convert_conner(5,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3,(er-ed)) U2I2,
                          util_pg.convert_conner(6,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3,(er-ed)) U3I3, freq
                        FROM curr_power WHERE mid = :par1 AND date_time+ INTERIOR_PG.get_hourtimezone=(TO_DATE(:par2, ''dd.mm.yyyy hh24:mi:ss'')+ INTERIOR_PG.get_hourtimezone)
                      UNION ALL
                      SELECT   mid, (er-ed)/1000 na, (q1-q3)/1000 nr, ACOS(cosf)*180/3.1415926 an, cosf, volt ua,
                          volt2 ub, volt3 uc, NFIU1 an_ua, NFIU2 an_ub, NFIU3 an_uc, currento ia,
                          curr2 ib, curr3 ic, NFII1 an_ia, NFII2 an_ib, NFII3 an_ic,
                          util_pg.convert_conner(1,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3) U1U2,
                          util_pg.convert_conner(2,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3) U1U3,
                          util_pg.convert_conner(3,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3) U2U3,
                          util_pg.convert_conner(4,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3,(er-ed)) U1I1,
                          util_pg.convert_conner(5,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3,(er-ed)) U2I2,
                          util_pg.convert_conner(6,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3,(er-ed)) U3I3, freq
                        FROM curr_power_arch WHERE mid = :par1 AND date_time+ INTERIOR_PG.get_hourtimezone=(TO_DATE(:par2, ''dd.mm.yyyy hh24:mi:ss'')+ INTERIOR_PG.get_hourtimezone)
                    ) where rownum<=1 ';
  ELSE
   subselect_p (an_stepprofile, lv_subselect);
   lv_sql :=
    'select * from
                    (
                      SELECT   mid, (er-ed)/1000 na, (q1-q3)/1000 nr, ACOS(cosf)*180/3.1415926 an, cosf, volt ua,
                          volt2 ub, volt3 uc, NFIU1 an_ua, NFIU2 an_ub, NFIU3 an_uc, currento ia,
                          curr2 ib, curr3 ic, NFII1 an_ia, NFII2 an_ib, NFII3 an_ic,
                          util_pg.convert_conner(1,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3) U1U2,
                          util_pg.convert_conner(2,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3) U1U3,
                          util_pg.convert_conner(3,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3) U2U3,
                          util_pg.convert_conner(4,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3,(er-ed)) U1I1,
                          util_pg.convert_conner(5,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3,(er-ed)) U2I2,
                          util_pg.convert_conner(6,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3,(er-ed)) U3I3, freq
                        FROM curr_power WHERE mid = (SELECT MID FROM GROUPS WHERE GID=:par1
                       '
    || lv_subselect
    || ' ) AND date_time+ INTERIOR_PG.get_hourtimezone=(TO_DATE(:par2, ''dd.mm.yyyy hh24:mi:ss'')+ INTERIOR_PG.get_hourtimezone)
                      UNION ALL
                      SELECT   mid, (er-ed)/1000 na, (q1-q3)/1000 nr, ACOS(cosf)*180/3.1415926 an, cosf, volt ua,
                          volt2 ub, volt3 uc, NFIU1 an_ua, NFIU2 an_ub, NFIU3 an_uc, currento ia,
                          curr2 ib, curr3 ic, NFII1 an_ia, NFII2 an_ib, NFII3 an_ic,
                          util_pg.convert_conner(1,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3) U1U2,
                          util_pg.convert_conner(2,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3) U1U3,
                          util_pg.convert_conner(3,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3) U2U3,
                          util_pg.convert_conner(4,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3,(er-ed)) U1I1,
                          util_pg.convert_conner(5,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3,(er-ed)) U2I2,
                          util_pg.convert_conner(6,NFIU1,NFIU2,NFIU3,NFII1,NFII2,NFII3,(er-ed)) U3I3, freq
                        FROM curr_power_arch WHERE mid = (SELECT MID FROM GROUPS WHERE GID=:par1
                        '
    || lv_subselect
    || ' ) AND date_time+ interior_pg.get_hourtimezone=(TO_DATE(:par2, ''dd.mm.yyyy hh24:mi:ss'')+ INTERIOR_PG.get_hourtimezone)
                    ) where rownum<=1';
  END IF;

  IF (an_ispoints = 1) THEN
   OPEN acur_t FOR lv_sql USING an_idgroup, av_date, an_idgroup, av_date;
  ELSIF (an_ispoints = 0) THEN
   IF (an_stepprofile = gn_stpmonth) THEN
    OPEN acur_t FOR lv_sql USING an_idgroup, an_periodforyearfinish, an_periodforyearstart, av_date, an_idgroup, an_periodforyearfinish, an_periodforyearstart,
    av_date;
   ELSE
    OPEN acur_t FOR lv_sql USING an_idgroup, an_period, av_date, an_idgroup, an_period, av_date;
   END IF;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------------
 PROCEDURE taskmenuform_readtreenode_p (an_nodeparent NUMBER,   --наличие родителя
                                                             an_task_id NUMBER, an_role_id NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  IF (an_nodeparent = 0) THEN
   OPEN acur_t FOR
    SELECT   1 havechild, t.task_id, NVL (t.task_cod, 0) task_cod, t.NAME, r.nacc
        FROM tasks t,
             (SELECT *
                FROM role_task
               WHERE role_id = an_role_id) r
       WHERE t.PARENT IS NULL AND t.task_id = r.task_id(+) AND t.task_id IN (SELECT     task_id
                                                                                   FROM tasks
                                                                             CONNECT BY PRIOR PARENT = task_id
                                                                             START WITH task_id IN (SELECT task_id
                                                                                                      FROM role_task
                                                                                                     WHERE role_id = an_role_id) AND nshow = 1)
             AND EXISTS (SELECT *
                           FROM tasks
                          WHERE PARENT = t.task_id)
    UNION ALL
    SELECT   0 havechild, t.task_id, NVL (t.task_cod, 0) task_cod, t.NAME, r.nacc
        FROM tasks t,
             (SELECT *
                FROM role_task
               WHERE role_id = an_role_id) r
       WHERE t.PARENT IS NULL AND t.task_id = r.task_id(+) AND t.task_id IN (SELECT     task_id
                                                                                   FROM tasks
                                                                             CONNECT BY PRIOR PARENT = task_id
                                                                             START WITH task_id IN (SELECT task_id
                                                                                                      FROM role_task
                                                                                                     WHERE role_id = an_role_id) AND nshow = 1)
             AND NOT EXISTS (SELECT *
                               FROM tasks
                              WHERE PARENT = t.task_id)
    ORDER BY 4;
  ELSE
   OPEN acur_t FOR
    SELECT   1 havechild, t.task_id, NVL (t.task_cod, 0) task_cod, t.NAME, r.nacc
        FROM tasks t,
             (SELECT *
                FROM role_task
               WHERE role_id = an_role_id) r
       WHERE t.PARENT = an_task_id AND t.task_id = r.task_id(+) AND t.task_id IN (SELECT     task_id
                                                                                        FROM tasks
                                                                                  CONNECT BY PRIOR PARENT = task_id
                                                                                  START WITH task_id IN (SELECT task_id
                                                                                                           FROM role_task
                                                                                                          WHERE role_id = an_role_id) AND nshow = 1)
             AND EXISTS (SELECT *
                           FROM tasks
                          WHERE PARENT = t.task_id)
    UNION ALL
    SELECT   0 havechild, t.task_id, NVL (t.task_cod, 0) task_cod, t.NAME, r.nacc
        FROM tasks t,
             (SELECT *
                FROM role_task
               WHERE role_id = an_role_id) r
       WHERE t.PARENT = an_task_id AND t.task_id = r.task_id(+) AND t.task_id IN (SELECT     task_id
                                                                                        FROM tasks
                                                                                  CONNECT BY PRIOR PARENT = task_id
                                                                                  START WITH task_id IN (SELECT task_id
                                                                                                           FROM role_task
                                                                                                          WHERE role_id = an_role_id) AND nshow = 1)
             AND NOT EXISTS (SELECT *
                               FROM tasks
                              WHERE PARENT = t.task_id)
    ORDER BY 4;
  END IF;
 END;

-----------------------------------------------------------------------------------------------------------------------------
 PROCEDURE editformlist_getshemas_p (acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT   monitor, NVL (NAME, '') NAME
       FROM monitor_schemes
   ORDER BY 1;
 END;

------------------------------------------------------------------------------------------------------------------------------
 PROCEDURE editformlist_readgroupnode_p (an_nodeparent NUMBER,   --наличие родителя
                                                              an_id NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  IF (an_nodeparent = 0) THEN
   OPEN acur_t FOR
    SELECT   1 havechild, gid, NAME
        FROM GROUPS g
       WHERE PARENT IS NULL AND mid IS NULL AND EXISTS (SELECT *
                                                          FROM GROUPS
                                                         WHERE PARENT = g.gid AND mid IS NULL)
    UNION ALL
    SELECT   0 havechild, gid, NAME
        FROM GROUPS g
       WHERE PARENT IS NULL AND mid IS NULL AND NOT EXISTS (SELECT *
                                                              FROM GROUPS
                                                             WHERE PARENT = g.gid AND mid IS NULL)
    ORDER BY 3;
  ELSE
   OPEN acur_t FOR
    SELECT   1 havechild, gid, NAME
        FROM GROUPS g
       WHERE PARENT = an_id AND mid IS NULL AND EXISTS (SELECT *
                                                          FROM GROUPS
                                                         WHERE PARENT = g.gid AND mid IS NULL)
    UNION ALL
    SELECT   0 havechild, gid, NAME
        FROM GROUPS g
       WHERE PARENT = an_id AND mid IS NULL AND NOT EXISTS (SELECT *
                                                              FROM GROUPS
                                                             WHERE PARENT = g.gid AND mid IS NULL)
    ORDER BY 3;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------------
 PROCEDURE editformlist_readnode1_p (an_nodeparent NUMBER,   --наличие родителя
                                                          an_tv NUMBER,   --какое дерево
                                                                       an_id NUMBER, an_currentschema NUMBER, acur_t OUT common_pg.tcur
 ) IS
 BEGIN
  IF (an_tv = 1) THEN
   IF (an_nodeparent = 0) THEN
    OPEN acur_t FOR
     SELECT   1 havechild, t.fid, NVL (t.codetemplate, 0) codetemplate, t.nameform, t.commentform, t.enablecontrols, NVL (t.stepprofile, 0) stepprofile,
              t.namealert, DECODE (NVL (t.codetemplate, 0), 0, 0, 1) priz, t.vprocname, ft.nameform, ft.enablecontrols, NVL (t.mid, 0) mid,
              util_pg.get_pointname (t.mid, 0, 0) midname
         FROM forms t, form_templates ft
        WHERE t.PARENT IS NULL AND t.monitor = an_currentschema AND t.codetemplate = ft.codetemplate(+)
              AND EXISTS (SELECT *
                            FROM forms
                           WHERE PARENT = t.fid AND monitor = an_currentschema)
     UNION ALL
     SELECT   0 havechild, t.fid, NVL (t.codetemplate, 0), t.nameform, t.commentform, t.enablecontrols, NVL (t.stepprofile, 0), t.namealert,
              DECODE (NVL (t.codetemplate, 0), 0, 0, 1) priz, t.vprocname, ft.nameform, ft.enablecontrols, NVL (t.mid, 0),
              util_pg.get_pointname (t.mid, 0, 0) midname
         FROM forms t, form_templates ft
        WHERE t.PARENT IS NULL AND t.monitor = an_currentschema AND t.codetemplate = ft.codetemplate(+)
              AND NOT EXISTS (SELECT *
                                FROM forms
                               WHERE PARENT = t.fid AND monitor = an_currentschema)
     ORDER BY 9, 4;
   ELSE
    OPEN acur_t FOR
     SELECT   1 havechild, t.fid, NVL (t.codetemplate, 0) codetemplate, t.nameform, t.commentform, t.enablecontrols, NVL (t.stepprofile, 0) stepprofile,
              t.namealert, DECODE (NVL (t.codetemplate, 0), 0, 0, 1) priz, t.vprocname, ft.nameform, ft.enablecontrols, NVL (t.mid, 0) mid,
              util_pg.get_pointname (t.mid, 0, 0) midname
         FROM forms t, form_templates ft
        WHERE t.PARENT = an_id AND t.monitor = an_currentschema AND t.codetemplate = ft.codetemplate(+)
              AND EXISTS (SELECT *
                            FROM forms
                           WHERE PARENT = t.fid AND monitor = an_currentschema)
     UNION ALL
     SELECT   0 havechild, t.fid, NVL (t.codetemplate, 0), t.nameform, t.commentform, t.enablecontrols, NVL (t.stepprofile, 0), t.namealert,
              DECODE (NVL (t.codetemplate, 0), 0, 0, 1) priz, t.vprocname, ft.nameform, ft.enablecontrols, NVL (t.mid, 0),
              util_pg.get_pointname (t.mid, 0, 0) midname
         FROM forms t, form_templates ft
        WHERE t.PARENT = an_id AND t.monitor = an_currentschema AND t.codetemplate = ft.codetemplate(+)
              AND NOT EXISTS (SELECT *
                                FROM forms
                               WHERE PARENT = t.fid AND monitor = an_currentschema)
     ORDER BY 9, 4;
   END IF;
  ELSE
   IF (an_nodeparent = 0) THEN
    OPEN acur_t FOR
     SELECT   1 havechild, template_id fid, NVL (codetemplate, 0) codetemplate, nameform, commentform, enablecontrols, NVL (stepprofile, 0) stepprofile, namealert,
              DECODE (NVL (codetemplate, 0), 0, 0, 1) priz, '' vprocname, '' nameform, enablecontrols, 0 mid, '' midname
         FROM form_templates t
        WHERE PARENT IS NULL AND EXISTS (SELECT *
                                           FROM form_templates
                                          WHERE PARENT = t.template_id)
     UNION ALL
     SELECT   0 havechild, template_id, NVL (codetemplate, 0), nameform, commentform, enablecontrols, NVL (stepprofile, 0), namealert,
              DECODE (NVL (codetemplate, 0), 0, 0, 1) priz, '', '', enablecontrols, 0, ''
         FROM form_templates t
        WHERE PARENT IS NULL AND NOT EXISTS (SELECT *
                                               FROM form_templates
                                              WHERE PARENT = t.template_id)
     ORDER BY 9, 4;
   ELSE
    OPEN acur_t FOR
     SELECT   1 havechild, template_id fid, NVL (codetemplate, 0) codetemplate, nameform, commentform, enablecontrols, NVL (stepprofile, 0) stepprofile, namealert,
              DECODE (NVL (codetemplate, 0), 0, 0, 1) priz, '' vprocname, nameform, enablecontrols, 0 mid, '' midname
         FROM form_templates t
        WHERE PARENT = an_id AND EXISTS (SELECT *
                                           FROM form_templates
                                          WHERE PARENT = t.template_id)
     UNION ALL
     SELECT   0 havechild, template_id, NVL (codetemplate, 0), nameform, commentform, enablecontrols, NVL (stepprofile, 0), namealert,
              DECODE (NVL (codetemplate, 0), 0, 0, 1) priz, '', nameform, enablecontrols, 0, ''
         FROM form_templates t
        WHERE PARENT = an_id AND NOT EXISTS (SELECT *
                                               FROM form_templates
                                              WHERE PARENT = t.template_id)
     ORDER BY 9, 4;
   END IF;
  END IF;
 END;

