 PROCEDURE editformlist_readnode2_p (an_id NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT   g.gid, f.fid
       FROM form_group g, forms f
      WHERE g.fid = f.fid AND f.PARENT = an_id
   ORDER BY DECODE (NVL (f.codetemplate, 0), 0, 0, 1), f.nameform;
 END;

--------------------------------------------------------------------------------------------------------------------------
 PROCEDURE editformlist_vclone_p (an_id1 NUMBER, an_id2 NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT e.fid fd1, fd.fid fd2
     FROM forms_ex e, forms f, forms fd
    WHERE e.fid = f.fid AND f.monitor = an_id1 AND fd.monitor = an_id2
          AND (fd.codetemplate = f.codetemplate OR (fd.codetemplate IS NULL AND f.codetemplate IS NULL))
          AND (fd.nameform = f.nameform OR (fd.nameform IS NULL AND f.nameform IS NULL))
          AND (fd.commentform = f.commentform OR (fd.commentform IS NULL AND f.commentform IS NULL))
          AND (fd.enablecontrols = f.enablecontrols OR (fd.enablecontrols IS NULL AND f.enablecontrols IS NULL))
          AND (fd.stepprofile = f.stepprofile OR (fd.stepprofile IS NULL AND f.stepprofile IS NULL))
          AND (fd.namealert = f.namealert OR (fd.namealert IS NULL AND f.namealert IS NULL))
          AND (fd.vprocname = f.vprocname OR (fd.vprocname IS NULL AND f.vprocname IS NULL)) AND (fd.mid = f.mid OR (fd.mid IS NULL AND f.mid IS NULL));
 END;

-----------------------------------------------------------------------------------------------------------------------------
 PROCEDURE chartinterior_selectdata_p (an_ispoints NUMBER,   --группа или точка fd-> IsPoints
                                                          an_stepprofile NUMBER,   -- детализация fd->StepProfile
                                                                                an_codetemplate NUMBER,   --код монитора fd->CodeTemplate
                                                                                                       an_stepprof NUMBER,   --//Минимальный шаг профиля в секундах
 av_firstdate VARCHAR2, av_lastdate VARCHAR2, an_idgroup NUMBER, an_periodforyearstart NUMBER, an_periodforyearfinish NUMBER, an_period NUMBER,
 acur_t OUT common_pg.tcur
 ) IS
  lv_inverted    VARCHAR2 (150);
  lv_subsel      VARCHAR2 (400);
  lv_subselect   VARCHAR2 (400);
  lv_table       VARCHAR2 (150);
  lv_partly_er   VARCHAR2 (400);
  lv_partly_ed   VARCHAR2 (400);
  lv_decperiod   VARCHAR2 (400);
  lv_paramlist   VARCHAR2 (600);
  lv_grouping    VARCHAR2 (200);
  lv_firstdate   DATE;
  lv_lastdate    DATE;
  lv_sql         VARCHAR2 (8000);
-----------------------------------
 BEGIN
  decperiod_p (an_ispoints,   --группа или точка
               lv_decperiod);
  subselect_p (an_stepprofile, lv_subselect);
  lv_firstdate := TO_DATE (av_firstdate, 'dd.mm.yyyy hh24:mi:ss') + interior_pg.get_hourtimezone;
  lv_lastdate := TO_DATE (av_lastdate, 'dd.mm.yyyy hh24:mi:ss') + interior_pg.get_hourtimezone;

  IF (an_ispoints = 1) THEN
   lv_inverted := ' ''n'' ';

   IF util_pg.isfolder (an_idgroup) = 1 THEN
    lv_subsel := ' G.mid in (select mid from points connect by prior mid=parent and prior ind not in (3,4) start with mid=:par3) ';
   ELSE
    lv_subsel := ' G.mid=:par3 ';
   END IF;
   lv_table := ' points ';
   lv_partly_er := ' ';
   lv_partly_ed := ' ';
  ELSE
   lv_inverted := 'G.inverted';
   lv_subsel :=
    ' G.gid in (select gid from groups connect by ((prior gid=parent) or
          (prior NROOT2=NROOT2 and prior nroot1>0 and nroot1 is null) ' || lv_subselect || ') start with gid=:par3 ' || lv_subselect || ') ';
   lv_table := ' groups ';
   lv_partly_er := ' *decode(g.NPARTLY,2,0,1) ';
   lv_partly_ed := ' *decode(g.NPARTLY,1,0,1) ';
  END IF;

  lv_grouping := ' floor((date_time- interior_pg.get_hourtimezone-:par1)*86400/:par4) ';

  IF (an_codetemplate = gn_apro_c) THEN
   lv_paramlist :=
    ',sum((-util_pg.sld(P.mid,nvl(P.er' || lv_partly_er || ',0),
                     nvl(P.ed' || lv_partly_ed || ',0)))*DECODE(' || lv_inverted || ',''y'',1,-1)' || lv_decperiod || ')*3600/:par4/1000 ';
  ELSIF (an_codetemplate = gn_rpro_c) THEN
   lv_paramlist := ',sum((-util_pg.sld(P.mid,nvl(P.q1,0),nvl(P.q3,0)))*DECODE(' || lv_inverted || ',''y'',1,-1)' || lv_decperiod || ')*3600/:par4/1000 ';
  END IF;

  lv_sql :=
   'select ' || lv_grouping || 'BCount' || lv_paramlist || 'AParam from  profile  P, ' || lv_table
   || 'G
	 where P.mid=G.mid AND
	 date_time >= :par1
	 and date_time <= :par2
     and ' || lv_subsel || '
     group by ' || lv_grouping || 'order by 1';

  IF (an_ispoints = 1) THEN
   OPEN acur_t FOR lv_sql USING lv_firstdate, an_stepprof, an_stepprof, lv_firstdate, lv_lastdate, an_idgroup, lv_firstdate, an_stepprof;
  ELSIF (an_ispoints = 0) THEN
   IF (an_stepprofile = gn_stpmonth) THEN
    OPEN acur_t FOR lv_sql
    USING lv_firstdate, an_stepprof, an_stepprof, lv_firstdate, lv_lastdate, an_periodforyearfinish, an_periodforyearstart, an_idgroup, an_periodforyearfinish,
          an_periodforyearstart, lv_firstdate, an_stepprof;
   ELSE
    OPEN acur_t FOR lv_sql USING lv_firstdate, an_stepprof, an_stepprof, lv_firstdate, lv_lastdate, an_period, an_idgroup, an_period, lv_firstdate, an_stepprof;
   END IF;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE interior_formdescr_p (an_ispoints NUMBER,   --группа или точка fd-> IsPoints
                                                    an_stepprofile NUMBER,   -- детализация fd->StepProfile
                                                                          an_idgroup NUMBER, an_periodforyearstart NUMBER, an_periodforyearfinish NUMBER,
 an_period NUMBER, acur_t OUT common_pg.tcur
 ) IS
  lv_subselect   VARCHAR2 (200);
  lv_sql         VARCHAR2 (4000);
 BEGIN
  IF (an_ispoints = 1) THEN
   lv_sql := 'select mid, nvl(util_pg.get_shortname_f(short_name,mid),util_pg.get_name_f(name,mid))name
         from points where parent = :par1 order by 2';
  ELSE
   subselect_p (an_stepprofile, lv_subselect);
   lv_sql :=
    'select gid mid, nvl(util_pg.get_shortname_f(short_name,mid),util_pg.get_name_f(name,mid))name
         from groups where parent = :par1
         ' || lv_subselect || ' order by 2';
  END IF;

  IF (an_ispoints = 1) THEN
   OPEN acur_t FOR lv_sql USING an_idgroup;
  ELSIF (an_ispoints = 0) THEN
   IF (an_stepprofile = gn_stpmonth) THEN
    OPEN acur_t FOR lv_sql USING an_idgroup, an_periodforyearfinish, an_periodforyearstart;
   ELSE
    OPEN acur_t FOR lv_sql USING an_idgroup, an_period;
   END IF;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
 PROCEDURE limitpowerint_selectdata_p (an_ispoints NUMBER,   --группа или точка fd-> IsPoints
                                                          an_stepprofile NUMBER,   -- детализация fd->StepProfile только gn_stpHour,gn_stpMinute
                                                                                an_codetemplate NUMBER,   --код монитора fd->CodeTemplate
                                                                                                       av_rowcount VARCHAR2,   -- RowCount
                                                                                                                            an_powerprofile NUMBER,   --// Количество строк при выводе графика нагрузки
 an_stepprof NUMBER,   --//Минимальный шаг профиля в секундах
                    av_firstdate VARCHAR2, av_lastdate VARCHAR2, an_idgroup NUMBER, an_period NUMBER, acur_t OUT common_pg.tcur
 ) IS
  lv_subselect       VARCHAR2 (1000);
  lv_table           VARCHAR2 (150);
  lv_partly_er       VARCHAR2 (600);
  lv_partly_ed       VARCHAR2 (600);
  lv_decnsourcesec   VARCHAR2 (1000);
  lv_decnsourcef     VARCHAR2 (1000);
  lv_decperiod       VARCHAR2 (600);
  lv_paramlist       VARCHAR2 (4000);
  lv_grouping        VARCHAR2 (600);
  lv_firstdate       DATE;
  lv_lastdate        DATE;
  lv_sql             VARCHAR2 (10000);
-----------------------------------
 BEGIN
  lv_firstdate := TO_DATE (av_firstdate, 'dd.mm.yyyy hh24:mi:ss') + interior_pg.get_hourtimezone;
  lv_lastdate := TO_DATE (av_lastdate, 'dd.mm.yyyy hh24:mi:ss') + interior_pg.get_hourtimezone;
  takeofpartquerifornsorse_p (an_ispoints,   --группа или точка
                              an_stepprofile,   -- детализация только gn_stpHour,gn_stpMinute
                              av_rowcount,   --
                              lv_firstdate, lv_lastdate, lv_decnsourcesec, lv_decnsourcef);
  decperiod_p (an_ispoints,   --группа или точка
               lv_decperiod);
  subselect_p (an_stepprofile, lv_subselect);

  IF (an_ispoints = 1) THEN
   lv_partly_er := ' ';
   lv_partly_ed := ' ';
  ELSE
   lv_partly_er := ' *decode(g.NPARTLY,2,0,1) ';
   lv_partly_ed := ' *decode(g.NPARTLY,1,0,1) ';
  END IF;

  IF (an_codetemplate = gn_apbo_f) THEN
   lv_paramlist :=
    ',sum(DECODE(G.inverted,''y'',-util_pg.sld(P.mid,nvl(P.er' || lv_partly_er || ',0),
                  nvl(P.ed' || lv_partly_ed || ',0)),util_pg.sld(P.mid,nvl(P.er' || lv_partly_er || ',0),
                  nvl(P.ed' || lv_partly_ed || ',0)))' || lv_decperiod || ')*3600/:par4/1000 ';
  ELSIF (an_codetemplate = gn_rpbo_f) THEN
   lv_paramlist :=
    ',sum(DECODE(G.inverted,''y'',-util_pg.sld(P.mid,nvl(P.q1,0),nvl(P.q3,0)),
                  util_pg.sld(P.mid,nvl(P.q1,0),nvl(P.q3,0)))' || lv_decperiod || ')*3600/:par4/1000 ';
  END IF;

  IF (an_stepprofile = gn_stphour) THEN
   lv_grouping := ' 1+FLOOR((date_time- interior_pg.get_hourtimezone-:par1)*' || TO_CHAR (1440.0 / an_powerprofile) || ' )';
   lv_table := ' halfhour ';
  ELSIF (an_stepprofile = gn_stpminute) THEN
   lv_grouping := ' 1+FLOOR((date_time- interior_pg.get_hourtimezone-:par1)*86400/:par4) ';
   lv_table := ' profile ';
  END IF;

  lv_sql :=
   'select ' || lv_grouping || ' BGroup' || lv_paramlist || ' AParam' || lv_decnsourcef || ' decnsour from ' || lv_table
   || ' P, groups G
	 where P.mid=G.mid AND 
	 date_time >= :par1
	 and   date_time <= :par2
     and   G.gid in (select gid from groups
     connect by ((prior gid=parent) or (prior NROOT2=NROOT2 and prior nroot1>0 and nroot1 is null) '
   || lv_subselect || '  )
     start with gid=:par3 ' || lv_subselect || ') group by ' || lv_grouping || ' order by 1';

  IF (an_stepprofile = gn_stphour) THEN
   OPEN acur_t FOR lv_sql USING lv_firstdate, an_stepprof, an_idgroup, lv_firstdate, lv_lastdate, an_period, an_idgroup, an_period, lv_firstdate;
  ELSIF (an_stepprofile = gn_stpminute) THEN
   OPEN acur_t FOR lv_sql USING lv_firstdate, an_stepprof, an_stepprof, an_idgroup, lv_firstdate, lv_lastdate, an_period, an_idgroup, an_period, lv_firstdate,
   an_stepprof;
  END IF;
 END;

-------------------------------------------------------------------------------------------------------------------------------
 PROCEDURE limitpowerint_selectdata2_p (an_sec NUMBER, an_stepprof NUMBER,   --//Минимальный шаг профиля в секундах
                                                                          av_firstdate VARCHAR2, av_lastdate VARCHAR2, an_idgroup NUMBER, an_period NUMBER,
 acur_t OUT common_pg.tcur
 ) IS
 BEGIN
  OPEN acur_t FOR
   SELECT   CEIL ((TRUNC (TO_DATE (av_firstdate, 'dd.mm.yyyy hh24:mi:ss')) + (morning_start - TRUNC (morning_start))
                   - (TO_DATE (av_firstdate, 'dd.mm.yyyy hh24:mi:ss')) + an_sec
                  )
                  * 86400 / an_stepprof) morning_start,
            FLOOR ((TRUNC (TO_DATE (av_firstdate, 'dd.mm.yyyy hh24:mi:ss')) + (morning_end - TRUNC (morning_end))
                    - (TO_DATE (av_firstdate, 'dd.mm.yyyy hh24:mi:ss')) + an_sec
                   )
                   * 86400 / an_stepprof)
            + 2 morning_end,
            CEIL ((TRUNC (TO_DATE (av_firstdate, 'dd.mm.yyyy hh24:mi:ss')) + (evening_start - TRUNC (evening_start))
                   - (TO_DATE (av_firstdate, 'dd.mm.yyyy hh24:mi:ss')) + an_sec
                  )
                  * 86400 / an_stepprof) evening_start,
            FLOOR ((TRUNC (TO_DATE (av_firstdate, 'dd.mm.yyyy hh24:mi:ss')) + (evening_end - TRUNC (evening_end))
                    - (TO_DATE (av_firstdate, 'dd.mm.yyyy hh24:mi:ss')) + an_sec
                   )
                   * 86400 / an_stepprof)
            + 2 evening_end,
            num, date_time
       FROM (SELECT gl.morning_start, gl.morning_end, gl.evening_start, gl.evening_end, 1 num, gl.dstart date_time
               FROM (SELECT   gid, MAX (dstart) dstart
                         FROM grouplimit
                        WHERE dstart < (TO_DATE (av_lastdate, 'dd.mm.yyyy hh24:mi:ss')) AND morning_start IS NOT NULL AND morning_end IS NOT NULL
                              AND evening_start IS NOT NULL AND evening_end IS NOT NULL
                     GROUP BY gid) mgl,
                    grouplimit gl,
                    (SELECT     gid
                           FROM GROUPS g
                          WHERE EXISTS (
                                 SELECT *
                                   FROM grouplimit
                                  WHERE gid = g.gid AND dstart < (TO_DATE (av_lastdate, 'dd.mm.yyyy hh24:mi:ss')) AND morning_start IS NOT NULL
                                        AND morning_end IS NOT NULL AND evening_start IS NOT NULL AND evening_end IS NOT NULL)
                                AND ROWNUM = 1
                     CONNECT BY PRIOR g.PARENT = g.gid AND (an_period BETWEEN NVL (g.nfromperiod, 0) AND NVL (g.ntillperiod, 299912))
                     START WITH g.gid = an_idgroup AND (an_period BETWEEN NVL (g.nfromperiod, 0) AND NVL (g.ntillperiod, 299912))) g
              WHERE g.gid = mgl.gid AND mgl.gid = gl.gid(+) AND mgl.dstart = gl.dstart(+)
             UNION ALL
             SELECT morning_start, morning_end, evening_start, evening_end, 2 num, date_time
               FROM maxhours
              WHERE date_time <= (TO_DATE (av_lastdate, 'dd.mm.yyyy hh24:mi:ss')))
   ORDER BY 5, 6 DESC;
 END;

----------------------------------------------------------------------------------------------------------------------------
 PROCEDURE limitpowerint_selectdata3_p (an_codetemplate NUMBER,   --код монитора fd->CodeTemplate
                                                               av_lastdate VARCHAR2, an_idgroup NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  IF (an_codetemplate = gn_apbo_f) THEN
   OPEN acur_t FOR
    SELECT   NVL (ROUND (nlimitcons / 1000 / TO_NUMBER (TO_CHAR (LAST_DAY (TO_DATE (av_lastdate, 'dd.mm.yyyy hh24:mi:ss')), 'DD')), 3), -3.40282347e+38) ea,
             NVL (ROUND (nlimitcapm / 1000, 3), -3.40282347e+38) pa_morning, NVL (ROUND (nlimitcape / 1000, 3), -3.40282347e+38) pa_evening
        FROM grouplimit
       WHERE gid = an_idgroup AND dstart <= (TO_DATE (av_lastdate, 'dd.mm.yyyy hh24:mi:ss'))
    ORDER BY dstart DESC;
  ELSIF (an_codetemplate = gn_rpbo_f) THEN
   OPEN acur_t FOR
    SELECT   NVL (DECODE (1, 2, 1, NULL), -3.40282347e+38) ea, NVL (DECODE (1, 2, 1, NULL), -3.40282347e+38) pa_morning,
             NVL (DECODE (1, 2, 1, NULL), -3.40282347e+38) pa_evening
        FROM grouplimit
       WHERE gid = an_idgroup AND dstart <= (TO_DATE (av_lastdate, 'dd.mm.yyyy hh24:mi:ss'))
    ORDER BY dstart DESC;
  END IF;
 END;

----------------------------------------------------------------------------------------------------------------------------
 PROCEDURE limitpowerint_formdescr_p (an_idgroup NUMBER, an_period NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT   gid, NVL (util_pg.get_shortname_f (short_name, mid), util_pg.get_name_f (NAME, mid)) NAME, 1
       FROM GROUPS
      WHERE gid = an_idgroup AND (an_period BETWEEN NVL (nfromperiod, 0) AND NVL (ntillperiod, 299912))
   UNION
   SELECT   gid, NVL (util_pg.get_shortname_f (short_name, mid), util_pg.get_name_f (NAME, mid)), 2
       FROM GROUPS
      WHERE PARENT = an_idgroup AND (an_period BETWEEN NVL (nfromperiod, 0) AND NVL (ntillperiod, 299912))
   ORDER BY 3, 2;
 END;

----------------------------------------------------------------------------------------------------------------------------
 PROCEDURE tduinterior_formdescr_p (an_idgroup NUMBER, an_period NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT   gid, NVL (util_pg.get_shortname_f (short_name, mid), util_pg.get_name_f (NAME, mid)) short_name
       FROM GROUPS
      WHERE PARENT = an_idgroup AND (an_period BETWEEN NVL (nfromperiod, 0) AND NVL (ntillperiod, 299912))
   ORDER BY 2;
 END;

-----------------------------------------------------------------------------------------------------------------------------
 PROCEDURE tduinterior_selectdata_p (an_ispoints NUMBER,   --группа или точка fd-> IsPoints
                                                        av_obsoletetimelimit VARCHAR2, an_tempgid NUMBER, an_period NUMBER, acur_t OUT common_pg.tcur
 ) IS
  lv_partly_er   VARCHAR2 (500);
  lv_partly_ed   VARCHAR2 (500);
 BEGIN
  IF (an_ispoints = 0) THEN
   lv_partly_er := ' *decode(c.NPARTLY,2,0,1) ';
   lv_partly_ed := ' *decode(c.NPARTLY,1,0,1) ';
  ELSE
   lv_partly_er := ' ';
   lv_partly_ed := ' ';
  END IF;

  OPEN acur_t FOR 'select 
        decode(nvl(sum(obsolete),1),0,to_number(to_char(max(c.date_time),''-ddmmhh24mi'')),nvl(sum(obsolete),1)) obsolete,
        round(sum(decode(obsolete,0,(-util_pg.sld( c.mid,nvl(c.er'
                  || lv_partly_er || ',0),nvl(c.ed' || lv_partly_ed
                  || ',0)))*c.inverted,null))/1000,3)DT,
        round(sum(decode(obsolete,0,(-util_pg.sld( c.mid,nvl(c.q1,0),nvl(c.q3,0)))*c.inverted,null))/1000,3)DAT,
        to_char(max(c.date_time),''-ddmmhh24mi'') cur_date
        from (
        select c.mid,date_time,er,ed,q1,q3,
        decode(sign('
                  || av_obsoletetimelimit
                  || '-abs(sysdate-decode(implement_date,null,sysdate,c.date_time))),1,0,1) obsolete,
        decode(inverted,''y'',1,-1) inverted,NPARTLY from curr_power c, points p,
         (select mid,inverted,NPARTLY from groups
         connect by ((prior gid=parent) or (prior NROOT2=NROOT2 and prior nroot1>0 and nroot1 is null)
         AND (:par2 BETWEEN  nvl(nfromperiod,0) AND nvl(ntillperiod,299912))
         )
         start with gid=:par1 
         AND (:par2 BETWEEN  nvl(nfromperiod,0) AND nvl(ntillperiod,299912))
         ) f
         where f.mid=c.mid and c.mid=p.mid(+)) c ' USING an_period, an_tempgid, an_period;
 END;

------------------------------------------------------------------------------------------------------------------------------
 PROCEDURE tduinterior_clickcomposition_p (an_arow NUMBER, an_idgroup NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  IF (an_arow = 0) THEN
   OPEN acur_t FOR
    SELECT NVL (PARENT, 0) idgroup
      FROM GROUPS
     WHERE gid = an_idgroup;
  ELSE
   OPEN acur_t FOR
    SELECT COUNT (*) tempidgroup
      FROM GROUPS
     WHERE PARENT = an_idgroup;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------------
 PROCEDURE tduinterior_clickcomp2_p (an_idgroup NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT NVL (util_pg.get_name_f (NAME, mid), util_pg.get_shortname_f (short_name, mid)) NAME,
          NVL (util_pg.get_shortname_f (short_name, mid), util_pg.get_name_f (NAME, mid)) shortname, NVL (group_total, 'n') sumgroup
     FROM GROUPS
    WHERE gid = an_idgroup;
 END;

