 PROCEDURE tconsumlimit_selectdata_p (an_ispoints NUMBER,   --группа или точка fd-> IsPoints
                                                         av_obsoletetimelimit VARCHAR2, an_stepprofile NUMBER,   -- детализация только gn_stpHour,gn_stpMinute
 an_groupislist NUMBER, an_tempgid NUMBER, an_periodforyearstart NUMBER, an_periodforyearfinish NUMBER, an_period NUMBER, acur_t OUT common_pg.tcur
 ) IS
  lv_subtab      VARCHAR2 (1000);
  lv_partly_er   VARCHAR2 (400);
  lv_partly_ed   VARCHAR2 (400);
  lv_subselect   VARCHAR2 (1000);
  lv_sql         VARCHAR2 (10000);
 BEGIN
  IF (an_stepprofile = gn_stpmonth) THEN
   lv_subtab := ' AND ( nvl(g2.nfromperiod,0)<=:par3 OR nvl(g2.ntillperiod,299912)>=:par2) ';
  ELSE
   lv_subtab := ' AND (:par2 BETWEEN  nvl(g2.nfromperiod,0) AND nvl(g2.ntillperiod,299912))';
  END IF;

  IF (an_ispoints = 0) THEN
   lv_partly_er := '*decode(c.NPARTLY,2,0,1)';
   lv_partly_ed := '*decode(c.NPARTLY,1,0,1)';
  ELSE
   lv_partly_er := '';
   lv_partly_ed := '';
  END IF;

  subselect_p (an_stepprofile, lv_subselect);
  lv_sql :=
   'select limit, fact/1000 afact, fact/1000-limit limfact, armor, nvl(obsolete,1)obs
              from (select
              decode(sum(obsolete),0,to_char(max(c.date_time),''-hh24mi''),sum(obsolete)) obsolete,
              sum(decode(obsolete,0,(-util_pg.sld(c.mid,nvl(c.er'
   || lv_partly_er || ',0),nvl(c.ed' || lv_partly_ed
   || ',0)))*c.inverted,null)) fact
              from (select c.mid,date_time,er,ed,q1,q3,
              decode(sign(' || av_obsoletetimelimit
   || '-abs(sysdate-decode(implement_date,null,sysdate,c.date_time))),1,0,1) obsolete,
              decode(inverted,''y'',1,-1) inverted,NPARTLY from curr_power c, points p,
              (select mid,inverted,NPARTLY from groups
              connect by ((prior gid=parent) or (prior NROOT2=NROOT2 and prior nroot1>0 and nroot1 is null)
               '
   || lv_subselect || ' )
              start with gid=:par1
              ' || lv_subselect
   || ' ) f
              where f.mid=c.mid and c.mid=p.mid(+))c),
              (select sum(decode(flag,1,c.NLIMITCAPM,-1,c.NLIMITCAPE))/1000 limit ,sum(NEMERGENCYRESERVE)/1000 armor
              from (select decode(decode(sign(to_number(to_char(util_pg.planhour_f(1),''sssss''))-to_number(to_char(sysdate,''sssss''))),0,-1,1,1,-1,-1)+
              decode(sign(to_number(to_char(util_pg.planhour_f(2),''sssss''))-to_number(to_char(sysdate,''sssss''))),0,-1,1,1,-1,-1)
              ,2,-1,-2,-1,0,1) flag from dual), ';

  IF (an_groupislist = 1) THEN
   lv_sql :=
    lv_sql
    || ' grouplimit c,(select gid,NEMERGENCYRESERVE from groups
                     where gid=(SELECT g2.gid FROM groups g1, groups g2
                     WHERE g1.gid=:par1 AND g1.nroot2 = g2.nroot2 AND g2.nroot1 IS NULL
                      '
    || lv_subtab || ' )) g ';
  ELSE
   lv_sql := lv_sql || ' grouplimit c,(select gid,NEMERGENCYRESERVE from groups where gid=:par1
                ' || lv_subselect || ' ) g ';
  END IF;

  lv_sql := lv_sql || ' where c.gid=g.gid and c.dstart=(select max(dstart) from grouplimit where gid=c.gid and dstart<sysdate))';

  IF (an_stepprofile = gn_stpmonth) THEN
   OPEN acur_t FOR lv_sql
   USING an_periodforyearfinish, an_periodforyearstart, an_tempgid, an_periodforyearfinish, an_periodforyearstart, an_tempgid, an_periodforyearfinish,
         an_periodforyearstart;
  ELSE
   OPEN acur_t FOR lv_sql USING an_period, an_tempgid, an_period, an_tempgid, an_period;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------------
 PROCEDURE tconsumlimit_formdescr_p (an_ispoints NUMBER,   --группа или точка fd-> IsPoints
                                                        an_stepprofile NUMBER,   -- детализация fd->StepProfile
                                                                              an_idgroup NUMBER, an_periodforyearstart NUMBER, an_periodforyearfinish NUMBER,
 an_period NUMBER, acur_t OUT common_pg.tcur
 ) IS
  lv_subselect   VARCHAR2 (200);
  lv_sql         VARCHAR2 (4000);
 BEGIN
  IF (an_ispoints = 1) THEN
   lv_sql := 'select g.mid, nvl(short_name,name)name from points g where parent = :par1 order by 2';
  ELSE
   subselect_p (an_stepprofile, lv_subselect);
   lv_sql := 'select g.gid mid, nvl(short_name,name)name from groups g where parent = :par1
              ' || lv_subselect || ' order by 2';
  END IF;

  IF (an_ispoints = 1) THEN
   OPEN acur_t FOR lv_sql USING an_idgroup;
  ELSIF (an_ispoints = 0) THEN
   IF (an_stepprofile = gn_stpmonth) THEN
    OPEN acur_t FOR lv_sql USING an_idgroup, an_periodforyearfinish, an_periodforyearstart;
   ELSE
    OPEN acur_t FOR lv_sql USING an_idgroup, an_period;
   END IF;
  END IF;
 END;

