 PROCEDURE tconsumimbalance_selectdata_p (an_ispoints NUMBER,   --группа или точка fd-> IsPoints
                                                             av_obsoletetimelimit VARCHAR2, an_codetemplate NUMBER, an_stepprofile NUMBER,   -- детализация только gn_stpHour,gn_stpMinute
 an_tempgid NUMBER, an_periodforyearstart NUMBER, an_periodforyearfinish NUMBER, an_period NUMBER, av_firstdate VARCHAR2, av_lastdate VARCHAR2,
 acur_t OUT common_pg.tcur
 ) IS
  lv_subtab        VARCHAR2 (1000);
  lv_partly_er     VARCHAR2 (400);
  lv_partly_ed     VARCHAR2 (400);
  lv_subselect     VARCHAR2 (1000);
  lv_sql           VARCHAR2 (10000);
  lv_table         VARCHAR2 (200);
  lv_decperiod     VARCHAR2 (400);
  lv_oracletable   VARCHAR2 (200);
 BEGIN
  IF (an_ispoints = 1) THEN
   lv_table := 'points';
   lv_partly_er := ' ';
   lv_partly_ed := ' ';
  ELSE
   lv_table := 'groups';
   lv_partly_er := '*decode(g.NPARTLY,2,0,1)';
   lv_partly_ed := '*decode(g.NPARTLY,1,0,1)';
  END IF;

  subselect_p (an_stepprofile, lv_subselect);
  decperiod_p (an_ispoints, lv_decperiod);

  IF (an_codetemplate = gn_consumimbalance_pow_f) THEN
   lv_sql :=
    ' SELECT to_char(sysdate, ''dd.mm.yyyy hh24:mi'')currTime, ain, aall, decode(ain,0,-100,aall/ain*100)dat, obsolete
                FROM
                (SELECT SUM(DECODE(G.inverted,''y'',nvl(c.ed'
    || lv_partly_ed || ',0),nvl(c.er' || lv_partly_er || ',0)))/1000 ain,
                SUM((-util_pg.sld(c.mid,nvl(c.er' || lv_partly_er || ',0),nvl(c.ed' || lv_partly_ed || ',0)))*DECODE(G.inverted,''y'',1,-1)' || lv_decperiod
    || ')/1000 aall,
                SUM(decode( sign(' || av_obsoletetimelimit || '-abs(sysdate-c.date_time)),1,c.obsolete,1)) obsolete
                FROM curr_power c, ' || lv_table
    || ' g
                WHERE c.mid = g.mid AND g.gid IN
                 (select gid from groups
                 connect by ((prior gid=parent) or (prior NROOT2=NROOT2 and prior nroot1>0 and nroot1 is null)
                '
    || lv_subselect || ' )
                 start with gid=:par1 ' || lv_subselect || ' )) ';
  ELSE
   interior2_choiceoftable_p (0, an_stepprofile, lv_oracletable);
   lv_sql :=
    ' SELECT to_char(sysdate, ''hh24:mi'') currTime, ain, aall, decode(ain,0,decode(aall,0,0,-100),aall/ain*100) dat, obsolete
                FROM
                (SELECT SUM(DECODE(G.inverted,''y'',nvl(c.ed'
    || lv_partly_ed || ',0),nvl(c.er' || lv_partly_er || ',0)))/1000 ain,
                SUM((-util_pg.sld(c.mid,nvl(c.er' || lv_partly_er || ',0),nvl(c.ed' || lv_partly_ed || ',0)))*DECODE(G.inverted,''y'',1,-1)' || lv_decperiod
    || ')/1000 aall,
                0 obsolete
                FROM ' || lv_oracletable || ' c , ' || lv_table || ' g
                WHERE c.mid = g.mid AND date_time >= (to_date(''' || av_firstdate
    || ''', ''dd.mm.yyyy hh24:mi:ss''))
                AND  date_time <= (to_date(''' || av_lastdate
    || ''', ''dd.mm.yyyy hh24:mi:ss'')) AND g.gid IN
                 (select gid from groups
                 connect by ((prior gid=parent) or (prior NROOT2=NROOT2 and prior nroot1>0 and nroot1 is null)
                '
    || lv_subselect || ' )
                 start with gid=:par1 ' || lv_subselect || ')) ';
  END IF;

  IF (an_stepprofile = gn_stpmonth) THEN
   OPEN acur_t FOR lv_sql USING an_periodforyearfinish, an_periodforyearstart, an_tempgid, an_periodforyearfinish, an_periodforyearstart;
  ELSE
   OPEN acur_t FOR lv_sql USING an_period, an_tempgid, an_period;
  END IF;
 END;

---------------------------------------------------------------------------------------------------------------------------
 PROCEDURE tdecadinterior_selectdata_p (an_ispoints NUMBER,   --группа или точка fd-> IsPoints
                                                           av_datetime VARCHAR2, an_codetemplate NUMBER, an_stepprofile NUMBER,   -- детализация только gn_stpHour,gn_stpMinute
 an_tempgid NUMBER, an_periodforyearstart NUMBER, an_periodforyearfinish NUMBER, an_period NUMBER, acur_t OUT common_pg.tcur
 ) IS
  lv_subtab      VARCHAR2 (1000);
  lv_partly_er   VARCHAR2 (400);
  lv_partly_ed   VARCHAR2 (400);
  lv_subselect   VARCHAR2 (1000);
  lv_sql         VARCHAR2 (10000);
  lv_table       VARCHAR2 (200);
  lv_decperiod   VARCHAR2 (400);
  lv_inverted    VARCHAR2 (200);
  lv_paramlist   VARCHAR2 (1000);
 BEGIN
  subselect_p (an_stepprofile, lv_subselect);

  IF (an_ispoints = 1) THEN
   lv_table := 'points';
   lv_partly_er := ' ';
   lv_partly_ed := ' ';

   IF util_pg.isfolder (an_tempgid) = 1 THEN
    lv_subtab := ' G.mid in (select mid from points connect by prior mid=parent and prior ind not in (3,4) start with mid=:par3) ';
   ELSE
    lv_subtab := ' G.mid=:par3 ';
   END IF;
   lv_inverted := '''n''';
  ELSE
   lv_table := 'groups';
   lv_partly_er := '*decode(g.NPARTLY,2,0,1)';
   lv_partly_ed := '*decode(g.NPARTLY,1,0,1)';
   lv_subtab :=
    ' and G.gid in (select gid from groups connect by ((prior gid=parent) or (prior NROOT2=NROOT2 and prior nroot1>0 and nroot1 is null)
               ' || lv_subselect || ' ) start with gid=:par2 ' || lv_subselect || ' )';
   lv_inverted := 'G.inverted';
  END IF;

  decperiod_p (an_ispoints, lv_decperiod);

  IF (an_codetemplate = gn_aero_decad_f) THEN
   lv_paramlist := ' sum(DECODE(' || lv_inverted || ',''y'',nvl(b.ed' || lv_partly_ed || ',0), nvl(b.er' || lv_partly_er || ',0))' || lv_decperiod || ')/1000 val ';
  ELSIF (an_codetemplate = gn_aebo_decad_f) THEN
   lv_paramlist :=
    ' sum( -util_pg.sld( b.mid, nvl(b.er' || lv_partly_er || ',0),
                 (nvl(b.ed' || lv_partly_ed || ',0) ) )*DECODE(' || lv_inverted || ',''y'',1,-1)' || lv_decperiod || ')/1000 val ';
  END IF;

  lv_paramlist := lv_paramlist || ' , 0 nsource ';
  lv_sql :=
   'SELECT ' || lv_paramlist || '
              FROM bill b, ' || lv_table
   || ' g
              WHERE b.mid = g.mid AND
              date_time > trunc((to_date(:par1, ''dd.mm.yyyy hh24:mi:ss'')+ INTERIOR_PG.get_hourtimezone),''mm'')
              and   date_time <=  to_date(''11''||to_char((to_date(:par1, ''dd.mm.yyyy hh24:mi:ss'')+ INTERIOR_PG.get_hourtimezone),''.mm.yyyy hh24:mi:ss''),''dd.mm.yyyy hh24:mi:ss'')
              and   sysdate > to_date(''11''||to_char((to_date(:par1, ''dd.mm.yyyy hh24:mi:ss'')+ INTERIOR_PG.get_hourtimezone),''.mm.yyyy hh24:mi:ss''),''dd.mm.yyyy hh24:mi:ss'')
             '
   || lv_subtab || '
              UNION ALL 
             SELECT ' || lv_paramlist || '
              FROM bill b, ' || lv_table
   || ' g
              WHERE b.mid = g.mid AND 
              date_time > trunc((to_date(:par1, ''dd.mm.yyyy hh24:mi:ss'')+ INTERIOR_PG.get_hourtimezone),''mm'')
              and   date_time <=  to_date(''21''||to_char((to_date(:par1, ''dd.mm.yyyy hh24:mi:ss'')+ INTERIOR_PG.get_hourtimezone),''.mm.yyyy hh24:mi:ss''),''dd.mm.yyyy hh24:mi:ss'')
              and   sysdate > to_date(''21''||to_char((to_date(:par1, ''dd.mm.yyyy hh24:mi:ss'')+ INTERIOR_PG.get_hourtimezone),''.mm.yyyy hh24:mi:ss''),''dd.mm.yyyy hh24:mi:ss'')
             '
   || lv_subtab || '
             UNION ALL 
             SELECT ' || lv_paramlist || '
              FROM bill b, ' || lv_table
   || ' g
              WHERE b.mid = g.mid AND 
              date_time > trunc((to_date(:par1, ''dd.mm.yyyy hh24:mi:ss'')+ INTERIOR_PG.get_hourtimezone),''mm'')
              and   date_time <=  add_months(trunc((to_date(:par1, ''dd.mm.yyyy hh24:mi:ss'')+ INTERIOR_PG.get_hourtimezone),''mm''),1)
              and   sysdate > add_months(trunc((to_date(:par1, ''dd.mm.yyyy hh24:mi:ss'')+ INTERIOR_PG.get_hourtimezone),''mm''),1)
              '
   || lv_subtab;

  IF (an_ispoints = 1) THEN
   OPEN acur_t FOR lv_sql
   USING av_datetime, av_datetime, av_datetime, an_tempgid, av_datetime, av_datetime, av_datetime, an_tempgid, av_datetime, av_datetime, av_datetime, an_tempgid;
  ELSE
   IF (an_stepprofile = gn_stpmonth) THEN
    OPEN acur_t FOR lv_sql
    USING av_datetime, av_datetime, av_datetime, an_periodforyearfinish, an_periodforyearstart, an_tempgid, an_periodforyearfinish, an_periodforyearstart,
          av_datetime, av_datetime, av_datetime, an_periodforyearfinish, an_periodforyearstart, an_tempgid, an_periodforyearfinish, an_periodforyearstart,
          av_datetime, av_datetime, av_datetime, an_periodforyearfinish, an_periodforyearstart, an_tempgid, an_periodforyearfinish, an_periodforyearstart;
   ELSE
    OPEN acur_t FOR lv_sql
    USING av_datetime, av_datetime, av_datetime, an_period, an_tempgid, an_period, av_datetime, av_datetime, av_datetime, an_period, an_tempgid, an_period,
          av_datetime, av_datetime, av_datetime, an_period, an_tempgid, an_period;
   END IF;
  END IF;
 END;

----------------------------------------------------------------------------------------------------------------------
 PROCEDURE monitorlist_readtreen_p (an_nodeparent NUMBER, an_monitor NUMBER, an_monitor_id NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  IF (an_nodeparent = 0) THEN
   OPEN acur_t FOR
    SELECT   1 havechild, monitor_id, mschema, NAME, dsize, DECODE (dsize, 0, 1, 2)
        FROM monitors m
       WHERE mschema = an_monitor AND nparent IS NULL AND EXISTS (SELECT *
                                                                    FROM monitors
                                                                   WHERE nparent = m.monitor_id)
    UNION ALL
    SELECT   0 havechild, monitor_id, mschema, NAME, dsize, DECODE (dsize, 0, 1, 2)
        FROM monitors m
       WHERE mschema = an_monitor AND nparent IS NULL AND NOT EXISTS (SELECT *
                                                                        FROM monitors
                                                                       WHERE nparent = m.monitor_id)
    ORDER BY 6, 4;
  ELSE
   OPEN acur_t FOR
    SELECT   1 havechild, monitor_id, mschema, NAME, dsize, DECODE (dsize, 0, 1, 2)
        FROM monitors m
       WHERE mschema = an_monitor AND nparent = an_monitor_id AND EXISTS (SELECT *
                                                                            FROM monitors
                                                                           WHERE nparent = m.monitor_id)
    UNION ALL
    SELECT   0 havechild, monitor_id, mschema, NAME, dsize, DECODE (dsize, 0, 1, 2)
        FROM monitors m
       WHERE mschema = an_monitor AND nparent = an_monitor_id AND NOT EXISTS (SELECT *
                                                                                FROM monitors
                                                                               WHERE nparent = m.monitor_id)
    ORDER BY 6, 4;
  END IF;
 END;

--------------------------------------------------------------------------------------------------------------------------
 PROCEDURE journalsys_selectdata_p (an_idgroup NUMBER, an_filter NUMBER, av_code VARCHAR2, av_orderstr VARCHAR2, av_selecteddate VARCHAR2, an_stepprof NUMBER,
 an_adv_filter NUMBER, acur_t OUT common_pg.tcur
 ) IS
  lv_sql   VARCHAR2 (5000);
  lv_tmp   VARCHAR2 (1000);
 BEGIN
  lv_sql :=
   'SELECT   TO_CHAR (j.date_time, ''dd.mm.yyyy hh24:mi:ss'') field1,
         DECODE (pp.ind, 3, p.NAME || '' / '') || pp.NAME field2, d.veventtext||j.state_descr field3,
         j.state_cod field0, j.vcode field4
    FROM points p, points pp, journal j,METEREVENTSDICT d
   WHERE ( j.date_time >=decode(:par3,1,trunc(to_date(:par1, ''dd.mm.yyyy hh24:mi''),''yyyy''),
   2,trunc(to_date(:par1, ''dd.mm.yyyy hh24:mi''),''month''),3,trunc(to_date(:par1, ''dd.mm.yyyy hh24:mi''))
   -6,trunc(to_date(:par1, ''dd.mm.yyyy hh24:mi'')))
    AND j.date_time <decode(:par3,1,add_months(trunc(to_date(:par1, ''dd.mm.yyyy hh24:mi''),''yyyy''),12),
    2,add_months(trunc(to_date(:par1, ''dd.mm.yyyy hh24:mi''),''month''),1),3,
    trunc(to_date(:par1, ''dd.mm.yyyy hh24:mi''))+1,trunc(to_date(:par1, ''dd.mm.yyyy hh24:mi''))+1))
     AND p.mid(+) = pp.PARENT
     AND j.mid = pp.mid and j.nevent=d.nevent(+)';

  IF (an_idgroup <> 0) THEN
   lv_sql := lv_sql || ' AND (j.mid IN (SELECT  mid FROM points CONNECT BY PRIOR mid = PARENT  START WITH mid =' || TO_CHAR (an_idgroup) || ' )) ';
  END IF;

  IF (an_filter <> 0) THEN
   lv_sql := lv_sql || 'AND (state_cod=DECODE(' || TO_CHAR (an_filter) || ',1,0,state_cod+1) OR state_cod<>DECODE(' || TO_CHAR (an_filter) || ',2,0,state_cod)) ';
  END IF;

  IF (av_code IS NOT NULL) THEN
   lv_sql := lv_sql || ' AND (';

   FOR i IN 1 .. INSTR (av_code, ',', -1, 1) + 1 LOOP
    lv_tmp := util_pg.get_param (av_code, i, ',');

    IF lv_tmp IS NOT NULL THEN
     IF INSTR (lv_tmp, '%') > 0 OR INSTR (lv_tmp, '_') > 0 THEN
      lv_sql := lv_sql || ' j.vcode LIKE ''' || lv_tmp || ''' OR ';
     ELSE
      lv_sql := lv_sql || ' j.vcode = ''' || lv_tmp || ''' OR ';
     END IF;
    ELSE
     EXIT;
    END IF;
   END LOOP;

   lv_sql := RTRIM (lv_sql, 'OR ');
   lv_sql := lv_sql || ' ) ';
  END IF;

  IF (an_adv_filter > 0) THEN
   lv_sql := lv_sql || ' AND j.nevent in (select nevent from filters where nevent is not null connect by prior nid=nparent start with nid=' || an_adv_filter || ') ';
  ELSIF (an_adv_filter < 0) THEN
   lv_sql :=
    lv_sql || ' AND (j.nevent NOT in (select nevent from filters where nevent is not null connect by prior nid=nparent start with nid=' || (-1) * an_adv_filter
    || ') OR j.nevent IS NULL )';
  END IF;

  lv_sql := lv_sql || ' ORDER BY ' || av_orderstr;

  OPEN acur_t FOR lv_sql
  USING an_stepprof, av_selecteddate, av_selecteddate, av_selecteddate, av_selecteddate, an_stepprof, av_selecteddate, av_selecteddate, av_selecteddate,
        av_selecteddate;
 END;

--------------------------------------------------------------------------------------------------------------------
 PROCEDURE journal_selectdata_p (an_idgroup NUMBER, an_filter1_type NUMBER, an_filter2_mid NUMBER, av_orderstr VARCHAR2, av_selecteddate VARCHAR2,
 an_stepprof NUMBER, acur_t OUT common_pg.tcur
 ) IS
  lv_sql   VARCHAR2 (5000);
 BEGIN
  lv_sql :=
   'SELECT to_char(f.Date_Time,''dd.mm.yyyy hh24:mi'') field1, f.Name field2, f.Message field3, f.Task_Job field0
     FROM Fiscal f, users u
     WHERE u.name=f.name
     and f.Date_Time>=decode(:par3,1,trunc(to_date(:par1, ''dd.mm.yyyy hh24:mi''),''yyyy''),2,
     trunc(to_date(:par1, ''dd.mm.yyyy hh24:mi''),''month''),3,trunc(to_date(:par1, ''dd.mm.yyyy hh24:mi''))-6,
     trunc(to_date(:par1, ''dd.mm.yyyy hh24:mi'')))
     AND f.Date_Time<decode(:par3,1,add_months(trunc(to_date(:par1, ''dd.mm.yyyy hh24:mi''),''yyy''),12),2,
     add_months(trunc(to_date(:par1, ''dd.mm.yyyy hh24:mi''),''month''),1),3,
     trunc(to_date(:par1, ''dd.mm.yyyy hh24:mi''))+1,trunc(to_date(:par1, ''dd.mm.yyyy hh24:mi''))+1) ';

  IF (an_idgroup <> 0) THEN
   lv_sql := lv_sql || 'and f.Task_Cod in (SELECT task_Cod FROM tasks CONNECT BY prior Task_Id = Parent START WITH Task_Id =' || TO_CHAR (an_idgroup) || ' ) ';
  END IF;

  IF (an_filter1_type <> 0) THEN
   lv_sql := lv_sql || 'and task_job=' || TO_CHAR (an_filter1_type) || '  ';
  END IF;

  IF (an_filter2_mid <> 0) THEN
   lv_sql := lv_sql || 'and u.user_id=' || TO_CHAR (an_filter2_mid) || '  ';
  END IF;

  lv_sql := lv_sql || ' ORDER BY ' || av_orderstr;

  OPEN acur_t FOR lv_sql
  USING an_stepprof, av_selecteddate, av_selecteddate, av_selecteddate, av_selecteddate, an_stepprof, av_selecteddate, av_selecteddate, av_selecteddate,
        av_selecteddate;
 END;

