 PROCEDURE journalalert_p (an_tag NUMBER, av_orderstr VARCHAR2, an_filter2_mid NUMBER, an_filter2_type NUMBER, av_code VARCHAR2, an_adv_filter NUMBER,
 acur_t OUT common_pg.tcur
 ) IS
  lv_sql   VARCHAR2 (8000);
  lv_tmp   VARCHAR2 (1000);
 BEGIN
  IF (an_tag = 1) THEN
   lv_sql :=
    'select mid field1, a field4, b field3, c field2
                  FROM(SELECT l.mid, state_date c, state_date a, ''Нет связи по каналу ''||vname||''. ''||state_descr b
                        FROM last_save l, channels c
                        WHERE l.mid = c.cid AND l.STATE_COD<>0
                        AND (:par1=0 OR l.mid IN (SELECT Q.MID FROM points q CONNECT BY PRIOR q.mid=q.parent START WITH q.MID=:par1))
                      UNION
                       SELECT l.mid, state_date c, state_date a, ''Нет связи по каналу ''||vname||''. ''||state_descr b
                        FROM last_save l, deportation c
                        WHERE l.mid = c.ndeportation AND l.STATE_COD<>0
                        AND (:par1=0 OR l.mid IN (SELECT Q.MID FROM points q CONNECT BY PRIOR q.mid=q.parent START WITH q.MID=:par1))
                      UNION
                        SELECT p.mid, state_date c, state_date a, p1.NAME||'' Нет данных по точке учета ''||p.NAME||''. ''||state_descr b
                        FROM last_save l, points p , points p1
                        WHERE p1.mid = p.parent AND l.mid = p.mid AND l.state_cod > 0 AND
                          p.mid IN(SELECT mid FROM chanpoint WHERE cid IN
                        (SELECT cid FROM channels WHERE was_dead IS NOT NULL)
                         AND (:par1=0 OR mid IN (SELECT Q.MID FROM points q CONNECT BY PRIOR q.mid=q.parent START WITH q.MID=:par1)))) aass
                  ORDER BY '
    || av_orderstr;

   OPEN acur_t FOR lv_sql USING an_filter2_mid, an_filter2_mid, an_filter2_mid, an_filter2_mid, an_filter2_mid, an_filter2_mid;
  ELSIF (an_tag = 2) THEN
   lv_sql :=
    'select mid field1, a field4, b field3, c field2
                  FROM
                    (
                           SELECT l.mid,l.date_time c, l.date_time a,
                           pa.NAME||decode(pa.NAME,'''','''','' / '')||p.NAME||'': ''||decode(l1, 0, '' Нет фазы А.'','''')||decode(l2, 0, '' Нет фазы В.'','''')||decode(l3, 0, '' Нет фазы C.'','''') b
                         FROM points p,points pa, LGstatus l
                         WHERE p.mid = l.mid AND p.parent=pa.mid(+)
                           AND l.u <> 0
                           AND l1+l2+l3 < 3
                          AND (:par1=0 OR p.mid IN (SELECT Q.MID FROM points q CONNECT BY PRIOR q.mid=q.parent START WITH q.MID=:par1))
                         UNION ALL
                         SELECT NPROCEDURE mid,ddate c, ddate a, vtext b
                         FROM check_status
                    ) aass
                  ORDER BY '
    || av_orderstr;

   OPEN acur_t FOR lv_sql USING an_filter2_mid, an_filter2_mid;
  ELSIF (an_tag = 3) THEN
   lv_sql :=
    'select decode(j.state_cod,0,0,1) field1, j.date_time field4,
                    substr(pa.NAME||decode(pa.NAME,'''','''','' / '')||p.NAME||'': ''||d.veventtext||j.state_descr,1,170) field3,
                    j.date_time field2, j.vcode field5
                  FROM journallast j, points p, points pa,METEREVENTSDICT d
                  WHERE j.mid = p.mid(+) AND p.parent=pa.mid(+) and j.nevent=d.nevent(+)                  
                    AND (:par1=0 OR p.mid IN (SELECT Q.MID FROM points q CONNECT BY PRIOR q.mid=q.parent START WITH q.MID=:par1))
                    AND (:par2=0 OR (decode(j.state_cod,0,1,2)=:par2 ))';

   IF (av_code IS NOT NULL) THEN
    lv_sql := lv_sql || ' AND (';

    FOR i IN 1 .. INSTR (av_code, ',', -1, 1) + 1 LOOP
     lv_tmp := util_pg.get_param (av_code, i, ',');

     IF lv_tmp IS NOT NULL THEN
      IF INSTR (lv_tmp, '%') > 0 OR INSTR (lv_tmp, '_') > 0 THEN
       lv_sql := lv_sql || ' j.vcode LIKE ''' || lv_tmp || ''' OR ';
      ELSE
       lv_sql := lv_sql || ' j.vcode = ''' || lv_tmp || ''' OR ';
      END IF;
     ELSE
      EXIT;
     END IF;
    END LOOP;

    lv_sql := RTRIM (lv_sql, 'OR ');
    lv_sql := lv_sql || ' ) ';
   END IF;

   IF (an_adv_filter > 0) THEN
    lv_sql :=
             lv_sql || ' AND j.nevent in (select nevent from filters where nevent is not null connect by prior nid=nparent start with nid=' || an_adv_filter || ') ';
   ELSIF (an_adv_filter < 0) THEN
    lv_sql :=
     lv_sql || ' AND (j.nevent NOT in (select nevent from filters where nevent is not null connect by prior nid=nparent start with nid=' || (-1) * an_adv_filter
     || ') OR j.nevent IS NULL )';
   END IF;

   lv_sql := lv_sql || ' order by ' || av_orderstr;

   OPEN acur_t FOR lv_sql USING an_filter2_mid, an_filter2_mid, an_filter2_type, an_filter2_type;
  END IF;
 END;
