CREATE OR REPLACE 
PACKAGE BODY loss_pg IS
 ------------------------------------------------------------------------------------------------------------------------
   -- пакет работы с потерями
   -- дата создания 24/02/2003 (Сечин А.А.)
 gn_task_code NUMBER DEFAULT 46;
 ------------------------------------------------------------------------------------------------------------------------
   -- Процедура вставки
 PROCEDURE ins_p(
  an_mid                    NUMBER, --Ид точки
  av_name                   VARCHAR2, --Название
  an_sn                     NUMBER, --NSN
  an_sh                     NUMBER, --NSH
  an_deltapidling           NUMBER, --NDELTAPIDLING
  an_deltapsc               NUMBER, --NDELTAPSC
  an_iidling                NUMBER, --NIIDLING
  an_usc                    NUMBER, --Uкз% /
  an_ro                     NUMBER, --NRO
  an_xo                     NUMBER, --NXO
  an_l                      NUMBER, --NL
  an_un                     NUMBER, --NUN
  an_energypercent          NUMBER, --Процент вхождения
  an_workinghours           NUMBER, --Время работы
  an_fullhours              NUMBER, --Полное время
  an_notincludeconsump      NUMBER, --Расход не учитывать
  an_parallelconnection     NUMBER, --Паралельное соединение
  an_renergypercent         NUMBER, --Потери Реактив
  an_procent                NUMBER, --Расчет по процентам
  an_connectionparam    OUT NUMBER --Ид параметра
                                  ) IS
  ln_connectionparam NUMBER;
 BEGIN
  SAVEPOINT loss_ins;
  SELECT points_seq.NEXTVAL
    INTO ln_connectionparam
    FROM DUAL;
  INSERT INTO connectionparam
              (nconnectionparam, mid, vname, nsn, nsh, ndeltapidling, ndeltapsc, niidling, nusc,
               nro, nxo, nl, nun, nenergypercent, nworkinghours, nfullhours, nnotincludeconsump,
               nparallelconnection, nrenergypercent, nprocent)
       VALUES (ln_connectionparam, an_mid, av_name, an_sn, an_sh, an_deltapidling, an_deltapsc, an_iidling, an_usc,
               an_ro, an_xo, an_l, an_un, an_energypercent, an_workinghours, an_fullhours, an_notincludeconsump,
               an_parallelconnection, an_renergypercent, an_procent);
  an_connectionparam := ln_connectionparam;
  admin_pg.fiscal_p(
   gn_task_code, 1, 'Для точки ' || util_pg.node_path_f(an_mid, 'points', 'mid', 'parent') || ' добавлен параметр потерь ' ||
                    NVL(av_name, an_connectionparam));
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT loss_ins;
   raise_application_error(
    -20001, 'loss_pg.ins_p: Ошибка вставки параметров присоединения. ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ------------------------------------------------------------------------------------------------------------------------
   -- Процедура обновления данных
 PROCEDURE upd_p(
  an_connectionparam    NUMBER, --Ид параметра
  an_mid                NUMBER, --Ид точки
  av_name               VARCHAR2, --Название
  an_sn                 NUMBER, --NSN
  an_sh                 NUMBER, --NSH
  an_deltapidling       NUMBER, --NDELTAPIDLING
  an_deltapsc           NUMBER, --NDELTAPSC
  an_iidling            NUMBER, --NIIDLING
  an_usc                NUMBER, --Uкз% /
  an_ro                 NUMBER, --NRO
  an_xo                 NUMBER, --NXO
  an_l                  NUMBER, --NL
  an_un                 NUMBER, --NUN
  an_energypercent      NUMBER, --Процент вхождения
  an_workinghours       NUMBER, --Время работы
  an_fullhours          NUMBER, --Полное время
  an_notincludeconsump  NUMBER, --Расход не учитывать
  an_parallelconnection NUMBER, --Паралельное соединение
  an_renergypercent     NUMBER, --Потери Реактив
  an_procent            NUMBER --Расчет по процентам
                              ) IS
 BEGIN
  SAVEPOINT loss_upd;
  UPDATE connectionparam
     SET vname = av_name,
         nsn = an_sn,
         nsh = an_sh,
         ndeltapidling = an_deltapidling,
         ndeltapsc = an_deltapsc,
         niidling = an_iidling,
         nusc = an_usc,
         nro = an_ro,
         nxo = an_xo,
         nl = an_l,
         nun = an_un,
         nenergypercent = an_energypercent,
         nworkinghours = an_workinghours,
         nfullhours = an_fullhours,
         nnotincludeconsump = an_notincludeconsump,
         nparallelconnection = an_parallelconnection,
         nrenergypercent = an_renergypercent,
         nprocent = an_procent
   WHERE nconnectionparam = an_connectionparam;
  admin_pg.fiscal_p(
   gn_task_code, 2, 'Для точки ' || util_pg.node_path_f(an_mid, 'points', 'mid', 'parent') || ' изменен параметр потерь ' ||
                    NVL(av_name, an_connectionparam));
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT loss_upd;
   raise_application_error(
    -20001, 'loss_pg.upd_p: Ошибка обновления параметров присоединения. ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ------------------------------------------------------------------------------------------------------------------------
   -- Процедура вставки, обновления данных (долевых)
 PROCEDURE insupd_p(
  an_connectionparam   NUMBER, --Ид параметра
  an_mid               NUMBER, --Ид точки
  an_notincludeconsump NUMBER --Расход не учитывать
                             ) IS
  lv_name VARCHAR2(200);
 BEGIN
  SAVEPOINT loss_insupd;
  UPDATE sharedconnectionparam
     SET nnotincludeconsump = an_notincludeconsump
   WHERE nconnectionparam = an_connectionparam AND mid = an_mid;
  IF SQL%ROWCOUNT = 0 THEN
   INSERT INTO sharedconnectionparam
               (nconnectionparam, mid, nnotincludeconsump)
        VALUES (an_connectionparam, an_mid, an_notincludeconsump);
  END IF;
  SELECT vname
    INTO lv_name
    FROM connectionparam
   WHERE nconnectionparam = an_connectionparam;
  admin_pg.fiscal_p(
   gn_task_code, 1, 'Для точки ' || util_pg.node_path_f(an_mid, 'points', 'mid', 'parent') ||
                    ' добавлен/изменен параметр долевых потерь ' || NVL(lv_name, an_connectionparam));
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT loss_insupd;
   raise_application_error(
    -20001, 'loss_pg.insupd_p: Ошибка обновления долевых параметров присоединения. ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ------------------------------------------------------------------------------------------------------------------------
  -- Процедура удаления данных
 PROCEDURE del_p(
  an_connectionparam NUMBER, --Ид параметра
  an_mid             NUMBER --Ид точки (Если >0 то считаем что долевые и удаляем из долевых)
                           ) IS
  ln_mid  NUMBER;
  lv_name VARCHAR2(200);
 BEGIN
  SELECT mid, vname
    INTO ln_mid, lv_name
    FROM connectionparam
   WHERE nconnectionparam = an_connectionparam;
  IF an_mid > 0 THEN
   DELETE FROM sharedconnectionparam
         WHERE nconnectionparam = an_connectionparam AND mid = an_mid;
  ELSE
   DELETE FROM connectionparam
         WHERE nconnectionparam = an_connectionparam;
  END IF;
  admin_pg.fiscal_p(
   gn_task_code, 3, 'Для точки ' || util_pg.node_path_f(ln_mid, 'points', 'mid', 'parent') || ' удален параметр потерь ' ||
                    NVL(lv_name, an_connectionparam));
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(
    -20001, 'loss_pg.del_p: Ошибка удаления параметров присоединения. ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ------------------------------------------------------------------------------------------------------------------------
     -- Время на точке
 PROCEDURE settimep_p(
  an_mid          NUMBER, --Ид точки
  at_period       common_pg.tt_number, --Период
  at_workinghours common_pg.tt_number, --Время работы
  at_fullhours    common_pg.tt_number --Полное время
                                     ) IS
 BEGIN
  SAVEPOINT loss_settime;
  DELETE FROM pointfullhours
        WHERE mid = an_mid;
  IF  at_period.COUNT > 0 AND at_period(1) <> 0 THEN
   FOR i IN 1 .. at_period.COUNT LOOP
    INSERT INTO pointfullhours
                (mid, naccperiod, nfullhours, nworkinghours)
         VALUES (an_mid, at_period(i), at_fullhours(i), at_workinghours(i));
   END LOOP;
  END IF;
  admin_pg.fiscal_p(
   gn_task_code, 2, 'Изменено время работы точки ' || util_pg.node_path_f(an_mid, 'points', 'mid', 'parent'));
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT loss_settime;
   raise_application_error(
    -20001, 'loss_pg.settime_p: Задания времени работы точки учета. ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ------------------------------------------------------------------------------------------------------------------------
 ----       Импорт из АСРПП         -------------------------------------------------------------------------------------
 ------------------------------------------------------------------------------------------------------------------------
   -- Процедура вставки
 PROCEDURE ins_p_a(
  an_connectionparam    NUMBER, --Ид параметра
  an_mid                NUMBER, --Ид точки
  av_name               VARCHAR2, --Название
  an_sn                 NUMBER, --NSN
  an_sh                 NUMBER, --NSH
