-- И РАЗНОСКА ПОТЕРЬ С УЧЕТОМ ИЗМЕНЕНИЯ КОММУТАЦИИ
--
-- MODIFICATION HISTORY
-- Person      Date        Comments
-- ---------   --------    -------------------------------------------
-- Вештак      14.02.06    Первый релиз
-- Вештак      17.05.06    Специально для ЧОЭ убрана разноска потерь (VIA-1),
--                           добавлена разноска по получасовкам (VIA-2)
--                           убран подсчет рабочих часов (три минуты считался)


  period_       number;  -- id расчетного периода
  sdate_        date;    -- дата начала периода
  ldate_        date;    -- дата конца периода

  cdate         date;
  i             number;
  node          number;
  bus           number;
  feeder_       number;
  QM_           number;
  cnt           number;
  by_hours      boolean;

  type tr_windings is record(
    idlingW     number,
    idlingVar   number,
    QW          number,
    QVar        number,
    S           number);
  type t_windings is table of tr_windings
    index by binary_integer;
  windings      t_windings;

  type tr_edges is record(
    feeder      number,
    Wh          number,
    Varh        number,
    QM          number,
    lW          number,
    lVar        number);
  type t_edges is table of tr_edges
    index by binary_integer;
  edges         t_edges;

  lossed_Wh_    number;
  lossed_Varh_  number;
  divisor       number;
  ler           number;
  led           number;

  once_more     boolean;


days        number;
lr          number;
ld          number;
br          number;
bd          number;
sr          number;
sd          number;


procedure recovery_by_bus is
begin
  -- Восстанавливаем данные по небалансу узлов
  for c in (select * from calc_periods where period = period_) loop
    for cc in (select distinct outfit from calc_links l, rt_objects o
        where l.cpid = c.cpid and o.oid = l.outfit and o.rt_type in (0, 400)) loop


      -- Определяем необходимость и возможность восстановления данных по небалансу узла
      begin
        select min(oid), sum(qm) into feeder_, qm_ from calc_results
          where cpid = c.cpid and qm > 0 and oid in
            (select feeder from calc_links where cpid = c.cpid and outfit = cc.outfit);
      exception when no_data_found then qm_ := 0;
      end;
      select count(*) into cnt from calc_links where cpid = c.cpid and outfit = cc.outfit;

      i := 0;
      if qm_ > 1 then
        -- нет данных более чем одной точки узла. Пытаемся объединить фидера без
        -- линий и трансформаторов в одну точку.
        update calc_results set qm = -2
          where cpid = c.cpid and qm = 1 and oid in
           (select a.feeder from
             (select feeder from calc_links where cpid = c.cpid group by feeder having count(*) = 1) a,
             (select feeder from calc_links where cpid = c.cpid and outfit = cc.outfit) b
             where a.feeder = b.feeder
           );
        select count(*), min(oid) into i, feeder_ from calc_results
          where cpid = c.cpid and qm = -2 and oid in
            (select feeder from calc_links where cpid = c.cpid and outfit = cc.outfit);
        if qm_- i <> 0 then  -- фокус не удался, данных все равно не хватает. Откатываемся
          update calc_results set qm = 1
            where cpid = c.cpid and qm = -2 and oid in
              (select feeder from calc_links where cpid = c.cpid and outfit = cc.outfit);
        else
          qm_ := 1;
        end if;
      end if;

      if qm_ = 1 and cnt > 1 then
        -- восстанавливаем данные
        update calc_results set (src, wh, varh, qm) = (select 20, -sum(wh), -sum(varh), decode(i, 0, 0, -3)
            from calc_results
            where cpid = c.cpid and qm < 1 and oid in (select feeder from calc_links
                where cpid = c.cpid and outfit = cc.outfit))
          where cpid = c.cpid and oid = feeder_;
        once_more := true;
      end if;

      if qm_ = 2 then
        -- если обе точки без данных - трансформаторные ввода, то пытаемся разбить небаланс
        -- по соотношению Sn
        select count(*) into i from rt_links l, rt_objects o
          where o.oid = l.outfit and o.rt_type in (600, 610) and l.feeder in
              (select oid from calc_results where cpid = c.cpid and qm = 1
                 and oid in (select distinct feeder from calc_links where cpid = c.cpid and outfit = cc.outfit));
        if i = 2 then
          select -sum(Wh), -sum(Varh) into edges(1).Wh, edges(1).VArh from calc_results
            where cpid = c.cpid and qm in (0, -3) and oid in (select feeder from calc_links
                where cpid = c.cpid and outfit = cc.outfit);
          select r.oid, nsn into edges(1).feeder, edges(1).lw from calc_results r, connectionparam p
            where r.cpid = c.cpid and r.qm = 1 and p.nwinding in (0, 1)
              and r.oid in (select distinct feeder from calc_links where cpid = c.cpid and outfit = cc.outfit)
              and p.mid in
                  (select o.oid from rt_objects o, rt_links l
                     where o.oid = l.outfit and o.rt_type in (600, 610) and l.feeder = r.oid)
              and rownum = 1;
          select r.oid, nsn into edges(2).feeder, edges(2).lw from calc_results r, connectionparam p
            where r.cpid = c.cpid and r.qm = 1 and p.nwinding in (0, 1)
              and r.oid in (select distinct feeder from calc_links where cpid = c.cpid and outfit = cc.outfit)
              and p.mid in
                  (select o.oid from rt_objects o, rt_links l
                     where o.oid = l.outfit and o.rt_type in (600, 610) and l.feeder = r.oid)
              and r.oid <> edges(1).feeder;
          update calc_results set src = 20,
              wh = edges(1).wh * edges(1).lw /(edges(1).lw + edges(2).lw),
              varh = edges(1).varh * edges(1).lw /(edges(1).lw + edges(2).lw),
              qm = 0
            where cpid = c.cpid and oid = edges(1).feeder;
          update calc_results set src = 20,
              wh = edges(1).wh * edges(2).lw /(edges(1).lw + edges(2).lw),
              varh = edges(1).varh * edges(2).lw /(edges(1).lw + edges(2).lw),
              qm = 0
            where cpid = c.cpid and oid = edges(2).feeder;
          qm_ := 0;
          once_more := true;
        end if;
      end if;
    end loop;
  end loop;
end;

procedure recovery_by_lines is
a   number;
b   number;
c_  number;
j   number;

  procedure calc_line(oid_ in number) is
  begin
    if edges(1).qm < 1 and edges(2).qm < 1 then  -- измеряемые потери, т.е. разность входа и выхода
      lossed_Wh_ := -(edges(1).Wh + edges(2).Wh);
      lossed_Varh_ := -(edges(1).Varh + edges(2).Varh);
      for cc in (select p.cpid from calc_periods p, calc_results r
          where period = period_
            and r.cpid = p.cpid and r.oid = edges(2).feeder and r.Wh >= 0) loop
--        if edges(2).Wh <> 0 and edges(2).VArh <> 0 then
        update calc_results set
            lossed_Wh = lossed_Wh + lossed_Wh_,
            lossed_Varh = lossed_Varh + lossed_Varh_
          where oid = edges(2).feeder and cpid = cc.cpid;
--        end if;
      end loop;
--VIA
      update calc_hours set rt_type = null where oid = oid_;  -- помечаем, что объект обработан
    end if;

    if edges(1).qm >= 1 and edges(2).qm < 1 then -- обычный расчет по методике 1998 года
      lossed_Wh_ := (power(edges(2).Wh, 2) + power(edges(2).Varh, 2)) * windings(1).QW;
      lossed_VArh_ := (power(edges(2).Wh, 2) + power(edges(2).Varh, 2)) * windings(1).QVAr;
      for cc in (select p.cpid from calc_periods p, calc_results r
          where period = period_
            and r.cpid = p.cpid and r.oid = edges(2).feeder and r.Wh >= 0) loop
--        if edges(2).Wh <> 0 and edges(2).VArh <> 0 then
        update calc_results set
            lossed_Wh = lossed_Wh + lossed_Wh_ * Wh / decode(edges(2).Wh, 0, 1, edges(2).Wh),
            lossed_Varh = lossed_Varh + Lossed_Varh_ * VArh / decode(edges(2).VArh, 0, 1, edges(2).VArh)
          where oid = edges(2).feeder and cpid = cc.cpid;
--        end if;
        update calc_results set
            (src, Wh, VArh, QM) =
                (select 30, -sum(Wh + lossed_Wh), -sum(VArh + lossed_VArh), max(QM)
                  from calc_results where cpid = cc.cpid and oid in (edges(2).feeder))
          where cpid = cc.cpid and oid = edges(1).feeder;
      end loop;
      once_more := true;
--VIA
      update calc_hours set rt_type = null where oid = oid_;  -- помечаем, что объект обработан
    end if;

    if edges(1).qm < 1 and edges(2).qm >= 1 then -- расчет потерь "сверху вниз"
      if windings(1).QW <> 0 then
        edges(1).wh := -edges(1).wh;  edges(1).varh := -edges(1).varh;
        j := windings(1).QVAr/windings(1).QW;
        a := power(j, 2) + 1;
        b := 2 * j * (edges(1).VArh - j * edges(1).Wh) + 1 / windings(1).QW;
        c_ := edges(1).VArh - j * edges(1).Wh;
        c_ := power(c_, 2) - edges(1).Wh / windings(1).QW;
        edges(2).Wh := (-b + sqrt(b*b - 4*a*c_))/2/a;
        -- edges(3).Wh := (-b - sqrt(b*b - 4*a*c_))/2/a;
        edges(2).Varh := sign(edges(1).VArh) * sqrt(abs(edges(1).Wh/windings(1).QW - edges(2).wh/windings(1).QW - power(edges(2).wh, 2)));
        -- edges(3).Varh := edges(1).Wh/windings(1).QW - edges(3).wh/windings(1).QW - power(edges(3).wh, 2);
      else
        edges(2).Wh := edges(1).Wh;
        edges(2).VArh := edges(1).VArh;
      end if;
      for cc in (select p.cpid from calc_periods p, calc_results r
          where period = period_
            and r.cpid = p.cpid and r.oid = edges(1).feeder and r.Wh <= 0) loop
        update calc_results set (Wh, VArh, lossed_Wh, lossed_VArh, src, QM) =
            (select edges(2).Wh * (-Wh) / decode(edges(1).Wh, 0, 1, edges(1).Wh),
                    edges(2).VArh * (-VArh) / decode(edges(1).VArh, 0, 1, edges(1).VArh),
                    -Wh - edges(2).Wh * (-Wh) / decode(edges(1).Wh, 0, 1, edges(1).Wh),
                    -VArh - edges(2).VArh * (-VArh) / decode(edges(1).VArh, 0, 1, edges(1).VArh),
                    30, 0
               from calc_results where oid = edges(1).feeder and cpid = cc.cpid)
          where cpid = cc.cpid and oid = edges(2).feeder;
      end loop;
      once_more := true;
--VIA
      update calc_hours set rt_type = null where oid = oid_;  -- помечаем, что объект обработан
    end if;

  end;

begin
  -- Потери в линиях

  for c in (select oid, sum(common) common from calc_hours
      where rt_type = 500 and cpid in (select cpid from calc_periods where period = period_)
      group by oid having sum(common) <> 0) loop
    i := 1;
    for cc in (select r.oid, sum(Wh) Wh, sum(Varh) Varh, max(QM) QM,
            count(distinct decode(sign(wh), 0, 1,sign(wh))) cnt
        from calc_results r, rt_links l  --, rt_objects o
        where l.outfit = c.oid and r.oid = l.feeder --and o.oid = r.oid
          and r.cpid in (select cpid from calc_periods where period = period_)
        group by r.oid) loop
      i := i + 1;
      edges(i).feeder := cc.oid;
      edges(i).Wh := cc.Wh;
      edges(i).Varh := cc.Varh;
      edges(i).QM := cc.QM;
      edges(i).lW := cc.cnt;
    end loop;

    select nro*nl/1000/c.common, nxo*nl/1000/c.common
      into windings(1).QW, windings(1).QVar
      from connectionparam
      where mid = (select parent from rt_objects where oid = c.oid);
    select windings(1).QW/voltage/voltage, windings(1).QVar/voltage/voltage
      into windings(1).QW, windings(1).QVar
      from rt_objects
      where oid in (select feeder from rt_links where outfit = c.oid and rownum = 1);

--edges(2).lw := 1;  edges(3).lw := 1;
    if edges(2).lw <> 2 and edges(3).lw <> 2 then  -- в периоде не было изменений направления
      if edges(2).Wh <= 0 and edges(3).Wh >= 0 then  -- ищем где у линии начало и где у линии конец
        edges(1).feeder := edges(2).feeder;    edges(2).feeder := edges(3).feeder;
        edges(1).Wh := edges(2).Wh;            edges(2).Wh := edges(3).Wh;
        edges(1).Varh := edges(2).Varh;        edges(2).Varh := edges(3).Varh;
        edges(1).QM := edges(2).QM;            edges(2).QM := edges(3).QM;
      else
        edges(1).feeder := edges(3).feeder;
        edges(1).Wh := edges(3).Wh;
        edges(1).Varh := edges(3).Varh;
        edges(1).QM := edges(3).QM;
      end if;
      calc_line(c.oid);
    else                                            -- концы менялись местами, считаем дважды
      edges(1).feeder := edges(3).feeder;
      edges(1).Wh := edges(3).Wh;
      edges(1).Varh := edges(3).Varh;
      edges(1).QM := edges(3).QM;
      select sum(Wh), sum(VArh) into edges(1).Wh, edges(1).VArh from calc_results
        where oid = edges(1).feeder
          and cpid in (select cpid from calc_periods where period = period_)
          and Wh < 0;
      select sum(Wh), sum(VArh) into edges(2).Wh, edges(2).VArh from calc_results
        where oid = edges(2).feeder
          and cpid in (select cpid from calc_periods where period = period_)
          and Wh > 0;
      calc_line(c.oid);

      edges(1).feeder := edges(2).feeder;    edges(2).feeder := edges(3).feeder;
      edges(1).Wh := edges(2).Wh;            edges(2).Wh := edges(3).Wh;
      edges(1).Varh := edges(2).Varh;        edges(2).Varh := edges(3).Varh;
      edges(1).QM := edges(2).QM;            edges(2).QM := edges(3).QM;
      select sum(Wh), sum(VArh) into edges(1).Wh, edges(1).VArh from calc_results
        where oid = edges(1).feeder
          and cpid in (select cpid from calc_periods where period = period_)
          and Wh < 0;
      select sum(Wh), sum(VArh) into edges(2).Wh, edges(2).VArh from calc_results
        where oid = edges(2).feeder
          and cpid in (select cpid from calc_periods where period = period_)
          and Wh > 0;
      calc_line(c.oid);
    end if;

    select max(QM) into i from calc_results
      where oid in (edges(1).feeder, edges(2).feeder)
          and cpid in (select cpid from calc_periods where period = period_);
    if i < 1 then
      update calc_hours set rt_type = null where oid = c.oid;  -- помечаем, что объект обработан
    end if;


/*
    if edges(1).qm < 1 and edges(2).qm < 1 then  -- измеряемые потери, т.е. разность входа и выхода
      lossed_Wh_ := -(edges(1).Wh + edges(2).Wh);
      lossed_Varh_ := -(edges(1).Varh + edges(2).Varh);
      for cc in (select * from calc_periods where period = period_) loop
        if edges(2).Wh <> 0 and edges(2).VArh <> 0 then
          update calc_results set
              lossed_Wh = lossed_Wh + lossed_Wh_,
              lossed_Varh = lossed_Varh + lossed_Varh_
            where oid = edges(2).feeder and cpid = cc.cpid;
        end if;
      end loop;
      update calc_hours set rt_type = null where oid = c.oid;  -- помечаем, что объект обработан
    end if;

    if edges(1).qm >= 1 and edges(2).qm < 1 then -- обычный расчет по методике 1998 года
      lossed_Wh_ := (power(edges(2).Wh, 2) + power(edges(2).Varh, 2)) * windings(1).QW;
      lossed_VArh_ := (power(edges(2).Wh, 2) + power(edges(2).Varh, 2)) * windings(1).QVAr;
      for cc in (select * from calc_periods where period = period_) loop
        if edges(2).Wh <> 0 and edges(2).VArh <> 0 then
          update calc_results set
              lossed_Wh = lossed_Wh + lossed_Wh_ * Wh / edges(2).Wh,
              lossed_Varh = lossed_Varh + Lossed_Varh_ * VArh / edges(2).VArh
            where oid = edges(2).feeder and cpid = cc.cpid;
        end if;
        update calc_results set
            (src, Wh, VArh, QM) =
                (select 30, -sum(Wh + lossed_Wh), -sum(VArh + lossed_VArh), max(QM)
                  from calc_results where cpid = cc.cpid and oid in (edges(2).feeder))
          where cpid = cc.cpid and oid = edges(1).feeder;
      end loop;
      once_more := true;
      update calc_hours set rt_type = null where oid = c.oid;  -- помечаем, что объект обработан
    end if;

    if edges(1).qm < 1 and edges(2).qm >= 1 then -- расчет потерь "сверху вниз"
      edges(1).wh := -edges(1).wh;  edges(1).varh := -edges(1).varh;
      j := windings(1).QVAr/windings(1).QW;
      a := power(j, 2) + 1;
      b := 2 * j * (edges(1).VArh - j * edges(1).Wh) + 1 / windings(1).QW;
      c_ := edges(1).VArh - j * edges(1).Wh;
      c_ := power(c_, 2) - edges(1).Wh / windings(1).QW;
      edges(2).Wh := (-b + sqrt(b*b - 4*a*c_))/2/a;
      -- edges(3).Wh := (-b - sqrt(b*b - 4*a*c_))/2/a;
      edges(2).Varh := sqrt(abs(edges(1).Wh/windings(1).QW - edges(2).wh/windings(1).QW - power(edges(2).wh, 2)));
      -- edges(3).Varh := edges(1).Wh/windings(1).QW - edges(3).wh/windings(1).QW - power(edges(3).wh, 2);
      for cc in (select * from calc_periods where period = period_) loop
        update calc_results set (Wh, VArh, lossed_Wh, lossed_VArh, src, QM) =
            (select edges(2).Wh * (-Wh) / edges(1).Wh,
                    edges(2).VArh * (-VArh) / edges(1).VArh,
                    -Wh - edges(2).Wh * (-Wh) / edges(1).Wh,
                    -VArh - edges(2).VArh * (-VArh) / edges(1).VArh,
                    30, 0
               from calc_results where oid = edges(1).feeder and cpid = cc.cpid)
          where cpid = cc.cpid and oid = edges(2).feeder;
      end loop;
      once_more := true;
      update calc_hours set rt_type = null where oid = c.oid;  -- помечаем, что объект обработан
    end if;
*/
  end loop;
end;

procedure recovery_by_trans is
begin
  -- Расчет потерь тр-ров
  for c in (select oid, sum(common) common, sum(work) work from calc_hours
      where rt_type in (600, 610) and cpid in (select cpid from calc_periods where period = period_)
      group by oid having sum(common) > 0) loop
    windings(1).idlingW := 0;  windings(1).idlingVar := 0; windings(1).QW := 0; windings(1).QVAr := 0; windings(1).S := 0;
    windings(2).idlingW := 0;  windings(2).idlingVar := 0; windings(2).QW := 0; windings(2).QVAr := 0; windings(2).S := 0;
    windings(3).idlingW := 0;  windings(3).idlingVar := 0; windings(3).QW := 0; windings(3).QVAr := 0; windings(3).S := 0;
    i := 0;
    for cc in (select * from connectionparam where mid = c.oid order by nwinding)
        loop
      i := i + 1;
      windings(i).idlingW := cc.ndeltapidling;
      windings(i).idlingVar := cc.niIdling * cc.nsn / 100;
      windings(i).QW := cc.ndeltaPSC / power(nvl(cc.nsh, cc.nsn), 2);
      windings(i).QVar := cc.nusc / nvl(cc.nsh, cc.nsn) / 100;
      windings(i).S := nvl(cc.nsh, cc.nsn);
    end loop;
    if (windings(2).S + windings(3).S) = 0 then -- особенности хранения двухобмоточных
      windings(2).S := windings(1).S;           --   в CALCPARAM
    end if;

    edges(1).feeder := 0;  edges(1).Wh := 0;  edges(1).VArh := 0;  edges(1).QM := 0;  edges(1).lw := 0; edges(1).lvar := 0;
    edges(2).feeder := 0;  edges(2).Wh := 0;  edges(2).VArh := 0;  edges(2).QM := 0;  edges(2).lw := 0; edges(2).lvar := 0;
    edges(3).feeder := 0;  edges(3).Wh := 0;  edges(3).VArh := 0;  edges(3).QM := 0;  edges(3).lw := 0; edges(3).lvar := 0;
    i := 0;
    for cc in (select r.oid, sum(Wh) Wh, sum(Varh) Varh, max(QM) QM, o.voltage,
          max(act_loss) lw, max(react_loss) lvar
        from calc_results r, rt_links l, rt_objects o, feeders f
        where l.outfit = c.oid and r.oid = l.feeder and o.oid = r.oid and f.mid = r.oid
          and r.cpid in (select cpid from calc_periods where period = period_)
        group by r.oid, o.voltage
        order by o.voltage desc) loop
      i := i + 1;
      edges(i).feeder := cc.oid;
      edges(i).Wh := cc.Wh;
      edges(i).Varh := cc.Varh;
      edges(i).QM := cc.QM;
      edges(i).lw := cc.lw;
      edges(i).lvar := cc.lvar;
    end loop;


    if (edges(2).lw <> 0) or (edges(3).lw <> 0) then                    -- В описании фидеров указаны
                                                                        -- проценты потерь в тр-ре.
      if edges(1).qm >= 1 and edges(2).qm < 1 and edges(3).qm < 1 then  -- Считаем по процентам
        for cc in (select p.cpid cpid from calc_periods p
            where p.period = period_) loop

--          if edges(2).Wh <> 0 and edges(2).VArh <> 0 then  -- потери в средней обмотке
          update calc_results set
              lossed_Wh = lossed_Wh + edges(2).lW * Wh / 100,
              lossed_Varh = lossed_Varh + edges(2).lVar * VArh / 100
            where oid = edges(2).feeder and cpid = cc.cpid;
--          end if;
--          if edges(3).Wh <> 0 and edges(3).VArh <> 0 then  -- потери в нижней обмотке
          update calc_results set
              lossed_Wh = lossed_Wh + edges(3).lW * Wh / 100,
              lossed_Varh = lossed_Varh + edges(3).lVar * VArh / 100
            where oid = edges(3).feeder and cpid = cc.cpid;
--          end if;
          update calc_results set                          -- расход в верхней обмотке
              (src, Wh, VArh, QM) =
                  (select 40, -sum(Wh + lossed_Wh), -sum(VArh + lossed_VArh), max(QM)
                    from calc_results where cpid = cc.cpid and oid in (edges(2).feeder, edges(3).feeder))
            where cpid = cc.cpid and oid = edges(1).feeder;
        end loop;
        once_more := true;
        update calc_hours set rt_type = null where oid = c.oid;  -- помечаем, что объект обработан
      end if;

    else       -- Честные расчеты по формулам
      if edges(1).qm >= 1 and edges(2).qm < 1 and edges(3).qm < 1 then  -- классика 1998 года
        -- lossed_Wh_ := windings(1).idlingW * c.common;
        -- lossed_Varh_ := windings(1).idlingVar * c.common;
        lossed_Wh_ := 0;  lossed_VArh_ := 0;
        if c.work <> 0 then
          lossed_Wh_ := lossed_Wh_ +
                        (power(nvl(edges(2).Wh,0) + nvl(edges(3).Wh,0), 2)
                        +power(nvl(edges(2).Varh,0) + nvl(edges(3).Varh,0), 2)
                        ) * nvl(windings(1).QW, 0) / c.work
                        +
                        (power(nvl(edges(2).Wh,0), 2) + power(nvl(edges(2).VArh,0), 2)
                        ) * nvl(windings(2).QW, 0) / c.work
                        +
                        (power(nvl(edges(3).Wh,0), 2) + power(nvl(edges(3).VArh,0), 2)
                        ) * nvl(windings(3).QW, 0) / c.work;

          lossed_VArh_ := lossed_VArh_ +
                        (power(nvl(edges(2).Wh,0) + nvl(edges(3).Wh,0), 2)
                        +power(nvl(edges(2).Varh,0) + nvl(edges(3).Varh,0), 2)
                        ) * nvl(windings(1).QVar, 0) / c.work
                        +
                        (power(nvl(edges(2).Wh,0), 2) + power(nvl(edges(2).VArh,0), 2)
                        ) * nvl(windings(2).QVar, 0) / c.work
                        +
                        (power(nvl(edges(3).Wh,0), 2) + power(nvl(edges(3).VArh,0), 2)
                        ) * nvl(windings(3).QVar, 0) / c.work;
        end if;
/*
DBMS_OUTPUT.Put_Line(lossed_wh_||'   '||lossed_varh_);
DBMS_OUTPUT.Put_Line(edges(1).feeder||'  '||edges(1).Wh||'  '||edges(1).VArh||'  '||edges(1).QM);
DBMS_OUTPUT.Put_Line(edges(2).feeder||'  '||edges(2).Wh||'  '||edges(2).VArh||'  '||edges(2).QM);
DBMS_OUTPUT.Put_Line(edges(3).feeder||'  '||edges(3).Wh||'  '||edges(3).VArh||'  '||edges(3).QM);
*/

        if (edges(2).Wh + edges(3).Wh) = 0 then divisor := 1; else divisor := (edges(2).Wh + edges(3).Wh); end if;
        edges(2).lW := lossed_Wh_*edges(2).Wh / divisor;
        edges(3).lW := lossed_Wh_*edges(3).Wh / divisor;
        if (edges(2).VArh + edges(3).VArh) = 0 then divisor := 1; else divisor := (edges(2).VArh + edges(3).VArh); end if;
        edges(2).lVar := lossed_VArh_*edges(2).VArh / divisor;
        edges(3).lVar := lossed_VArh_*edges(3).VArh / divisor;

        -- В цикле по подпериодам расставляем потери вводам средних/нижних обмоток
        -- и общий расход верхней обмотки
        for cc in (select p.cpid cpid, h.common common from calc_periods p, calc_hours h
            where p.period = period_ and h.cpid = p.cpid and h.oid = c.oid) loop
          update calc_results set                         -- потери х/х в средней и нижней обмотках
              lossed_Wh = lossed_Wh + windings(1).idlingW * cc.common * windings(2).S/(windings(2).S + windings(3).S),
              lossed_Varh = lossed_Varh + windings(1).idlingVAr * cc.common * windings(2).S/(windings(2).S + windings(3).S)
            where oid = edges(2).feeder and cpid = cc.cpid;
          update calc_results set
              lossed_Wh = lossed_Wh + windings(1).idlingW * cc.common * windings(3).S/(windings(2).S + windings(3).S),
              lossed_Varh = lossed_Varh + windings(1).idlingVAr * cc.common * windings(3).S/(windings(2).S + windings(3).S)
            where oid = edges(3).feeder and cpid = cc.cpid;

--          if edges(2).Wh <> 0 and edges(2).VArh <> 0 then  -- потери в средней обмотке
            update calc_results set
                lossed_Wh = lossed_Wh + edges(2).lW * Wh / decode(edges(2).Wh, 0, 1, edges(2).Wh),
                lossed_Varh = lossed_Varh + edges(2).lVar * VArh / decode(edges(2).VArh, 0, 1, edges(2).VArh)
              where oid = edges(2).feeder and cpid = cc.cpid;
--          end if;
--          if edges(3).Wh <> 0 and edges(3).VArh <> 0 then  -- потери в нижней обмотке
            update calc_results set
                lossed_Wh = lossed_Wh + edges(3).lW * Wh / decode(edges(3).Wh, 0, 1, edges(3).Wh),
                lossed_Varh = lossed_Varh + edges(3).lVar * VArh / decode(edges(3).VArh, 0, 1, edges(3).VArh)
              where oid = edges(3).feeder and cpid = cc.cpid;
--          end if;
          update calc_results set                          -- потери в верхней обмотке
              (src, Wh, VArh, QM) =
                  (select 40, -sum(Wh + lossed_Wh), -sum(VArh + lossed_VArh), max(QM)
                    from calc_results where cpid = cc.cpid and oid in (edges(2).feeder, edges(3).feeder))
            where cpid = cc.cpid and oid = edges(1).feeder;
        end loop;
        once_more := true;
        update calc_hours set rt_type = null where oid = c.oid;  -- помечаем, что объект обработан
      end if;    -- Конец расчета по методике 1998 года
    end if;      -- Конец условного оператора выбора способа расчета - по формулам или процентам
  end loop;
end;

procedure finetune is
begin
  select to_date(period_, 'yyyymmdd')+1-trunc(to_date(period_, 'yyyymmdd'), 'mm') into days from dual;

  select
      ((a.er+b.er+c.er)*(a.er+b.er+c.er)+(a.q1+b.q1+c.q1)*(a.q1+b.q1+c.q1))*0.1*13.9/110/110/days/24/1000 lr,
      ((a.ed+b.ed+c.ed)*(a.ed+b.ed+c.ed)+(a.q3+b.q3+c.q3)*(a.q3+b.q3+c.q3))*0.1*13.9/110/110/days/24/1000 ld,
      a.er+b.er+c.er sr,  a.ed+b.ed+c.ed sd,
      z.er br, z.ed bd
    into lr, ld, sr, sd, bd, br
    from
    (select sum(er) er, sum(ed) ed, sum(q1) q1, sum(q3) q3 from billold where mid = 2859
      and nexceptcalc is null and nsource > 0 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > trunc(to_date(period_, 'yyyymmdd'), 'mm')) a,
    (select sum(er) er, sum(ed) ed, sum(q1) q1, sum(q3) q3 from billold where mid = 2847
      and nexceptcalc is null and nsource > 0 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > trunc(to_date(period_, 'yyyymmdd'), 'mm')) b,
    (select sum(er) er, sum(ed) ed, sum(q1) q1, sum(q3) q3 from billold where mid = 2851
      and nexceptcalc is null and nsource > 0 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > trunc(to_date(period_, 'yyyymmdd'), 'mm')) c,
    (select sum(er) er, sum(ed) ed, sum(q1) q1, sum(q3) q3 from billold where mid = 3800
      and nexceptcalc is null and nsource > 0 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > trunc(to_date(period_, 'yyyymmdd'), 'mm')) z;

  delete from billold where mid = 3800 and nsource = -10 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > to_date(period_, 'yyyymmdd');
  delete from halfhourold where mid = 3800 and nsource = -10 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > to_date(period_, 'yyyymmdd');


  update billold set ed = ed + sr+lr-br, er = er + sd-ld-bd
    where mid = 3800 and nsource = 1500 and date_time = to_date(period_, 'yyyymmdd')+1;


  select count(*) into cnt from halfhourold where mid = 3800 and nsource = 150 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > to_date(period_, 'yyyymmdd') and ed <> 0;
  if cnt = 0 then
    update halfhourold set ed = ed + sr+lr-br
      where mid = 3800 and nsource = 150 and date_time = to_date(period_, 'yyyymmdd')+1;
  else
    update halfhourold set ed = ed + (sr+lr-br)/cnt
      where mid = 3800 and nsource = 150 and date_time <= to_date(period_, 'yyyymmdd')+1
        and date_time > to_date(period_, 'yyyymmdd') and ed <> 0;
  end if;

  select count(*) into cnt from halfhourold where mid = 3800 and nsource = 150 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > to_date(period_, 'yyyymmdd') and er <> 0;
  if cnt = 0 then
    update halfhourold set er = er + sd-ld-bd
      where mid = 3800 and nsource = 150 and date_time = to_date(period_, 'yyyymmdd')+1;
  else
    update halfhourold set er = er + (sd-ld-bd)/cnt
      where mid = 3800 and nsource = 150 and date_time <= to_date(period_, 'yyyymmdd')+1
        and date_time > to_date(period_, 'yyyymmdd') and er <> 0;
  end if;


  select
      ((a.er)*(a.er)+(a.q1)*(a.q1))*0.1*7.5/110/110/days/24/1000 lr,
      ((a.ed)*(a.ed)+(a.q3)*(a.q3))*0.1*7.5/110/110/days/24/1000 lr,
      a.er,  a.ed sd,
      z.er br, z.ed bd
    into lr, ld, sr, sd, bd, br
    from
    (select sum(er) er, sum(ed) ed, sum(q1) q1, sum(q3) q3 from billold where mid = 2855
      and nexceptcalc is null and nsource > 0 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > trunc(to_date(period_, 'yyyymmdd'), 'mm')) a,
    (select sum(er) er, sum(ed) ed, sum(q1) q1, sum(q3) q3 from billold where mid = 3802
      and nexceptcalc is null and nsource > 0 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > trunc(to_date(period_, 'yyyymmdd'), 'mm')) z;

  delete from billold where mid = 3802 and nsource = -10 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > to_date(period_, 'yyyymmdd');
  delete from halfhourold where mid = 3802 and nsource = -10 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > to_date(period_, 'yyyymmdd');


  update billold set ed = ed + sr+lr-br, er = er + sd-ld-bd
    where mid = 3802 and nsource = 1500 and date_time = to_date(period_, 'yyyymmdd')+1;


  select count(*) into cnt from halfhourold where mid = 3802 and nsource = 150 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > to_date(period_, 'yyyymmdd') and ed <> 0;
  if cnt = 0 then
    update halfhourold set ed = ed + sr+lr-br
      where mid = 3802 and nsource = 150 and date_time = to_date(period_, 'yyyymmdd')+1;
  else
    update halfhourold set ed = ed + (sr+lr-br)/cnt
      where mid = 3802 and nsource = 150 and date_time <= to_date(period_, 'yyyymmdd')+1
        and date_time > to_date(period_, 'yyyymmdd') and ed <> 0;
  end if;

  select count(*) into cnt from halfhourold where mid = 3802 and nsource = 150 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > to_date(period_, 'yyyymmdd') and er <> 0;
  if cnt = 0 then
    update halfhourold set er = er + sd-ld-bd
      where mid = 3802 and nsource = 150 and date_time = to_date(period_, 'yyyymmdd')+1;
  else
    update halfhourold set er = er + (sd-ld-bd)/cnt
      where mid = 3802 and nsource = 150 and date_time <= to_date(period_, 'yyyymmdd')+1
        and date_time > to_date(period_, 'yyyymmdd') and er <> 0;
  end if;


  select
      ((a.er+b.er+c.er)*(a.er+b.er+c.er)+(a.er+b.er+c.er)*(a.er+b.er+c.er)*0.64)*0.096*13.7/154/154/days/24/1000 lr,
      a.er+b.er+c.er sr,
      z.ed bd
    into lr, sr, br
    from
    (select sum(er)*(1+1.5/100) er from billold where mid in (3329, 3331)
      and nexceptcalc is null and nsource > 0 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > trunc(to_date(period_, 'yyyymmdd'), 'mm')) a,
    (select sum(er)*(1+0.4/100) er from billold where mid in (3327, 3325)
      and nexceptcalc is null and nsource > 0 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > trunc(to_date(period_, 'yyyymmdd'), 'mm')) b,
    (select sum(er) er from billold where mid in (3323, 3321)
      and nexceptcalc is null and nsource > 0 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > trunc(to_date(period_, 'yyyymmdd'), 'mm')) c,
    (select sum(er) er, sum(ed) ed, sum(q1) q1, sum(q3) q3 from billold where mid = 3867
      and nexceptcalc is null and nsource > 0 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > trunc(to_date(period_, 'yyyymmdd'), 'mm')) z;


  delete from billold where mid = 3867 and nsource = -10 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > to_date(period_, 'yyyymmdd');
  delete from halfhourold where mid = 3867 and nsource = -10 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > to_date(period_, 'yyyymmdd');


  update billold set ed = ed + sr+lr-br, er = 0
    where mid = 3867 and nsource = 1500 and date_time = to_date(period_, 'yyyymmdd')+1;


  select count(*) into cnt from halfhourold where mid = 3867 and nsource = 150 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > to_date(period_, 'yyyymmdd') and ed <> 0;
  if cnt = 0 then
    update halfhourold set ed = ed + sr+lr-br, er = 0
      where mid = 3867 and nsource = 150 and date_time = to_date(period_, 'yyyymmdd')+1;
  else
    update halfhourold set ed = ed + (sr+lr-br)/cnt, er = 0
      where mid = 3867 and nsource = 150 and date_time <= to_date(period_, 'yyyymmdd')+1
        and date_time > to_date(period_, 'yyyymmdd') and ed <> 0;
  end if;

  select
      ((a.ed)*(a.ed)+(a.ed)*(a.ed)*0.64)*0.17*45.3/154/154/days/24/1000 lr,
      ((a.ed)*(a.ed)+(a.q3)*(a.q3))*0.1*7.5/110/110/days/24/1000 ld,
      a.er,  a.ed sd,
      z.er br, z.ed bd
    into ld, lr, sr, sd, bd, br
    from
    (select sum(er) er, sum(ed) ed, sum(q1) q1, sum(q3) q3 from billold where mid = 3336
      and nexceptcalc is null and nsource > 0 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > trunc(to_date(period_, 'yyyymmdd'), 'mm')) a,
    (select sum(er) er, sum(ed) ed, sum(q1) q1, sum(q3) q3 from billold where mid = 3864
      and nexceptcalc is null and nsource > 0 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > trunc(to_date(period_, 'yyyymmdd'), 'mm')) z;

  delete from billold where mid = 3864 and nsource = -10 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > to_date(period_, 'yyyymmdd');
  delete from halfhourold where mid = 3864 and nsource = -10 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > to_date(period_, 'yyyymmdd');


  update billold set er = er + sd-ld-bd
    where mid = 3864 and nsource = 1500 and date_time = to_date(period_, 'yyyymmdd')+1;



  select count(*) into cnt from halfhourold where mid = 3864 and nsource = 150 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > to_date(period_, 'yyyymmdd') and er <> 0;
  if cnt = 0 then
    update halfhourold set er = er + sd-ld-bd
      where mid = 3864 and nsource = 150 and date_time = to_date(period_, 'yyyymmdd')+1;
  else
    update halfhourold set er = er + (sd-ld-bd)/cnt
      where mid = 3864 and nsource = 150 and date_time <= to_date(period_, 'yyyymmdd')+1
        and date_time > to_date(period_, 'yyyymmdd') and er <> 0;
  end if;

  select
      ((a.ed)*(a.ed)+(a.ed)*(a.ed)*0.64)*0.05*75.5/154/154/days/24/1000 lr,
      ((a.ed)*(a.ed)+(a.q3)*(a.q3))*0.1*7.5/110/110/days/24/1000 ld,
      a.er,  a.ed sd,
      z.er br, z.ed bd
    into ld, lr, sr, sd, bd, br
    from
    (select sum(er) er, sum(ed) ed, sum(q1) q1, sum(q3) q3 from billold where mid = 3340
      and nexceptcalc is null and nsource > 0 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > trunc(to_date(period_, 'yyyymmdd'), 'mm')) a,
    (select sum(er) er, sum(ed) ed, sum(q1) q1, sum(q3) q3 from billold where mid = 3865
      and nexceptcalc is null and nsource > 0 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > trunc(to_date(period_, 'yyyymmdd'), 'mm')) z;

  delete from billold where mid = 3865 and nsource = -10 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > to_date(period_, 'yyyymmdd');
  delete from halfhourold where mid = 3865 and nsource = -10 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > to_date(period_, 'yyyymmdd');


  update billold set er = er + sd-ld-bd
    where mid = 3865 and nsource = 1500 and date_time = to_date(period_, 'yyyymmdd')+1;



  select count(*) into cnt from halfhourold where mid = 3865 and nsource = 150 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > to_date(period_, 'yyyymmdd') and er <> 0;
  if cnt = 0 then
    update halfhourold set er = er + sd-ld-bd
      where mid = 3865 and nsource = 150 and date_time = to_date(period_, 'yyyymmdd')+1;
  else
    update halfhourold set er = er + (sd-ld-bd)/cnt
      where mid = 3865 and nsource = 150 and date_time <= to_date(period_, 'yyyymmdd')+1
        and date_time > to_date(period_, 'yyyymmdd') and er <> 0;
  end if;

  select
      ((a.ed)*(a.ed)+(a.ed)*(a.ed)*0.64)*0.17*37.05/110/110/days/24/1000 lr,
      ((a.ed)*(a.ed)+(a.q3)*(a.q3))*0.1*7.5/110/110/days/24/1000 ld,
      a.er,  a.ed sd,
      z.er br, z.ed bd
    into ld, lr, sr, sd, bd, br
    from
    (select sum(er) er, sum(ed) ed, sum(q1) q1, sum(q3) q3 from billold where mid = 3350
      and nexceptcalc is null and nsource > 0 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > trunc(to_date(period_, 'yyyymmdd'), 'mm')) a,
    (select sum(er) er, sum(ed) ed, sum(q1) q1, sum(q3) q3 from billold where mid = 3866
      and nexceptcalc is null and nsource > 0 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > trunc(to_date(period_, 'yyyymmdd'), 'mm')) z;

  delete from billold where mid = 3866 and nsource = -10 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > to_date(period_, 'yyyymmdd');
  delete from halfhourold where mid = 3866 and nsource = -10 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > to_date(period_, 'yyyymmdd');


  update billold set er = er + sd-ld-bd
    where mid = 3866 and nsource = 1500 and date_time = to_date(period_, 'yyyymmdd')+1;



  select count(*) into cnt from halfhourold where mid = 3866 and nsource = 150 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > to_date(period_, 'yyyymmdd') and er <> 0;
  if cnt = 0 then
    update halfhourold set er = er + sd-ld-bd
      where mid = 3866 and nsource = 150 and date_time = to_date(period_, 'yyyymmdd')+1;
  else
    update halfhourold set er = er + (sd-ld-bd)/cnt
      where mid = 3866 and nsource = 150 and date_time <= to_date(period_, 'yyyymmdd')+1
        and date_time > to_date(period_, 'yyyymmdd') and er <> 0;
  end if;



  delete from billold where mid = 3828 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > to_date(period_, 'yyyymmdd');
  delete from halfhourold where mid = 3828 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > to_date(period_, 'yyyymmdd');



  select
      a.er + a.lr + (a.er+a.lr)*(a.er+a.lr)*1.64*0.6*1.2/10/10/days/24/1000 br, nvl(z.er, 0) lr
    into br, lr
    from
    (select sum(er) er, 0.265*days*24 + sum(er)*sum(er)*1.64*1.28/63/63/days/24 lr from billold
       where mid in (2824)
      and nexceptcalc is null and nsource > 0 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > trunc(to_date(period_, 'yyyymmdd'), 'mm')) a,
    (select sum(er) er from billold
       where mid in (3828)
      and nexceptcalc is null and nsource > 0 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > trunc(to_date(period_, 'yyyymmdd'), 'mm')) z;


  insert into billold(mid, nsource, date_time, er, ed)
    values(3828, 1500, to_date(period_, 'yyyymmdd')+1, br-lr, 0);

--  update billold set er = br-lr, ed = 0
--    where mid = 3828 and nsource = 1500 and date_time = to_date(period_, 'yyyymmdd')+1;


  select count(*) into cnt from halfhourold where mid = 2824 and date_time <= to_date(period_, 'yyyymmdd')+1
      and date_time > to_date(period_, 'yyyymmdd');
  if cnt = 0 then
    insert into halfhourold(mid, nsource, date_time, er, ed)
      values(3828, 150, to_date(period_, 'yyyymmdd')+1, br-lr, 0);

--    update halfhourold set er = br-lr, ed = 0
--      where mid = 3828 and nsource = 150 and date_time = to_date(period_, 'yyyymmdd')+1;
  else
    for bd in 1..48 loop
      insert into halfhourold(mid, nsource, date_time, er, ed)
        values(3828, 150, to_date(period_, 'yyyymmdd')+bd/48, (br-lr)/48, 0);
    end loop;

--    update halfhourold set er = (br-lr)/cnt, ed = 0
--      where mid = 3828 and nsource = 150 and date_time <= to_date(period_, 'yyyymmdd')+1
--        and date_time > to_date(period_, 'yyyymmdd');
  end if;



end;


procedure calc(an_commit NUMBER default 1) is
-- Главная расчетная процедура
begin
  -- При расчете потерь по часовым расходам результаты записываются в HalfhourOld и
  -- в BillOld
  -- Удаляем результаты предыдущего расчета
  if by_hours then
    delete from halfhourold
      where mid in (select distinct oid from calc_results
          where cpid in (select cpid from calc_periods where period = period_))
        and date_time > sdate_ and date_time <= ldate_ and (nsource < 0 or nsource = 150);
    delete from billold
      where mid in (select distinct oid from calc_results
          where cpid in (select cpid from calc_periods where period = period_))
        and date_time > sdate_ and date_time <= ldate_ and (nsource < 0 or nsource = 1500 or nsource = 7200);
  end if;

  -- Удаляем все расчеты по данному периоду
  delete from calc_periods where period = period_;

  if not by_hours then    -- Расчет за месяц. Разбиваем месяц на подпериоды изменения коммутации
    cdate := sdate_;
    for c in (
        select distinct sdate from osm_switchings
          where sdate >= sdate_ and sdate < ldate_
        union all
        select ldate_ sdate from dual
        order by sdate) loop
      insert into calc_periods(cpid, period, sdate, edate)
        values(calc_seq.nextval, period_, cdate, c.sdate);
      cdate := c.sdate;
    end loop;
/*
    -- Добавляем подпериоды изменения направления перетоков
    delete from calc_tmp;
    for c in (select mid, count(distinct sign(nvl(er, 0) - nvl(ed, 0))) cnt from halfhourold
        where date_time > sdate_ and date_time <= ldate_ and nsource > 0
          and nexceptcalc is null and mid in (select distinct feeder from rt_links)
          and (nvl(er, 0) <> 0 or nvl(ed, 0) <> 0)
        group by mid
        having count(distinct sign(nvl(er,0) - nvl(ed,0))) > 1) loop

      i := 0;
      for cc in (select decode(sign(nvl(er, 0) - nvl(ed, 0)), 0, 1, sign(nvl(er, 0) - nvl(ed, 0))) sgn,
            date_time, er, ed from halfhourold
          where nsource > 0 and nexceptcalc is null and mid = c.mid
            and date_time > sdate_ and date_time <= ldate_
          order by date_time) loop

        if i <> 0 then
          if cc.sgn <> i then
            i := cc.sgn;
            insert into calc_tmp(dt) values(cc.date_time - 1/48);
          end if;
        else
          i := cc.sgn;
        end if;
      end loop;

      for cc in (select dt from calc_tmp order by dt) loop
        begin
          select cpid, edate into i, cdate from calc_periods
            where period = period_ and sdate < cc.dt and edate > cc.dt;
        exception when others then i := 0;
        end;
        if i <> 0 then
          update calc_periods set edate = cc.dt where cpid = i;
          insert into calc_periods(cpid, period, sdate, edate)
            values(calc_seq.nextval, period_, cc.dt, cdate);
        end if;
      end loop;
    end loop;
*/
  else                    -- Расчет по часам. Имеем 24 подпериода
    for i in 1..24 loop
      insert into calc_periods(cpid, period, sdate, edate)
        values(calc_seq.nextval, period_, sdate_+ (i-1)/24, sdate_+ i/24);
    end loop;
  end if;



  -- Calc_results набиваем перетоками актива/реактива по подпериодам с учетом
  -- инверсии. В lossed_wh временно записываем процент реактива от актива, если он проставлен
--  for c in (select * from calc_periods where period = period_) loop
    insert into calc_results(oid, cpid, src, wh, varh, lossed_wh, lossed_varh, qm)
      select o.oid, p.cpid, 10,
          sum(decode(f.ninverted, 1, nvl(ed,0)-nvl(er,0), nvl(er,0)-nvl(ed,0))),
          sum(decode(f.ninverted, 1, nvl(q3,0)-nvl(q1,0), nvl(q1,0)-nvl(q3,0))),
          nvl(max(nratio), 0), 0, 0
        from rt_objects o, calc_periods p, feeders f, halfhourold h, recompens r
        where o.rt_type = 900 and f.mid = o.oid and h.mid = o.oid and h.nexceptcalc is null
          and p.period = period_ and h.date_time > p.sdate and h.date_time <= p.edate
          and f.nrecompens = r.nrecompens(+)
        group by o.oid, p.cpid;
--  end loop;

  -- Замещаем реактивную э/э долей активной по точкам, где расход реактива не по счетчику
  update calc_results set varh = wh * lossed_wh, lossed_wh = 0
    where cpid in (select cpid from calc_periods where period = period_)
      and lossed_wh <> 0;


  -- В таблице результатов расчета по подпериодам всем фидерам без данных проставляем
  -- нули с признаком отсутствия данных
  for c in (select * from calc_periods where period = period_) loop
    insert into calc_results(oid, cpid, src, wh, varh, lossed_wh, lossed_varh, qm)
      select oid, c.cpid, 10, 0, 0, 0, 0, 1 from rt_objects o
        where o.rt_type in (-1, 900)
          and o.oid not in (select oid from calc_results where cpid = c.cpid);
  end loop;

  -- Для точек, которые опрашиваются автоматически, сбрасываем метку качества.
  -- Т.е. предполагаем, что они обесточены и имеют нулевой расход
  for c in (select r.rowid rid from calc_results r, feeders f
      where r.qm = 1 and cpid in (select cpid from calc_periods where period = period_)
        and f.mid = r.oid and nvl(f.canal, 0) <> 0) loop
    update calc_results set qm = 0 where rowid = c.rid;
  end loop;

  -- Ячейки секционных соединителей не должны присутствовать в Calc_results
  delete from calc_results where oid in (select feeder from rt_links where switch <> 0
        group by switch, feeder having count(*) > 1);

  -- Предполагаем, что во всех подпериодах все трансформаторы и линии были в работе
  insert into calc_hours(oid, cpid, common, work, rt_type)
    select oid, cpid, round((edate - sdate)*24), round((edate - sdate)*24), rt_type
      from rt_objects o, calc_periods p where o.rt_type in (500, 600, 610)
        and p.period = period_;
  -- В свое время не догадался придумать разные rt_types для линий и участков линий. Теперь
  -- такая чепуха:
  delete from calc_hours where oid in (select oid from rt_objects where rt_type = 500
      and parent is null);

  -- В рабочей таблице связей тиражируем связи с выключателями по числу
  -- подпериодов
  insert into calc_links(cpid, outfit, feeder, switch)
    select cpid, outfit, feeder, switch from calc_periods p, rt_links l
      where p.period = period_ and l.switch is not null;

  -- По присоединениям, отключенным от шин в подпериоде, уменьшается
  -- на единицу метка качества в результатах расчета и удаляются связи
  for c in (select * from calc_periods where period = period_) loop
    update calc_results set qm = qm - 1
      where cpid = c.cpid         --and qm = 1  --< новый взгляд на отключенные присоединения
        and oid in (select min(feeder) from calc_links
            where cpid = c.cpid and switch in (select oid from osm_switchings
                where state <> 1 and sdate <= c.sdate and ldate > c.sdate)
              group by feeder);

    delete from calc_links
      where cpid = c.cpid
        and switch in (select switch from calc_links
            where cpid = c.cpid and switch in (select oid from osm_switchings
                where state <> 1 and sdate <= c.sdate and ldate > c.sdate));
  end loop;

  -- Не от хорошей жизни копируем безусловные связи столько раз, сколько есть
  -- подпериодов
  insert into calc_links(cpid, outfit, feeder, switch)
    select cpid, outfit, feeder, 0 from calc_periods p, rt_links l
      where p.period = period_ and l.switch is null;

  -- Объединяем в узлы секции шин, у которых в таблице связи проставлены секционники
  for c in (select * from calc_periods where period = period_) loop
    for cc in (select switch, feeder from calc_links where cpid = c.cpid and switch <> 0
        group by switch, feeder having count(*) > 1) loop
      select a.outfit, b.outfit into node, bus from calc_links a, calc_links b
        where a.switch = cc.switch and b.switch = a.switch and a.outfit <> b.outfit
          and rownum = 1;
      delete from calc_links where cpid = c.cpid and switch = cc.switch;
      update calc_links set outfit = node
        where cpid = c.cpid and outfit = bus;
    end loop;
  end loop;
/*
  -- Считаем часы работы трансформаторов
  for c in (select * from calc_periods where period = period_) loop
    for cc in (select oid from rt_objects where rt_type in (600, 610)) loop
      select count(*) into cnt from calc_links
        where cpid = c.cpid and outfit <> cc.oid and feeder in
            (select feeder from rt_links where outfit = cc.oid);
      update calc_hours set common = decode(cnt, 0, 0, common), work = decode(cnt, 0, 0, 1, 0, work)
        where cpid = c.cpid and oid = cc.oid;
    end loop;
  end loop;
  -- ... и общие часы работы линий
  for c in (select * from calc_periods where period = period_) loop
    for cc in (select oid from calc_hours where rt_type = 500) loop
      select count(*) into cnt from calc_links
        where cpid = c.cpid and outfit <> cc.oid and feeder in
            (select feeder from rt_links where outfit = cc.oid);
      update calc_hours set common = decode(cnt, 2, common, 0)
        where cpid = c.cpid and oid = cc.oid;
    end loop;
  end loop;
*/

  once_more := true;   -- надеемся чего-то посчитать
  while once_more loop
    while once_more loop
      once_more := false; -- след. три процедуры взведут флаг, если чего-нибудь восстановят
      recovery_by_bus;
      recovery_by_lines;
    end loop;
    recovery_by_trans;
  end loop;


  -- Разноска потерь
/*  VIA-1
  for c in (select * from calc_periods where period = period_) loop
    for cc in (select distinct outfit from calc_links l, rt_objects o
        where l.cpid = c.cpid and o.oid = l.outfit and o.rt_type = 0) loop
      select sum(lossed_wh), sum(lossed_varh) into edges(1).lw, edges(1).lvar from calc_results
        where cpid = c.cpid and oid in
            (select distinct feeder from calc_links where cpid = c.cpid and outfit = cc.outfit);
      select sum(wh), sum(varh) into edges(1).wh, edges(1).varh from calc_results
        where cpid = c.cpid and oid in
            (select distinct feeder from calc_links where cpid = c.cpid and outfit = cc.outfit)
          and lossed_wh = 0 and lossed_varh = 0;
--      if edges(1).wh <> 0 and edges(1).varh <> 0 then
        update calc_results
          set lossed_wh = -edges(1).lw * wh / decode(edges(1).wh, 0, 1, edges(1).wh),
              lossed_varh = -edges(1).lvar * varh / decode(edges(1).varh, 0, 1, edges(1).varh)
          where cpid = c.cpid and oid in
              (select distinct feeder from calc_links where cpid = c.cpid and outfit = cc.outfit)
            and lossed_wh = 0 and lossed_varh = 0;
--      end if;
    end loop;
  end loop;
*/

  -- Отрабатываем ситуации, когда граница принадлежности проходит где-то
  -- внутри ВЛ и на двух ее концах есть измерения
/*
  for c in (select * from calc_periods where period = period_) loop
    for cc in (select distinct outfit from calc_links l, rt_objects o
        where l.cpid = c.cpid and o.oid = l.outfit and o.rt_type in (0, 400)) loop

      select count(*), sum(src), max(src) into cnt, qm_, node from calc_results
        where cpid = c.cpid and oid in (select feeder from calc_links
            where cpid = c.cpid and outfit = cc.outfit);

      if cnt = 2 and qm_ = 60 and node < 40 then  -- Свой человек: на шине только две точки
                                                  -- и обе восстановлены по линиям

        update calc_results set wh = decode(sign(wh), -1, -0.1, 0, 0, 99999999999999)
          where cpid = c.cpid and oid in (select feeder from calc_links
            where cpid = c.cpid and outfit = cc.outfit);
        i := 0;
        for d in (select oid, sum(wh) wh, sum(varh) varh from calc_results
            where cpid = c.cpid and oid in (select feeder from calc_links
                where cpid = c.cpid and outfit in (select outfit from calc_links
                    where cpid = c.cpid and feeder in (select feeder from calc_links
                        where cpid = c.cpid and outfit = cc.outfit)))
--              and oid not in (select feeder from calc_links
--                  where cpid = c.cpid and outfit = cc.outfit)
            group by oid
            order by wh asc) loop
          i := i + 1;
          edges(i).feeder := d.oid;  edges(i).wh := d.wh;  edges(i).varh := d.varh;
        end loop;

        select nL into edges(1).lw from connectionparam
          where mid = (select parent from calc_links l, rt_objects o where o.oid = l.outfit
            and cpid = c.cpid and feeder = edges(1).feeder and rt_type = 500);

        select nL into edges(3).lw from connectionparam
          where mid = (select parent from calc_links l, rt_objects o where o.oid = l.outfit
            and cpid = c.cpid and feeder = edges(3).feeder and rt_type = 500);


        update calc_results set
--            wh = -edges(1).Wh - (-edges(1).Wh - edges(3).Wh) * edges(3).lw/(edges(1).lw + edges(3).lw),
            lossed_wh = (-edges(1).Wh - edges(3).Wh) * edges(3).lw/(edges(1).lw + edges(3).lw),
--            VArh = -edges(1).VArh - (-edges(1).VArh - edges(3).VArh) * edges(3).lw/(edges(1).lw + edges(3).lw),
            lossed_VArh = (-edges(1).VArh - edges(3).VArh) * edges(3).lw/(edges(1).lw + edges(3).lw)
          where cpid = c.cpid and oid = edges(3).feeder;
        update calc_results set
            wh = -edges(1).Wh - (-edges(1).Wh - edges(3).Wh) * edges(1).lw/(edges(1).lw + edges(3).lw),
            lossed_wh = (-edges(1).Wh - edges(3).Wh) * edges(1).lw/(edges(1).lw + edges(3).lw),
            VArh = -edges(1).VArh - (-edges(1).VArh - edges(3).VArh) * edges(1).lw/(edges(1).lw + edges(3).lw),
            lossed_VArh = (-edges(1).VArh - edges(3).VArh) * edges(1).lw/(edges(1).lw + edges(3).lw)
          where cpid = c.cpid and oid = edges(4).feeder;
        update calc_results set
            (wh, varh, lossed_wh, lossed_varh) = (select -wh, -varh, 0, 0 from calc_results
                where cpid = c.cpid and oid = edges(4).feeder)
          where cpid = c.cpid and oid = edges(2).feeder;
      end if;
    end loop;
  end loop;
*/


  if by_hours then            -- Расчет по часовым расходам. Заполняем ХалфХаурОлд и Bill
    -- Расходы восстановленных присоединений
/*  VIA-2
    insert into halfhourold(mid, date_time, nsource, er, ed, q1, q3)
      select oid, edate, 150,
          decode(sign(wh), -1, 0, wh),
          decode(sign(wh), 1, 0, -wh),
          decode(sign(wh), -1, 0, varh),
          decode(sign(wh), 1, 0, -varh)
        from calc_results r, calc_periods p
        where p.period = period_ and r.cpid = p.cpid and qm < 1 and src > 10;
*/
    for c in (select oid, edate,
          decode(sign(wh), -1, 0, wh) er,
          decode(sign(wh), 1, 0, -wh) ed,
          decode(sign(wh), -1, 0, varh) q1,
          decode(sign(wh), 1, 0, -varh) q3
        from calc_results r, calc_periods p
        where p.period = period_ and r.cpid = p.cpid and qm < 1 and src > 10) loop

      insert into halfhourold(mid, date_time, nsource, er, ed, q1, q3)
        values(c.oid, c.edate - 1/48, 150, c.er/2, c.ed/2, c.q1/2, c.q3/2);
      insert into halfhourold(mid, date_time, nsource, er, ed, q1, q3)
        values(c.oid, c.edate, 150, c.er/2, c.ed/2, c.q1/2, c.q3/2);

/*
      insert into halfhourold(mid, date_time, nsource, er, ed, q1, q3)
        values(c.oid, c.edate, 150, c.er, c.ed/2, c.q1/2, c.q3/2);
*/
    end loop;

    insert into billold(mid, date_time, nsource, er, ed, q1, q3)
      select oid, to_date(period_, 'yyyymmdd')+1, 1500,
          sum(decode(sign(wh), -1, 0, wh)),
          sum(decode(sign(wh), 1, 0, -wh)),
          sum(decode(sign(wh), -1, 0, varh)),
          sum(decode(sign(wh), 1, 0, -varh))
        from calc_results r
        where cpid in (select cpid from calc_periods where period = period_) and qm < 1 and src > 10
        group by oid, to_date(period_, 'yyyymmdd')+1;

    -- Потери по всем точкам
/*  VIA-2
    insert into halfhourold(mid, date_time, nsource, er, ed, q1, q3)
      select oid, edate, -10,
          decode(sign(wh), -1, 0, lossed_wh),
          decode(sign(wh), 1, 0, -lossed_wh),
          decode(sign(wh), -1, 0, lossed_varh),
          decode(sign(wh), 1, 0, -lossed_varh)
        from calc_results r, calc_periods p
        where p.period = period_ and r.cpid = p.cpid and qm < 1;
*/
    for c in (select oid, edate,
          decode(sign(wh), -1, 0, lossed_wh) er,
          decode(sign(wh), 1, 0, -lossed_wh) ed,
          decode(sign(wh), -1, 0, lossed_varh) q1,
          decode(sign(wh), 1, 0, -lossed_varh) q3
        from calc_results r, calc_periods p
        where p.period = period_ and r.cpid = p.cpid and qm < 1) loop
begin
      insert into halfhourold(mid, date_time, nsource, er, ed, q1, q3)
        values(c.oid, c.edate - 1/48, -10, c.er/2, c.ed/2, c.q1/2, c.q3/2);
      insert into halfhourold(mid, date_time, nsource, er, ed, q1, q3)
        values(c.oid, c.edate, -10, c.er/2, c.ed/2, c.q1/2, c.q3/2);
exception when others then null;
end;

/*
      insert into halfhourold(mid, date_time, nsource, er, ed, q1, q3)
        values(c.oid, c.edate, -10, c.er, c.ed/2, c.q1/2, c.q3/2);
*/
    end loop;

begin
    insert into billold(mid, date_time, nsource, er, ed, q1, q3)
      select oid, to_date(period_, 'yyyymmdd')+1, -10,
          sum(decode(sign(wh), -1, 0, lossed_wh)),
          sum(decode(sign(wh), 1, 0, -lossed_wh)),
          sum(decode(sign(wh), -1, 0, lossed_varh)),
          sum(decode(sign(wh), 1, 0, -lossed_varh))
        from calc_results r
        where cpid in (select cpid from calc_periods where period = period_) and qm < 1
        group by oid, to_date(period_, 'yyyymmdd')+1;
exception when others then null;
end;

  end if;

select vvalue into i from parameter where npid = 12;
if i = 11 then
  edges(1).feeder := 2440;  edges(2).feeder := 3093;  edges(3).feeder := 3762;  edges(4).feeder := 3763;
  windings(1).S := 3764;  windings(2).S := 3766;
  select nL into windings(1).QW from connectionparam
    where mid = windings(1).S;
  select nL into windings(2).QW from connectionparam
    where mid = windings(2).S;

  select sum(er), sum(ed) into edges(1).wh, edges(1).lw from billold
    where mid = edges(1).feeder and nexceptcalc is null and nsource > 0
      and date_time = to_date(period_, 'yyyymmdd')+1;
  select decode(sum(er), 0, 1, sum(er)), decode(sum(ed), 0, 1, sum(ed)) into edges(2).wh, edges(2).lw from billold
    where mid = edges(2).feeder and nexceptcalc is null and nsource > 0
      and date_time = to_date(period_, 'yyyymmdd')+1;
  ler := (edges(1).lw - edges(2).wh);
  led := (edges(2).lw - edges(1).wh);
  if edges(2).lw = 0 then edges(2).lw := 0.0001; end if;
  if edges(2).wh = 0 then edges(2).wh := 0.0001; end if;

--  update halfhourold set er = 0 where mid in (edges(1).feeder, edges(2).feeder, edges(3).feeder, edges(4).feeder)

  for c in (select a.date_time date_time, sum(a.er) er1, sum(a.ed) ed1, sum(b.er) er2, sum(b.ed) ed2
      from halfhourold a, halfhourold b
      where a.date_time = b.date_time and a.mid = edges(1).feeder and b.mid = edges(2).feeder
        and a.date_time > to_date(period_, 'yyyymmdd') and a.date_time <= to_date(period_, 'yyyymmdd')+1
        and b.date_time > to_date(period_, 'yyyymmdd') and b.date_time <= to_date(period_, 'yyyymmdd')+1
        and a.nexceptcalc is null and b.nexceptcalc is null and a.nsource > 0 and b.nsource > 0
      group by a.date_time) loop
    update halfhourold set
        er = led*windings(1).QW/(windings(1).QW + windings(2).QW)*c.ed2/edges(2).lw
      where mid = edges(1).feeder and date_time = c.date_time and nsource = -10;
    update halfhourold set
        er = ler*windings(2).QW/(windings(1).QW + windings(2).QW)*c.er2/edges(2).wh
      where mid = edges(2).feeder and date_time = c.date_time and nsource = -10;
    update halfhourold set
        er = ler*windings(1).QW/(windings(1).QW + windings(2).QW)*c.er2/edges(2).wh
      where mid = edges(3).feeder and date_time = c.date_time and nsource = -10;
    update halfhourold set
        er = led*windings(2).QW/(windings(1).QW + windings(2).QW)*c.ed2/edges(2).lw
      where mid = edges(4).feeder and date_time = c.date_time and nsource = -10;
    update halfhourold set
        er = c.er2 + ler*windings(2).QW/(windings(1).QW + windings(2).QW)*c.er2/edges(2).wh,
        ed = c.ed2 - led*windings(2).QW/(windings(1).QW + windings(2).QW)*c.ed2/edges(2).lw
      where mid = edges(3).feeder and date_time = c.date_time and nsource = 150;
    update halfhourold set
        er = c.ed2 - led*windings(2).QW/(windings(1).QW + windings(2).QW)*c.ed2/edges(2).lw,
        ed = c.er2 + ler*windings(2).QW/(windings(1).QW + windings(2).QW)*c.er2/edges(2).wh
      where mid = edges(4).feeder and date_time = c.date_time and nsource = 150;
  end loop;

  for c in (select * from calc_periods where period = period_) loop
    update calc_results r set lossed_wh =
        (select sum(er) from halfhourold where mid = r.oid
            and date_time > c.sdate and date_time <= c.edate and nsource = -10)
      where oid in (edges(1).feeder, edges(2).feeder, edges(3).feeder, edges(4).feeder)
        and cpid = c.cpid;
    update calc_results r set wh =
        (select sum(er-ed) from halfhourold where mid = r.oid
            and date_time > c.sdate and date_time <= c.edate and nsource = 150)
      where oid in (edges(3).feeder, edges(4).feeder)
        and cpid = c.cpid;
  end loop;
  delete from billold where mid in (edges(3).feeder, edges(4).feeder)
      and date_time > to_date(period_, 'yyyymmdd') and date_time <= to_date(period_, 'yyyymmdd')+1;
  delete from billold where mid in (edges(1).feeder, edges(2).feeder) and nsource = -10
      and date_time > to_date(period_, 'yyyymmdd') and date_time <= to_date(period_, 'yyyymmdd')+1;
  insert into billold (mid, date_time, nsource, er)
    select mid, to_date(period_, 'yyyymmdd')+1, -10, sum(er) from halfhourold
      where mid in (edges(1).feeder, edges(2).feeder, edges(3).feeder, edges(4).feeder)
        and date_time > to_date(period_, 'yyyymmdd') and date_time <= to_date(period_, 'yyyymmdd')+1
        and nsource = -10
      group by mid;
  insert into billold (mid, date_time, nsource, er, ed)
    select mid, to_date(period_, 'yyyymmdd')+1, 1500, sum(er), sum(ed) from halfhourold
      where mid in (edges(3).feeder, edges(4).feeder)
        and date_time > to_date(period_, 'yyyymmdd') and date_time <= to_date(period_, 'yyyymmdd')+1
        and nsource = 150
      group by mid;


  edges(1).feeder := 2442;  edges(2).feeder := 3095;  edges(3).feeder := 3773;  edges(4).feeder := 3774;
  windings(1).S := 3770;  windings(2).S := 3768;
  select nL into windings(1).QW from connectionparam
    where mid = windings(1).S;
  select nL into windings(2).QW from connectionparam
    where mid = windings(2).S;

  select sum(er), sum(ed) into edges(1).wh, edges(1).lw from billold
    where mid = edges(1).feeder and nexceptcalc is null and nsource > 0
      and date_time = to_date(period_, 'yyyymmdd')+1;
  select decode(sum(er), 0, 1, sum(er)), decode(sum(ed), 0, 1, sum(ed)) into edges(2).wh, edges(2).lw from billold
    where mid = edges(2).feeder and nexceptcalc is null and nsource > 0
      and date_time = to_date(period_, 'yyyymmdd')+1;
  ler := (edges(1).lw - edges(2).wh);
  led := (edges(2).lw - edges(1).wh);
  if edges(2).lw = 0 then edges(2).lw := 0.0001; end if;
  if edges(2).wh = 0 then edges(2).wh := 0.0001; end if;

--  update halfhourold set er = 0 where mid in (edges(1).feeder, edges(2).feeder, edges(3).feeder, edges(4).feeder)

  for c in (select a.date_time date_time, sum(a.er) er1, sum(a.ed) ed1, sum(b.er) er2, sum(b.ed) ed2
      from halfhourold a, halfhourold b
      where a.date_time = b.date_time and a.mid = edges(1).feeder and b.mid = edges(2).feeder
        and a.date_time > to_date(period_, 'yyyymmdd') and a.date_time <= to_date(period_, 'yyyymmdd')+1
        and b.date_time > to_date(period_, 'yyyymmdd') and b.date_time <= to_date(period_, 'yyyymmdd')+1
        and a.nexceptcalc is null and b.nexceptcalc is null and a.nsource > 0 and b.nsource > 0
      group by a.date_time) loop
    update halfhourold set
        er = led*windings(1).QW/(windings(1).QW + windings(2).QW)*c.ed2/edges(2).lw
      where mid = edges(1).feeder and date_time = c.date_time and nsource = -10;
    update halfhourold set
        er = ler*windings(2).QW/(windings(1).QW + windings(2).QW)*c.er2/edges(2).wh
      where mid = edges(2).feeder and date_time = c.date_time and nsource = -10;
    update halfhourold set
        er = ler*windings(1).QW/(windings(1).QW + windings(2).QW)*c.er2/edges(2).wh
      where mid = edges(3).feeder and date_time = c.date_time and nsource = -10;
    update halfhourold set
        er = led*windings(2).QW/(windings(1).QW + windings(2).QW)*c.ed2/edges(2).lw
      where mid = edges(4).feeder and date_time = c.date_time and nsource = -10;
    update halfhourold set
        er = c.er2 + ler*windings(2).QW/(windings(1).QW + windings(2).QW)*c.er2/edges(2).wh,
        ed = c.ed2 - led*windings(2).QW/(windings(1).QW + windings(2).QW)*c.ed2/edges(2).lw
      where mid = edges(3).feeder and date_time = c.date_time and nsource = 150;
    update halfhourold set
        er = c.ed2 - led*windings(2).QW/(windings(1).QW + windings(2).QW)*c.ed2/edges(2).lw,
        ed = c.er2 + ler*windings(2).QW/(windings(1).QW + windings(2).QW)*c.er2/edges(2).wh
      where mid = edges(4).feeder and date_time = c.date_time and nsource = 150;
  end loop;

  for c in (select * from calc_periods where period = period_) loop
    update calc_results r set lossed_wh =
        (select sum(er) from halfhourold where mid = r.oid
            and date_time > c.sdate and date_time <= c.edate and nsource = -10)
      where oid in (edges(1).feeder, edges(2).feeder, edges(3).feeder, edges(4).feeder)
        and cpid = c.cpid;
    update calc_results r set wh =
        (select sum(er-ed) from halfhourold where mid = r.oid
            and date_time > c.sdate and date_time <= c.edate and nsource = 150)
      where oid in (edges(3).feeder, edges(4).feeder)
        and cpid = c.cpid;
  end loop;
  delete from billold where mid in (edges(3).feeder, edges(4).feeder)
      and date_time > to_date(period_, 'yyyymmdd') and date_time <= to_date(period_, 'yyyymmdd')+1;
  delete from billold where mid in (edges(1).feeder, edges(2).feeder) and nsource = -10
      and date_time > to_date(period_, 'yyyymmdd') and date_time <= to_date(period_, 'yyyymmdd')+1;
  insert into billold (mid, date_time, nsource, er)
    select mid, to_date(period_, 'yyyymmdd')+1, -10, sum(er) from halfhourold
      where mid in (edges(1).feeder, edges(2).feeder, edges(3).feeder, edges(4).feeder)
        and date_time > to_date(period_, 'yyyymmdd') and date_time <= to_date(period_, 'yyyymmdd')+1
        and nsource = -10
      group by mid;
  insert into billold (mid, date_time, nsource, er, ed)
    select mid, to_date(period_, 'yyyymmdd')+1, 1500, sum(er), sum(ed) from halfhourold
      where mid in (edges(3).feeder, edges(4).feeder)
        and date_time > to_date(period_, 'yyyymmdd') and date_time <= to_date(period_, 'yyyymmdd')+1
        and nsource = 150
      group by mid;

  finetune;
end if;


  -- Очищаем Calc_links
  delete from calc_links where cpid in (select cpid from calc_periods where period = period_);
  if an_commit=1 then
  commit;
  end if;
end; -- Procedure


Procedure run(period in number,an_commit NUMBER) is
begin
  IF nvl(util_pg.nlosstype,0) <> 2 THEN
    return;
  END IF;
  begin
    select to_number(vvalue) into i from parameter where npid = 30;
  exception when others then i := 0;
  end;
  period_ := period;
  if i = 0 then  -- расчет потерь исключительно на месячных расходах
    if period_ > 999999 then period_ := round(period_/100); end if;
    sdate_ := to_date(to_char(period_), 'yyyymm');
    ldate_ := add_months(sdate_, 1);
    by_hours := false;
  else           -- может быть расчет за одни сутки
    if period_ > 999999 then
      sdate_ := to_date(to_char(period_), 'yyyymmdd');
      ldate_ := sdate_ + 1;
      by_hours := true;
    else
      sdate_ := to_date(to_char(period), 'yyyymm');
      ldate_ := add_months(sdate_, 1);
      by_hours := false;
    end if;
  end if;
  calc(an_commit);
end;

Procedure recalc_losses(an_maket IN NUMBER, ddate_ IN DATE) is
  i     number;
  j     number;
  k     number;
begin
  select to_char(trunc(ddate_, 'mm'), 'yyyymmdd'), to_char(ddate_, 'dd') into j, k from dual;
  for i in 0..k-1 loop
    loss_replacement_pg.run(j+i);
  end loop;
end;


Procedure rep(sid_ in number, period in number) is

  type t_p is table of connectionparam%rowtype
    index by binary_integer;
  p             t_p;
--  type r_v is table of calc_results%rowtype;
--    index by bynary_integer;
--  v             r_v;
  type tr_edges is record(
    feeder      number,
    Wh          number,
    Varh        number,
    QM          number,
    lW          number,
    lVar        number,
    src         number,
    vsrc        varchar2(100));
  type t_edges is table of tr_edges
    index by binary_integer;
  v             t_edges;
  i             number;

  ord_          number := 0;
  lvl_          number := 0;
  line_         varchar2(2000);
  s1            varchar2(2000);
  s2            varchar2(2000);
  s3            varchar2(2000);
  s             varchar2(2000);
  w             number := 25;
  unnecessary   number;
  j             number;
  lw            number;
  lvar          number;
  wh            number;
  varh          number;

  procedure il is
  begin
    line_ := lpad(' ', lvl_*2)||rpad(s1, greatest(length(s1), w),' ') || rpad(s2, w,' ') || rpad(s3, w,' ');
    insert into calc_protocol(sid, period, ord, lvl, line)
      values(sid_, period_, ord_, lvl_, line_);
    s1 := ' ';  s2 := ' ';  s3 := ' ';
    ord_ := ord_ + 1;
  end;

BEGIN
  delete from calc_protocol where sid = sid_ and period = period_;

  begin
    select to_number(vvalue) into i from parameter where npid = 30;
  exception when others then i := 0;
  end;
  period_ := period;
  if i = 0 then  -- расчет потерь исключительно на месячных расходах
    if period_ > 999999 then period_ := round(period_/100); end if;
    sdate_ := to_date(to_char(period_), 'yyyymm');
    ldate_ := add_months(sdate_, 1);
  else           -- может быть расчет за одни сутки
    if period_ > 999999 then
      sdate_ := to_date(to_char(period_), 'yyyymmdd');
      ldate_ := sdate_ + 1;
    else
      sdate_ := to_date(to_char(period), 'yyyymm');
      ldate_ := add_months(sdate_, 1);
    end if;
  end if;

  lvl_ := 0;
  s1 := 'ПРОТОКОЛ РАСЧЕТА ОБЪЕКТОВ СХЕМЫ "';
  select name into s from se_sheets where sid = sid_;
  s1 := s1 || s || '" ЗА ПЕРИОД C '||to_char(sdate_, 'dd.mm.yy')||' ПО '||to_char(ldate_, 'dd.mm.yy');
--  select to_char(to_date(period_, 'yyyymm'), 'mm.yyyy') into s from dual;
--  s1 := s1 || s;
  il;

  -- Цикл по подстанциям с суммированием потерь тр-ров и небалансов шин
  for c in (select * from se_objects where sid = sid_ and se_type = 1000 order by name) loop
    il;
    lvl_ := 1;
    s1 := c.name; unnecessary := ord_; il;

    -- Потери в трансформаторах
    for cc in (select * from se_objects where sid = sid_ and subst = c.oid and se_type in (40, 110)
        order by name) loop
      unnecessary := 0;
      lvl_ := 2;
      s1 := cc.name;  il;

      i := 0;
      for d in (select * from connectionparam where mid = cc.oid order by nwinding) loop
        i := i + 1;
        p(i).nsn := d.nsn;  p(i).nsh := nvl(d.nsh, d.nsn); p(i).ndeltapidling := d.ndeltapidling;
        p(i).ndeltapsc := d.ndeltapsc;  p(i).niidling := d.niidling; p(i).nusc := d.nusc;
      end loop;

      lvl_ := 4;
      if i = 1 then
        s1 := 'Sn, кВА    = '||p(1).nsn;  il;
        s1 := 'dPхх, кВт  = '||p(1).ndeltapidling;  il;
        s1 := 'dPкз, кВт  = '||p(1).ndeltapsc;  il;
        s1 := 'Iхх, %     = '||p(1).niidling;  il;
        s1 := 'Uкз, %     = '||p(1).nusc;  il;
      end if;
      if i = 3 then
        s1 := 'Sn, кВА    = '||p(1).nsn; il;
        s1 := 'Sв, кВА    = '||p(1).nsh;        s2 := 'Sc, кВА    = '||p(2).nsh;  s3 := 'Sн, кВА    = '||p(3).nsh; il;
        s1 := 'dPхх, кВт  = '||p(1).ndeltapidling;  il;
        s1 := 'dPкзв, кВт = '||p(1).ndeltapsc;  s2 := 'dPкзc, кВт = '||p(2).ndeltapsc;  s3 := 'dPкзн, кВт = '||p(3).ndeltapsc;  il;
        s1 := 'Iхх, %     = '||p(1).niidling;  il;
        s1 := 'Uкзв, %    = '||p(1).nusc;      s2 := 'Uкзс, %    = '||p(2).nusc;  s3 := 'Uкзн, %    = '||p(3).nusc;  il;
      end if;
      select sum(common), sum(work) into i, j
        from calc_hours where oid = cc.oid and cpid in (select cpid from calc_periods where period = period_);
      s1 := 'To, час.   = '||i;  s2 := 'Tp, час.   = '||j;
      il;

      v(1).feeder := 0;  v(1).wh := 0;  v(1).varh := 0;  v(1).qm := 0;  v(1).lw := 0;  v(1).lvar := 0;  v(1).src := 0;  v(1).vsrc := ' ';
      v(2).feeder := 0;  v(2).wh := 0;  v(2).varh := 0;  v(2).qm := 0;  v(2).lw := 0;  v(2).lvar := 0;  v(2).src := 0;  v(2).vsrc := ' ';
      v(3).feeder := 0;  v(3).wh := 0;  v(3).varh := 0;  v(3).qm := 0;  v(3).lw := 0;  v(3).lvar := 0;  v(3).src := 0;  v(3).vsrc := ' ';
      i := 0;
      for d in (select sum(Wh) wh, sum(VArh) varh, sum(lossed_Wh) lossed_wh,
            sum(lossed_VArh) lossed_varh, max(qm) qm, max(src) src, o.voltage, o.oid
          from calc_results r, rt_objects o where cpid in (select cpid from calc_periods where period = period_)
            and o.oid in (select feeder from rt_links where outfit = cc.oid)
            and r.oid = o.oid
            group by o.oid, o.voltage
            order by o.voltage desc) loop
        i := i + 1;
        v(i).wh := d.wh;  v(i).varh := d.varh; v(i).lw := d.lossed_wh; v(i).lvar := d.lossed_varh;
        v(i).qm :=d.qm;  v(i).src := d.src;
        select decode(d.qm, 1, 'НЕТ ДАННЫХ!',
            decode(d.src, 10, 'по счетчику:', 20, 'по небалансу шин:', 30, 'по линии:', 40, ' '))
          into v(i).vsrc from dual;
      end loop;
      il;
      lvl_ := 3;
      if i = 3 then
        lvl_ := 3; s1 := 'Расход электроэнергии на низком напряжении  '||v(3).vsrc; il; lvl_:=4;
        s2 := 'Аа, кВтч  = '||v(3).wh;
        s3 := 'Аp, кВАрч  = '||v(3).varh;
        il;
        lvl_ := 3; s1 := 'Расход электроэнергии на среднем напряжении '||v(2).vsrc; il; lvl_:=4;
        s2 := 'Аа, кВтч  = '||v(2).wh;
        s3 := 'Аp, кВАрч  = '||v(2).varh;
        il;
        if v(1).src <> 40 then
          lvl_ := 3; s1 := 'Расход электроэнергии на высоком напряжении '||v(1).vsrc; il; lvl_:=4;
          s2 := 'Аа, кВтч  = '||v(1).wh;
          s3 := 'Аp, кВАрч  = '||v(1).varh;
          il;
        end if;
      else
        lvl_ := 3; s1 := 'Расход электроэнергии на низком  напряжении '||v(2).vsrc; il; lvl_:=4;
        s2 := 'Аа, кВтч  = '||v(2).wh;
        s3 := 'Аp, кВАрч  = '||v(2).varh;
        il;
        if v(1).src <> 40 then
          lvl_ := 3; s1 := 'Расход электроэнергии на высоком напряжении '||v(1).vsrc; il; lvl_:=4;
          s2 := 'Аа, кВтч  = '||v(1).wh;
          s3 := 'Аp, кВАрч  = '||v(1).varh;
          il;
        end if;
      end if;
      if v(1).src < 40 and v(1).qm < 1 then
        lvl_ := 3; s1 := 'Фактические потери электроэнергии в трансформаторе:'; il; lvl_:=4;
        s2 := 'dАа, кВтч = '||(v(1).wh + v(2).wh + v(3).wh);
        s3 := 'dАp, кВАрч = '||(v(1).varh + v(2).varh + v(3).varh);
        il;
        lvl_ := 3; s1 := 'Расчетные потери электроэнергии в трансформаторе:'; il; lvl_:=4;
        s2 := 'dАа, кВтч = '||(v(2).lw + v(3).lw);
        s3 := 'dАp, кВАрч = '||(v(2).lvar + v(3).lvar);
        il;
        lvl_ := 3; s1 := 'Расхождение между фактическими и расчетными потерями:'; il; lvl_:=4;
        s2 := 'dАа, кВтч = '||(v(1).wh + v(2).wh + v(3).wh + v(2).lw + v(3).lw);
        s3 := 'dАp, кВАрч = '||(v(1).varh + v(2).varh + v(3).varh + v(2).lvar + v(3).lvar);
        il;
        if ((v(1).wh + v(2).wh + v(3).wh) <> 0) and ((v(1).varh + v(2).varh + v(3).varh) <> 0) then
          lvl_ := 3; s1 := '                              в процентном отношении:'; il; lvl_:=4;
          s2 := 'dАа, %    = '||((v(1).wh + v(2).wh + v(3).wh + v(2).lw + v(3).lw) / (v(1).wh + v(2).wh + v(3).wh) * 100);
          s3 := 'dАp, %     = '||((v(1).varh + v(2).varh + v(3).varh + v(2).lvar + v(3).lvar) / (v(1).varh + v(2).varh + v(3).varh) * 100);
          il;
        end if;
      else
        lvl_ := 3; s1 := 'Расчетные потери электроэнергии в трансформаторе:'; il; lvl_:=4;
        s2 := 'dАа, кВтч = '||(v(2).lw + v(3).lw);
        s3 := 'dАp, кВАрч = '||(v(2).lvar + v(3).lvar);
        il;
        if v(1).wh <> 0 and v(1).varh <> 0 then
          lvl_ := 3; s1 := 'Доля потерь электроэнергии в общем расходе трансформатора:'; il; lvl_:=4;
          s2 := 'dАа, %    = '||round(-((v(2).lw + v(3).lw)/v(1).wh*100), 1);
          s3 := 'dАp, %     = '||round(-((v(2).lvar + v(3).lvar)/v(1).varh*100), 1);
          il;
        end if;
      end if;
      il;
    end loop;

    -- Ищем уровни напряжений, где можно посчитать небаланс. Т.е. нет точек, восстановленных
    -- по шинам и количество точек больше одной
    for cc in (select * from rt_objects where parent = c.oid and rt_type = 950) loop
      begin
        select sum(Wh), sum(VArh), sum(decode(sign(wh), 1, wh, 0)),
            sum(decode(sign(varh), 1, wh, 0)), max(decode(src, 20, 100, src)), count(distinct oid)
          into lw, lvar, wh, varh, j, i
          from calc_results r where cpid in (select cpid from calc_periods where period = period_)
              and r.oid in (select feeder from rt_links where outfit in
                  (select oid from rt_objects where rt_type = 0 and parent = cc.oid));
      exception when others then j := 100;
      end;
      if j < 100 and i > 1 then
        unnecessary := 0;
        lvl_ := 3; s1 := 'Небаланс шин '||cc.name||':'; il; lvl_:=4;
        s2 := 'dАа, кВтч = '||lw;
        s3 := 'dАp, кВАрч = '||lvar;
        il;
        if wh <> 0 and varh <> 0 then
          lvl_ := 3; s1 := 'Относительный небаланс шин '||cc.name||':'; il; lvl_:=4;
          s2 := 'dАа, %    = '||round(lw/wh*100, 1);
          s3 := 'dАp, %     = '||round(lvar/varh*100, 1);
          il;
        end if;
        il;
      end if;
    end loop;

    if unnecessary <> 0 then
      delete from calc_protocol where sid = sid_ and ord = unnecessary;
    end if;

  end loop;


  -- Потери в линиях
  for c in (select * from rt_objects
      where rt_type = 500 and parent is not null
        and parent in (select oid from se_objects where sid = sid_ and se_type = 500)
      order by name) loop
    il;
    lvl_ := 1;
    s1 := c.name; il;

    i := 0;
    for d in (select * from connectionparam where mid = c.parent order by nwinding) loop
      i := i + 1;
      p(i).nsn := d.nsn;  p(i).nsh := nvl(d.nsh, d.nsn); p(i).ndeltapidling := d.ndeltapidling;
      p(i).ndeltapsc := d.ndeltapsc;  p(i).niidling := d.niidling; p(i).nusc := d.nusc;
      p(i).nro := d.nro;  p(i).nxo := d.nro;  p(i).nun := d.nun;  p(i).nl := d.nl;
    end loop;

    lvl_ := 4;
    s1 := 'r0, Ом/км  = '||p(1).nro;  il;
    s1 := 'х0, Ом/км  = '||p(1).nxo;  il;
    s1 := 'L, км      = '||p(1).nl;  il;
    s1 := 'Un, кВ     = '||p(1).nun;  il;
    select sum(common) into j
      from calc_hours where oid = c.oid and cpid in (select cpid from calc_periods where period = period_);
    s1 := 'To, час.   = '||j;
    il;

    v(1).feeder := 0;  v(1).wh := 0;  v(1).varh := 0;  v(1).qm := 0;  v(1).lw := 0;  v(1).lvar := 0;  v(1).src := 0;  v(1).vsrc := ' ';
    v(2).feeder := 0;  v(2).wh := 0;  v(2).varh := 0;  v(2).qm := 0;  v(2).lw := 0;  v(2).lvar := 0;  v(2).src := 0;  v(2).vsrc := ' ';
    v(3).feeder := 0;  v(3).wh := 0;  v(3).varh := 0;  v(3).qm := 0;  v(3).lw := 0;  v(3).lvar := 0;  v(3).src := 0;  v(3).vsrc := ' ';
    i := 0;
    for d in (select sum(Wh) wh, sum(VArh) varh, sum(lossed_Wh) lossed_wh,
          sum(lossed_VArh) lossed_varh, max(qm) qm, max(src) src, o.voltage, o.oid
        from calc_results r, rt_objects o where cpid in (select cpid from calc_periods where period = period_)
          and o.oid in (select feeder from rt_links where outfit = c.oid)
          and r.oid = o.oid
          group by o.oid, o.voltage
          order by 1 asc) loop
      i := i + 1;
      v(i).wh := d.wh;  v(i).varh := d.varh; v(i).lw := d.lossed_wh; v(i).lvar := d.lossed_varh;
      v(i).qm :=d.qm;  v(i).src := d.src;
      select decode(d.qm, 1, 'НЕТ ДАННЫХ!',
          decode(d.src, 10, 'по счетчику:', 20, 'по небалансу шин:', 30, 'по линии:', 40, ' '))
        into v(i).vsrc from dual;
    end loop;
    il;
    lvl_ := 3;
    lvl_ := 3; s1 := 'Расход электроэнергии на выходе линии '||v(2).vsrc; il; lvl_:=4;
    s2 := 'Аа, кВтч  = '||v(2).wh;
    s3 := 'Аp, кВАрч  = '||v(2).varh;
    il;
    if v(1).src < 30 and v(1).qm < 1 and v(2).src < 30 and v(2).qm < 1 then
      lvl_ := 3; s1 := 'Расход электроэнергии на входе линии  '||v(1).vsrc; il; lvl_:=4;
      s2 := 'Аа, кВтч  = '||v(1).wh;
      s3 := 'Аp, кВАрч  = '||v(1).varh;
      il;
      lvl_ := 3; s1 := 'Фактические потери электроэнергии в линии:'; il; lvl_:=4;
      s2 := 'dАа, кВтч = '||(v(1).wh + v(2).wh + v(3).wh);
      s3 := 'dАp, кВАрч = '||(v(1).varh + v(2).varh + v(3).varh);
      il;
      lvl_ := 3; s1 := 'Расчетные потери электроэнергии в линии:'; il; lvl_:=4;
      lw := (v(2).wh*v(2).wh + v(2).varh*v(2).varh)*p(1).nro*p(1).nl/p(1).nun/p(1).nun/j/1000;
      lvar := (v(2).wh*v(2).wh + v(2).varh*v(2).varh)*p(1).nxo*p(1).nl/p(1).nun/p(1).nun/j/1000;
      s2 := 'dАа, кВтч = '||lw;
      s3 := 'dАp, кВАрч = '||lvar;
      il;
      lvl_ := 3; s1 := 'Расхождение между фактическими и расчетными потерями:'; il; lvl_:=4;
      s2 := 'dАа, кВтч = '||(v(1).wh + v(2).wh - lw);
      s3 := 'dАp, кВАрч = '||(v(1).varh + v(2).varh - lvar);
      il;
      lvl_ := 3; s1 := '                              в процентном отношении:'; il; lvl_:=4;
      s2 := 'dАа, %    = '||((v(1).wh + v(2).wh - lw) / (v(1).wh + v(2).wh + v(3).wh) * 100);
      s3 := 'dАp, %     = '||((v(1).varh + v(2).varh - lvar) / (v(1).varh + v(2).varh + v(3).varh) * 100);
      il;
    else
      lvl_ := 3; s1 := 'Расчетные потери электроэнергии в линии:'; il; lvl_:=4;
      s2 := 'dАа, кВтч = '||(v(2).lw + v(3).lw);
      s3 := 'dАp, кВАрч = '||(v(2).lvar + v(3).lvar);
      il;
      if (v(1).wh <> 0) and (v(1).varh <> 0) then
        lvl_ := 3; s1 := 'Доля потерь электроэнергии в общем расходе линии:'; il; lvl_:=4;
        s2 := 'dАа, %    = '||round(-((v(2).lw + v(3).lw)/v(1).wh*100), 1);
        s3 := 'dАp, %     = '||round(-((v(2).lvar + v(3).lvar)/v(1).varh*100), 1);
        il;
      end if;
    end if;
    il;
--    end loop;

    if unnecessary <> 0 then
      delete from calc_protocol where sid = sid_ and ord = unnecessary;
    end if;

  end loop;

END; -- Procedure


Procedure swt(sid_ in number, sdate_ in date) is
  unnecessary   number;
  unnecessaryU  number;
  necessary     number;
  ln            varchar2(200);
  s             varchar2(200);
  ord_          number := 1;
  lvl_          number := 0;

  procedure il is
  begin
    insert into calc_protocol(sid, sdate, ord, lvl, line)
      values(sid_, sdate_, ord_, lvl_, lpad(' ', lvl_*2)||ln);
    ln := ' ';
    ord_ := ord_ + 1;
  end;

BEGIN
  delete from calc_protocol where sid = sid_ and sdate = sdate_;

  lvl_ := 0;
  ln := 'ОТКЛОНЕНИЯ ОТ НОРМАЛЬНОЙ СХЕМЫ ОБЪЕКТОВ ПЛАНШЕТА "';
  select name into s from se_sheets where sid = sid_;
  ln := ln || s || '" НА ';
  select to_char(sdate_, 'dd.mm.yyyy hh24:mi') into s from dual;
  ln := ln || s;
  il;

  necessary := 0;
  for c in (select * from se_objects where sid = sid_ and se_type = 1000 order by name) loop
    il;
    lvl_ := 1;
    unnecessary := ord_;
    ln := c.name; il;
    lvl_ := 2;
    for cc in (select * from rt_objects where rt_type = 950 and parent = c.oid) loop
      unnecessaryU := ord_;
      ln := cc.name; il;
      lvl_ := 3;
      for d in (select distinct decode(s.state, 0, 'Откл.  ', 'Вкл.   ')||o.name name
          from rt_objects o, osm_switchings s, rt_links l where o.parent = cc.oid and l.feeder = o.oid
              and s.oid = l.switch and s.sdate <= sdate_ and ldate > sdate_
              and s.state <>
              (select state from osm_switchings
                where oid = l.switch and sdate = to_date('01.01.2000','dd.mm.yyyy'))) loop
        ln := d.name; il;
        unnecessaryU := 0;
        unnecessary  := 0;
      end loop;
      if unnecessaryU <> 0 then
        delete from calc_protocol where ord = unnecessaryU and sdate = sdate_;
      end if;
    end loop;
    if unnecessary <> 0 then
      delete from calc_protocol where ord = unnecessary and sdate = sdate_;
    else
      necessary := 1;
    end if;
  end loop;

  if necessary = 0 then
    lvl_ := 0;
    delete from calc_protocol where sdate = sdate_;
      ln := 'ОТКЛОНЕНИЙ ОТ НОРМАЛЬНОЙ СХЕМЫ ОБЪЕКТОВ ПЛАНШЕТА "';
    select name into s from se_sheets where sid = sid_;
    ln := ln || s || '" НА '||to_char(sdate_, 'dd.mm.yyyy hh24:mi')|| ' НЕТ!' ;
    il;
  end if;


END;  -- Procedure






END;
/


