-- Start of DDL Script for Package Body RYDA.METERPARAMETER_PG
-- Generated 14.11.2008 08:47:57 from RYDA@sesreg

CREATE OR REPLACE 
PACKAGE BODY meterparameter_pg IS
 ------------------------------------------------------------------------------------------------------------------------
 -- Возвращает основной курсор
 PROCEDURE getparam(an_mid NUMBER, ret_t OUT common_pg.tcur) IS
 BEGIN
  OPEN ret_t FOR
   SELECT mid, ddate, vfilename, BFILE, vnote
     FROM meterparameter
    WHERE mid = NVL(an_mid, 0);
 END;
 ----------------------------------------------------------------
   -- Сохранение
 PROCEDURE upd_p(an_mid NUMBER, ad_date DATE, av_fname VARCHAR2, ab_file IN OUT BLOB, av_note VARCHAR2) IS
 BEGIN
  IF ab_file IS NULL THEN
   UPDATE meterparameter
      SET ddate = ad_date,
          vfilename = av_fname,
          BFILE = EMPTY_BLOB(),
          vnote = av_note
    WHERE mid = an_mid AND ddate = ad_date;
  ELSE
   UPDATE    meterparameter
         SET ddate = ad_date,
             vfilename = av_fname,
             BFILE = ab_file,
             vnote = av_note
       WHERE mid = an_mid AND ddate = ad_date
   RETURNING BFILE
        INTO ab_file;
  END IF;
  IF SQL%ROWCOUNT = 0 THEN
   INSERT INTO meterparameter
               (mid, ddate, vfilename, BFILE, vnote)
        VALUES (an_mid, ad_date, av_fname, EMPTY_BLOB(), av_note)
     RETURNING BFILE
          INTO ab_file;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'METERPARAMETER_PG.upd_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ----------------------------------------------------------------
    -- Удаление
 PROCEDURE del_p(an_mid NUMBER, ad_date DATE) IS
 BEGIN
  DELETE FROM meterparameter
        WHERE mid = an_mid AND ddate = ad_date;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'METERPARAMETER_PG.del_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;
----------------------------------------------------------------
END;
/


