-- Start of DDL Script for Package Body RYDA.MONITOR_METERS_PG
-- Generated 14.11.2008 08:47:57 from RYDA@sesreg

CREATE OR REPLACE 
PACKAGE BODY monitor_meters_pg IS
------------------------------------------------------------------------
-- пакет для работы с монитором показаний
-- 15.07.2008 Кондаков А.Г.
------------------------------------------------------------------------
 PROCEDURE get_GraphVspom(an_mid NUMBER, an_ttype NUMBER, acur_t OUT common_pg.tcur) IS -- получение имен при построении графика (TfmMonitorMeters->oqGraphVspom)
 BEGIN
  IF (an_ttype=2) THEN
    OPEN acur_t FOR
        SELECT NAME FROM GROUPS WHERE gid=an_mid;
  ELSE
    OPEN acur_t FOR
        SELECT NAME FROM points WHERE mid=an_mid;
  END IF;
 END;
--------------------------------------------------------------------------------------
 PROCEDURE get_SysDate(acur_t OUT common_pg.tcur) IS -- выполнялась в TfmMonitorMeters::TfmMonitorMeter
 BEGIN
   OPEN acur_t FOR
        SELECT to_char(sysdate,'dd.mm.yyyy hh24:mi') day1, to_char(sysdate-1,'dd.mm.yyyy hh24:mi') day2 FROM dual;
 END;
--------------------------------------------------------------------------------------
 PROCEDURE get_GraphPointsList(an_flag NUMBER, an_mid NUMBER, acur_t OUT common_pg.tcur) IS
 -- получить список точек, для которых строим график, в TfmMonitorMeters::GetSqlText
  lv_sql    VARCHAR2(4000);
 BEGIN
  IF (an_flag=0) THEN
        RETURN;
  ELSIF (an_flag=1) THEN
        lv_sql := 'select mid from (select * from points where cod=0) where ptype is not null
                   CONNECT BY PRIOR mid=parent START WITH parent=' || an_mid;
  ELSIF (an_flag=2) THEN
        lv_sql := 'select mid from groups where mid is not null
                   CONNECT BY PRIOR gid=parent START WITH parent=' || an_mid;
  ELSIF (an_flag=3) THEN
        lv_sql := 'select p.mid from CHANPOINT c,POINTS p
                   WHERE c.mid=p.mid AND cid IN (SELECT  c.CID FROM POINTS p, CHANNELS c
                   WHERE p.MID=c.CID(+) AND nvl(nkind,0)<>1  AND c.cid IS NOT NULL
                   CONNECT BY PRIOR p.mid=p.PARENT START WITH p.parent=' || an_mid || ') ';
  ELSIF (an_flag=4) THEN
        lv_sql := 'select p.mid from CHANPOINT c,POINTS p  where c.mid=p.mid and cid =' || an_mid;

  ELSIF (an_flag=5) THEN
        lv_sql := 'select mid from points where ptype=1 connect by prior mid=parent
                                       START WITH parent=' || an_mid;
  ELSIF (an_flag=6) THEN
        lv_sql := 'select mid from groups where mid is not null connect by prior gid=parent
                                     START WITH parent=' || an_mid;
  ELSIF (an_flag=7) THEN
        lv_sql := 'select mid from groups where gid=' || an_mid;
  ELSE
        RETURN;
  END IF;
  OPEN acur_t FOR lv_sql;
 END;
--------------------------------------------------------------------------------------
 PROCEDURE get_ShutOff_PU(at_nodes common_pg.tt_number, av_from VARCHAR2, av_to VARCHAR2, an_mid NUMBER, acur_t OUT common_pg.tcur) IS
 -- построение графика Отключение ПУ (TfmMonitorMeters::Graph)
  lv_sql    VARCHAR(4000);
  v_nodes    VARCHAR2(4000);
 BEGIN
  v_nodes := monitor_meters_pg.get_v_nodes(an_mid,at_nodes);
  IF (length(v_nodes) <> 0) THEN
    v_nodes := ' mid IN (' ||v_nodes|| ') AND ';
  END IF;
  OPEN acur_t FOR 'select date_time, decode(state_cod,1010,0,1) st from journal where state_cod in (1010,-1010)
                   AND ' || v_Nodes || ' date_time>=to_date(:p_from,''dd.mm.yyyy hh24:mi'')
                   AND date_time<=to_date(:p_to,''dd.mm.yyyy hh24:mi'') ORDER BY date_time'
                  using av_from, av_to;
 END;
--------------------------------------------------------------------------------------
 PROCEDURE get_CntPossPoints(an_flag NUMBER, av_step VARCHAR2, av_from VARCHAR2, av_to VARCHAR2, acur_t OUT common_pg.tcur) IS
 --вычисляется количество возможных точек (TfmMonitorMeters::Graph)
 BEGIN
  IF (an_flag=1) THEN
        OPEN acur_t FOR 'select decode( :av_step,0,0,trunc(cnt_m*24*60/ :av_step)+1) cnt
                  FROM(SELECT to_date(:av_to, '' dd.mm.yyyy hh24:mi '' )
                  -to_date(:av_from, '' dd.mm.yyyy hh24:mi '' ) cnt_m FROM dual)'
                  using av_step, av_step, av_to, av_from;
  ELSIF (an_flag=2) THEN
        OPEN acur_t FOR 'select trunc(to_date(:av_to,''dd.mm.yyyy hh24:mi'')) -
                  trunc(to_date(:av_from,''dd.mm.yyyy hh24:mi''))+1 cnt FROM dual'
                  using av_to, av_from;
  ELSIF (an_flag=3) THEN
        OPEN acur_t FOR 'select trunc(MONTHS_BETWEEN(to_date(:av_to,''dd.mm.yyyy hh24:mi''),
                  to_date(:av_from,''dd.mm.yyyy hh24:mi'')))+1 cnt FROM dual'
                  using av_to, av_from;
  ELSE
        RETURN;
  END IF;
 END;
--------------------------------------------------------------------------------------
 PROCEDURE get_GraphHistor(an_flag NUMBER, at_nodes common_pg.tt_number, av_from VARCHAR2, av_to VARCHAR2, an_table NUMBER, an_mid NUMBER, acur_t OUT common_pg.tcur) IS
 -- рисуем историю наличия связи (TfmMonitorMeters::GraphIstoir)
  v_nodes    VARCHAR2(4000);
 BEGIN
  v_nodes := monitor_meters_pg.get_v_nodes(an_mid,at_nodes);
  IF (length(v_nodes) <> 0) THEN
    v_nodes := ' a.mid IN (' ||v_nodes|| ') AND ';
  END IF;
  IF (an_flag=1) THEN
        OPEN acur_t FOR 'select distinct p.mid from CHANPOINT a,points p
                         WHERE '||v_nodes||' p.mid=a.cid ';
  ELSIF (an_flag=2) THEN
        OPEN acur_t FOR 'SELECT a.date_time, decode(a.state_cod,0,1,0) st, d.VEVENTTEXT||a.state_descr state_descr FROM journal a,METEREVENTSDICT d
                         WHERE a.nevent=d.nevent(+) and  a.state_cod IN (0,1,2,6) AND '||v_nodes||
                         'a.date_time>=to_date(:meFrom,''dd.mm.yyyy hh24:mi'')
                         AND a.date_time<=to_date(:meTo,''dd.mm.yyyy hh24:mi'')
                         ORDER BY a.date_time'
                        using av_from, av_to;
  ELSE
        RETURN;
  END IF;
 END;
