 PROCEDURE get_IsNodeProp(an_flag NUMBER, av_from VARCHAR2,
                        av_to VARCHAR2, av_step VARCHAR2, acur_t OUT common_pg.tcur) IS
--есть ли пропуски в показаниях (TfmMonitorMeters::IsNodeProp)
 BEGIN
  IF (an_flag=0) THEN
        OPEN acur_t FOR 'select decode(' ||av_step|| ',0,0,trunc(cnt_m*24*60/' ||av_step|| ')) cnt
                         FROM(SELECT to_date(:meTo,''dd.mm.yyyy hh24:mi'')-to_date(:meFrom,''dd.mm.yyyy hh24:mi'') cnt_m FROM dual)'
                        using av_to, av_from;
  ELSIF (an_flag=1) THEN
        OPEN acur_t FOR 'select trunc(to_date(:meTo,''dd.mm.yyyy hh24:mi'')) - trunc(to_date(:meFrom,''dd.mm.yyyy hh24:mi''))+1 cnt
                         FROM dual'
                        using av_to, av_from;
  ELSIF (an_flag=2) THEN
        OPEN acur_t FOR 'select trunc(MONTHS_BETWEEN(to_date(:meTo,''dd.mm.yyyy hh24:mi''),to_date(:meFrom,''dd.mm.yyyy hh24:mi'')))+1 cnt
                         FROM dual'
                        using av_to, av_from;
  ELSIF (an_flag=3) THEN
