 PROCEDURE get_30817_name_p(an_maket NUMBER, ad_date DATE, av_name OUT common_pg.tt_varchar2) IS
 BEGIN
  FOR lc IN (SELECT   vname
                 FROM maketgroups
                WHERE nmaket = an_maket
             ORDER BY vname) LOOP
   av_name(av_name.COUNT + 1) := lc.vname;
  END LOOP;
 END;
 ------------------------------------------------------------------------------------------------------------------------
 --Для монитора отправленных 30817 возвращает данные
 PROCEDURE get_30817_data_p(
  an_maket     NUMBER,
  ad_date      DATE,
  an_1     OUT common_pg.tt_number,
  an_2     OUT common_pg.tt_number,
  an_3     OUT common_pg.tt_number,
  an_4     OUT common_pg.tt_number,
  an_5     OUT common_pg.tt_number,
  an_6     OUT common_pg.tt_number,
  an_7     OUT common_pg.tt_number,
  an_8     OUT common_pg.tt_number,
  an_9     OUT common_pg.tt_number,
  an_10    OUT common_pg.tt_number,
  an_11    OUT common_pg.tt_number,
  an_12    OUT common_pg.tt_number,
  an_13    OUT common_pg.tt_number,
  an_14    OUT common_pg.tt_number,
  an_15    OUT common_pg.tt_number,
  an_16    OUT common_pg.tt_number,
  an_17    OUT common_pg.tt_number,
  an_18    OUT common_pg.tt_number,
  an_19    OUT common_pg.tt_number,
  an_20    OUT common_pg.tt_number,
  an_21    OUT common_pg.tt_number,
  an_22    OUT common_pg.tt_number,
  an_23    OUT common_pg.tt_number,
  an_24    OUT common_pg.tt_number,
  an_25    OUT common_pg.tt_number,
  an_26    OUT common_pg.tt_number) IS
  cv_sep CONSTANT VARCHAR(1)            := ':';
  i               NUMBER                DEFAULT 1;
  lt_file         common_pg.tt_varchar2;
  lv_str          VARCHAR2(4000);
  lv_maket        VARCHAR2(256);
  lv_fname        VARCHAR2(256);
  ln_div          NUMBER; --Делитель (Используется при формировании макета в кВт*ч)
 BEGIN
  SELECT MAX(vname), DECODE(util_pg.get_param(MAX(vparam), 1), '1', 1000, 1)
    INTO lv_maket, ln_div
    FROM makets
   WHERE nmaket = an_maket;
  SELECT MAX(f.vfile)
    INTO lv_fname
    FROM deportfiles f, deportation d
   WHERE f.ddate = TRUNC(ad_date) AND f.ndeportation = d.ndeportation(+) AND d.nmaket = an_maket;
  IF lv_fname IS NULL THEN
   raise_application_error(
    -20002, 'monitor_pg.get_30817_data_p: За ' || TO_CHAR(ad_date, 'dd.mm.yyyy') || ' макет ''' || lv_maket ||
            ''' сформирован не был.');
  END IF;
  lt_file := file_pg.readfile_f(lv_fname);
  FOR lc IN (SELECT   '(' || vcode || ')' vcode
                 FROM maketgroups
                WHERE nmaket = an_maket
             ORDER BY vname) LOOP
   an_1(i) := NULL;
   an_2(i) := NULL;
   an_3(i) := NULL;
   an_4(i) := NULL;
   an_5(i) := NULL;
   an_6(i) := NULL;
   an_7(i) := NULL;
   an_8(i) := NULL;
   an_9(i) := NULL;
   an_10(i) := NULL;
   an_11(i) := NULL;
   an_12(i) := NULL;
   an_13(i) := NULL;
   an_14(i) := NULL;
   an_15(i) := NULL;
   an_16(i) := NULL;
   an_17(i) := NULL;
   an_18(i) := NULL;
   an_19(i) := NULL;
   an_12(i) := NULL;
   an_21(i) := NULL;
   an_22(i) := NULL;
   an_23(i) := NULL;
   an_24(i) := NULL;
   an_25(i) := NULL;
   an_26(i) := NULL;
   FOR j IN 2 .. lt_file.COUNT LOOP
    IF util_pg.get_param(lt_file(j), 1, cv_sep) = lc.vcode THEN
     lv_str := lt_file(j);
     an_1(i) := util_pg.get_param(lv_str, 2, cv_sep) / ln_div;
     an_2(i) := util_pg.get_param(lv_str, 3, cv_sep) / ln_div;
     an_3(i) := util_pg.get_param(lv_str, 4, cv_sep) / ln_div;
     an_4(i) := util_pg.get_param(lv_str, 5, cv_sep) / ln_div;
     an_5(i) := util_pg.get_param(lv_str, 6, cv_sep) / ln_div;
     an_6(i) := util_pg.get_param(lv_str, 7, cv_sep) / ln_div;
     an_7(i) := util_pg.get_param(lv_str, 8, cv_sep) / ln_div;
     an_8(i) := util_pg.get_param(lv_str, 9, cv_sep) / ln_div;
     an_9(i) := util_pg.get_param(lv_str, 10, cv_sep) / ln_div;
     an_10(i) := util_pg.get_param(lv_str, 11, cv_sep) / ln_div;
     an_11(i) := util_pg.get_param(lv_str, 12, cv_sep) / ln_div;
     an_12(i) := util_pg.get_param(lv_str, 13, cv_sep) / ln_div;
     an_13(i) := util_pg.get_param(lv_str, 14, cv_sep) / ln_div;
     an_14(i) := util_pg.get_param(lv_str, 15, cv_sep) / ln_div;
     an_15(i) := util_pg.get_param(lv_str, 16, cv_sep) / ln_div;
     an_16(i) := util_pg.get_param(lv_str, 17, cv_sep) / ln_div;
     an_17(i) := util_pg.get_param(lv_str, 18, cv_sep) / ln_div;
     an_18(i) := util_pg.get_param(lv_str, 19, cv_sep) / ln_div;
     an_19(i) := util_pg.get_param(lv_str, 20, cv_sep) / ln_div;
     an_12(i) := util_pg.get_param(lv_str, 21, cv_sep) / ln_div;
     an_21(i) := util_pg.get_param(lv_str, 22, cv_sep) / ln_div;
     an_22(i) := util_pg.get_param(lv_str, 23, cv_sep) / ln_div;
     an_23(i) := util_pg.get_param(lv_str, 24, cv_sep) / ln_div;
     an_24(i) := util_pg.get_param(lv_str, 25, cv_sep) / ln_div;
     an_25(i) := util_pg.get_param(lv_str, 26, cv_sep) / ln_div;
     an_26(i) := util_pg.get_param(lv_str, 27, cv_sep) / ln_div;
     EXIT;
    END IF;
   END LOOP;
   i := i + 1;
  END LOOP;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'monitor_pg.get_30817_data_p:' || CHR(10) || SQLERRM(SQLCODE));
 END;
------------------------------------------------------------------------------------------------------------------------
END; -- Package Body monitor_pg
/


