-- Start of DDL Script for Package Body RYDA.MONITORING_PG
-- Generated 14.11.2008 08:47:57 from RYDA@sesreg

CREATE OR REPLACE 
PACKAGE BODY monitoring_pg   -- пакет мониторинга системы
                             -- дата создания 20.02.2004 (Коваленко А.С.)
                           ------------------------------------------------------------------------------------------------------------------------
                           IS
 gn_task_code NUMBER DEFAULT 620;
 -- Проверяет по всем точкам данной группы произведен опрос на установленную дату или нет
 -- Возвращает 0 если данные есть, иначе - если нет

 -- an_id - ид точки или группы

 -- если ad_control_date = NULL, то дата контроля берется с таблици feeders (ncommcontrol,ntechcontrol)

    -- an_data_control - тип контролируемых данных
 -- 1 - profile
 -- 2 - halfhour
 -- 3 - bill
 -- 4 - months

 -- an_control_type - тип контроля 0 - коммерческий 1 - технический

 -- an_table имя таблицы с которой берутся точки 0 - points 1 - groups

 -- an_flagTimeControl если 1 то реагируем на временные рамки при проверке 0 - нет
 FUNCTION get_group_point_status_f(
  an_id              NUMBER,
  ad_control_date    DATE,
  an_data_control    NUMBER,
  an_control_type    NUMBER,
  an_table           NUMBER,
  an_flagtimecontrol NUMBER)
  RETURN NUMBER IS
  ln_ret          NUMBER;
  lv_sql          VARCHAR2(2000);
  lv_datafield    VARCHAR2(100);
  ld_control_date DATE;
 BEGIN
  IF an_data_control = 1 THEN
   lv_datafield := 'profile';
  ELSIF an_data_control = 2 THEN
   lv_datafield := 'util_pg.to_localtime(halfhour)';
  ELSIF an_data_control = 3 THEN
   lv_datafield := 'bill';
  ELSIF an_data_control = 4 THEN
   lv_datafield := 'months';
  END IF;
  IF an_table = 1 THEN
   lv_sql := 'SELECT COUNT(f.mid) ' || 'FROM   feeders f, last_save ls ' || 'WHERE f.mid IN (SELECT     mid ' ||
             '                      FROM GROUPS ' || '                     WHERE mid IS NOT NULL ' ||
             '                CONNECT BY PARENT = PRIOR gid ' || '                START WITH gid = ' || an_id ||
             ' ) AND ls.mid = f.mid ';
  ELSE
   lv_sql := 'SELECT COUNT(f.mid) ' || 'FROM   feeders f, last_save ls ' || 'WHERE f.mid IN (SELECT     mid ' ||
             '                      FROM POINTS ' || '                     WHERE ind = 3 ' ||
             '                CONNECT BY PARENT = PRIOR mid ' || '                START WITH mid = ' || an_id ||
             ' ) AND ls.mid = f.mid ';
  END IF;
  IF ad_control_date IS NULL THEN
   IF an_control_type = 0 THEN
    lv_sql := lv_sql || ' AND DECODE(ncommcontrol,null,SYSDATE,' || lv_datafield || ') < TRUNC (SYSDATE) ';
    IF an_flagtimecontrol = 1 THEN
     lv_sql := lv_sql || ' AND (TRUNC(SYSDATE) + ncommcontrol/24/60 < SYSDATE ' ||
               ' AND TRUNC(SYSDATE) + ncommcontrol/24/60 > SYSDATE-1/24) ';
    END IF;
   END IF;
   IF an_control_type = 1 THEN
    lv_sql := lv_sql || ' AND ' || lv_datafield || ' + ntechcontrol / 24 / 60 < SYSDATE ';
    IF an_flagtimecontrol = 1 THEN
     lv_sql := lv_sql || ' AND nvl(ddataabsencec,SYSDATE-100) + ntechcontrol / 24 / 60 < SYSDATE ';
    END IF;
   END IF;
  ELSE
   lv_sql := lv_sql || ' AND ' || lv_datafield || ' < to_date(''' || TO_CHAR(ad_control_date, 'dd.mm.yyyy hh24:mi:ss') ||
             ''',''dd.mm.yyyy hh24:mi:ss'')';
  END IF;
  EXECUTE IMMEDIATE lv_sql
   INTO ln_ret;
  RETURN ln_ret;
 END;
 ------------------------------------------------------------------------------------------------------------------------
 -- Возвращает >0 если по каким то точкам стоит флажек отсутствия данных
 -- an_role_id - Ид роли для которой производится проверка
 -- an_test_type - Тип проверки 0 - комерческие данные 1 - технические
 FUNCTION get_role_beep_status_f(an_role_id NUMBER, an_test_type NUMBER)
  RETURN NUMBER IS
  ln_ret       NUMBER;
  lv_sql       VARCHAR2(500);
  lv_datafield VARCHAR2(20);
 BEGIN
  SELECT DECODE(an_test_type, 0, 'ndataabsencec', 'ndataabsencect')
    INTO lv_datafield
    FROM DUAL;
  lv_sql :=
    'SELECT count(f.mid) from feeders f, (SELECT mid FROM GROUPS WHERE mid IS NOT NULL CONNECT BY PARENT = PRIOR gid ' ||
    ' START WITH gid IN (select gid from role_groups WHERE role_id = ' || an_role_id || ')) m ' ||
    ' where m.mid = f.mid and ' || lv_datafield || ' > 0';
  EXECUTE IMMEDIATE lv_sql
   INTO ln_ret;
  RETURN ln_ret;
 END;
 ------------------------------------------------------------------------------------------------------------------------
 -- Квитирует отсутсвие данных
 -- an_test_type - Тип проверки 0 - комерческие данные 1 - технические
 PROCEDURE receipt_data_absence_p(an_role_id NUMBER, an_test_type NUMBER) IS
  CURSOR cr_group IS
   SELECT util_pg.node_path_f(gid, 'groups', 'gid', 'parent') ||
          DECODE(an_test_type, 0, ' Комерческий контроль', ' Технический контроль') g
     FROM role_groups
    WHERE role_id = an_role_id;
  lv_sql       VARCHAR2(500);
  lv_datafield VARCHAR2(20);
 BEGIN
  SELECT DECODE(an_test_type, 0, 'ndataabsencec', 'ndataabsencect')
    INTO lv_datafield
    FROM DUAL;
  lv_sql := 'update feeders set ' || lv_datafield || ' = 0 ' ||
            'where mid in (SELECT mid FROM GROUPS WHERE mid IS NOT NULL CONNECT BY PARENT = PRIOR gid ' ||
            ' START WITH gid IN (select gid from role_groups WHERE role_id = ' || an_role_id || '))';
  EXECUTE IMMEDIATE lv_sql;
  FOR cr_g IN cr_group LOOP
   admin_pg.fiscal_p(gn_task_code, 2, 'Квитирование отсутствия данных по группе ' || cr_g.g);
  END LOOP;
 END;
END;
/


