CREATE OR REPLACE 
PACKAGE BODY operatingday_pg IS
 ------------------------------------------------------------------------------------------------------------------------
 gn_task_code NUMBER DEFAULT 46;
 ------------------------------------------------------------------------------------------------------------------------
   -- пакет по задаче ввод типа разносок суточных расходов
   -- дата создания 29/11/2007 Сечин А.А.
 ------------------------------------------------------------------------------------------------------------------------
  -- Возвращает основной курсор
 PROCEDURE getinfo(an_mid NUMBER, ad_from DATE, ad_till DATE, an_sort NUMBER, ret_t OUT common_pg.tcur) IS
  ln_mid               NUMBER         DEFAULT NVL(an_mid, 0);
  lv_sql               VARCHAR2(4000);
  cn_colcount CONSTANT NUMBER         := 6;
 BEGIN
  lv_sql :=
    'select util_pg.get_pointname(o.nowner,0,0) owname,o.dstart,util_pg.get_pointname(o.mid,0,0) pname,g.name gname,' ||
    'o.dregime,o.nshift,' || ln_mid || ' mid, o.nowner owmid,o.mid pmid,g.gid ' ||
    'from OPERATINGDAY o,(select * from points connect by prior parent =mid start with mid=' || ln_mid ||
    ') ow, points p,groups g where o.nowner=ow.mid and o.mid=p.mid(+) and o.gid=g.gid(+)';
  --Ограничение по дате
  IF ad_from IS NOT NULL THEN
   lv_sql :=
       lv_sql || ' and o.dstart>=to_date(''' || TO_CHAR(ad_from, 'dd.mm.yyyy hh24:mi:ss') || ''',''dd.mm.yyyy hh24:mi:ss'')';
  END IF;
  IF ad_till IS NOT NULL THEN
   lv_sql :=
       lv_sql || ' and o.dstart<=to_date(''' || TO_CHAR(ad_till, 'dd.mm.yyyy hh24:mi:ss') || ''',''dd.mm.yyyy hh24:mi:ss'')';
  END IF;
  --Сортировка
  lv_sql := lv_sql || ' ORDER BY ';
  IF  ABS(an_sort) > 0 AND ABS(an_sort) <= cn_colcount THEN
   lv_sql := lv_sql || ABS(an_sort);
   IF an_sort < 0 THEN
    lv_sql := lv_sql || ' desc';
   END IF;
   lv_sql := lv_sql || ',';
  END IF;
  lv_sql := lv_sql || ' ' || (cn_colcount + 1) || ' desc,2 desc';
  OPEN ret_t FOR lv_sql;
 END;
 ----------------------------------------------------------------
    -- Сохранение
 PROCEDURE upd_p(an_owner NUMBER, ad_start DATE, an_mid NUMBER, an_gid NUMBER, ad_regime DATE, an_shift NUMBER) IS
  ln_type NUMBER DEFAULT 2;
 BEGIN
  UPDATE operatingday
     SET dstart = ad_start,
         mid = an_mid,
         gid = an_gid,
         dregime = ad_regime,
         nshift = NVL(an_shift, 0)
   WHERE nowner = an_owner AND dstart = ad_start;
  IF SQL%ROWCOUNT = 0 THEN
   ln_type := 1;
   INSERT INTO operatingday
               (nowner, dstart, mid, gid, dregime, nshift)
        VALUES (an_owner, ad_start, an_mid, an_gid, ad_regime, an_shift);
  END IF;
  admin_pg.fiscal_p(
   gn_task_code, ln_type, 'Произведено изменение правил разноски на ГН для ' ||
                          util_pg.node_path_f(an_owner, 'points', 'mid', 'parent') || ' с ' || TO_CHAR(
                                                                                                ad_start, 'dd.mm.yyyy'));
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'operatingday_pg.upd_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ----------------------------------------------------------------
     -- Удаление
 PROCEDURE del_p(an_owner NUMBER, ad_start DATE) IS
 BEGIN
  DELETE FROM operatingday
        WHERE nowner = an_owner AND dstart = ad_start;
  IF SQL%ROWCOUNT > 0 THEN
   admin_pg.fiscal_p(
    gn_task_code, 3, 'Произведено удаление правила разноски на ГН для ' ||
                     util_pg.node_path_f(an_owner, 'points', 'mid', 'parent') || ' с ' || TO_CHAR(
                                                                                           ad_start, 'dd.mm.yyyy'));
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'operatingday_pg.del_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;
-------------------------------------------------------------------------------------------
END; -- Package Body switchts_pg
/


-- End of DDL Script for Package Body RYDA.OPERATINGDAY_PG

-- Start of DDL Script for Package Body RYDA.OPERSCAN_PG
-- Generated 14.11.2008 08:47:57 from RYDA@sesreg

CREATE OR REPLACE 
PACKAGE BODY operscan_pg IS
 ------------------------------------------------------------------------------------------------------------------------
    -- пакет работы со схемами оперативного опроса и оперативным опросом
    -- дата создания 01/02/2004 (Сечин А.А.)
 gn_task_code NUMBER;
 ------------------------------------------------------------------------------------------------------------------------
 PROCEDURE ins_p(av_name VARCHAR2, --название схемы
                                  at_cid common_pg.tt_number,
                                            an_operscanschemas OUT NUMBER) IS
  ln_ret NUMBER;
 BEGIN
  SAVEPOINT operscan_ins;
  admin_pg.fiscal_p(gn_task_code, 1, 'Добавлена схема оперативного опроса ' || av_name);
  SELECT roles_seq.NEXTVAL
    INTO ln_ret
    FROM DUAL;
  INSERT INTO operscanschemas
              (noperscanschemas, vname)
       VALUES (ln_ret, av_name);
  IF  at_cid.COUNT > 0 AND at_cid(1) <> 0 THEN
   FOR i IN 1 .. at_cid.COUNT LOOP
    INSERT INTO schemchannels
                (noperscanschemas, cid)
         VALUES (ln_ret, at_cid(i));
    admin_pg.fiscal_p(
     gn_task_code, 1, ' В схему оперативного опроса ' || av_name || ' добавлен канал ' ||
                      util_pg.node_path_f(at_cid(i), 'points', 'mid', 'parent'));
   END LOOP;
  END IF;
  an_operscanschemas := ln_ret;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT operscan_ins;
   raise_application_error(
    -20001, 'operscan_pg.ins_p: Ошибка вставки схемы оперативного опроса. ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ------------------------------------------------------------------------------------------------------------------------
 PROCEDURE upd_p(an_operscanschemas NUMBER, --Ид схемы
                                           av_name VARCHAR2, --название схемы
                                                            at_cid common_pg.tt_number) IS
  lv_name VARCHAR2(200);
 BEGIN
  SAVEPOINT operscan_upd;
  SELECT vname
    INTO lv_name
    FROM operscanschemas
   WHERE noperscanschemas = an_operscanschemas;
  IF lv_name <> av_name THEN
   lv_name := lv_name || ' - ' || av_name;
  END IF;
  admin_pg.fiscal_p(gn_task_code, 2, ' Изменены параметры схемы оперативного опроса ' || lv_name);
  lv_name := av_name;
  UPDATE operscanschemas
     SET vname = av_name
   WHERE noperscanschemas = an_operscanschemas;
  DELETE FROM schemchannels
        WHERE noperscanschemas = an_operscanschemas;
  IF  at_cid.COUNT > 0 AND at_cid(1) <> 0 THEN
   FOR i IN 1 .. at_cid.COUNT LOOP
    INSERT INTO schemchannels
                (noperscanschemas, cid)
         VALUES (an_operscanschemas, at_cid(i));
    admin_pg.fiscal_p(
     gn_task_code, 1, ' В схему оперативного опроса ' || lv_name || ' добавлен канал ' ||
                      util_pg.node_path_f(at_cid(i), 'points', 'mid', 'parent'));
   END LOOP;
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK TO SAVEPOINT operscan_upd;
   raise_application_error(
    -20001, 'operscan_pg.upd_p: Ошибка обновления схемы оперативного опроса. ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ------------------------------------------------------------------------------------------------------------------------
 PROCEDURE del_p(an_operscanschemas NUMBER --Ид схемы
                                          ) IS
  lv_name VARCHAR2(200);
 BEGIN
  SELECT vname
    INTO lv_name
    FROM operscanschemas
   WHERE noperscanschemas = an_operscanschemas;
  admin_pg.fiscal_p(gn_task_code, 3, ' Удалена схема оперативного опроса ' || lv_name);
  DELETE FROM operscanschemas
        WHERE noperscanschemas = an_operscanschemas;
 END;
 ------------------------------------------------------------------------------------------------------------------------
 PROCEDURE active_p(an_cid NUMBER, --Ид канала
                                  ad_end DATE, --дата окончания
                                              an_cycle_tout NUMBER) IS
  ln_protocol NUMBER;
 BEGIN
  SELECT MAX(protocol_id)
    INTO ln_protocol
    FROM channels
   WHERE cid = an_cid;
  IF comsrvdisp_pg.is_client_canal(ln_protocol) = 0 THEN
   raise_application_error(-20001, 'Запуск оперативного опроса для канала серверного типа запрещен.');
  END IF;
  admin_pg.fiscal_p(
   gn_task_code, 2, 'Запущен оперативный опрос по каналу ' || util_pg.node_path_f(an_cid, 'points', 'mid', 'parent') ||
                    ' Дата окончания ' || TO_CHAR(SYSDATE, 'dd.mm.yyyy ') || TO_CHAR(ad_end, 'hh24:mi:ss') ||
                    ' Период опроса ' || an_cycle_tout || ' сек.');
  --Для незапущенных каналов nvl(nkind,0) <> 100;
  UPDATE channels
     SET cycle_tout2 = DECODE(NVL(nkind, 0), 0, cycle_tout, cycle_tout2),
         blocking2 = DECODE(NVL(nkind, 0), 0, blocking, blocking2),
         dstart2 = DECODE(NVL(nkind, 0), 0, dstart, dstart2),
         dend2 = DECODE(NVL(nkind, 0), 0, dend, dend2),
         nparent2 = DECODE(NVL(nkind, 0), 0, nparent, nparent2),
         nnotreadcurr2 = DECODE(NVL(nkind, 0), 0, nnotreadcurr, nnotreadcurr2),
         dstart = SYSDATE,
         dend = ad_end,
         cycle_tout = an_cycle_tout,
         blocking = 0,
         nparent = NULL,
         nnotreadcurr = 0,
         nkind = 100,
         ndelivered = 0,
         vuser = common_pg.username_f
   WHERE cid = an_cid AND NVL(nkind, 0) <> 100;
  --Для запущенных каналов nkind = 100;
  UPDATE channels
     SET dstart = SYSDATE,
         dend = ad_end,
         cycle_tout = an_cycle_tout,
         vuser = common_pg.username_f
   WHERE cid = an_cid AND nkind = 100;
 END;
 ------------------------------------------------------------------------------------------------------------------------
 PROCEDURE deactive_p(an_cid NUMBER --Ид канала
                                   ) IS
 BEGIN
  admin_pg.fiscal_p(
   gn_task_code, 2, 'Остановлен оперативный опрос по каналу ' || util_pg.node_path_f(an_cid, 'points', 'mid', 'parent'));
  UPDATE channels
     SET nkind = 0,
         vuser = NULL,
         cycle_tout = cycle_tout2,
         blocking = blocking2,
         dstart = dstart2,
         dend = dend2,
         nparent = nparent2,
         nnotreadcurr = nnotreadcurr2
   WHERE cid = an_cid AND nkind = 100;
 END;
