CREATE OR REPLACE 
PACKAGE BODY opros_term_pg IS
------------------------------------------------------------------------
-- пакет для работы с терминалом опроса
-- 14.07.2008 Кондаков А.Г.
------------------------------------------------------------------------
 PROCEDURE get_graph (an_mid NUMBER, ad_date_time DATE, acur_t OUT common_pg.tcur) IS   -- при построении графика (TGraphsF->GraphOQry)
 BEGIN
  OPEN acur_t FOR
   SELECT   j.date_time, j.mid, j.state_cod, d.veventtext || j.state_descr state_descr
       FROM journal j, metereventsdict d
      WHERE (j.mid = an_mid) AND j.date_time >= ad_date_time AND j.nevent = d.nevent(+)
   ORDER BY date_time;
 END;

--------------------------------------------------------------------------------------
 PROCEDURE get_lboundgr (an_mid NUMBER, ad_date_time DATE, acur_t OUT common_pg.tcur) IS   -- при построении графика (TGraphsF->LBoundGrOQry)
 BEGIN
  OPEN acur_t FOR
   SELECT   MAX (date_time)
       FROM journal
      WHERE (mid = an_mid) AND (date_time >= ad_date_time)
   ORDER BY date_time;
 END;

--------------------------------------------------------------------------------------
 PROCEDURE get_lboundval (an_mid NUMBER, ad_date_time DATE, acur_t OUT common_pg.tcur) IS   -- при построении графика (TGraphsF->LBoundValOQry)
 BEGIN
  OPEN acur_t FOR
   SELECT j.date_time, j.mid, j.state_cod, d.veventtext || j.state_descr state_descr
     FROM journal j, metereventsdict d
    WHERE j.mid = an_mid AND j.date_time >= ad_date_time AND j.nevent = d.nevent(+);
 END;

--------------------------------------------------------------------------------------
 PROCEDURE get_passgroups (acur_t OUT common_pg.tcur) IS   -- (TGraphsF->PassGroupsOQry)
 BEGIN
  OPEN acur_t FOR
   SELECT   p1.mid, 0, MAX (p1.NAME) NAME
       FROM last_save l, points p1, points p2, channels c
      WHERE c.cid = p2.mid(+) AND p2.mid = l.mid(+) AND p2.PARENT = p1.mid(+)
   GROUP BY p1.mid
   UNION
   SELECT   p1.mid, 1, MAX (p1.NAME) NAME
       FROM points p1, points p2, feeders f
      WHERE util_pg.get_customer_id <> 10 AND f.mid = p2.mid(+) AND p2.PARENT = p1.mid(+)
   GROUP BY p1.mid
   ORDER BY 2, 3;
 END;

--------------------------------------------------------------------------------------
 PROCEDURE get_currt (acur_t OUT common_pg.tcur) IS   -- получение системной даты(TPointsF->CurrTOQry)
 BEGIN
  OPEN acur_t FOR
   SELECT SYSDATE
     FROM DUAL;
 END;

--------------------------------------------------------------------------------------
 PROCEDURE get_points (an_sort NUMBER, acur_t OUT common_pg.tcur) IS   -- получение точек(TPointsF->PointsOQry)
  lv_sql   VARCHAR2 (4000);
 BEGIN
  lv_sql :=
   'SELECT NVL(l.state_cod,200), p1.NAME, p2.NAME,
             decode(util_pg.getparamvalue_f(27),0,l.CLOCK,decode(sign(abs(l.CLOCK)-util_pg.getparamvalue_f(27)),1,util_pg.getparamvalue_f(27)*sign(l.CLOCK),l.CLOCK)) CLOCK,
             l.PROFILE, l.HALFHOUR, l.BILL, l.MONTHS, p1.mid, l.mid, 0,2
           FROM
             last_save l, points p1, points p2, feeders f
           WHERE
             f.mid=p2.mid(+) AND p2.mid = l.mid(+) AND p2.parent = p1.mid(+)	
           UNION ALL
           SELECT
             NVL(l.state_cod,200), p1.NAME, p2.NAME,l.CLOCK, l.PROFILE,
             decode( COMSRVDISP_PG.is_need_canal(c.protocol_id),0,l.HALFHOUR,LUCK),
             decode( COMSRVDISP_PG.is_need_canal(c.protocol_id),0,l.BILL,STATE_DATE),
             decode( COMSRVDISP_PG.is_need_canal(c.protocol_id),0,l.MONTHS,l.FAIL),
             p1.mid, l.mid, decode( c.protocol_id, 2, 1, 3, 1, 2 ),1
           FROM
             last_save l, points p1, points p2, channels c
           WHERE c.cid = p2.mid(+) AND  p2.mid = l.mid(+) AND p2.parent = p1.mid(+)
           ORDER BY ';

  IF ABS (an_sort) > 0 THEN
   lv_sql := lv_sql || ABS (an_sort);

   IF an_sort < 0 THEN
    lv_sql := lv_sql || ' DESC';
   END IF;

   lv_sql := lv_sql || ',';
  END IF;

  lv_sql := lv_sql || ' 1';

  OPEN acur_t FOR lv_sql;
 END;

--------------------------------------------------------------------------------------
 PROCEDURE get_jurn (an_sort NUMBER, an_dlk_mid NUMBER, acur_t OUT common_pg.tcur) IS   -- построение журнала (TJurnalF->JurnOQry)
  lv_sql    VARCHAR2 (4000);
  ln_sort   NUMBER          DEFAULT NVL (an_sort, 0);
 BEGIN
  lv_sql :=
   'SELECT nvl(state_cod,200), j.date_time, d.VEVENTTEXT||j.state_descr state_descr, j.mid, j.vcode 
    FROM journal j,METEREVENTSDICT d 
    WHERE j.mid = ' || NVL (an_dlk_mid, 0) || ' and j.nevent=d.nevent(+) 
    ORDER BY ';

  IF ABS (ln_sort) > 0 THEN
   lv_sql := lv_sql || ABS (ln_sort);

   IF an_sort < 0 THEN
    lv_sql := lv_sql || ' DESC';
   END IF;

   lv_sql := lv_sql || ',';
  END IF;

  lv_sql := lv_sql || ' 1';

  OPEN acur_t FOR lv_sql;
 END;
--------------------------------------------------------------------------------------
END;
/


