-- Generated 14.11.2008 08:47:57 from RYDA@sesreg

CREATE OR REPLACE 
PACKAGE body orderformula_pg AS

FUNCTION order_formula 
RETURN  varchar2 
IS
 fcount NUMBER;
 ShiftCountMax NUMBER;
 ShiftCount NUMBER;
 fshift NUMBER;
BEGIN
 SELECT Count(nid) into fcount from pointformula;

 ShiftCountMax :=fcount*fcount;
 ShiftCount := 0;
 fshift := 1;

 WHILE fshift = 1  LOOP
    fshift := 0;
  FOR i IN (select NID, MID, NORDER from pointformula) LOOP
    
   FOR j IN (select i.NID, i.MID,i.NORDER, NID IdResult, MID Result, NORDER OrderResult from pointformula) LOOP
    
    IF i.NID <> j.IdResult THEN
       FOR v IN (select NID, vparam
                  from formulparams
                   where nid = i.NID
                     --and to_number(util_pg.get_param_rev(vparam, 2, '.'))= j.Result
                      )                        
                            LOOP
                  
          
                  
                           
                              
          IF NVL(i.NORDER,0) <= NVL(j.OrderResult,0) AND (to_number(util_pg.get_param_rev(v.vparam, 2, '.')) =j.Result) THEN
          update pointformula 
           set NORDER  = (select NVL(max(norder),0)+1 from pointformula where nid = j.IdResult)
           where nid = i.NID;
            fshift := 1;
            ShiftCount := ShiftCount +1;
            
           END IF;  
       
       END LOOP;
       
         
     END IF;
     
      
   END LOOP;
 
    IF ShiftCount > ShiftCountMax THEN
      raise_application_error (-20001, 'Error. Cycle process');
    END IF;
   
        
   END LOOP;
   End LOOP;

 update pointformula 
   set NORDER = (select min(NORDER)-1 from pointformula)
    where NORDER is NULL; 
Return ('ok');
  
   
END order_formula;

  

END orderformula_pg;
/


