CREATE OR REPLACE 
PACKAGE BODY parser_pg IS
-----------------------------------------------------------------------------------------------------------------------
 idexpr        NUMBER;   -- Id Expression
 varcount      NUMBER;   -- Count  expression's variables
--   Result NUMBER;         -- Expressions result value
 varname       t;   -- array of expressions variables
 charvarname   CHAR (256);   -- expressions variable
 val           n;   -- array of expressions variables values
 v             NUMBER;   -- expressions variable value
 error         NUMBER;   -- execute error

------------------------------------------------------------------------------------------------------------------------
 FUNCTION newexpression (expr STRING)
  RETURN PLS_INTEGER AS
  LANGUAGE c
  NAME "NewExpression"
  LIBRARY parser
  PARAMETERS (
   expr STRING
  );

-------------------------------------------------------------------------------------------------------------------------
 FUNCTION getnbusedvars (idexpr BINARY_INTEGER)
  RETURN PLS_INTEGER AS
  LANGUAGE c
  NAME "GetNbUsedVars"
  LIBRARY parser
  PARAMETERS (
   idexpr INT
  );

-------------------------------------------------------------------------------------------------------------------------
 FUNCTION getusedvar (idexpr BINARY_INTEGER, j BINARY_INTEGER, varname IN OUT STRING, len BINARY_INTEGER)
  RETURN PLS_INTEGER AS
  LANGUAGE c
  NAME "GetUsedVar"
  LIBRARY parser
  PARAMETERS (
   idexpr INT,
   j INT,
   varname STRING,
   len INT
  );

------------------------------------------------------------------------------------------------------------------------
 FUNCTION setvar (idexpr BINARY_INTEGER, idvar BINARY_INTEGER, varname STRING, val IN OUT DOUBLE PRECISION)
  RETURN PLS_INTEGER AS
  LANGUAGE c
  NAME "SetVar"
  LIBRARY parser
  PARAMETERS (
   idexpr INT,
   idvar INT,
   varname STRING,
   val DOUBLE
  );

------------------------------------------------------------------------------------------------------------------------
 FUNCTION evaluate (idexpr BINARY_INTEGER, RESULT OUT DOUBLE PRECISION)
  RETURN DOUBLE PRECISION AS
  LANGUAGE c
  NAME "Evaluate"
  LIBRARY parser
  PARAMETERS (
   idexpr INT,
   RESULT DOUBLE
  );

------------------------------------------------------------------------------------------------------------------------
 FUNCTION getparsererror
  RETURN PLS_INTEGER AS
  LANGUAGE c
  NAME "GetParserError"
  LIBRARY parser;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION getparsererrortext (an_err PLS_INTEGER DEFAULT NULL)
  RETURN VARCHAR2 IS
  ln_err   PLS_INTEGER DEFAULT NVL (an_err, getparsererror);
 BEGIN
  IF ln_err = 1 THEN
   RETURN 'Неправильный HANDLER экземпляра формулы';
  ELSIF ln_err = 2 THEN
   RETURN 'Ошибка в синтаксисе формулы';
  ELSIF ln_err = 3 THEN
   RETURN 'В формуле использован неизвестный аргумент';
  ELSIF ln_err = 4 THEN
   RETURN 'Неверное значение аргумента';
  ELSIF ln_err = 5 THEN
   RETURN 'Недостаточно памяти';
  END IF;

  RETURN 'Неизвестная ошибка. Код: ' || ln_err;
 END;

---------------------------------------------------------------------------------------------------------------------
 FUNCTION changeexpression (idexpr BINARY_INTEGER, expr STRING)
  RETURN PLS_INTEGER AS
  LANGUAGE c
  NAME "ChangeExpression"
  LIBRARY parser
  PARAMETERS (
   idexpr INT,
   expr STRING
  );

-------------------------------------------------------------------------------------------------------------------------
 FUNCTION deleteexpression (idexpr BINARY_INTEGER)
  RETURN PLS_INTEGER AS
  LANGUAGE c
  NAME "ChangeExpression"
  LIBRARY parser
  PARAMETERS (
   idexpr INT
  );

-------------------------------------------------------------------------------------------------------------------------
 FUNCTION setvars (idexpr BINARY_INTEGER, val IN OUT DOUBLE PRECISION)
  RETURN PLS_INTEGER AS
  LANGUAGE c
  NAME "ChangeExpression"
  LIBRARY parser
  PARAMETERS (
   idexpr INT,
   val DOUBLE
  );

-------------------------------------------------------------------------------------------------------------------------
 FUNCTION parser_proc (expr VARCHAR2, RESULT OUT NUMBER)
  RETURN NUMBER IS
 BEGIN
  idexpr := newexpression (expr);
  varcount := getnbusedvars (idexpr);

  --dbms_output.PUT_LINE (to_char(VarCount));
  FOR j IN 0 .. varcount - 1 LOOP
   varname (j) := ' ';
   error := getusedvar (idexpr, j, varname (j), 256);
  END LOOP;

  FOR i IN 1 .. 10000 LOOP
   --    получить значения параметров формулы
   FOR j IN 0 .. varcount - 1 LOOP
    val (j) := j * 10 + 10;
   END LOOP;

   FOR i IN 0 .. varcount - 1 LOOP
    v := val (i);
    error := setvar (idexpr, i, varname (i), v);
   --  dbms_output.PUT_LINE ('error setvar '||Val(i)||' '||Error);
    -- dbms_output.PUT_LINE (VarName(i)||' '||to_char(Val(i)));
   END LOOP;

   error := evaluate (idexpr, RESULT);
  /*IF Error = 0 THEN
    dbms_output.PUT_LINE (Result||' error '|| Error);
   END IF;*/
  END LOOP;

  RETURN error;
 END;
END;
/


