 --Суточный график потребления активной и реактивной мощности для ЦТ ХЭС (поднимаем график)
 PROCEDURE report5x_p IS
  CURSOR lcur_select(ld_from DATE) IS
   SELECT   TRUNC(
             TO_CHAR(h.date_time - 1 / 86400, 'SSSSS') / 1800) +
            1 dt,
            SUM(
             DECODE(
              g.inverted, 'y', -util_pg.sld(
                                 h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0),
                                 NVL(h.ed * DECODE(g.npartly, 1, 0, 1), 0)),
              util_pg.sld(
               h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(
                                                                  h.ed * DECODE(g.npartly, 1, 0, 1), 0))) *
             DECODE(SIGN(TRUNC(h.date_time) - TO_DATE(NVL(g.nfromperiod, 160501), 'yyyymm')), 1, 1, NULL) *
             DECODE(SIGN((LAST_DAY(TO_DATE(NVL(g.ntillperiod, 299912), 'yyyymm')) + 1) - h.date_time), -1, NULL, 1)) *
            2
              sumer,
            SUM(
             DECODE(
              g.inverted, 'y', -util_pg.sld(h.mid, NVL(h.q1, 0), NVL(h.q3, 0)), util_pg.sld(
                                                                                 h.mid, NVL(h.q1, 0), NVL(h.q3, 0))) *
             DECODE(SIGN(TRUNC(h.date_time) - TO_DATE(NVL(g.nfromperiod, 160501), 'yyyymm')), 1, 1, NULL) *
             DECODE(SIGN((LAST_DAY(TO_DATE(NVL(g.ntillperiod, 299912), 'yyyymm')) + 1) - h.date_time), -1, NULL, 1)) *
            2
              sumqq
       FROM halfhour h, groups g
      WHERE h.mid = g.mid
        AND g.gid IN (SELECT     gid
                            FROM groups
                           WHERE mid IS NOT NULL
                      CONNECT BY PRIOR gid = parent
                      START WITH gid = filereport_pg.gn_group)
        AND h.date_time > ld_from
        AND h.date_time <= filereport_pg.gd_till
   GROUP BY TRUNC(
             TO_CHAR(h.date_time - 1 / 86400, 'SSSSS') / 1800);
  lt_er     common_pg.tt_number;
  lt_qq     common_pg.tt_number;
  lv_time   VARCHAR2(10);
  lv_name   VARCHAR2(2000);
  ln_abill  NUMBER              DEFAULT 0;
  ln_qbill  NUMBER              DEFAULT 0;
  ln_abillm NUMBER              DEFAULT 0;
  ln_qbillm NUMBER              DEFAULT 0;
  ln_amonth NUMBER              DEFAULT 0;
  ln_qmonth NUMBER              DEFAULT 0;
  ln_atmp   NUMBER;
  ln_qtmp   NUMBER;
 BEGIN
  filereport_pg.put_p(
   '    Суточный график потребления активной и реактивной мощности по группе '|| filereport_pg.gv_name);
  filereport_pg.put_p('      за '|| TO_CHAR(filereport_pg.gd_from, 'DD.MM.YYYY') || /*' по ' ||
                      TO_CHAR(filereport_pg.gd_till, 'DD.MM.YYYY') ||*/ '  МВт ');
  filereport_pg.put_p('');
  FOR i IN 1 .. 48 LOOP
   lt_er(i) := 0; --null;
   lt_qq(i) := 0; --null;
  END LOOP;
  FOR lc IN lcur_select(filereport_pg.gd_from) LOOP
   lt_er(lc.dt) := NVL(lc.sumer, 0);
   lt_qq(lc.dt) := NVL(lc.sumqq, 0);
   ln_abill := ln_abill + NVL(lc.sumer, 0) / 2;
   ln_qbill := ln_qbill + NVL(lc.sumqq, 0) / 2;
  END LOOP;
  SELECT SUM(
          DECODE(
           g.inverted, 'y', -util_pg.sld(
                              h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(
                                                                                 h.ed * DECODE(g.npartly, 1, 0, 1), 0)),
           util_pg.sld(
            h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(
                                                               h.ed * DECODE(g.npartly, 1, 0, 1), 0))) *
          DECODE(SIGN(TRUNC(h.date_time) - TO_DATE(NVL(g.nfromperiod, 160501), 'yyyymm')), 1, 1, NULL) *
          DECODE(SIGN((LAST_DAY(TO_DATE(NVL(g.ntillperiod, 299912), 'yyyymm')) + 1) - h.date_time), -1, NULL, 1)) sumer,
         SUM(
          DECODE(
           g.inverted, 'y', -util_pg.sld(h.mid, NVL(h.q1, 0), NVL(h.q3, 0)), util_pg.sld(
                                                                              h.mid, NVL(h.q1, 0), NVL(h.q3, 0))) *
          DECODE(SIGN(TRUNC(h.date_time) - TO_DATE(NVL(g.nfromperiod, 160501), 'yyyymm')), 1, 1, NULL) *
          DECODE(SIGN((LAST_DAY(TO_DATE(NVL(g.ntillperiod, 299912), 'yyyymm')) + 1) - h.date_time), -1, NULL, 1)) sumqq
    INTO ln_abillm,
         ln_qbillm
    FROM bill h, groups g
   WHERE h.mid = g.mid
     AND g.gid IN (SELECT     gid
                         FROM groups
                        WHERE mid IS NOT NULL
                   CONNECT BY PRIOR gid = parent
                   START WITH gid = filereport_pg.gn_group)
     AND h.date_time > filereport_pg.gd_from
     AND h.date_time <= filereport_pg.gd_till;
  SELECT SUM(
          DECODE(
           g.inverted, 'y', -util_pg.sld(
                              h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(
                                                                                 h.ed * DECODE(g.npartly, 1, 0, 1), 0)),
           util_pg.sld(
            h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(
                                                               h.ed * DECODE(g.npartly, 1, 0, 1), 0))) *
          DECODE(SIGN(TRUNC(h.date_time) - TO_DATE(NVL(g.nfromperiod, 160501), 'yyyymm')), 1, 1, NULL) *
          DECODE(SIGN((LAST_DAY(TO_DATE(NVL(g.ntillperiod, 299912), 'yyyymm')) + 1) - h.date_time), -1, NULL, 1)) sumer,
         SUM(
          DECODE(
           g.inverted, 'y', -util_pg.sld(h.mid, NVL(h.q1, 0), NVL(h.q3, 0)), util_pg.sld(
                                                                              h.mid, NVL(h.q1, 0), NVL(h.q3, 0))) *
          DECODE(SIGN(TRUNC(h.date_time) - TO_DATE(NVL(g.nfromperiod, 160501), 'yyyymm')), 1, 1, NULL) *
          DECODE(SIGN((LAST_DAY(TO_DATE(NVL(g.ntillperiod, 299912), 'yyyymm')) + 1) - h.date_time), -1, NULL, 1)) sumqq
    INTO ln_amonth,
         ln_qmonth
    FROM bill h, groups g
   WHERE h.mid = g.mid
     AND g.gid IN (SELECT     gid
                         FROM groups
                        WHERE mid IS NOT NULL
                   CONNECT BY PRIOR gid = parent
                   START WITH gid = filereport_pg.gn_group)
     AND h.date_time > TRUNC(filereport_pg.gd_from, 'month')
     AND h.date_time <= filereport_pg.gd_till;
  filereport_pg.put_p(
   LPAD('Потребление Акт.   энергии за сутки ', 53, ' ') ||
   LPAD(TO_CHAR(ln_abillm / 1000, '99999999990.999'), 16, ' '));
  filereport_pg.put_p(
   LPAD('Потребление Реакт. энергии за сутки ', 53, ' ') ||
   LPAD(TO_CHAR(ln_qbillm / 1000, '99999999990.999'), 16, ' '));
  filereport_pg.put_p(
   LPAD('Потребление Акт.   энергии с начала месяца ', 53, ' ') ||
   LPAD(TO_CHAR(ln_amonth / 1000, '99999999990.999'), 16, ' '));
  filereport_pg.put_p(
   LPAD('Потребление Реакт. энергии с начала месяца ', 53, ' ') ||
   LPAD(TO_CHAR(ln_qmonth / 1000, '99999999990.999'), 16, ' '));
  filereport_pg.put_p('');
  filereport_pg.put_p(LPAD('-', 103, '-'));
  filereport_pg.put_p(
   ' Время      Акт.мощ.    Реакт.мощ. Время      Акт.мощ.    Реакт.мощ. Время      Акт.мощ.    Реакт.мощ.');
  filereport_pg.put_p(LPAD('-', 103, '-'));
  FOR i IN 1 .. 16 LOOP
   lv_name := '';
   FOR j IN 1 .. 3 LOOP
    IF  i = 16 AND j = 3 THEN
     lv_time := '24:00';
    ELSE
     lv_time := TO_CHAR(TRUNC(SYSDATE) + (16 * (j - 1) + i) / 48, 'HH24:MI');
    END IF;
    ln_atmp := lt_er(16 * (j - 1) + i);
    ln_qtmp := lt_qq(16 * (j - 1) + i);
    IF ln_abill <> 0 THEN
     ln_atmp := ln_atmp * ln_abillm / ln_abill;
    END IF;
    IF ln_qbill <> 0 THEN
     ln_qtmp := ln_qtmp * ln_qbillm / ln_qbill;
    END IF;
    lv_name := lv_name || LPAD(lv_time, 6, ' ') ||
               LPAD(TO_CHAR(ROUND(ln_atmp / 1000, 3), '99999990.999'), 14, ' ') ||
               LPAD(TO_CHAR(ROUND(ln_qtmp / 1000, 3), '99999990.999'), 14, ' ');
   END LOOP;
   filereport_pg.put_p(SUBSTR(lv_name, 1, 103));
  END LOOP;
  filereport_pg.put_p(LPAD('-', 103, '-'));
 END;
 ------------------------------------------------------------------------------------------------------------------------
 --Потребление группы
 PROCEDURE report6_p IS
  CURSOR lcur_sel IS
   SELECT name, gid
     FROM groups
    WHERE parent = filereport_pg.gn_group
      AND (    TO_CHAR(filereport_pg.gd_from, 'yyyymm') <= NVL(ntillperiod, 299912)
           AND TO_CHAR(filereport_pg.gd_till, 'yyyymm') >= NVL(nfromperiod, 160501));
  CURSOR lcur_sel1(lc_gid NUMBER) IS
   SELECT SUM(
           DECODE(
            g.inverted, 'y', -util_pg.sld(
                               c.mid, NVL(c.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(
                                                                                  c.ed * DECODE(g.npartly, 1, 0, 1), 0)),
            util_pg.sld(
             c.mid, NVL(c.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(
                                                                c.ed * DECODE(g.npartly, 1, 0, 1), 0))) *
           DECODE(SIGN(TRUNC(c.date_time) - TO_DATE(NVL(g.nfromperiod, 160501), 'yyyymm')), 1, 1, NULL) *
           DECODE(SIGN((LAST_DAY(TO_DATE(NVL(g.ntillperiod, 299912), 'yyyymm')) + 1) - c.date_time), -1, NULL, 1))
            cnt
     FROM groups g, halfhour c
    WHERE g.gid IN (SELECT     g1.gid
                          FROM groups g1
                         WHERE g1.mid IS NOT NULL
                    CONNECT BY PRIOR g1.gid = g1.parent
                    START WITH g1.gid = lc_gid)
      AND g.mid = c.mid
      AND c.date_time > filereport_pg.gd_from
      AND c.date_time <= filereport_pg.gd_till;
  ln_full NUMBER DEFAULT 0;
 BEGIN
  filereport_pg.put_p('    Потребление энергии по группе: '|| filereport_pg.gv_name);
  filereport_pg.put_p(
   '    начиная с '|| TO_CHAR(filereport_pg.gd_from, 'dd.mm.yyyy hh24:mi:ss') || ' по ' ||
   TO_CHAR(filereport_pg.gd_till, 'dd.mm.yyyy hh24:mi:ss'));
  filereport_pg.put_p('');
  filereport_pg.put_p(LPAD('-', 60, '-'));
  filereport_pg.put_p('    Составляющая                 Потребление, [МВт/час]');
  filereport_pg.put_p(LPAD('-', 60, '-'));
  FOR lc IN lcur_sel LOOP
   FOR lc1 IN lcur_sel1(lc.gid) LOOP
    IF lc1.cnt <> 0 THEN
     ln_full := ln_full + lc1.cnt;
     filereport_pg.put_p(RPAD(lc.name, 35, ' ') || LPAD(TO_CHAR(lc1.cnt / 1000, '999999990.999'), 15, ' '));
    ELSE
     filereport_pg.put_p(RPAD(lc.name, 45, ' ') || '*');
    END IF;
   END LOOP;
  END LOOP;
  filereport_pg.put_p(LPAD('-', 60, '-'));
  filereport_pg.put_p('   ИТОГО :                          '|| TO_CHAR(ln_full / 1000, '999999990.999'));
 END;
 ------------------------------------------------------------------------------------------------------------------------
 --Подекадный расход с нарастающим итогом
 PROCEDURE report7_p IS
  CURSOR lcur_pointsum(an_gid NUMBER, ad_month DATE, an_decad NUMBER) IS
   -- курсор-запрос по суммарному расходу по "an_decad"-декаде для "ad_month"-даты по "an_mid"-й точке, где "av_inverted"-признак инверсии точки в группе
   SELECT SUM(
           DECODE(
            g.inverted, 'y', -util_pg.sld(
                               h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(
                                                                                  h.ed * DECODE(g.npartly, 1, 0, 1), 0)),
            util_pg.sld(
             h.mid, NVL(h.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(
                                                                h.ed * DECODE(g.npartly, 1, 0, 1), 0))) *
           DECODE(SIGN(TRUNC(h.date_time) - TO_DATE(NVL(g.nfromperiod, 160501), 'yyyymm')), 1, 1, NULL) *
           DECODE(SIGN((LAST_DAY(TO_DATE(NVL(g.ntillperiod, 299912), 'yyyymm')) + 1) - h.date_time), -1, NULL, 1))
            summa
     FROM bill h, groups g
    WHERE g.gid = an_gid
      AND g.mid = h.mid
      AND h.date_time >
              DECODE(an_decad, 1, TRUNC(ad_month, 'MONTH'), 2, TRUNC(ad_month, 'MONTH') + 10, TRUNC(ad_month, 'MONTH') +
                                                                                              20)
      AND h.date_time <= DECODE(
                          an_decad, 1, TRUNC(ad_month, 'MONTH') + 10, 2, TRUNC(ad_month, 'MONTH') + 20,
                          ADD_MONTHS(TRUNC(ad_month, 'MONTH'), 1));
  CURSOR lcur_sel IS
   SELECT     RPAD(' ', 2 * (LEVEL - 1), ' ') || name name, gid, parent, inverted, mid, npartly
         FROM groups
   CONNECT BY PRIOR gid = parent
          AND TO_CHAR(filereport_pg.gd_from, 'yyyymm') BETWEEN NVL(nfromperiod, 160501) AND NVL(ntillperiod, 299912)
   START WITH gid = filereport_pg.gn_group
          AND TO_CHAR(filereport_pg.gd_from, 'yyyymm') BETWEEN NVL(nfromperiod, 160501) AND NVL(ntillperiod, 299912);
  CURSOR lcur_sel1(an_gid NUMBER) IS
   SELECT     RPAD(' ', 2 * (LEVEL - 1), ' ') || name name, gid, parent, inverted, mid, npartly
         FROM groups
   CONNECT BY PRIOR gid = parent
          AND TO_CHAR(filereport_pg.gd_from, 'yyyymm') BETWEEN NVL(nfromperiod, 160501) AND NVL(ntillperiod, 299912)
   START WITH gid = an_gid
          AND TO_CHAR(filereport_pg.gd_from, 'yyyymm') BETWEEN NVL(nfromperiod, 160501) AND NVL(ntillperiod, 299912);
  n_gids    common_pg.tt_number; -- таблицы с соответствующими гидами
  n_parents common_pg.tt_number;
  v_names   common_pg.tt_varchar2;
  n_dec_1   common_pg.tt_number; -- таблицы значений по декадам
  n_dec_2   common_pg.tt_number;
  n_dec_3   common_pg.tt_number;
  n_ind     NUMBER;
  i         NUMBER;
  j         NUMBER;
  n_d1      NUMBER;
  n_d2      NUMBER;
  n_d3      NUMBER;
 BEGIN
  filereport_pg.put_p('    Подекадный расход с нарастающим итогом по группе '|| filereport_pg.gv_name);
  filereport_pg.put_p(
   '         за '|| TO_CHAR(filereport_pg.gd_from, 'MONTH') || ' месяц ' || TO_CHAR(filereport_pg.gd_from, 'YYYY') ||
   ' года. [МВт/час]');
  filereport_pg.put_p('');
  filereport_pg.put_p(
   RPAD('-', 43, '-') || '+' || RPAD('-', 21, '-') || '+' || RPAD('-', 21, '-') || '+' || RPAD('-', 21, '-') || '+');
  filereport_pg.put_p(
   '               Наименование                |     1-я декада      |     2-я декада      |     3-я декада      |');
  filereport_pg.put_p(
   RPAD('-', 43, '-') || '+' || RPAD('-', 21, '-') || '+' || RPAD('-', 21, '-') || '+' || RPAD('-', 21, '-') || '+');
  n_ind := 0;
  FOR lc_sel IN lcur_sel LOOP
   n_ind := n_ind + 1;
   v_names(n_ind) := lc_sel.name;
   n_gids(n_ind) := lc_sel.gid;
   n_parents(n_ind) := lc_sel.parent;
   n_dec_1(n_ind) := 0;
   n_dec_2(n_ind) := 0;
   n_dec_3(n_ind) := 0;
   IF lc_sel.mid IS NOT NULL THEN
    FOR lc_sum IN lcur_pointsum(lc_sel.gid, filereport_pg.gd_from, 1) LOOP
     n_dec_1(n_ind) := lc_sum.summa;
    END LOOP;
    FOR lc_sum IN lcur_pointsum(lc_sel.gid, filereport_pg.gd_from, 2) LOOP
     n_dec_2(n_ind) := lc_sum.summa;
    END LOOP;
    FOR lc_sum IN lcur_pointsum(lc_sel.gid, filereport_pg.gd_from, 3) LOOP
     n_dec_3(n_ind) := lc_sum.summa;
    END LOOP;
   ELSE
    FOR lc_gsel IN lcur_sel1(lc_sel.gid) LOOP
     IF lc_gsel.mid IS NOT NULL THEN
      FOR lc_sum IN lcur_pointsum(lc_gsel.gid, filereport_pg.gd_from, 1) LOOP
       n_dec_1(n_ind) := n_dec_1(n_ind) + NVL(lc_sum.summa, 0);
      END LOOP;
      FOR lc_sum IN lcur_pointsum(lc_gsel.gid, filereport_pg.gd_from, 2) LOOP
       n_dec_2(n_ind) := n_dec_2(n_ind) + NVL(lc_sum.summa, 0);
      END LOOP;
      FOR lc_sum IN lcur_pointsum(lc_gsel.gid, filereport_pg.gd_from, 3) LOOP
       n_dec_3(n_ind) := n_dec_3(n_ind) + NVL(lc_sum.summa, 0);
      END LOOP;
     END IF;
    END LOOP;
   END IF;
  END LOOP;
  FOR i IN 1 .. n_ind LOOP
   n_d1 := n_dec_1(i);
   n_d2 := NVL(n_dec_2(i) + NVL(n_d1, 0), n_d1);
   n_d3 := NVL(n_dec_3(i) + NVL(n_d2, 0), n_d2);
   IF SYSDATE < ADD_MONTHS(TRUNC(filereport_pg.gd_from, 'MONTH'), 1) THEN
    n_d3 := NULL;
   END IF;
   IF SYSDATE < TRUNC(filereport_pg.gd_from, 'MONTH') + 20 THEN
    n_d2 := NULL;
   END IF;
   IF SYSDATE < TRUNC(filereport_pg.gd_from, 'MONTH') + 10 THEN
    n_d1 := NULL;
   END IF;
   filereport_pg.put_p(
    RPAD(v_names(i), 43, ' ') || '|' || LPAD(NVL(TO_CHAR(n_d1 / 1000, '99999999999990.999'), ' '), 20, ' ') || ' |' ||
    LPAD(NVL(TO_CHAR(n_d2 / 1000, '99999999999990.999'), ' '), 20, ' ') || ' |' ||
    LPAD(NVL(TO_CHAR(n_d3 / 1000, '99999999999990.999'), ' '), 20, ' ') || ' |');
  END LOOP;
 END;
 ------------------------------------------------------------------------------------------------------------------------
 PROCEDURE report89_p(an_procedure NUMBER, ad_from DATE, an_maket NUMBER, ad_till DATE, an_info NUMBER) IS
  ld_from  DATE                  DEFAULT NVL(TRUNC(ad_from), filereport_pg.gd_from);
  ld_till  DATE                  DEFAULT NVL(TRUNC(ad_till), filereport_pg.gd_till);
  CURSOR lcur_sel IS
   SELECT   f.ddate, f.vfile, MAX(m.nmaket) nmaket, MAX(m.vname) vname
       FROM deportfiles f, deportation d, makets m
      WHERE f.ddate >= ld_from
        AND f.ddate < ld_till
        AND f.ndeportation = d.ndeportation(+)
        AND d.nmaket = m.nmaket
        AND ((an_maket IS NULL AND m.nprocedure = an_procedure) OR (an_maket IS NOT NULL AND d.nmaket = an_maket))
   GROUP BY f.ddate, f.vfile
   ORDER BY f.ddate;
  lt_file  common_pg.tt_varchar2;
  ln_insel NUMBER                := 0;
 BEGIN
  FOR lc IN lcur_sel LOOP
   ln_insel := 1;
   IF NVL(an_info, 0) <> 1 THEN
    BEGIN
     lt_file := file_pg.readfile_f(lc.vfile);
    EXCEPTION
     WHEN OTHERS THEN
      lt_file.DELETE;
      lt_file(1) := 'Загрузка файла макета произошла с ошибкой.';
      lt_file(2) := SQLERRM;
    END;
    IF (NVL(an_info, 0) <> 2) THEN
     filereport_pg.put_p(RPAD('*', 100, '*'));
    END IF;
   END IF;
   IF (NVL(an_info, 0) <> 2) THEN
    filereport_pg.put_p('Макет: "'|| lc.vname || '"');
    filereport_pg.put_p('Время, за которое сформирован макет: "'|| TO_CHAR(lc.ddate, 'dd.mm.yyyy hh24:mi') || '"');
    filereport_pg.put_p('Каналы расылки: ');
    FOR lc1 IN (SELECT   d.vname, f.denter,
                         DECODE(
                          f.nstate, 0, 'Макет готов к отсылке.' ||
                                       DECODE(d.nblock, 1, ' Канал заблокирован.', ' Ожидайте.'), 1,
                          'Макет отослан адресату' || NVL(TO_CHAR(f.dsend, ' dd.mm.yyyy hh24:mi:ss') || '.', '.'),
                          'Ошибка отсылки - ' || f.verror) state
                    FROM deportfiles f, deportation d
                   WHERE f.ddate = lc.ddate AND f.vfile = lc.vfile AND f.ndeportation = d.ndeportation(+)
                ORDER BY d.vname) LOOP
     filereport_pg.put_p(
      RPAD(' ', 6) || '"' || lc1.vname || '"  Время формирования: "' || TO_CHAR(lc1.denter, 'dd.mm.yyyy hh24:mi:ss') ||
      '"  Состояние: "' || lc1.state || '"');
    END LOOP;
   END IF;
   IF NVL(an_info, 0) <> 1 THEN
    IF (NVL(an_info, 0) <> 2) THEN
     filereport_pg.put_p(RPAD('-', 100, '-'));
    END IF;
    FOR i IN 1 .. lt_file.COUNT LOOP
     filereport_pg.put_p(lt_file(i));
    END LOOP;
    lt_file.DELETE;
   END IF;
   IF (NVL(an_info, 0) <> 2) THEN
    filereport_pg.put_p(RPAD('*', 100, '*'));
   END IF;
  END LOOP;
  IF  ln_insel = 0 AND an_info = 2 AND an_maket > 0 THEN
   filereport_pg.put_p('Загрузка файла макета произошла с ошибкой.');
   filereport_pg.put_p('На указанную дату макет не сформирован.');
  END IF;
 END;
   -----------------------------------------------------------------------------------------------------------------------
 --Отосланные макеты за период
 PROCEDURE report8s_p(an_info NUMBER) IS
 BEGIN
  FOR lc IN (SELECT   nmaket, vname
                 FROM makets
                WHERE nmaket IN (SELECT     mid
                                       FROM points
                                 CONNECT BY PRIOR mid = parent
                                 START WITH mid = filereport_pg.gn_group AND filereport_pg.gn_ispoint = 1)
             UNION
             SELECT DISTINCT m.nmaket, m.vname
                        FROM makets m, deportation d
                       WHERE d.ndeportation IN (SELECT     mid
                                                      FROM points
                                                CONNECT BY PRIOR mid = parent
                                                START WITH mid = filereport_pg.gn_group AND filereport_pg.gn_ispoint =
                                                                                                                      1)
                         AND d.nmaket = m.nmaket(+)
             UNION
             SELECT   m.nmaket, m.vname
                 FROM makets m
                WHERE filereport_pg.gn_group = -1 AND EXISTS( SELECT *
                                                                FROM deportation
                                                               WHERE nmaket = m.nmaket)
             ORDER BY 2) LOOP
   report89_p(NULL, NULL, lc.nmaket, NULL, an_info);
  END LOOP;
 END;
  -----------------------------------------------------------------------------------------------------------------------
 --Макет 30817
 PROCEDURE report8_p(ad_date DATE, an_maket NUMBER) IS
 BEGIN
  IF an_maket IS NOT NULL THEN
   report89_p(NULL, ad_date, an_maket);
  ELSE
   FOR lc IN (SELECT   nprocedure
                  FROM deportprocedures
                 --WHERE ntype = 0 AND nprocedure <> 3
                 WHERE ntype = 0 AND nprocedure <> 3 AND (util_pg.get_customer_id <> 1 OR nprocedure IN (5))
              ORDER BY vname) LOOP
    report89_p(lc.nprocedure, ad_date, an_maket);
   END LOOP;
  END IF;
 END;
  -----------------------------------------------------------------------------------------------------------------------
 --Макет 1010
 PROCEDURE report9_p(ad_date DATE, an_maket NUMBER) IS
 BEGIN
  report89_p(1, ad_date, an_maket);
 END;
  -----------------------------------------------------------------------------------------------------------------------
 --Типа 30817 за несколько дней
 PROCEDURE report10_p IS
  CURSOR lcur_sel IS
   SELECT     mid, DECODE(inverted, 'y', 1, 0) inv, name, npartly, nfromperiod, ntillperiod
         FROM groups
        WHERE mid IS NOT NULL
   CONNECT BY PRIOR gid = parent
          AND TO_CHAR(filereport_pg.gd_from, 'yyyymm') BETWEEN NVL(nfromperiod, 160501) AND NVL(ntillperiod, 299912)
   START WITH gid = filereport_pg.gn_group
          AND TO_CHAR(filereport_pg.gd_from, 'yyyymm') BETWEEN NVL(nfromperiod, 160501) AND NVL(ntillperiod, 299912)
     ORDER BY name;
  CURSOR lcur_sel1(lc_mid NUMBER, ad_date DATE, lc_nfromperiod NUMBER, lc_ntillperiod NUMBER) IS
   SELECT   TO_NUMBER(TO_CHAR(TRUNC(date_time - 1 / 86400, 'HH24'), 'HH24')) dt,
            SUM(
             util_pg.sld(b.mid, NVL(b.er, 0), NVL(b.ed, 0)) *
             DECODE(SIGN(b.date_time - TO_DATE(NVL(lc_nfromperiod, 160501), 'yyyymm')), 1, 1, NULL) *
             DECODE(SIGN((LAST_DAY(TO_DATE(NVL(lc_ntillperiod, 299912), 'yyyymm')) + 1) - b.date_time), -1, NULL, 1))
              sm
       FROM halfhour b
      WHERE b.mid = lc_mid AND b.date_time > TRUNC(ad_date) AND b.date_time <= TRUNC(ad_date) + 1
   GROUP BY TO_NUMBER(TO_CHAR(TRUNC(date_time - 1 / 86400, 'HH24'), 'HH24'));
  ld_tmp    DATE;
  lt_ras    common_pg.tt_number;
  ln_rasall NUMBER;
  lv_str    VARCHAR2(4000);
 BEGIN
  FOR lc IN lcur_sel LOOP
   filereport_pg.put_p('');
   filereport_pg.put_p(lc.name);
   ld_tmp := TRUNC(filereport_pg.gd_from);
   WHILE ld_tmp < TRUNC(filereport_pg.gd_till) + 1 LOOP
    FOR i IN 0 .. 23 LOOP
     lt_ras(i) := 0;
    END LOOP;
    ln_rasall := 0;
    lv_str := '';
    FOR lc1 IN lcur_sel1(lc.mid, ld_tmp, lc.nfromperiod, lc.ntillperiod) LOOP
     lt_ras(lc1.dt) := lt_ras(lc1.dt) + lc1.sm;
    END LOOP;
    lv_str := '';
    FOR i IN 0 .. 23 LOOP
     lt_ras(i) := lt_ras(i);
     ln_rasall := ln_rasall + lt_ras(i);
     lv_str := lv_str || ROUND(lt_ras(i)) || ':';
    END LOOP;
    lv_str := TO_CHAR(ld_tmp, 'DD.MM.YYYY') || ':' || ROUND(ln_rasall) || ':' || lv_str;
    filereport_pg.put_p(lv_str);
    lt_ras.DELETE;
    ld_tmp := ld_tmp + 1;
   END LOOP;
  END LOOP;
 END;
