 --Текущая мощность (KSS)
 PROCEDURE report11_p IS
  timelimit NUMBER      DEFAULT  util_pg.obsolescence_f / 1440; -- предел расхождения во времени при считывании текущей мощьности (CURR_POWER)
  CURSOR lcur_summa(an_gid NUMBER) IS
   SELECT DECODE(
           g.inverted, 'y', -util_pg.sld(
                              c.mid, NVL(c.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(
                                                                                 c.ed * DECODE(g.npartly, 1, 0, 1), 0)),
           util_pg.sld(
            c.mid, NVL(c.er * DECODE(g.npartly, 2, 0, 1), 0), NVL(
                                                               c.ed * DECODE(g.npartly, 1, 0, 1), 0))) activ,
          DECODE(
           g.inverted, 'y', -util_pg.sld(c.mid, NVL(c.q3, 0), NVL(c.q1, 0)), util_pg.sld(
                                                                                   c.mid, NVL(c.q3, 0), NVL(c.q1, 0))) react
     FROM curr_power c, groups g
    WHERE c.mid = g.mid
      AND g.gid IN (SELECT     gid
                          FROM groups
                         WHERE mid IS NOT NULL
                    CONNECT BY PRIOR gid = parent
                           AND SYSDATE BETWEEN TO_DATE(NVL(nfromperiod, 160501), 'yyyymm')
                                           AND TO_DATE(NVL(ntillperiod, 299912), 'yyyymm')
                    START WITH gid = an_gid
                           AND SYSDATE BETWEEN TO_DATE(NVL(nfromperiod, 160501), 'yyyymm')
                                           AND TO_DATE(NVL(ntillperiod, 299912), 'yyyymm'))
      AND c.date_time <= SYSDATE
      AND c.date_time >= (SYSDATE - timelimit)
      AND c.obsolete = 0;
  CURSOR lcur_groups IS
   SELECT gid, name
     FROM groups
    WHERE parent = filereport_pg.gn_group
      AND SYSDATE BETWEEN TO_DATE(NVL(nfromperiod, 160501), 'yyyymm') AND TO_DATE(NVL(ntillperiod, 299912), 'yyyymm');
  ln_cnt    NUMBER      DEFAULT 0;
  ln_cnts   NUMBER      DEFAULT 0;
  ln_activ  NUMBER      DEFAULT 0;
  ln_react  NUMBER      DEFAULT 0;
  ln_aactiv NUMBER      DEFAULT 0;
  ln_areact NUMBER      DEFAULT 0;
  lv_err    VARCHAR2(5);
 BEGIN
  filereport_pg.put_p('    Текущая мощность по группе: '|| filereport_pg.gv_name);
  filereport_pg.put_p('    Время: '|| TO_CHAR(SYSDATE, 'hh24:mi:ss') || '   Дата: ' || TO_CHAR(SYSDATE, 'dd.mm.yyyy'));
  filereport_pg.put_p('');
  filereport_pg.put_p(LPAD('-', 90, '-'));
  filereport_pg.put_p(
   RPAD('   Составляющая', 30, ' ') || RPAD('Акт.мощн.факт.,[МВт]', 28, ' ') || RPAD('Реакт.мощн.факт.,[МВАр]', 28, ' ') ||
   'ERR');
  filereport_pg.put_p(LPAD('-', 90, '-'));
  ln_aactiv := 0;
  ln_areact := 0;
  FOR lc IN lcur_groups LOOP
   SELECT     COUNT(gid)
         INTO ln_cnt
         FROM groups
        WHERE mid IS NOT NULL
   CONNECT BY PRIOR gid = parent
   START WITH gid = lc.gid;
   IF ln_cnt = 0 THEN
    ln_activ := NULL;
    ln_react := NULL;
   ELSE
    ln_activ := 0;
    ln_react := 0;
    ln_cnts := 0;
    FOR lc1 IN lcur_summa(lc.gid) LOOP
     ln_cnts := ln_cnts + 1;
     ln_activ := ln_activ + lc1.activ;
     ln_react := ln_react + lc1.react;
    END LOOP;
   END IF;
   IF ln_cnt <> ln_cnts THEN
    lv_err := '*';
   ELSE
    lv_err := ' ';
   END IF;
   filereport_pg.put_p(
    RPAD(lc.name, 35, ' ') || LPAD(NVL(TO_CHAR(ln_activ / 1000, '999999990.999'), ' '), 15, ' ') ||
    LPAD(NVL(TO_CHAR(ln_react / 1000, '999999990.999'), ' '), 30, ' ') || LPAD(lv_err, 8, ' '));
   ln_aactiv := ln_aactiv + NVL(ln_activ, 0);
   ln_areact := ln_areact + NVL(ln_react, 0);
  END LOOP;
  filereport_pg.put_p(LPAD('-', 90, '-'));
  filereport_pg.put_p(
   RPAD('ИТОГО', 35, ' ') || LPAD(NVL(TO_CHAR(ln_aactiv / 1000, '999999990.999'), ' '), 15, ' ') ||
   LPAD(NVL(TO_CHAR(ln_areact / 1000, '999999990.999'), ' '), 30, ' ') || LPAD(lv_err, 8, ' '));
 END;
  ------------------------------------------------------------------------------------------------------------------------
 --Показания приборов учёта (KSS)
 PROCEDURE report12_p IS
  ln_pos_lim   NUMBER         := 32;
  ln_er_entype NUMBER;
  ln_ed_entype NUMBER;
  ln_q1_entype NUMBER;
  ln_q3_entype NUMBER;
  CURSOR lcur_fdrs IS
   SELECT   f.er_position pos, p.name nam,
            DECODE(ln_er_entype, 1, 'актив. прм.', 2, 'актив. отд.', 3, 'реакт. птр.', 5, 'реакт. ген.') entype, m.mtrsn
              sn,
            m.digits mask, util_pg.get_meterage(p.mid, filereport_pg.gd_from, ln_er_entype, 1) value, ln_er_entype
       FROM meters m, points p, feeders f
      WHERE p.mid = m.mid
        AND m.entype = 1
        AND f.er_position > ln_pos_lim
        AND f.mid = p.mid
        AND p.mid IN (SELECT DISTINCT mid
                                 FROM groups
                                WHERE mid IS NOT NULL
                           CONNECT BY PRIOR gid = parent
                           START WITH gid = filereport_pg.gn_group)
   UNION ALL
   SELECT   f.ed_position, p.name nam,
            DECODE(ln_ed_entype, 1, 'актив. прм.', 2, 'актив. отд.', 3, 'реакт. птр.', 5, 'реакт. ген.'), m.mtrsn sn,
            m.digits mask, util_pg.get_meterage(p.mid, filereport_pg.gd_from, ln_ed_entype, 1) value, ln_ed_entype
       FROM meters m, points p, feeders f
      WHERE p.mid = m.mid
        AND m.entype = 2
        AND f.ed_position > ln_pos_lim
        AND f.mid = p.mid
        AND p.mid IN (SELECT DISTINCT mid
                                 FROM groups
                                WHERE mid IS NOT NULL
                           CONNECT BY PRIOR gid = parent
                           START WITH gid = filereport_pg.gn_group)
   UNION ALL
   SELECT   f.q1_position, p.name nam,
            DECODE(ln_q1_entype, 1, 'актив. прм.', 2, 'актив. отд.', 3, 'реакт. птр.', 5, 'реакт. ген.'), m.mtrsn sn,
            m.digits mask, util_pg.get_meterage(p.mid, filereport_pg.gd_from, ln_q1_entype, 1) value, ln_q1_entype
       FROM meters m, points p, feeders f
      WHERE p.mid = m.mid
        AND m.entype = 3
        AND f.q1_position > ln_pos_lim
        AND f.mid = p.mid
        AND p.mid IN (SELECT DISTINCT mid
                                 FROM groups
                                WHERE mid IS NOT NULL
                           CONNECT BY PRIOR gid = parent
                           START WITH gid = filereport_pg.gn_group)
   UNION ALL
   SELECT   f.q3_position, p.name nam,
            DECODE(ln_q3_entype, 1, 'актив. прм.', 2, 'актив. отд.', 3, 'реакт. птр.', 5, 'реакт. ген.'), m.mtrsn sn,
            m.digits mask, util_pg.get_meterage(p.mid, filereport_pg.gd_from, ln_q3_entype, 1) value, ln_q3_entype
       FROM meters m, points p, feeders f
      WHERE p.mid = m.mid
        AND m.entype = 5
        AND f.q3_position > ln_pos_lim
        AND f.mid = p.mid
        AND p.mid IN (SELECT DISTINCT mid
                                 FROM groups
                                WHERE mid IS NOT NULL
                           CONNECT BY PRIOR gid = parent
                           START WITH gid = filereport_pg.gn_group)
   ORDER BY 2, 7;
  lv_ps        VARCHAR2(1000);
  ln_mid       NUMBER         DEFAULT 0;
  ln_gid       NUMBER         DEFAULT 0;
  ld_date      DATE;
 BEGIN
  IF util_pg.needchdr_f(NULL) = 1 THEN
   ln_er_entype := 2;
   ln_ed_entype := 1;
   ln_q1_entype := 5;
   ln_q3_entype := 3;
  ELSE
   ln_er_entype := 1;
   ln_ed_entype := 2;
   ln_q1_entype := 3;
   ln_q3_entype := 5;
  END IF;
  SELECT DECODE(mid, NULL, gid, parent)
    INTO ln_gid
    FROM groups
   WHERE gid = filereport_pg.gn_group;
  SELECT name
    INTO lv_ps
    FROM groups
   WHERE gid = ln_gid;
  filereport_pg.put_p('    Показания по подстанции: '|| lv_ps);
  ld_date :=
            TRUNC(filereport_pg.gd_from, 'dd') +
            FLOOR(
             (filereport_pg.gd_from - TRUNC(filereport_pg.gd_from, 'dd')) * 48) /
            48;
  filereport_pg.put_p('    Время: '|| TO_CHAR(ld_date, 'hh24:mi:ss') || '   Дата: ' || TO_CHAR(ld_date, 'dd.mm.yyyy'));
  filereport_pg.put_p('');
  filereport_pg.put_p(LPAD('-', 80, '-'));
  filereport_pg.put_p(
   RPAD('Позиция', 8, ' ') || RPAD('Фидер', 30, ' ') || ' ' || RPAD('Энергия', 12, ' ') || RPAD('З-д №', 10, ' ') ||
   LPAD('  Показания  ', 18, ' '));
  filereport_pg.put_p(LPAD('-', 80, '-'));
  FOR lc IN lcur_fdrs LOOP
   filereport_pg.put_p(
    RPAD(lc.pos - 32, 8, ' ') || RPAD(lc.nam, 30, ' ') || ' ' || RPAD(lc.entype, 12, ' ') || RPAD(lc.sn, 10, ' ') ||
    LPAD(TO_CHAR(lc.VALUE, REPLACE(NVL(lc.mask, '999999.99'), '9', '0')), 18, ' '));
  END LOOP;
  filereport_pg.put_p(LPAD('-', 80, '-'));
 END;
 ------------------------------------------------------------------------------------------------------------------------
 --Первичная информация УСД ИТЕК (получасовой расход) (KSS)  an_type = 1
 --Первичная информация УСД ИТЕК (суточный расход) (KSS)     an_type = 2
 --Первичная информация УСД ИТЕК (месячный расход) (KSS)     an_type = 3
 PROCEDURE report13_p(an_type NUMBER) IS
  CURSOR lcur_sel(an_pos NUMBER, an_gid NUMBER) IS
   SELECT p.mid mid,
          util_pg.chdr_f(p.mid, DECODE(an_pos, er_position, 1, ed_position, 2, q1_position, 3, q3_position, 5)) typ,
          p.name nam, DECODE(SIGN(m.canal - 100000), 1, 20, 10) nsource
     FROM feeders m, points p
    WHERE m.mid = p.mid
      AND (er_position = an_pos OR ed_position = an_pos OR q1_position = an_pos OR q3_position = an_pos)
      AND p.mid IN (SELECT DISTINCT mid
                               FROM groups
                              WHERE mid IS NOT NULL AND parent = an_gid);
  CURSOR lcur_sel1(lc_mid NUMBER, lc_source NUMBER) IS
   SELECT   TRUNC(
             TO_CHAR(date_time - 1 / 86400, 'SSSSS') / 1800) +
            1 dt,
            SUM(er) er, SUM(ed) ed, SUM(q1) q1, SUM(q3) q3
       FROM halfhourold
      WHERE mid = lc_mid
        AND date_time > TRUNC(filereport_pg.gd_from)
        AND date_time <= TRUNC(filereport_pg.gd_from) + 1
        AND nsource = lc_source
   GROUP BY TRUNC(TO_CHAR(date_time - 1 / 86400, 'SSSSS') / 1800);
  lc_sel     lcur_sel%ROWTYPE;
  lv_ps      VARCHAR2(1000);
  ln_mid     NUMBER                DEFAULT 0;
  ln_gid     NUMBER                DEFAULT 0;
  ld_date    DATE;
  lv_type    VARCHAR2(50);
  ln_val     NUMBER;
  ln_koef    NUMBER;
  lt_p       common_pg.tt_varchar2;
  lt_k       common_pg.tt_varchar2;
  lt_tmp     common_pg.tt_varchar2;
  lv_tmp     VARCHAR2(1000);
  ln_source  NUMBER;
  ln_itekoff NUMBER                DEFAULT 32;
 BEGIN
  SELECT DECODE(mid, NULL, gid, parent), mid
    INTO ln_gid, ln_mid
    FROM groups
   WHERE gid = filereport_pg.gn_group;
  IF  ln_mid IS NOT NULL AND an_type = 1 THEN --------Спец отчет (по точке и получасовки)
   SELECT name
     INTO lv_ps
     FROM points
    WHERE mid = ln_mid;
   SELECT RPAD(NVL(TRIM(TO_CHAR(SUM(ker), '999990.999999')), ' '), 14, ' '),
          RPAD(NVL(TRIM(TO_CHAR(SUM(ked), '999990.999999')), ' '), 14, ' '),
          RPAD(NVL(TRIM(TO_CHAR(SUM(kq1), '999990.999999')), ' '), 14, ' '),
          RPAD(NVL(TRIM(TO_CHAR(SUM(kq3), '999990.999999')), ' '), 14, ' ')
     INTO lt_k(1),
          lt_k(2),
          lt_k(3),
          lt_k(4)
     FROM itekcoeff
    WHERE mid = ln_mid;
   SELECT RPAD(TO_CHAR(SUM(er_position - ln_itekoff)), 2, ' '), RPAD(TO_CHAR(SUM(ed_position - ln_itekoff)), 2, ' '),
          RPAD(TO_CHAR(SUM(q1_position - ln_itekoff)), 2, ' '), RPAD(TO_CHAR(SUM(q3_position - ln_itekoff)), 2, ' '),
          DECODE(SIGN(SUM(canal) - 100000), 1, 20, 10) nsource
     INTO lt_p(1), lt_p(2),
          lt_p(3), lt_p(4),
          ln_source
     FROM feeders
    WHERE mid = ln_mid;
   util_pg.chdr(ln_mid, lt_k(1), lt_k(2), lt_k(3), lt_k(4));
   util_pg.chdr(ln_mid, lt_p(1), lt_p(2), lt_p(3), lt_p(4));
   lt_tmp(1) := ':' || '     ' || ':' || 'Актив принятая  ' || ':' || 'Актив отданная  ' || ':' || 'Реактив принятая' || ':' ||
                'Реактив сгенерен' || ':';
   lt_tmp(2) := ':' || 'Время' || ':';
   lt_tmp(3) := ':' || '     ' || ':';
   FOR i IN 1 .. 4 LOOP
    IF lt_p(i) IS NULL OR lt_p(i) = '-3' THEN
     lt_p(i) := '  ';
    END IF;
    lt_tmp(2) := lt_tmp(2) || 'Позиция №' || lt_p(i) || '     ' || ':';
    lt_tmp(3) := lt_tmp(3) || 'K=' || lt_k(i) || ':';
   END LOOP;
   filereport_pg.put_p(
    '   Первичная информация УСД ИТЕК за '|| TO_CHAR(filereport_pg.gd_from, 'dd.mm.yyyy') || ' (график нагрузки)');
   filereport_pg.put_p('      по точке учета: '|| lv_ps);
   filereport_pg.put_p('');
   filereport_pg.put_p('+'|| LPAD('-', 73, '-') || '+');
   FOR i IN 1 .. 3 LOOP
    filereport_pg.put_p(lt_tmp(i));
   END LOOP;
   filereport_pg.put_p('+'|| LPAD('-', 73, '-') || '+');
   lt_tmp.DELETE;
   FOR lc IN lcur_sel1(ln_mid, ln_source) LOOP
    lt_tmp(lc.dt) := LPAD(NVL(TO_CHAR(lc.er, '9999999990.9999'), ' '), 16, ' ') || ':' ||
                     LPAD(NVL(TO_CHAR(lc.ed, '9999999990.9999'), ' '), 16, ' ') || ':' ||
                     LPAD(NVL(TO_CHAR(lc.q1, '9999999990.9999'), ' '), 16, ' ') || ':' ||
                     LPAD(NVL(TO_CHAR(lc.q3, '9999999990.9999'), ' '), 16, ' ') || ':';
   END LOOP;
   FOR i IN 1 .. 48 LOOP
    lv_tmp := ':' || TRIM(TO_CHAR(TRUNC(i / 2), '00')) || ':' || TRIM(TO_CHAR(30 * MOD(i, 2), '00')) || ':';
    IF NOT lt_tmp.EXISTS(i) THEN
     FOR j IN 1 .. 4 LOOP
      lv_tmp := lv_tmp || LPAD(' ', 16) || ':';
     END LOOP;
     filereport_pg.put_p(lv_tmp);
    ELSE
     filereport_pg.put_p(lv_tmp || lt_tmp(i));
    END IF;
   END LOOP;
   filereport_pg.put_p('+'|| LPAD('-', 73, '-') || '+');
  ELSE
   SELECT name
     INTO lv_ps
     FROM groups
    WHERE gid = ln_gid;
   IF an_type = 1 THEN
    lv_type := '(за полчаса)';
    ld_date :=
           TRUNC(filereport_pg.gd_from, 'dd') +
           FLOOR(
            (filereport_pg.gd_from - TRUNC(filereport_pg.gd_from, 'dd')) * 48) /
           48;
   ELSIF an_type = 2 THEN
    lv_type := '(за сутки)';
    ld_date := TRUNC(filereport_pg.gd_from, 'dd') + 1;
   ELSIF an_type = 3 THEN
    lv_type := '(за месяц)';
    ld_date := TRUNC(ADD_MONTHS(filereport_pg.gd_from, 1), 'mm');
   ELSE
    RETURN;
   END IF;
   filereport_pg.put_p('   Первичная информация УСД ИТЕК '|| lv_type || ' по подстанции: ' || lv_ps);
   IF an_type = 1 THEN
    filereport_pg.put_p('    Время: '|| TO_CHAR(ld_date, 'hh24:mi:ss') || '   Дата: ' || TO_CHAR(ld_date, 'dd.mm.yyyy'));
   ELSE
    IF an_type = 2 THEN
     filereport_pg.put_p('    Дата: '|| TO_CHAR(ld_date - 1, 'dd.mm.yyyy'));
    ELSE
     filereport_pg.put_p('    Месяц: '|| TO_CHAR(ld_date - 1, 'MONTH'));
    END IF;
   END IF;
   filereport_pg.put_p('');
   filereport_pg.put_p(LPAD('-', 86, '-'));
   filereport_pg.put_p(
    RPAD('Позиция', 10, ' ') || LPAD(' Расход', 15, ' ') || RPAD('  Коэфф.ИТЕКа', 18, ' ') || RPAD('   Энергия', 18, ' ') ||
    RPAD('     Фидер', 30, ' '));
   filereport_pg.put_p(LPAD('-', 86, '-'));
   FOR i IN 0 .. 63 LOOP
    lv_type := NULL;
    ln_mid := NULL;
    ln_val := NULL;
    ln_koef := NULL;
    OPEN lcur_sel(i + 33, ln_gid);
    FETCH lcur_sel INTO lc_sel;
    IF lcur_sel%NOTFOUND THEN
     lc_sel.typ := NULL;
     lc_sel.nam := NULL;
    END IF;
    CLOSE lcur_sel;
    ln_mid := lc_sel.mid;
    ln_source := lc_sel.nsource;
    IF ln_mid IS NOT NULL THEN
     IF lc_sel.typ = 1 THEN
      lv_type := 'Актив. прием';
     ELSIF lc_sel.typ = 2 THEN
      lv_type := 'Актив. отдача';
     ELSIF lc_sel.typ = 3 THEN
      lv_type := 'Реакт. прием';
     ELSIF lc_sel.typ = 5 THEN
      lv_type := 'Реакт. генерация';
     END IF;
     IF an_type = 1 THEN
      SELECT SUM(DECODE(lc_sel.typ, 1, er, 2, ed, 3, q1, q3))
        INTO ln_val
        FROM halfhourold
       WHERE mid = ln_mid AND date_time = ld_date AND nsource = ln_source; --= 20;--AND nexceptcalc IS NULL AND nsource < 30;
     ELSIF an_type = 2 THEN
      SELECT SUM(DECODE(lc_sel.typ, 1, er, 2, ed, 3, q1, q3))
        INTO ln_val
        FROM billorg
       WHERE mid = ln_mid AND date_time = ld_date AND nsource = ln_source; --=20
     ELSE
      SELECT SUM(DECODE(lc_sel.typ, 1, er, 2, ed, 3, q1, q3))
        INTO ln_val
        FROM monthsorg
       WHERE mid = ln_mid AND date_time = ld_date AND nsource = ln_source; --=20
     END IF;
     SELECT SUM(DECODE(lc_sel.typ, 2, ker, 1, ked, 5, kq1, kq3)) koef
       INTO ln_koef
       FROM itekcoeff
      WHERE mid = ln_mid;
    END IF;
    filereport_pg.put_p(
     LPAD(i + 1, 4, ' ') || '  ' || LPAD(NVL(TO_CHAR(ln_val, '99999999990.9999'), ' '), 17, ' ') ||
     LPAD(NVL(TO_CHAR(ln_koef, '999990.999999'), ' '), 15, ' ') || '     ' || RPAD(lv_type, 15, ' ') || RPAD(
                                                                                                         lc_sel.nam, 50,
                                                                                                         ' '));
   END LOOP;
  END IF;
 END;
 ------------------------------------------------------------------------------------------------------------------------
 --Подекадный расход с нарастающим итогом (по группам)
 PROCEDURE report14_p IS
  -- курсор-запрос по суммарному расходу по "an_decad"-декаде для "ad_month"-даты по "an_gid"-й группе
  CURSOR lcur_pointsum(an_gid NUMBER, ad_month DATE, an_decad NUMBER) IS
   SELECT SUM(
           DECODE(
            g.inverted, 'y', -util_pg.sld(
                               h.mid, h.er * DECODE(g.npartly, 2, 0, 1), h.ed * DECODE(g.npartly, 1, 0, 1)),
            util_pg.sld(
             h.mid, h.er * DECODE(g.npartly, 2, 0, 1), h.ed * DECODE(g.npartly, 1, 0, 1))) *
           DECODE(SIGN(h.date_time - TO_DATE(NVL(g.nfromperiod, 160501), 'yyyymm')), 1, 1, NULL) *
           DECODE(SIGN((LAST_DAY(TO_DATE(NVL(g.ntillperiod, 299912), 'yyyymm')) + 1) - h.date_time), -1, NULL, 1))
            summa
     FROM bill h, groups g
    WHERE g.gid = an_gid
      AND g.mid = h.mid
      AND h.date_time >
              DECODE(an_decad, 1, TRUNC(ad_month, 'MONTH'), 2, TRUNC(ad_month, 'MONTH') + 10, TRUNC(ad_month, 'MONTH') +
                                                                                              20)
      AND h.date_time <= DECODE(
                          an_decad, 1, TRUNC(ad_month, 'MONTH') + 10, 2, TRUNC(ad_month, 'MONTH') + 20,
                          TRUNC(ADD_MONTHS(ad_month, 1), 'MONTH'));
  CURSOR lcur_sel IS
   SELECT   DECODE(gid, filereport_pg.gn_group, '', '   ') || name nam, gid, mid,
            DECODE(gid, filereport_pg.gn_group, 1, 2) t
       FROM groups
      WHERE gid = filereport_pg.gn_group
         OR     parent = filereport_pg.gn_group
            AND TO_CHAR(filereport_pg.gd_from, 'yyyymm') BETWEEN NVL(nfromperiod, 160501) AND NVL(ntillperiod, 299912)
   ORDER BY t, name;
  CURSOR lcur_sel1(an_gid NUMBER) IS
   SELECT     gid
         FROM groups
        WHERE mid IS NOT NULL
   CONNECT BY PRIOR gid = parent
          AND TO_CHAR(filereport_pg.gd_from, 'yyyymm') BETWEEN NVL(nfromperiod, 160501) AND NVL(ntillperiod, 299912)
   START WITH gid = an_gid
          AND TO_CHAR(filereport_pg.gd_from, 'yyyymm') BETWEEN NVL(nfromperiod, 160501) AND NVL(ntillperiod, 299912);
  v_names common_pg.tt_varchar2;
  n_dec_1 common_pg.tt_number; -- таблицы значений по декадам
  n_dec_2 common_pg.tt_number;
  n_dec_3 common_pg.tt_number;
  n_ind   NUMBER;
  i       NUMBER;
  j       NUMBER;
  n_d1    NUMBER;
  n_d2    NUMBER;
  n_d3    NUMBER;
  curdate DATE;
 BEGIN
  filereport_pg.put_p('    Подекадный расход перетока активной энергии с нарастающим итогом');
  filereport_pg.put_p(
   ' по группе '|| filereport_pg.gv_name || ' за ' || TO_CHAR(filereport_pg.gd_from, 'MONTH') || ' месяц ' ||
   TO_CHAR(filereport_pg.gd_from, 'YYYY') || ' года. [тыс. кВт*час]');
  filereport_pg.put_p('');
  filereport_pg.put_p(
   RPAD('-', 43, '-') || '+' || RPAD('-', 21, '-') || '+' || RPAD('-', 21, '-') || '+' || RPAD('-', 21, '-') || '+');
  filereport_pg.put_p(
   '               Наименование                |     1-я декада      |     2-я декада      |     3-я декада      |');
  filereport_pg.put_p(
   RPAD('-', 43, '-') || '+' || RPAD('-', 21, '-') || '+' || RPAD('-', 21, '-') || '+' || RPAD('-', 21, '-') || '+');
  n_ind := 0;
  FOR lc_sel IN lcur_sel LOOP
   n_ind := n_ind + 1;
   v_names(n_ind) := lc_sel.nam;
   n_dec_1(n_ind) := NULL;
   n_dec_2(n_ind) := NULL;
   n_dec_3(n_ind) := NULL;
   IF lc_sel.mid IS NOT NULL THEN
    FOR lc_sum IN lcur_pointsum(lc_sel.gid, filereport_pg.gd_from, 1) LOOP
     n_dec_1(n_ind) := lc_sum.summa;
    END LOOP;
    FOR lc_sum IN lcur_pointsum(lc_sel.gid, filereport_pg.gd_from, 2) LOOP
     n_dec_2(n_ind) := lc_sum.summa;
    END LOOP;
    FOR lc_sum IN lcur_pointsum(lc_sel.gid, filereport_pg.gd_from, 3) LOOP
     n_dec_3(n_ind) := lc_sum.summa;
    END LOOP;
   ELSE
    FOR lc_gsel IN lcur_sel1(lc_sel.gid) LOOP
     FOR lc_sum IN lcur_pointsum(lc_gsel.gid, filereport_pg.gd_from, 1) LOOP
      n_dec_1(n_ind) := NVL(n_dec_1(n_ind) + NVL(lc_sum.summa, 0), lc_sum.summa);
     END LOOP;
     FOR lc_sum IN lcur_pointsum(lc_gsel.gid, filereport_pg.gd_from, 2) LOOP
      n_dec_2(n_ind) := NVL(n_dec_2(n_ind) + NVL(lc_sum.summa, 0), lc_sum.summa);
     END LOOP;
     FOR lc_sum IN lcur_pointsum(lc_gsel.gid, filereport_pg.gd_from, 3) LOOP
      n_dec_3(n_ind) := NVL(n_dec_3(n_ind) + NVL(lc_sum.summa, 0), lc_sum.summa);
     END LOOP;
    END LOOP;
   END IF;
  END LOOP;
  FOR i IN 1 .. n_ind LOOP
   n_d1 := n_dec_1(i);
   n_d2 := NVL(n_dec_2(i) + NVL(n_d1, 0), n_d1);
   n_d3 := NVL(n_dec_3(i) + NVL(n_d2, 0), n_d2);
   SELECT SYSDATE
     INTO curdate
     FROM DUAL;
   IF SYSDATE < TRUNC(ADD_MONTHS(filereport_pg.gd_from, 1), 'MONTH') THEN
    n_d3 := NULL;
   END IF;
   IF SYSDATE < TRUNC(filereport_pg.gd_from, 'MONTH') + 21 THEN
    n_d2 := NULL;
   END IF;
   IF SYSDATE < TRUNC(filereport_pg.gd_from, 'MONTH') + 11 THEN
    n_d1 := NULL;
   END IF;
   filereport_pg.put_p(
    RPAD(v_names(i), 43, ' ') || '|' || LPAD(NVL(TO_CHAR(n_d1 / 1000, '99999999999990.999'), ' '), 20, ' ') || ' |' ||
    LPAD(NVL(TO_CHAR(n_d2 / 1000, '99999999999990.999'), ' '), 20, ' ') || ' |' ||
    LPAD(NVL(TO_CHAR(n_d3 / 1000, '99999999999990.999'), ' '), 20, ' ') || ' |');
  END LOOP;
 END;
  -----------------------------------------------------------------------------------------------------------------------
 --Недопустимые расхождения при верификации
 PROCEDURE report15_p IS
  repwidth NUMBER DEFAULT 90;
 BEGIN
  filereport_pg.put_p('    Недопустимые расхождения при верификации ');
  filereport_pg.put_p(' ');
  filereport_pg.put_p(RPAD('-', repwidth, '-'));
  filereport_pg.put_p(RPAD('     Дата', 30, ' ') || 'Подстанция / Точка учета');
  filereport_pg.put_p(RPAD('Верификация', 40, ' ') || RPAD('План', 10, ' ') || RPAD('Факт', 10, ' ') || 'Примечание');
  filereport_pg.put_p(RPAD('-', repwidth, '-'));
  FOR c IN (SELECT   RPAD(TO_CHAR(ddate, 'dd.mm.yy hh24:mi'), 30, ' ') dd, RPAD(p1.name, 40, ' ') proc,
                     p3.name || '/' || p2.name point, RPAD(vparam, 10, ' ') plan,
                     RPAD(
                      ROUND(
                       ABS(nmustbe - nindeed) / DECODE(SIGN(nmustbe), 0, 1, -1, -nmustbe, nmustbe) * 100, 3), 10, ' ') fact,
                     DECODE(
                      c.nprocedure, 6, 'Осн.' || ROUND(nmustbe, 5) || ' / Дубль.' || ROUND(nindeed, 5), 7,
                      'Итек ' || ROUND(nmustbe, 5) || ' / БД ' || ROUND(nindeed, 5), 8, 'З-д №' || ROUND(nmustbe, 5) ||
                                                                                        ' / Св.№' || ROUND(nindeed, 5),
                      9, 'По ПУ ' || ROUND(nmustbe, 5) || ' / По БД ' || ROUND(nindeed, 5), 10, 'По ПУ ' ||
                                                                                                ROUND(nmustbe, 5) ||
                                                                                                ' / По БД ' ||
                                                                                                ROUND(nindeed, 5), 11,
                      'Прием ' || ROUND(nmustbe, 5) || ' / Отдача ' || ROUND(nindeed, 5), 12, 'ОВ ' ||
                                                                                              ROUND(nmustbe, 5) ||
                                                                                              ' / БД ' ||
                                                                                              ROUND(nindeed, 5), 13,
                      'Факт ' || ROUND(nmustbe, 5) || ' / Отчет ' || ROUND(nindeed, 5), NULL) prim
                FROM check_results c, points p1, points p2, points p3
               WHERE p1.mid = c.nprocedure AND p2.mid = c.mid AND p3.mid = p2.parent
            ORDER BY ddate DESC, 3 ASC) LOOP
   filereport_pg.put_p(c.dd || c.point);
   filereport_pg.put_p(c.proc || c.plan || c.fact || c.prim);
   filereport_pg.put_p(RPAD('-', repwidth, '-'));
  END LOOP;
 END;
 -----------------------------------------------------------------------------------------------------------------------
 -- M30817 с нарастающим
 PROCEDURE reportm30817acc_p IS
  repwidth NUMBER        DEFAULT 90;
  line     VARCHAR2(500);
 BEGIN
  FOR c IN (SELECT DISTINCT nmaket
                       FROM maketgroups
                      WHERE ngroup IN (SELECT ngroup
                                         FROM maket30817
                                        WHERE ddate = TRUNC(filereport_pg.gd_from))) LOOP
   line := ' ';
   FOR cc IN (SELECT   vcode, HOUR, SUM(kwh) total
                  FROM maket30817 m, maketgroups g
                 WHERE g.nmaket = c.nmaket
                   AND m.ngroup = g.ngroup
                   AND m.ddate <= TRUNC(filereport_pg.gd_from)
                   AND m.ddate >= TRUNC(filereport_pg.gd_from, 'mm')
              GROUP BY vcode, HOUR
              ORDER BY TO_NUMBER(vcode) DESC, HOUR ASC) LOOP
    IF cc.HOUR = 0 THEN
     filereport_pg.put_p(line);
     line := cc.vcode || ':';
    ELSE
     line := line || cc.total || ':';
    END IF;
   END LOOP;
   filereport_pg.put_p(line);
   filereport_pg.put_p(RPAD('-', repwidth, '-'));
  END LOOP;
 END;
 -----------------------------------------------------------------------------------------------------------------------
 --Первичные данные для канала
 PROCEDURE report18_p IS
  CURSOR lcur_sel IS
   SELECT   w.mid mid, w.date_time date_time, w.nsort n, w.vdata data, p.vname name
       FROM lg_loadprof w, channels p
      WHERE w.mid IN (SELECT cid
                        FROM chanpoint
                       WHERE mid IN (SELECT     mid
                                           FROM groups
                                     CONNECT BY PRIOR gid = parent
                                     START WITH gid = filereport_pg.gn_group))
        AND w.mid = p.cid(+)
        AND w.date_time >= filereport_pg.gd_from
        AND w.date_time <= filereport_pg.gd_till
   ORDER BY w.mid, w.date_time, w.nsort;
  ln_curr NUMBER DEFAULT -1;
  ld_curr DATE;
 BEGIN
  filereport_pg.put_p('    Первичные данные для канала по группе: '|| filereport_pg.gv_name);
  filereport_pg.put_p(
   '    начиная с '|| TO_CHAR(filereport_pg.gd_from, 'dd.mm.yyyy hh24:mi:ss') || ' по ' ||
   TO_CHAR(filereport_pg.gd_till, 'dd.mm.yyyy hh24:mi:ss'));
  filereport_pg.put_p('');
  FOR lc IN lcur_sel LOOP
   IF lc.mid <> ln_curr OR ld_curr <> lc.date_time THEN
    filereport_pg.put_p(RPAD('-', 80, '-'));
    filereport_pg.put_p('Канал:  '|| lc.name);
    filereport_pg.put_p('Дата:   '|| TO_CHAR(lc.date_time, 'dd.mm.yyyy hh24:mi:ss'));
    filereport_pg.put_p(RPAD('-', 80, '-'));
    ln_curr := lc.mid;
    ld_curr := lc.date_time;
   END IF;
   filereport_pg.put_p(lc.data);
  END LOOP;
 END;
 -----------------------------------------------------------------------------------------------------------------------
  --Первичные данные для канала (УППД)
 PROCEDURE report19_p(an_type NUMBER) IS
  CURSOR lcur_sel IS
   SELECT   w.mid mid, w.date_time date_time, w.nsort n, w.vdata data, p.vname name
       FROM lg_loadprof w, channels p
      WHERE w.mid IN (SELECT     mid
                            FROM points
                      CONNECT BY PRIOR mid = parent
                      START WITH mid = filereport_pg.gn_group OR (filereport_pg.gn_group IS NULL AND parent IS NULL))
        AND w.mid = p.cid(+)
        AND w.date_time >= filereport_pg.gd_from
        AND w.date_time <= filereport_pg.gd_till
   ORDER BY w.mid, w.date_time, w.nsort;
  CURSOR lcur_sel1 IS
   SELECT   w.mid mid, w.date_time date_time, w.nsort n, w.vdata data, p.vname name
       FROM lg_readout w, channels p
      WHERE w.mid IN (SELECT     mid
                            FROM points
                      CONNECT BY PRIOR mid = parent
                      START WITH mid = filereport_pg.gn_group OR (filereport_pg.gn_group IS NULL AND parent IS NULL))
        AND w.mid = p.cid(+)
        AND w.date_time >= filereport_pg.gd_from
        AND w.date_time <= filereport_pg.gd_till
   ORDER BY w.mid, w.date_time, w.nsort;
  ln_curr NUMBER DEFAULT -1;
  ld_curr DATE;
 BEGIN
  filereport_pg.put_p('    Первичные данные для канала по объекту: '|| filereport_pg.gv_name);
  filereport_pg.put_p(
   '    начиная с '|| TO_CHAR(filereport_pg.gd_from, 'dd.mm.yyyy hh24:mi:ss') || ' по ' ||
   TO_CHAR(filereport_pg.gd_till, 'dd.mm.yyyy hh24:mi:ss'));
  filereport_pg.put_p('');
  IF an_type IS NULL THEN
   FOR lc IN lcur_sel LOOP
    IF lc.mid <> ln_curr OR ld_curr <> lc.date_time THEN
     filereport_pg.put_p(RPAD('-', 80, '-'));
     filereport_pg.put_p('Канал:  '|| lc.name);
     filereport_pg.put_p('Дата:   '|| TO_CHAR(lc.date_time, 'dd.mm.yyyy hh24:mi:ss'));
     filereport_pg.put_p(RPAD('-', 80, '-'));
     ln_curr := lc.mid;
     ld_curr := lc.date_time;
    END IF;
    filereport_pg.put_p(lc.data);
   END LOOP;
  ELSE
   FOR lc IN lcur_sel1 LOOP
    IF lc.mid <> ln_curr OR ld_curr <> lc.date_time THEN
     filereport_pg.put_p(RPAD('-', 80, '-'));
     filereport_pg.put_p('Канал:  '|| lc.name);
     filereport_pg.put_p('Дата:   '|| TO_CHAR(lc.date_time, 'dd.mm.yyyy hh24:mi:ss'));
     filereport_pg.put_p(RPAD('-', 80, '-'));
     ln_curr := lc.mid;
     ld_curr := lc.date_time;
    END IF;
    filereport_pg.put_p(lc.data);
   END LOOP;
  END IF;
 END;
