------------------------------------------------------------------------------------------------------------------------
 PROCEDURE report1_p IS
  CURSOR lcur_sel IS
   SELECT c2.mid lg, c1.mid itek   /*,p2.name,p1.name,c2.*,c1.**/
     FROM (SELECT f.mid, ch.cid, f.er_position
             FROM channels ch, chanpoint cp, feeders f
            WHERE ch.protocol_id = 3 AND ch.vname LIKE 'я%' AND ch.blocking = 0 AND ch.cid = cp.cid AND cp.mid = f.mid) c1,
          (SELECT f.mid, ch.cid, f.er_position
             FROM channels ch, chanpoint cp, feeders f
            WHERE ch.protocol_id = 19 AND ch.cid IN (30913, 30787, 30917, 30947, 30919) AND ch.cid = cp.cid AND cp.mid = f.mid) c2,
          points p1,
          points p2
    WHERE DECODE (c1.cid, 31516, 30787, 31629, 30917, 31732, 30913, 31873, 30947, 32040, 30919) = c2.cid AND c1.er_position = c2.er_position AND c1.mid = p1.mid
          AND c2.mid = p2.mid;

  ln_maxdiff   NUMBER DEFAULT 1;
 BEGIN
  FOR lc IN lcur_sel LOOP
   filereport_pg.put_p (lc.lg || ' ' || lc.itek);
  END LOOP;
 END;

-----------------------------------------------------------------------------------------------------------------------
--Тестирование потерь
 PROCEDURE report2_p IS
  CURSOR lcur_sel IS
   SELECT   p.mid, p.NAME, NVL (f.nrecompens, 0) nrecompens, NVL (t.nratio, 0) nratio
       FROM points p, feeders f, recompens t
      WHERE p.mid IN (SELECT     mid
                            FROM GROUPS
                           WHERE mid IS NOT NULL
                      CONNECT BY PRIOR gid = PARENT
                      START WITH gid = filereport_pg.gn_group) AND p.mid = f.mid(+) AND f.nrecompens = t.nrecompens(+)
   ORDER BY p.NAME;

  ln_er      NUMBER;
  ln_per     NUMBER;
  ln_ser     NUMBER;
  ln_sper    NUMBER;
  ln_ed      NUMBER;
  ln_ped     NUMBER;
  ln_sed     NUMBER;
  ln_sped    NUMBER;
  ln_q1      NUMBER;
  ln_pq1     NUMBER;
  ln_sq1     NUMBER;
  ln_spq1    NUMBER;
  ln_q3      NUMBER;
  ln_sq3     NUMBER;
  ln_pq3     NUMBER;
  ln_spq3    NUMBER;
  ld_start   DATE   DEFAULT TRUNC (filereport_pg.gd_from);
 BEGIN
  FOR lc IN lcur_sel LOOP
   filereport_pg.put_p (lc.NAME);
   filereport_pg.put_p ('----------------------------------------------------');
   filereport_pg.put_p ('   ' || '|' || '     ER    ' || '|' || '   PER     ' || '|' || '   ER+PER  ' || '|' || '     ED    ' || '|' || '   PED     ' || '|'
                        || '   ED+PED  ' || '|' || '     Q1    ' || '|' || '   PQ1     ' || '|' || '   Q1+PQ1  ' || '|' || '     Q3    ' || '|' || '   PQ3     '
                        || '|' || '   Q3+PQ3  ' || '|' || '    delta1     ' || '|' || '  delta2       ' || '|');
   filereport_pg.put_p ('----------------------------------------------------');
   ln_ser := 0;
   ln_sed := 0;
   ln_sper := 0;
   ln_sped := 0;
   ln_sq1 := 0;
   ln_sq3 := 0;
   ln_spq1 := 0;
   ln_spq3 := 0;

   FOR i IN 0 .. 23 LOOP
    ln_per := pointcalc_pg.f_defwaste (ld_start + i / 24, ld_start + (i + 1) / 24, lc.mid, NULL, 1, 1);
    ln_ped := pointcalc_pg.f_defwaste (ld_start + i / 24, ld_start + (i + 1) / 24, lc.mid, NULL, 1, 0);
    ln_pq1 := pointcalc_pg.f_defwaste (ld_start + i / 24, ld_start + (i + 1) / 24, lc.mid, NULL, 0, 1);
    ln_pq3 := pointcalc_pg.f_defwaste (ld_start + i / 24, ld_start + (i + 1) / 24, lc.mid, NULL, 0, 0);

    SELECT NVL (SUM (er), 0), NVL (SUM (ed), 0), NVL (SUM (q1), 0), NVL (SUM (q3), 0)
      INTO ln_er, ln_ed, ln_q1, ln_q3
      FROM halfhour
     WHERE mid = lc.mid AND date_time > ld_start + i / 24 AND date_time <= ld_start + (i + 1) / 24;

    IF lc.nrecompens > 0 THEN
     ln_q1 := ln_er * lc.nratio;
     ln_q3 := ln_ed * lc.nratio;
    END IF;

    filereport_pg.put_p (TO_CHAR (i + 1, '00') || '|' || TO_CHAR (ln_er, '9999999990') || '|' || TO_CHAR (ln_per, '9999999990') || '|'
                         || TO_CHAR (ln_er + ln_per, '9999999990') || '|' || TO_CHAR (ln_ed, '9999999990') || '|' || TO_CHAR (ln_ped, '9999999990') || '|'
                         || TO_CHAR (ln_ed + ln_ped, '9999999990') || '|' || TO_CHAR (ln_q1, '9999999990') || '|' || TO_CHAR (ln_pq1, '9999999990') || '|'
                         || TO_CHAR (ln_q1 + ln_pq1, '9999999990') || '|' || TO_CHAR (ln_q3, '9999999990') || '|' || TO_CHAR (ln_pq3, '9999999990') || '|'
                         || TO_CHAR (ln_q3 + ln_pq3, '9999999990') || '|' || TO_CHAR (ln_er * ln_er + ln_q1 * ln_q1, '99999999999990') || '|'
                         || TO_CHAR (ln_ed * ln_ed + ln_q3 * ln_q3, '99999999999990') || '|');
    ln_ser := ln_ser + ln_er;
    ln_sed := ln_sed + ln_ed;
    ln_sper := ln_sper + ln_per;
    ln_sped := ln_sped + ln_ped;
    ln_sq1 := ln_sq1 + ln_q1;
    ln_sq3 := ln_sq3 + ln_q3;
    ln_spq1 := ln_spq1 + ln_pq1;
    ln_spq3 := ln_spq3 + ln_pq3;
   END LOOP;

   filereport_pg.put_p ('ИТ |' || TO_CHAR (ln_ser, '9999999990') || '|' || TO_CHAR (ln_sper, '9999999990') || '|' || TO_CHAR (ln_ser + ln_sper, '9999999990') || '|'
                        || TO_CHAR (ln_sed, '9999999990') || '|' || TO_CHAR (ln_sped, '9999999990') || '|' || TO_CHAR (ln_sed + ln_sped, '9999999990') || '|'
                        || TO_CHAR (ln_sq1, '9999999990') || '|' || TO_CHAR (ln_spq1, '9999999990') || '|' || TO_CHAR (ln_sq1 + ln_spq1, '9999999990') || '|'
                        || TO_CHAR (ln_sq3, '9999999990') || '|' || TO_CHAR (ln_spq3, '9999999990') || '|' || TO_CHAR (ln_sq3 + ln_spq3, '9999999990') || '|'
                        || TO_CHAR (ln_ser * ln_ser + ln_sq1 * ln_sq1, '99999999999990') || '|' || TO_CHAR (ln_sed * ln_sed + ln_sq3 * ln_sq3, '99999999999990')
                        || '|');
   ln_per := pointcalc_pg.f_defwaste (ld_start, ld_start + 1, lc.mid, NULL, 1, 1);
   ln_ped := pointcalc_pg.f_defwaste (ld_start, ld_start + 1, lc.mid, NULL, 1, 0);
   ln_pq1 := pointcalc_pg.f_defwaste (ld_start, ld_start + 1, lc.mid, NULL, 0, 1);
   ln_pq3 := pointcalc_pg.f_defwaste (ld_start, ld_start + 1, lc.mid, NULL, 0, 0);

   SELECT NVL (SUM (er), 0), NVL (SUM (ed), 0), NVL (SUM (q1), 0), NVL (SUM (q3), 0)
     INTO ln_er, ln_ed, ln_q1, ln_q3
     FROM halfhour
    WHERE mid = lc.mid AND date_time > TRUNC (filereport_pg.gd_from) AND date_time <= TRUNC (filereport_pg.gd_from) + 1;

   IF lc.nrecompens >= 0 THEN
    ln_q1 := ln_er * lc.nratio;
    ln_q3 := ln_ed * lc.nratio;
   END IF;

   filereport_pg.put_p (TO_CHAR (0, '00') || '|' || TO_CHAR (ln_er, '9999999990') || '|' || TO_CHAR (ln_per, '9999999990') || '|'
                        || TO_CHAR (ln_er + ln_per, '9999999990') || '|' || TO_CHAR (ln_ed, '9999999990') || '|' || TO_CHAR (ln_ped, '9999999990') || '|'
                        || TO_CHAR (ln_ed + ln_ped, '9999999990') || '|' || TO_CHAR (ln_q1, '9999999990') || '|' || TO_CHAR (ln_pq1, '9999999990') || '|'
                        || TO_CHAR (ln_q1 + ln_pq1, '9999999990') || '|' || TO_CHAR (ln_q3, '9999999990') || '|' || TO_CHAR (ln_pq3, '9999999990') || '|'
                        || TO_CHAR (ln_q3 + ln_pq3, '9999999990') || '|' || TO_CHAR (ln_er * ln_er + ln_q1 * ln_q1, '99999999999990') || '|'
                        || TO_CHAR (ln_ed * ln_ed + ln_q3 * ln_q3, '99999999999990') || '|');
  END LOOP;
 END;

