 PROCEDURE report3_p IS
  CURSOR lcur_sel IS
   SELECT   pa.NAME podst, p.NAME fid, DECODE (halfhour, NULL, 'НЕТ', TO_CHAR (halfhour, 'DD.MM.YYYY HH24:MI')) dat
       FROM points p,
            points pa,
            (SELECT *
               FROM last_save
              WHERE halfhour >= TO_DATE ('22.05.2003', 'dd.mm.yyyy')) l
      WHERE p.mid IN (SELECT mid
                        FROM chanpoint) AND p.PARENT = pa.mid AND p.mid = l.mid(+)
   ORDER BY pa.NAME, p.NAME;
 BEGIN
  filereport_pg.put_p ('                 Контроль опроса на ' || TO_DATE (SYSDATE, 'DD.MM.YYYY HH24:MI'));
  filereport_pg.put_p ('+' || RPAD ('-', 74, '-') || '+');
  filereport_pg.put_p ('|' || RPAD ('Подстанция', 24) || '|' || RPAD ('Точка учета', 32) || '|' || RPAD ('Дата опроса', 16) || '|');
  filereport_pg.put_p ('+' || RPAD ('-', 74, '-') || '+');

  FOR lc IN lcur_sel LOOP
   filereport_pg.put_p ('|' || RPAD (lc.podst, 24) || '|' || RPAD (lc.fid, 32) || '|' || RPAD (lc.dat, 16) || '|');
  END LOOP;

  filereport_pg.put_p ('+' || RPAD ('-', 74, '-') || '+');
 END;

-----------------------------------------------------------------------------------------------------------------------
 PROCEDURE report4_p IS
  ld_from           DATE                DEFAULT util_pg.trunchh24_2 (filereport_pg.gd_from);
  ld_till           DATE                DEFAULT util_pg.trunchh24_2 (filereport_pg.gd_till);
  lv_tab   CONSTANT VARCHAR2 (1)        := CHR (9);

  CURSOR lcur_sel IS
   SELECT   p.mid, p.NAME NAME, p1.NAME pname
       FROM points p, points p1
      WHERE p.mid IN (SELECT     mid
                            FROM GROUPS
                      CONNECT BY PRIOR gid = PARENT
                      START WITH gid = filereport_pg.gn_group) AND p.PARENT = p1.mid(+)
   ORDER BY p1.NAME, p.NAME;

  CURSOR lcur_sel1 (lc_mid NUMBER) IS
   SELECT   util_pg.trunchh24_2 (date_time - 1 / 86400) + 1 / 48 dt, SUM (er) er, SUM (ed) ed, SUM (q1) q1, SUM (q3) q3
       FROM halfhour
      WHERE mid = lc_mid AND date_time > ld_from AND date_time <= ld_till
   GROUP BY util_pg.trunchh24_2 (date_time - 1 / 86400) + 1 / 48;

  lt_er             common_pg.tt_number;
  lt_ed             common_pg.tt_number;
  lt_q1             common_pg.tt_number;
  lt_q3             common_pg.tt_number;
  ln_er             NUMBER;
  ln_ed             NUMBER;
  ln_q1             NUMBER;
  ln_q3             NUMBER;
  ln_ser            NUMBER;
  ln_sed            NUMBER;
  ln_sq1            NUMBER;
  ln_sq3            NUMBER;
  ln_cn             NUMBER;
  ln_k              NUMBER;
  ln_off            NUMBER              DEFAULT 0;
 BEGIN
  ln_cn := 48 * (ld_till - ld_from);

  IF ld_from = TRUNC (ld_from, 'HH24') THEN
   ln_off := 1;
  END IF;

  FOR lc IN lcur_sel LOOP
   filereport_pg.put_p ('Подстанция:  ' || lc.pname);
   filereport_pg.put_p ('Точка:  ' || lc.NAME);
   filereport_pg.put_p ('За период с ' || TO_CHAR (ld_from, 'dd.mm.yyyy hh24:mi') || ' по ' || TO_CHAR (ld_till, 'dd.mm.yyyy hh24:mi'));
   filereport_pg.put_p (RPAD ('-', 70, '-'));
   filereport_pg.put_p ('Дата       ' || lv_tab || 'Время' || lv_tab || 'A+' || lv_tab || 'A+' || lv_tab || 'A-' || lv_tab || 'A-' || lv_tab || 'R+' || lv_tab
                        || 'R+' || lv_tab || 'R-' || lv_tab || 'R-');
   filereport_pg.put_p (RPAD ('-', 70, '-'));
   ln_ser := 0;
   ln_sed := 0;
   ln_sq1 := 0;
   ln_sq3 := 0;

   FOR i IN 1 .. ln_cn LOOP
    lt_er (i) := NULL;
    lt_ed (i) := NULL;
    lt_q1 (i) := NULL;
    lt_q3 (i) := NULL;
   END LOOP;

   FOR lc1 IN lcur_sel1 (lc.mid) LOOP
    ln_k := 48 * (lc1.dt - ld_from);
    lt_er (ln_k) := lc1.er;
    lt_ed (ln_k) := lc1.ed;
    lt_q1 (ln_k) := lc1.q1;
    lt_q3 (ln_k) := lc1.q3;
    ln_ser := ln_ser + lc1.er;
    ln_sed := ln_sed + lc1.ed;
    ln_sq1 := ln_sq1 + lc1.q1;
    ln_sq3 := ln_sq3 + lc1.q3;
   END LOOP;

   FOR i IN 1 .. ln_cn LOOP
    IF i > 1 AND MOD (i + ln_off, 2) = 1 THEN
     ln_er := util_pg.nvlsum (lt_er (i), lt_er (i - 1));
     ln_ed := util_pg.nvlsum (lt_ed (i), lt_ed (i - 1));
     ln_q1 := util_pg.nvlsum (lt_q1 (i), lt_q1 (i - 1));
     ln_q3 := util_pg.nvlsum (lt_q3 (i), lt_q3 (i - 1));
    ELSE
     ln_er := NULL;
     ln_ed := NULL;
     ln_q1 := NULL;
     ln_q3 := NULL;
    END IF;

    filereport_pg.put_p (TO_CHAR (ld_from + i / 48, 'dd.mm.yyyy') || lv_tab || TO_CHAR (ld_from + i / 48, 'HH24:MI') || lv_tab || lt_er (i) || lv_tab || ln_er
                         || lv_tab || lt_ed (i) || lv_tab || ln_ed || lv_tab || lt_q1 (i) || lv_tab || ln_q1 || lv_tab || lt_q3 (i) || lv_tab || ln_q3);
   END LOOP;

   filereport_pg.put_p (RPAD ('-', 70, '-'));
   filereport_pg.put_p ('Итого:' || lv_tab || lv_tab || ln_ser || lv_tab || ln_ser || lv_tab || ln_sed || lv_tab || ln_sed || lv_tab || ln_sq1 || lv_tab || ln_sq1
                        || lv_tab || ln_sq3 || lv_tab || ln_sq3);
   filereport_pg.put_p (RPAD ('-', 70, '-'));
   filereport_pg.put_p ('');
  END LOOP;
 END;

