 PROCEDURE report5_p IS
  ld_from           DATE         DEFAULT filereport_pg.gd_from;
  ld_till           DATE         DEFAULT filereport_pg.gd_till;
  lv_tab   CONSTANT VARCHAR2 (1) := CHR (9);
  ln_r              NUMBER       DEFAULT 5;

  CURSOR lcur_sel IS
   SELECT   p.mid, p.NAME NAME, p1.NAME pname
       FROM points p, points p1
      WHERE p.mid IN (SELECT     mid
                            FROM GROUPS
                      CONNECT BY PRIOR gid = PARENT
                      START WITH gid = filereport_pg.gn_group) AND p.PARENT = p1.mid(+)
   ORDER BY p1.NAME, p.NAME;

  CURSOR lcur_sel1 (lc_mid NUMBER) IS
   SELECT   date_time, er, ed, q1, q3, erm, edm, q1m, q3m
       FROM curr_power_arch
      WHERE mid = lc_mid AND date_time > ld_from AND date_time <= ld_till
   ORDER BY date_time;
 BEGIN
  FOR lc IN lcur_sel LOOP
   filereport_pg.put_p ('Подстанция:  ' || lc.pname);
   filereport_pg.put_p ('Точка:  ' || lc.NAME);
   filereport_pg.put_p ('За период с ' || TO_CHAR (ld_from, 'dd.mm.yyyy hh24:mi') || ' по ' || TO_CHAR (ld_till, 'dd.mm.yyyy hh24:mi'));
   filereport_pg.put_p (RPAD ('-', 50, '-'));
   filereport_pg.put_p ('Дата       ' || lv_tab || 'A+' || lv_tab || 'A+' || lv_tab || 'A-' || lv_tab || 'A-' || lv_tab || 'R+' || lv_tab || 'R+' || lv_tab || 'R-'
                        || lv_tab || 'R-');
   filereport_pg.put_p (RPAD ('-', 50, '-'));

   FOR lc1 IN lcur_sel1 (lc.mid) LOOP
    filereport_pg.put_p (TO_CHAR (lc1.date_time, 'dd.mm.yyyy hh24:mi:ss') || lv_tab || TO_CHAR (ROUND (lc1.erm, ln_r), '9990.00000') || lv_tab
                         || TO_CHAR (ROUND (lc1.er * 1000, ln_r), '99990.00') || lv_tab || TO_CHAR (ROUND (lc1.edm, ln_r), '9990.00000') || lv_tab
                         || TO_CHAR (ROUND (lc1.ed * 1000, ln_r), '99990.00') || lv_tab || TO_CHAR (ROUND (lc1.q1m, ln_r), '9990.00000') || lv_tab
                         || TO_CHAR (ROUND (lc1.q1 * 1000, ln_r), '99990.00') || lv_tab || TO_CHAR (ROUND (lc1.q3m, ln_r), '9990.00000') || lv_tab
                         || TO_CHAR (ROUND (lc1.q3 * 1000, ln_r), '99990.00'));
   END LOOP;

   filereport_pg.put_p (RPAD ('-', 50, '-'));
   filereport_pg.put_p ('');
  END LOOP;
 END;

