 PROCEDURE report13_p IS
  CURSOR lcur_sel IS
   SELECT --DECODE(monitoring_pg.get_group_point_status_f(NVL(g.mid, 0), filereport_pg.gd_from, 2, 0, 0, 0), 0, ' ', '*') f,
          CASE WHEN g.mid IS NULL THEN ' '
               WHEN halfhour IS NULL THEN '*'
               WHEN halfhour < filereport_pg.gd_from THEN '*'
               ELSE ' '
          END f,
          LPAD(' ', (lev - 1) * 5, ' ') || name n, TO_CHAR(halfhour, 'dd.mm.yyyy hh24:mi:ss') d, v
     FROM
