           START WITH gg.gid = filereport_pg.gn_group) g;
 BEGIN
  filereport_pg.put_p(
   ' Отчет об отсутствии получасовых данных по точкам на '|| TO_CHAR(filereport_pg.gd_from, 'dd.mm.yyyy hh24:mi:ss'));
  filereport_pg.put_p('');
  filereport_pg.put_p(' выполнен '|| TO_CHAR(SYSDATE, 'dd.mm.yyyy hh24:mi:ss'));
  filereport_pg.put_p('');
  FOR lc IN lcur_sel LOOP
   filereport_pg.put_p(RPAD(lc.n, 70) || ' | ' || lc.f || ' | ' || RPAD(NVL(lc.d,' '), 19) || ' | ' || lc.v);
  END LOOP;
 END;

