-----------------------------------------------------------------------------------------------------------------------
 PROCEDURE report13_2_p IS
    gname           VARCHAR2 (150);
    point_cnt       NUMBER;
    f_cnt           NUMBER;
    vf              NUMBER;
    f_vf            NUMBER;
 BEGIN
    SELECT name INTO gname FROM points WHERE mid=1000;
    filereport_pg.put_p(
        ' Статистика опроса точек учета по группам с '|| TO_CHAR(filereport_pg.gd_from, 'dd.mm.yyyy hh24:mi:ss') ||' по '|| TO_CHAR(filereport_pg.gd_till, 'dd.mm.yyyy hh24:mi:ss') ||' '|| LPAD(TO_CHAR(gname), 32));
    filereport_pg.put_p('');
    filereport_pg.put_p(' выполнен '|| TO_CHAR(SYSDATE, 'dd.mm.yyyy hh24:mi:ss'));
    filereport_pg.put_p('');
    filereport_pg.put_p(RPAD('-',108,'-'));
    filereport_pg.put_p('|                                     |           |                                   |                    |');
    filereport_pg.put_p('|                                     |   Общее   |    Неопрашиваются точки учета     |                    |');
    filereport_pg.put_p('|             Наименование            |   кол-во  |-----------------------------------|                    |');
    filereport_pg.put_p('|              подстанции             |   точек   |           | Из них по |  Причина  |     Примечание     |');
    filereport_pg.put_p('|                                     |   учета   |   Всего   | известной | выясняется|                    |');
    filereport_pg.put_p('|                                     |           |           |  причине  |           |                    |');
    filereport_pg.put_p(RPAD('-',108,'-'));
    
    FOR lc IN (SELECT gid, name FROM groups WHERE parent=filereport_pg.gn_group ORDER BY name) LOOP
        gname := lc.name;
        SELECT  COUNT(*), 
                SUM(f), 
                SUM(SIGN(NVL(v, 0))*f), 
                SUM(f) - SUM(SIGN(NVL(v, 0))*f) 
        INTO    point_cnt, f_cnt, vf, f_vf
        FROM (
                SELECT  g.gid, g.mid, ls.halfhour,
                        CASE WHEN ls.halfhour IS NULL THEN 1
                             WHEN ls.halfhour < filereport_pg.gd_from THEN 1
                             ELSE 0
                        END f,
                        (SELECT LENGTH(NVL(vvalue, 0)) FROM addpointparamval WHERE mid=g.mid and nsort=0) v
                FROM groups g, last_save ls
                WHERE g.mid = ls.mid(+) AND g.gid IN (
                            SELECT gid FROM groups WHERE mid IS NOT NULL CONNECT BY PRIOR gid = parent
                                                    START WITH gid = lc.gid)
            );
                
        filereport_pg.put_p('| ' || RPAD(NVL(gname, ' '), 35) || ' | ' || LPAD(NVL(TO_CHAR(point_cnt, '99999999'), ' '), 9) || ' | ' || LPAD(NVL(TO_CHAR(f_cnt, '99999999'), ' '), 9) || ' | ' || LPAD(NVL(TO_CHAR(vf, '99999999'), ' '), 9) || ' | ' || LPAD(NVL(TO_CHAR(f_vf, '99999999'), ' '), 9) || ' | ' || RPAD(' ', 18) || ' |');
        
    END LOOP;
    filereport_pg.put_p(RPAD('-',108,'-'));
 END; --PROCEDURE report13_2_p
