 --Универсальная - показывает все макеты (расчетная) за период
 PROCEDURE report17_p IS
 BEGIN
  FOR lc IN (SELECT m.*
               FROM makets m, deportprocedures d
              WHERE m.nmaket = filereport_pg.gn_group AND filereport_pg.gn_ispoint = 1 AND m.nprocedure = d.nprocedure AND d.ntype = 0) LOOP
   file_pg.startrep_p (lc.nmaket, filereport_pg.gd_from, lc.vparam);
  END LOOP;
 END;
------------------------------------------------------------------------------------------------------------------------
