             RPAD(NVL(TO_CHAR(c1_rec.fact), ' '), 10) || '!' || RPAD(NVL(TO_CHAR(c1_rec.nmustbe, '99999999'), ' '), 11) ||
             '!' || RPAD(NVL(TO_CHAR(c1_rec.nindeed, '99999999'), ' '), 11) || '!';
