 PROCEDURE p_checkmtrsn IS
  CURSOR lcur_1 IS
   SELECT   b.date_time ddate, pa.name pstan_name, p.name point_name, m.mtrsn nsi, b.er_mtrsn fact
       FROM meters m,
            (SELECT   MAX(date_time) date_time, mid, er_mtrsn
                 FROM billorg
                WHERE date_time >= TRUNC(filereport_pg.gd_from) AND date_time < TRUNC(filereport_pg.gd_till) + 1
             GROUP BY mid, er_mtrsn) b,
            points p, points pa
      WHERE b.mid = m.mid
        AND m.mid IN (SELECT mid
                        FROM chanpoint)
        AND (LPAD(m.mtrsn, 100, '0') <> LPAD(b.er_mtrsn, 100, '0') OR (m.mtrsn IS NULL AND b.er_mtrsn IS NOT NULL))
        AND b.mid = p.mid(+)
        AND p.parent = pa.mid(+)
        AND m.mid IN (SELECT     mid
                            FROM groups
                      CONNECT BY PRIOR gid = parent
                      START WITH gid = filereport_pg.gn_group AND filereport_pg.gn_ispoint = 0
                      UNION ALL
                      SELECT     mid
                            FROM points
                      CONNECT BY PRIOR mid = parent
                      START WITH mid = filereport_pg.gn_group AND filereport_pg.gn_ispoint = 1)
   ORDER BY 1 DESC, 2, 3;
  -------------------------
  t1_tab common_pg.tt_varchar2;
  lv_str VARCHAR2(265);
  lv_t1  VARCHAR2(265)         DEFAULT LPAD('-', 100, '-');
 -----------------------
 BEGIN
  filereport_pg.put_p(
   TO_CHAR(SYSDATE, 'dd.mm.yyyy') || '             Сверка номера устройства с данными НСИ за период с ' ||
   TO_CHAR(filereport_pg.gd_from, 'DD.MM.YYYY') || ' по ' || TO_CHAR(filereport_pg.gd_till, 'DD.MM.YYYY'));
  filereport_pg.put_p(TO_CHAR(SYSDATE, '  hh24:mi:ss') || '                       по группе ' || filereport_pg.gv_name);
  filereport_pg.put_p(' ');
  t1_tab(1) := lv_t1;
  t1_tab(2) := '     Дата       ! Наименование подстанции !   Наименование точки учета   !     НСИ    !    Факт    !';
  t1_tab(3) := lv_t1;
  FOR i IN 1 .. 3 LOOP
   filereport_pg.setheaderrow_p(t1_tab(i), i); --Заполняем таблицу gt_header
  END LOOP;
  t1_tab.DELETE;
  filereport_pg.setuseheader_p(TRUE);
  filereport_pg.printheader_p; --Печатаем таблицу gt_header
  FOR c1_rec IN lcur_1 LOOP
   lv_str := TO_CHAR(c1_rec.ddate, 'dd.mm.yyyy hh24:mi') || '!' || RPAD(NVL(SUBSTR(c1_rec.pstan_name, 1, 25), ' '), 25) ||
             '!' || RPAD(NVL(SUBSTR(c1_rec.point_name, 1, 30), ' '), 30) || '!' || LPAD(NVL(c1_rec.nsi, ' '), 12) || '!' ||
             LPAD(NVL(c1_rec.fact, ' '), 12) || '!';
   filereport_pg.put_p(lv_str);
  END LOOP;
  filereport_pg.put_p(lv_t1);
