 PROCEDURE p_balance_ IS
    gname           VARCHAR2 (150);
    pname           VARCHAR2 (150);
    sum_er          NUMBER;
    sum_ed          NUMBER;
    nbalance        NUMBER;
    pbalance        NUMBER;
    check_Err_Ok    VARCHAR2 (12);
 BEGIN
    select name into gname from points where mid=1000;
    filereport_pg.put_p(
        ' Отчет о балансах по получасовым данным и балансным группам с '|| TO_CHAR(filereport_pg.gd_from, 'dd.mm.yyyy hh24:mi:ss') ||' по '|| TO_CHAR(filereport_pg.gd_till, 'dd.mm.yyyy hh24:mi:ss') ||' '|| LPAD(TO_CHAR(gname), 32));
    filereport_pg.put_p('');
    filereport_pg.put_p(' выполнен '|| TO_CHAR(SYSDATE, 'dd.mm.yyyy hh24:mi:ss'));
    filereport_pg.put_p('');
    filereport_pg.put_p(RPAD('-',138,'-'));
    filereport_pg.put_p('|                                     |                                     |           |           |           |           |              ');
    filereport_pg.put_p('|            Наименование             |             Наименование            |   Приём   |  Отдача   |  Небаланс |  Небаланс | Примечание   ');
    filereport_pg.put_p('|        родительской группы          |           балансной группы          |   кВт*ч   |   кВт*ч   |   кВт*ч   |     %     |              ');
    filereport_pg.put_p('|                                     |                                     |           |           |           |           |              ');
    filereport_pg.put_p(RPAD('-',138,'-'));

    for lc in (select distinct gp.gid, gp.name from groups gp, groups gg where gp.gid=gg.parent and LOWER(gg.vparam) like '%баланс%' order by gp.name) loop
        pname := lc.name;
        for lcc in (select gid, name from groups where parent=lc.gid order by name) loop
            gname := lcc.name;
            select  SUM(er),
                    SUM(ed),
                    DECODE(SIGN(util_pg.get_countpoint_f(lcc.gid,0) - COUNT(distinct mid)),1,'Неполный','Ok')
               into sum_er, sum_ed, check_Err_Ok
            from (
                select  h.mid, 
                        NVL(DECODE(g.inverted, 'y', h.ed*DECODE (g.npartly, 1, 0, 1), h.er*DECODE (g.npartly, 2, 0, 1)), 0) er,
                        NVL(DECODE(g.inverted, 'y', h.er*DECODE (g.npartly, 1, 0, 1), h.ed*DECODE (g.npartly, 2, 0, 1)), 0) ed
                from halfhourold h, groups g
                where h.nexceptcalc is NULL and h.nsource > 0
                and h.date_time > filereport_pg.gd_from
                and h.date_time <= filereport_pg.gd_till
                and h.mid=g.mid
                and g.gid in (select gid from groups where mid is not NULL
                                connect by prior gid=parent start with gid=lcc.gid)
                
                );
 
            nbalance := sum_er - sum_ed;
            if sum_er = 0 
                then pbalance := 0; 
                else pbalance := nbalance/sum_er*100; 
            end if;

            filereport_pg.put_p('| ' || RPAD(NVL(pname, ' '), 35) || ' | ' || RPAD(NVL(gname, ' '), 35) || ' |' || LPAD(NVL(TO_CHAR(ROUND(sum_er), '999999999'), ' '), 10) || ' |' || LPAD(NVL(TO_CHAR(ROUND(sum_ed), '999999999'), ' '), 10) || ' |' || LPAD(NVL(TO_CHAR(ROUND(nbalance), '999999999'), ' '), 10) || ' |' || LPAD(NVL(TO_CHAR(ROUND(pbalance,3), '99999.999'), ' '), 10) || ' | ' || RPAD(NVL(TO_CHAR(check_Err_Ok), ' '), 12));

        end loop;
    end loop;
    filereport_pg.put_p(RPAD('-',138,'-'));
 END; --PROCEDURE p_balance_
------------------------------------------------------------------------------------------------------------------------
END; --PACKAGE BODY
/


