CREATE OR REPLACE 
PACKAGE BODY pointcalc_pg IS
 /*Если установлены режим работы присоединения (nWorkingHours, nShifts) и (или)
 время его включения (nFullHours), для текущего месяца (в ssConnectionParamFullHours)
 или постоянный (в ssConnectionParam), то для расчета потерь используются эти значения.
 Если установлены режимы работы точек, подключенных к присоединению (nWorkTimeType,
 nWorkingHours, nDayHours), и (или) времена их включения (nFullHours), для текущего месяца
 (в ssPointFullHours) или постоянные (в ssPointI), то для расчета потерь используются
 максимальные не равные нулю по величине режим работы и времена включения этих точек.
 Равенство нулю режима работы или времени включения одной из этих точек означает
 равенство нулю режима работы и (или) времени включения, использующегося для расчета потерь.
 Иначе для расчета потерь в качестве режима работы и времени включения используются календарные
 часы месяца расчета.
 Режим работы, использующийся для расчета потерь, меньше или равен времени включения,
 использующегося для расчета потерь.*/
 ------------------------------------------------------------------------------------------------
 PROCEDURE p_setpotercoef(an_reznew IN OUT tr_potercoef, an_coef IN NUMBER) IS
 BEGIN
  an_reznew.z := an_coef;
  an_reznew.z1 := an_coef;
  an_reznew.z2 := an_coef;
  an_reznew.z3 := an_coef;
  an_reznew.h := an_coef;
  an_reznew.d := an_coef;
 END;
 ------------------------------------------------------------------------------------------------
 FUNCTION f_gettypepot(an_point IN NUMBER, an_period IN NUMBER)
  RETURN VARCHAR2 IS
  ln_ret NUMBER;
 BEGIN
  SELECT NVL(MAX(nwastepercentcalc), 0)
    INTO ln_ret
    FROM feeders
   WHERE mid = an_point;
  IF ln_ret = 1 THEN
   RETURN '%';
  ELSIF ln_ret = 2 THEN
   RETURN 'Фп';
  ELSIF ln_ret = 3 THEN
   RETURN '%2';
  ELSE
   SELECT COUNT(*)
     INTO ln_ret
     FROM DUAL
    WHERE EXISTS( SELECT mid
                    FROM connectionparam
                   WHERE mid = an_point
                  UNION ALL
                  SELECT mid
                    FROM sharedconnectionparam
                   WHERE mid = an_point);
   IF ln_ret = 1 THEN
    RETURN 'Ф';
   END IF;
  END IF;
  RETURN 'Н';
 END;
 ------------------------------------------------------------------------------------------------
 FUNCTION f_provvar1(an_parallelconnection NUMBER, an_accperiod NUMBER)
  RETURN NUMBER IS
  ln_ret NUMBER;
  -- Ищем параллельные присоединения
  CURSOR lcur_sel IS
   /*Ищем параллельные присоединения и их время работы (To)*/
   SELECT nconnectionparam
     FROM connectionparam
    WHERE nparallelconnection = an_parallelconnection;
  -- Вытягиваем Ид всех точек по параметру
  CURSOR lcur_p(lc_param IN NUMBER) IS
   SELECT c.mid npoint
     FROM connectionparam c
    WHERE c.nconnectionparam = lc_param AND c.nnotincludeconsump = 0
   UNION ALL
   SELECT c.mid npoint
     FROM sharedconnectionparam c
    WHERE c.nconnectionparam = lc_param AND c.nnotincludeconsump = 0;
 BEGIN
  SELECT COUNT(*)
    INTO ln_ret
    FROM connectionparam
   WHERE nparallelconnection = an_parallelconnection;
  IF ln_ret < 2 THEN
   RETURN 0;
  END IF;
  FOR lc IN lcur_sel LOOP
   FOR lcp IN lcur_p(lc.nconnectionparam) LOOP
    SELECT COUNT(*)
      INTO ln_ret
      FROM DUAL
     WHERE EXISTS( SELECT mid npoint
                     FROM connectionparam
                    WHERE mid = lcp.npoint
                      AND nnotincludeconsump = 0
                      AND nconnectionparam <> lc.nconnectionparam
                      AND nconnectionparam IN (SELECT nconnectionparam
                                                 FROM connectionparam
                                                WHERE nparallelconnection = an_parallelconnection)
                   UNION ALL
                   SELECT mid npoint
                     FROM sharedconnectionparam
                    WHERE mid = lcp.npoint
                      AND nnotincludeconsump = 0
                      AND nconnectionparam <> lc.nconnectionparam
                      AND nconnectionparam IN (SELECT nconnectionparam
                                                 FROM connectionparam
                                                WHERE nparallelconnection = an_parallelconnection));
    IF ln_ret > 0 THEN
     RETURN 1;
    END IF;
   END LOOP;
  END LOOP;
  RETURN 0;
 END;
 ------------------------------------------------------------------------------------------------
 ------------------------------------------------------------------------------------------------
 ------------------------------------------------------------------------------------------------
 FUNCTION f_getparallelproc(an_parallelconnection NUMBER, an_accperiod NUMBER, an_currentt0 NUMBER)
  RETURN NUMBER IS
  ln_ret      NUMBER;
  ln_daycount NUMBER DEFAULT TO_NUMBER(TO_CHAR(LAST_DAY(TO_DATE(an_accperiod, 'YYYYMM')), 'DD')); --Кол-во дней в месяце
  ln_maxt0    NUMBER;
  ln_allt0    NUMBER DEFAULT 0;
  CURSOR lcur_sel IS
   /*Ищем параллельные присоединения и их время работы (To)*/
   SELECT nconnectionparam, nfullhours
     FROM connectionparam
    WHERE nparallelconnection = an_parallelconnection;
  CURSOR lcur_p(lc_param IN NUMBER) IS
   SELECT NVL(ph.nfullhours, pi.nfullhours) nfullhours
     FROM connectionparam c, feeders pi, pointfullhours ph
    WHERE c.nconnectionparam = lc_param
      AND c.mid = pi.mid(+)
      AND pi.mid = ph.mid(+)
      AND an_accperiod = ph.naccperiod(+)
   UNION ALL
   SELECT NVL(ph.nfullhours, pi.nfullhours) nfullhours
     FROM sharedconnectionparam c, feeders pi, pointfullhours ph
    WHERE c.nconnectionparam = lc_param
      AND c.mid = pi.mid(+)
      AND pi.mid = ph.mid(+)
      AND an_accperiod = ph.naccperiod(+);
 BEGIN
  SELECT COUNT(*)
    INTO ln_ret
    FROM connectionparam
   WHERE nparallelconnection = an_parallelconnection;
  IF ln_ret < 2 THEN
   RETURN 1;
  END IF;
  FOR lc IN lcur_sel LOOP
   ln_maxt0 := lc.nfullhours;
   IF ln_maxt0 IS NULL THEN
    FOR lcp IN lcur_p(lc.nconnectionparam) LOOP
     ln_maxt0 := GREATEST(NVL(lcp.nfullhours, ln_maxt0), NVL(ln_maxt0, lcp.nfullhours));
    END LOOP;
   END IF;
   ln_allt0 := ln_allt0 + NVL(ln_maxt0, ln_daycount * 24);
  END LOOP;
  IF ln_allt0 = 0 THEN
   RETURN 0;
  END IF;
  RETURN LEAST(an_currentt0 / ln_allt0, 1); --least(an_CurrentT0,ln_DayCount*24)/least(ln_AllT0,ln_DayCount*24);
 END;
 ------------------------------------------------------------------------------------------------
 -- Считаем расход по всем точкам для всех параллельных параметров
 PROCEDURE p_getsharesconsumption(
  an_parallelconnection        NUMBER,
  an_mid                       NUMBER,
  an_accperiod                 NUMBER,
  an_defdir                    NUMBER,
  an_sa                 IN OUT NUMBER,
  an_sr                 IN OUT NUMBER) IS
  -- Вытягиваем ид палаллельных параметров в которых фигурирует точка
  CURSOR lcur_sel IS
   SELECT c.nconnectionparam
     FROM connectionparam c
    WHERE c.nparallelconnection = an_parallelconnection
      AND EXISTS( SELECT nconnectionparam
                    FROM connectionparam
                   WHERE mid = an_mid AND nconnectionparam = c.nconnectionparam
                  UNION ALL
                  SELECT nconnectionparam
                    FROM sharedconnectionparam
                   WHERE mid = an_mid AND nconnectionparam = c.nconnectionparam);
  -- Вытягиваем параметры точек для конкретного параметра
  CURSOR lcur_p(lc_param IN NUMBER) IS
   SELECT pi.mid npoint, NVL(re.nratio, 0) nratio, pi.nrecompens nmeasurables
     FROM connectionparam c, feeders pi, recompens re
    WHERE c.nconnectionparam = lc_param
      AND c.nnotincludeconsump = 0
      AND c.mid = pi.mid(+)
      AND pi.nrecompens = re.nrecompens(+)
   UNION
   SELECT pi.mid npoint, NVL(re.nratio, 0) nratio, pi.nrecompens nmeasurables
     FROM sharedconnectionparam c, feeders pi, recompens re
    WHERE c.nconnectionparam = lc_param
      AND c.nnotincludeconsump = 0
      AND c.mid = pi.mid(+)
      AND pi.nrecompens = re.nrecompens(+);
  ln_a NUMBER;
  ln_r NUMBER;
 BEGIN
  an_sa := 0;
  an_sr := 0;
  FOR lc IN lcur_sel LOOP -- перебираем все точки для параллельных параметров
   FOR lcp IN lcur_p(lc.nconnectionparam) LOOP
    SELECT NVL(SUM(NVL(DECODE(an_defdir, 1, er, ed), 0) * DECODE(nwasteabs, 1, 0, 1)), 0),
           NVL(SUM(NVL(DECODE(an_defdir, 1, q1, q3), 0) * DECODE(nwasteabs, 1, 0, 1)), 0)
      INTO ln_a,
           ln_r
      FROM bill
     WHERE mid = lcp.npoint
       AND date_time > TO_DATE(an_accperiod, 'YYYYMM')
       AND date_time <= ADD_MONTHS(TO_DATE(an_accperiod, 'YYYYMM'), 1);
    IF lcp.nmeasurables >= 0 THEN
     ln_r := ROUND(ln_a * lcp.nratio);
    END IF;
    an_sa := an_sa + ln_a;
    an_sr := an_sr + ln_r;
   END LOOP;
  END LOOP;
 END;
 ------------------------------------------------------------------------------------------------
 PROCEDURE f_getpoternew(
  lr_potertemp  IN OUT tr_potercoef,
  an_mid               NUMBER,
  an_act               NUMBER,
  an_accperiod         NUMBER,
  an_potrebonly        NUMBER,
  an_defdir            NUMBER) IS
  ln_ratio              NUMBER;
  ln_a                  NUMBER;
  ln_a1                 NUMBER;
  ln_a2                 NUMBER;
  ln_a3                 NUMBER;
  ln_r                  NUMBER;
  ln_r1                 NUMBER;
  ln_r2                 NUMBER;
  ln_r3                 NUMBER;
  ln_pr1                NUMBER;
  ln_pr2                NUMBER;
  ln_measurables        NUMBER;
  ln_s2                 NUMBER;
  ln_sa                 NUMBER;
  ln_sr                 NUMBER;
  ln_count              NUMBER;
  lb_find               BOOLEAN;
  ln_daycount           NUMBER  DEFAULT TO_NUMBER(TO_CHAR(LAST_DAY(TO_DATE(an_accperiod, 'YYYYMM')), 'DD')); --Кол-во дней в месяце
  ln_point_workinghours NUMBER;
  ln_max_workinghours   NUMBER;
  ln_point_t0           NUMBER;
  ln_maxt0              NUMBER;
  ln_procparallel       NUMBER;
  ln_provvar1           NUMBER;
  -----------------------
  CURSOR lcur_sel IS
   /*Ищет всевозможные присоединения и их параметры для расчета потерь,
     где фигурирует точка с ид.=an_mid*/
   SELECT   c.nconnectionparam, NVL(c.nsn, 1) nsn, NVL(nsh, NVL(c.nsn, 1)) nsh, NVL(c.ndeltapidling, 0) ndeltapidling,
            NVL(c.ndeltapsc, 0) ndeltapsc, NVL(c.niidling, 0) niidling, NVL(c.nusc, 0) nusc, NVL(c.nro, 0) nro,
            NVL(c.nxo, 0) nxo, NVL(c.nl, 0) nl, NVL(c.nun, 1) nun,
            (NVL(c.nenergypercent, 100) / 100) nenergypercent,
            NVL(
             ph.nworkinghours, NVL(
                                pfh.nworkinghours, NVL(
                                                    c.nworkinghours, NVL(
                                                                      DECODE(999, 3, 700, 1, 200, 2, 450, NULL),
                                                                      pi.nworkinghours)))) nworkinghours,
            c.nparallelconnection, NVL(ph.nfullhours, NVL(pfh.nfullhours, NVL(c.nfullhours, pi.nfullhours))) nfullhours,
            c.nnotincludeconsump, 1 mainpoint
       FROM connectionparam c, connectionparamfullhours ph, pointfullhours pfh, feeders pi
      WHERE c.mid = an_mid
        AND c.nconnectionparam = ph.nconnectionparam(+)
        AND an_accperiod = ph.naccperiod(+)
        AND c.mid = pfh.mid(+)
        AND an_accperiod = pfh.naccperiod(+)
        AND c.mid = pi.mid(+)
   UNION ALL
   SELECT   c.nconnectionparam, NVL(c.nsn, 1) nsn, NVL(nsh, NVL(c.nsn, 1)) nsh, NVL(c.ndeltapidling, 0) ndeltapidling,
            NVL(c.ndeltapsc, 0) ndeltapsc, NVL(c.niidling, 0) niidling, NVL(c.nusc, 0) nusc, NVL(c.nro, 0) nro,
            NVL(c.nxo, 0) nxo, NVL(c.nl, 0) nl, NVL(c.nun, 1) nun,
            (NVL(c.nenergypercent, 100) / 100) nenergypercent,
            NVL(
             ph.nworkinghours, NVL(
                                pfh.nworkinghours, NVL(
                                                    c.nworkinghours, NVL(
                                                                      DECODE(999, 3, 700, 1, 200, 2, 450, NULL),
                                                                      pi.nworkinghours)))) nworkinghours,
            c.nparallelconnection, NVL(ph.nfullhours, NVL(pfh.nfullhours, NVL(c.nfullhours, pi.nfullhours))) nfullhours,
            s.nnotincludeconsump, 0 mainpoint
       FROM connectionparam c, sharedconnectionparam s, connectionparamfullhours ph, pointfullhours pfh, feeders pi
      WHERE s.mid = an_mid
        AND s.nconnectionparam = c.nconnectionparam(+)
        AND c.nconnectionparam = ph.nconnectionparam(+)
        AND an_accperiod = ph.naccperiod(+)
        AND c.mid = pfh.mid(+)
        AND an_accperiod = pfh.naccperiod(+)
        AND c.mid = pi.mid(+)
   ORDER BY 1;
  CURSOR lcur_p(lc_param NUMBER) IS
   /*Ищем все точки которые участвуют в доле по дележке потерь присоединения
     NNOTINCLUDECONSUMP - отвечает за включение расхода по точке в общее потребление по присоединению*/
   SELECT   mid npoint, nnotincludeconsump
       FROM connectionparam
      WHERE nconnectionparam = lc_param
   UNION ALL
   SELECT   mid npoint, nnotincludeconsump
       FROM sharedconnectionparam
      WHERE nconnectionparam = lc_param
   ORDER BY 1;
  CURSOR lcur_ss(lc_mid IN NUMBER) IS
   SELECT /*Дотягиваем информацию по остальным точкам, участвующим в дележке потерь
            а именно часы работы и наличае счетчиков для ответа на вопрос: Как счмтать
            расход реактивной (по активной или по показаниям реактивной)*/
          NVL(re.nratio, 0) nratio, pi.nrecompens nmeasurables,
          NVL(ph.nworkinghours, pi.nworkinghours) point_workinghours, NVL(ph.nfullhours, pi.nfullhours) nfullhours
     FROM feeders pi, recompens re, pointfullhours ph
    WHERE pi.mid = lc_mid
      AND pi.nrecompens = re.nrecompens(+)
      AND pi.mid = ph.mid(+)
      AND an_accperiod = ph.naccperiod(+)
      --проверка точки на "отлючено"
      AND NOT EXISTS(
                     SELECT mid
                       FROM pointfullhours
                      WHERE naccperiod = an_accperiod AND mid = pi.mid AND nfullhours = 0);
 BEGIN
  p_setpotercoef(lr_potertemp, 0); --Зануляем lr_PoterTemp
  IF an_potrebonly = 1 THEN --мы не считаем потери, а считаем потребление по точке за месяц
   SELECT NVL(SUM(NVL(DECODE(an_defdir, 1, er, ed), 0) * DECODE(nwasteabs, 1, 0, 1)), 0), --Мы игнорируем записи с nWasteabs=1 (по уст. мощности)
          NVL(SUM(NVL(DECODE(an_defdir, 1, aer, aed), 0) * DECODE(nwasteabs, 1, 0, 1)), 0), -- Актив
          NVL(SUM(NVL(DECODE(an_defdir, 1, ber, bed), 0) * DECODE(nwasteabs, 1, 0, 1)), 0),
          NVL(SUM(NVL(DECODE(an_defdir, 1, cer, ced), 0) * DECODE(nwasteabs, 1, 0, 1)), 0),
          NVL(SUM(NVL(DECODE(an_defdir, 1, q1, q3), 0) * DECODE(nwasteabs, 1, 0, 1)), 0),
          NVL(SUM(NVL(DECODE(an_defdir, 1, aq1, aq3), 0) * DECODE(nwasteabs, 1, 0, 1)), 0), -- Рактив
          NVL(SUM(NVL(DECODE(an_defdir, 1, bq1, bq3), 0) * DECODE(nwasteabs, 1, 0, 1)), 0),
          NVL(SUM(NVL(DECODE(an_defdir, 1, cq1, cq3), 0) * DECODE(nwasteabs, 1, 0, 1)), 0)
     INTO ln_a,
          ln_a1,
          ln_a2,
          ln_a3,
          ln_r,
          ln_r1,
          ln_r2,
          ln_r3
     FROM bill
    WHERE mid = an_mid
      AND date_time > TO_DATE(an_accperiod, 'YYYYMM')
      AND date_time <= ADD_MONTHS(TO_DATE(an_accperiod, 'YYYYMM'), 1);
   IF an_act = 1 THEN --Нужно по активной
    lr_potertemp.z := ln_a;
    lr_potertemp.z1 := ln_a1;
    lr_potertemp.z2 := ln_a2;
    lr_potertemp.z3 := ln_a3;
   ELSE --Нужно по реактивной
    OPEN lcur_ss(an_mid);
    FETCH lcur_ss INTO ln_ratio, ln_measurables, ln_point_workinghours, ln_point_t0;
    IF lcur_ss%NOTFOUND THEN
     CLOSE lcur_ss;
     RETURN;
    END IF;
    CLOSE lcur_ss;
    IF ln_measurables >= 0 THEN --реактивная считается по активной
     lr_potertemp.z := ROUND(ln_a * ln_ratio);
     lr_potertemp.z1 := ROUND(ln_a1 * ln_ratio);
     lr_potertemp.z2 := ROUND(ln_a2 * ln_ratio);
     lr_potertemp.z3 := ROUND(ln_a3 * ln_ratio);
    ELSE
     lr_potertemp.z := ln_r;
     lr_potertemp.z1 := ln_r1;
     lr_potertemp.z2 := ln_r2;
     lr_potertemp.z3 := ln_r3;
    END IF;
   END IF;
   RETURN;
  END IF;
  SELECT COUNT(*)
    INTO ln_a
    FROM DUAL
   WHERE EXISTS( SELECT *
                   FROM connectionparam
                  WHERE mid = an_mid)
      OR EXISTS( SELECT *
                   FROM sharedconnectionparam
                  WHERE mid = an_mid);
  IF ln_a = 0 THEN --Если нет потерь
   RETURN;
  END IF;
  /*Далее мы считаем потери. Берем все присоединения, где фигурирует точка.
    Считаем расход по всем точкам привязанным к данному присоединению и на этот расход считаем
    потери. Берем свою часть (пропорционально расходу). Причем, если участвует одна точка, то
    все потери вешаются на нее (это принципиально, если расход=0 а потери есть {потери холостого хода} )
    Часы работы трансформатора ln_max_workinghours и время всей работы ln_maxT0
    (обычно не задано и следовательно равно кол-ву часов в месяце) ищутся как
    максимальные среди всех точек и самого присоединения*/
  FOR lc IN lcur_sel LOOP
   SELECT COUNT(*)
     INTO ln_count
     FROM connectionparam c, feeders p
    WHERE c.nconnectionparam = lc.nconnectionparam AND c.mid = p.mid(+);
   SELECT COUNT(*)
     INTO ln_a
     FROM sharedconnectionparam c, feeders p
    WHERE c.nconnectionparam = lc.nconnectionparam AND c.mid = p.mid(+);
   ln_count := ln_count + ln_a;
   IF ln_count = 0 THEN
    NULL;
   ELSIF ln_count = 1 THEN --Не долевые
    IF NVL(lc.nworkinghours, 1) <> 0 THEN
     SELECT NVL(re.nratio, 0) nratio, pi.nrecompens, NVL(ph.nworkinghours, pi.nworkinghours),
            NVL(ph.nfullhours, NVL(NVL(lc.nfullhours, pi.nfullhours), ln_daycount * 24))
       INTO ln_ratio, ln_measurables, ln_max_workinghours,
            ln_maxt0
       FROM feeders pi, recompens re, pointfullhours ph
      WHERE pi.mid = an_mid
        AND pi.nrecompens = re.nrecompens(+)
        AND pi.mid = ph.mid(+)
        AND an_accperiod = ph.naccperiod(+);
     IF lc.nnotincludeconsump <> 1 THEN
      SELECT NVL(SUM(NVL(DECODE(an_defdir, 1, er, ed), 0) * DECODE(nwasteabs, 1, 0, 1)), 0),
             NVL(SUM(NVL(DECODE(an_defdir, 1, q1, q3), 0) * DECODE(nwasteabs, 1, 0, 1)), 0)
        INTO ln_a,
             ln_r
        FROM bill
       WHERE mid = an_mid
         AND date_time > TO_DATE(an_accperiod, 'YYYYMM')
         AND date_time <= ADD_MONTHS(TO_DATE(an_accperiod, 'YYYYMM'), 1);
      IF ln_measurables >= 0 THEN
       ln_r := ROUND(ln_a * ln_ratio);
      END IF;
     ELSE
      ln_a := 0;
      ln_r := 0;
     END IF;
     ln_maxt0 := LEAST(ln_maxt0, ln_daycount * 24);
     ln_max_workinghours := LEAST(
                             ln_maxt0, NVL(
                                        GREATEST(
                                         NVL(lc.nworkinghours, ln_max_workinghours), NVL(
                                                                                      ln_max_workinghours,
                                                                                      lc.nworkinghours)), ln_daycount *
                                                                                                          24),
                             ln_daycount * 24);
     IF ln_max_workinghours > 0 THEN --Если max время работы=0, то потери равны 0 (так договорились)
      /*Та формула , что  на бумаге немного переписана. Отделены два слагаемых
        которые содержат сумму квадратов расхода и которые не содержат*/
      IF an_act = 1 THEN --активные потери
       ln_pr1 := lc.ndeltapidling * ln_maxt0;
       ln_pr2 := (lc.ndeltapsc / (lc.nsh * lc.nsh * ln_max_workinghours)) +
                 (((lc.nl / 1000) * lc.nro) /
                  (ln_max_workinghours * lc.nun * lc.nun));
      ELSE --реактивные потери
       ln_pr1 := (lc.nsn * lc.niidling) * (ln_maxt0 / 100);
       ln_pr2 := (lc.nusc / (100 * lc.nsh * ln_max_workinghours)) +
                 (((lc.nl / 1000) * lc.nxo) /
                  (ln_max_workinghours * lc.nun * lc.nun));
      END IF;
      lr_potertemp.z := lr_potertemp.z +
                        (ln_pr1 +
                         (ln_a * ln_a + ln_r * ln_r) * ln_pr2) *
                        lc.nenergypercent;
     END IF;
    END IF;
   ELSE --Долевые
    ln_provvar1 := f_provvar1(lc.nparallelconnection, an_accperiod);
    ln_count := 0;
    ln_sa := 0;
    ln_sr := 0;
    ln_a1 := 0;
    ln_r1 := 0;
    lb_find := FALSE;
    ln_max_workinghours := lc.nworkinghours;
    ln_maxt0 := NULL;
    FOR lcp IN lcur_p(lc.nconnectionparam) LOOP
     OPEN lcur_ss(lcp.npoint);
     FETCH lcur_ss INTO ln_ratio, ln_measurables, ln_point_workinghours, ln_point_t0;
     IF lcur_ss%NOTFOUND THEN
      ln_ratio := NULL;
     END IF;
     CLOSE lcur_ss;
     IF ln_ratio IS NOT NULL THEN --точка открыта
      ln_count := ln_count + 1;
      SELECT NVL(SUM(NVL(DECODE(an_defdir, 1, er, ed), 0) * DECODE(nwasteabs, 1, 0, 1)), 0),
             NVL(SUM(NVL(DECODE(an_defdir, 1, q1, q3), 0) * DECODE(nwasteabs, 1, 0, 1)), 0)
        INTO ln_a,
             ln_r
        FROM bill
       WHERE mid = lcp.npoint
         AND date_time > TO_DATE(an_accperiod, 'YYYYMM')
         AND date_time <= ADD_MONTHS(TO_DATE(an_accperiod, 'YYYYMM'), 1);
      IF ln_measurables >= 0 THEN
       ln_r := ROUND(ln_a * ln_ratio);
      END IF;
      IF lcp.npoint = an_mid THEN
       ln_a1 := ln_a;
       ln_r1 := ln_r;
       lb_find := TRUE;
      END IF;
      IF ln_point_t0 IS NOT NULL THEN
       ln_maxt0 := GREATEST(ln_point_t0, NVL(ln_maxt0, ln_point_t0));
      END IF;
      IF ln_point_workinghours IS NOT NULL THEN
       ln_max_workinghours := GREATEST(ln_point_workinghours, NVL(ln_max_workinghours, ln_point_workinghours));
      END IF;
      IF lcp.nnotincludeconsump <> 1 THEN
       ln_sa := ln_sa + ln_a;
       ln_sr := ln_sr + ln_r;
      END IF;
     END IF;
    END LOOP;
    IF ln_count > 0 THEN
     IF lc.nworkinghours = 0 THEN --Если на параметре присоединения время работы=0, то потери равны 0 (так договорились)
      ln_pr1 := 0;
      ln_pr2 := 0;
     ELSE
      ln_maxt0 := LEAST(NVL(NVL(lc.nfullhours, ln_maxt0), ln_daycount * 24), ln_daycount * 24);
      ln_max_workinghours := LEAST(ln_maxt0, NVL(ln_max_workinghours, ln_daycount * 24), ln_daycount * 24);
      IF ln_max_workinghours = 0 THEN --Если max время работы=0, то потери равны 0 (так договорились)
       ln_pr1 := 0;
       ln_pr2 := 0;
      ELSE
       IF an_act = 1 THEN --активные потери
        ln_pr1 := lc.ndeltapidling * ln_maxt0;
        ln_pr2 := (lc.ndeltapsc / (lc.nsh * lc.nsh * ln_max_workinghours)) +
                  (((lc.nl / 1000) * lc.nro) /
                   (ln_max_workinghours * lc.nun * lc.nun));
       ELSE --реактивные потери
        ln_pr1 := (lc.nsn * lc.niidling) * (ln_maxt0 / 100);
        ln_pr2 := (lc.nusc / (100 * lc.nsh * ln_max_workinghours)) +
                  (((lc.nl / 1000) * lc.nxo) /
                   (ln_max_workinghours * lc.nun * lc.nun));
       END IF;
      END IF;
     END IF;
     IF ln_provvar1 = 1 THEN --спаренные трансформаторы без счетчиков
      ln_procparallel := f_getparallelproc(lc.nparallelconnection, an_accperiod, ln_maxt0);
     ELSE
      ln_procparallel := 1;
     END IF;
     ln_s2 := ROUND(ln_procparallel * ln_sa) *
              ROUND(ln_procparallel * ln_sa) +
              ROUND(ln_procparallel * ln_sr) *
              ROUND(ln_procparallel * ln_sr); --сумма квадратов расходов с весом каждого трансформатора
     IF  ln_count = 1 AND lb_find AND (lc.nparallelconnection IS NULL OR ln_provvar1 = 1) THEN --одна точка
      lr_potertemp.z := lr_potertemp.z +
                        (ln_pr1 + ln_s2 * ln_pr2) * lc.nenergypercent;
     ELSIF (lc.nparallelconnection IS NULL OR ln_provvar1 = 1) THEN
      IF an_act = 1 THEN --пропорция
       IF ABS(ln_sa) > 0 THEN
        lr_potertemp.z := lr_potertemp.z +
                          (ln_pr1 + ln_s2 * ln_pr2) * lc.nenergypercent *
                          LEAST(ln_a1 / ln_sa, 1);
       ELSIF ABS(ln_sa) = 0 THEN
        IF lc.mainpoint = 1 THEN
         NULL; --Если закоментировать следующую строчку, то потери холостого хода без расхода не будут учитываться
         lr_potertemp.z := lr_potertemp.z +
                           (ln_pr1 + ln_s2 * ln_pr2) * lc.nenergypercent;
        END IF;
       END IF;
      ELSIF NVL(an_act, 0) <> 1 THEN
       IF an_accperiod < 200202 THEN --Потери по старому (реактив)
        IF ABS(ln_sr) > 0 THEN
         lr_potertemp.z := lr_potertemp.z +
                           (ln_pr1 + ln_s2 * ln_pr2) * lc.nenergypercent *
                           LEAST(ln_r1 / ln_sr, 1);
        ELSIF ABS(ln_sr) = 0 THEN
         IF lc.mainpoint = 1 THEN
          NULL; --Если закоментировать следующую строчку, то потери холостого хода без расхода не будут учитываться
          lr_potertemp.z := lr_potertemp.z +
                            (ln_pr1 + ln_s2 * ln_pr2) * lc.nenergypercent;
         END IF;
        END IF;
       ELSE --Потери по новому
        IF ABS(ln_sa) > 0 THEN
         lr_potertemp.z := lr_potertemp.z +
                           (ln_pr1 + ln_s2 * ln_pr2) * lc.nenergypercent *
                           LEAST(ln_a1 / ln_sa, 1);
        ELSIF ABS(ln_sa) = 0 THEN
         IF lc.mainpoint = 1 THEN
          NULL; --Если закоментировать следующую строчку, то потери холостого хода без расхода не будут учитываться
          lr_potertemp.z := lr_potertemp.z +
                            (ln_pr1 + ln_s2 * ln_pr2) * lc.nenergypercent;
         END IF;
        END IF;
       END IF;
      END IF;
     ELSE
      p_getsharesconsumption(lc.nparallelconnection, an_mid, an_accperiod, an_defdir, ln_sa, ln_sr);
      IF an_act = 1 THEN --пропорция
       IF ABS(ln_sa) > 0 THEN
        lr_potertemp.z := lr_potertemp.z +
                          (ln_pr1 + ln_s2 * ln_pr2) * lc.nenergypercent *
                          LEAST(ln_a1 / ln_sa, 1);
       ELSIF ABS(ln_sa) = 0 THEN
        IF lc.mainpoint = 1 THEN
         NULL; --Если закоментировать следующую строчку, то потери холостого хода без расхода не будут учитываться
         lr_potertemp.z := lr_potertemp.z +
                           (ln_pr1 + ln_s2 * ln_pr2) * lc.nenergypercent;
        END IF;
       END IF;
      ELSIF NVL(an_act, 0) <> 1 THEN
       IF an_accperiod < 200202 THEN --Потери по старому (реактив)
        IF ABS(ln_sr) > 0 THEN
         lr_potertemp.z := lr_potertemp.z +
                           (ln_pr1 + ln_s2 * ln_pr2) * lc.nenergypercent *
                           LEAST(ln_r1 / ln_sr, 1);
        ELSIF ABS(ln_sr) = 0 THEN
         IF lc.mainpoint = 1 THEN
          NULL; --Если закоментировать следующую строчку, то потери холостого хода без расхода не будут учитываться
          lr_potertemp.z := lr_potertemp.z +
                            (ln_pr1 + ln_s2 * ln_pr2) * lc.nenergypercent;
         END IF;
        END IF;
       ELSE
        IF ABS(ln_sa) > 0 THEN
         lr_potertemp.z := lr_potertemp.z +
                           (ln_pr1 + ln_s2 * ln_pr2) * lc.nenergypercent *
                           LEAST(ln_a1 / ln_sa, 1);
        ELSIF ABS(ln_sa) = 0 THEN
         IF lc.mainpoint = 1 THEN
          NULL; --Если закоментировать следующую строчку, то потери холостого хода без расхода не будут учитываться
          lr_potertemp.z := lr_potertemp.z +
                            (ln_pr1 + ln_s2 * ln_pr2) * lc.nenergypercent;
         END IF;
        END IF;
       END IF;
      END IF;
     END IF;
    END IF;
   END IF;
  END LOOP;
 END;
 ------------------------------------------------------------------------------------------------
 FUNCTION f_waste(an_accperiod NUMBER, an_mid NUMBER, av_zone VARCHAR2, an_act NUMBER, an_defdir NUMBER)
  RETURN NUMBER IS
  ln_rez              NUMBER;
  ln_reznew           tr_potercoef;
  ln_reznew1          tr_potercoef;
  ln_potera           NUMBER;
  ln_poterr           NUMBER;
  ln_poter            NUMBER;
  ln_wastepercentcalc NUMBER;
  ln_count            NUMBER;
  ln_rezout           NUMBER;
  CURSOR lcur_coef IS -- Вытягиваем процент потерь (для потерь не по формуле)
   SELECT NVL(po.line_loss, 0) + NVL(po.act_loss, 0), NVL(po.react_loss, 0), nwastepercentcalc
     FROM feeders po
    WHERE po.mid = an_mid;
 BEGIN
  /*Примечание:
      Если требуются потери по зоне, то считаем сумарные потери, а потом берем зонное вложение.*/
  OPEN lcur_coef;
  FETCH lcur_coef INTO ln_potera, ln_poterr, ln_wastepercentcalc;
  IF lcur_coef%NOTFOUND THEN
   CLOSE lcur_coef;
   RETURN 0;
  END IF;
  CLOSE lcur_coef;
  IF ln_wastepercentcalc = 0 THEN
   RETURN 0;
  ELSIF ln_wastepercentcalc = 4 THEN --Потери по формуле
   f_getpoternew(ln_reznew, an_mid, an_act, an_accperiod, 0, an_defdir); --Считаем потери в ln_RezNew
   IF av_zone = 'A' OR av_zone = 'B' OR av_zone = 'C' THEN --Потери по каждой зоне
    f_getpoternew(ln_reznew1, an_mid, an_act, an_accperiod, 1, an_defdir); --Считаем расход в ln_RezNew1
    IF ln_reznew1.z1 + ln_reznew1.z2 + ln_reznew1.z3 = 0 THEN
     IF av_zone = 'C' THEN --Ошибки округления на третью зону
      RETURN ROUND(ln_reznew.z);
     ELSE
      RETURN 0;
     END IF;
    END IF;
    ln_rez := ROUND(ln_reznew.z);
    IF av_zone = 'A' THEN --Делим потери по зоне пропорционально вложению зоны
     ln_rez := ROUND((ln_rez * ln_reznew1.z1) / (ln_reznew1.z1 + ln_reznew1.z2 + ln_reznew1.z3));
    ELSIF av_zone = 'B' THEN
     ln_rez := ROUND((ln_rez * ln_reznew1.z2) / (ln_reznew1.z1 + ln_reznew1.z2 + ln_reznew1.z3));
    ELSE
     ln_rez := ROUND(
                ln_rez -
                ROUND(
                 (ln_rez * ln_reznew1.z1) / (ln_reznew1.z1 + ln_reznew1.z2 + ln_reznew1.z3)) -
                ROUND(
                 (ln_rez * ln_reznew1.z2) / (ln_reznew1.z1 + ln_reznew1.z2 + ln_reznew1.z3)));
    END IF;
   ELSE --потери без зон
    ln_rez := ln_reznew.z;
   END IF;
  ELSE
   IF ln_wastepercentcalc > 4 THEN --На будущее
    RETURN 0;
   END IF;
   IF an_act = 1 THEN
    ln_poter := ln_potera;
   ELSE
    ln_poter := ln_poterr;
   END IF;
   f_getpoternew(ln_reznew, an_mid, an_act, an_accperiod, 1, an_defdir); --Считаем расход по точке в ln_RezNew
   IF ln_wastepercentcalc = 1 THEN --потери в процентах
    ln_rez := ROUND(ln_reznew.z * ln_poter / 100);
   ELSIF ln_wastepercentcalc = 2 THEN -- фиксированые потери
    ln_rez := ln_poter;
   ELSIF ln_wastepercentcalc = 3 THEN --потери процент в квадрате
    ln_rez := ROUND(ln_reznew.z * ln_reznew.z * ln_poter / 100000);
   END IF;
   IF av_zone = 'A' OR av_zone = 'B' OR av_zone = 'C' THEN --если по зоне то процентовка
    IF ln_reznew.z1 + ln_reznew.z2 + ln_reznew.z3 = 0 THEN
     IF av_zone = 'C' THEN --Ошибки округления на третью зону
      RETURN ROUND(ln_rez);
     ELSE
      RETURN 0;
     END IF;
    END IF;
    IF av_zone = 'A' THEN
     ln_rez := ROUND((ln_rez * ln_reznew.z1) / (ln_reznew.z1 + ln_reznew.z2 + ln_reznew.z3));
    ELSIF av_zone = 'B' THEN
     ln_rez := ROUND((ln_rez * ln_reznew.z2) / (ln_reznew.z1 + ln_reznew.z2 + ln_reznew.z3));
    ELSE --ошибки округления на 3 зону
     ln_rez := ROUND(
                ln_rez -
                ROUND(
                 (ln_rez * ln_reznew.z1) / (ln_reznew.z1 + ln_reznew.z2 + ln_reznew.z3)) -
                ROUND(
                 (ln_rez * ln_reznew.z2) / (ln_reznew.z1 + ln_reznew.z2 + ln_reznew.z3)));
    END IF;
   END IF;
  END IF;
  RETURN ROUND(ln_rez);
 END;
  ------------------------------------------------------------------------------------------------
  ------------------------------------------------------------------------------------------------
  ------------------------------------------------------------------------------------------------
 -- Сумарное время работы всех паралельных присоединений
 FUNCTION f_defgetparallelproc(an_parallelconnection NUMBER, ad_start DATE, ad_end DATE, an_currentt0 NUMBER)
  RETURN NUMBER IS
  ln_ret      NUMBER;
  ln_daycount NUMBER DEFAULT ad_end - ad_start; --Кол-во дней в месяце
  ln_delim    NUMBER;
  ln_maxt0    NUMBER;
  ln_allt0    NUMBER DEFAULT 0;
  CURSOR lcur_sel IS
   /*Ищем параллельные присоединения и их время работы (To)*/
   SELECT nconnectionparam, nfullhours
     FROM connectionparam
    WHERE nparallelconnection = an_parallelconnection;
  CURSOR lcur_p(lc_param IN NUMBER) IS
   SELECT NVL(ch.nfullhours, NVL(ph.nfullhours, NVL(c.nfullhours, pi.nfullhours))) / ln_delim nfullhours
     FROM connectionparam c, feeders pi, pointfullhours ph, connectionparamfullhours ch
    WHERE c.nconnectionparam = lc_param
      AND c.mid = pi.mid(+)
      AND c.nconnectionparam = ch.nconnectionparam(+)
      AND TO_NUMBER(TO_CHAR(ad_start, 'YYYYMM')) = ch.naccperiod(+)
      AND pi.mid = ph.mid(+)
      AND TO_NUMBER(TO_CHAR(ad_start, 'YYYYMM')) = ph.naccperiod(+)
   UNION ALL
   SELECT NVL(ph.nfullhours, pi.nfullhours) / ln_delim nfullhours
     FROM sharedconnectionparam c, feeders pi, pointfullhours ph
    WHERE c.nconnectionparam = lc_param
      AND c.mid = pi.mid(+)
      AND pi.mid = ph.mid(+)
      AND TO_NUMBER(TO_CHAR(ad_start, 'YYYYMM')) = ph.naccperiod(+);
 BEGIN
  IF  ad_start = TRUNC(ad_start, 'MONTH') AND ADD_MONTHS(ad_start, 1) = ad_end THEN
   ln_delim := 1;
  ELSE
   ln_delim := NULL;
  END IF;
  SELECT COUNT(*)
    INTO ln_ret
    FROM connectionparam
   WHERE nparallelconnection = an_parallelconnection;
  IF ln_ret < 2 THEN
   RETURN 1;
  END IF;
  FOR lc IN lcur_sel LOOP
   ln_maxt0 := lc.nfullhours;
   IF ln_maxt0 IS NULL THEN
    FOR lcp IN lcur_p(lc.nconnectionparam) LOOP
     ln_maxt0 := GREATEST(NVL(lcp.nfullhours, ln_maxt0), NVL(ln_maxt0, lcp.nfullhours));
    END LOOP;
   END IF;
   ln_allt0 := ln_allt0 + NVL(ln_maxt0, ln_daycount * 24);
  END LOOP;
  IF ln_allt0 = 0 THEN
   RETURN 0;
  END IF;
  RETURN LEAST(an_currentt0 / ln_allt0, 1); --least(an_CurrentT0,ln_DayCount*24)/least(ln_AllT0,ln_DayCount*24);
 END;
 ------------------------------------------------------------------------------------------------
 PROCEDURE p_defgetusedconsumpt(
  an_connectionparam        NUMBER,
  ad_start                  DATE,
  ad_end                    DATE,
  an_sa              IN OUT NUMBER,
  an_sr              IN OUT NUMBER) IS
  CURSOR lcur_sel IS
   SELECT c.mid, c.ntype, c.nkc, NVL(NVL(r1.nratio, r.nratio), 0) nratio, f.nrecompens
     FROM usedconsumpt c, feeders f, recompens r, recompens r1
    WHERE c.nconnectionparam = an_connectionparam
      AND c.mid = f.mid
      AND f.nrecompens = r.nrecompens(+)
      AND c.nrecompens = r1.nrecompens(+)
      AND NOT EXISTS( SELECT mid
                        FROM pointfullhours
                       WHERE naccperiod = TO_NUMBER(TO_CHAR(ad_start, 'YYYYMM')) AND mid = c.mid AND nfullhours = 0);
  ln_a NUMBER;
  ln_r NUMBER;
 BEGIN
  an_sa := NVL(an_sa, 0);
  an_sr := NVL(an_sr, 0);
  FOR lc IN lcur_sel LOOP
   SELECT NVL(SUM(DECODE(lc.ntype, 1, er, 2, ed, NVL(er, 0) - NVL(ed, 0))), 0) * lc.nkc,
          NVL(SUM(DECODE(lc.ntype, 1, q1, 2, q2, NVL(q1, 0) - NVL(q2, 0))), 0) * lc.nkc
     INTO ln_a,
          ln_r
     FROM halfhour
    WHERE mid = lc.mid AND date_time > ad_start AND date_time <= ad_end;
   IF lc.nrecompens > 0 THEN
    ln_r := ROUND(ln_a * lc.nratio);
   END IF;
   an_sa := an_sa + ln_a;
   an_sr := an_sr + ln_r;
  END LOOP;
 END;
 ------------------------------------------------------------------------------------------------
 PROCEDURE p_defgetsharesconsumption(
  an_parallelconnection        NUMBER,
  an_mid                       NUMBER,
  ad_start                     DATE,
  ad_end                       DATE,
  an_defdir                    NUMBER,
  an_sa                 IN OUT NUMBER,
  an_sr                 IN OUT NUMBER) IS
  CURSOR lcur_sel IS
   SELECT c.nconnectionparam
     FROM connectionparam c
    WHERE c.nparallelconnection = an_parallelconnection
      AND EXISTS( SELECT nconnectionparam
                    FROM connectionparam
                   WHERE mid = an_mid AND nconnectionparam = c.nconnectionparam
                  UNION ALL
                  SELECT nconnectionparam
                    FROM sharedconnectionparam
                   WHERE mid = an_mid AND nconnectionparam = c.nconnectionparam);
  CURSOR lcur_p(lc_param IN NUMBER) IS
   SELECT pi.mid npoint, NVL(re.nratio, 0) nratio, pi.nrecompens nmeasurables
     FROM connectionparam c, feeders pi, recompens re
    WHERE c.nconnectionparam = lc_param
      AND c.nnotincludeconsump = 0
      AND c.mid = pi.mid(+)
      AND pi.nrecompens = re.nrecompens(+)
   UNION
   SELECT pi.mid npoint, NVL(re.nratio, 0) nratio, pi.nrecompens nmeasurables
     FROM sharedconnectionparam c, feeders pi, recompens re
    WHERE c.nconnectionparam = lc_param
      AND c.nnotincludeconsump = 0
      AND c.mid = pi.mid(+)
      AND pi.nrecompens = re.nrecompens(+);
  ln_a NUMBER;
  ln_r NUMBER;
 BEGIN
  an_sa := 0;
  an_sr := 0;
  FOR lc IN lcur_sel LOOP
   FOR lcp IN lcur_p(lc.nconnectionparam) LOOP
    SELECT NVL(SUM(NVL(DECODE(an_defdir, 1, er, ed), 0)), 0), NVL(SUM(NVL(DECODE(an_defdir, 1, q1, q3), 0)), 0)
      INTO ln_a, ln_r
      FROM halfhour
     WHERE mid = lcp.npoint AND date_time > ad_start AND date_time <= ad_end;
    IF lcp.nmeasurables >= 0 THEN
     ln_r := ROUND(ln_a * lcp.nratio);
    END IF;
    an_sa := an_sa + ln_a;
    an_sr := an_sr + ln_r;
   END LOOP;
   p_defgetusedconsumpt(lc.nconnectionparam, ad_start, ad_end, an_sa, an_sr);
  END LOOP;
 END;
 ------------------------------------------------------------------------------------------------
 PROCEDURE p_defgetpoterpar(
  an_pa              OUT NUMBER,
  an_pr              OUT NUMBER,
  an_connectionparam     NUMBER,
  ad_start               DATE,
  ad_end                 DATE,
  an_defdir              NUMBER) IS
  ln_ratio              NUMBER;
  ln_a                  NUMBER;
  ln_r                  NUMBER;
  ln_pr1a               NUMBER;
  ln_pr2a               NUMBER;
  ln_pr1r               NUMBER;
  ln_pr2r               NUMBER;
  ln_measurables        NUMBER;
  ln_s2                 NUMBER;
  ln_sa                 NUMBER;
  ln_sr                 NUMBER;
  ln_count              NUMBER;
  ln_daycount           NUMBER DEFAULT (ad_end - ad_start); --Кол-во дней в месяце
  ln_delim              NUMBER DEFAULT  24 * (ad_end - ad_start);
  ln_point_workinghours NUMBER;
  ln_max_workinghours   NUMBER;
  ln_point_t0           NUMBER;
  ln_maxt0              NUMBER;
  ln_procparallel       NUMBER;
  ln_provvar1           NUMBER;
  -----------------------
  CURSOR lcur_sel IS
   /*Ищет всевозможные присоединения и их параметры для расчета потерь,
     где фигурирует точка с ид.=an_mid*/
   SELECT c.nconnectionparam, NVL(c.nsn, 1) nsn, NVL(nsh, NVL(c.nsn, 1)) nsh, NVL(c.ndeltapidling, 0) ndeltapidling,
          NVL(c.ndeltapsc, 0) ndeltapsc, NVL(c.niidling, 0) niidling, NVL(c.nusc, 0) nusc, NVL(c.nro, 0) nro,
          NVL(c.nxo, 0) nxo, NVL(c.nl, 0) nl, NVL(c.nun, 1) nun,
          NVL(c.nenergypercent, 100) / 100 nenergypercent,
          NVL(
           ph.nworkinghours, NVL(
                              pfh.nworkinghours, NVL(
                                                  c.nworkinghours, NVL(
                                                                    DECODE(999, 3, 700, 1, 200, 2, 450, NULL),
                                                                    pi.nworkinghours)))) /
          ln_delim nworkinghours,
          c.nparallelconnection,
          NVL(ph.nfullhours, NVL(pfh.nfullhours, NVL(c.nfullhours, pi.nfullhours))) / ln_delim nfullhours,
          c.nnotincludeconsump, 1 mainpoint, c.mid,
          NVL(c.nrenergypercent, 100) / 100 nrenergypercent, c.nprocent
     FROM connectionparam c, connectionparamfullhours ph, pointfullhours pfh, feeders pi
    WHERE c.nconnectionparam = an_connectionparam
      AND c.nconnectionparam = ph.nconnectionparam(+)
      AND TO_NUMBER(TO_CHAR(ad_start, 'YYYYMM')) = ph.naccperiod(+)
      AND c.mid = pfh.mid(+)
      AND TO_NUMBER(TO_CHAR(ad_start, 'YYYYMM')) = pfh.naccperiod(+)
      AND c.mid = pi.mid(+);
  CURSOR lcur_p(lc_param NUMBER) IS
   /*Ищем все точки которые участвуют в доле по дележке потерь присоединения
     NNOTINCLUDECONSUMP - отвечает за включение расхода по точке в общее потребление по присоединению*/
   SELECT mid npoint, nnotincludeconsump
     FROM connectionparam
    WHERE nconnectionparam = lc_param
   UNION ALL
   SELECT mid npoint, nnotincludeconsump
     FROM sharedconnectionparam
    WHERE nconnectionparam = lc_param;
  CURSOR lcur_ss(lc_mid IN NUMBER) IS
   SELECT /*Дотягиваем информацию по остальным точкам, участвующим в дележке потерь
            а именно часы работы и наличае счетчиков для ответа на вопрос: Как счмтать
            расход реактивной (по активной или по показаниям реактивной)*/
          NVL(re.nratio, 0) nratio, pi.nrecompens nmeasurables,
          NVL(ph.nworkinghours, pi.nworkinghours) / ln_delim point_workinghours,
          NVL(ph.nfullhours, pi.nfullhours) / ln_delim nfullhours
     FROM feeders pi, recompens re, pointfullhours ph
    WHERE pi.mid = lc_mid
      AND pi.nrecompens = re.nrecompens(+)
      AND pi.mid = ph.mid(+)
      AND TO_NUMBER(TO_CHAR(ad_start, 'YYYYMM')) = ph.naccperiod(+)
      --проверка точки на "отлючено"
      AND NOT EXISTS( SELECT mid
                        FROM pointfullhours
                       WHERE naccperiod = TO_NUMBER(TO_CHAR(ad_start, 'YYYYMM')) AND mid = pi.mid AND nfullhours = 0);
 BEGIN
  /*Далее мы считаем потери. Берем все присоединения, где фигурирует точка.
    Считаем расход по всем точкам привязанным к данному присоединению и на этот расход считаем
    потери. Берем свою часть (пропорционально расходу). Причем, если участвует одна точка, то
    все потери вешаются на нее (это принципиально, если расход=0 а потери есть {потери холостого хода} )
    Часы работы трансформатора ln_max_workinghours и время всей работы ln_maxT0
    (обычно не задано и следовательно равно кол-ву часов в месяце) ищутся как
    максимальные среди всех точек и самого присоединения*/
  IF  ad_start = TRUNC(ad_start, 'MONTH') AND ADD_MONTHS(ad_start, 1) = ad_end THEN
   ln_delim := 1;
  ELSE
   ln_delim := NULL;
  END IF;
  an_pa := 0;
  an_pr := 0;
  FOR lc IN lcur_sel LOOP
   SELECT 1 + COUNT(*)
     INTO ln_count
     FROM sharedconnectionparam c, feeders p
    WHERE c.nconnectionparam = lc.nconnectionparam AND c.mid = p.mid(+);
   IF ln_count = 1 THEN --Не долевые
    IF NVL(lc.nworkinghours, 1) <> 0 THEN
     SELECT NVL(re.nratio, 0) nratio, pi.nrecompens, NVL(ph.nworkinghours, pi.nworkinghours) / ln_delim,
            NVL(ph.nfullhours / ln_delim, NVL(NVL(lc.nfullhours, pi.nfullhours) / ln_delim, ln_daycount * 24))
       INTO ln_ratio, ln_measurables, ln_max_workinghours,
            ln_maxt0
       FROM feeders pi, recompens re, pointfullhours ph
      WHERE pi.mid = lc.mid
        AND pi.nrecompens = re.nrecompens(+)
        AND pi.mid = ph.mid(+)
        AND TO_NUMBER(TO_CHAR(ad_start, 'YYYYMM')) = ph.naccperiod(+);
     IF lc.nnotincludeconsump <> 1 THEN
      SELECT NVL(SUM(NVL(DECODE(an_defdir, 1, er, ed), 0)), 0), NVL(SUM(NVL(DECODE(an_defdir, 1, q1, q3), 0)), 0)
        INTO ln_a, ln_r
        FROM halfhour
       WHERE mid = lc.mid AND date_time > ad_start AND date_time <= ad_end;
      IF ln_measurables >= 0 THEN
       ln_r := ROUND(ln_a * ln_ratio);
      END IF;
     ELSE
      ln_a := 0;
      ln_r := 0;
     END IF;
     ln_maxt0 := LEAST(ln_maxt0, ln_daycount * 24);
     ln_max_workinghours := LEAST(
                             ln_maxt0, NVL(
                                        GREATEST(
                                         NVL(lc.nworkinghours, ln_max_workinghours), NVL(
                                                                                      ln_max_workinghours,
                                                                                      lc.nworkinghours)), ln_daycount *
                                                                                                          24),
                             ln_daycount * 24);
     IF ln_max_workinghours > 0 THEN --Если max время работы=0, то потери равны 0 (так договорились)
      /*Та формула , что  на бумаге немного переписана. Отделены два слагаемых
        которые содержат сумму квадратов расхода и которые не содержат*/
      ln_pr1a := lc.ndeltapidling * ln_maxt0;
      ln_pr2a := (lc.ndeltapsc / (lc.nsh * lc.nsh * ln_max_workinghours)) +
                 (((lc.nl / 1000) * lc.nro) /
                  (ln_max_workinghours * lc.nun * lc.nun));
      ln_pr1r := (lc.nsn * lc.niidling) * (ln_maxt0 / 100);
      ln_pr2r := (lc.nusc / (100 * lc.nsh * ln_max_workinghours)) +
                 (((lc.nl / 1000) * lc.nxo) /
                  (ln_max_workinghours * lc.nun * lc.nun));
      p_defgetusedconsumpt(lc.nconnectionparam, ad_start, ad_end, ln_a, ln_r);
      IF lc.nprocent = 1 THEN
       an_pa := an_pa + ln_a * lc.nenergypercent;
       an_pr := an_pr + ln_r * lc.nrenergypercent;
      ELSE
       ln_s2 := ln_a * ln_a + ln_r * ln_r;
       an_pa := an_pa +
                (ln_pr1a + ln_s2 * ln_pr2a) * lc.nenergypercent;
       an_pr := an_pr +
                (ln_pr1r + ln_s2 * ln_pr2r) * lc.nrenergypercent;
      END IF;
     END IF;
    END IF;
   ELSE --Долевые
    ln_provvar1 := f_provvar1(lc.nparallelconnection, TO_NUMBER(TO_CHAR(ad_start, 'YYYYMM')));
    ln_count := 0;
    ln_sa := 0;
    ln_sr := 0;
    ln_max_workinghours := lc.nworkinghours;
    ln_maxt0 := NULL;
    FOR lcp IN lcur_p(lc.nconnectionparam) LOOP
     OPEN lcur_ss(lcp.npoint);
     FETCH lcur_ss INTO ln_ratio, ln_measurables, ln_point_workinghours, ln_point_t0;
     IF lcur_ss%NOTFOUND THEN
      ln_ratio := NULL;
     END IF;
     CLOSE lcur_ss;
     IF ln_ratio IS NOT NULL THEN --точка открыта
      ln_count := ln_count + 1;
      SELECT NVL(SUM(NVL(DECODE(an_defdir, 1, er, ed), 0)), 0), NVL(SUM(NVL(DECODE(an_defdir, 1, q1, q3), 0)), 0)
        INTO ln_a, ln_r
        FROM halfhour
       WHERE mid = lcp.npoint AND date_time > ad_start AND date_time <= ad_end;
      IF ln_measurables >= 0 THEN
       ln_r := ROUND(ln_a * ln_ratio);
      END IF;
      IF ln_point_t0 IS NOT NULL THEN
       ln_maxt0 := GREATEST(ln_point_t0, NVL(ln_maxt0, ln_point_t0));
      END IF;
      IF ln_point_workinghours IS NOT NULL THEN
       ln_max_workinghours := GREATEST(ln_point_workinghours, NVL(ln_max_workinghours, ln_point_workinghours));
      END IF;
      IF lcp.nnotincludeconsump <> 1 THEN
       ln_sa := ln_sa + ln_a;
       ln_sr := ln_sr + ln_r;
      END IF;
     END IF;
    END LOOP;
    IF ln_count > 0 THEN
     IF lc.nworkinghours = 0 THEN --Если на параметре присоединения время работы=0, то потери равны 0 (так договорились)
      ln_pr1a := 0;
      ln_pr2a := 0;
      ln_pr1r := 0;
      ln_pr2r := 0;
     ELSIF lc.nprocent = 1 THEN
      ln_pr1a := 0;
      ln_pr2a := 1;
      ln_pr1r := 0;
      ln_pr2r := 1;
     ELSE
      ln_maxt0 := LEAST(NVL(NVL(lc.nfullhours, ln_maxt0), ln_daycount * 24), ln_daycount * 24);
      ln_max_workinghours := LEAST(ln_maxt0, NVL(ln_max_workinghours, ln_daycount * 24), ln_daycount * 24);
      IF ln_max_workinghours = 0 THEN --Если max время работы=0, то потери равны 0 (так договорились)
       ln_pr1a := 0;
       ln_pr2a := 0;
       ln_pr1r := 0;
       ln_pr2r := 0;
      ELSIF lc.nprocent = 1 THEN
       ln_pr1a := 0;
       ln_pr2a := 1;
       ln_pr1r := 0;
       ln_pr2r := 1;
      ELSE
       ln_pr1a := lc.ndeltapidling * ln_maxt0;
       ln_pr2a := (lc.ndeltapsc / (lc.nsh * lc.nsh * ln_max_workinghours)) +
                  (((lc.nl / 1000) * lc.nro) /
                   (ln_max_workinghours * lc.nun * lc.nun));
       ln_pr1r := (lc.nsn * lc.niidling) * (ln_maxt0 / 100);
       ln_pr2r := (lc.nusc / (100 * lc.nsh * ln_max_workinghours)) +
                  (((lc.nl / 1000) * lc.nxo) /
                   (ln_max_workinghours * lc.nun * lc.nun));
      END IF;
     END IF;
     IF ln_provvar1 = 1 THEN --спаренные трансформаторы без счетчиков
      ln_procparallel := f_defgetparallelproc(lc.nparallelconnection, ad_start, ad_end, ln_maxt0);
     ELSE
      ln_procparallel := 1;
     END IF;
     p_defgetusedconsumpt(lc.nconnectionparam, ad_start, ad_end, ln_sa, ln_sr);
     IF lc.nprocent = 1 THEN
      an_pa := an_pa +
               ROUND(ln_procparallel * ln_sa) * ln_pr2a * lc.nenergypercent;
      an_pr := an_pr +
               ROUND(ln_procparallel * ln_sr) * ln_pr2r * lc.nrenergypercent;
     ELSE
      ln_s2 := ROUND(ln_procparallel * ln_sa) *
               ROUND(ln_procparallel * ln_sa) +
               ROUND(ln_procparallel * ln_sr) *
               ROUND(ln_procparallel * ln_sr); --сумма квадратов расходов с весом каждого трансформатора
      an_pa := an_pa +
               (ln_pr1a + ln_s2 * ln_pr2a) * lc.nenergypercent;
      an_pr := an_pr +
               (ln_pr1r + ln_s2 * ln_pr2r) * lc.nrenergypercent;
     END IF;
    END IF;
   END IF;
  END LOOP;
 END;
 ------------------------------------------------------------------------------------------------
 -- Возвращает потери по всем зависимым параметрам * relatedparam *
 FUNCTION f_getsum2(
  an_a               NUMBER,
  an_r               NUMBER,
  an_connectionparam NUMBER,
  an_act             NUMBER,
  ad_start           DATE,
  ad_end             DATE,
  an_defdir          NUMBER)
  RETURN NUMBER IS
  ln_sa      NUMBER DEFAULT an_a;
  ln_sr      NUMBER DEFAULT an_r;
  ln_a       NUMBER;
  ln_r       NUMBER;
  ln_procent NUMBER;
  CURSOR lcur_sel IS
   SELECT     nfirstparam, nkc
         FROM relatedparam
   CONNECT BY PRIOR nconnectionparam = nfirstparam
   START WITH nconnectionparam = an_connectionparam;
 BEGIN
  FOR lc IN lcur_sel LOOP
   --Вычисляет потери по параметру
   p_defgetpoterpar(ln_a, ln_r, lc.nfirstparam, ad_start, ad_end, an_defdir);
   ln_sa := ln_sa + lc.nkc * ln_a;
   ln_sr := ln_sr + lc.nkc * ln_r;
  END LOOP;
  SELECT MAX(nprocent)
    INTO ln_procent
    FROM connectionparam
   WHERE nconnectionparam = an_connectionparam;
  IF ln_procent = 1 THEN
   IF an_act = 1 THEN
    RETURN ln_sa;
   ELSE
    RETURN ln_sr;
   END IF;
  END IF;
  RETURN ln_sa * ln_sa + ln_sr * ln_sr;
 END;
 ------------------------------------------------------------------------------------------------
 PROCEDURE f_defgetpoternew(
  lr_potertemp  IN OUT tr_potercoef,
  an_mid               NUMBER,
  an_act               NUMBER,
  ad_start             DATE,
  ad_end               DATE,
  an_potrebonly        NUMBER,
  an_defdir            NUMBER) IS
  ln_ratio              NUMBER;
  ln_a                  NUMBER;
  ln_a1                 NUMBER;
  ln_a2                 NUMBER;
  ln_a3                 NUMBER;
  ln_r                  NUMBER;
  ln_r1                 NUMBER;
  ln_r2                 NUMBER;
  ln_r3                 NUMBER;
  ln_pr1                NUMBER;
  ln_pr2                NUMBER;
  ln_measurables        NUMBER;
  ln_s2                 NUMBER;
  ln_sa                 NUMBER;
  ln_sr                 NUMBER;
  ln_count              NUMBER;
  lb_find               BOOLEAN;
  ln_daycount           NUMBER  DEFAULT (ad_end - ad_start); --Кол-во дней в месяце
  ln_delim              NUMBER  DEFAULT  24 * (ad_end - ad_start);
  ln_point_workinghours NUMBER;
  ln_max_workinghours   NUMBER;
  ln_point_t0           NUMBER;
  ln_maxt0              NUMBER;
  ln_procparallel       NUMBER;
  ln_provvar1           NUMBER;
  -----------------------
  CURSOR lcur_sel IS
   /*Ищет всевозможные присоединения и их параметры для расчета потерь,
     где фигурирует точка с ид.=an_mid*/
   SELECT c.nconnectionparam, NVL(c.nsn, 1) nsn, NVL(nsh, NVL(c.nsn, 1)) nsh, NVL(c.ndeltapidling, 0) ndeltapidling,
          NVL(c.ndeltapsc, 0) ndeltapsc, NVL(c.niidling, 0) niidling, NVL(c.nusc, 0) nusc, NVL(c.nro, 0) nro,
          NVL(c.nxo, 0) nxo, NVL(c.nl, 0) nl, NVL(c.nun, 1) nun,
          NVL(
           ph.nworkinghours, NVL(
                              pfh.nworkinghours, NVL(
                                                  c.nworkinghours, NVL(
                                                                    DECODE(999, 3, 700, 1, 200, 2, 450, NULL),
                                                                    pi.nworkinghours)))) /
          ln_delim nworkinghours,
          c.nparallelconnection,
          NVL(ph.nfullhours, NVL(pfh.nfullhours, NVL(c.nfullhours, pi.nfullhours))) / ln_delim nfullhours,
          c.nnotincludeconsump, 1 mainpoint, c.nprocent,
          DECODE(
           an_act, 1, NVL(c.nenergypercent, 100) / 100, NVL(c.nrenergypercent, 100) / 100) npr
     FROM connectionparam c, connectionparamfullhours ph, pointfullhours pfh, feeders pi
    WHERE c.mid = an_mid
      AND c.nconnectionparam = ph.nconnectionparam(+)
      AND TO_NUMBER(TO_CHAR(ad_start, 'YYYYMM')) = ph.naccperiod(+)
      AND c.mid = pfh.mid(+)
      AND TO_NUMBER(TO_CHAR(ad_start, 'YYYYMM')) = pfh.naccperiod(+)
      AND c.mid = pi.mid(+)
   UNION ALL
   SELECT c.nconnectionparam, NVL(c.nsn, 1) nsn, NVL(nsh, NVL(c.nsn, 1)) nsh, NVL(c.ndeltapidling, 0) ndeltapidling,
          NVL(c.ndeltapsc, 0) ndeltapsc, NVL(c.niidling, 0) niidling, NVL(c.nusc, 0) nusc, NVL(c.nro, 0) nro,
          NVL(c.nxo, 0) nxo, NVL(c.nl, 0) nl, NVL(c.nun, 1) nun,
          NVL(
           ph.nworkinghours, NVL(
                              pfh.nworkinghours, NVL(
                                                  c.nworkinghours, NVL(
                                                                    DECODE(999, 3, 700, 1, 200, 2, 450, NULL),
                                                                    pi.nworkinghours)))) /
          ln_delim nworkinghours,
          c.nparallelconnection,
          NVL(ph.nfullhours, NVL(pfh.nfullhours, NVL(c.nfullhours, pi.nfullhours))) / ln_delim nfullhours,
          s.nnotincludeconsump, 0 mainpoint, c.nprocent,
          DECODE(
           an_act, 1, NVL(c.nenergypercent, 100) / 100, NVL(c.nrenergypercent, 100) / 100) npr
     FROM connectionparam c, sharedconnectionparam s, connectionparamfullhours ph, pointfullhours pfh, feeders pi
    WHERE s.mid = an_mid
      AND s.nconnectionparam = c.nconnectionparam(+)
      AND c.nconnectionparam = ph.nconnectionparam(+)
      AND TO_NUMBER(TO_CHAR(ad_start, 'YYYYMM')) = ph.naccperiod(+)
      AND c.mid = pfh.mid(+)
      AND TO_NUMBER(TO_CHAR(ad_start, 'YYYYMM')) = pfh.naccperiod(+)
      AND c.mid = pi.mid(+);
  CURSOR lcur_p(lc_param NUMBER) IS
   /*Ищем все точки которые участвуют в доле по дележке потерь присоединения
     NNOTINCLUDECONSUMP - отвечает за включение расхода по точке в общее потребление по присоединению*/
   SELECT mid npoint, nnotincludeconsump
     FROM connectionparam
    WHERE nconnectionparam = lc_param
   UNION ALL
   SELECT mid npoint, nnotincludeconsump
     FROM sharedconnectionparam
    WHERE nconnectionparam = lc_param;
  CURSOR lcur_ss(lc_mid IN NUMBER) IS
   SELECT /*Дотягиваем информацию по остальным точкам, участвующим в дележке потерь
            а именно часы работы и наличае счетчиков для ответа на вопрос: Как счмтать
            расход реактивной (по активной или по показаниям реактивной)*/
          NVL(re.nratio, 0) nratio, pi.nrecompens nmeasurables,
          NVL(ph.nworkinghours, pi.nworkinghours) / ln_delim point_workinghours,
          NVL(ph.nfullhours, pi.nfullhours) / ln_delim nfullhours
     FROM feeders pi, recompens re, pointfullhours ph
    WHERE pi.mid = lc_mid
      AND pi.nrecompens = re.nrecompens(+)
      AND pi.mid = ph.mid(+)
      AND TO_NUMBER(TO_CHAR(ad_start, 'YYYYMM')) = ph.naccperiod(+)
      --проверка точки на "отлючено"
      AND NOT EXISTS( SELECT mid
                        FROM pointfullhours
                       WHERE naccperiod = TO_NUMBER(TO_CHAR(ad_start, 'YYYYMM')) AND mid = pi.mid AND nfullhours = 0);
 BEGIN
  p_setpotercoef(lr_potertemp, 0); --Зануляем lr_PoterTemp
  IF  ad_start = TRUNC(ad_start, 'MONTH') AND ADD_MONTHS(ad_start, 1) = ad_end THEN
   ln_delim := 1;
  ELSE
   ln_delim := NULL;
  END IF;
  -- ============ мы не считаем потери, а считаем потребление по точке за месяц ==
  IF an_potrebonly = 1 THEN
   SELECT NVL(SUM(NVL(DECODE(an_defdir, 1, er, ed), 0)), 0), --Мы игнорируем записи с nWasteabs=1 (по уст. мощности)
                                                            NVL(SUM(NVL(DECODE(an_defdir, 1, q1, q3), 0)), 0)
     INTO ln_a, ln_r
     FROM halfhour
    WHERE mid = an_mid AND date_time > ad_start AND date_time <= ad_end;
   SELECT NVL(SUM(NVL(DECODE(an_defdir, 1, aer, aed), 0)), 0), NVL(SUM(NVL(DECODE(an_defdir, 1, ber, bed), 0)), 0),
          NVL(SUM(NVL(DECODE(an_defdir, 1, cer, ced), 0)), 0), NVL(SUM(NVL(DECODE(an_defdir, 1, aq1, aq3), 0)), 0),
          NVL(SUM(NVL(DECODE(an_defdir, 1, bq1, bq3), 0)), 0), NVL(SUM(NVL(DECODE(an_defdir, 1, cq1, cq3), 0)), 0)
     INTO ln_a1, ln_a2,
          ln_a3, ln_r1,
          ln_r2, ln_r3
     FROM bill
    WHERE mid = an_mid AND date_time > ad_start AND date_time <= ad_end;
   IF an_act = 1 THEN --Нужно по активной
    lr_potertemp.z := ln_a;
    lr_potertemp.z1 := ln_a1;
    lr_potertemp.z2 := ln_a2;
    lr_potertemp.z3 := ln_a3;
   ELSE --Нужно по реактивной
    OPEN lcur_ss(an_mid);
    FETCH lcur_ss INTO ln_ratio, ln_measurables, ln_point_workinghours, ln_point_t0;
    IF lcur_ss%NOTFOUND THEN
     CLOSE lcur_ss;
     RETURN;
    END IF;
    CLOSE lcur_ss;
    IF ln_measurables >= 0 THEN --реактивная считается по активной
     lr_potertemp.z := ROUND(ln_a * ln_ratio);
     lr_potertemp.z1 := ROUND(ln_a1 * ln_ratio);
     lr_potertemp.z2 := ROUND(ln_a2 * ln_ratio);
     lr_potertemp.z3 := ROUND(ln_a3 * ln_ratio);
    ELSE
     lr_potertemp.z := ln_r;
     lr_potertemp.z1 := ln_r1;
     lr_potertemp.z2 := ln_r2;
     lr_potertemp.z3 := ln_r3;
    END IF;
   END IF;
   RETURN;
  END IF;
  -- =============================================================================

  SELECT COUNT(*)
    INTO ln_a
    FROM DUAL
   WHERE EXISTS( SELECT *
                   FROM connectionparam
                  WHERE mid = an_mid)
      OR EXISTS( SELECT *
                   FROM sharedconnectionparam
                  WHERE mid = an_mid);
  IF ln_a = 0 THEN --Если нет потерь
   RETURN;
  END IF;
  /*Далее мы считаем потери. Берем все присоединения, где фигурирует точка.
    Считаем расход по всем точкам привязанным к данному присоединению и на этот расход считаем
    потери. Берем свою часть (пропорционально расходу). Причем, если участвует одна точка, то
    все потери вешаются на нее (это принципиально, если расход=0 а потери есть {потери холостого хода} )
    Часы работы трансформатора ln_max_workinghours и время всей работы ln_maxT0
    (обычно не задано и следовательно равно кол-ву часов в месяце) ищутся как
    максимальные среди всех точек и самого присоединения*/
  FOR lc IN lcur_sel LOOP
   SELECT SUM(t.cn)
     INTO ln_count
     FROM (SELECT COUNT(*) cn
             FROM connectionparam c, feeders p
            WHERE c.nconnectionparam = lc.nconnectionparam AND c.mid = p.mid(+)
           UNION ALL
           SELECT COUNT(*) cn
             FROM sharedconnectionparam c, feeders p
            WHERE c.nconnectionparam = lc.nconnectionparam AND c.mid = p.mid(+)) t;
   IF ln_count = 0 THEN
    NULL;
   ELSIF  FALSE AND ln_count = 1 THEN --Не долевые
    IF NVL(lc.nworkinghours, 1) <> 0 THEN
     SELECT NVL(re.nratio, 0) nratio, pi.nrecompens, NVL(ph.nworkinghours, pi.nworkinghours) / ln_delim,
            NVL(ph.nfullhours / ln_delim, NVL(NVL(lc.nfullhours, pi.nfullhours) / ln_delim, ln_daycount * 24))
       INTO ln_ratio, ln_measurables, ln_max_workinghours,
            ln_maxt0
       FROM feeders pi, recompens re, pointfullhours ph
      WHERE pi.mid = an_mid
        AND pi.nrecompens = re.nrecompens(+)
        AND pi.mid = ph.mid(+)
        AND TO_NUMBER(TO_CHAR(ad_start, 'YYYYMM')) = ph.naccperiod(+);
     IF lc.nnotincludeconsump <> 1 THEN -- если расход по точке включается
      SELECT NVL(SUM(NVL(DECODE(an_defdir, 1, er, ed), 0)), 0), NVL(SUM(NVL(DECODE(an_defdir, 1, q1, q3), 0)), 0)
        INTO ln_a, ln_r
        FROM halfhour
       WHERE mid = an_mid AND date_time > ad_start AND date_time <= ad_end;
      IF ln_measurables >= 0 THEN
       ln_r := ROUND(ln_a * ln_ratio);
      END IF;
     ELSE
      ln_a := 0;
      ln_r := 0;
     END IF;
     ln_maxt0 := LEAST(ln_maxt0, ln_daycount * 24);
     ln_max_workinghours := LEAST(
                             ln_maxt0, NVL(
                                        GREATEST(
                                         NVL(lc.nworkinghours, ln_max_workinghours), NVL(
                                                                                      ln_max_workinghours,
                                                                                      lc.nworkinghours)), ln_daycount *
                                                                                                          24),
                             ln_daycount * 24);
     IF ln_max_workinghours > 0 THEN --Если max время работы=0, то потери равны 0 (так договорились)
      /*Та формула , что  на бумаге немного переписана. Отделены два слагаемых
        которые содержат сумму квадратов расхода и которые не содержат*/
      IF an_act = 1 THEN --активные потери
       ln_pr1 := lc.ndeltapidling * ln_maxt0;
       ln_pr2 := (lc.ndeltapsc / (lc.nsh * lc.nsh * ln_max_workinghours)) +
                 (((lc.nl / 1000) * lc.nro) /
                  (ln_max_workinghours * lc.nun * lc.nun));
      ELSE --реактивные потери
       ln_pr1 := (lc.nsn * lc.niidling) * (ln_maxt0 / 100);
       ln_pr2 := (lc.nusc / (100 * lc.nsh * ln_max_workinghours)) +
                 (((lc.nl / 1000) * lc.nxo) /
                  (ln_max_workinghours * lc.nun * lc.nun));
      END IF;
      IF lc.nprocent = 1 THEN
       ln_pr1 := 0;
       ln_pr2 := 1;
      END IF;
      p_defgetusedconsumpt(lc.nconnectionparam, ad_start, ad_end, ln_a, ln_r);
      ln_s2 := f_getsum2(ln_a, ln_r, lc.nconnectionparam, an_act, ad_start, ad_end, an_defdir);
      lr_potertemp.z := lr_potertemp.z +
                        (ln_pr1 + ln_s2 * ln_pr2) * lc.npr;
     END IF;
    END IF;
   ELSE --Долевые
    -- определяем есть параллельные присоединения или нет
    ln_provvar1 := f_provvar1(lc.nparallelconnection, TO_NUMBER(TO_CHAR(ad_start, 'YYYYMM')));
    ln_count := 0;
    ln_sa := 0;
    ln_sr := 0;
    ln_a1 := 0;
    ln_r1 := 0;
    lb_find := FALSE;
    ln_max_workinghours := lc.nworkinghours;
    ln_maxt0 := NULL;
    -- Для всех параметров из connectionparam где участвует данная точка
    FOR lcp IN lcur_p(lc.nconnectionparam) LOOP -- Ищем все точки которые участвуют в доле по дележке потерь присоединения
     OPEN lcur_ss(lcp.npoint); -- вытягиваем инфу по очередной точке которая в доле
     FETCH lcur_ss INTO ln_ratio, ln_measurables, ln_point_workinghours, ln_point_t0;
     IF lcur_ss%NOTFOUND THEN
      ln_ratio := NULL;
     END IF;
     CLOSE lcur_ss;
     IF ln_ratio IS NOT NULL THEN --точка открыта
      ln_count := ln_count + 1;
      -- Вытягиваем расход по точке -------------------------------------------
      SELECT NVL(SUM(NVL(DECODE(an_defdir, 1, er, ed), 0)), 0), NVL(SUM(NVL(DECODE(an_defdir, 1, q1, q3), 0)), 0)
        INTO ln_a, ln_r
        FROM halfhour
       WHERE mid = lcp.npoint AND date_time > ad_start AND date_time <= ad_end;
      -------------------------------------------------------------------------
      IF ln_measurables >= 0 THEN -- Если реактив считается как процент от актива
       ln_r := ROUND(ln_a * ln_ratio);
      END IF;
      IF lcp.npoint = an_mid THEN -- Если текущая совпадает со входной
       ln_a1 := ln_a;
       ln_r1 := ln_r;
       lb_find := TRUE;
      END IF;
      IF ln_point_t0 IS NOT NULL THEN -- nfullhours - полное время
       ln_maxt0 := GREATEST(ln_point_t0, NVL(ln_maxt0, ln_point_t0));
      END IF;
      IF ln_point_workinghours IS NOT NULL THEN -- Время работы
       ln_max_workinghours := GREATEST(ln_point_workinghours, NVL(ln_max_workinghours, ln_point_workinghours));
      END IF;
      IF lcp.nnotincludeconsump <> 1 THEN -- смотрим участвует ли расхот по данной точке
       ln_sa := ln_sa + ln_a;
       ln_sr := ln_sr + ln_r;
      END IF;
     END IF;
    END LOOP;
    IF ln_count > 0 THEN -- Если кол-во долевых точек > 0
     IF lc.nworkinghours = 0 THEN --Если на параметре присоединения время работы=0, то потери равны 0 (так договорились)
      ln_pr1 := 0;
      ln_pr2 := 0;
      ln_maxt0 := 0;
     ELSIF lc.nprocent = 1 THEN
      ln_pr1 := 0;
      ln_pr2 := 1;
     ELSE
      ln_maxt0 := LEAST(NVL(NVL(lc.nfullhours, ln_maxt0), ln_daycount * 24), ln_daycount * 24);
      ln_max_workinghours := LEAST(ln_maxt0, NVL(ln_max_workinghours, ln_daycount * 24), ln_daycount * 24);
      IF ln_max_workinghours = 0 THEN --Если max время работы=0, то потери равны 0 (так договорились)
       ln_pr1 := 0;
       ln_pr2 := 0;
      ELSIF lc.nprocent = 1 THEN
       ln_pr1 := 0;
       ln_pr2 := 1;
      ELSE
       IF an_act = 1 THEN --активные потери
        ln_pr1 := lc.ndeltapidling * ln_maxt0;
        ln_pr2 := (lc.ndeltapsc / (lc.nsh * lc.nsh * ln_max_workinghours)) +
                  (((lc.nl / 1000) * lc.nro) /
                   (ln_max_workinghours * lc.nun * lc.nun));
       ELSE --реактивные потери
        ln_pr1 := (lc.nsn * lc.niidling) * (ln_maxt0 / 100);
        ln_pr2 := (lc.nusc / (100 * lc.nsh * ln_max_workinghours)) +
                  (((lc.nl / 1000) * lc.nxo) /
                   (ln_max_workinghours * lc.nun * lc.nun));
       END IF;
      END IF;
     END IF;
     IF ln_provvar1 = 1 THEN -- есть спаренные трансформаторы без счетчиков
      -- Сумарное время работы всех паралельных присоединений
      ln_procparallel := f_defgetparallelproc(lc.nparallelconnection, ad_start, ad_end, ln_maxt0);
     ELSE
      ln_procparallel := 1;
     END IF;
     -- Возвращает расход актива и реактива по коэфиициенту вхождения из таблицы  * usedconsumpt *
     p_defgetusedconsumpt(lc.nconnectionparam, ad_start, ad_end, ln_sa, ln_sr);
     -- Возвращает потери по всем зависимым параметрам * relatedparam *
     ln_s2 := f_getsum2(
               ROUND(ln_procparallel * ln_sa), ROUND(ln_procparallel * ln_sr), lc.nconnectionparam, an_act, ad_start,
               ad_end, an_defdir); --сумма квадратов расходов с весом каждого трансформатора
     IF  ln_count = 1 AND lb_find AND (lc.nparallelconnection IS NULL OR ln_provvar1 = 1) THEN --одна точка
      lr_potertemp.z := lr_potertemp.z +
                        (ln_pr1 + ln_s2 * ln_pr2) * lc.npr;
     ELSE
      IF  lc.nparallelconnection IS NOT NULL AND ln_provvar1 = 0 THEN
       -- Считаем расход по всем точкам для всех параллельных параметров
       p_defgetsharesconsumption(lc.nparallelconnection, an_mid, ad_start, ad_end, an_defdir, ln_sa, ln_sr);
      END IF;
      IF an_act = 1 OR util_pg.calcreaktlossbyreakt_f = 0 THEN --Потери долевые рубим по активу
       IF ABS(ln_sa) > 0 THEN
        lr_potertemp.z := lr_potertemp.z +
                          (ln_pr1 + ln_s2 * ln_pr2) * lc.npr * LEAST(ln_a1 / ln_sa, 1);
       ELSIF  ABS(ln_sa) = 0 AND lc.mainpoint = 1 THEN
        lr_potertemp.z := lr_potertemp.z +
                          (ln_pr1 + ln_s2 * ln_pr2) * lc.npr;
       END IF;
      ELSE --Потери долевые рубим по реактиву
       IF ABS(ln_sr) > 0 THEN
        lr_potertemp.z := lr_potertemp.z +
                          (ln_pr1 + ln_s2 * ln_pr2) * lc.npr * LEAST(ln_r1 / ln_sr, 1);
       ELSIF  ABS(ln_sr) = 0 AND lc.mainpoint = 1 THEN
        lr_potertemp.z := lr_potertemp.z +
                          (ln_pr1 + ln_s2 * ln_pr2) * lc.npr;
       END IF;
      END IF;
     END IF;
    END IF;
   END IF;
  END LOOP;
 END;
 ------------------------------------------------------------------------------------------------
 FUNCTION f_defwaste(
  ad_start       DATE,
  ad_end         DATE,
  an_mid         NUMBER,
  av_zone        VARCHAR2,
  an_act         NUMBER,
  an_defdir      NUMBER,
  an_windingtype NUMBER DEFAULT 0)
  RETURN NUMBER IS
  ln_rez              NUMBER;
  ln_reznew           tr_potercoef;
  ln_reznew1          tr_potercoef;
  ln_potera           NUMBER;
  ln_poterr           NUMBER;
  ln_poter            NUMBER;
  ln_wastepercentcalc NUMBER;
  ln_count            NUMBER;
  ln_rezout           NUMBER;
  CURSOR lcur_coef IS -- Вытягиваем процент потерь (для потерь не по формуле)
   SELECT NVL(po.line_loss, 0) + NVL(po.act_loss, 0), NVL(po.react_loss, 0), nwastepercentcalc
     FROM feeders po
    WHERE po.mid = an_mid;
 BEGIN
  /*Примечание:
      Если требуются потери по зоне, то считаем сумарные потери, а потом берем зонное вложение.*/
  OPEN lcur_coef;
  FETCH lcur_coef INTO ln_potera, ln_poterr, ln_wastepercentcalc;
  IF lcur_coef%NOTFOUND THEN
   CLOSE lcur_coef;
   RETURN 0;
  END IF;
  CLOSE lcur_coef;
  IF ln_wastepercentcalc = 0 THEN
   RETURN 0;
  ELSIF ln_wastepercentcalc = 4 THEN --Потери по формуле
   f_defgetpoternew(ln_reznew, an_mid, an_act, ad_start, ad_end, 0, an_defdir); --Считаем потери в ln_RezNew
   IF av_zone = 'A' OR av_zone = 'B' OR av_zone = 'C' THEN --Потери по каждой зоне
    f_defgetpoternew(ln_reznew1, an_mid, an_act, ad_start, ad_end, 1, an_defdir); --Считаем расход в ln_RezNew1
    IF ln_reznew1.z1 + ln_reznew1.z2 + ln_reznew1.z3 = 0 THEN
     IF av_zone = 'C' THEN --Ошибки округления на третью зону
      RETURN ROUND(ln_reznew.z);
     ELSE
      RETURN 0;
     END IF;
    END IF;
    ln_rez := ROUND(ln_reznew.z);
    IF av_zone = 'A' THEN --Делим потери по зоне пропорционально вложению зоны
     ln_rez := ROUND((ln_rez * ln_reznew1.z1) / (ln_reznew1.z1 + ln_reznew1.z2 + ln_reznew1.z3));
    ELSIF av_zone = 'B' THEN
     ln_rez := ROUND((ln_rez * ln_reznew1.z2) / (ln_reznew1.z1 + ln_reznew1.z2 + ln_reznew1.z3));
    ELSE
     ln_rez := ROUND(
                ln_rez -
                ROUND(
                 (ln_rez * ln_reznew1.z1) / (ln_reznew1.z1 + ln_reznew1.z2 + ln_reznew1.z3)) -
                ROUND(
                 (ln_rez * ln_reznew1.z2) / (ln_reznew1.z1 + ln_reznew1.z2 + ln_reznew1.z3)));
    END IF;
   ELSE --потери без зон
    ln_rez := ln_reznew.z;
   END IF;
  ELSE
   IF ln_wastepercentcalc > 4 THEN --На будущее
    RETURN 0;
   END IF;
   IF an_act = 1 THEN
    ln_poter := ln_potera;
   ELSE
    ln_poter := ln_poterr;
   END IF;
   f_defgetpoternew(ln_reznew, an_mid, an_act, ad_start, ad_end, 1, an_defdir); --Считаем расход по точке в ln_RezNew
   IF ln_wastepercentcalc = 1 THEN --потери в процентах
    ln_rez := ROUND(ln_reznew.z * ln_poter / 100);
   ELSIF ln_wastepercentcalc = 2 THEN -- фиксированые потери
    ln_rez := ln_poter;
   ELSIF ln_wastepercentcalc = 3 THEN --потери процент в квадрате
    ln_rez := ROUND(ln_reznew.z * ln_reznew.z * ln_poter / 100000);
   END IF;
   IF av_zone = 'A' OR av_zone = 'B' OR av_zone = 'C' THEN --если по зоне то процентовка
    IF ln_reznew.z1 + ln_reznew.z2 + ln_reznew.z3 = 0 THEN
     IF av_zone = 'C' THEN --Ошибки округления на третью зону
      RETURN ROUND(ln_rez);
     ELSE
      RETURN 0;
     END IF;
    END IF;
    IF av_zone = 'A' THEN
     ln_rez := ROUND((ln_rez * ln_reznew.z1) / (ln_reznew.z1 + ln_reznew.z2 + ln_reznew.z3));
    ELSIF av_zone = 'B' THEN
     ln_rez := ROUND((ln_rez * ln_reznew.z2) / (ln_reznew.z1 + ln_reznew.z2 + ln_reznew.z3));
    ELSE --ошибки округления на 3 зону
     ln_rez := ROUND(
                ln_rez -
                ROUND(
                 (ln_rez * ln_reznew.z1) / (ln_reznew.z1 + ln_reznew.z2 + ln_reznew.z3)) -
                ROUND(
                 (ln_rez * ln_reznew.z2) / (ln_reznew.z1 + ln_reznew.z2 + ln_reznew.z3)));
    END IF;
   END IF;
  END IF;
  --    return ln_Rez;
  RETURN ROUND(ln_rez);
 END;
 ------------------------------------------------------------------------------------------------
  --считает порери и пишет в halfhourold
 PROCEDURE calcloss(ad_date DATE, an_mid NUMBER) IS
  ld_date DATE   DEFAULT TRUNC(ad_date);
  erw     NUMBER;
  edw     NUMBER;
  q1w     NUMBER;
  q3w     NUMBER;
 BEGIN
  IF NVL(util_pg.nlosstype, 0) <> 1 THEN
   RETURN;
  END IF;
  -- Считаем потери
  FOR lc IN (SELECT mid
               FROM feeders
              WHERE an_mid IS NULL AND nwastepercentcalc <> 0
             UNION ALL
             SELECT mid
               FROM feeders
              WHERE mid = an_mid AND nwastepercentcalc <> 0) LOOP
   DELETE FROM halfhourold
         WHERE mid = lc.mid AND date_time > ld_date AND date_time <= ld_date + 1 AND nsource < 0;
   erw := pointcalc_pg.f_defwaste(ad_date, ad_date + 1, lc.mid, NULL, 1, 1);
   edw := pointcalc_pg.f_defwaste(ad_date, ad_date + 1, lc.mid, NULL, 1, 0);
   q1w := pointcalc_pg.f_defwaste(ad_date, ad_date + 1, lc.mid, NULL, 0, 1);
   q3w := pointcalc_pg.f_defwaste(ad_date, ad_date + 1, lc.mid, NULL, 0, 0);
   INSERT INTO halfhourold
               (mid, date_time, nsource, nexceptcalc, er, ed, q1, q3)
    (SELECT lc.mid, h.date_time, -src, NULL, DECODE(ers, 0, 0, ROUND(erh * erw / ers)),
            DECODE(eds, 0, 0, ROUND(edh * edw / eds)),
            DECODE(q1s, 0, 0, ROUND(q1h * q1w / q1s)),
            DECODE(q3s, 0, 0, ROUND(q3h * q3w / q3s))
       FROM (SELECT   mid, date_time, SUM(er) erh, SUM(ed) edh, SUM(q1) q1h, SUM(q3) q3h
                 FROM halfhourold
                WHERE mid = lc.mid AND nexceptcalc IS NULL AND date_time > ld_date AND date_time <= ld_date + 1
             GROUP BY mid, date_time) h,
            (SELECT   mid, MAX(nsource) src, SUM(er) ers, SUM(ed) eds, SUM(q1) q1s, SUM(q3) q3s
                 FROM halfhourold
                WHERE mid = lc.mid AND nexceptcalc IS NULL AND date_time > ld_date AND date_time <= ld_date + 1
             GROUP BY mid) hh);
  END LOOP;
 END;
---------------------------------------------------------------------------------------------------
END;
/


