CREATE OR REPLACE 
PACKAGE BODY qm_pg IS
-------------------------------------------------------------------------------
--пакет для работы с меткой качества
-- 08.10.2008 Сечин А.А.
-------------------------------------------------------------------------------
 FUNCTION defqm
  RETURN VARCHAR2 IS
 BEGIN
  RETURN cv_defqm;
 END;

-------------------------------------------------------------------------------
 FUNCTION okqm
  RETURN VARCHAR2 IS
 BEGIN
  RETURN cv_okqm;
 END;

-------------------------------------------------------------------------------
 FUNCTION sbt (qm VARCHAR2, n NUMBER, val VARCHAR2)
  RETURN VARCHAR2 IS
 BEGIN
  RETURN sbt (qm, n, n, val);
 END;

-------------------------------------------------------------------------------
 FUNCTION sbt (qm VARCHAR2, n1 NUMBER, n2 NUMBER, val VARCHAR2)
  RETURN VARCHAR2 IS
  lv_qm   VARCHAR2 (32) := NVL (qm, cv_defqm);
 BEGIN
  RETURN SUBSTR (qm, 1, n1 - 1) || LPAD (val, n2 - n1 + 1, val) || SUBSTR (qm, n2 + 1, cn_lenqm - n2);
 END;

-------------------------------------------------------------------------------
 FUNCTION gbt (qm VARCHAR2, n NUMBER)
  RETURN VARCHAR2 IS
 BEGIN
  RETURN SUBSTR (qm, n, 1);
 END;

-------------------------------------------------------------------------------
 FUNCTION sumqm (av_qm1 VARCHAR2, av_qm2 VARCHAR2)
  RETURN VARCHAR2 IS
  lv_qm1   VARCHAR2 (32) := NVL (av_qm1, cv_defqm);
  lv_qm2   VARCHAR2 (32) := NVL (av_qm2, cv_defqm);
  lv_ret   VARCHAR2 (32) DEFAULT lv_qm1;
  lv_b1    VARCHAR2 (1);
  lv_b2    VARCHAR2 (1);
 BEGIN
  lv_b1 := gbt (lv_qm1, 1);
  lv_b2 := gbt (lv_qm2, 1);

  --Устанавливаем статус (1 бит)
  IF lv_b1 = cn_invalid OR lv_b2 = cn_invalid THEN   --Если есть хоть один инвалид то инвалид
   lv_ret := sbt (lv_ret, 1, cn_invalid);
  ELSIF lv_b1 IN (cn_question, cn_reserv) OR lv_b2 IN (cn_question, cn_reserv) THEN   --Если есть хоть один вопрос или нет данных то вопрос
   lv_ret := sbt (lv_ret, 1, cn_question);
  END IF;   --А иначе и так понятно что результат cn_ok

  --Устанавливаем биты по умолчанию  (2-19 и 21)
  lv_ret := sbt (lv_ret, 2, 19, cn_no);
  lv_ret := sbt (lv_ret, 2, 21, cn_no);

  --Устанавливаем дорасчет (20 бит)
  IF av_qm1 IS NULL OR av_qm2 IS NULL THEN   --если неполнота то неполнота
   lv_ret := sbt (lv_ret, 20, cn_add_insuff);
  ELSIF gbt (lv_qm1, 20) = cn_add_err OR gbt (lv_qm2, 20) = cn_add_err THEN   --если ошибка то ошибка
   lv_ret := sbt (lv_ret, 20, cn_add_err);
  ELSE   --иначе OK
   lv_ret := sbt (lv_ret, 20, cn_add_ok);
  END IF;

  --Устанавливаем источник (22 бит)
  lv_b1 := gbt (lv_qm1, 22);
  lv_b2 := gbt (lv_qm2, 22);

  IF lv_b1 = cn_manual OR lv_b2 = cn_manual THEN   --Если есть хоть один ручник то ручник
   lv_ret := sbt (lv_ret, 22, cn_manual);
  ELSIF lv_b1 = cn_add_main AND lv_b2 = cn_add_main THEN   --Оба главных то ничего т.к. результат главный
   NULL;
  ELSE
   lv_ret := sbt (lv_ret, 22, cn_calc);
  END IF;

  RETURN lv_ret;
 END;

-------------------------------------------------------------------------------
 FUNCTION rungqm (av_qm VARCHAR2)
  RETURN NUMBER IS   --Для order by  - Ранг метки
  lv_qm   VARCHAR2 (32) := NVL (av_qm, cv_defqm);
 BEGIN
  IF gbt (lv_qm, 1) = cn_ok THEN
   RETURN 1;
  ELSIF gbt (lv_qm, 1) = cn_question THEN
   RETURN 2;
  END IF;

  RETURN 1000;
 END;

-------------------------------------------------------------------------------
 FUNCTION intet_to_qm (an_status NUMBER)
  RETURN VARCHAR2 IS
  varstatus   VARCHAR (6);
  evstatus    NUMBER;
  qm          VARCHAR (22);
  valid       NUMBER;
  SOURCE      NUMBER;
  kodsource   NUMBER;
 BEGIN
  IF an_status = 0 THEN
   RETURN cv_defqm;
  ELSIF gbt (TO_CHAR (an_status), 1) = '2' THEN
   RETURN sbt (cv_defqm, 1, 1, cn_invalid);
  ELSIF gbt (TO_CHAR (an_status), 1) = '1' THEN
   evstatus := an_status - 100;
   qm := cv_defqm;
   valid := cn_ok;
   SOURCE := cn_process;
   kodsource := cn_add_main;

   WHILE evstatus > 0 LOOP
    varstatus := varstatus || TO_CHAR (MOD (evstatus, 2));
    evstatus := TRUNC (evstatus / 2);
   END LOOP;

   FOR i IN 1 .. LENGTH (varstatus) LOOP
    IF gbt (varstatus, i) = '1' THEN
     IF i = 1 THEN
      valid := cn_question;
     ELSIF i = 2 THEN
      kodsource := cn_manual;
      SOURCE := cn_subst;
     ELSIF i = 5 AND kodsource <> cn_manual THEN
      kodsource := cn_calc;
     END IF;
    END IF;
   END LOOP;

   qm := sbt (qm, 1, 1, TO_CHAR (valid));
   qm := sbt (qm, 10, 10, TO_CHAR (SOURCE));
   qm := sbt (qm, 22, 22, TO_CHAR (kodsource));
  END IF;

  RETURN qm;
 END;

-------------------------------------------------------------------------------
 FUNCTION ev2_to_qm (an_status NUMBER)
  RETURN VARCHAR2 IS
  varstatus   VARCHAR (6);
  evstatus    NUMBER;
  qm          VARCHAR (22);
  valid       NUMBER;
  SOURCE      NUMBER;
  kodsource   NUMBER;
 BEGIN
  IF an_status = 0 THEN
   RETURN cv_defqm;
  ELSE
   evstatus := an_status;
   qm := cv_defqm;
   valid := cn_ok;
   SOURCE := cn_process;
   kodsource := cn_add_main;

   WHILE evstatus > 0 LOOP
    varstatus := varstatus || TO_CHAR (MOD (evstatus, 2));
    evstatus := TRUNC (evstatus / 2);
   END LOOP;

   FOR i IN 1 .. LENGTH (varstatus) LOOP
    IF gbt (varstatus, i) = '1' THEN
     IF i = 1 THEN
      kodsource := cn_add_main;
     ELSIF i = 2 THEN
      SOURCE := cn_subst;
      kodsource := cn_manual;
     ELSIF i = 3 THEN
      valid := cn_invalid;

      IF kodsource <> cn_manual THEN
       kodsource := cn_calc;
      END IF;
     ELSIF i > 2 AND kodsource <> cn_manual THEN
      kodsource := cn_calc;
     END IF;
    END IF;
   END LOOP;

   qm := sbt (qm, 1, 1, TO_CHAR (valid));
   qm := sbt (qm, 10, 10, TO_CHAR (SOURCE));
   qm := sbt (qm, 22, 22, TO_CHAR (kodsource));
  END IF;

  RETURN qm;
 END;
-------------------------------------------------------------------------------
END;
/


