CREATE OR REPLACE 
PACKAGE BODY rates_pg IS
 ------------------------------------------------------------------------------------------------------------------------
   -- тарификация по режимным суткам
   -- дата создания 23.04.2002 (Коваленко А.С.)
 gn_task_code NUMBER DEFAULT 60;
 ------------------------------------------------------------------------------------------------------------------------
 PROCEDURE setendtime IS
 BEGIN
  UPDATE rates
     SET TIME = TIME - TRUNC(TIME, 'yyyy') + TRUNC(TIME, 'cc');
    
  UPDATE rates r
     SET endtime = (SELECT MIN(TIME)
                      FROM rates
                     WHERE rid = r.rid AND TIME > r.TIME);
  UPDATE rates r
     SET endtime = TRUNC(TIME) + 1 - 1 / 86400
   WHERE endtime IS NULL;
 --  commit;
 END;
 ------------------------------------------------------------------------------------------------------------------------
    -- Сохранение изменений по тарифам на указанную дату
 PROCEDURE update_tariff_p(
  an_rid         IN NUMBER, -- rid идентификатор тарифа
  ad_switch_date IN DATE, -- дата внедрения тарифа
  av_times       IN common_pg.tt_varchar2, -- массив строк - времена тарифных зон в формате 'hh24:mi:ss'
  av_rates       IN common_pg.tt_number -- массив строк - тарифы
  --an_fchange     IN NUMBER -- флаг изменения тарифов - 1-новый, 2-редактировать, 3-удалить
                          ) IS
  ln_rid  NUMBER;
  ln_date DATE;
  lv_msg  VARCHAR2(200);
 BEGIN
     SELECT switch_date
          INTO ln_date
           FROM rate_list
           WHERE rid = an_rid;
            ln_rid := an_rid;
      IF ln_date<>ad_switch_date THEN
      -- lv_msg := 'Изменено расписание на дату ' || TO_CHAR(ln_date, 'dd.mm.yyyy hh24:mi:ss');
       lv_msg := lv_msg || ' Новая дата ввода ' || TO_CHAR(ad_switch_date, 'dd.mm.yyyy hh24:mi:ss');
       admin_pg.fiscal_p(gn_task_code, 2, lv_msg);
       UPDATE rate_list
        SET switch_date = ad_switch_date
       WHERE rid = an_rid;
       END IF;
       DELETE FROM rates
         WHERE rid = an_rid;
         FOR i IN 1 .. av_times.COUNT LOOP
            IF  av_times.EXISTS(i) AND av_rates.EXISTS(i) THEN
       INSERT INTO rates
                (rid, TIME, rate)
         VALUES (ln_rid, TO_DATE('20000101 '||av_times(i), 'YYYYMMDD hh24:mi'), av_rates(i));
          END IF;
          END LOOP;
        
     setendtime;
  lv_msg := 'Изменено расписание на дату ' || TO_CHAR(ln_date, 'dd.mm.yyyy hh24:mi:ss');
  EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'rates_pg.update_tariff_p: ' || CHR(10) || SQLERRM(SQLCODE));

 END;
 -------------------------------------------------------------------------------------------------
  PROCEDURE ins_tariff_p(
  
  ad_switch_date IN DATE, -- дата внедрения тарифа
  av_times       IN common_pg.tt_varchar2, -- массив строк - времена тарифных зон в формате 'hh24:mi:ss'
  av_rates       IN common_pg.tt_number, -- массив строк - тарифы
  an_rid         OUT NUMBER -- rid идентификатор тарифа
                          ) IS

  ln_rid  NUMBER;
  ln_date DATE;
  lv_msg  VARCHAR2(200);
  BEGIN
    SELECT limits_seq.NEXTVAL
             INTO ln_rid
             FROM DUAL;
             an_rid:=ln_rid;
              admin_pg.fiscal_p(
              gn_task_code, 1, 'Добавлено расписание тарифов на дату ' || TO_CHAR(ad_switch_date, 'dd.mm.yyyy hh24:mi:ss'));
            INSERT INTO rate_list
              (rid, switch_date)
             VALUES (ln_rid, ad_switch_date);
              FOR i IN 1 .. av_times.COUNT LOOP
            IF  av_times.EXISTS(i) AND av_rates.EXISTS(i) THEN
           INSERT INTO rates
                (rid, TIME, rate)
         VALUES (ln_rid, TO_DATE('20000101 '||av_times(i), 'YYYYMMDD hh24:mi'), av_rates(i));
          END IF;
          END LOOP;
    setendtime;
   EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'rates_pg.ins_tariff_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;
 ------------------------------------------------------------------------------------------------------------------------
PROCEDURE del_tariff_p(
    an_rid         IN NUMBER) IS     -- rid идентификатор тарифа
  ln_date DATE;
 
 BEGIN
    SELECT switch_date
          INTO ln_date
           FROM rate_list
           WHERE rid = an_rid;
     admin_pg.fiscal_p(
     gn_task_code, 3, 'Удалено расписание тарифов на дату ' || TO_CHAR(ln_date, 'dd.mm.yyyy hh24:mi:ss'));
      DELETE FROM rate_list
         WHERE rid = an_rid;
  EXCEPTION
  WHEN OTHERS THEN
   raise_application_error(-20001, 'rates_pg.del_tariff_p: ' || CHR(10) || SQLERRM(SQLCODE));
END;
----------------------------------------------------------------------------------------
 --Клонирование расписания на след год
 PROCEDURE clone_p IS
  ld_start DATE;
  ln_rid   NUMBER;
 BEGIN
  SELECT TRUNC(MAX(switch_date), 'YYYY')
    INTO ld_start
    FROM rate_list;
  FOR lc IN (SELECT rid, ADD_MONTHS(switch_date, 12) dat
               FROM rate_list
              WHERE switch_date >= ld_start) LOOP
   SELECT limits_seq.NEXTVAL
     INTO ln_rid
     FROM DUAL;
   INSERT INTO rate_list
               (rid, switch_date)
        VALUES (ln_rid, lc.dat);
   INSERT INTO rates
               (rid, TIME, rate, endtime)
    SELECT ln_rid, TIME, rate, endtime
      FROM rates
     WHERE rid = lc.rid;
  END LOOP;
  IF ld_start is not null then
   admin_pg.fiscal_p(
    gn_task_code, 1, 'Выполнено клонирование расписания тарифных зон на ' || TO_CHAR(ld_start, 'yyyy')||' год.');
   COMMIT;
  end if;
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error(-20001, 'rates_pg.clone_p: ' || CHR(10) || SQLERRM(SQLCODE));
 END;
------------------------------------------------------------------------------------------------------------------------
-- Процедура чтения id
 PROCEDURE select_rid_p (acur_t OUT common_pg.tcur) IS
 BEGIN
   OPEN acur_t FOR
   SELECT rid, to_char(switch_date,'dd.mm.yyyy') switch_date1
                  FROM  rate_list
                  ORDER BY switch_date desc;
 END;
 -------------------------------------------------------------------------------------------------------------------------
 -- Процедура чтения данных
 PROCEDURE read_data_p (an_rid NUMBER ,acur_t OUT common_pg.tcur) IS
 BEGIN
   OPEN acur_t FOR
   SELECT to_char(time,'hh24:mi')time1, rate
                  FROM  rates
                  WHERE rid =an_rid
                  ORDER BY time;
                  
 END;
 -------------------------------------------------------------------------------------------------------------------------
END; -- Package Body RATE_PG
/


