 --Макет Казахстан
 PROCEDURE mkazah_p (an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS
  ln_step              NUMBER              DEFAULT 15 / 1440;
  lc_tab      CONSTANT VARCHAR2 (1)        := '#';
  lc_season   CONSTANT VARCHAR2 (1)        := '0';   -- указатель времени зима - лето, должен быть всегда = 0
  ld_date              DATE                DEFAULT util_pg.trunc_d (ad_date, ln_step);
  lt_ras               common_pg.tt_number;

  CURSOR lcur_g IS
   SELECT   ngroup, vcode
       FROM maketgroups
      WHERE nmaket = an_maket
   ORDER BY vcode, vname;

  CURSOR lcur_p (lc_group NUMBER) IS
   SELECT mid, nkc
     FROM maketpoints
    WHERE ngroup = lc_group;

  CURSOR lcur_r (lc_mid NUMBER) IS
   SELECT ROUND (SUM (b.er)) er, ROUND (SUM (b.ed)) ed, ROUND (SUM (b.q1)) q1, ROUND (SUM (b.q2)) q2, ROUND (SUM (b.q3)) q3, ROUND (SUM (b.q4)) q4
     FROM halfhour b
    WHERE b.mid = lc_mid AND b.date_time > ld_date AND b.date_time <= ld_date + ln_step;
 BEGIN
  FOR lc_g IN lcur_g LOOP
   FOR j IN 1 .. 6 LOOP
    lt_ras (j) := NULL;
   END LOOP;

   FOR lc_p IN lcur_p (lc_g.ngroup) LOOP
    FOR lc_r IN lcur_r (lc_p.mid) LOOP
     lt_ras (1) := util_pg.sumn (lt_ras (1), lc_p.nkc * lc_r.er);   --er
     lt_ras (2) := util_pg.sumn (lt_ras (2), lc_p.nkc * lc_r.ed);   --ed
     lt_ras (3) := util_pg.sumn (lt_ras (3), lc_p.nkc * lc_r.q1);   --q1
     lt_ras (4) := util_pg.sumn (lt_ras (4), lc_p.nkc * lc_r.q2);   --q2
     lt_ras (5) := util_pg.sumn (lt_ras (5), lc_p.nkc * lc_r.q3);   --q3
     lt_ras (6) := util_pg.sumn (lt_ras (6), lc_p.nkc * lc_r.q4);   --q4
    END LOOP;
   END LOOP;

   file_pg.out_p (   lc_g.vcode
                  || lc_tab
                  || TO_CHAR (ld_date + ln_step, 'DD/MM/YYYY HH24:MI')
                  || lc_tab
                  || lc_season
                  || lc_tab
                  || util_pg.get_num_dt (ld_date, 10, ln_step)
                  || lc_tab
                  || lt_ras (1)
                  || lc_tab
                  || lt_ras (2)
                  || lc_tab
                  || lt_ras (3)
                  || lc_tab
                  || lt_ras (4)
                  || lc_tab
                  || lt_ras (5)
                  || lc_tab
                  || lt_ras (6)
                  || lc_tab
                  || util_pg.sumn (lt_ras (3), lt_ras (6))
                  || lc_tab
                  || util_pg.sumn (lt_ras (4), lt_ras (5))
                  || lc_tab);
  END LOOP;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20001, 'reports1_pg.mkazah_p: ' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
  --Макет журнал счетчика Казахстан
 PROCEDURE jourkazah_p (an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS
  cn_lock     CONSTANT NUMBER       := 30;
  lc_tab      CONSTANT VARCHAR2 (1) := '#';
  lc_season   CONSTANT VARCHAR2 (1) := '0';   -- указатель времени зима - лето, должен быть всегда = 0
  ld_date              DATE;

  CURSOR lcur_sel (lc_dat DATE) IS
   SELECT   mg.vcode, e.evdate, e.evtype
       FROM ea_events e, maketpoints mp, maketgroups mg
      WHERE e.denter >= lc_dat AND e.mid = mp.mid AND mp.ngroup = mg.ngroup AND mg.nmaket = an_maket
   ORDER BY mg.vcode, e.evdate, e.evtype;
 BEGIN
  IF admin_pg.lock_p (cn_lock, 'ea_events') <> 1 THEN
   raise_application_error (-20009, 'Формирование файла не может быть произведено ввиду отсутствия возможности блокировки таблицы в течении ' || cn_lock || ' сек.',
                            TRUE);
  END IF;

  SELECT NVL (MAX (dlastcreated), SYSDATE - 500)
    INTO ld_date
    FROM makets
   WHERE nmaket = an_maket;

  IF file_pg.is_immediate = 1 THEN   --Если запущен вручную то уменьшаем до входного параметра
   ld_date := LEAST (NVL (ad_date, ld_date), ld_date);
  END IF;

  FOR lc IN lcur_sel (ld_date) LOOP
   file_pg.out_p (lc.vcode || lc_tab || TO_CHAR (lc.evdate, 'dd/mm/yyyy hh24:mi') || lc_tab || lc_season || lc_tab || lc.evtype || lc_tab || '0' || lc_tab || ''
                  || lc_tab);
  END LOOP;

  SYS.DBMS_LOCK.sleep (1);
 END;

------------------------------------------------------------------------------------------------------------------------
  --Макет ГН
 PROCEDURE m4024_p (an_maket NUMBER, ad_date DATE, av_fname IN OUT VARCHAR2) IS
  cn_step   CONSTANT NUMBER                := 1 / 48;   --:= CHR(9);
  lv_tab    CONSTANT VARCHAR2 (1)          := ':';   --:= CHR(9);
  cn_row    CONSTANT NUMBER                := 4;

  CURSOR lcur_g IS
   SELECT   ngroup, vcode
       FROM maketgroups
      WHERE nmaket = an_maket
   ORDER BY vname;

  CURSOR lcur_p (lc_group NUMBER) IS
   SELECT mid, nkc
     FROM maketpoints
    WHERE ngroup = lc_group;

  CURSOR lcur_s (lc_group NUMBER) IS
   SELECT     nsubgroup, nsign
         FROM maketformulas
   CONNECT BY PRIOR nsubgroup = ngroup
   START WITH ngroup = lc_group;

  CURSOR lcur_r (lc_mid NUMBER, lc_nkc NUMBER) IS
   SELECT   util_pg.get_num_dt (date_time - 1 / 86400, nsource, cn_step) dt, ROUND (DECODE (SIGN (lc_nkc), -1, SUM (b.ed), SUM (b.er)), cn_rn) er,
            ROUND (DECODE (SIGN (lc_nkc), -1, SUM (b.er), SUM (b.ed)), cn_rn) ed,
            ROUND (DECODE (SIGN (lc_nkc), -1, util_pg.sumn (SUM (b.q3), SUM (b.q4)), util_pg.sumn (SUM (b.q1), SUM (b.q2))), cn_rn) q1,
            ROUND (DECODE (SIGN (lc_nkc), -1, util_pg.sumn (SUM (b.q1), SUM (b.q2)), util_pg.sumn (SUM (b.q3), SUM (b.q4))), cn_rn) q3
       FROM halfhour b
      WHERE b.mid = lc_mid AND b.date_time > TRUNC (ad_date) AND b.date_time <= TRUNC (ad_date) + 1
   GROUP BY util_pg.get_num_dt (date_time - 1 / 86400, nsource, cn_step);

  lt_ras             common_pg.tt_number;
  lt_str             common_pg.tt_varchar2;
  ln_col             NUMBER                DEFAULT util_pg.get_count_dt (ad_date, cn_step) + 1;
  lv_bstr            VARCHAR2 (2000);
  lv_ent             VARCHAR2 (2000);
  ln_ost             NUMBER                := 0;
 BEGIN
  SELECT MAX (vparam)
    INTO lv_bstr
    FROM makets
   WHERE nmaket = an_maket;

  lv_ent := NVL (TRIM (util_pg.get_param (lv_bstr, 3)), util_pg.enterprise_char_f);
  file_pg.out_p ('((//' || NVL (TRIM (util_pg.get_param (lv_bstr, 5)), '4024') || ':' || TO_CHAR (ad_date, 'yymmdd') || ':' || lv_ent || '++');

  FOR lc_g IN lcur_g LOOP   --Идем по всем группам
   FOR i IN 1 .. ln_col LOOP   --Занулили временный массив
    FOR j IN 1 .. cn_row LOOP
     lt_ras (ln_col * (j - 1) + i) := NULL;
     lt_str (j) := '';
    END LOOP;
   END LOOP;

   FOR lc_p IN lcur_p (lc_g.ngroup) LOOP   --Просуммировали все точки в группе
    FOR lc_r IN lcur_r (lc_p.mid, lc_p.nkc) LOOP
     lt_ras (0 * ln_col + lc_r.dt) := util_pg.sumn (lt_ras (0 * ln_col + lc_r.dt), lc_r.er);
     lt_ras (1 * ln_col + lc_r.dt) := util_pg.sumn (lt_ras (1 * ln_col + lc_r.dt), lc_r.ed);
     lt_ras (2 * ln_col + lc_r.dt) := util_pg.sumn (lt_ras (2 * ln_col + lc_r.dt), lc_r.q1);
     lt_ras (3 * ln_col + lc_r.dt) := util_pg.sumn (lt_ras (3 * ln_col + lc_r.dt), lc_r.q3);
    END LOOP;
   END LOOP;

   FOR lc_s IN lcur_s (lc_g.ngroup) LOOP   --Просуммировали все дочерние подгруппы
    FOR lc_p IN lcur_p (lc_s.nsubgroup) LOOP
     FOR lc_r IN lcur_r (lc_p.mid, lc_p.nkc * lc_s.nsign) LOOP
      lt_ras (0 * ln_col + lc_r.dt) := util_pg.sumn (lt_ras (0 * ln_col + lc_r.dt), lc_r.er);
      lt_ras (1 * ln_col + lc_r.dt) := util_pg.sumn (lt_ras (1 * ln_col + lc_r.dt), lc_r.ed);
      lt_ras (2 * ln_col + lc_r.dt) := util_pg.sumn (lt_ras (2 * ln_col + lc_r.dt), lc_r.q1);
      lt_ras (3 * ln_col + lc_r.dt) := util_pg.sumn (lt_ras (3 * ln_col + lc_r.dt), lc_r.q3);
     END LOOP;
    END LOOP;
   END LOOP;

   --Округляем до целых, остатки переносим на следующее значение
   FOR j IN 1 .. cn_row LOOP
    ln_ost := 0;

    FOR i IN 1 .. ln_col - 1 LOOP
     lt_ras ((j - 1) * ln_col + i) := lt_ras ((j - 1) * ln_col + i) + ln_ost;
     ln_ost := lt_ras ((j - 1) * ln_col + i) - TRUNC (lt_ras ((j - 1) * ln_col + i));
     lt_ras ((j - 1) * ln_col + i) := TRUNC (lt_ras ((j - 1) * ln_col + i));
    END LOOP;
   END LOOP;

   FOR i IN 1 .. ln_col - 1 LOOP   --Вычислили cn_row суточных расхода
    FOR j IN 1 .. cn_row LOOP
     lt_ras ((j - 1) * ln_col + ln_col) := util_pg.sumn (lt_ras ((j - 1) * ln_col + ln_col), lt_ras ((j - 1) * ln_col + i));

     IF i = ln_col - 1 THEN
      lt_str (j) := lt_str (j) || lt_ras ((j - 1) * ln_col + i);
     ELSE
      lt_str (j) := lt_str (j) || lt_ras ((j - 1) * ln_col + i) || lv_tab;
     END IF;
    END LOOP;
   END LOOP;

   FOR j IN 1 .. cn_row LOOP   --Собрали cn_row сторк
    lt_str (j) :=
     '(' || lc_g.vcode || ':0' || j || ':' || ROUND (24 * 60 * cn_step) || ')' || lv_tab
     || REPLACE (lt_ras ((j - 1) * ln_col + ln_col) || lv_tab || lt_str (j), '.', ',');
    --IF lt_ras((j - 1) * ln_col + ln_col) IS NOT NULL THEN --Если что-то есть, то выводим
    file_pg.out_p (lt_str (j));
   --END IF;
   END LOOP;

   lt_ras.DELETE;
   lt_str.DELETE;
  END LOOP;

  file_pg.out_p ('==))');
 END;
------------------------------------------------------------------------------------------------------------------------
END;   -- Package Body REPORTS1_PG
/


