    PROCEDURE classic_rep (an_group NUMBER, av_param VARCHAR2, ad_sdate DATE, ad_edate DATE, an_wasteflag NUMBER, an_zone NUMBER default 0)
    IS
        lt_cons    common_pg.tt_number;
        lt_wast    common_pg.tt_number;
        lv_param   VARCHAR2 (2000)     DEFAULT av_param;

        CURSOR lcur_group
        IS
            SELECT gid, NAME, inverted, mid, vparam, group_total
              FROM GROUPS
             WHERE gid = an_group;
    BEGIN
        DELETE FROM rep_classic;

        lt_cons (1) := 0;
        lt_cons (2) := 0;
        lt_cons (3) := 0;
        lt_cons (4) := 0;
        lt_wast (1) := 0;
        lt_wast (2) := 0;
        lt_wast (3) := 0;
        lt_wast (4) := 0;

--  Для зон
-- А
        lt_cons (5) := 0;
        lt_cons (6) := 0;
        lt_cons (7) := 0;
        lt_cons (8) := 0;
        lt_wast (5) := 0;
        lt_wast (6) := 0;
        lt_wast (7) := 0;
        lt_wast (8) := 0;
-- В
        lt_cons (9) := 0;
        lt_cons (10) := 0;
        lt_cons (11) := 0;
        lt_cons (12) := 0;
        lt_wast (9) := 0;
        lt_wast (10) := 0;
        lt_wast (11) := 0;
        lt_wast (12) := 0;
-- С
        lt_cons (13) := 0;
        lt_cons (14) := 0;
        lt_cons (15) := 0;
        lt_cons (16) := 0;
        lt_wast (13) := 0;
        lt_wast (14) := 0;
        lt_wast (15) := 0;
        lt_wast (16) := 0;


        FOR lc IN lcur_group
        LOOP
            IF av_param IS NULL
            THEN
                lv_param := lc.vparam;
            END IF;

            summ_group (lc.gid, lc.NAME, lv_param, lc.mid, lc.inverted, 0, ad_sdate, ad_edate, an_wasteflag, lt_cons, lt_wast, an_zone);
        END LOOP;
/*        FOR lc IN lcur_group
        LOOP
            add_point (lc.gid, lc.NAME, lc.vparam, 41724, lc.inverted, 0, ad_sdate, ad_edate, an_wasteflag, lt_cons, lt_wast);
        END LOOP;*/
    END;

--------------------------------------------------------------------------------
--------------------------------------------------------------------------------
----------------- receiv_deliv_rep ---------------------------------------------
--------------------------------------------------------------------------------
--------------------------------------------------------------------------------
    PROCEDURE add_point_receiv_deliv (
        an_gid                  NUMBER,
        av_name                 VARCHAR2,
        av_param                VARCHAR2,
        an_mid                  NUMBER,
        av_inverted             VARCHAR2,
        an_level                NUMBER,
        ad_st                   DATE,
        ad_fin                  DATE,
        an_wasteflag            NUMBER,
        at_cons        IN OUT   common_pg.tt_number,
        at_wast        IN OUT   common_pg.tt_number
    )
    IS
        ln_dmid            NUMBER;   -- ИД дубля
        lv_dname           VARCHAR2 (300);   -- Имя дубля
        ld_st_ov           DATE           DEFAULT NULL;
        ld_fin_ov          DATE           DEFAULT NULL;
        ln_id_ov           NUMBER;   -- ИД обводника или основной точки
        lv_ov_name         VARCHAR2 (300);   -- имя обводника
        lv_ov_mtype        VARCHAR2 (20);   -- тип счетчика обводника
        lv_ov_mtrsn        VARCHAR2 (20);   -- номер счетчика обводника
        ld_st_dub          DATE;
        ld_fin_dub         DATE;
        ln_met_type        NUMBER;   -- 1 работаем по дублю 0- по основному
        ld_st_ch           DATE;
        ld_fin_ch          DATE;
        ln_ch              NUMBER;   -- 1 было снятие 0- небыло
        lv_sm              VARCHAR2 (20);   -- показания на начало
        lv_em              VARCHAR2 (20);   -- показания на конец
        ln_cons            NUMBER;
        ln_wast            NUMBER;
        ln_wast_d          NUMBER;
        lv_curr_ins_name   VARCHAR2 (300);   -- имя которое формируем динамически и вставляем в таблицу
        ln_entype          NUMBER;
        ln_kc              NUMBER;
        ln_kc_point        NUMBER;
        ln_curr_norder     NUMBER         DEFAULT 0;

        -- возвращает даты переключение на ОВ и обратно за отчетный период
        CURSOR lcur_ov_period (an_mid NUMBER)   -- сюда передаем ид основного счетчика. Соотсетственно в группах для отчетов тоже должны быть основные
        IS
            SELECT   ad_st ddate, an_mid ID
                FROM DUAL
               WHERE NOT EXISTS (
                         SELECT sw1.nswitch
                           FROM switches sw1, switches sw2
                          WHERE sw1.ID = sw2.ID
                            AND sw1.mid = an_mid
                            AND sw1.dswitch = (SELECT MAX (dswitch)
                                                 FROM switches
                                                WHERE mid = an_mid AND dswitch <= ad_st)
                            AND sw2.descape = (SELECT MIN (descape)
                                                 FROM switches
                                                WHERE mid = an_mid AND descape > ad_st))
            UNION ALL
            SELECT   ad_st ddate, sw1.nswitch ID
                FROM switches sw1, switches sw2
               WHERE sw1.ID = sw2.ID
                 AND sw1.mid = an_mid
                 AND sw1.dswitch = (SELECT MAX (dswitch)
                                      FROM switches
                                     WHERE mid = an_mid AND dswitch <= ad_st)
                 AND sw2.descape = (SELECT MIN (descape)
                                      FROM switches
                                     WHERE mid = an_mid AND descape > ad_st)
            UNION ALL
            SELECT   dswitch ddate, nswitch ID
                FROM switches
               WHERE mid = an_mid AND dswitch > ad_st AND dswitch < ad_fin
            UNION ALL
            SELECT   descape ddate, an_mid ID
                FROM switches
               WHERE mid = an_mid AND descape > ad_st AND descape < ad_fin
            UNION ALL
            SELECT   ad_fin ddate, an_mid ID
                FROM DUAL
            ORDER BY 1;

-- Возвращает даты перехода на дублирующие счетчики и обратно
        CURSOR lcur_dubperiod (an_dmid NUMBER, ad_stdate DATE, ad_findate DATE)   -- суда суем ИД дублируущего
        IS
            SELECT   ad_stdate ddate, 1 dubl
                FROM DUAL
               WHERE EXISTS (
                         SELECT *
                           FROM calcbyduplication cd1, calcbyduplication cd2
                          WHERE cd1.dstart = cd2.dstart
                            AND cd1.mid = cd2.mid
                            AND cd1.mid = an_dmid
                            AND cd1.dstart = (SELECT MAX (dstart)
                                                FROM calcbyduplication
                                               WHERE mid = an_dmid AND dstart <= ad_stdate)
                            AND (cd2.dend = (SELECT MIN (dend)
                                               FROM calcbyduplication
                                              WHERE mid = an_dmid AND dend > ad_stdate) OR cd2.dend IS NULL))
            UNION ALL
            SELECT   ad_stdate ddate, 0 dubl
                FROM DUAL
               WHERE NOT EXISTS (
                         SELECT *
                           FROM calcbyduplication cd1, calcbyduplication cd2
                          WHERE cd1.dstart = cd2.dstart
                            AND cd1.mid = cd2.mid
                            AND cd1.mid = an_dmid
                            AND cd1.dstart = (SELECT MAX (dstart)
                                                FROM calcbyduplication
                                               WHERE mid = an_dmid AND dstart <= ad_stdate)
                            AND (cd2.dend = (SELECT MIN (dend)
                                               FROM calcbyduplication
                                              WHERE mid = an_dmid AND dend > ad_stdate) OR cd2.dend IS NULL))
            UNION ALL
            SELECT   dstart ddate, 1 dubl
                FROM calcbyduplication
               WHERE mid = an_dmid AND dstart > ad_stdate AND dstart < ad_findate
            UNION ALL
            SELECT   dend ddate, 0 dubl
                FROM calcbyduplication
               WHERE mid = an_dmid AND dend > ad_stdate AND dend < ad_findate
            UNION ALL
            SELECT   ad_findate ddate, 0 dubl
                FROM DUAL
            ORDER BY 1;

-- возвращает даты замены счетчиков
        CURSOR lcur_change_met (an_dmid NUMBER, ad_stdate DATE, ad_findate DATE, an_entype NUMBER)   -- суда суем ИД основного или дублирующего в зависимости от ситуации
        IS
            SELECT   '1' mtrsn, '1' mtype, ad_stdate ddate, 0 ch
                FROM DUAL
            UNION ALL
            SELECT   mtrsn, mtype, dend ddate, 1 ch
                FROM metershistory
               WHERE mid = an_dmid AND dend >= ad_stdate AND dend < ad_findate AND entype IN (an_entype, 7)
            UNION ALL
            SELECT   mtrsn, mtype, ad_findate ddate, 0 ch
                FROM metershistory
               WHERE mid = an_dmid AND entype IN (an_entype, 7) AND date_time <= ad_stdate AND dend >= ad_findate
            UNION ALL
            SELECT   mtrsn, mtype, ad_findate ddate, 0 ch
                FROM meters
               WHERE mid = an_dmid
                 AND entype IN (an_entype, 7)
                 AND NOT EXISTS (SELECT mtrsn, mtype, ad_findate ddate, 0 ch
                                   FROM metershistory
                                  WHERE mid = an_dmid AND entype IN (an_entype, 7) AND date_time <= ad_stdate AND dend >= ad_findate)
            ORDER BY 3;
    BEGIN
        at_cons (1) := 0;
        at_cons (2) := 0;
        at_cons (3) := 0;
        at_cons (4) := 0;
        at_wast (1) := 0;
        at_wast (2) := 0;
        at_wast (3) := 0;
        at_wast (4) := 0;

        -- ищем ид дублирующего счетчика
        BEGIN
            SELECT f.mid, NAME
              INTO ln_dmid, lv_dname
              FROM feeders f, points p
             WHERE nmainpoint = an_mid AND f.mid = p.mid AND ROWNUM < 2;
        EXCEPTION
            WHEN NO_DATA_FOUND
            THEN
                ln_dmid := 0;
        END;

        SELECT kc
          INTO ln_kc_point
          FROM feeders
         WHERE mid = an_mid;

        FOR lc_ov IN lcur_ov_period (an_mid)   -- делаем цикл по переключениям ОВ
        LOOP
            ln_curr_norder := 0;

            IF ld_st_ov IS NOT NULL AND ld_fin_ov IS NULL
            THEN
                ld_fin_ov := lc_ov.ddate;

                SELECT kc
                  INTO ln_kc
                  FROM feeders
                 WHERE mid = ln_id_ov;

                IF ln_id_ov <> an_mid   -- т.е. было переключение на ОВ
                THEN
                    IF INSTR (NVL (av_param, ' '), 'априем') > 0
                    THEN
                        SELECT DECODE (av_inverted, 'y', 2, 1)
                          INTO ln_entype
                          FROM DUAL;

                        -- получаем атрибуты обводника
                        SELECT p.NAME, mtrsn, mtype
                          INTO lv_ov_name, lv_ov_mtrsn, lv_ov_mtype
                          FROM points p, meters m
                         WHERE p.mid = ln_id_ov AND p.mid = m.mid AND m.entype IN (7, ln_entype);

                        lv_curr_ins_name := av_name || ' -> ' || lv_ov_name;
                        lv_sm := util_pg.get_meterage_vch2 (ln_id_ov, ld_st_ov, ln_entype, 0);
                        lv_em := util_pg.get_meterage_vch2 (ln_id_ov, ld_fin_ov, ln_entype, 0);
                        ln_cons := NVL (util_pg.get_meterage_difference (ln_id_ov, ld_st_ov, ld_fin_ov, ln_entype, 0), 0);

                        IF an_wasteflag = 1
                        THEN
                            ln_wast := ROUND (NVL (waste_pg.get_point_waste (ln_id_ov, ld_st_ov, ld_fin_ov, ln_entype, 'difference'), 0));
                        ELSE
                            ln_wast := 0;
                        END IF;

                        at_cons (1) := at_cons (1) + ROUND (ln_cons * ln_kc);
                        at_wast (1) := at_wast (1) + ln_wast;

                        SELECT rep_seq.NEXTVAL
                          INTO ln_curr_norder
                          FROM DUAL;

                        INSERT INTO rep_receiv_deliv
                                    (gid, objtype, nlevel, NAME, ermtype, ermtrsn, eredate, erem, ersdate, ersm, erdif,
                                     erkc, ercons, norder
                                    )
                             VALUES (an_gid, 1, an_level, lv_curr_ins_name, lv_ov_mtype, lv_ov_mtrsn, ld_fin_ov, lv_em, ld_st_ov, lv_sm, ln_cons,
                                     ln_kc, ROUND (ln_cons * ln_kc), ln_curr_norder
                                    );
                    END IF;

                    IF INSTR (NVL (av_param, ' '), 'аотдача') > 0
                    THEN
                        SELECT DECODE (av_inverted, 'y', 1, 2)
                          INTO ln_entype
                          FROM DUAL;

                        -- получаем атрибуты обводника
                        SELECT p.NAME, mtrsn, mtype
                          INTO lv_ov_name, lv_ov_mtrsn, lv_ov_mtype
                          FROM points p, meters m
                         WHERE p.mid = ln_id_ov AND p.mid = m.mid AND m.entype IN (7, ln_entype);

                        lv_curr_ins_name := av_name || ' -> ' || lv_ov_name;
                        lv_sm := util_pg.get_meterage_vch2 (ln_id_ov, ld_st_ov, ln_entype, 0);
                        lv_em := util_pg.get_meterage_vch2 (ln_id_ov, ld_fin_ov, ln_entype, 0);
                        ln_cons := NVL (util_pg.get_meterage_difference (ln_id_ov, ld_st_ov, ld_fin_ov, ln_entype, 0), 0);

                        IF an_wasteflag = 1
                        THEN
                            ln_wast := ROUND (NVL (waste_pg.get_point_waste (ln_id_ov, ld_st_ov, ld_fin_ov, ln_entype, 'difference'), 0));
                        ELSE
                            ln_wast := 0;
                        END IF;

                        at_cons (2) := at_cons (2) + ROUND (ln_cons * ln_kc);
                        at_wast (2) := at_wast (2) + ln_wast;

                        IF ln_curr_norder > 0
                        THEN
                            UPDATE rep_receiv_deliv
                               SET edmtype = lv_ov_mtype,
                                   edmtrsn = lv_ov_mtrsn,
                                   ededate = ld_fin_ov,
                                   edem = lv_em,
                                   edsdate = ld_st_ov,
                                   edsm = lv_sm,
                                   eddif = ln_cons,
                                   edkc = ln_kc,
                                   edcons = ROUND (ln_cons * ln_kc)
                             WHERE norder = ln_curr_norder;
                        ELSE
                            INSERT INTO rep_receiv_deliv
                                        (gid, objtype, nlevel, NAME, edmtype, edmtrsn, ededate, edem, edsdate, edsm,
                                         eddif, edkc, edcons, norder
                                        )
                                 VALUES (an_gid, 1, an_level, lv_curr_ins_name, lv_ov_mtype, lv_ov_mtrsn, ld_fin_ov, lv_em, ld_st_ov, lv_sm,
                                         ln_cons, ln_kc, ROUND (ln_cons * ln_kc), rep_seq.NEXTVAL
                                        );
                        END IF;

                        ln_curr_norder := 0;
                    END IF;

                    IF INSTR (NVL (av_param, ' '), 'рприем') > 0
                    THEN
                        SELECT DECODE (av_inverted, 'y', 5, 3)
                          INTO ln_entype
                          FROM DUAL;

                        -- получаем атрибуты обводника
                        SELECT p.NAME, mtrsn, mtype
                          INTO lv_ov_name, lv_ov_mtrsn, lv_ov_mtype
                          FROM points p, meters m
                         WHERE p.mid = ln_id_ov AND p.mid = m.mid AND m.entype IN (7, ln_entype);

                        lv_curr_ins_name := av_name || ' -> ' || lv_ov_name;
                        lv_sm := util_pg.get_meterage_vch2 (ln_id_ov, ld_st_ov, ln_entype, 0);
                        lv_em := util_pg.get_meterage_vch2 (ln_id_ov, ld_fin_ov, ln_entype, 0);
                        ln_cons := NVL (util_pg.get_meterage_difference (ln_id_ov, ld_st_ov, ld_fin_ov, ln_entype, 0), 0);

                        IF an_wasteflag = 1
                        THEN
                            ln_wast := ROUND (NVL (waste_pg.get_point_waste (ln_id_ov, ld_st_ov, ld_fin_ov, ln_entype, 'difference'), 0));
                        ELSE
                            ln_wast := 0;
                        END IF;

                        at_cons (3) := at_cons (3) + ROUND (ln_cons * ln_kc);
                        at_wast (3) := at_wast (3) + ln_wast;

                        SELECT rep_seq.NEXTVAL
                          INTO ln_curr_norder
                          FROM DUAL;

                        INSERT INTO rep_receiv_deliv
                                    (gid, objtype, nlevel, NAME, ermtype, ermtrsn, eredate, erem, ersdate, ersm, erdif,
                                     erkc, ercons, norder
                                    )
                             VALUES (an_gid, 1, an_level, lv_curr_ins_name, lv_ov_mtype, lv_ov_mtrsn, ld_fin_ov, lv_em, ld_st_ov, lv_sm, ln_cons,
                                     ln_kc, ROUND (ln_cons * ln_kc), ln_curr_norder
                                    );
                    END IF;

                    IF INSTR (NVL (av_param, ' '), 'ргенер') > 0
                    THEN
                        SELECT DECODE (av_inverted, 'y', 3, 5)
                          INTO ln_entype
                          FROM DUAL;

                        -- получаем атрибуты обводника
                        SELECT p.NAME, mtrsn, mtype
                          INTO lv_ov_name, lv_ov_mtrsn, lv_ov_mtype
                          FROM points p, meters m
                         WHERE p.mid = ln_id_ov AND p.mid = m.mid AND m.entype IN (7, ln_entype);

                        lv_curr_ins_name := av_name || ' -> ' || lv_ov_name;
                        lv_sm := util_pg.get_meterage_vch2 (ln_id_ov, ld_st_ov, ln_entype, 0);
                        lv_em := util_pg.get_meterage_vch2 (ln_id_ov, ld_fin_ov, ln_entype, 0);
                        ln_cons := NVL (util_pg.get_meterage_difference (ln_id_ov, ld_st_ov, ld_fin_ov, ln_entype, 0), 0);

                        IF an_wasteflag = 1
                        THEN
                            ln_wast := ROUND (NVL (waste_pg.get_point_waste (ln_id_ov, ld_st_ov, ld_fin_ov, ln_entype, 'difference'), 0));
                        ELSE
                            ln_wast := 0;
                        END IF;

                        at_cons (4) := at_cons (4) + ROUND (ln_cons * ln_kc);
                        at_wast (4) := at_wast (4) + ln_wast;

                        IF ln_curr_norder > 0
                        THEN
                            UPDATE rep_receiv_deliv
                               SET edmtype = lv_ov_mtype,
                                   edmtrsn = lv_ov_mtrsn,
                                   ededate = ld_fin_ov,
                                   edem = lv_em,
                                   edsdate = ld_st_ov,
                                   edsm = lv_sm,
                                   eddif = ln_cons,
                                   edkc = ln_kc,
                                   edcons = ROUND (ln_cons * ln_kc)
                             WHERE norder = ln_curr_norder;
                        ELSE
                            INSERT INTO rep_receiv_deliv
                                        (gid, objtype, nlevel, NAME, edmtype, edmtrsn, ededate, edem, edsdate, edsm,
                                         eddif, edkc, edcons, norder
                                        )
                                 VALUES (an_gid, 1, an_level, lv_curr_ins_name, lv_ov_mtype, lv_ov_mtrsn, ld_fin_ov, lv_em, ld_st_ov, lv_sm,
                                         ln_cons, ln_kc, ROUND (ln_cons * ln_kc), rep_seq.NEXTVAL
                                        );
                        END IF;

                        ln_curr_norder := 0;
                    END IF;
                END IF;

--------------------------------------------
                ld_st_dub := NULL;
                ld_fin_dub := NULL;

                FOR lc_dub IN lcur_dubperiod (ln_dmid, ld_st_ov, ld_fin_ov)   -- цикл по переходам на дубли
                LOOP
                    ln_curr_norder := 0;

                    IF ld_st_dub IS NOT NULL AND ld_fin_dub IS NULL
                    THEN
                        ld_fin_dub := lc_dub.ddate;

-- Замены счетчиков выводим независимо от режимов ОВ и переключений на дубл
-- но разность показаний выводится только в случае если расчет ведется по этому счетчику
--==============================================================================
                        IF INSTR (NVL (av_param, ' '), 'априем') > 0
                        THEN
--+++++++++++++++++++++++++++++++++++++++++++
                            ld_st_ch := NULL;
                            ld_fin_ch := NULL;
                            ln_ch := 0;

                            SELECT DECODE (av_inverted, 'y', 2, 1)
                              INTO ln_entype
                              FROM DUAL;

                            FOR lc_ch IN lcur_change_met (an_mid, ld_st_dub, ld_fin_dub, ln_entype)   -- цикл по заменам счетчиков
                            LOOP
                                IF ld_st_ch IS NOT NULL AND ld_fin_ch IS NULL
                                THEN
                                    ld_fin_ch := lc_ch.ddate;

                                    IF lc_ch.ch = 1
                                    THEN
                                        lv_curr_ins_name := av_name || ' (снят)';
                                        ln_ch := 1;
                                    ELSE
                                        IF ln_ch = 1
                                        THEN
                                            lv_curr_ins_name := av_name || ' (уст.)';
                                        ELSE
                                            lv_curr_ins_name := av_name;
                                        END IF;
                                    END IF;

/*                                    IF ln_id_ov <> an_mid AND (lc_ch.ch = 1 OR ln_ch = 1) -- если необходимо учитывать замену
                                    THEN
                                        NULL;
                                    END IF;
*/
                                    lv_sm := util_pg.get_meterage_vch2 (an_mid, ld_st_ch, ln_entype, 1);
                                    lv_em := util_pg.get_meterage_vch2 (an_mid, ld_fin_ch, ln_entype, 0);   -- 0 - На момент снятия счетчика или в штатной ситуации
                                    ln_cons := util_pg.get_meterage_difference (an_mid, ld_st_ch, ld_fin_ch, ln_entype, 0);

                                    IF an_wasteflag = 1
                                    THEN
                                        ln_wast := ROUND (NVL (waste_pg.get_point_waste (an_mid, ld_st_ch, ld_fin_ch, ln_entype, 'difference'), 0));
                                    ELSE
                                        ln_wast := 0;
                                    END IF;

                                    IF ln_id_ov <> an_mid
                                    THEN
                                        ln_kc := ln_kc_point;
                                    END IF;

                                    at_cons (1) := at_cons (1) + ROUND (ln_cons * ln_kc);
                                    at_wast (1) := at_wast (1) + ln_wast;

                                    INSERT INTO rep_receiv_deliv
                                                (gid, objtype, nlevel, NAME, ermtype, ermtrsn, eredate, erem, ersdate, ersm,
                                                 erdif, erkc, ercons, norder
                                                )
                                         VALUES (an_gid, 1, an_level, lv_curr_ins_name, lc_ch.mtype, lc_ch.mtrsn, ld_fin_ch, lv_em, ld_st_ch, lv_sm,
                                                 ln_cons, ln_kc, ROUND (ln_cons * ln_kc), rep_seq.NEXTVAL
                                                );

                                    ld_st_ch := ld_fin_ch;
                                    ld_fin_ch := NULL;
                                END IF;

                                IF ld_st_ch IS NULL
                                THEN
                                    ld_st_ch := lc_ch.ddate;
                                END IF;

                                IF lc_ch.ch = 0 AND ln_ch = 1
                                THEN
                                    ln_ch := 0;
                                END IF;
                            END LOOP;
--+++++++++++++++++++++++++++++++++++++++++++
                        END IF;

                        IF INSTR (NVL (av_param, ' '), 'аотдача') > 0
                        THEN
--+++++++++++++++++++++++++++++++++++++++++++
                            ld_st_ch := NULL;
                            ld_fin_ch := NULL;
                            ln_ch := 0;

                            SELECT DECODE (av_inverted, 'y', 1, 2)
                              INTO ln_entype
                              FROM DUAL;

                            FOR lc_ch IN lcur_change_met (an_mid, ld_st_dub, ld_fin_dub, ln_entype)   -- цикл по заменам счетчиков
                            LOOP
                                IF ld_st_ch IS NOT NULL AND ld_fin_ch IS NULL
                                THEN
                                    ld_fin_ch := lc_ch.ddate;

                                    IF lc_ch.ch = 1
                                    THEN
                                        lv_curr_ins_name := av_name || ' (снят)';
                                        ln_ch := 1;
                                    ELSE
                                        IF ln_ch = 1
                                        THEN
                                            lv_curr_ins_name := av_name || ' (уст.)';
                                        ELSE
                                            lv_curr_ins_name := av_name;
                                        END IF;
                                    END IF;

                                    lv_sm := util_pg.get_meterage_vch2 (an_mid, ld_st_ch, ln_entype, 1);
                                    lv_em := util_pg.get_meterage_vch2 (an_mid, ld_fin_ch, ln_entype, 0);   -- 0 - На момент снятия счетчика или в штатной ситуации
                                    ln_cons := util_pg.get_meterage_difference (an_mid, ld_st_ch, ld_fin_ch, ln_entype, 0);

                                    IF an_wasteflag = 1
                                    THEN
                                        ln_wast := ROUND (NVL (waste_pg.get_point_waste (an_mid, ld_st_ch, ld_fin_ch, ln_entype, 'difference'), 0));
                                    ELSE
                                        ln_wast := 0;
                                    END IF;

                                    IF ln_id_ov <> an_mid
                                    THEN
                                        ln_kc := ln_kc_point;
                                    END IF;

                                    at_cons (2) := at_cons (2) + ROUND (ln_cons * ln_kc);
                                    at_wast (2) := at_wast (2) + ln_wast;

                                    BEGIN
                                        SELECT NVL (MIN (norder), 0)
                                          INTO ln_curr_norder
                                          FROM rep_receiv_deliv
                                         WHERE gid = an_gid AND edmtype IS NULL AND edmtrsn IS NULL AND edsdate IS NULL;
                                    EXCEPTION
                                        WHEN NO_DATA_FOUND
                                        THEN
                                            ln_curr_norder := 0;
                                    END;

                                    IF ln_curr_norder > 0
                                    THEN
                                        UPDATE rep_receiv_deliv
                                           SET edmtype = lc_ch.mtype,
                                               edmtrsn = lc_ch.mtrsn,
                                               ededate = ld_fin_ch,
                                               edem = lv_em,
                                               edsdate = ld_st_ch,
                                               edsm = lv_sm,
                                               eddif = ln_cons,
                                               edkc = ln_kc,
                                               edcons = ROUND (ln_cons * ln_kc)
                                         WHERE norder = ln_curr_norder;
                                    ELSE
                                        INSERT INTO rep_receiv_deliv
                                                    (gid, objtype, nlevel, NAME, edmtype, edmtrsn, ededate, edem, edsdate,
                                                     edsm, eddif, edkc, edcons, norder
                                                    )
                                             VALUES (an_gid, 1, an_level, lv_curr_ins_name, lc_ch.mtype, lc_ch.mtrsn, ld_fin_ch, lv_em, ld_st_ch,
                                                     lv_sm, ln_cons, ln_kc, ROUND (ln_cons * ln_kc), rep_seq.NEXTVAL
                                                    );
                                    END IF;

                                    ld_st_ch := ld_fin_ch;
                                    ld_fin_ch := NULL;
                                END IF;

                                IF ld_st_ch IS NULL
                                THEN
                                    ld_st_ch := lc_ch.ddate;
                                END IF;

                                IF lc_ch.ch = 0 AND ln_ch = 1
                                THEN
                                    ln_ch := 0;
                                END IF;
                            END LOOP;
--+++++++++++++++++++++++++++++++++++++++++++
                        END IF;

                        IF INSTR (NVL (av_param, ' '), 'рприем') > 0
