--+++++++++++++++++++++++++++++++++++++++++++
                            ld_st_ch := NULL;
                            ld_fin_ch := NULL;
                            ln_ch := 0;

                            SELECT DECODE (av_inverted, 'y', 5, 3)
                              INTO ln_entype
