-- а теперь пишем в таблицу потери, притом, отдельной строкой, как и просил Сашка
        IF (INSTR (NVL (av_param, ' '), 'потери_апр') > 0) OR INSTR (NVL (av_param, ' '), 'потери_аотд') > 0
