    PROCEDURE summ_group_receiv_deliv (
        an_gid                  NUMBER,
        av_name                 VARCHAR2,
        av_param                VARCHAR2,
        an_mid                  NUMBER,
        av_inverted             VARCHAR2,
        an_level                NUMBER,
        ad_st                   DATE,
        ad_fin                  DATE,
        an_wasteflag            NUMBER,
        at_cons        IN OUT   common_pg.tt_number,
        at_wast        IN OUT   common_pg.tt_number
    )
    IS
        ln_curr_norder   NUMBER              DEFAULT 0;

        CURSOR lcur_group
        IS
            SELECT   gid, NAME, inverted, mid, vparam
                FROM GROUPS
               WHERE PARENT = an_gid
            ORDER BY vparam;

        lt_cons          common_pg.tt_number;
        lt_wast          common_pg.tt_number;
    BEGIN
        lt_cons (1) := 0;
        lt_cons (2) := 0;
        lt_cons (3) := 0;
        lt_cons (4) := 0;
        lt_wast (1) := 0;
        lt_wast (2) := 0;
        lt_wast (3) := 0;
        lt_wast (4) := 0;

        IF an_mid IS NULL
        THEN   -- то есть группа
            ln_curr_norder := 0;

            INSERT INTO rep_receiv_deliv
                        (gid, objtype, nlevel, NAME, norder
                        )
                 VALUES (an_gid, 0, an_level, av_name, rep_seq.NEXTVAL
                        );

            FOR lc IN lcur_group
            LOOP
                summ_group_receiv_deliv (lc.gid, lc.NAME, lc.vparam, lc.mid, lc.inverted, an_level + 1, ad_st, ad_fin, an_wasteflag, lt_cons,
                                         lt_wast);
            END LOOP;

            IF INSTR (NVL (av_param, ' '), 'априем') > 0
            THEN
                SELECT rep_seq.NEXTVAL
                  INTO ln_curr_norder
                  FROM DUAL;

                INSERT INTO rep_receiv_deliv
                            (gid, objtype, nlevel, NAME, ercons, norder
                            )
                     VALUES (an_gid, 0, an_level, 'ИТОГО', lt_cons (1), ln_curr_norder
                            );
            END IF;

            IF INSTR (NVL (av_param, ' '), 'аотдача') > 0
            THEN
                IF ln_curr_norder > 0
                THEN
                    UPDATE rep_receiv_deliv
                       SET edcons = lt_cons (2)
                     WHERE norder = ln_curr_norder;
                ELSE
                    INSERT INTO rep_receiv_deliv
                                (gid, objtype, nlevel, NAME, edcons, norder
                                )
                         VALUES (an_gid, 0, an_level, 'ИТОГО', lt_cons (2), rep_seq.NEXTVAL
                                );
                END IF;

                ln_curr_norder := 0;
            END IF;

            IF INSTR (NVL (av_param, ' '), 'рприем') > 0
            THEN
                SELECT rep_seq.NEXTVAL
                  INTO ln_curr_norder
                  FROM DUAL;

                INSERT INTO rep_receiv_deliv
                            (gid, objtype, nlevel, NAME, ercons, norder
                            )
                     VALUES (an_gid, 0, an_level, 'ИТОГО', lt_cons (3), ln_curr_norder
                            );
            END IF;

            IF INSTR (NVL (av_param, ' '), 'ргенер') > 0
            THEN
                IF ln_curr_norder > 0
                THEN
                    UPDATE rep_receiv_deliv
                       SET edcons = lt_cons (4)
                     WHERE norder = ln_curr_norder;
                ELSE
                    INSERT INTO rep_receiv_deliv
                                (gid, objtype, nlevel, NAME, edcons, norder
                                )
                         VALUES (an_gid, 0, an_level, 'ИТОГО', lt_cons (4), rep_seq.NEXTVAL
                                );
                END IF;

                ln_curr_norder := 0;
            END IF;
/*            IF INSTR (NVL (av_param, ' '), 'асальдо') > 0
            THEN
                INSERT INTO rep_classic
                            (gid, objtype, nlevel, NAME, etype, cons, norder
                            )
                     VALUES (an_gid, 0, an_level, 'САЛЬДО', 'А', lt_cons (1) - lt_cons (2), rep_seq.NEXTVAL
                            );
            END IF;*/
        ELSE   -- тоесть точка
            add_point_receiv_deliv (an_gid, av_name, av_param, an_mid, av_inverted, an_level, ad_st, ad_fin, an_wasteflag, lt_cons, lt_wast);
        END IF;

        at_cons (1) := lt_cons (1) + at_cons (1);
        at_cons (2) := lt_cons (2) + at_cons (2);
        at_cons (3) := lt_cons (3) + at_cons (3);
        at_cons (4) := lt_cons (4) + at_cons (4);
        at_wast (1) := lt_wast (1) + at_wast (1);
        at_wast (2) := lt_wast (2) + at_wast (2);
        at_wast (3) := lt_wast (3) + at_wast (3);
        at_wast (4) := lt_wast (4) + at_wast (4);
    END;

--------------------------------------------------------------------------------
    PROCEDURE receiv_deliv_rep (an_group NUMBER, av_param VARCHAR2, ad_sdate DATE, ad_edate DATE, an_wasteflag NUMBER)
    IS
        lt_cons    common_pg.tt_number;
        lt_wast    common_pg.tt_number;
        lv_param   VARCHAR2 (2000)     DEFAULT av_param;

        CURSOR lcur_group
        IS
            SELECT gid, NAME, inverted, mid, vparam, group_total
              FROM GROUPS
             WHERE gid = an_group;
    BEGIN
        DELETE FROM rep_receiv_deliv;

        lt_cons (1) := 0;
        lt_cons (2) := 0;
        lt_cons (3) := 0;
        lt_cons (4) := 0;
        lt_wast (1) := 0;
        lt_wast (2) := 0;
        lt_wast (3) := 0;
        lt_wast (4) := 0;

        FOR lc IN lcur_group
        LOOP
            IF av_param IS NULL
            THEN
                lv_param := lc.vparam;
            END IF;

            summ_group_receiv_deliv (lc.gid, lc.NAME, lv_param, lc.mid, lc.inverted, 0, ad_sdate, ad_edate, an_wasteflag, lt_cons, lt_wast);
        END LOOP;
/*        FOR lc IN lcur_group
        LOOP
            add_point (lc.gid, lc.NAME, lc.vparam, 41724, lc.inverted, 0, ad_sdate, ad_edate, an_wasteflag, lt_cons, lt_wast);
        END LOOP;*/
    END;
--------------------------------------------------------------------------------
END;
