                                                 FROM points gr1
                                                WHERE gr1.PARENT = gr.mid)
    ORDER BY t, vname;
  ELSE
   OPEN acur_t FOR
    SELECT   1 pp, gr.gid mid, util_pg.get_name_f (gr.NAME, gr.mid) vname, DECODE (gr.mid, NULL, 0, 10) + DECODE (gr.inverted, 'y', 2, 1) pr,
             DECODE (gr.mid, NULL, 0, 10) t
        FROM GROUPS gr
       WHERE gr.PARENT = an_id AND EXISTS (SELECT *
                                             FROM GROUPS gr1
                                            WHERE gr1.PARENT = gr.gid)
    UNION ALL
    SELECT   2 pp, gr.gid mid, util_pg.get_name_f (gr.NAME, gr.mid) vname, DECODE (gr.mid, NULL, 0, 10) + DECODE (gr.inverted, 'y', 2, 1) pr,
             DECODE (gr.mid, NULL, 0, 10) t
        FROM GROUPS gr
       WHERE gr.PARENT = an_id AND NOT EXISTS (SELECT *
                                                 FROM GROUPS gr1
                                                WHERE gr1.PARENT = gr.gid)
    ORDER BY t, vname;
  END IF;
 END;

