 PROCEDURE selectgroupproc_getalltree_p (an_codetemplate NUMBER, an_idformtree NUMBER, an_setvisualcontrols NUMBER,   --//Установка доступности
 acur_t OUT common_pg.tcur) IS
 BEGIN
  IF ((an_codetemplate <> 1000) AND (an_codetemplate <> 1100)) THEN
   OPEN acur_t FOR
    SELECT   1 pp, gr.gid, NVL (gr.NAME, '') vname, DECODE (gr.mid, NULL, 0, 10) + DECODE (gr.inverted, 'y', 2, 1) pr, DECODE (gr.mid, NULL, 0, 10) t
        FROM GROUPS gr, form_group fg
       WHERE gr.gid = fg.gid AND fg.fid = an_idformtree AND EXISTS (SELECT *
                                                                      FROM GROUPS gr1
                                                                     WHERE gr1.PARENT = gr.gid) AND an_setvisualcontrols > 2
    UNION ALL
    SELECT   2 pp, gr.gid, NVL (gr.NAME, '') vname, DECODE (gr.mid, NULL, 0, 10) + DECODE (gr.inverted, 'y', 2, 1) pr, DECODE (gr.mid, NULL, 0, 10) t
        FROM GROUPS gr, form_group fg
       WHERE gr.gid = fg.gid AND fg.fid = an_idformtree
             AND (NOT EXISTS (SELECT *
                                FROM GROUPS gr1
                               WHERE gr1.PARENT = gr.gid) OR EXISTS (SELECT *
                                                                       FROM GROUPS gr1
                                                                      WHERE gr1.PARENT = gr.gid) AND an_setvisualcontrols <= 2)
    ORDER BY t, vname;
  ELSE
   IF (an_codetemplate = 1000) THEN
    OPEN acur_t FOR
     SELECT   1 lev, t1.task_id, NVL (t1.task_cod, 0) task_cod, NVL (t1.NAME, '') vname, DECODE (t1.task_cod, NULL, 0, 0, 0, 1) t
         FROM tasks t1
        WHERE t1.PARENT IS NULL AND EXISTS (SELECT *
                                              FROM tasks
                                             WHERE PARENT = t1.task_id)
     UNION ALL
     SELECT   2 lev, t1.task_id, NVL (t1.task_cod, 0) task_cod, NVL (t1.NAME, '') vname, DECODE (t1.task_cod, NULL, 0, 0, 0, 1) t
         FROM tasks t1
        WHERE t1.PARENT IS NULL AND NOT EXISTS (SELECT *
                                                  FROM tasks
                                                 WHERE PARENT = t1.task_id)
     ORDER BY t, vname;
   ELSE
    OPEN acur_t FOR
     SELECT   1 lev, p.mid, NVL (p.ind, 1) task_cod, NVL (p.NAME, '') vname, DECODE (p.ind, NULL, 1, 1, 1, 2, 1, 3) t
         FROM points p
        WHERE PARENT IS NULL AND EXISTS (SELECT *
                                           FROM points
                                          WHERE PARENT = p.mid)
     UNION ALL
     SELECT   2 lev, p.mid, NVL (p.ind, 1) task_cod, NVL (p.NAME, '') vname, DECODE (p.ind, NULL, 1, 1, 1, 2, 1, 3) t
         FROM points p
        WHERE PARENT IS NULL AND NOT EXISTS (SELECT *
                                               FROM points
                                              WHERE PARENT = p.mid)
     ORDER BY t, vname;
   END IF;
  END IF;
 END;

