 PROCEDURE selectform_addpoints_p (an_lmid NUMBER, an_data NUMBER, an_tn NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  IF (an_tn = 0) THEN
   IF (an_lmid < 0) THEN
    OPEN acur_t FOR
     SELECT   1 pp, gr.mid, util_pg.get_name_f (gr.NAME, gr.mid) vname, decode(gr.ind,1,0,2,0,3,1,600,6,610,8,500,7,5) t ,
     gr.NORDER,decode(gr.ind,1,decode(gr.cod,0,1,1000),2,decode(gr.cod,0,1,1000),3,3,4,3,600,6,610,8,500,5)tt
         FROM points gr
        WHERE gr.mid = (SELECT MIN (mid)
