    UNION ALL
    SELECT   2 pp, gr.mid, util_pg.get_name_f (gr.NAME, gr.mid) vname, DECODE (gr.ind, 3, -1, -2) t
        FROM points gr
       WHERE PARENT = an_data AND NOT EXISTS (SELECT *
