 PROCEDURE selectform_getselectedtree_p (an_codetemplate NUMBER, an_ispoints NUMBER, an_idgroup NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  IF ((an_codetemplate <> 1000) AND (an_codetemplate <> 1100)) THEN
   IF (an_ispoints = 1) THEN
    OPEN acur_t FOR
     SELECT     mid ID
           FROM points
     CONNECT BY PRIOR PARENT = mid
     START WITH mid = an_idgroup;
   ELSE
    OPEN acur_t FOR
     SELECT     gid ID
           FROM GROUPS
     CONNECT BY PRIOR PARENT = gid
     START WITH gid = an_idgroup;
   END IF;
  ELSE
   IF (an_codetemplate = 1000) THEN
    OPEN acur_t FOR
     SELECT     task_id ID
           FROM tasks
     CONNECT BY PRIOR PARENT = task_id
     START WITH task_id = an_idgroup;
   ELSE
    OPEN acur_t FOR
     SELECT     mid ID
           FROM points
     CONNECT BY PRIOR PARENT = mid
     START WITH mid = an_idgroup;
   END IF;
  END IF;
 END;

-------------------------------------------------------------------------------------------------------------------------
 PROCEDURE selectpoint_read_node (an_gid NUMBER, an_flag NUMBER, acur_t OUT common_pg.tcur) IS
  -- added 01.08.2008  Kondakov A.G.
  -- используется в TfmSelectPoint::ReadNode и в TfmSetupFilters
  av_gid    VARCHAR2 (100);
  av_gid2   VARCHAR2 (100);
  lv_sql    VARCHAR2 (4000);
 BEGIN
  IF (an_gid = 0) THEN
   IF (an_flag = 1) THEN
    av_gid := ' Parent is NULL ';
   ELSIF (an_flag = 2) THEN
    av_gid := ' p.PARENT=1 ';
   ELSIF (an_flag = 3) THEN
    av_gid := ' p.PARENT IS NULL ';
   ELSIF (an_flag = 4) THEN
    av_gid := ' gid=indic_pg.getoutputgroup ';
   ELSIF (an_flag = 5) THEN
    av_gid := ' p.PARENT IS NULL AND p.COD=0 ';
   ELSIF (an_flag = 6) THEN
    av_gid := ' p.nPARENT IS NULL ';
   ELSIF (an_flag = 8) THEN
    -- av_gid := ' p.mid=1000 ';
    av_gid := ' p.PARENT IS NULL AND p.COD=0 ';
    av_gid2 := ' p.Parent is NULL ';
   END IF;
  ELSE
   IF (an_flag = 1) THEN
    av_gid := ' parent=' || TO_CHAR (an_gid);
   ELSIF (an_flag = 2) THEN
    av_gid := ' p.parent=' || TO_CHAR (an_gid);
   ELSIF (an_flag = 3) THEN
    av_gid := ' p.parent=' || TO_CHAR (an_gid);
   ELSIF (an_flag = 4) THEN
    av_gid := ' parent=' || TO_CHAR (an_gid);
   ELSIF (an_flag = 5) THEN
    av_gid := ' p.parent=' || TO_CHAR (an_gid);
   ELSIF (an_flag = 6) THEN
    av_gid := ' p.nparent=' || TO_CHAR (an_gid);
   ELSIF (an_flag = 8) THEN
    av_gid := ' p.parent=' || TO_CHAR (an_gid);
    av_gid2 := ' p.parent=' || TO_CHAR (an_gid);
   END IF;
  END IF;

  IF (an_flag = 1) THEN
   lv_sql :=
    'SELECT 1 HaveChild, gid mid , decode(mid,NULL,4,1) TYPE, nvl(NAME,'' '') NAME ,util_pg.get_pointname(mid, 2) pinfo
                  FROM GROUPS p
                  WHERE '
    || av_gid
    || '
                     AND EXISTS (SELECT * FROM GROUPS WHERE parent=p.gid)
                  UNION ALL
                  SELECT 0 HaveChild, gid, decode(mid,NULL,4,1) TYPE, nvl(NAME,'' '') NAME ,util_pg.get_pointname(mid, 2) pinfo
                  FROM GROUPS p
                  WHERE '
    || av_gid || '
                     AND NOT EXISTS (SELECT * FROM GROUPS WHERE parent=p.gid)
                  ORDER BY 3,4';
  ELSIF (an_flag = 2) THEN
   lv_sql :=
    'SELECT 1 HaveChild, p.mid, decode(c.cid,NULL,0,1) TYPE, nvl(c.vname,nvl(p.NAME,'' '')) NAME, ''Канал: ''||nvl(c.vname,nvl(p.NAME,'' '')) pinfo
                  FROM points p,channels c
                  WHERE '
    || av_gid
