  ELSIF (an_flag = 5) THEN
   lv_sql :=
   /* 'SELECT 1 HaveChild, p.mid, decode(p.ind,1,0,2,0,3,1,5) TYPE ,decode(p.ind,1,1,2,1,3), nvl(p.NAME,'' '') NAME, util_pg.get_pointname(p.mid, 2) pinfo
   FROM points p
