CREATE OR REPLACE 
PACKAGE BODY switches_pg IS
   -- пакет работы с переключениями ов
   -- дата создания 02/12/2002 (Коваленко А.С)
   -- 05/12/2002 реализация проверок, расчетов и переносов (Вештак)
------------------------------------------------------------------------------------------------------------------------
 gn_task_code   NUMBER        DEFAULT 72;
 cv_source      VARCHAR2 (64) := 'ОВ';

------------------------------------------------------------------------------------------------------------------------
  -- Процедура вставки
 PROCEDURE ins_p (an_switch NUMBER,   --Ид ОВ
                                   ad_switch DATE,   --Дата переключения
                                                  an_mid NUMBER,   --Ид точки
                                                                an_erm NUMBER,   --Показание ОВ
                                                                              an_edm NUMBER,   --Показание ОВ
                                                                                            an_q1m NUMBER,   --Показание ОВ
                                                                                                          an_q2m NUMBER,   --Показание ОВ
                                                                                                                        an_q3m NUMBER,   --Показание ОВ
                                                                                                                                      an_q4m NUMBER,   --Показание ОВ
 an_user_id NUMBER,   --Ид пользователя
                   an_id OUT NUMBER   --Ид строки
 ) IS
  ln_mid       NUMBER         := an_mid;
  prevmid      NUMBER;
  ad_escape    DATE;
  realescape   DATE;
  ntemp        NUMBER;
  dtemp        DATE;
  vtemp        VARCHAR2 (500);
  exact        NUMBER;
  nstate_      NUMBER;
  er_          NUMBER;
  ed_          NUMBER;
  q1_          NUMBER;
  q2_          NUMBER;
  q3_          NUMBER;
  q4_          NUMBER;
  kc_          NUMBER;
  q1234_       NUMBER;
 BEGIN
  SELECT MAX (kc), MAX (DECODE (q1234, '*', 1, 0))
    INTO kc_, q1234_
    FROM feeders
   WHERE mid = an_switch;

  -- поиск даты конца периода переключения
  SELECT MIN (dswitch)
    INTO ad_escape
    FROM switches
   WHERE nswitch = an_switch AND dswitch >= ad_switch;

  IF ad_escape IS NULL THEN
   ad_escape := TO_DATE ('01.01.3001', 'dd.mm.yyyy');
  END IF;

  BEGIN
   -- Находим ИД предыдущего переключения
   SELECT NVL (mid, nswitch)
     INTO ntemp
     FROM switches
    WHERE nswitch = an_switch AND dswitch = (SELECT MAX (dswitch)
                                               FROM switches
                                              WHERE nswitch = an_switch AND dswitch < ad_switch);
  EXCEPTION
   WHEN OTHERS THEN
    ntemp := an_switch;
  END;

  IF ntemp <> an_switch AND an_mid <> an_switch THEN
   raise_application_error (-20001, 'ОВ не может переключаться с точки на точку без перевода самого на себя!');
  END IF;

  BEGIN
   SELECT mid
     INTO ntemp
     FROM switches
    WHERE nswitch = an_switch AND dswitch = ad_escape;
  EXCEPTION
   WHEN OTHERS THEN
    ntemp := 0;
  END;

  IF an_mid = ntemp THEN
   raise_application_error (-20001, 'Заданное назначение ОВ совпадает со следующим назначением!');
  END IF;

  BEGIN
   SELECT mid
     INTO ntemp
     FROM switches
    WHERE nswitch = an_switch AND dswitch <= ad_switch AND descape >= ad_switch;
  EXCEPTION
   WHEN OTHERS THEN
    ntemp := 0;
  END;

  IF an_mid = ntemp THEN
   raise_application_error (-20001, 'Заданное назначение ОВ совпадает с предыдущим назначением!');
  END IF;

  IF ad_switch = ad_escape THEN
   raise_application_error (-20001, 'Для заданного ОВ и заданной даты уже есть запись в истории переключений!');
  END IF;

  IF an_switch <> an_mid THEN   -- проверяем, что по точке нет данных и нет другого ОВ в периоде переключения
   /*
     begin
       select count(*), min(date_time) into ntemp, dtemp from halfhourold where mid = an_mid and nsource in (10, 20)
       and date_time > ad_switch and date_time <= ad_escape;
       exception when others then ntemp := 0;
     end;
     if ntemp <> 0 then
       raise_application_error(-20001,'Некорректный период. По точке учета есть данные с '||to_char(dtemp,'dd.mm.yyyy hh24:mi'));
       return;
     end if;
   */
   BEGIN
    SELECT MIN (nswitch)
      INTO ntemp
      FROM switches
     WHERE nswitch <> an_switch AND mid = an_mid
           AND ((dswitch >= ad_switch AND dswitch < ad_escape) OR (descape > ad_switch AND descape <= ad_escape) OR (dswitch <= ad_switch AND descape >= ad_escape));
   EXCEPTION
    WHEN OTHERS THEN
     ntemp := 0;
   END;

   IF ntemp <> 0 THEN
    SELECT NAME
      INTO vtemp
      FROM points
     WHERE mid = ntemp;

    raise_application_error (-20001, 'Обнаружено пересечение периодов переключений с ОВ ' || vtemp);
   END IF;
  END IF;

  IF an_switch = an_mid THEN
   ln_mid := NULL;
  END IF;

  SELECT points_seq.NEXTVAL
    INTO an_id
    FROM DUAL;

  INSERT INTO switches
              (ID, nswitch, dswitch, mid, erm, edm, q1m, q2m, q3m, q4m, denter, user_id, descape
              )
       VALUES (an_id, an_switch, ad_switch, ln_mid, an_erm, an_edm, an_q1m, an_q2m, an_q3m, an_q4m, SYSDATE, an_user_id, ad_escape
              );

  indic_pg.setindic (an_switch, ad_switch, 1, 8, 1, cv_source, 'Переключение ОВ', util_pg.get_mtrsn (an_switch, 1), kc_, an_erm,
                     util_pg.indicoverturn (an_erm - indic_pg.getlastindic (an_switch, ad_switch, 1, NULL, 8), NULL) * kc_);
  indic_pg.setindic (an_switch, ad_switch, 2, 8, 1, cv_source, 'Переключение ОВ', util_pg.get_mtrsn (an_switch, 2), kc_, an_edm,
                     util_pg.indicoverturn (an_edm - indic_pg.getlastindic (an_switch, ad_switch, 2, NULL, 8), NULL) * kc_);
  indic_pg.setindic (an_switch, ad_switch, 3, 8, 1, cv_source, 'Переключение ОВ', util_pg.get_mtrsn (an_switch, 3), kc_, an_q1m,
                     util_pg.indicoverturn (an_q1m - indic_pg.getlastindic (an_switch, ad_switch, 3, NULL, 8), NULL) * kc_);
  indic_pg.setindic (an_switch, ad_switch, 5, 8, 1, cv_source, 'Переключение ОВ', util_pg.get_mtrsn (an_switch, 5), kc_, an_q3m,
                     util_pg.indicoverturn (an_q3m - indic_pg.getlastindic (an_switch, ad_switch, 5, NULL, 8), NULL) * kc_);

  IF q1234_ > 0 THEN
   indic_pg.setindic (an_switch, ad_switch, 4, 8, 1, cv_source, 'Переключение ОВ', util_pg.get_mtrsn (an_switch, 4), kc_, an_q2m,
                      util_pg.indicoverturn (an_q2m - indic_pg.getlastindic (an_switch, ad_switch, 4, NULL, 8), NULL) * kc_);
   indic_pg.setindic (an_switch, ad_switch, 6, 8, 1, cv_source, 'Переключение ОВ', util_pg.get_mtrsn (an_switch, 6), kc_, an_q4m,
                      util_pg.indicoverturn (an_q4m - indic_pg.getlastindic (an_switch, ad_switch, 6, NULL, 8), NULL) * kc_);
  END IF;

  -- корректируем конец периода предыдущего переключения
  UPDATE switches
     SET descape = ad_switch
   WHERE nswitch = an_switch AND dswitch = (SELECT MAX (dswitch)
                                              FROM switches
                                             WHERE nswitch = an_switch AND dswitch < ad_switch);

  BEGIN
   SELECT mid
     INTO prevmid
     FROM switches
    WHERE nswitch = an_switch AND descape = ad_switch;
  EXCEPTION
   WHEN OTHERS THEN
    prevmid := an_switch;
  END;

  realescape := TRUNC (ad_escape) + FLOOR (TO_CHAR (ad_escape, 'sssss') / 1800) * 1800 / 24 / 60 / 60;

  IF realescape <> ad_escape THEN
   realescape := realescape + 1 / 48;
  END IF;

  IF prevmid <> an_switch THEN
   /* last
       update halfhourold h set nexceptcalc = (select nexceptcalc from halfhourold
         where date_time = h.date_time and nsource = h.nsource+20 and nswitch = an_switch)
       where mid = an_switch and date_time > ad_switch and date_time <= ad_escape;
                                    -- удаляем возможные дубликаты профиля ОВ в точках учета
       delete from halfhourold where nswitch = an_switch and date_time > ad_switch and date_time <= ad_escape;
   */
   UPDATE halfhourold
      SET nexceptcalc = 1
    WHERE mid = prevmid AND nsource >= 30 AND nsource < util_pg.cn_manualinput AND date_time > ad_switch AND date_time <= ad_escape;
  END IF;

  IF an_switch <> an_mid THEN   -- если ОВ переключили на точку, то дублируем профиль ОВ с ид точки
   DELETE FROM halfhourold
         WHERE mid = an_mid AND nswitch = an_switch AND date_time > ad_switch AND date_time <= ad_escape;

   INSERT INTO halfhourold
               (mid, date_time, nsource, nswitch, nexceptcalc, er, ed, q1, q2, q3, q4, erm, edm, q1m, q2m, q3m, q4m, nkc, vqm)
    (SELECT an_mid, date_time, nsource + 20, an_switch, nexceptcalc, er, ed, q1, q2, q3, q4, erm, edm, q1m, q2m, q3m, q4m, nkc,
            qm_pg.sbt (NVL (vqm, qm_pg.cv_okqm), 22, qm_pg.cn_ov)
       FROM halfhourold
      WHERE mid = an_switch AND nsource >= 10 AND nsource < 30 AND date_time > ad_switch AND date_time <= ad_escape);
  /*                                 -- исключаем из расчета профиль ОВ
      update halfhourold set nexceptcalc = 1 where mid = an_switch and date_time  > ad_switch
       and date_time <= realescape and nsource in (10, 20);
  */
  END IF;

  exact := 1;

  IF TO_CHAR (ad_switch, 'sssss') = FLOOR (TO_CHAR (ad_switch, 'sssss') / 1800) * 1800 THEN
   exact := 0;
  END IF;

  nstate_ := 0;
  vtemp := '';

  IF NVL (an_erm, 0) = 0 AND NVL (an_edm, 0) = 0 AND NVL (an_q1m, 0) = 0 AND NVL (an_q2m, 0) = 0 AND NVL (an_q3m, 0) = 0 AND NVL (an_q4m, 0) = 0 THEN
   nstate_ := 2;
   vtemp := 'Нет показаний ОВ на момент переключения';
  END IF;

  BEGIN
   SELECT COUNT (*)
     INTO ntemp
     FROM monthsorg
    WHERE mid = an_switch AND date_time = TRUNC (ad_switch, 'mm') AND nsource = 10;
  EXCEPTION
   WHEN OTHERS THEN
    ntemp := 0;
  END;

  IF ntemp = 0 THEN
   nstate_ := 2;
   vtemp := 'Нет показаний OB на начало месяца';
  END IF;

  BEGIN
   dtemp := TRUNC (ad_switch) + FLOOR (TO_CHAR (ad_switch, 'sssss') / 1800) * 1800 / 24 / 60 / 60 + 1 / 48;

   SELECT MIN (nsource)
     INTO ntemp
     FROM halfhourold
    WHERE mid = an_switch AND date_time = dtemp;
  EXCEPTION
   WHEN OTHERS THEN
    ntemp := 0;
  END;

  IF ntemp = 0 THEN
   nstate_ := 2;
   vtemp := 'Нет профиля нагрузки OB на момент переключения';
  END IF;

  IF nstate_ = 0 THEN
   SELECT MAX (digits)
     INTO ntemp
     FROM meters
    WHERE mid = an_switch;

   SELECT kc_ * (NVL (an_erm, erm) - erm - CEIL ((SIGN (NVL (an_erm, erm) - erm) - 1) / 2) * FLOOR (ntemp + 1)),
          kc_ * (NVL (an_edm, edm) - edm - CEIL ((SIGN (NVL (an_edm, edm) - edm) - 1) / 2) * FLOOR (ntemp + 1)),
          kc_ * (NVL (an_q1m, q1m) - q1m - CEIL ((SIGN (NVL (an_q1m, q1m) - q1m) - 1) / 2) * FLOOR (ntemp + 1)),
          kc_ * (NVL (an_q2m, q2m) - q2m - CEIL ((SIGN (NVL (an_q2m, q2m) - q2m) - 1) / 2) * FLOOR (ntemp + 1)),
          kc_ * (NVL (an_q3m, q3m) - q3m - CEIL ((SIGN (NVL (an_q3m, q3m) - q3m) - 1) / 2) * FLOOR (ntemp + 1)),
          kc_ * (NVL (an_q4m, q4m) - q4m - CEIL ((SIGN (NVL (an_q4m, q4m) - q4m) - 1) / 2) * FLOOR (ntemp + 1))
     INTO er_,
          ed_,
          q1_,
          q2_,
          q3_,
          q4_
     FROM monthsorg
    WHERE mid = an_switch AND date_time = TRUNC (ad_switch, 'mm') AND nsource = 10;

   SELECT er_ - SUM (er), ed_ - SUM (ed), q1_ - SUM (q1), q2_ - SUM (q2), q3_ - SUM (q3), q4_ - SUM (q4)
     INTO er_, ed_, q1_, q2_, q3_, q4_
     FROM halfhourold
    WHERE mid = an_switch AND date_time > TRUNC (ad_switch, 'mm') AND date_time <= ad_switch AND nexceptcalc IS NULL;

   IF prevmid <> an_switch THEN
    INSERT INTO halfhourold
                (mid, date_time, nsource, nswitch, nexceptcalc, er, ed, q1, q2, q3, q4, nkc
                )
         VALUES (prevmid, dtemp, util_pg.cn_manualinput, an_switch, NULL, er_, ed_, q1_, q2_, q3_, q4_, kc_
                );

    das_pg.calcpoint4bill (prevmid, ad_switch, ad_escape);
   END IF;

   IF an_switch <> an_mid THEN
    SELECT SUM (er - er_), SUM (ed - ed_), SUM (q1 - q1_), SUM (q2 - q2_), SUM (q3 - q3_), SUM (q4 - q4_)
      INTO er_, ed_, q1_, q2_, q3_, q4_
      FROM halfhourold
     WHERE mid = an_switch AND date_time = dtemp AND nexceptcalc IS NULL;

    INSERT INTO halfhourold
                (mid, date_time, nsource, nswitch, nexceptcalc, er, ed, q1, q2, q3, q4, nkc
                )
         VALUES (an_mid, dtemp, util_pg.cn_manualinput, an_switch, NULL, er_, ed_, q1_, q2_, q3_, q4_, kc_
                );

    DELETE FROM halfhourold
          WHERE mid = an_mid AND date_time = dtemp AND nsource >= 30 AND nsource < util_pg.cn_manualinput;

    das_pg.calcpoint4bill (an_mid, ad_switch, ad_escape);
   END IF;
  END IF;

  UPDATE switches
     SET nstate = DECODE (nstate_, 0, 1, 1, 2, 0),
         verror = vtemp
   WHERE ID = an_id;

  IF util_pg.get_customer_id = 3 THEN
   das_pg.calcperiod4bill (TRUNC (ad_switch), TRUNC (SYSDATE));
  END IF;

  IF NOT (an_switch = an_mid) THEN   --Начало работы обходного
   file_pg.startbyevents_p (43, an_id, ad_switch);
  ELSE
   file_pg.startbyevents_p (44, an_id, ad_switch);
  END IF;

  admin_pg.fiscal_p (gn_task_code, 1,
                     'Введено переключение ОВ ' || util_pg.node_path_f (an_switch, 'points', 'mid', 'parent') || ' с ' || TO_CHAR (ad_switch, 'dd.mm.yyyy hh24:mi')
                     || ' на точку ' || util_pg.node_path_f (an_mid, 'points', 'mid', 'parent'));
 END;

