  -- Процедура обновления данных
 PROCEDURE upd_p (an_id NUMBER,   --Ид строки
                               an_switch NUMBER,   --Ид ОВ
                                                ad_switch DATE,   --Дата переключения
                                                               an_mid NUMBER,   --Ид точки
                                                                             an_erm NUMBER,   --Показание ОВ
                                                                                           an_edm NUMBER,   --Показание ОВ
                                                                                                         an_q1m NUMBER,   --Показание ОВ
                                                                                                                       an_q2m NUMBER,   --Показание ОВ
                                                                                                                                     an_q3m NUMBER,   --Показание ОВ
 an_q4m NUMBER,   --Показание ОВ
               an_user_id NUMBER   --Ид пользователя
 ) IS
  ln_mid      NUMBER         := an_mid;
  prevmid     NUMBER;
  ad_escape   DATE;
  ntemp       NUMBER;
  dtemp       DATE;
  vtemp       VARCHAR2 (500);
 BEGIN
  del_p (an_id);
  ins_p (an_switch, ad_switch, an_mid, an_erm, an_edm, an_q1m, an_q2m, an_q3m, an_q4m, an_user_id, ntemp);

  UPDATE switches
     SET ID = an_id
   WHERE ID = ntemp;
 /*
     IF an_switch = an_mid THEN
         ln_mid := NULL;
      END IF;
    UPDATE switches SET NSWITCH = an_switch, DSWITCH = ad_switch,MID = ln_mid,ERM = an_erm,
                        EDM = an_edm,Q1M = an_q1m,Q2M = an_q2m,Q3M = an_q3m,Q4M = an_q4m,
                        DENTER = sysdate,USER_ID = an_user_id
    WHERE ID = an_id;
 */
 EXCEPTION
  WHEN OTHERS THEN
   ROLLBACK;
   raise_application_error (-20001, 'switches_pg.upd_p: Ошибка редaктирования переключения ОВ. ' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура удаления данных
 PROCEDURE del_p (an_id NUMBER   --Ид строки
                              ) IS
  an_switch    NUMBER;
  an_mid       NUMBER;
  prevmid      NUMBER;
  nextmid      NUMBER;
  ad_switch    DATE;
  ad_escape    DATE;
  realswitch   DATE;
  realescape   DATE;
  ntemp        NUMBER;
  dtemp        DATE;
  er_          NUMBER;
  ed_          NUMBER;
  q1_          NUMBER;
  q2_          NUMBER;
  q3_          NUMBER;
  q4_          NUMBER;
  kc_          NUMBER;
  ld_tmp       DATE;
 BEGIN
  SELECT nswitch, dswitch, descape, NVL (mid, nswitch)
    INTO an_switch, ad_switch, ad_escape, an_mid
    FROM switches
   WHERE ID = an_id;

  realswitch := TRUNC (ad_switch) + FLOOR (TO_CHAR (ad_switch, 'sssss') / 1800) * 1800 / 24 / 60 / 60;

  IF realswitch <> ad_switch THEN
   realswitch := realswitch + 1 / 48;
  END IF;

  realescape := TRUNC (ad_escape) + FLOOR (TO_CHAR (ad_escape, 'sssss') / 1800) * 1800 / 24 / 60 / 60;

  IF realescape <> ad_escape THEN
   realescape := realescape + 1 / 48;
  END IF;

  BEGIN
   SELECT NVL (mid, an_switch)
     INTO prevmid
     FROM switches
    WHERE nswitch = an_switch AND descape = ad_switch;
  EXCEPTION
   WHEN OTHERS THEN
    prevmid := an_switch;
  END;

  BEGIN
   SELECT NVL (mid, an_switch)
     INTO nextmid
     FROM switches
    WHERE nswitch = an_switch AND dswitch = ad_escape;
  EXCEPTION
   WHEN OTHERS THEN
    nextmid := 0;
  END;

  IF nextmid <> 0 THEN
   IF nextmid <> prevmid THEN
    raise_application_error (-20001, 'Нельзя удалить/редактировать переключение ОВ, если оно не последнее!');
   END IF;
  END IF;

  SELECT MAX (kc)
    INTO kc_
    FROM feeders
   WHERE mid = an_switch;

  IF an_mid <> an_switch THEN
   DELETE FROM halfhourold
         WHERE mid = an_mid AND nswitch = an_switch AND date_time > ad_switch AND date_time <= ad_escape;

   das_pg.calcpoint4bill (an_mid, ad_switch, ad_escape);
  ELSE
   DELETE FROM halfhourold
         WHERE mid = prevmid AND nswitch = an_switch AND date_time > ad_switch AND date_time <= ad_escape;

   INSERT INTO halfhourold
               (mid, date_time, nsource, nswitch, nexceptcalc, er, ed, q1, q2, q3, q4, erm, edm, q1m, q2m, q3m, q4m, nkc,vqm)
    (SELECT prevmid, date_time, nsource + 20, an_switch, nexceptcalc, er, ed, q1, q2, q3, q4, erm, edm, q1m, q2m, q3m, q4m, nkc,qm_pg.sbt (NVL (vqm, qm_pg.cv_okqm), 22, qm_pg.cn_ov)
       FROM halfhourold
      WHERE mid = an_switch AND prevmid <> an_switch   --Сечин чтоб не было сам на себя
                                                    AND nsource >= 10 AND nsource < 30 AND date_time > ad_switch AND date_time <= ad_escape);

   das_pg.calcpoint4bill (prevmid, ad_switch, ad_escape);
  END IF;

  UPDATE switches
     SET descape = ad_escape
   WHERE nswitch = an_switch AND descape = ad_switch;

  DELETE FROM billorg
        WHERE mid = an_switch AND date_time = ad_switch AND SOURCE = cv_source;

  ld_tmp := indic_pg.recalcdiff (an_switch, ad_switch);

  DELETE FROM switches
        WHERE ID = an_id;

  admin_pg.fiscal_p (gn_task_code, 3,
                     'Удалено переключение ОВ ' || util_pg.node_path_f (an_switch, 'points', 'mid', 'parent') || ' за ' || TO_CHAR (ad_switch, 'dd.mm.yyyy hh24:mi'));
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20001, 'switches_pg.del_p: Ошибка удаления переключения ОВ. ' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Процедура расчета
 PROCEDURE meterings (an_switch NUMBER, ad_switch DATE, time1 OUT VARCHAR2, er1 OUT VARCHAR2, ed1 OUT VARCHAR2, q11 OUT VARCHAR2, q21 OUT VARCHAR2, q31 OUT VARCHAR2,
 q41 OUT VARCHAR2, time2 OUT VARCHAR2, er2 OUT VARCHAR2, ed2 OUT VARCHAR2, q12 OUT VARCHAR2, q22 OUT VARCHAR2, q32 OUT VARCHAR2, q42 OUT VARCHAR2
 ) IS
  dtemp    DATE;
  lv_sep   VARCHAR2 (8) DEFAULT SUBSTR (11 / 10, 2, 1);
 BEGIN
  dtemp := util_pg.trunchh24_2 (ad_switch);
  er1 := TO_NUMBER (REPLACE (REPLACE (util_pg.get_meterage_vch2 (an_switch, dtemp, 1, 0), ',', lv_sep), '.', lv_sep));
  ed1 := TO_NUMBER (REPLACE (REPLACE (util_pg.get_meterage_vch2 (an_switch, dtemp, 2, 0), ',', lv_sep), '.', lv_sep));
  q11 := TO_NUMBER (REPLACE (REPLACE (util_pg.get_meterage_vch2 (an_switch, dtemp, 3, 0), ',', lv_sep), '.', lv_sep));
  q21 := TO_NUMBER (REPLACE (REPLACE (util_pg.get_meterage_vch2 (an_switch, dtemp, 4, 0), ',', lv_sep), '.', lv_sep));
  q31 := TO_NUMBER (REPLACE (REPLACE (util_pg.get_meterage_vch2 (an_switch, dtemp, 5, 0), ',', lv_sep), '.', lv_sep));
  q41 := TO_NUMBER (REPLACE (REPLACE (util_pg.get_meterage_vch2 (an_switch, dtemp, 6, 0), ',', lv_sep), '.', lv_sep));
  time1 := TO_CHAR (dtemp, 'hh24:mi');

  IF ad_switch <> dtemp THEN
   dtemp := dtemp + 1 / 48;
   time2 := TO_CHAR (dtemp, 'hh24:mi');
   er2 := TO_NUMBER (REPLACE (REPLACE (util_pg.get_meterage_vch2 (an_switch, dtemp, 1, 0), ',', lv_sep), '.', lv_sep));
   ed2 := TO_NUMBER (REPLACE (REPLACE (util_pg.get_meterage_vch2 (an_switch, dtemp, 2, 0), ',', lv_sep), '.', lv_sep));
   q12 := TO_NUMBER (REPLACE (REPLACE (util_pg.get_meterage_vch2 (an_switch, dtemp, 3, 0), ',', lv_sep), '.', lv_sep));
   q22 := TO_NUMBER (REPLACE (REPLACE (util_pg.get_meterage_vch2 (an_switch, dtemp, 4, 0), ',', lv_sep), '.', lv_sep));
   q32 := TO_NUMBER (REPLACE (REPLACE (util_pg.get_meterage_vch2 (an_switch, dtemp, 5, 0), ',', lv_sep), '.', lv_sep));
   q42 := TO_NUMBER (REPLACE (REPLACE (util_pg.get_meterage_vch2 (an_switch, dtemp, 6, 0), ',', lv_sep), '.', lv_sep));
  END IF;
 EXCEPTION
  WHEN OTHERS THEN
   NULL;
 END;

