-----------------------------------------------------------------------------------------------------------
  -- максимальное значенние по указанной точке за период времени для поиска переключения обводников
 FUNCTION getval (an_mid NUMBER, ad_stdate DATE, ad_endate DATE)
  RETURN NUMBER IS
  ln_vals   NUMBER;
 BEGIN
  SELECT GREATEST (NVL (ABS (MAX (er)), 0), NVL (ABS (MAX (ed)), 0))
    INTO ln_vals
    FROM halfhourold
   WHERE mid = an_mid AND date_time > ad_stdate AND date_time <= ad_endate AND (nsource < 30 OR nsource >= util_pg.cn_manualinput);

  RETURN ln_vals;
 END;

-----------------------------------------------------------------------------------------------------------
--Процедура проверки переключения обводников за сутки
--(проверка выполняется с перехлестом на 2 получасовки при выполнении по 2-м смежным суткам)
 PROCEDURE checkswitch_p (an_mid IN NUMBER,   -- родительская группа точек для перечня проверяемых обводников
                                           ad_stdate IN DATE,   -- дата начала проверки переключения
                                                             ad_endate IN DATE,   -- дата конца проверки переключения
                                                                               an_scount OUT NUMBER,   -- число проверенных обводников
                                                                                                    at_smids OUT common_pg.tt_number,   -- перечень найденных переключений с Mid обводника
 at_pmids OUT common_pg.tt_number,   -- перечень с MID соответствующих переключаемых точек
                                     --     (если NULL - не найденна точка или найденно больше 1-й !!! - требует вмешательства оператора)
 at_types OUT common_pg.tt_number   -- порядковый номер шага переключения при дискретном проходе указанного промежутка времени:
                                    --     >0 -вкл. обводника;
                                    --     <0 -выкл. обводника;
 ) IS
  ln_stepdate   NUMBER DEFAULT 1 / 48;   -- шаг прохода по промежутку времени при проверке (==30 мин)
  ln_dswitch    NUMBER DEFAULT 2 / 48;   -- время переключения обводника (== 1 час: < 30 мин и 30 мин > )
  ln_dmeter     NUMBER DEFAULT 1 / 48;   -- время измерения среднего расхода (== 30 мин)
  ln_kzero      NUMBER DEFAULT 0.05;   -- процент нуля при переключении линии с обводником от базовой нагрузки (== %5)
  ln_kdiffval   NUMBER DEFAULT 0.20;   -- процент допустимого отклонения нагрузки при переключении OV и L (== %20)

  -- перечень обводников в БД по родительской точке
  CURSOR c_switchs (ca_parent NUMBER) IS
   SELECT p.mid
     FROM feeders f,
          (SELECT     *
                 FROM points
           CONNECT BY PRIOR mid = PARENT
           START WITH mid = ca_parent) p
    WHERE f.nswitch <> 0 AND f.mid = p.mid AND f.nmainpoint IS NULL;

  -- перечень точек (необводников), которые могут быть переключенны на обводник cn_OV
  CURSOR c_getpoints (cn_ov NUMBER) IS
   SELECT f.*
     FROM feeders f, points p, points p1, feeders f1
    WHERE f.nswitch = 0 AND f.mid = p.mid AND p1.mid = cn_ov AND p.PARENT = p1.PARENT AND f.nmainpoint IS NULL AND f1.mid = cn_ov AND f1.POWER = f.POWER;

  -- начальный и конечный расход по точке при определения соответствия для обводника
  ln_pprev      NUMBER;
  ln_pnext      NUMBER;
  ln_sprev      NUMBER;
  ln_snext      NUMBER;
  ln_swmax      NUMBER;
  -- индекс текущего обводника в таблице результатов
  ln_curr       NUMBER;
  ln_ind        NUMBER;
  ld_curr       DATE;
 BEGIN
  an_scount := 0;
  ln_curr := 1;

  -- перебор обводников
  FOR cur_s IN c_switchs (an_mid) LOOP
   an_scount := an_scount + 1;
   -- проверка наличия расхода на обводнике
   ln_swmax := getval (cur_s.mid, ad_stdate - ln_stepdate, ad_endate);

   IF ln_swmax <> 0 THEN
    -- проверка изменения состояния обводника
    ln_ind := 1;

    WHILE ad_stdate + ln_ind * ln_stepdate < ad_endate LOOP
     ld_curr := ad_stdate + ln_ind * ln_stepdate;
     ln_sprev := getval (cur_s.mid, ld_curr - ln_dswitch, ld_curr - ln_dswitch / 2);
     ln_snext := getval (cur_s.mid, ld_curr - ln_dswitch / 2, ld_curr);

     IF (ln_sprev = 0 AND ln_snext <> 0) OR (ln_sprev <> 0 AND ln_snext = 0) THEN
      -- Корректировка значений
      IF (ln_sprev = 0 AND ln_snext <> 0) THEN
       ln_sprev := getval (cur_s.mid, ld_curr - ln_dswitch / 2 - ln_dmeter, ld_curr - ln_dswitch / 2);
       ln_snext := getval (cur_s.mid, ld_curr + ln_dswitch / 2, ld_curr + ln_dswitch / 2 + ln_dmeter);
      ELSIF (ln_sprev <> 0 AND ln_snext = 0) THEN
       ln_sprev := getval (cur_s.mid, ld_curr - ln_dswitch - ln_dmeter, ld_curr - ln_dswitch);
       ln_snext := getval (cur_s.mid, ld_curr, ld_curr + ln_dmeter);
      END IF;

      IF LEAST (ln_sprev, ln_snext) < ln_kzero * GREATEST (ln_sprev, ln_snext) THEN
       at_smids (ln_curr) := cur_s.mid;

       -- определение типа изменения состояния обводника
       IF (ln_sprev < ln_snext) THEN
        at_types (ln_curr) := ln_ind;   -- on
       ELSIF (ln_sprev > ln_snext) THEN
        at_types (ln_curr) := - (ln_ind - 1);   -- off
       END IF;

       -- цикл по точкам
       <<points_loop>>
       FOR cur_points IN c_getpoints (cur_s.mid) LOOP
        ld_curr := ad_stdate + ABS (at_types (ln_curr)) * ln_stepdate;
        ln_pprev := getval (cur_points.mid, ld_curr - ln_dswitch / 2 - ln_dmeter, ld_curr - ln_dswitch / 2);
        ln_pnext := getval (cur_points.mid, ld_curr + ln_dswitch / 2, ld_curr + ln_dswitch / 2 + ln_dmeter);

        IF (at_types (ln_curr) < 0 AND ln_pprev <= ln_pnext * ln_kzero AND GREATEST (ln_sprev, ln_pnext) * ln_kdiffval >= ABS (ln_sprev - ln_pnext))
           OR (at_types (ln_curr) > 0 AND ln_pnext <= ln_pprev * ln_kzero AND GREATEST (ln_snext, ln_pprev) * ln_kdiffval >= ABS (ln_snext - ln_pprev)) THEN
         IF at_pmids.EXISTS (ln_curr) THEN
          at_pmids.DELETE (ln_curr);
          EXIT;
         ELSE
          at_pmids (ln_curr) := cur_points.mid;
         END IF;
        END IF;
       END LOOP points_loop;

       ln_curr := ln_curr + 1;
      END IF;
     END IF;

     ln_ind := ln_ind + 1;
    END LOOP;
   END IF;
  END LOOP;
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20001, 'check_pg.checkswitch_p: Ошибка при проверке переключений обводников. ' || CHR (10) || SQLERRM (SQLCODE));
 END;

-----------------------------------------------------------------------------------------------------------
 PROCEDURE by_switchov (an_maket IN NUMBER, ddate_ IN DATE) IS
  check_id    NUMBER              DEFAULT 15;
  lt_smids    common_pg.tt_number;
  lt_pmids    common_pg.tt_number;
  lt_types    common_pg.tt_number;
  ln_scount   NUMBER;   -- число проверенных обводников
  ln_ncount   NUMBER;   -- число переключений обводников
  ln_pcount   NUMBER;   -- число произведенных переключений
  ld_date     DATE                DEFAULT TRUNC (ddate_);
  ln_switch   NUMBER;   -- ид строки, возвращаемая процедурой вставки SWITCHES_PG.ins_p
 BEGIN
  switches_pg.checkswitch_p (1000, TRUNC (ld_date), TRUNC (ld_date) + 1, ln_scount, lt_smids, lt_pmids, lt_types);
  ln_ncount := lt_smids.COUNT;
  ln_pcount := 0;

  IF ln_ncount <> 0 THEN
   FOR i IN lt_smids.FIRST .. lt_smids.LAST LOOP
    IF lt_pmids.EXISTS (i) AND lt_types.EXISTS (i) AND lt_types (i) <> 0 THEN
     ln_pcount := ln_pcount + 1;
    END IF;
   END LOOP;
  END IF;

  -- сообщение в журнал о факте работы процедуры
  admin_pg.journal_p (check_id, 0,
                      'Проверенно обводников: ' || TO_CHAR (ln_scount) || '. Найденно переключений: ' || TO_CHAR (ln_ncount) || ' . Переключенно из найденных: '
                      || TO_CHAR (ln_pcount) || '. Дата проверки ' || TO_CHAR (ddate_, 'dd.mm.yyyy'),
                      1);

  -- разбор результатов
  FOR i IN 1 .. lt_smids.COUNT LOOP
   BEGIN
    IF lt_pmids.EXISTS (i) AND lt_types.EXISTS (i) AND lt_types (i) <> 0 THEN
     IF lt_types (i) > 0 THEN   -- вкл. обводника
      switches_pg.ins_p (lt_smids (i), ld_date + (lt_types (i) - 1) / 48,   -- дата переключения
                         lt_pmids (i), util_pg.get_meterage (lt_smids (i), ld_date + lt_types (i) / 48, 1),
                         util_pg.get_meterage (lt_smids (i), ld_date + lt_types (i) / 48, 2), util_pg.get_meterage (lt_smids (i), ld_date + lt_types (i) / 48, 3),
                         util_pg.get_meterage (lt_smids (i), ld_date + lt_types (i) / 48, 4), util_pg.get_meterage (lt_smids (i), ld_date + lt_types (i) / 48, 5),
                         util_pg.get_meterage (lt_smids (i), ld_date + lt_types (i) / 48, 6), 1,   --common_pg.userid_f(), -- from administrator
                         ln_switch);
      admin_pg.journal_p (lt_smids (i), -1, 'Обводник переключен на точку: ' || REPLACE (util_pg.get_pointname (lt_pmids (i), 1), CHR (10), ' / '), 1);
     ELSE   -- выкл.
      switches_pg.ins_p (lt_smids (i), ld_date - lt_types (i) / 48,   -- дата переключения
                         lt_smids (i), util_pg.get_meterage (lt_smids (i), ld_date - lt_types (i) / 48, 1),
                         util_pg.get_meterage (lt_smids (i), ld_date - lt_types (i) / 48, 2), util_pg.get_meterage (lt_smids (i), ld_date - lt_types (i) / 48, 3),
                         util_pg.get_meterage (lt_smids (i), ld_date - lt_types (i) / 48, 4), util_pg.get_meterage (lt_smids (i), ld_date - lt_types (i) / 48, 5),
                         util_pg.get_meterage (lt_smids (i), ld_date - lt_types (i) / 48, 6), 1,   --common_pg.userid_f(), -- from administrator
                         ln_switch);
      admin_pg.journal_p (lt_smids (i), -1, 'Обводник отключился от точки: ' || REPLACE (util_pg.get_pointname (lt_pmids (i), 1), CHR (10), ' / '), 1);
     END IF;
    ELSE
     admin_pg.journal_p (lt_smids (i), -1, 'Не найдена точка для переключения обводника.', 1);
    END IF;

    COMMIT;
   EXCEPTION
    WHEN OTHERS THEN
     ROLLBACK;
   END;
  END LOOP;

  admin_pg.signal (6);
  COMMIT;
 END;
-----------------------------------------------------------------------------------------------------------
END;   -- Package Body SWITCHES_PG
