PACKAGE BODY test_pg IS
 ------------------------------------------------------------------------------------------------------------------------
 PROCEDURE p1(param1 IN OUT NUMBER, --Ид условия
                                   param2 IN OUT VARCHAR2) IS
 BEGIN
  param1 := param1 + 1;
  param2 := 'test' || param2;
 END;
 ------------------------------------------------------------------------------------------------------------------------
  --построение дерева задач на корневом уровне
 PROCEDURE p2(param1 NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  IF param1 IS NULL THEN
   OPEN acur_t FOR
    SELECT   mid, parent, name, short_name
        FROM points
       WHERE parent IS NULL AND ind = 3
    ORDER BY name ASC;
  ELSE
   OPEN acur_t FOR
    SELECT   mid, parent, name, short_name
        FROM points
       WHERE parent = param1 AND ind = 3
    ORDER BY name ASC;
  END IF;
 END;
 ------------------------------------------------------------------------------------------------------------------------
 PROCEDURE p3(param1 NUMBER, at_tab IN OUT common_pg.tt_number) IS
  BEGIN
  at_tab.DELETE;
  FOR i IN 1 .. 10 LOOP
   at_tab(i) := i;
  END LOOP;
  END;
------------------------------------------------------------------------------------------------------------------------
END;
