 PROCEDURE get_usdlist (an_mid NUMBER, acur_t OUT common_pg.tcur) IS
 -- используется в TMainForm::getUSDList
 -- добавление пунктов в меню pm - перечень точек, для которых точка с ид mid является УСД
 BEGIN
  OPEN acur_t FOR
   SELECT mid,
          TO_CHAR (er_position, '09') || ' | ' || TO_CHAR (ed_position, '09') || ' | ' || TO_CHAR (q1_position, '09') || ' | ' || TO_CHAR (q3_position, '09')
          || ' |   ' || util_pg.get_pointname (mid, 1) NAME
     FROM feeders
    WHERE nusd = an_mid;
 END;

--------------------------------------------------------------------------------------
 PROCEDURE find_node (an_mid NUMBER, acur_t OUT common_pg.tcur) IS
 -- используется в TMainForm::FindNode
 -- путь к точке начиная с коренного узла
 BEGIN
  OPEN acur_t FOR
   SELECT   mid
       FROM (SELECT     ROWNUM n, mid
                   FROM points
             CONNECT BY PRIOR PARENT = mid
             START WITH mid = an_mid)
   ORDER BY n DESC;
 END;

--------------------------------------------------------------------------------------
 PROCEDURE showchannellist (an_mid NUMBER, an_flag NUMBER, acur_t OUT common_pg.tcur) IS
 -- используется в TMainForm::ShowChannelList
 BEGIN
  IF (an_flag = 1) THEN
   OPEN acur_t FOR
    SELECT DISTINCT s.mid, s.PARENT, s.NAME vname,
                    DECODE (c.cid, NULL, DECODE (s.tag, 1, 23, 4), DECODE (c.nparent, NULL, DECODE (s.tag, 1, 11, 9), DECODE (s.tag, 1, 12, 10))) imind
               FROM (SELECT     p.mid, p.PARENT, p.NAME, p.tag
                           FROM points p
                     CONNECT BY PRIOR p.PARENT = p.mid
                     START WITH p.mid IN (SELECT c.cid
                                            FROM channels c
                                           WHERE c.com_id = an_mid)) s,
                    channels c
              WHERE s.PARENT IS NOT NULL AND c.cid(+) = s.mid
           ORDER BY 3;
  ELSIF (an_flag = 2) THEN
   OPEN acur_t FOR
    SELECT DISTINCT s.mid, s.PARENT, s.NAME vname,
                    DECODE (c.cid, NULL, DECODE (s.tag, 1, 23, 4), DECODE (c.nparent, NULL, DECODE (s.tag, 1, 11, 9), DECODE (s.tag, 1, 12, 10))) imind
               FROM (SELECT     *
                           FROM points p
                     CONNECT BY PRIOR p.PARENT = p.mid
                     START WITH p.mid IN (SELECT cp.cid
                                            FROM chanpoint cp
                                           WHERE cp.mid = an_mid)) s,
                    channels c
              WHERE PARENT IS NOT NULL AND c.cid(+) = s.mid
           ORDER BY 3;
  ELSIF (an_flag = 3) THEN
   OPEN acur_t FOR
    SELECT DISTINCT c.gid mid, c.PARENT, c.NAME vname, DECODE (c.mid, NULL, 2, DECODE (c.inverted, 'y', 1, 0)) imind
               FROM GROUPS c
         CONNECT BY PRIOR c.PARENT = c.gid
         START WITH c.gid IN (SELECT cp.gid
                                FROM GROUPS cp
                               WHERE cp.mid = an_mid)
           ORDER BY 3;
  ELSIF (an_flag = 4) THEN
   OPEN acur_t FOR
    SELECT ndeportation mid, ndeportation PARENT, vname, DECODE (nblock, 0, 9, 11) imind
      FROM deportation
     WHERE nmaket = an_mid;
  ELSIF (an_flag = 5) THEN
   OPEN acur_t FOR
    SELECT DISTINCT m.nmaket mid, m.nmaket PARENT, m.vname, 3 imind
               FROM makets m, maketgroups cp, maketpoints p
              WHERE m.nmaket = cp.nmaket AND p.ngroup = cp.ngroup AND p.mid = an_mid
    UNION ALL
    SELECT   p.ngroup, cp.nmaket, cp.vname, 2 imind
        FROM maketgroups cp, maketpoints p
       WHERE p.ngroup = cp.ngroup AND p.mid = an_mid
    UNION ALL
    SELECT   m.mid, m.ngroup, util_pg.get_pointname (m.mid, 1), 0 imind
        FROM maketpoints m
       WHERE m.mid = an_mid
    ORDER BY 3;
  ELSE
   RETURN;
  END IF;
 END;

--------------------------------------------------------------------------------------
 PROCEDURE createsubmenu_1 (av_mon VARCHAR2, an_id NUMBER, acur_t OUT common_pg.tcur) IS
 -- используется в TMainForm::createSubMenu_M
 BEGIN
  OPEN acur_t FOR
   SELECT   fid, nameform, 0 codetemplate
       FROM forms f
      WHERE monitor = av_mon AND PARENT IS NULL
            AND EXISTS (
                SELECT     *
                      FROM forms
                     WHERE codetemplate IN (1200, 1201, 1202, 1203, 1206) AND monitor = av_mon AND SUBSTR (enablecontrols, 7, 1) = '1'
                           AND (mid IS NULL OR mid IN (SELECT     mid
                                                             FROM points
                                                       CONNECT BY PRIOR PARENT = mid
                                                       START WITH mid = an_id))
                CONNECT BY PRIOR fid = PARENT
                START WITH fid = f.fid)
   ORDER BY 2;
 END;

--------------------------------------------------------------------------------------
 PROCEDURE createsubmenu_2 (av_mon VARCHAR2, an_id NUMBER, an_fid NUMBER, acur_t OUT common_pg.tcur) IS
 -- используется в TMainForm::createSubMenu_M
 BEGIN
  OPEN acur_t FOR
   SELECT   f.fid, f.nameform, f.codetemplate, f.enablecontrols, f.stepprofile, f.namealert, f.mid
       FROM forms f
      WHERE monitor = av_mon AND PARENT = an_fid
            AND EXISTS (
                SELECT     *
                      FROM forms
                     WHERE codetemplate IN (1200, 1201, 1202, 1203, 1206) AND monitor = av_mon AND SUBSTR (enablecontrols, 7, 1) = '1'
                           AND (mid IS NULL OR mid IN (SELECT     mid
                                                             FROM points
                                                       CONNECT BY PRIOR PARENT = mid
                                                       START WITH mid = an_id))
                CONNECT BY PRIOR fid = PARENT
                START WITH fid = f.fid)
   ORDER BY 2;
 END;

--------------------------------------------------------------------------------------
 PROCEDURE createsubmenu (an_fid NUMBER, an_mon NUMBER, an_gid NUMBER, acur_t OUT common_pg.tcur) IS
  -- используется в TMainForm::createSubMenu
  av_fid   VARCHAR2 (100);
 BEGIN
  IF (an_fid = 0) THEN
   av_fid := ' IS NULL ';
  ELSE
   av_fid := ' = ' || TO_CHAR (an_fid);
  END IF;

  OPEN acur_t FOR 'SELECT DISTINCT DECODE (f.codetemplate, NULL, 1, 0) CHILD, f.fid,
                f.codetemplate, f.nameform, f.commentform, f.enablecontrols,
                f.stepprofile, f.namealert, f.vprocname,'
                  || an_gid || ',f.mid
     FROM forms f
     WHERE PARENT ' || av_fid || ' AND monitor = ' || an_mon
                  || '
     CONNECT BY PRIOR PARENT = fid
     START WITH SUBSTR (enablecontrols, 7, 1) = ''1''
     AND ((f.CODETEMPLATE NOT IN (1200,1201,1202,1203,1206))
          OR (f.CODETEMPLATE IN (1200,1201,1202,1203,1206)
              AND (f.mid IS NULL OR f.mid IN (SELECT mid FROM points CONNECT BY PRIOR parent=mid START WITH mid='
                  || an_gid || '))
             )
         )
     ORDER BY 1, nameform DESC';
 END;

--------------------------------------------------------------------------------------
 PROCEDURE createsubmenu_g (an_fid NUMBER, an_mrole NUMBER, an_gid NUMBER, acur_t OUT common_pg.tcur) IS
  -- используется в TMainForm::createSubMenu_G
  av_fid   VARCHAR2 (100);
 BEGIN
  IF (an_fid = 0) THEN
   av_fid := ' IS NULL ';
  ELSE
   av_fid := ' = ' || TO_CHAR (an_fid);
  END IF;

  OPEN acur_t FOR 'SELECT DISTINCT DECODE (f.codetemplate, NULL, 1, 0) CHILD, f.fid, f.codetemplate, f.nameform, f.commentform,
                   f.enablecontrols, f.stepprofile, f.namealert, f.vprocname
    FROM forms f
    WHERE f.PARENT '
                  || av_fid || ' AND f.monitor = ' || an_mrole || '
          CONNECT BY PRIOR f.PARENT = f.fid
          START WITH f.monitor = ' || an_mrole
                  || '
                AND f.fid IN (SELECT fid FROM form_Group
                              WHERE gid IN (SELECT GID FROM GROUPS CONNECT BY PRIOR PARENT=GID START WITH GID='
                  || an_gid || '))
    ORDER BY 1, f.nameform DESC';
 END;

--------------------------------------------------------------------------------------
 PROCEDURE loaddate (an_mid NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT TO_CHAR (a.PROFILE, 'dd.mm.yyyy hh24:mi:ss') PROFILE, TO_CHAR (a.halfhour, 'dd.mm.yyyy hh24:mi:ss') halfhour,
          TO_CHAR (a.bill, 'dd.mm.yyyy hh24:mi:ss') bill, TO_CHAR (a.months, 'dd.mm.yyyy hh24:mi:ss') MONTH,
          DECODE (SIGN (c.cid),
                  1, a.clock,
                  DECODE (util_pg.getparamvalue_f (27),
                          0, a.clock,
                          DECODE (SIGN (ABS (a.clock) - util_pg.getparamvalue_f (27)), 1, util_pg.getparamvalue_f (27) * SIGN (a.clock), a.clock)
                         )
                 ) clock,
          TO_CHAR (a.state_date, 'dd.mm.yyyy hh24:mi:ss') state_date, a.state_cod,
          NVL (DECODE (SIGN (c.cid), 1, DECODE (a.trial, NULL, DECODE (c.was_dead, NULL, 'Опрос не производился'))), a.state_descr) state_descr,
          TO_CHAR (a.luck, 'dd.mm.yyyy hh24:mi:ss') luck, TO_CHAR (a.trial, 'dd.mm.yyyy hh24:mi:ss') trial
     FROM last_save a, channels c
    WHERE a.mid = an_mid AND a.mid = c.cid(+);
 END;
--------------------------------------------------------------------------------------
END;
/


