    SELECT 1 ID, 'Показання лічильника' title1, 'на 0 г. 1-го числа звітного місяця' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal,
           1 nlock, 100 nwidth, '' vmasks
      FROM DUAL
    UNION ALL
    SELECT 2 ID, 'Показання лічильника' title1, 'на 24 г. останнього числа звітного місяця' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl,
           cn_right dataal, 1 nlock, 100 nwidth, '' vmasks
      FROM DUAL
    UNION ALL
    SELECT 3 ID, 'Різниця показників лічильників' title1, '' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock, 100 nwidth,
           '' vmasks
      FROM DUAL
    UNION ALL
    SELECT 4 ID, 'Коефіцієнт лічильника' title1, '' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 1 nlock, 85 nwidth, '' vmasks
      FROM DUAL
    UNION ALL
    SELECT 5 ID, 'Кіл-ть електроенергії облікованої лічильником кВт/г.' title1, '' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal,
           1 nlock, 120 nwidth, '' vmasks
      FROM DUAL
    UNION ALL
    SELECT 6 ID, 'Примітка' title1, '' title2, cn_btnface titlecl, cn_left titleal, cn_white datacl, cn_right dataal, 0 nlock, 120 nwidth, '' vmasks
      FROM DUAL;

   IF an_ispoint = 1 THEN
    OPEN row_t FOR
     SELECT TO_CHAR (ROWNUM) title1, t.ID, t.title2, t.title3, t.title4, t.datacl, t.dataal, t.nlock, t.vmasks
       FROM (SELECT   p.mid ID, DECODE (f.vcode, '', '', f.vcode || '.') || pa.NAME || ' / ' || p.NAME title2, m.mtrsn title3, d.t title4, cn_white datacl,
                      cn_right dataal, 0 nlock, '' vmasks
                 FROM feeders f,
                      meters m,
                      points p,
                      points pa,
                      (SELECT ROWNUM r, DECODE (ROWNUM, 1, 'прийом', 'віддача') t
                         FROM dict
                        WHERE ROWNUM <= 2) d
                WHERE f.mid IN (SELECT     mid
                                      FROM points
                                CONNECT BY PRIOR mid = PARENT
                                START WITH mid = an_id) AND f.mid = m.mid(+) AND m.entype(+) = 7 AND f.mid = p.mid(+) AND p.PARENT = pa.mid(+)
             ORDER BY pa.NAME, pa.mid, p.NAME, p.mid, d.t) t   -- сортировка по d.t значит - сначала отдача, потом прием
     UNION ALL
     SELECT '' title1, -1 ID, '' title2, 'Разом:' title3, 'віддача' title4, cn_yellow datacl, cn_right dataal, 0 nlock, '' vmasks
       FROM DUAL
      WHERE ln_locksum = 0
     UNION ALL
     SELECT '' title1, -1 ID, '' title2, '' title3, 'прийом' title4, cn_yellow datacl, cn_right dataal, 0 nlock, '' vmasks
       FROM DUAL
      WHERE ln_locksum = 0
     UNION ALL
     SELECT '' title1, -1 ID, '' title2, '' title3, 'сальдо' title4, cn_yellow datacl, cn_right dataal, 0 nlock, '' vmasks
       FROM DUAL
      WHERE ln_locksum = 0;
   ELSE
    OPEN row_t FOR
     SELECT TO_CHAR(ROWNUM) title1, t.ID, t.title2, t.title3, t.title4, t.datacl, t.dataal, t.nlock, t.vmasks
       FROM (SELECT   p.mid ID, NVL(util_pg.get_param(g.VPARAM,2),DECODE (f.vcode,'','',f.vcode ||'.') || pa.NAME ||'/'|| p.NAME) title2, m.mtrsn title3, d.t title4, cn_white datacl,
                      cn_right dataal, 0 nlock, '' vmasks
                 FROM GROUPS g,
                      feeders f,
                      meters m,
                      points p,
                      points pa,
                      (SELECT ROWNUM r, DECODE (ROWNUM, 1, 'прийом', 'віддача') t
                         FROM dict
                        WHERE ROWNUM <= 2) d
                WHERE g.gid IN (
                       SELECT     gid
                             FROM GROUPS
                       CONNECT BY PRIOR gid = PARENT
                                  AND (TO_CHAR (ad_from, 'yyyymm') <= NVL (ntillperiod, 299912) AND TO_CHAR (ad_till, 'yyyymm') >= NVL (nfromperiod, 160501))
                       START WITH gid = an_id
                                  AND (TO_CHAR (ad_from, 'yyyymm') <= NVL (ntillperiod, 299912) AND TO_CHAR (ad_till, 'yyyymm') >= NVL (nfromperiod, 160501)))
                      AND g.mid = f.mid AND f.mid = m.mid(+) AND m.entype(+) = 7 AND f.mid = p.mid(+) AND p.PARENT = pa.mid(+)
             ORDER BY util_pg.allnumber_f(util_pg.get_param(g.VPARAM,1,';')), pa.NAME, pa.mid, p.NAME, p.mid, d.t) t   -- сортировка по d.t значит - сначала отдача, потом прием
     UNION ALL
     SELECT '' title1, -1 ID, '' title2, 'Разом:' title3, 'віддача' title4, cn_yellow datacl, cn_right dataal, 0 nlock, '' vmasks
       FROM DUAL
      WHERE ln_locksum = 0
     UNION ALL
     SELECT '' title1, -1 ID, '' title2, '' title3, 'прийом' title4, cn_yellow datacl, cn_right dataal, 0 nlock, '' vmasks
