-- Возвращает множитель 1 или 0 при учете признака частичного вхождения
 FUNCTION get_koef_npartly (an_npartly NUMBER, an_i NUMBER, an_inverted VARCHAR2)
  RETURN NUMBER IS
 BEGIN
  IF an_npartly IS NULL THEN
   RETURN 1;
  ELSIF an_npartly = 1 THEN
   IF an_inverted = 'y' THEN
    IF an_i = 1 THEN
     RETURN NULL;
    ELSIF an_i = 2 THEN
     RETURN 1;
    ELSIF an_i = 3 THEN
     RETURN NULL;
    ELSIF an_i = 5 THEN
     RETURN 1;
    END IF;
   ELSIF an_inverted = 'n' THEN
    IF an_i = 1 THEN
     RETURN 1;
    ELSIF an_i = 2 THEN
     RETURN NULL;
    ELSIF an_i = 3 THEN
     RETURN 1;
    ELSIF an_i = 5 THEN
     RETURN NULL;
    END IF;
   END IF;
  ELSIF an_npartly = 2 THEN
   IF an_inverted = 'y' THEN
    IF an_i = 1 THEN
     RETURN 1;
    ELSIF an_i = 2 THEN
     RETURN NULL;
    ELSIF an_i = 3 THEN
     RETURN 1;
    ELSIF an_i = 5 THEN
     RETURN NULL;
    END IF;
   ELSIF an_inverted = 'n' THEN
    IF an_i = 1 THEN
     RETURN NULL;
    ELSIF an_i = 2 THEN
     RETURN 1;
    ELSIF an_i = 3 THEN
     RETURN NULL;
    ELSIF an_i = 5 THEN
     RETURN 1;
    END IF;
   END IF;
  END IF;
 END;

