--Отсечение даты до декады
 FUNCTION truncdec (d DATE)
  RETURN DATE IS
 BEGIN
  IF TO_NUMBER (TO_CHAR (d, 'DD')) <= 10 THEN
   RETURN TRUNC (d, 'MM');
  ELSIF TO_NUMBER (TO_CHAR (d, 'DD')) <= 20 THEN
   RETURN TRUNC (d, 'MM') + 10;
  END IF;

  RETURN TRUNC (d, 'MM') + 20;
 END;

------------------------------------------------------------------------------------------------------------------------
--Вычисление декады
 FUNCTION getdec (d DATE)
  RETURN NUMBER IS
 BEGIN
  IF TO_NUMBER (TO_CHAR (d, 'DD')) <= 10 THEN
   RETURN 1;
  ELSIF TO_NUMBER (TO_CHAR (d, 'DD')) <= 20 THEN
   RETURN 2;
  END IF;

  RETURN 3;
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION add_dec (d DATE, i INTEGER)
  RETURN DATE IS
  ln_sec      NUMBER;
  ln_daydec   NUMBER;
  ln_dec      NUMBER;
  ret         DATE;
 BEGIN
  ln_sec := TO_NUMBER (TO_CHAR (d, 'SSSSS')) / 86400;
  ln_daydec := TRUNC (d) - truncdec (d) + 1;
  ln_dec := getdec (d);
  ret := ADD_MONTHS (TRUNC (d, 'MM'), TRUNC (i / 3));

  IF MOD (i, 3) = -2 THEN
   IF ln_dec = 1 THEN
    ret := ADD_MONTHS (ret, -1);
    ln_dec := 2;
   ELSIF ln_dec = 2 THEN
    ret := ADD_MONTHS (ret, -1);
    ln_dec := 3;
   ELSE
    ln_dec := 1;
   END IF;
  ELSIF MOD (i, 3) = -1 THEN
   IF ln_dec = 1 THEN
    ret := ADD_MONTHS (ret, -1);
    ln_dec := 3;
   ELSIF ln_dec = 2 THEN
    ln_dec := 1;
   ELSE
    ln_dec := 2;
   END IF;
  ELSIF MOD (i, 3) = 1 THEN
   IF ln_dec = 1 THEN
    ln_dec := 2;
   ELSIF ln_dec = 2 THEN
    ln_dec := 3;
   ELSE
    ret := ADD_MONTHS (ret, 1);
    ln_dec := 1;
   END IF;
  ELSIF MOD (i, 3) = 2 THEN
   IF ln_dec = 1 THEN
    ln_dec := 3;
   ELSIF ln_dec = 2 THEN
    ret := ADD_MONTHS (ret, 1);
    ln_dec := 1;
   ELSE
    ret := ADD_MONTHS (ret, 1);
    ln_dec := 2;
   END IF;
  END IF;

  IF ln_dec = 1 OR ln_dec = 2 THEN
   ret := ret + LEAST (10 * (ln_dec - 1) + ln_daydec, 10 * ln_dec) - 1;
  ELSE
   ret := ret + LEAST (20 + ln_daydec, TO_NUMBER (TO_CHAR (LAST_DAY (ret), 'DD'))) - 1;
  END IF;

  RETURN ret + ln_sec;
 END;

