--Отсечение до получасовок
 FUNCTION trunchh24_2 (d DATE)
  RETURN DATE IS
 BEGIN
  RETURN trunc_d (d, 1 / 48);
 END;

------------------------------------------------------------------------------------------------------------------------
--Отсечение до an_dif - как делить 1/2 - это пол дня, 1/24 - по часам , 1/48 - по получасам,1/480 - 3 минутки
 FUNCTION trunc_d (d DATE, an_dif NUMBER)
  RETURN DATE IS
  cn_rn   CONSTANT NUMBER := 22;
 BEGIN
  RETURN TRUNC (d) + TRUNC (TO_CHAR (d, 'SSSSS') / ROUND (86400 * an_dif, cn_rn)) * an_dif;
 END;

------------------------------------------------------------------------------------------------------------------------
 --Возвращает порядковый номер данных при группировке (для макетов 25 час и, т, д)
 FUNCTION get_num_dt (d DATE, an_source NUMBER, an_dif NUMBER, an_in_end NUMBER, an_shifttz NUMBER)
  --an_dif - как делить 1/2 - это пол дня, 1/24 - по часам , 1/48 - по получасам
