     ln_ret := TRUNC (TO_CHAR (d - TO_CHAR (d, 'HH24') / 24, 'SSSSS') / ROUND (86400 * an_dif, cn_rn)) + 1 + 1 / an_dif;
    END IF;
   ELSE   --посредине
    IF (d > TRUNC (d) + (switch_f + 1) / 24) OR (d > TRUNC (d) + switch_f / 24 AND an_source NOT IN (19, 29, 39, 49, 59)) THEN
     --ЕСЛИ БОЛЬШЕ (switch_f+1) или > switch_f и не сдвиг добавляем 1
     ln_ret := TRUNC (TO_CHAR (d, 'SSSSS') / ROUND (86400 * an_dif, cn_rn)) + 1 + 1 / 24 / an_dif;
    END IF;
   END IF;
  ELSIF ln_isdsw = 1 THEN   --весна
   IF d > TRUNC (d) + switch_f / 24 THEN   --ЕСЛИ БОЛЬШЕ 3 НОЧИ, ТО УБИРАЕМ ЧАС
    ln_ret := TRUNC (TO_CHAR (d - 1 / 24, 'SSSSS') / ROUND (86400 * an_dif, cn_rn)) + 1;
