------------------------------------------------------------------------------------------------------------------------
 -- Возвращает утренний или вечерний лимит мощности по группе в зависимости от ad_date
 -- an_gid - ИД группы
 -- ad_date - дата и время лимита. Если передаваемое время не утро и не вечер то возвращается NULL
 FUNCTION get_grouplimit (an_gid NUMBER, ad_date DATE)
  RETURN NUMBER IS
  ln_ret    NUMBER;
  ld_date   DATE;
 BEGIN
  --Ищем переопределенные часы максимальной нагрузки
  FOR lc IN (SELECT     gid
                   FROM GROUPS g
                  WHERE EXISTS (
                         SELECT *
                           FROM grouplimit
                          WHERE gid = g.gid AND dstart < ad_date AND morning_start IS NOT NULL AND morning_end IS NOT NULL AND evening_start IS NOT NULL
                                AND evening_end IS NOT NULL)
             CONNECT BY PRIOR g.PARENT = g.gid
             START WITH g.gid = an_gid) LOOP
   SELECT MAX (dstart)
     INTO ld_date
     FROM grouplimit
    WHERE gid = lc.gid AND dstart < ad_date;

   SELECT SUM (n)
     INTO ln_ret
     FROM (SELECT 1 n
             FROM grouplimit mh
            WHERE gid = lc.gid AND dstart = ld_date AND TO_CHAR (morning_start, 'sssss') <= TO_CHAR (ad_date, 'sssss')
                  AND TO_CHAR (morning_end, 'sssss') >= TO_CHAR (ad_date, 'sssss')
           UNION ALL
           SELECT 2 n
             FROM grouplimit mh
            WHERE gid = lc.gid AND dstart = ld_date AND TO_CHAR (evening_start, 'sssss') <= TO_CHAR (ad_date, 'sssss')
                  AND TO_CHAR (evening_end, 'sssss') >= TO_CHAR (ad_date, 'sssss'));

   EXIT;
  END LOOP;

  IF ld_date IS NULL THEN   --нет переопределенных часы для группы (самой или родительской)
   SELECT MAX (date_time)
     INTO ld_date
     FROM maxhours
    WHERE date_time < ad_date;

   SELECT SUM (n)
     INTO ln_ret
     FROM (SELECT 1 n
             FROM maxhours mh
            WHERE date_time = ld_date AND TO_CHAR (morning_start, 'sssss') <= TO_CHAR (ad_date, 'sssss')
                  AND TO_CHAR (morning_end, 'sssss') >= TO_CHAR (ad_date, 'sssss')
           UNION ALL
           SELECT 2 n
             FROM maxhours mh
            WHERE date_time = ld_date AND TO_CHAR (evening_start, 'sssss') <= TO_CHAR (ad_date, 'sssss')
                  AND TO_CHAR (evening_end, 'sssss') >= TO_CHAR (ad_date, 'sssss'));
  END IF;

  SELECT DECODE (ln_ret, 1, nlimitcapm, 2, nlimitcape)
    INTO ln_ret
    FROM grouplimit gl
   WHERE dstart = (SELECT MAX (dstart)
                     FROM grouplimit
                    WHERE dstart < ad_date AND gid = an_gid) AND gid = an_gid;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
  --Возвращает 1, если есть данные по точке
 FUNCTION is_point_have_data (an_mid NUMBER)
  RETURN NUMBER IS
  ln_ret   NUMBER;
 BEGIN
  SELECT COUNT (*)
    INTO ln_ret
    FROM DUAL
   WHERE EXISTS (SELECT *
                   FROM months e,
                        (SELECT     mid
                               FROM points
                         CONNECT BY PRIOR mid = PARENT
                         START WITH mid = an_mid) m
                  WHERE e.mid = m.mid) OR EXISTS (SELECT *
                                                    FROM bill e,
                                                         (SELECT     mid
                                                                FROM points
                                                          CONNECT BY PRIOR mid = PARENT
                                                          START WITH mid = an_mid) m
                                                   WHERE e.mid = m.mid) OR EXISTS (SELECT *
                                                                                     FROM halfhour e,
                                                                                          (SELECT     mid
                                                                                                 FROM points
                                                                                           CONNECT BY PRIOR mid = PARENT
                                                                                           START WITH mid = an_mid) m
                                                                                    WHERE e.mid = m.mid) OR EXISTS (SELECT *
                                                                                                                      FROM PROFILE e,
                                                                                                                           (SELECT     mid
                                                                                                                                  FROM points
                                                                                                                            CONNECT BY PRIOR mid = PARENT
                                                                                                                            START WITH mid = an_mid) m
                                                                                                                     WHERE e.mid = m.mid);

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION indicoverturn (an_val NUMBER, an_len NUMBER)
  RETURN NUMBER IS
  ln_res   NUMBER;
  k        NUMBER DEFAULT 1;
  ln_len   NUMBER;
 BEGIN
  IF ABS (an_len) >= 100 THEN
   ln_len := LENGTH (TRUNC (ABS (an_len)));
  ELSE
   ln_len := TRUNC (NVL (ABS (an_len), 0));
  END IF;

  ln_res := an_val;

  IF ABS (an_val) < 0.00001 THEN
   RETURN 0;
  END IF;

  IF NVL (an_val, 0) >= 0 THEN
   RETURN ln_res;
  ELSE
   IF ln_len <= 0 OR ln_len < LENGTH (TRUNC (ABS (an_val))) THEN
    ln_len := LENGTH (TRUNC (ABS (an_val)));
   END IF;

   WHILE ln_len > 0 LOOP
    k := k * 10;
    ln_len := ln_len - 1;
   END LOOP;

   ln_res := an_val + k;
  END IF;

  RETURN ln_res;
 END;

------------------------------------------------------------------------------------------------------------------------
 --Возвращает расход на место (10010 превращает в 10 пр четырехразрядах)
 FUNCTION overindic_to_indic (an_val NUMBER, an_len NUMBER)
  RETURN NUMBER IS
  ln_len   NUMBER DEFAULT NVL (TRUNC (an_len), LENGTH (TRUNC (an_val)));
 BEGIN
  RETURN MOD (an_val, POWER (10, ln_len));
 END;

