 FUNCTION chdr_f (a NUMBER)
  RETURN NUMBER IS
 BEGIN
  IF a = 1 THEN
   RETURN 2;
  ELSIF a = 2 THEN
   RETURN 1;
  ELSIF a = 3 THEN
   RETURN 5;
  ELSIF a = 4 THEN
   RETURN 6;
  ELSIF a = 5 THEN
   RETURN 3;
  ELSIF a = 6 THEN
   RETURN 4;
  END IF;

  RETURN a;
 END;

