------------------------------------------------------------------------------------------------------------------------
--Переворот прием отдача
 FUNCTION sld (an_mid NUMBER, an_1 NUMBER, an_2 NUMBER)
  RETURN NUMBER IS
 BEGIN
  IF needchdr_f (an_mid) = 1 THEN
   IF an_1 IS NULL THEN
    RETURN an_2;
   ELSE
    IF an_2 IS NULL THEN
     RETURN -an_1;
    ELSE
     RETURN - (an_1 - an_2);
    END IF;
   END IF;
  ELSE
   IF an_1 IS NULL THEN
    RETURN -an_2;
   ELSE
    IF an_2 IS NULL THEN
     RETURN an_1;
    ELSE
     RETURN (an_1 - an_2);
    END IF;
   END IF;
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
--Суммирует с NULL
 FUNCTION sumn (an_1 NUMBER, an_2 NUMBER)
  RETURN NUMBER IS
 BEGIN
  IF an_1 IS NULL THEN
   RETURN an_2;
  ELSIF an_2 IS NULL THEN
   RETURN an_1;
  ELSE
   RETURN (an_1 + an_2);
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
 --длиное название точки
 FUNCTION get_pointname (an_mid NUMBER, an_detal NUMBER, an_show NUMBER)
  --0 только имя, 1 - имя и П.С., 2 - все
 RETURN VARCHAR2 IS
  lv_ret     VARCHAR2 (2000);
  lv_p       VARCHAR2 (2000);
  lv_pa      VARCHAR2 (2000);
  ln_smart   NUMBER;

  CURSOR lcur_met (lc_smart NUMBER) IS
   SELECT DECODE (lc_smart, 1, '№ ' || mtrsn, DECODE (m.entype, 1, 'А пр.', 2, 'А от.', 3, 'Р пр.', 'Р ген.') || ' №' || mtrsn || ';') met
     FROM meters m
    WHERE m.mid = an_mid AND m.date_time = (SELECT MAX (date_time)
                                              FROM meters
                                             WHERE mid = an_mid AND date_time < SYSDATE AND DECODE (smart, '*', 1, 0) = lc_smart AND entype = m.entype)
          AND DECODE (m.smart, '*', 1, 0) = lc_smart;
 BEGIN
  SELECT MAX (p.NAME), MAX (pa.NAME), MAX (DECODE (f.smart, '*', 1, 0))
    INTO lv_p, lv_pa, ln_smart
    FROM points p, points pa, feeders f
   WHERE p.mid = an_mid AND p.PARENT = pa.mid(+) AND p.mid = f.mid(+);

  IF lv_p IS NOT NULL THEN
   IF an_show = 1 THEN
    lv_ret := 'ТУ ' || lv_p;
   ELSE
    lv_ret := lv_p;
   END IF;
  END IF;

  IF an_detal > 0 AND lv_pa IS NOT NULL THEN
   IF an_show = 1 THEN
    lv_ret := 'ПС ' || lv_pa || CHR (10) || lv_ret;
   ELSE
    lv_ret := lv_pa || CHR (10) || lv_ret;
   END IF;
  END IF;

  IF an_detal > 1 AND lv_pa IS NOT NULL THEN
   lv_ret := lv_ret || CHR (10) || 'Cчетчики: ';

   FOR lc IN lcur_met (ln_smart) LOOP
    lv_ret := lv_ret || lc.met || '   ';
   END LOOP;
  END IF;

  RETURN SUBSTR (NVL (lv_ret, ' '), 1, 255);
 END;

-------------------------------------------------------------------------------------------------
 --длиное название группы
 FUNCTION get_groupname (an_gid NUMBER, an_detal NUMBER DEFAULT 1)
  --степень детализации
 RETURN VARCHAR2 IS
  lv_ret   VARCHAR2 (2000);

  CURSOR lcur_sel IS
   SELECT     DECODE (LEVEL, 1, NAME, NAME || ' \ ') NAME
         FROM GROUPS
        WHERE LEVEL <= DECODE (SIGN (an_detal), 0, 1, NULL, 1, -1, 1, TRUNC (an_detal))
   CONNECT BY PRIOR PARENT = gid
   START WITH gid = an_gid;
 BEGIN
  FOR lc IN lcur_sel LOOP
   lv_ret := lc.NAME || lv_ret;
  END LOOP;

  RETURN SUBSTR (NVL (lv_ret, ' '), 1, 255);
 END;

