 PROCEDURE f_preparesortbyl_n IS
 BEGIN
  gt_sortobject.DELETE;
 END;

-------------------------------------------------------------------------------------------------
 FUNCTION f_recursort (an_id NUMBER, an_sort NUMBER)
  RETURN NUMBER IS
  ln_sort   NUMBER DEFAULT an_sort;

  CURSOR lcur_sel1 IS
   SELECT   task_id
       FROM tasks
      WHERE PARENT IS NULL
   ORDER BY NAME;

  CURSOR lcur_sel2 IS
   SELECT   task_id
       FROM tasks
      WHERE PARENT = an_id
   ORDER BY NAME;
 BEGIN
  IF an_id IS NULL THEN
   FOR lc IN lcur_sel1 LOOP
    ln_sort := ln_sort + 1;
    gt_sortobject (lc.task_id) := ln_sort;
    ln_sort := f_recursort (lc.task_id, ln_sort);
   END LOOP;
  ELSE
   FOR lc IN lcur_sel2 LOOP
    ln_sort := ln_sort + 1;
    gt_sortobject (lc.task_id) := ln_sort;
    ln_sort := f_recursort (lc.task_id, ln_sort);
   END LOOP;
  END IF;

  RETURN ln_sort;
 END;

-------------------------------------------------------------------------------------------------
 FUNCTION f_sorttaskbyl_n (an_needread NUMBER, an_id NUMBER, an_start NUMBER)
  RETURN NUMBER IS
  ln_sort   NUMBER DEFAULT 1;
 BEGIN
  IF NVL (an_needread, 1) <= 1 THEN
   gt_sortobject (an_id) := 1;
   ln_sort := f_recursort (an_start, ln_sort);
  END IF;

  RETURN gt_sortobject (an_id);
 EXCEPTION
  WHEN OTHERS THEN
   RETURN 10000;
 END;

-------------------------------------------------------------------------------------------------
-- Возвращает показания счетчика (рассчет показаний производится на основании
-- месячных или показаний занесенных в таблицу MAN_IMP_HHOUR показаний,
-- путем прибавление пролучасовых расходов)
-- параметр an_etype может принимать значения:
-- 1 - erm
-- 2 - edm
-- 3 - q1m
-- 4 - q2m
-- 5 - q3m
-- 6 - q4m
-- параметр an_meterage_table может принимать значения:
-- 1 - man_inp_hhour
-- 2 - months
-- 3 - billorg
 FUNCTION get_meterage (an_mid NUMBER, ad_date DATE, an_etype NUMBER, an_meterage_table NUMBER)
  RETURN NUMBER IS
  ld_lastdate_met   DATE   := NULL;
  ln_m_erm          NUMBER;
  ln_m_edm          NUMBER;
  ln_m_q1m          NUMBER;
  ln_m_q2m          NUMBER;
  ln_m_q3m          NUMBER;
  ln_m_q4m          NUMBER;
  ln_erm            NUMBER;
  ln_edm            NUMBER;
  ln_q1m            NUMBER;
  ln_q2m            NUMBER;
  ln_q3m            NUMBER;
  ln_q4m            NUMBER;
  ln_ret            NUMBER;
 BEGIN
  IF an_meterage_table = 1 THEN
   SELECT MAX (date_time)
     INTO ld_lastdate_met
     FROM man_inp_hhour
    WHERE mid = an_mid AND date_time <= ad_date;

   SELECT erm, edm, q1m, q2m, q3m, q4m
     INTO ln_m_erm, ln_m_edm, ln_m_q1m, ln_m_q2m, ln_m_q3m, ln_m_q4m
     FROM man_inp_hhour
    WHERE mid = an_mid AND date_time = ld_lastdate_met;
  ELSIF an_meterage_table = 2 THEN
   SELECT MAX (date_time)
     INTO ld_lastdate_met
     FROM months
    WHERE mid = an_mid AND date_time <= ad_date;

   SELECT erm, edm, q1m, q2m, q3m, q4m
     INTO ln_m_erm, ln_m_edm, ln_m_q1m, ln_m_q2m, ln_m_q3m, ln_m_q4m
     FROM months
    WHERE mid = an_mid AND date_time = ld_lastdate_met;
  ELSIF an_meterage_table = 3 THEN
   SELECT MAX (date_time)
     INTO ld_lastdate_met
     FROM billorg
    WHERE mid = an_mid AND date_time <= ad_date;

   SELECT erm, edm, q1m, q2m, q3m, q4m
     INTO ln_m_erm, ln_m_edm, ln_m_q1m, ln_m_q2m, ln_m_q3m, ln_m_q4m
     FROM billorg
    WHERE mid = an_mid AND date_time = ld_lastdate_met;
  END IF;

  SELECT NVL (SUM (er / DECODE (kc, 0, 1, kc)), 0), NVL (SUM (ed / DECODE (kc, 0, 1, kc)), 0), NVL (SUM (q1 / DECODE (kc, 0, 1, kc)), 0),
         NVL (SUM (q2 / DECODE (kc, 0, 1, kc)), 0), NVL (SUM (q3 / DECODE (kc, 0, 1, kc)), 0), NVL (SUM (q4 / DECODE (kc, 0, 1, kc)), 0)
    INTO ln_erm, ln_edm, ln_q1m,
         ln_q2m, ln_q3m, ln_q4m
    FROM halfhour h, feeders f
   WHERE f.mid = an_mid AND f.mid = h.mid AND date_time > ld_lastdate_met AND date_time <= ad_date;

  IF an_etype = 1 THEN
   ln_ret := ln_m_erm + ln_erm;
  ELSIF an_etype = 2 THEN
   ln_ret := ln_m_edm + ln_edm;
  ELSIF an_etype = 3 THEN
   ln_ret := ln_m_q1m + ln_q1m;
  ELSIF an_etype = 4 THEN
   ln_ret := ln_m_q2m + ln_q2m;
  ELSIF an_etype = 5 THEN
   ln_ret := ln_m_q3m + ln_q3m;
  ELSIF an_etype = 6 THEN
   ln_ret := ln_m_q4m + ln_q4m;
  END IF;

  RETURN ln_ret;
 /* EXCEPTION
   WHEN OTHERS THEN
    RETURN -1;*/
 END;

------------------------------------------------------------------------------------------------------------------------
-- Возвращает показания счетчика (рассчет показаний производится на основании
-- месячных или показаний занесенных в таблицу MAN_IMP_HHOUR показаний,
-- путем прибавление пролучасовых расходов)
-- параметр an_etype может принимать значения:
-- 1 - erm
-- 2 - edm
-- 3 - q1m
-- 4 - q2m
-- 5 - q3m
-- 6 - q4m

 -- 7 - aerm
 -- 8 - aedm
 -- 9 - aq1m
 -- 10 - aq2m
 -- 11 - aq3m
 -- 12 - aq4m

 -- 13 - berm
 -- 14 - bedm
 -- 15 - bq1m
 -- 16 - bq2m
 -- 17 - bq3m
 -- 18 - bq4m

 -- 19 - cerm
 -- 20 - cedm
 -- 21 - cq1m
 -- 22 - cq2m
 -- 23 - cq3m
 -- 24 - cq4m
 FUNCTION get_meterage (an_mid NUMBER, ad_date DATE, an_etype NUMBER)
  RETURN NUMBER IS
 BEGIN
  RETURN get_meterage (an_mid, ad_date, an_etype, 0, NULL);
 END;

 ------------------------------------------------------------------------------------------------------------------------
 -- an_mettype принимает значения
--    0 - На момент снятия счетчика или в штатной ситуации( NSOURCE = 7 или NSOURCE > 8)
--    Иначе - На момент установки счетчика или в штатной ситуации ( NSOURCE = 8 или NSOURCE > 8)
 -- параметр an_table может принимать значения:
 -- 1 - man_inp_hhour
 -- 2 - monthsorg
 -- 3 - billorg
 -- 4 - halfhour
 -- 0,NULL - по всем таблицам
 -- Иначе return NULL;
 FUNCTION get_meterage (an_mid NUMBER, ad_date DATE, an_etype NUMBER, an_mettype NUMBER, an_table NUMBER, an_withoutcalc NUMBER)   -- Умная
  RETURN NUMBER IS
  CURSOR lcur_sel IS
   SELECT   0 t, MIN (date_time - ad_date) dif, DECODE (get_customer_id, 2, -1, 0)
       FROM halfhour
      WHERE NOT (NVL (get_customer_id, 0) = 16 AND an_etype IN (3, 4, 5, 6) AND mid IN (3154, 3156)) AND mid = an_mid AND date_time = ad_date
            AND DECODE (an_etype, 2, edm, 3, q1m, 4, q2m, 5, q3m, 6, q4m, erm) IS NOT NULL
     HAVING MIN (date_time - ad_date) IS NOT NULL AND DECODE (NVL (an_table, 0), 0, 4, an_table) = 4
   UNION ALL
   SELECT   1 t, MIN (date_time - ad_date) dif, DECODE (get_customer_id, 2, -1, 0)
       FROM billorg
      WHERE mid = an_mid AND date_time >= ad_date
            AND DECODE (an_etype,
                        2, edm,
                        3, q1m,
                        4, q2m,
                        5, q3m,
                        6, q4m,
                        7, aerm,
                        8, aedm,
                        9, aq1m,
                        10, aq2m,
                        11, aq3m,
                        12, aq4m,
                        13, berm,
                        14, bedm,
                        15, bq1m,
                        16, bq2m,
                        17, bq3m,
                        18, bq4m,
                        19, cerm,
                        20, cedm,
                        21, cq1m,
                        22, cq2m,
                        23, cq3m,
                        24, cq4m,
                        erm
                       ) IS NOT NULL
     HAVING MIN (date_time - ad_date) IS NOT NULL AND DECODE (NVL (an_table, 0), 0, 3, an_table) = 3
   UNION ALL
   SELECT   2 t, MIN (ad_date - date_time) dif, DECODE (get_customer_id, 2, -1, 0)
       FROM billorg
      WHERE mid = an_mid AND date_time < ad_date
            AND DECODE (an_etype,
                        2, edm,
                        3, q1m,
                        4, q2m,
                        5, q3m,
                        6, q4m,
                        7, aerm,
                        8, aedm,
                        9, aq1m,
                        10, aq2m,
                        11, aq3m,
                        12, aq4m,
                        13, berm,
                        14, bedm,
                        15, bq1m,
                        16, bq2m,
                        17, bq3m,
                        18, bq4m,
                        19, cerm,
                        20, cedm,
                        21, cq1m,
                        22, cq2m,
                        23, cq3m,
                        24, cq4m,
                        erm
                       ) IS NOT NULL
     HAVING MIN (ad_date - date_time) IS NOT NULL AND DECODE (NVL (an_table, 0), 0, 3, an_table) = 3
   UNION ALL
   SELECT   3 t, MIN (date_time - ad_date) dif, DECODE (get_customer_id, 2, -1, 0)
       FROM monthsorg
      WHERE mid = an_mid AND date_time >= ad_date
            AND DECODE (an_etype,
                        2, edm,
                        3, q1m,
                        4, q2m,
                        5, q3m,
                        6, q4m,
                        7, aerm,
                        8, aedm,
                        9, aq1m,
                        10, aq2m,
                        11, aq3m,
                        12, aq4m,
                        13, berm,
                        14, bedm,
                        15, bq1m,
                        16, bq2m,
                        17, bq3m,
                        18, bq4m,
                        19, cerm,
                        20, cedm,
                        21, cq1m,
                        22, cq2m,
                        23, cq3m,
                        24, cq4m,
                        erm
                       ) IS NOT NULL
     HAVING MIN (date_time - ad_date) IS NOT NULL AND DECODE (NVL (an_table, 0), 0, 2, an_table) = 2
   UNION ALL
   SELECT   4 t, MIN (ad_date - date_time) dif, DECODE (get_customer_id, 2, -1, 0)
       FROM monthsorg
      WHERE mid = an_mid AND date_time < ad_date
            AND DECODE (an_etype,
                        2, edm,
                        3, q1m,
                        4, q2m,
                        5, q3m,
                        6, q4m,
                        7, aerm,
                        8, aedm,
                        9, aq1m,
                        10, aq2m,
                        11, aq3m,
                        12, aq4m,
                        13, berm,
                        14, bedm,
                        15, bq1m,
                        16, bq2m,
                        17, bq3m,
                        18, bq4m,
                        19, cerm,
                        20, cedm,
                        21, cq1m,
                        22, cq2m,
                        23, cq3m,
                        24, cq4m,
                        erm
                       ) IS NOT NULL
     HAVING MIN (ad_date - date_time) IS NOT NULL AND DECODE (NVL (an_table, 0), 0, 2, an_table) = 2
   UNION ALL
   SELECT   5 t, MIN (date_time - ad_date) dif, 0
       FROM man_inp_hhour
      WHERE mid = an_mid AND date_time >= ad_date
            AND DECODE (an_etype,
                        2, edm,
                        3, q1m,
                        4, q2m,
                        5, q3m,
                        6, q4m,
                        7, aerm,
                        8, aedm,
                        9, aq1m,
                        10, aq2m,
                        11, aq3m,
                        12, aq4m,
                        13, berm,
                        14, bedm,
                        15, bq1m,
                        16, bq2m,
                        17, bq3m,
                        18, bq4m,
                        19, cerm,
                        20, cedm,
                        21, cq1m,
                        22, cq2m,
                        23, cq3m,
                        24, cq4m,
                        erm
                       ) IS NOT NULL
     HAVING MIN (date_time - ad_date) IS NOT NULL AND DECODE (NVL (an_table, 0), 0, 1, an_table) = 1
   UNION ALL
   SELECT   6 t, MIN (ad_date - date_time) dif, 0
       FROM man_inp_hhour
      WHERE mid = an_mid AND date_time < ad_date
            AND DECODE (an_etype,
                        2, edm,
                        3, q1m,
                        4, q2m,
                        5, q3m,
                        6, q4m,
                        7, aerm,
                        8, aedm,
                        9, aq1m,
                        10, aq2m,
                        11, aq3m,
                        12, aq4m,
                        13, berm,
                        14, bedm,
                        15, bq1m,
                        16, bq2m,
                        17, bq3m,
                        18, bq4m,
                        19, cerm,
                        20, cedm,
                        21, cq1m,
                        22, cq2m,
                        23, cq3m,
                        24, cq4m,
                        erm
                       ) IS NOT NULL
     HAVING MIN (ad_date - date_time) IS NOT NULL AND DECODE (NVL (an_table, 0), 0, 1, an_table) = 1
   ORDER BY 3, 2, 1;

  ln_val      NUMBER;
  ln_ret      NUMBER;
  ln_retdat   DATE;
  ln_difdat   NUMBER;   --date_time-ad_date
  lv_tab      VARCHAR2 (32);
  lv_what     VARCHAR2 (32);
  lb_add      BOOLEAN         DEFAULT TRUE;
  lv_sql      VARCHAR2 (4000);
  lv_agr      VARCHAR2 (32);
  ln_entype   NUMBER;
  ln_digits   NUMBER;
 BEGIN
  FOR lc IN lcur_sel LOOP
   IF MOD (lc.t, 2) = 1 THEN
    ln_difdat := lc.dif;
   ELSE
    ln_difdat := -lc.dif;
   END IF;

   IF lc.t = 0 THEN
    lv_tab := 'halfhour';
   ELSIF lc.t <= 2 THEN
    lv_tab := 'billorg';
   ELSIF lc.t <= 4 THEN
    lv_tab := 'monthsorg';
   ELSE
    lv_tab := 'MAN_INP_HHOUR';
    lb_add := FALSE;
   END IF;

   IF an_etype = 2 THEN
    lv_what := 'edm';
    ln_entype := 2;
   ELSIF an_etype = 3 THEN
    lv_what := 'q1m';
    ln_entype := 3;
   ELSIF an_etype = 4 THEN
    lv_what := 'q2m';
    ln_entype := 3;
   ELSIF an_etype = 5 THEN
    lv_what := 'q3m';
    ln_entype := 5;
   ELSIF an_etype = 6 THEN
    lv_what := 'q4m';
    ln_entype := 5;
   ELSIF lc.t = 0 THEN
    lv_what := 'erm';
    ln_entype := 1;
   --зона A
   ELSIF an_etype = 7 THEN
    lv_what := 'aerm';
    ln_entype := 1;
   ELSIF an_etype = 8 THEN
    lv_what := 'aedm';
    ln_entype := 2;
   ELSIF an_etype = 9 THEN
    lv_what := 'aq1m';
    ln_entype := 3;
   ELSIF an_etype = 10 THEN
    lv_what := 'aq2m';
    ln_entype := 3;
   ELSIF an_etype = 11 THEN
    lv_what := 'aq3m';
    ln_entype := 5;
   ELSIF an_etype = 12 THEN
    lv_what := 'aq4m';
    ln_entype := 5;
   --зона B
   ELSIF an_etype = 13 THEN
    lv_what := 'berm';
    ln_entype := 1;
   ELSIF an_etype = 14 THEN
    lv_what := 'bedm';
    ln_entype := 2;
   ELSIF an_etype = 15 THEN
    lv_what := 'bq1m';
    ln_entype := 3;
   ELSIF an_etype = 16 THEN
    lv_what := 'bq2m';
    ln_entype := 3;
   ELSIF an_etype = 17 THEN
    lv_what := 'bq3m';
    ln_entype := 5;
   ELSIF an_etype = 18 THEN
    lv_what := 'bq4m';
    ln_entype := 5;
   --зона C
   ELSIF an_etype = 19 THEN
    lv_what := 'cerm';
    ln_entype := 1;
   ELSIF an_etype = 20 THEN
    lv_what := 'cedm';
    ln_entype := 2;
   ELSIF an_etype = 21 THEN
    lv_what := 'cq1m';
    ln_entype := 3;
   ELSIF an_etype = 22 THEN
    lv_what := 'cq2m';
    ln_entype := 3;
   ELSIF an_etype = 23 THEN
    lv_what := 'cq3m';
    ln_entype := 5;
   ELSIF an_etype = 24 THEN
    lv_what := 'cq4m';
    ln_entype := 5;
   ELSE
    lv_what := 'erm';
    ln_entype := 1;
   END IF;

   lv_sql := 'select date_time,' || lv_what || ' from ' || lv_tab || ' where mid=:1 and date_time-:2=:3 and ' || lv_what || ' is not null';

   IF lb_add THEN
    IF an_mettype = 0 THEN
     lv_agr := 'min';
    ELSE
     lv_agr := 'max';
    END IF;

    lv_sql := lv_sql || ' and nsource=(select ' || lv_agr || '(nsource) from ' || lv_tab || ' where mid=:4 and date_time-:5=:6 and ' || lv_what || ' is not null)';

    EXECUTE IMMEDIATE lv_sql
                 INTO ln_retdat, ln_ret
                USING an_mid, ad_date, ln_difdat, an_mid, ad_date, ln_difdat;
   ELSE
    EXECUTE IMMEDIATE lv_sql
                 INTO ln_retdat, ln_ret
                USING an_mid, ad_date, ln_difdat;
   END IF;

   IF ln_retdat = ad_date THEN
    EXIT;
   ELSIF an_withoutcalc = 1 THEN   --без дорасчета
    IF TRUNC (ln_retdat) = TRUNC (ad_date) THEN
     NULL;
    ELSE
     ln_ret := NULL;
    END IF;

    EXIT;
   END IF;

   SELECT NVL (SUM (DECODE (an_etype, 2, ed, 3, q1, 4, q2, 5, q3, 6, q4, er) / NVL (DECODE (nkc, 0, 1, nkc), 1)), 0)
     INTO ln_val
     FROM halfhour
    WHERE mid = an_mid AND date_time > LEAST (ad_date, ln_retdat) AND date_time <= GREATEST (ad_date, ln_retdat) AND (NVL (nsource, 0) < 30 OR NVL (nsource, 0) > 49);

   SELECT NVL (MAX (digits), cn_def_digits)
     INTO ln_digits
     FROM meters
    WHERE mid = an_mid AND entype = (SELECT MAX (DECODE (smart, '*', 7, ln_entype))
                                       FROM feeders
                                      WHERE mid = an_mid);

   ln_ret :=
    ROUND (ABS (MOD (ln_ret - SIGN (ln_retdat - ad_date) * ln_val, POWER (10, LENGTH (GREATEST (ABS (TRUNC (ln_digits)), ABS (TRUNC (ln_ret))))))),
           LENGTH (1 + ABS (ln_digits - TRUNC (ln_digits))));
   EXIT;
  END LOOP;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Возвращает показания счетчика по формату разрядности счетчика
  -- если разрядность не введена, функция не работает
  -- an_mid - Ид точки
  -- ad_date - дата показаниц
  -- an_mettype принимает значения
  --    0 - На момент снятия счетчика или в штатной ситуации( NSOURCE = 7 или NSOURCE > 8)
  --    Иначе - На момент установки счетчика или в штатной ситуации ( NSOURCE = 8 или NSOURCE > 8)
 FUNCTION get_meterage_vch2 (an_mid NUMBER, ad_date DATE, an_etype NUMBER, an_mettype NUMBER, av_sep VARCHAR2, an_withoutcalc NUMBER)
  RETURN VARCHAR2 IS
  lndigits   NUMBER;
  lnentype   NUMBER;
  ln_ret     NUMBER;
  lv_sep     VARCHAR2 (32) DEFAULT NVL (av_sep, '.');
 BEGIN
  IF an_etype = 1 OR an_etype = 7 OR an_etype = 13 OR an_etype = 19 THEN
   lnentype := 1;
  END IF;

  IF an_etype = 2 OR an_etype = 8 OR an_etype = 14 OR an_etype = 20 THEN
   lnentype := 2;
  END IF;

  IF an_etype = 3 OR an_etype = 9 OR an_etype = 15 OR an_etype = 21 OR an_etype = 4 OR an_etype = 10 OR an_etype = 16 OR an_etype = 22 THEN
   lnentype := 3;
  END IF;

  IF an_etype = 5 OR an_etype = 11 OR an_etype = 17 OR an_etype = 23 OR an_etype = 6 OR an_etype = 12 OR an_etype = 18 OR an_etype = 24 THEN
   lnentype := 5;
  END IF;

  SELECT NVL (MAX (digits), cn_def_digits)
    INTO lndigits
    FROM meters
   WHERE mid = an_mid AND entype IN (lnentype, 7);

  ln_ret := get_meterage (an_mid, ad_date, an_etype, an_mettype, NULL, an_withoutcalc);
  lndigits := LPAD ('9', GREATEST (LENGTH (ABS (TRUNC (lndigits))), LENGTH (ABS (TRUNC (ln_ret)))), '9') + (lndigits - TRUNC (lndigits));   --Берем больше разрядность до запятой если значение больше
  RETURN REPLACE (TO_CHAR (TRUNC (ln_ret, LENGTH (lndigits) - INSTR (REPLACE (TO_CHAR (lndigits), ',', '.'), '.')),
                           REPLACE (REPLACE (TO_CHAR (lndigits), '9', '0'), ',', '.')),
                  '.', lv_sep);
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION get_meterage_difference (an_mid NUMBER, ad_stdate DATE, ad_findate DATE, an_etype NUMBER, an_mettype NUMBER, an_withoutcalc NUMBER)   -- Умная
  RETURN NUMBER IS
  lnentype       NUMBER;
  lnret          NUMBER;
  ln_mettype1    NUMBER       DEFAULT 1;
  ln_mettype2    NUMBER       DEFAULT 1;
  lv_sep         VARCHAR2 (8) DEFAULT SUBSTR (11 / 10, 2, 1);
  ln_calcpoint   NUMBER;
 BEGIN
  SELECT COUNT (*)
    INTO ln_calcpoint
    FROM feeders
   WHERE mid = an_mid AND ncalcpointtype > 0;

  IF ln_calcpoint > 0 THEN   --считаем по расходу
   SELECT SUM (DECODE (an_etype, 1, er, 2, ed, 3, q1, 4, q2, 5, q3, 6, q4, er))
     INTO lnret
     FROM billorg
    WHERE mid = an_mid AND date_time > ad_stdate AND date_time <= ad_findate;

   IF lnret IS NULL THEN
    SELECT SUM (DECODE (an_etype, 1, er, 2, ed, 3, q1, 4, q2, 5, q3, 6, q4, er))
      INTO lnret
      FROM halfhour
     WHERE mid = an_mid AND date_time > ad_stdate AND date_time <= ad_findate;
   END IF;

   RETURN lnret;
  END IF;

  IF an_etype = 1 OR an_etype = 7 OR an_etype = 13 OR an_etype = 19 THEN
   lnentype := 1;
  END IF;

  IF an_etype = 2 OR an_etype = 8 OR an_etype = 14 OR an_etype = 20 THEN
   lnentype := 2;
  END IF;

  IF an_etype = 3 OR an_etype = 9 OR an_etype = 15 OR an_etype = 21 OR an_etype = 4 OR an_etype = 10 OR an_etype = 16 OR an_etype = 22 THEN
   lnentype := 3;
  END IF;

  IF an_etype = 5 OR an_etype = 11 OR an_etype = 17 OR an_etype = 23 OR an_etype = 6 OR an_etype = 12 OR an_etype = 18 OR an_etype = 24 THEN
   lnentype := 5;
  END IF;

  IF an_mettype = 0 THEN
   ln_mettype1 := 1;
   ln_mettype2 := 0;
  END IF;

  lnret :=
   indicoverturn (REPLACE (REPLACE (get_meterage_vch2 (an_mid, ad_findate, an_etype, ln_mettype2, '', an_withoutcalc), ',', lv_sep), '.', lv_sep)
                  - REPLACE (REPLACE (get_meterage_vch2 (an_mid, ad_stdate, an_etype, ln_mettype1, '', an_withoutcalc), ',', lv_sep), '.', lv_sep),
                  NULL);
  RETURN lnret;
 END;

