 FUNCTION get_param (av_param VARCHAR2, i NUMBER, av_separator VARCHAR2)
  RETURN VARCHAR2 IS
  lv_param   VARCHAR2 (2000) DEFAULT av_param;
  j          NUMBER          DEFAULT i;
  k          NUMBER;
 BEGIN
  LOOP
   k := INSTR (lv_param, av_separator);

   IF j = 1 THEN
    IF k = 0 THEN
     RETURN REPLACE (lv_param, av_separator);
    ELSE
     RETURN SUBSTR (lv_param, 1, k - 1);
    END IF;
   ELSE
    IF k = 0 THEN
     RETURN '';
    ELSE
     lv_param := SUBSTR (lv_param, k + LENGTH (av_separator));
    END IF;
   END IF;

   j := j - 1;

   IF NVL (j, 0) <= 0 OR lv_param IS NULL OR av_separator IS NULL THEN
    RETURN '';
   END IF;
  END LOOP;
 END;

------------------------------------------------------------------------------------------------------------------------
--Возвращает в строке av_param, разделенной av_separator, i-ю подстроку с конца.
-- added by KAG 22.09.2008
 FUNCTION get_param_rev (av_param VARCHAR2, i NUMBER, av_separator VARCHAR2)
  RETURN VARCHAR2 IS
  lv_param   VARCHAR2 (2000) DEFAULT av_param;
  j          NUMBER          DEFAULT i;
  k          NUMBER;
 BEGIN
  LOOP
   k := INSTR (lv_param, av_separator, -1);

   IF j = 1 THEN
    IF k = 0 THEN
     RETURN REPLACE (lv_param, av_separator);
    ELSE
     RETURN SUBSTR (lv_param, k + LENGTH (av_separator));
    END IF;
   ELSE
    IF k = 0 THEN
     RETURN '';
    ELSE
     lv_param := SUBSTR (lv_param, 1, k - 1);
    END IF;
   END IF;

   j := j - 1;

   IF NVL (j, 0) <= 0 OR lv_param IS NULL OR av_separator IS NULL THEN
    RETURN '';
   END IF;
  END LOOP;
 END;

-------------------------------------------------------------------------------------------
 --Возвращает номер вхождения в строке av_str, разделенной av_separator  - подстроку av_substr.
 FUNCTION get_pos_str (av_str VARCHAR2, av_substr VARCHAR2, av_separator VARCHAR2)
  RETURN NUMBER IS
 BEGIN
  FOR i IN 1 .. NVL (LENGTH (av_str), 0) LOOP
   IF av_substr = get_param (av_str, i, av_separator) THEN
    RETURN i;
   END IF;
  END LOOP;

  RETURN 0;
 END;

