  -- Add by KSS for form Акт границ учёта перетоков (01.10.2003)
  -- Расход по точке через показания счётчиков
 FUNCTION get_value_f (an_mid NUMBER,   -- MID точки
                                     ad_from DATE,   -- исходная дата для вычисления расхода
                                                  ad_till DATE,   -- конечная дата для вычисления расхода
                                                               an_type NUMBER
 )
  -- тип энергии (значения описаны в описании процедуры UTIL_PG.get_meterage)
 RETURN NUMBER IS
  ln_kc   NUMBER;   -- коэффициент
  ln_ds   NUMBER;   -- digits
 BEGIN
  SELECT kc
    INTO ln_kc
    FROM feeders
   WHERE mid = an_mid;

  SELECT NVL (MAX (digits), cn_def_digits)
    INTO ln_ds
    FROM meters
   WHERE mid = an_mid AND ((NVL (smart, ' ') = '*' AND entype = 7) OR (NVL (smart, ' ') <> '*' AND entype = an_type));

  RETURN ln_kc * util_pg.indicoverturn (util_pg.get_meterage (an_mid, ad_till, an_type) - util_pg.get_meterage (an_mid, ad_from, an_type), LENGTH (TRUNC (ln_ds)));
 END;

------------------------------------------------------------------------------------------------------------------------
    -- Add by KSS for Акт границ учёта перетоков (15.10.2003)
    -- возвращает номер при проходе по дереву
 FUNCTION get_level_f (an_rownum NUMBER, an_level NUMBER)
  RETURN VARCHAR2 IS
  lv_result   VARCHAR2 (255);
 BEGIN
  -- проверка на инициализацию массива
  IF an_rownum = 1 THEN
   gt_num.DELETE;
  END IF;

  -- инициализация нового уровня
  IF NOT gt_num.EXISTS (an_level) THEN
   gt_num (an_level) := -1;
  END IF;

  gt_num (an_level) := gt_num (an_level) + 1;

  -- очистка хвоста
  FOR i IN an_level + 1 .. gt_num.LAST LOOP
   gt_num.DELETE (i);
  END LOOP;

  -- формирование результата
  lv_result := '';

  FOR i IN gt_num.FIRST .. gt_num.LAST LOOP
   IF i = gt_num.FIRST THEN
    lv_result := lv_result || TRIM (' ' FROM TO_CHAR (gt_num (i), '0999'));
   ELSE
    lv_result := lv_result || '.' || TRIM (' ' FROM TO_CHAR (gt_num (i), '0999'));
   END IF;
  END LOOP;

  RETURN lv_result;
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION get_loss_info (ln_connectionparam NUMBER, ln_mid NUMBER)
  --Возвращает информацию о потерях
 RETURN VARCHAR2 IS
  lv_ret   VARCHAR2 (16);
 BEGIN
  /*
  Функция возвращает CHAR(5) где на соответствующих местах стоят
  1:  О - данная точка является носителем потерь (в connectionparam)
      Р - данная точка не является носителем потерь (в sharedconnectionparam) и входит в долю к О
  2:  Д - Есть долевые потери
  3:  П - Есть паралельные соединения записаны в nparallelconnection
  4:  З - Есть зависимые потери
  5:  Т - Трехобмоточный трансформатор
  */
  SELECT lv_ret || NVL (MAX ('О'), 'Р')
    INTO lv_ret
    FROM connectionparam
   WHERE nconnectionparam = ln_connectionparam AND NVL (mid, 0) = ln_mid;

  SELECT lv_ret || NVL (MAX ('Д'), '_')
    INTO lv_ret
    FROM sharedconnectionparam
   WHERE nconnectionparam = ln_connectionparam AND NVL (mid, 0) <> ln_mid;

  SELECT lv_ret || NVL (MAX ('П'), '_')
    INTO lv_ret
    FROM connectionparam c, connectionparam c1
   WHERE c.nconnectionparam = ln_connectionparam AND c.nparallelconnection = c1.nparallelconnection(+) AND c1.nconnectionparam <> ln_connectionparam;

  SELECT lv_ret || NVL (MAX ('З'), '_')
    INTO lv_ret
    FROM relatedparam
   WHERE nconnectionparam = ln_connectionparam OR nfirstparam = ln_connectionparam;

  SELECT lv_ret || NVL (MAX ('Т'), '_')
    INTO lv_ret
    FROM connectionparam
   WHERE nconnectionparam = ln_connectionparam AND nsh IS NOT NULL;

  RETURN lv_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
--Возвращает информацию о количестве получасовок вычитаных опросчиком в заданый период
-- начиная с ad_start исключительно, заканчивая ad_end включительно
 FUNCTION get_halfhourold_count_f (an_mid NUMBER, ad_start DATE, ad_end DATE, an_nsource NUMBER)
  RETURN NUMBER IS
  ln_count      NUMBER DEFAULT 0;
  i             NUMBER;
  ld_currdate   DATE   DEFAULT ad_start;
  ln_half       NUMBER DEFAULT 1 / 48;
  ln_sek        NUMBER DEFAULT 1 / 24 / 60;

  CURSOR cr_hr IS
   SELECT   mid, date_time
       FROM halfhourold
      WHERE mid = an_mid AND date_time > ad_start AND date_time <= ad_end AND nsource = an_nsource
   ORDER BY date_time;
 BEGIN
  FOR lc_cr_hr IN cr_hr LOOP
   IF lc_cr_hr.date_time > ld_currdate AND lc_cr_hr.date_time <= (ld_currdate + ln_half) THEN
    ln_count := ln_count + 1;
    ld_currdate := (ld_currdate + ln_half);
   ELSE
    IF lc_cr_hr.date_time > (ld_currdate + ln_half) THEN
     ln_count := ln_count + 1;
    END IF;

    ld_currdate := TRUNC (lc_cr_hr.date_time) + FLOOR (TO_CHAR ((lc_cr_hr.date_time - ln_sek) + ln_half, 'sssss') / 1800) / 48;
   END IF;
  END LOOP;

  RETURN ln_count;
 END;

 ------------------------------------------------------------------------------------------------------------------------
 --Возвращает информацию о количестве cуточных вычитаных опросчиком в заданый период
-- начиная с ad_start исключительно, заканчивая ad_end включительно
 FUNCTION get_billorg_count_f (an_mid NUMBER, ad_start DATE, ad_end DATE, an_nsource NUMBER)
  RETURN NUMBER IS
  ln_count      NUMBER DEFAULT 0;
  i             NUMBER;
  ld_currdate   DATE   DEFAULT ad_start;

  CURSOR cr_hr IS
   SELECT   mid, date_time
       FROM billorg
      WHERE mid = an_mid AND date_time > ad_start AND date_time <= ad_end AND nsource = an_nsource
   ORDER BY date_time;
 BEGIN
  ld_currdate := TRUNC (ld_currdate + 1);

  FOR lc_cr_hr IN cr_hr LOOP
   IF lc_cr_hr.date_time >= ld_currdate AND lc_cr_hr.date_time < ld_currdate + 1 THEN
    ln_count := ln_count + 1;
    ld_currdate := ld_currdate + 1;
   ELSE
    IF lc_cr_hr.date_time > (ld_currdate + 1) THEN
     ln_count := ln_count + 1;
    END IF;

    ld_currdate := TRUNC (lc_cr_hr.date_time + 1);
   END IF;
  END LOOP;

  RETURN ln_count;
 END;

