 FUNCTION getovsum (an_switch NUMBER, ad_date DATE, an_type NUMBER)
  RETURN NUMBER IS
  ln_ret   NUMBER;
 BEGIN
  SELECT SUM (DECODE (an_type, 2, ed, 3, q1, 4, q2, 5, q3, 6, q4, er))
    INTO ln_ret
    FROM halfhour
   WHERE nswitch = an_switch AND date_time = ad_date;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
 --Вычисление расход по показаниям
 -- params - дополнительные параметры (по умолчанию NULL) - битовая маска
 --- 1-я позиция='1' - + расход по обводнику
 --- 2-я позиция='1' - с учётом замен
 --- 3-я позиция='1' - с учетом потерь
 FUNCTION get_energy (an_mid NUMBER, ad_start DATE, ad_end DATE, an_entype NUMBER, av_params VARCHAR2)
  RETURN NUMBER IS
  CURSOR lc_getswitchmeterage (lc_mid NUMBER, lc_entype NUMBER, lc_start DATE, lc_end DATE) IS
   SELECT dend, digits
     FROM metershistory
    WHERE mid = lc_mid AND (entype = lc_entype OR entype = 7) AND dend < lc_end AND dend > lc_start;

  ln_start       NUMBER;
  ln_end         NUMBER;
  ln_kc          NUMBER;
  ln_digits      NUMBER;
  ln_result      NUMBER;
  ld_stswitch    DATE;
  ld_enswitch    DATE;
  ln_switchmid   NUMBER;
  ld_curr        DATE;
  ln_addenergy   NUMBER;
 BEGIN
  SELECT MAX (kc)
    INTO ln_kc
    FROM feeders
   WHERE mid = an_mid;

  SELECT MAX (digits)
    INTO ln_digits
    FROM meters m
   WHERE m.mid = an_mid AND (m.entype = an_entype OR m.entype = 7);

  IF SUBSTR (av_params, 2, 1) = '1' THEN   -- с учётом замен
   ld_curr := ad_start;
   ln_result := 0;

   FOR lc_curr IN lc_getswitchmeterage (an_mid, an_entype, ad_start, ad_end) LOOP
    ln_start := get_meterage (an_mid, ld_curr, an_entype, 1, 0);
    ln_end := get_meterage (an_mid, lc_curr.dend, an_entype, 0, 0);

    -- выбрать недоучёт для замены счётчика
    SELECT MAX (DECODE (an_entype, 1, er, 2, ed, 3, q1, 4, q2, 5, q3, 6, q4))
      INTO ln_addenergy
      FROM billorg
     WHERE mid = an_mid AND date_time = lc_curr.dend AND nsource = 8;

    ---
    ln_result := ln_result + indicoverturn (ln_end - ln_start, LENGTH (TRUNC (lc_curr.digits))) * ln_kc + NVL (ln_addenergy, 0);
    ld_curr := lc_curr.dend;
   END LOOP;

   ln_start := get_meterage (an_mid, ld_curr, an_entype, 1, 0);
   ln_end := get_meterage (an_mid, ad_end, an_entype, 0, 0);
   ln_result := ln_result + indicoverturn (ln_end - ln_start, LENGTH (TRUNC (ln_digits))) * ln_kc;
  ELSE
   ln_start := get_meterage (an_mid, ad_start, an_entype, 0, 0);
   ln_end := get_meterage (an_mid, ad_end, an_entype, 0, 0);
   ln_result := indicoverturn (ln_end - ln_start, LENGTH (TRUNC (ln_digits))) * ln_kc;
  END IF;

  IF SUBSTR (av_params, 1, 1) = '1' THEN   -- + расход по обводнику
   SELECT MAX (nswitch), MAX (dswitch), MAX (descape)
     INTO ln_switchmid, ld_stswitch, ld_enswitch
     FROM switches
    WHERE mid = an_mid AND dswitch < ad_end AND descape > ad_start;

   IF ln_switchmid IS NOT NULL THEN
    ln_start := get_meterage (ln_switchmid, ld_stswitch, an_entype, 0, 0);
    ln_end := get_meterage (ln_switchmid, ld_enswitch, an_entype, 0, 0);

    SELECT MAX (kc)
      INTO ln_kc
      FROM feeders
     WHERE mid = ln_switchmid;

    SELECT MAX (digits)
      INTO ln_digits
      FROM meters m
     WHERE m.mid = ln_switchmid AND (m.entype = an_entype OR m.entype = 7);

    ln_result := ln_result + indicoverturn (ln_end - ln_start, LENGTH (TRUNC (ln_digits))) * ln_kc;
   END IF;
  END IF;

  IF SUBSTR (av_params, 3, 1) = '1' THEN   -- + потери
   ln_result := ln_result + pointcalc_pg.f_defwaste (ad_start, ad_end, an_mid, NULL, 1, an_entype);
   NULL;
  END IF;

  RETURN ln_result;
 END;

------------------------------------------------------------------------------------------------------------------------
 --Возвращает принадлежность дате зоны
 FUNCTION is_zone (ad_date DATE,   -- дата
                                an_zone NUMBER)   -- 0- пик 1-день 2-ночь
  RETURN NUMBER IS
  ln_tmp   NUMBER;
 BEGIN
  SELECT MIN (rid)
    INTO ln_tmp
    FROM rate_list
   WHERE switch_date <= ad_date AND switch_date = (SELECT MAX (switch_date)
                                                     FROM rate_list
                                                    WHERE switch_date <= ad_date);

  SELECT COUNT (*)
    INTO ln_tmp
    FROM DUAL
   WHERE EXISTS (
          SELECT *
            FROM rates
           WHERE rid = ln_tmp AND rate = an_zone AND TO_CHAR (ad_date, 'sssss') >= TO_CHAR (TIME, 'sssss')
                 AND TO_CHAR (ad_date, 'sssss') <= DECODE (TO_CHAR (endtime, 'sssss'), 864399, 86400, TO_CHAR (endtime, 'sssss')));

  RETURN ln_tmp;
 END;

------------------------------------------------------------------------------------------------------------------------
--Возвращает родителей точки или группы
 FUNCTION node_path_f (an_id NUMBER, av_table_name VARCHAR2, av_idname VARCHAR2, av_parentname VARCHAR2, av_columnname VARCHAR2 DEFAULT 'name')
  RETURN VARCHAR2 IS
  lv_sql     VARCHAR2 (500)  DEFAULT '';
  lv_row     VARCHAR2 (500)  DEFAULT '';
  ln_level   NUMBER;
  lv_ret     VARCHAR2 (2000) DEFAULT '';
  cr_sel     common_pg.tcur;
 BEGIN
  lv_sql :=
   'select level, ' || av_columnname || ' from ' || av_table_name || ' connect by prior ' || av_parentname || ' = ' || av_idname || ' start with ' || av_idname
   || ' = ' || an_id || ' order by level desc';

  OPEN cr_sel FOR lv_sql;

  LOOP
   FETCH cr_sel
    INTO ln_level, lv_row;

   EXIT WHEN cr_sel%NOTFOUND;
   lv_ret := lv_ret || lv_row || '\';
  END LOOP;

  CLOSE cr_sel;

  lv_ret := '< ' || SUBSTR (lv_ret, 1, LENGTH (lv_ret) - 1) || ' >';
  RETURN lv_ret;
  NULL;
 END;

