-- Процедура создания макета по группе an_gid - ИД группы an_makId - ИД макета
 PROCEDURE create_maket_from_group_p (an_makid NUMBER, an_gid NUMBER) IS
  CURSOR cr_sel_gname IS
   SELECT gid, NAME
     FROM GROUPS
    WHERE PARENT = an_gid;

  CURSOR cr_sel_pmid (ln_gid NUMBER) IS
   SELECT     mid, DECODE (inverted, 'y', -1, 1) inv
         FROM GROUPS
        WHERE mid IS NOT NULL
   CONNECT BY PARENT = PRIOR gid
   START WITH gid = ln_gid;

  ln_i        NUMBER DEFAULT 0;
  ln_ngroup   NUMBER;
 BEGIN
  FOR lc_cr_sel_gname IN cr_sel_gname LOOP
   ln_i := ln_i + 1;
   makets_pg.ins_g (an_makid, ln_i, lc_cr_sel_gname.NAME, '', ln_ngroup);

   FOR lc_cr_sel_pmid IN cr_sel_pmid (lc_cr_sel_gname.gid) LOOP
    makets_pg.chg_p (ln_ngroup, lc_cr_sel_pmid.mid, lc_cr_sel_pmid.inv, 5);
   END LOOP;
  END LOOP;
 END;

