 FUNCTION get_maxpowerpoint (an_parent NUMBER, is_group NUMBER)
  RETURN NUMBER IS
  ln_ret   NUMBER;
 BEGIN
  IF NVL (is_group, 0) = 1 THEN   --По группам
   IF an_parent IS NOT NULL THEN
    SELECT MAX (mid)
      INTO ln_ret
      FROM feeders
     WHERE mid IN (SELECT     mid
                         FROM GROUPS
                   CONNECT BY PRIOR gid = PARENT
                   START WITH gid = an_parent) AND POWER = (SELECT MAX (f.POWER)
                                                              FROM (SELECT     mid
                                                                          FROM GROUPS
                                                                    CONNECT BY PRIOR gid = PARENT
                                                                    START WITH gid = an_parent) g,
                                                                   feeders f
                                                             WHERE f.mid = g.mid);
   ELSE
    SELECT MAX (mid)
      INTO ln_ret
      FROM feeders
     WHERE mid IN (SELECT mid
                     FROM GROUPS) AND POWER = (SELECT MAX (f.POWER)
                                                 FROM GROUPS g, feeders f
                                                WHERE f.mid = g.mid);
   END IF;
  ELSE   --По точкам
   IF an_parent IS NOT NULL THEN
    SELECT MAX (mid)
      INTO ln_ret
      FROM feeders
     WHERE mid IN (SELECT     mid
                         FROM points
                   CONNECT BY PRIOR mid = PARENT
                   START WITH mid = an_parent) AND POWER = (SELECT MAX (f.POWER)
                                                              FROM (SELECT     mid
                                                                          FROM points
                                                                    CONNECT BY PRIOR mid = PARENT
                                                                    START WITH mid = an_parent) g,
                                                                   feeders f
                                                             WHERE f.mid = g.mid);
   ELSE
    SELECT MAX (mid)
      INTO ln_ret
      FROM feeders
     WHERE POWER = (SELECT MAX (POWER)
                      FROM feeders);
   END IF;
  END IF;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION get_datebyshortdate (ad_shortdate DATE, ad_relative DATE)
  RETURN DATE IS
  ld_ret     DATE;
  ln_year    NUMBER       DEFAULT TO_CHAR (ad_relative, 'YYYY');
  lv_short   VARCHAR2 (8) DEFAULT TO_CHAR (ad_shortdate, 'MMDD');
  ln_min     NUMBER;
 BEGIN
  ln_min :=
   LEAST (ABS (ad_relative - TO_DATE (ln_year || lv_short, 'YYYYMMDD')), ABS (ad_relative - ADD_MONTHS (TO_DATE (ln_year || lv_short, 'YYYYMMDD'), -12)),
          ABS (ad_relative - ADD_MONTHS (TO_DATE (ln_year || lv_short, 'YYYYMMDD'), 12)));

  IF ln_min = ABS (ad_relative - TO_DATE (ln_year || lv_short, 'YYYYMMDD')) THEN
   RETURN TO_DATE (ln_year || lv_short, 'YYYYMMDD');
  ELSIF ln_min = ABS (ad_relative - ADD_MONTHS (TO_DATE (ln_year || lv_short, 'YYYYMMDD'), -12)) THEN
   RETURN ADD_MONTHS (TO_DATE (ln_year || lv_short, 'YYYYMMDD'), -12);
  ELSE
   RETURN ADD_MONTHS (TO_DATE (ln_year || lv_short, 'YYYYMMDD'), 12);
  END IF;
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION get_sum_gr (an_group NUMBER, ad_start DATE, ad_end DATE, av_type VARCHAR2, an_dif NUMBER)
  RETURN vt_number IS
  CURSOR lcur_sel IS
   SELECT   SUM (-util_pg.sld (h.mid, NVL (h.er * DECODE (g.npartly, 2, 0, 1), 0), NVL (h.ed * DECODE (g.npartly, 1, 0, 1), 0)) * DECODE (g.inverted, 'y', 1, -1))
                                                                                                                                                                  e,
            SUM (-util_pg.sld (h.mid, NVL (h.q1, 0), NVL (h.q3, 0)) * DECODE (g.inverted, 'y', 1, -1)) q
       FROM halfhour h, GROUPS g
      WHERE g.gid IN (SELECT     gid
                            FROM GROUPS
                      CONNECT BY PARENT = PRIOR gid
                      START WITH gid = an_group) AND g.mid = h.mid AND h.date_time > ad_start AND h.date_time <= ad_end
   GROUP BY FLOOR (TO_CHAR (date_time - 1 / 86400, 'sssss') / (60 * an_dif))
   ORDER BY FLOOR (TO_CHAR (date_time - 1 / 86400, 'sssss') / (60 * an_dif));

  lt_ret   vt_number := vt_number ();
  i        NUMBER    DEFAULT 0;
 BEGIN
  FOR lc IN lcur_sel LOOP
   i := i + 1;
   lt_ret.EXTEND;

   IF av_type = 'E' THEN
    lt_ret (i) := lc.e;
   ELSIF av_type = 'Q' THEN
    lt_ret (i) := lc.q;
   ELSE
    lt_ret (i) := NULL;
   END IF;
  END LOOP;

  RETURN lt_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION get_sum_group (an_group NUMBER, ad_start DATE, ad_end DATE, av_type VARCHAR2, an_order NUMBER, an_dif NUMBER)
  RETURN NUMBER IS
  ln_ret   NUMBER;
 BEGIN
  IF av_type = 'E' THEN
   SELECT   SUM (-util_pg.sld (h.mid, NVL (h.er * DECODE (g.npartly, 2, 0, 1), 0), NVL (h.ed * DECODE (g.npartly, 1, 0, 1), 0)) * DECODE (g.inverted, 'y', 1, -1))
       INTO ln_ret
       FROM halfhour h, GROUPS g
      WHERE g.gid IN (SELECT     gid
                            FROM GROUPS
                      CONNECT BY PARENT = PRIOR gid
                      START WITH gid = an_group) AND g.mid = h.mid AND h.date_time > ad_start AND h.date_time <= ad_end
   GROUP BY FLOOR (TO_CHAR (date_time - 1 / 86400, 'sssss') / (60 * DECODE (an_order, NULL, 60 * 24, an_dif)))
     HAVING (an_order IS NULL OR FLOOR (TO_CHAR (date_time - 1 / 86400, 'sssss') / (60 * DECODE (an_order, NULL, 60 * 24, an_dif))) + 1 = an_order);
  ELSIF av_type = 'Q' THEN
   SELECT   SUM (-util_pg.sld (h.mid, NVL (h.q1, 0), NVL (h.q3, 0)) * DECODE (g.inverted, 'y', 1, -1))
       INTO ln_ret
       FROM halfhour h, GROUPS g
      WHERE g.gid IN (SELECT     gid
                            FROM GROUPS
                      CONNECT BY PARENT = PRIOR gid
                      START WITH gid = an_group) AND g.mid = h.mid AND h.date_time > ad_start AND h.date_time <= ad_end
   GROUP BY FLOOR (TO_CHAR (date_time - 1 / 86400, 'sssss') / (60 * DECODE (an_order, NULL, 60 * 24, an_dif)))
     HAVING (an_order IS NULL OR FLOOR (TO_CHAR (date_time - 1 / 86400, 'sssss') / (60 * DECODE (an_order, NULL, 60 * 24, an_dif))) + 1 = an_order);
  END IF;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
-- Возврашает сумму расходов ээ за период
 FUNCTION get_sum (an_mid NUMBER, ad_stdate DATE, ad_findate DATE, an_etype NUMBER, av_sum_table VARCHAR2)
  RETURN NUMBER IS
  ln_entype       NUMBER;
  lnret           NUMBER;
  lv_sql          VARCHAR2 (300);
  lv_field_name   VARCHAR2 (20);
--******************************************************************************
-- Для расчета расхода по показаниям
  ln_dmid         NUMBER;   -- ИД дубля
  ld_st_ov        DATE           DEFAULT NULL;
  ld_fin_ov       DATE           DEFAULT NULL;
  ln_id_ov        NUMBER;   -- ИД обводника или основной точки
  ld_st_dub       DATE;
  ld_fin_dub      DATE;
  ln_met_type     NUMBER;   -- 1 работаем по дублю 0- по основному
  ld_st_ch        DATE;
  ld_fin_ch       DATE;
  ln_cons         NUMBER         DEFAULT 0;
  ln_kc           NUMBER;
  ln_kc_point     NUMBER;

  -- возвращает даты переключение на ОВ и обратно за отчетный период
  CURSOR lcur_ov_period (an_mid NUMBER)   -- сюда передаем ид основного счетчика. Соотсетственно в группах для отчетов тоже должны быть основные
                                       IS
   SELECT   ad_stdate ddate, an_mid ID
       FROM DUAL
      WHERE NOT EXISTS (
             SELECT sw1.nswitch
               FROM switches sw1, switches sw2
              WHERE sw1.ID = sw2.ID AND sw1.mid = an_mid AND sw1.dswitch = (SELECT MAX (dswitch)
                                                                              FROM switches
                                                                             WHERE mid = an_mid AND dswitch <= ad_stdate)
                    AND sw2.descape = (SELECT MIN (descape)
                                         FROM switches
                                        WHERE mid = an_mid AND descape > ad_stdate))
   UNION ALL
   SELECT   ad_stdate ddate, sw1.nswitch ID
       FROM switches sw1, switches sw2
      WHERE sw1.ID = sw2.ID AND sw1.mid = an_mid AND sw1.dswitch = (SELECT MAX (dswitch)
                                                                      FROM switches
                                                                     WHERE mid = an_mid AND dswitch <= ad_stdate)
            AND sw2.descape = (SELECT MIN (descape)
                                 FROM switches
                                WHERE mid = an_mid AND descape > ad_stdate)
   UNION ALL
   SELECT   dswitch ddate, nswitch ID
       FROM switches
      WHERE mid = an_mid AND dswitch > ad_stdate AND dswitch < ad_findate
   UNION ALL
   SELECT   descape ddate, an_mid ID
       FROM switches
      WHERE mid = an_mid AND descape > ad_stdate AND descape < ad_findate
   UNION ALL
   SELECT   ad_findate ddate, an_mid ID
       FROM DUAL
   ORDER BY 1;

  -- Возвращает даты перехода на дублирующие счетчики и обратно
  CURSOR lcur_dubperiod (an_dmid NUMBER, ad_stdate DATE, ad_findate DATE)   -- суда суем ИД дублируущего
                                                                         IS
   SELECT   ad_stdate ddate, 1 dubl
       FROM DUAL
      WHERE EXISTS (
             SELECT *
               FROM calcbyduplication cd1, calcbyduplication cd2
              WHERE cd1.dstart = cd2.dstart AND cd1.mid = cd2.mid AND cd1.mid = an_dmid AND cd1.dstart = (SELECT MAX (dstart)
                                                                                                            FROM calcbyduplication
                                                                                                           WHERE mid = an_dmid AND dstart <= ad_stdate)
                    AND (cd2.dend = (SELECT MIN (dend)
                                       FROM calcbyduplication
                                      WHERE mid = an_dmid AND dend > ad_stdate) OR cd2.dend IS NULL))
   UNION ALL
   SELECT   ad_stdate ddate, 0 dubl
       FROM DUAL
      WHERE NOT EXISTS (
             SELECT *
               FROM calcbyduplication cd1, calcbyduplication cd2
              WHERE cd1.dstart = cd2.dstart AND cd1.mid = cd2.mid AND cd1.mid = an_dmid AND cd1.dstart = (SELECT MAX (dstart)
                                                                                                            FROM calcbyduplication
                                                                                                           WHERE mid = an_dmid AND dstart <= ad_stdate)
                    AND (cd2.dend = (SELECT MIN (dend)
                                       FROM calcbyduplication
                                      WHERE mid = an_dmid AND dend > ad_stdate) OR cd2.dend IS NULL))
   UNION ALL
   SELECT   dstart ddate, 1 dubl
       FROM calcbyduplication
      WHERE mid = an_dmid AND dstart > ad_stdate AND dstart < ad_findate
   UNION ALL
   SELECT   dend ddate, 0 dubl
       FROM calcbyduplication
      WHERE mid = an_dmid AND dend > ad_stdate AND dend < ad_findate
   UNION ALL
   SELECT   ad_findate ddate, 0 dubl
       FROM DUAL
   ORDER BY 1;

  -- возвращает даты замены счетчиков
  CURSOR lcur_change_met (an_dmid NUMBER, ad_stdate DATE, ad_findate DATE, an_entype NUMBER)   -- суда суем ИД основного или дублирующего в зависимости от ситуации
                                                                                            IS
   SELECT   '1' mtrsn, '1' mtype, ad_stdate ddate, 0 ch
       FROM DUAL
   UNION ALL
   SELECT   mtrsn, mtype, dend ddate, 1 ch
       FROM metershistory
      WHERE mid = an_dmid AND dend >= ad_stdate AND dend < ad_findate AND entype IN (an_entype, 7)
   UNION ALL
   SELECT   mtrsn, mtype, ad_findate ddate, 0 ch
       FROM metershistory
      WHERE mid = an_dmid AND entype IN (an_entype, 7) AND date_time <= ad_stdate AND dend >= ad_findate
   UNION ALL
   SELECT   mtrsn, mtype, ad_findate ddate, 0 ch
       FROM meters
      WHERE mid = an_dmid AND entype IN (an_entype, 7)
            AND NOT EXISTS (SELECT mtrsn, mtype, ad_findate ddate, 0 ch
                              FROM metershistory
                             WHERE mid = an_dmid AND entype IN (an_entype, 7) AND date_time <= ad_stdate AND dend >= ad_findate)
   ORDER BY 3;
--******************************************************************************
 BEGIN
  IF LOWER (av_sum_table) = 'difference' THEN
/*   SELECT kc
     INTO lnret
     FROM feeders
    WHERE mid = an_mid;
   RETURN  get_meterage_difference(an_mid, ad_stdate, ad_findate, an_etype, 0) * lnret;*/
--******************************************************************************-- ищем ид дублирующего счетчика
   BEGIN
    SELECT f.mid
      INTO ln_dmid
      FROM feeders f, points p
     WHERE nmainpoint = an_mid AND f.mid = p.mid AND ROWNUM < 2;
   EXCEPTION
    WHEN NO_DATA_FOUND THEN
     ln_dmid := 0;
   END;

   SELECT kc
     INTO ln_kc_point
     FROM feeders
    WHERE mid = an_mid;

   FOR lc_ov IN lcur_ov_period (an_mid)   -- делаем цикл по переключениям ОВ
                                       LOOP
    IF ld_st_ov IS NOT NULL AND ld_fin_ov IS NULL THEN
     ld_fin_ov := lc_ov.ddate;

     SELECT kc
       INTO ln_kc
       FROM feeders
      WHERE mid = ln_id_ov;

     IF ln_id_ov <> an_mid   -- т.е. было переключение на ОВ
                          THEN
      ln_cons := ln_cons + ROUND ((NVL (util_pg.get_meterage_difference (ln_id_ov, ld_st_ov, ld_fin_ov, an_etype, 0), 0)) * ln_kc);
     END IF;

--------------------------------------------
     ld_st_dub := NULL;
     ld_fin_dub := NULL;

     FOR lc_dub IN lcur_dubperiod (ln_dmid, ld_st_ov, ld_fin_ov)   -- цикл по переходам на дубли
                                                                LOOP
      IF ld_st_dub IS NOT NULL AND ld_fin_dub IS NULL THEN
       ld_fin_dub := lc_dub.ddate;
-- Замены счетчиков выводим независимо от режимов ОВ и переключений на дубл
-- но разность показаний выводится только в случае если расчет ведется по этому счетчику
--==============================================================================
       ld_st_ch := NULL;
       ld_fin_ch := NULL;

       FOR lc_ch IN lcur_change_met (an_mid, ld_st_dub, ld_fin_dub, an_etype)   -- цикл по заменам счетчиков
                                                                             LOOP
        IF ld_st_ch IS NOT NULL AND ld_fin_ch IS NULL THEN
         ld_fin_ch := lc_ch.ddate;

         IF ln_id_ov = an_mid THEN
          ln_cons := ln_cons + ROUND ((NVL (util_pg.get_meterage_difference (an_mid, ld_st_ch, ld_fin_ch, an_etype, 0), 0)) * ln_kc);
         END IF;

         ld_st_ch := ld_fin_ch;
         ld_fin_ch := NULL;
        END IF;

        IF ld_st_ch IS NULL THEN
         ld_st_ch := lc_ch.ddate;
        END IF;
       END LOOP;

--==============================================================================
       ld_st_dub := ld_fin_dub;
       ln_met_type := lc_dub.dubl;
       ld_fin_dub := NULL;
      END IF;

      IF ld_st_dub IS NULL THEN
       ld_st_dub := lc_dub.ddate;
       ln_met_type := lc_dub.dubl;
      END IF;
     END LOOP;

--------------------------------------------
     ld_st_ov := ld_fin_ov;
     ln_id_ov := lc_ov.ID;
     ld_fin_ov := NULL;
    END IF;

    IF ld_st_ov IS NULL THEN
     ld_st_ov := lc_ov.ddate;
     ln_id_ov := lc_ov.ID;
    END IF;
   END LOOP;

--******************************************************************************
   RETURN ln_cons;
  END IF;

  IF an_etype = 2 THEN
   lv_field_name := 'ed';
   ln_entype := 2;
  ELSIF an_etype = 3 THEN
   lv_field_name := 'q1';
   ln_entype := 3;
  ELSIF an_etype = 4 THEN
   lv_field_name := 'q2';
   ln_entype := 3;
  ELSIF an_etype = 5 THEN
   lv_field_name := 'q3';
   ln_entype := 5;
  ELSIF an_etype = 6 THEN
   lv_field_name := 'q4';
   ln_entype := 5;
  --зона A
  ELSIF an_etype = 7 THEN
   lv_field_name := 'aer';
   ln_entype := 1;
  ELSIF an_etype = 8 THEN
   lv_field_name := 'aed';
   ln_entype := 2;
  ELSIF an_etype = 9 THEN
   lv_field_name := 'aq1';
   ln_entype := 3;
  ELSIF an_etype = 10 THEN
   lv_field_name := 'aq2';
   ln_entype := 3;
  ELSIF an_etype = 11 THEN
   lv_field_name := 'aq3';
   ln_entype := 5;
  ELSIF an_etype = 12 THEN
   lv_field_name := 'aq4';
   ln_entype := 5;
  --зона B
  ELSIF an_etype = 13 THEN
   lv_field_name := 'ber';
   ln_entype := 1;
  ELSIF an_etype = 14 THEN
   lv_field_name := 'bed';
   ln_entype := 2;
  ELSIF an_etype = 15 THEN
   lv_field_name := 'bq1';
   ln_entype := 3;
  ELSIF an_etype = 16 THEN
   lv_field_name := 'bq2';
   ln_entype := 3;
  ELSIF an_etype = 17 THEN
   lv_field_name := 'bq3';
   ln_entype := 5;
  ELSIF an_etype = 18 THEN
   lv_field_name := 'bq4';
   ln_entype := 5;
  --зона C
  ELSIF an_etype = 19 THEN
   lv_field_name := 'cer';
   ln_entype := 1;
  ELSIF an_etype = 20 THEN
   lv_field_name := 'ced';
   ln_entype := 2;
  ELSIF an_etype = 21 THEN
   lv_field_name := 'cq1';
   ln_entype := 3;
  ELSIF an_etype = 22 THEN
   lv_field_name := 'cq2';
   ln_entype := 3;
  ELSIF an_etype = 23 THEN
   lv_field_name := 'cq3';
   ln_entype := 5;
  ELSIF an_etype = 24 THEN
   lv_field_name := 'cq4';
   ln_entype := 5;
  ELSE
   lv_field_name := 'er';
   ln_entype := 1;
  END IF;

  lv_sql := 'select sum(' || lv_field_name || ') from ' || av_sum_table || ' where mid=:1 and date_time>:2 and date_time<=:3 ';

  EXECUTE IMMEDIATE lv_sql
               INTO lnret
              USING an_mid, ad_stdate, ad_findate;

  RETURN lnret;
 END;

------------------------------------------------------------------------------------------------------------------------
-- Возврашает сумму расходов ээ за период по точке, тр-ру или линии
-- по сути расход возвращается как сумма расходов по всем точкам заданого параметра (an_windingtype)
-- an_mid - ид точки, трансформатора или линии
-- an_etype = 1 - расход актива
-- an_etype = 3 - расход реактива
-- an_windingtype - номер обмотки если тр 3-х обмоточный
--                                                       1 - высокая обмотка
--                                                       2 - средняя
--                                                       3 - низкая
--                                                   0 - для 2-х обмоточного, линии или точки
 FUNCTION get_sum_obj (an_mid NUMBER, ad_stdate DATE, ad_findate DATE, an_etype NUMBER, av_sum_table VARCHAR2, an_windingtype NUMBER)
  RETURN NUMBER IS
  ln_ret             NUMBER := 0;
  ln_sum             NUMBER := 0;
  ln_sum_work_time   NUMBER;
  ln_obj_type        NUMBER;

  -- Определяет сумарный расход по всем точкам тр-ра или линии с учетом их вхождения
  CURSOR lcur_sum (lc_mid NUMBER, en_type NUMBER, lc_nwinding NUMBER) IS
   SELECT SUM (DECODE (uc.ntype,
                       1, util_pg.get_sum (uc.mid, ad_stdate, ad_findate, DECODE (en_type, 1, 1, 3, DECODE (nratio, NULL, 3, 1)), av_sum_table) * uc.nkc
                        * DECODE (en_type, 3, NVL (nratio, 1), 1),
                       2, util_pg.get_sum (uc.mid, ad_stdate, ad_findate, DECODE (en_type, 1, 2, 3, DECODE (nratio, NULL, 5, 2)), av_sum_table) * uc.nkc
                        * DECODE (en_type, 3, NVL (nratio, 1), 1),
                       (util_pg.get_sum (uc.mid, ad_stdate, SYSDATE, DECODE (en_type, 1, 1, 3, DECODE (nratio, NULL, 3, 1)), av_sum_table)
                        - util_pg.get_sum (uc.mid, ad_stdate, ad_findate, DECODE (en_type, 1, 2, 3, DECODE (nratio, NULL, 5, 2)), av_sum_table)
                       )
                       * uc.nkc * DECODE (en_type, 3, NVL (nratio, 1), 1)
                      )) tr_sum
     FROM usedconsumpt uc, recompens r, connectionparam cp
    WHERE uc.nconnectionparam = cp.nconnectionparam AND cp.mid = lc_mid AND r.nrecompens(+) = uc.nrecompens AND (nwinding = lc_nwinding OR nwinding = 0);

  -- Выводит ид параллельных параметров трансформаторов а также ид самого тр или линии
  CURSOR lcur_tr_id (lc_mid NUMBER, lc_nwinding NUMBER) IS
   SELECT DISTINCT NVL (cp2.mid, cp1.mid) mid
              FROM connectionparam cp1, connectionparam cp2
             WHERE cp1.mid = an_mid AND cp1.nparallelconnection = cp2.nparallelconnection(+) AND cp1.nwinding = lc_nwinding;
 BEGIN
  SELECT ind
    INTO ln_obj_type
    FROM points
   WHERE mid = an_mid;

  IF ln_obj_type >= 600 AND ln_obj_type <= 610   -- т.е. для тр.
                                              THEN
   -- Вычисляем сумарное время работы всех паралельных трансформаторов
   SELECT SUM (util_pg.get_workhours (mid, TO_CHAR (ad_stdate, 'yyyymm'), 1))
     INTO ln_sum_work_time
     FROM (SELECT DISTINCT NVL (cp2.mid, cp1.mid) mid
                      FROM connectionparam cp1, connectionparam cp2
                     WHERE cp1.mid = an_mid AND cp1.nparallelconnection = cp2.nparallelconnection(+) AND cp1.nwinding = an_windingtype);

   IF ln_sum_work_time <= 0 THEN
    RETURN ln_ret;
   END IF;

   -- делаем цикл по параллельным параметрам
   FOR lc_tr_id IN lcur_tr_id (an_mid, an_windingtype) LOOP
    FOR lc_sum IN lcur_sum (lc_tr_id.mid, an_etype, an_windingtype) LOOP
     ln_sum := ln_sum + lc_sum.tr_sum;
    END LOOP;
   END LOOP;

   ln_ret := ln_sum * util_pg.get_workhours (an_mid, TO_CHAR (ad_stdate, 'yyyymm'), 1) / ln_sum_work_time;
  END IF;

  IF ln_obj_type = 500   -- т.е. для линии
                      THEN
   -- делаем цикл по параллельным параметрам
   FOR lc_tr_id IN lcur_tr_id (an_mid, an_windingtype) LOOP
    FOR lc_sum IN lcur_sum (lc_tr_id.mid, an_etype, an_windingtype) LOOP
     ln_ret := ln_ret + lc_sum.tr_sum;
    END LOOP;
   END LOOP;
  END IF;

  IF ln_obj_type = 3   -- т.е. для точки
                    THEN
   ln_ret := util_pg.get_sum (an_mid, ad_stdate, ad_findate, an_etype, av_sum_table);
  END IF;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
--Возвращает расширение файла
 FUNCTION get_fileext (av_fname VARCHAR2)
  RETURN VARCHAR2 IS
 BEGIN
  IF INSTR (av_fname, '.', -1, 1) > 0 THEN
   RETURN SUBSTR (av_fname, INSTR (av_fname, '.', -1, 1) + 1);
  END IF;

  RETURN '';
 END;

------------------------------------------------------------------------------------------------------------------------
  --Возвращает время работы точки в минутах
  -- an_control_type - 1 по наличии фазного напряжения
  -- an_control_type - 2 по наличии профиля большего пороговой мощности
  -- an_control_type - 3 по наличии ГН большего пороговой мощности
  -- an_int_interval - перод интеграции, т.е. по сколько минут группировать данные
 FUNCTION get_pointworktime (an_mid NUMBER, ad_start DATE, ad_end DATE, an_control_type NUMBER, an_int_interval NUMBER DEFAULT 30)
  RETURN NUMBER IS
  ln_ret          NUMBER;
  threshold_val   NUMBER DEFAULT 0;
 BEGIN
  SELECT NVL (allnumber_f (MAX (get_param (vaddparams, 3))), 0)
    INTO threshold_val
    FROM feeders
   WHERE mid = an_mid;

  threshold_val := threshold_val / (60 / an_int_interval);

  IF an_control_type = 1 THEN
   SELECT COUNT (*) * an_int_interval
     INTO ln_ret
     FROM (SELECT   1
               FROM curr_power_arch
              WHERE mid = an_mid AND date_time > ad_start AND date_time <= ad_end
           GROUP BY util_pg.trunc_d (date_time - 1 / 86400, an_int_interval / 1440)
             HAVING NVL (SUM (volt), 0) + NVL (SUM (volt2), 0) + NVL (SUM (volt3), 0) > 0);
  ELSIF an_control_type = 2 THEN
   SELECT COUNT (*) * an_int_interval
     INTO ln_ret
     FROM (SELECT   1
               FROM PROFILE
              WHERE mid = an_mid AND date_time > ad_start AND date_time <= ad_end
           GROUP BY util_pg.trunc_d (date_time - 1 / 86400, an_int_interval / 1440)
             HAVING NVL (SUM (er), 0) + NVL (SUM (ed), 0) > threshold_val);
  ELSIF an_control_type = 3 THEN
   SELECT COUNT (*) * an_int_interval
     INTO ln_ret
     FROM (SELECT   1
               FROM halfhourold
              WHERE mid = an_mid AND date_time > ad_start AND date_time <= ad_end
           GROUP BY util_pg.trunc_d (date_time - 1 / 86400, an_int_interval / 1440)
             HAVING NVL (SUM (er), 0) + NVL (SUM (ed), 0) > threshold_val);
  END IF;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
  --Возвращает время работы точки в минутах
  -- an_control_type - 1 по наличии фазного напряжения
  -- an_control_type - 2 по наличии профиля большего пороговой мощности
  -- an_control_type - 3 по наличии ГН большего пороговой мощности
  -- an_int_interval - перод интеграции, т.е. по сколько минут группировать данные
  -- an_etype        - параметр может принимать значения 0 - er,ed ;1 - er; 2 - ed
 FUNCTION get_pointworktime2 (an_mid NUMBER, ad_start DATE, ad_end DATE, an_control_type NUMBER, an_int_interval NUMBER DEFAULT 30, an_etype NUMBER DEFAULT 0)
  RETURN NUMBER IS
  ln_ret          NUMBER;
  threshold_val   NUMBER DEFAULT 0;
 BEGIN
  SELECT NVL (allnumber_f (MAX (get_param (vaddparams, 3))), 0)
    INTO threshold_val
    FROM feeders
   WHERE mid = an_mid;

  threshold_val := threshold_val / (60 / an_int_interval);

  IF an_control_type = 1 THEN
   SELECT COUNT (*) * an_int_interval
     INTO ln_ret
     FROM (SELECT   1
               FROM curr_power_arch
              WHERE mid = an_mid AND date_time > ad_start AND date_time <= ad_end
           GROUP BY util_pg.trunc_d (date_time - 1 / 86400, an_int_interval / 1440)
             HAVING NVL (SUM (volt), 0) + NVL (SUM (volt2), 0) + NVL (SUM (volt3), 0) > 0);
  ELSIF an_control_type = 2 THEN
   SELECT COUNT (*) * an_int_interval
     INTO ln_ret
     FROM (SELECT   1
               FROM PROFILE
              WHERE mid = an_mid AND date_time > ad_start AND date_time <= ad_end
           GROUP BY util_pg.trunc_d (date_time - 1 / 86400, an_int_interval / 1440)
             HAVING DECODE (an_etype, 0, NVL (SUM (er), 0) + NVL (SUM (ed), 0), 1, NVL (SUM (er), 0), 2, NVL (SUM (ed), 0)) > threshold_val);
  ELSIF an_control_type = 3 THEN
   SELECT COUNT (*) * an_int_interval
     INTO ln_ret
     FROM (SELECT   1
               FROM halfhourold
              WHERE mid = an_mid AND date_time > ad_start AND date_time <= ad_end
           GROUP BY util_pg.trunc_d (date_time - 1 / 86400, an_int_interval / 1440)
             HAVING DECODE (an_etype, 0, NVL (SUM (er), 0) + NVL (SUM (ed), 0), 1, NVL (SUM (er), 0), 2, NVL (SUM (ed), 0)) > threshold_val);
  END IF;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
  --Возвращает время работы параметра для трансформатора по расчёту потерь
 FUNCTION get_paramworktime (an_pid NUMBER, ad_date DATE)
  RETURN NUMBER IS
  ln_ret   NUMBER;
 BEGIN
  SELECT a.nworkinghours
    INTO ln_ret
    FROM connectionparamfullhours a
   WHERE a.nconnectionparam = an_pid AND a.naccperiod = TO_CHAR (ad_date, 'yyyymm');

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
--Возвращает тип вычисления текущей мощности (1- по тек показаниям счетчика, иначе как получится)
 FUNCTION get_typecalcpower (an_mid NUMBER)
  RETURN NUMBER IS
  ln_ret   NUMBER;
 BEGIN
  IF get_customer_id = 16 THEN
   RETURN 1;
  END IF;

  SELECT COUNT (*)
    INTO ln_ret
    FROM DUAL
   WHERE EXISTS (SELECT *
                   FROM feeders
                  WHERE mid = an_mid AND TRIM (get_param (vaddparams, 1)) = '1');

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
  --Возвращает вести ли покаания по квадрантам
 FUNCTION is_indicbyq1234 (an_mid NUMBER)
  RETURN NUMBER IS
  ln_ret   NUMBER;
 BEGIN
  SELECT COUNT (*)
    INTO ln_ret
    FROM DUAL
   WHERE EXISTS (SELECT *
                   FROM feeders
                  WHERE mid = an_mid AND q1234 = '*');

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
  --Возвращает вести ли профиль по curr_power_arch
 FUNCTION is_calc_profile_by_cp (an_mid NUMBER)
  RETURN NUMBER IS
 BEGIN
  IF NVL (getparamvalue_f (25), 0) <> 1 THEN
   RETURN 0;
  END IF;

  IF get_customer_id = 16 THEN
   RETURN 1;
  END IF;

  RETURN 0;
 END;

------------------------------------------------------------------------------------------------------------------------
 /*
 Возвращает тип ведения ГН
 (1- данные ГН пишем в PROFILE и суммируем для каждого получаса профиль в halfhourtmp)
  2- данные ГН пишем halfhourtmp и размножаем в PROFILE (для красоты сравнивания))
 */
 FUNCTION get_typekeephalfhour (an_mid NUMBER)
  RETURN NUMBER IS
  lv_ret   VARCHAR2 (16);
 BEGIN
  SELECT SUBSTR (TRIM (MAX (get_param (vaddparams, 2))), 1, 1)
    INTO lv_ret
    FROM feeders
   WHERE mid = an_mid;

  IF lv_ret = '1' THEN
   RETURN 1;
  ELSIF lv_ret = '2' THEN
   RETURN 2;
  END IF;

  RETURN 0;
 END;

------------------------------------------------------------------------------------------------------------------------
-- Возвращает время достижения максимальной нагрузки
 FUNCTION get_timemaxpower (an_gid NUMBER, ad_from DATE, ad_till DATE)
  RETURN DATE IS
  ld_ret   DATE;

  CURSOR lcur_sel IS
   SELECT   t.dt
       FROM (SELECT   (SUM (DECODE (gr.inverted,
                                    'y', -util_pg.sld (gr.mid, NVL (h.er * DECODE (gr.npartly, 2, 0, 1), 0), NVL (h.ed * DECODE (gr.npartly, 1, 0, 1), 0)),
                                    util_pg.sld (gr.mid, NVL (h.er * DECODE (gr.npartly, 2, 0, 1), 0), NVL (h.ed * DECODE (gr.npartly, 1, 0, 1), 0))
                                   ))
                      )
                      * 2 er,
                      util_pg.trunchh24_2 (h.date_time - 1 / 86400) + 1 / 48 dt,
                      util_pg.get_grouplimit (an_gid, util_pg.trunchh24_2 (h.date_time - 1 / 86400) + 1 / 48) lim
                 FROM halfhour h,
                      (SELECT     mid, gid, inverted, npartly
                             FROM GROUPS g
                       CONNECT BY PRIOR gid = PARENT
                       START WITH gid = an_gid) gr
                WHERE gr.mid = h.mid AND h.date_time > ad_from AND h.date_time <= ad_till
             GROUP BY util_pg.trunchh24_2 (h.date_time - 1 / 86400)) t
      WHERE t.er > t.lim
   ORDER BY t.er - t.lim DESC, t.dt;
 BEGIN
  OPEN lcur_sel;

  FETCH lcur_sel
   INTO ld_ret;

  CLOSE lcur_sel;

  RETURN ld_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
-- Возвращает расход за период
 FUNCTION get_saldo (an_gid NUMBER, ad_from DATE, ad_till DATE, an_act NUMBER DEFAULT 1)
  RETURN NUMBER IS
  ln_ret   NUMBER;
 BEGIN
  IF ad_from IS NULL THEN
   SELECT (SUM (DECODE (gr.inverted,
                        'y', -util_pg.sld (gr.mid, NVL (h.er * DECODE (gr.npartly, 2, 0, 1), 0), NVL (h.ed * DECODE (gr.npartly, 1, 0, 1), 0)),
                        util_pg.sld (gr.mid, NVL (h.er * DECODE (gr.npartly, 2, 0, 1), 0), NVL (h.ed * DECODE (gr.npartly, 1, 0, 1), 0))
                       ))
          ) er
     INTO ln_ret
     FROM curr_power h,
          (SELECT     mid, gid, inverted, npartly
                 FROM GROUPS g
           CONNECT BY PRIOR gid = PARENT
           START WITH gid = an_gid) gr
    WHERE gr.mid = h.mid AND SIGN (util_pg.obsolescence_f / 1440 - ABS (SYSDATE - h.date_time)) = 1;
  ELSE
   SELECT (SUM (DECODE (gr.inverted,
                        'y', -util_pg.sld (gr.mid, NVL (h.er * DECODE (gr.npartly, 2, 0, 1), 0), NVL (h.ed * DECODE (gr.npartly, 1, 0, 1), 0)),
                        util_pg.sld (gr.mid, NVL (h.er * DECODE (gr.npartly, 2, 0, 1), 0), NVL (h.ed * DECODE (gr.npartly, 1, 0, 1), 0))
                       ))
          ) er
     INTO ln_ret
     FROM halfhour h,
          (SELECT     mid, gid, inverted, npartly
                 FROM GROUPS g
           CONNECT BY PRIOR gid = PARENT
           START WITH gid = an_gid) gr
    WHERE gr.mid = h.mid AND h.date_time > ad_from AND h.date_time <= ad_till;
  END IF;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION get_ad_balance (an_gid NUMBER, ad_from DATE, ad_till DATE, an_proc NUMBER)
  RETURN NUMBER IS
  cn_sigma2          CONSTANT NUMBER DEFAULT 121 / 100;
  cn_defmeterclass   CONSTANT NUMBER DEFAULT 1;
  ln_ret                      NUMBER;
 BEGIN
  IF ad_from IS NULL THEN
   SELECT POWER (SUM (t.deltar2 * t.itr2 + t.deltad2 * t.itd2), 1 / 2) * DECODE (an_proc, 1, 1, GREATEST (MAX (t.er), MAX (t.ed)) / 100) nb
     INTO ln_ret
     FROM (SELECT NVL (DECODE (sm.er, 0, 0, it.er / sm.er), 0) * NVL (DECODE (sm.er, 0, 0, it.er / sm.er), 0) itr2,
                  NVL (DECODE (sm.ed, 0, 0, it.ed / sm.ed), 0) * NVL (DECODE (sm.ed, 0, 0, it.ed / sm.ed), 0) itd2,
                  cn_sigma2
                  * (fr.nclasstn * fr.nclasstn + fr.nclasstt * fr.nclasstt
                     + NVL (DECODE (gr.inverted, 'y', mr.dclass, mr.eclass), cn_defmeterclass)
                       * NVL (DECODE (gr.inverted, 'y', mr.dclass, mr.eclass), cn_defmeterclass)
                    ) deltar2,
                  cn_sigma2
                  * (fr.nclasstn * fr.nclasstn + fr.nclasstt * fr.nclasstt
                     + NVL (DECODE (gr.inverted, 'y', mr.eclass, mr.dclass), cn_defmeterclass)
                       * NVL (DECODE (gr.inverted, 'y', mr.eclass, mr.dclass), cn_defmeterclass)
                    ) deltad2,
                  sm.er, sm.ed
             FROM (SELECT   g.gid, NVL (SUM (DECODE (g.inverted, 'y', h.ed, h.er)), 0) er, NVL (SUM (DECODE (g.inverted, 'y', h.er, h.ed)), 0) ed
                       FROM GROUPS g, curr_power h
                      WHERE g.gid IN (SELECT     gid
                                            FROM GROUPS
                                      CONNECT BY PRIOR gid = PARENT
                                      START WITH gid = an_gid) AND g.mid = h.mid AND SIGN (util_pg.obsolescence_f / 1440 - ABS (SYSDATE - h.date_time)) = 1
                   GROUP BY g.gid) it,
                  (SELECT NVL (SUM (DECODE (g.inverted, 'y', h.ed, h.er)), 0) er, NVL (SUM (DECODE (g.inverted, 'y', h.er, h.ed)), 0) ed
                     FROM GROUPS g, curr_power h
                    WHERE g.gid IN (SELECT     gid
                                          FROM GROUPS
                                    CONNECT BY PRIOR gid = PARENT
                                    START WITH gid = an_gid) AND g.mid = h.mid AND SIGN (util_pg.obsolescence_f / 1440 - ABS (SYSDATE - h.date_time)) = 1) sm,
                  (SELECT   mid, MAX (DECODE (entype, 1, mclass, 7, mclass, NULL)) eclass, MAX (DECODE (entype, 2, mclass, 7, mclass, NULL)) dclass
                       FROM meters
                   GROUP BY mid) mr,
                  GROUPS gr,
                  feeders fr
            WHERE it.gid = gr.gid(+) AND gr.mid = fr.mid(+) AND gr.mid = mr.mid(+)) t;
  ELSE
   SELECT POWER (SUM (t.deltar2 * t.itr2 + t.deltad2 * t.itd2), 1 / 2) * DECODE (an_proc, 1, 1, GREATEST (MAX (t.er), MAX (t.ed)) / 100) nb
     INTO ln_ret
     FROM (SELECT NVL (DECODE (sm.er, 0, 0, it.er / sm.er), 0) * NVL (DECODE (sm.er, 0, 0, it.er / sm.er), 0) itr2,
                  NVL (DECODE (sm.ed, 0, 0, it.ed / sm.ed), 0) * NVL (DECODE (sm.ed, 0, 0, it.ed / sm.ed), 0) itd2,
                  cn_sigma2
                  * (fr.nclasstn * fr.nclasstn + fr.nclasstt * fr.nclasstt
                     + NVL (DECODE (gr.inverted, 'y', mr.dclass, mr.eclass), cn_defmeterclass)
                       * NVL (DECODE (gr.inverted, 'y', mr.dclass, mr.eclass), cn_defmeterclass)
                    ) deltar2,
                  cn_sigma2
                  * (fr.nclasstn * fr.nclasstn + fr.nclasstt * fr.nclasstt
                     + NVL (DECODE (gr.inverted, 'y', mr.eclass, mr.dclass), cn_defmeterclass)
                       * NVL (DECODE (gr.inverted, 'y', mr.eclass, mr.dclass), cn_defmeterclass)
                    ) deltad2,
                  sm.er, sm.ed
             FROM (SELECT   g.gid, NVL (SUM (DECODE (g.inverted, 'y', h.ed, h.er)), 0) er, NVL (SUM (DECODE (g.inverted, 'y', h.er, h.ed)), 0) ed
                       FROM GROUPS g, halfhour h
                      WHERE g.gid IN (SELECT     gid
                                            FROM GROUPS
                                      CONNECT BY PRIOR gid = PARENT
                                      START WITH gid = an_gid) AND g.mid = h.mid AND h.date_time > ad_from AND h.date_time <= ad_till
                   GROUP BY g.gid) it,
                  (SELECT NVL (SUM (DECODE (g.inverted, 'y', h.ed, h.er)), 0) er, NVL (SUM (DECODE (g.inverted, 'y', h.er, h.ed)), 0) ed
                     FROM GROUPS g, halfhour h
                    WHERE g.gid IN (SELECT     gid
                                          FROM GROUPS
                                    CONNECT BY PRIOR gid = PARENT
                                    START WITH gid = an_gid) AND g.mid = h.mid AND h.date_time > ad_from AND h.date_time <= ad_till) sm,
                  (SELECT   mid, MAX (DECODE (entype, 1, mclass, 7, mclass, NULL)) eclass, MAX (DECODE (entype, 2, mclass, 7, mclass, NULL)) dclass
                       FROM meters
                   GROUP BY mid) mr,
                  GROUPS gr,
                  feeders fr
            WHERE it.gid = gr.gid(+) AND gr.mid = fr.mid(+) AND gr.mid = mr.mid(+)) t;
  END IF;

  RETURN ln_ret;
 END;

