 FUNCTION newcalcday_f
  RETURN NUMBER IS
 BEGIN
  IF util_pg.get_customer_id IN (3, 4, 5, 18, 19, 22, 24, 25) THEN
   RETURN 0;
  END IF;

  RETURN 1;
 END;

------------------------------------------------------------------------------------------------------------------------
  -- Вычисление количества точек в группе an_type-1 points, иначе - groups
 FUNCTION get_countpoint_f (an_id NUMBER, an_type NUMBER)
  RETURN NUMBER IS
  ln_ret   NUMBER DEFAULT 0;
 BEGIN
  IF an_type = 1 THEN
   SELECT     COUNT (*)
         INTO ln_ret
         FROM points
        WHERE mid IN (SELECT mid
                        FROM feeders)
   CONNECT BY PRIOR mid = PARENT
   START WITH mid = an_id;
  ELSE
   SELECT     COUNT (*)
         INTO ln_ret
         FROM GROUPS
        WHERE mid IN (SELECT mid
                        FROM feeders)
   CONNECT BY PRIOR gid = PARENT
   START WITH gid = an_id;
  END IF;

  RETURN ln_ret;
 END;

------------------------------------------------------------------------------------------------------------------------
    -- Приведение абсолютных углов в относительные (для монитора отображения параметров сети)
    --an_type Возвращает угол 1- U1U2,2- U1U3,3- U2U3,4- U1I1,5- U2I2,6- U3I3 иначе return  null;
 FUNCTION convert_conner (an_type NUMBER, an_u1 NUMBER, an_u2 NUMBER, an_u3 NUMBER, an_i1 NUMBER, an_i2 NUMBER, an_i3 NUMBER, an_er_ed NUMBER)
  RETURN NUMBER IS
  ln_u1     NUMBER DEFAULT an_u1;
  ln_u2     NUMBER DEFAULT an_u2;
  ln_u3     NUMBER DEFAULT an_u3;
  ln_i1     NUMBER DEFAULT an_i1;
  ln_i2     NUMBER DEFAULT an_i2;
  ln_i3     NUMBER DEFAULT an_i3;
  ln_koef   NUMBER DEFAULT 1;
  ln_ret    NUMBER;
 BEGIN
  IF (an_er_ed < 0) THEN   -- если (er-ed<0) то относительные углы делаем отрицательными
   ln_koef := -1;
  END IF;

  IF an_type = 1 THEN
   ln_ret := ln_u2 - ln_u1;
  ELSIF an_type = 2 THEN
   ln_ret := ln_u3 - ln_u1;
  ELSIF an_type = 3 THEN
   ln_ret := ln_u3 - ln_u2;
  ELSIF an_type = 4 THEN
   ln_ret := ln_i1 - ln_u1;
  ELSIF an_type = 5 THEN
   IF ln_i2 < ln_i1 THEN
    ln_i2 := ln_i2 + 360;
   END IF;

   ln_ret := ln_i2 - ln_u2;
  ELSIF an_type = 6 THEN
   IF ln_i2 < ln_i1 THEN
    ln_i2 := ln_i2 + 360;
   END IF;

   IF ln_i3 < ln_i2 THEN
    ln_i3 := ln_i3 + 360;
   END IF;

   ln_ret := ln_i3 - ln_u3;
  END IF;

  ln_ret := MOD (ln_ret, 360);

  IF ABS (ln_ret) > 180 THEN
   ln_ret := 360 - ABS (ln_ret);
  END IF;

  IF an_type IN (1, 2, 3) THEN
   ln_ret := ABS (ln_ret);
  ELSIF an_type IN (4, 5, 6) THEN
   ln_ret := ln_koef * ABS (ln_ret);
  END IF;

  RETURN ln_ret;
 END;

