  --Возвращает код точки
 FUNCTION get_point_code (an_mid NUMBER, an_enterprise NUMBER, an_mainpoint NUMBER)
  RETURN VARCHAR2 IS
  lv_ret   VARCHAR2 (2000);
 BEGIN
  SELECT MAX (vcode)
    INTO lv_ret
    FROM feeders
   WHERE mid = an_mid;

  IF an_enterprise = 1 THEN
   lv_ret := enterprise_char_f || lv_ret;
  END IF;

  IF an_mainpoint = 1 THEN
   SELECT lv_ret || DECODE (MAX (nmainpoint), NULL, '1', '2')
     INTO lv_ret
     FROM feeders
    WHERE mid = an_mid;
  END IF;

  RETURN lv_ret;
 END;

