   --Проверка преобразования типов
 FUNCTION varchar_to_integer (av_value VARCHAR2)
  RETURN VARCHAR2 IS
 BEGIN
  RETURN TO_CHAR (ROUND (TO_NUMBER (REPLACE (av_value, ',', '.'))));
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20001, 'util_pg.varchar_to_integer: Ошибка преобразования строки ''' || av_value || ''' в число.' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION varchar_to_number (av_value VARCHAR2)
  RETURN VARCHAR2 IS
 BEGIN
  RETURN TO_CHAR (TO_NUMBER (REPLACE (av_value, ',', '.')));
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20001, 'util_pg.varchar_to_number: Ошибка преобразования строки ''' || av_value || ''' в число.' || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION varchar_to_date (av_value VARCHAR2, av_mask VARCHAR2)
  RETURN VARCHAR2 IS
  lv_mask   VARCHAR2 (256) DEFAULT NVL (av_mask, 'dd.mm.yyyy');
 BEGIN
  RETURN TO_CHAR (TO_DATE (av_value, lv_mask), lv_mask);
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20001,
                            'util_pg.varchar_to_date: Ошибка преобразования строки ''' || av_value || ''' в число по формату ''' || lv_mask || '''. ' || CHR (10)
                            || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION varchar_to_time (av_value VARCHAR2, av_mask VARCHAR2)
  RETURN VARCHAR2 IS
  lv_mask   VARCHAR2 (256) DEFAULT NVL (av_mask, 'HH24:MI');
 BEGIN
  IF av_mask IS NULL AND INSTR (av_value, ':', 1, 2) > 0 THEN
   lv_mask := 'HH24:MI:SS';
  END IF;

  RETURN TO_CHAR (TO_DATE (av_value, lv_mask), lv_mask);
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20001,
                            'util_pg.varchar_to_time: Ошибка преобразования строки ''' || av_value || ''' в число по формату ''' || lv_mask || '''. ' || CHR (10)
                            || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION varchar_to_datetime (av_value VARCHAR2, av_mask VARCHAR2)
  RETURN VARCHAR2 IS
  lv_mask   VARCHAR2 (256) DEFAULT NVL (av_mask, 'DD.MM.YYYY HH24:MI');
 BEGIN
  IF av_mask IS NULL AND INSTR (av_value, ':', 1, 2) > 0 THEN
   lv_mask := 'DD.MM.YYYY HH24:MI:SS';
  END IF;

  RETURN TO_CHAR (TO_DATE (av_value, lv_mask), lv_mask);
 EXCEPTION
  WHEN OTHERS THEN
   raise_application_error (-20001,
                            'util_pg.varchar_to_datetime: Ошибка преобразования строки ''' || av_value || ''' в число по формату ''' || lv_mask || '''. '
                            || CHR (10) || SQLERRM (SQLCODE));
 END;

------------------------------------------------------------------------------------------------------------------------
 FUNCTION create_guid (av_prefix VARCHAR2)
  RETURN VARCHAR2 IS
  lv_ret      VARCHAR2 (256);
  lv_prefix   VARCHAR2 (256) DEFAULT av_prefix;
 BEGIN
  IF lv_prefix IS NULL THEN
   SELECT MAX (vvalue)
     INTO lv_prefix
     FROM parameter
    WHERE npid = 40;
  END IF;

  lv_ret := LOWER (STANDARD.SYS_GUID);
  RETURN lv_prefix || SUBSTR (lv_ret, 1, 8) || '-' || SUBSTR (lv_ret, 9, 4) || '-' || SUBSTR (lv_ret, 13, 4) || '-' || SUBSTR (lv_ret, 17, 4) || '-'
         || SUBSTR (lv_ret, 21, 12);
 END;

