 --Вычисление значение по тексту
 FUNCTION getval (av_patram VARCHAR2, ad_from DATE, ad_till DATE)
  RETURN NUMBER IS
 BEGIN
  RETURN 0;
 END;
------------------------------------------------------------------------------------------------------------------------
BEGIN
 BEGIN   --Две попытки чтоб при слете было 2 попытки
  SELECT NVL (SUM (DECODE (vvalue, '', 0, vvalue)), 0)
    INTO gn_customer_id
    FROM parameter
   WHERE npid = 12;

  SELECT NVL (SUM (DECODE (vvalue, '1', 1, 0)), 0)
    INTO gn_isarch
    FROM parameter
   WHERE npid = 26;

  SELECT NVL (SUM (DECODE (vvalue, '', 20, vvalue)), 20)
    INTO gn_obsolescence
    FROM parameter
   WHERE npid = 16;

  SELECT NVL (SUM (DECODE (vvalue, '', -11, vvalue)), -11)
    INTO gn_hh24gid
    FROM parameter
   WHERE npid = 17;

  SELECT TO_DATE ('20000101 ' || NVL (MAX (vvalue), '01:00'), 'YYYYMMDD HH24:MI')
    INTO gd_morningstart
    FROM parameter
   WHERE npid = 15;

  SELECT TO_DATE ('20000101 ' || NVL (MAX (vvalue), '16:00'), 'YYYYMMDD HH24:MI')
    INTO gd_evningstart
    FROM parameter
   WHERE npid = 14;

  SELECT COUNT (*)
    INTO gn_srvcount
    FROM srv;

  SELECT NVL (SUM (DECODE (vvalue, '1', 1, '2', 2, 0)), 0)
    INTO gn_losstype
    FROM parameter
   WHERE npid = 36;

  SELECT NVL (SUM (DECODE (vvalue, '1', 1, 0)), 0)
    INTO gn_admintype
    FROM parameter
   WHERE npid = 37;

  gn_taketimezone := getparamvalue_f (38);
  gn_locksummertime := getparamvalue_f (29);
  gn_inverted := getparamvalue_f (42);
 EXCEPTION
  WHEN OTHERS THEN
   SELECT NVL (SUM (DECODE (vvalue, '', 0, vvalue)), 0)
     INTO gn_customer_id
     FROM parameter
    WHERE npid = 12;

   SELECT NVL (SUM (DECODE (vvalue, '1', 1, 0)), 0)
     INTO gn_isarch
     FROM parameter
    WHERE npid = 26;

   SELECT NVL (SUM (DECODE (vvalue, '', 20, vvalue)), 20)
     INTO gn_obsolescence
     FROM parameter
    WHERE npid = 16;

   SELECT NVL (SUM (DECODE (vvalue, '', -11, vvalue)), -11)
     INTO gn_hh24gid
     FROM parameter
    WHERE npid = 17;

   SELECT TO_DATE ('20000101 ' || NVL (MAX (vvalue), '01:00'), 'YYYYMMDD HH24:MI')
     INTO gd_morningstart
     FROM parameter
    WHERE npid = 15;

   SELECT TO_DATE ('20000101 ' || NVL (MAX (vvalue), '16:00'), 'YYYYMMDD HH24:MI')
     INTO gd_evningstart
     FROM parameter
    WHERE npid = 14;

   SELECT COUNT (*)
     INTO gn_srvcount
     FROM srv;

   SELECT NVL (SUM (DECODE (vvalue, '1', 1, '2', 2, 0)), 0)
     INTO gn_losstype
     FROM parameter
    WHERE npid = 36;

   SELECT NVL (SUM (DECODE (vvalue, '1', 1, 0)), 0)
     INTO gn_admintype
     FROM parameter
    WHERE npid = 37;

   gn_taketimezone := getparamvalue_f (38);
   gn_locksummertime := getparamvalue_f (29);
   gn_inverted := getparamvalue_f (42);
 END;
EXCEPTION
 WHEN OTHERS THEN
  gd_morningstart := TO_DATE ('20000101 01:00', 'YYYYMMDD HH24:MI');
  gd_evningstart := TO_DATE ('20000101 16:00', 'YYYYMMDD HH24:MI');
  gn_customer_id := 0;
  gn_isarch := 0;
  gn_locksummertime := 0;
  gn_srvcount := 1;
  gn_losstype := 0;
  gn_admintype := 0;
  gn_taketimezone := 0;
  gn_inverted := 0;
