PACKAGE BODY waste_pg
IS
--------------------------------------------------------------------------------
  -- пакет даля расчета потерь
  -- дата создания 13/07/2005 Коваленко А.С.

    -- Connectionparam - параметры по тр., линиям и просто по точке. Соответственно mid из points
    -- Sharedconnectionparam - долевые точки по параметру
    -- Usedconsumpt - используемый расход по параметру
    -- Relatedparam - зависимые параметры, т.е. потери на потери…

    -- Recompense - Задает процентовку реактива от актива, если не по счетчику
    -- Connectionparamfullhours - Время работы для параметра (использовать не будем)
    -- Pointfullhours - время работы для точки или трансформатора

    --------------------------------------------------------------------------------
-- Возвращает время работы параметра за период в колличестве часов
-- если add_months(ad_stdate,1) неравно ad_findate то возвращается (ad_stdate - ad_findate)*24
-- иначе считаем следующим образом:
-- ищем в CONNECTIONPARAMFULLHOURS (самый высокий приоритет) если нет
-- ищем в POINTFULLHOURS если нет
-- в CONNECTIONPARAM если и тут нет!
-- ну тогда уж извините берем календарное
-- an_time_type
--              0 - рабочее время
--              1 - полное время
    FUNCTION get_par_time (an_connectionparam NUMBER, ad_stdate DATE, ad_findate DATE, an_time_type NUMBER)
        RETURN NUMBER
    IS
        ln_ret   NUMBER := -1;
    BEGIN
        -- Если не месяц то вываливаем разницу
        IF ADD_MONTHS (ad_stdate, 1) <> ad_findate
        THEN
            ln_ret := (ad_findate - ad_stdate) * 24;
        END IF;

-- если с датами все ок то начинаем копать
        IF ln_ret < 0
        -- сначала смотрим время по параметру, самый высокий приоритет
        THEN
            BEGIN
                SELECT NVL (DECODE (an_time_type, 0, nworkinghours, 1, nfullhours), -1)
                  INTO ln_ret
                  FROM connectionparamfullhours
                 WHERE nconnectionparam = an_connectionparam AND naccperiod = TO_CHAR (ad_stdate, 'yyyymm');
            EXCEPTION
                WHEN NO_DATA_FOUND
                THEN
                    ln_ret := -1;
            END;
        END IF;

        IF ln_ret < 0
        -- затем по времени работы точки или тр. для данного параметра
        THEN
            BEGIN
                SELECT NVL (MAX (DECODE (an_time_type, 0, pf.nworkinghours, 1, pf.nfullhours)), -1)
                  INTO ln_ret
                  FROM connectionparam cp, pointfullhours pf
                 WHERE nconnectionparam = an_connectionparam AND cp.mid = pf.mid AND naccperiod = TO_CHAR (ad_stdate, 'yyyymm');
            EXCEPTION
                WHEN NO_DATA_FOUND
                THEN
                    ln_ret := -1;
            END;
        END IF;

        IF ln_ret < 0
        -- затем в самом параметре константы
        THEN
            BEGIN
                SELECT NVL (DECODE (an_time_type, 0, nworkinghours, 1, nfullhours), -1)
                  INTO ln_ret
                  FROM connectionparam
                 WHERE nconnectionparam = an_connectionparam;
            EXCEPTION
                WHEN NO_DATA_FOUND
                THEN
                    ln_ret := -1;
            END;
        END IF;

        IF ln_ret < 0
        THEN
            ln_ret := (ad_findate - ad_stdate) * 24;
        END IF;

        RETURN ln_ret;
    END;

--------------------------------------------------------------------------------

    -- Возврашает сумму расходов ээ по всем точкам за период для параметра
    -- an_connectionparam - ид параметра
    -- an_etype 1 - актив прием
    --          2 - актив отдача
    --          3 - реактив прием
    --          5 - реактив отдача
    -- av_sum_table - Таблица по которой ищется расход
    -- an_parallel = 1 - с учетом расходов по параллельным параметрам и их доли
    FUNCTION get_par_consum (an_connectionparam NUMBER, ad_stdate DATE, ad_findate DATE, an_etype NUMBER, av_sum_table VARCHAR2, an_parallel NUMBER)
        RETURN NUMBER
    IS
        ln_ret             NUMBER;
        ln_sum_work_time   NUMBER := 0;
        ln_sum             NUMBER := 0;

-- Определяет сумарный расход по всем точкам параметра с учетом их вхождения
        CURSOR lcur_sum (cn_сonnectionparam NUMBER, en_type NUMBER)
        IS
/*  Без учета отдачи
            SELECT SUM (DECODE (uc.ntype,
                                1, util_pg.get_sum (uc.mid, ad_stdate, ad_findate, DECODE (en_type, 1, 1, 3, DECODE (nratio, NULL, 3, 1)),
                                                    av_sum_table)
                                 * uc.nkc
                                 * DECODE (en_type, 3, NVL (nratio, 1), 1),
                                2, util_pg.get_sum (uc.mid, ad_stdate, ad_findate, DECODE (en_type, 1, 2, 3, DECODE (nratio, NULL, 5, 2)),
                                                    av_sum_table)
                                 * uc.nkc
                                 * DECODE (en_type, 3, NVL (nratio, 1), 1),
                                  (  util_pg.get_sum (uc.mid, ad_stdate, ad_findate, DECODE (en_type, 1, 1, 3, DECODE (nratio, NULL, 3, 1)),
                                                      av_sum_table)
                                   - util_pg.get_sum (uc.mid, ad_stdate, ad_findate, DECODE (en_type, 1, 2, 3, DECODE (nratio, NULL, 5, 2)),
                                                      av_sum_table)
                                  )
                                * uc.nkc
                                * DECODE (en_type, 3, NVL (nratio, 1), 1)
                               )) par_sum
              FROM usedconsumpt uc, recompens r
             WHERE uc.nconnectionparam = cn_сonnectionparam AND r.nrecompens(+) = uc.nrecompens;
*/
            SELECT SUM (DECODE (uc.ntype,
                                1, util_pg.get_sum (uc.mid, ad_stdate, ad_findate, DECODE (en_type, 1, 1, 2, 1, DECODE (nratio, NULL, 3, 1)),
                                                    av_sum_table)
                                 * uc.nkc
                                 * DECODE (en_type, 3, NVL (nratio, 1), 5, NVL (nratio, 1), 1),
                                2, util_pg.get_sum (uc.mid, ad_stdate, ad_findate, DECODE (en_type, 1, 2, 2, 2, DECODE (nratio, NULL, 5, 2)),
                                                    av_sum_table)
                                 * uc.nkc
                                 * DECODE (en_type, 3, NVL (nratio, 1), 5, NVL (nratio, 1), 1),
                                  (  util_pg.get_sum (uc.mid, ad_stdate, ad_findate, DECODE (en_type, 1, 1, 2, 1, DECODE (nratio, NULL, 3, 1)),
                                                      av_sum_table)
                                   - util_pg.get_sum (uc.mid, ad_stdate, ad_findate, DECODE (en_type, 1, 2, 2, 2, DECODE (nratio, NULL, 5, 2)),
                                                      av_sum_table)
                                  )
                                * uc.nkc
                                * DECODE (en_type, 3, NVL (nratio, 1), 5, NVL (nratio, 1), 1)
                               )) par_sum
              FROM usedconsumpt uc, recompens r
             WHERE uc.nconnectionparam = cn_сonnectionparam AND r.nrecompens(+) = uc.nrecompens;
-- Выводит ид параллельных параметров
        CURSOR lcur_tr_id
        IS
            SELECT DISTINCT NVL (cp2.nconnectionparam, cp1.nconnectionparam) nconnectionparam
                       FROM connectionparam cp1, connectionparam cp2
                      WHERE cp1.nconnectionparam = an_connectionparam AND cp1.nparallelconnection = cp2.nparallelconnection(+);
    BEGIN
        IF an_parallel = 1
        THEN
            -- делаем цикл по параллельным параметрам
            FOR lc_tr_id IN lcur_tr_id
            LOOP
                FOR lc_sum IN lcur_sum (lc_tr_id.nconnectionparam, an_etype)
                LOOP
                    ln_sum := ln_sum + lc_sum.par_sum;
                END LOOP;

                ln_sum_work_time := ln_sum_work_time + get_par_time (lc_tr_id.nconnectionparam, ad_stdate, ad_findate, 0);
            END LOOP;

            IF ln_sum_work_time = 0
            -- если не один параметр не работал так нечего и ...
            THEN
                RETURN 0;
            END IF;

            -- Расход умножаем на долю параметра с учетом его времени работы
            ln_ret := ln_sum * get_par_time (an_connectionparam, ad_stdate, ad_findate, 0) / ln_sum_work_time;
        ELSE
            -- считаем только один
            FOR lc_sum IN lcur_sum (an_connectionparam, an_etype)
            LOOP
                ln_sum := ln_sum + lc_sum.par_sum;
            END LOOP;

            ln_ret := ln_sum;
        END IF;

        RETURN ln_ret;
    END;

--------------------------------------------------------------------------------

    -- Возврашает сумму расходов ээ по всем точкам за период присудствующих в доле параметра (Sharedconnectionparam)
    -- с учетом расхода реактива nrecompens, а также с учетом птицы расхода
    -- an_connectionparam - ид параметра
    -- an_etype 1 - актив прием
    --          2 - актив отдача
    --          3 - реактив прием
    --          5 - реактив отдача
    -- av_sum_table - Таблица по которой ищется расход
    -- an_parallel = 1 - с учетом расходов по параллельным параметрам и их доли в общем сумарном расходе
    FUNCTION get_share_consum (an_connectionparam NUMBER, ad_stdate DATE, ad_findate DATE, an_etype NUMBER, av_sum_table VARCHAR2, an_parallel NUMBER)
        RETURN NUMBER
    IS
        ln_ret   NUMBER;
    BEGIN
/* Без учета отдачи
        IF an_parallel = 1
        THEN
            SELECT SUM (  util_pg.get_sum (f.mid, ad_stdate, ad_findate, DECODE (an_etype, 1, 1, 3, DECODE (nratio, NULL, 3, 1)), av_sum_table)
                        * DECODE (an_etype, 3, NVL (nratio, 1), 1))
              INTO ln_ret
              FROM feeders f,
                   recompens r,
                   (SELECT DISTINCT s.mid
                               FROM sharedconnectionparam s, (SELECT DISTINCT NVL (cp2.nconnectionparam, cp1.nconnectionparam) nconnectionparam
                                                                         FROM connectionparam cp1, connectionparam cp2
                                                                        WHERE cp1.nconnectionparam = an_connectionparam
                                                                          AND cp1.nparallelconnection = cp2.nparallelconnection(+)) conp
                              WHERE s.nconnectionparam = conp.nconnectionparam AND s.nnotincludeconsump = 0) sharemid
             WHERE f.mid = sharemid.mid AND f.nrecompens = r.nrecompens(+);
        ELSE
            SELECT SUM (  util_pg.get_sum (f.mid, ad_stdate, ad_findate, DECODE (an_etype, 1, 1, 3, DECODE (nratio, NULL, 3, 1)), av_sum_table)
                        * DECODE (an_etype, 3, NVL (nratio, 1), 1))
              INTO ln_ret
              FROM feeders f, recompens r, sharedconnectionparam s
             WHERE s.nconnectionparam = an_connectionparam AND f.mid = s.mid AND f.nrecompens = r.nrecompens(+) AND s.nnotincludeconsump = 0;
        END IF;
*/
        IF an_parallel = 1
        THEN
            SELECT SUM (  util_pg.get_sum (f.mid, ad_stdate, ad_findate, DECODE (an_etype, 3, DECODE (nratio, NULL, 3, 1), 5, DECODE (nratio, NULL, 5, 2),an_etype), av_sum_table)
                        * DECODE (an_etype, 3, NVL (nratio, 1), 5, NVL (nratio, 1), 1))
              INTO ln_ret
              FROM feeders f,
                   recompens r,
                   (SELECT DISTINCT s.mid
                               FROM sharedconnectionparam s, (SELECT DISTINCT NVL (cp2.nconnectionparam, cp1.nconnectionparam) nconnectionparam
                                                                         FROM connectionparam cp1, connectionparam cp2
                                                                        WHERE cp1.nconnectionparam = an_connectionparam
                                                                          AND cp1.nparallelconnection = cp2.nparallelconnection(+)) conp
                              WHERE s.nconnectionparam = conp.nconnectionparam AND s.nnotincludeconsump = 0) sharemid
             WHERE f.mid = sharemid.mid AND f.nrecompens = r.nrecompens(+);
        ELSE
            SELECT SUM (  util_pg.get_sum (f.mid, ad_stdate, ad_findate, DECODE (an_etype, 3, DECODE (nratio, NULL, 3, 1), 5, DECODE (nratio, NULL, 5, 2),an_etype), av_sum_table)
                        * DECODE (an_etype, 3, NVL (nratio, 1), 5, NVL (nratio, 1), 1))
              INTO ln_ret
              FROM feeders f, recompens r, sharedconnectionparam s
             WHERE s.nconnectionparam = an_connectionparam AND f.mid = s.mid AND f.nrecompens = r.nrecompens(+) AND s.nnotincludeconsump = 0;
        END IF;

        RETURN ln_ret;
    END;

--------------------------------------------------------------------------------

    -- Возврашает потери по точке за период
    -- an_mid - ид точки
    -- an_etype 1 - актив прием
    --          2 - актив отдача
    --          3 - реактив прием
    --          5 - реактив отдача
    -- av_sum_table - Таблица по которой ищатся расходы
    -- an_difzone - разбивка потерь на зоны (с bill вычитываются зонные расходы находится их доля от общего и далее дробятся потери)
    --            0 - общие
    --            1 - зона А
    --            2 - зона В
    --            3 - зона С
    FUNCTION get_point_waste (an_mid NUMBER, ad_stdate DATE, ad_findate DATE, an_etype NUMBER, av_sum_table VARCHAR2, an_difzone NUMBER DEFAULT 0)
        RETURN NUMBER
    IS
        ln_ret                    NUMBER := 0;
        ln_sum                    NUMBER := NULL;   -- сумирование потерь
        ln_tmp                    NUMBER;   -- временная для вычитки данных
        ln_share_sum              NUMBER;
        -- сумирование расхода по долевым точкам
        ln_cons_a                 NUMBER;   -- расход актива для расчета потерь
        ln_cons_r                 NUMBER;   -- расход реактива для расчета потерь
        ln_pxx                    NUMBER;
        ln_sn                     NUMBER;
        ln_ixx                    NUMBER;
        ln_tr                     NUMBER;
        ln_to                     NUMBER;
        ln_line_loss              NUMBER;
        ln_act_loss               NUMBER;
        ln_react_loss             NUMBER;
        ln_nwastepercentcalc      NUMBER;
        ln_calcreaktlossbyreakt   NUMBER;
        ln_z                      NUMBER := 1;
        ln_all                    NUMBER;

        -- вычитываем все параметры в дележке потерь которых участвует данная точка
        CURSOR lcur_sel
        IS
            -- Параметры где точка в доле

            --*********************
--  неправильно при параллели
/*            SELECT cp.nconnectionparam, cp.mid, cp.vname, p.ind obj_type, cp.nsn sn, cp.nsh sh, cp.ndeltapidling pxx, cp.ndeltapsc pkz,
                   cp.niidling ixx, cp.nusc ukz, cp.nro ro, cp.nxo xo, cp.nl l, cp.nun un, cp.nenergypercent ep, cp.nrenergypercent rp, cp.nprocent,
                   cp.nwinding
              FROM connectionparam cp, points p, sharedconnectionparam sh
             WHERE sh.mid = an_mid AND cp.nconnectionparam = sh.nconnectionparam AND cp.mid = p.mid
*/
--*********************
            SELECT cp.nconnectionparam, cp.mid, cp.vname, p.ind obj_type, cp.nsn sn, cp.nsh sh, cp.ndeltapidling pxx, cp.ndeltapsc pkz,
                   cp.niidling ixx, cp.nusc ukz, cp.nro ro, cp.nxo xo, cp.nl l, cp.nun un, cp.nenergypercent ep, cp.nrenergypercent rp, cp.nprocent,
                   cp.nwinding
              FROM connectionparam cp,
                   points p,
                   (SELECT DISTINCT NVL (cp2.nconnectionparam, cp1.nconnectionparam) nconnectionparam
                               FROM connectionparam cp1, connectionparam cp2, sharedconnectionparam sh
                              WHERE sh.mid = an_mid AND cp1.nconnectionparam = sh.nconnectionparam AND cp1.nparallelconnection = cp2.nparallelconnection(+)) connparam
             WHERE connparam.nconnectionparam = cp.nconnectionparam AND cp.mid = p.mid
            UNION ALL
            -- Параметры где точка в самом параметре
            SELECT cp.nconnectionparam, cp.mid, cp.vname, p.ind obj_type, cp.nsn sn, cp.nsh sh, cp.ndeltapidling pxx, cp.ndeltapsc pkz,
                   cp.niidling ixx, cp.nusc ukz, cp.nro ro, cp.nxo xo, cp.nl l, cp.nun un, cp.nenergypercent ep, cp.nrenergypercent rp, cp.nprocent,
                   cp.nwinding
              FROM connectionparam cp, points p
             WHERE cp.mid = an_mid AND cp.mid = p.mid;

        -- вытягиваем параметры для трехобмоточного по его ИД
        CURSOR lcur_sel_t3 (cn_mid NUMBER)
        IS
            SELECT   cp.nconnectionparam, cp.vname, mid, cp.nsn sn, cp.nsh sh, cp.ndeltapidling pxx, cp.ndeltapsc pkz, cp.niidling ixx, cp.nusc ukz,
                     cp.nwinding
                FROM connectionparam cp
               WHERE mid = cn_mid AND nwinding > 0
            ORDER BY nwinding;
    BEGIN
        -- вытягиваем тип расчета потерь по точке
        SELECT NVL (f.line_loss, 0), NVL (f.act_loss, 0), NVL (f.react_loss, 0), NVL (f.nwastepercentcalc, 0)
          INTO ln_line_loss, ln_act_loss, ln_react_loss, ln_nwastepercentcalc
          FROM feeders f
         WHERE mid = an_mid;

        -- определяем как делить реактивные потери, по активу или реактиву
/* Без учета отдачи
        SELECT DECODE (an_etype, 1, 1, 3, DECODE (util_pg.calcreaktlossbyreakt_f, 1, 3, 1))
          INTO ln_calcreaktlossbyreakt
          FROM DUAL;
*/
        SELECT DECODE (an_etype, 3, DECODE (util_pg.calcreaktlossbyreakt_f, 1, 3, 1), 5, DECODE (util_pg.calcreaktlossbyreakt_f, 1, 5, 2),an_etype)
          INTO ln_calcreaktlossbyreakt
          FROM DUAL;

        IF ln_nwastepercentcalc = 1   -- процент от расхода
        THEN
/* Без учета отдачи
            SELECT   util_pg.get_sum (f.mid, ad_stdate, ad_findate, DECODE (an_etype, 1, 1, 3, DECODE (nratio, NULL, 3, 1)), av_sum_table)
                   * DECODE (an_etype, 3, NVL (nratio, 1), 1)
                   * DECODE (an_etype, 1, (ln_line_loss + ln_act_loss), 3, ln_react_loss)
                   / 100
*/
           SELECT  util_pg.get_sum (f.mid, ad_stdate, ad_findate, DECODE (an_etype, 3, DECODE (nratio, NULL, 3, 1), 5, DECODE (nratio, NULL, 5, 2),an_etype), av_sum_table)
                        * DECODE (an_etype, 3, NVL (nratio, 1), 5, NVL (nratio, 1), 1)
                        * DECODE (an_etype, 3, ln_react_loss, 5, ln_react_loss, (ln_line_loss + ln_act_loss))
                   / 100
              INTO ln_sum
              FROM feeders f, recompens r
             WHERE f.mid = an_mid AND f.nrecompens = r.nrecompens(+);
        END IF;

        IF ln_nwastepercentcalc = 2   -- фиксированные потери
        THEN
            SELECT DECODE (an_etype, 3, ln_react_loss, 5, ln_react_loss, (ln_line_loss + ln_act_loss))
              INTO ln_sum
              FROM DUAL;
        END IF;

        IF ln_nwastepercentcalc = 3   -- процент от расхода в квадрате
        THEN
           SELECT  util_pg.get_sum (f.mid, ad_stdate, ad_findate, DECODE (an_etype, 3, DECODE (nratio, NULL, 3, 1), 5, DECODE (nratio, NULL, 5, 2),an_etype), av_sum_table)
                        * DECODE (an_etype, 3, NVL (nratio, 1), 5, NVL (nratio, 1), 1)
                        * DECODE (an_etype, 3, ln_react_loss, 5, ln_react_loss, (ln_line_loss + ln_act_loss))
                   / 100
              INTO ln_sum
              FROM feeders f, recompens r
             WHERE f.mid = an_mid AND f.nrecompens = r.nrecompens(+);

            ln_sum := ln_sum * ln_sum;
        END IF;

        IF ln_nwastepercentcalc = 4   -- по формуле
        THEN
            ln_sum := 0;

            FOR lc IN lcur_sel
            -- пробегаем в цикле по всем параметрам и считаем
            LOOP
                ln_share_sum := 0;   -- обнулили суматор расхода для долевых точек
                ln_sum := 0; -- обнулили суматор потерь
                -- Посчитали время работы параметра
                SELECT get_par_time (lc.nconnectionparam, ad_stdate, ad_findate, 0), get_par_time (lc.nconnectionparam, ad_stdate, ad_findate, 1)
                  INTO ln_tr, ln_to
                  FROM DUAL;

                IF lc.nprocent = 1   -- берем как процент от расхода по параметру
                THEN
                    SELECT  util_pg.get_sum (f.mid, ad_stdate, ad_findate, DECODE (an_etype, 3, DECODE (nratio, NULL, 3, 1), 5, DECODE (nratio, NULL, 5, 2),an_etype), av_sum_table)
                           * DECODE (an_etype, 3, NVL (nratio, 1), 5, NVL (nratio, 1), 1)
                           * DECODE (an_etype, 1, lc.ep, 2, lc.ep, 3, lc.rp, 5, lc.rp)
                      INTO ln_sum
                      FROM feeders f, recompens r
                     WHERE f.mid = an_mid AND f.nrecompens = r.nrecompens(+);
                ELSE   -- иначе как обычный параметр
                    IF ln_to > 0   -- то потери хх уже есть иначе нечего считать
                    THEN
                        IF ln_tr > 0   -- тогда считаем не только хх
                        THEN
                            IF lc.obj_type = 610   -- т.е. 3-х обмоточный
                            THEN
                                FOR lct3 IN lcur_sel_t3 (lc.mid)   -- пробегаем в цикле по всем параметрам 3-х обмоточного тр
                                LOOP
                                    -- расход актива для расчета потерь
                                    ln_cons_a := get_par_consum (lct3.nconnectionparam, ad_stdate, ad_findate, 1, av_sum_table, 1);
                                    -- расход реактива для расчета потерь
                                    ln_cons_r := get_par_consum (lct3.nconnectionparam, ad_stdate, ad_findate, 3, av_sum_table, 1);

                                    IF lct3.nwinding = 1   -- т.е. верхняя обмотка, то кое что запомним
                                    THEN
                                        ln_pxx := NVL (lct3.pxx, 0);
                                        ln_sn := NVL (lct3.sn, 0);
                                        ln_ixx := NVL (lct3.ixx, 0);
                                    ELSE
                                        -- считаем сумарный расход по долевым точкам
                                        ln_share_sum :=
                                              ln_share_sum
                                            + get_share_consum (lct3.nconnectionparam, ad_stdate, ad_findate, ln_calcreaktlossbyreakt, av_sum_table,
                                                                1);
                                    END IF;

                                    -- считаем потери *****************************************
                                    IF lct3.sh > 0
                                    THEN
                                        IF an_etype = 1
                                        -- актив
                                        THEN
                                            ln_sum :=
                                                  ln_sum
                                                + NVL ((((ln_cons_a * ln_cons_a) + (ln_cons_r * ln_cons_r))) * lct3.pkz / (lct3.sh * lct3.sh * ln_tr),
                                                       0);
                                        ELSE
                                            -- реактив
                                            ln_sum :=
                                                  ln_sum
                                                + NVL (  (((ln_cons_a * ln_cons_a) + (ln_cons_r * ln_cons_r)))
                                                       * lct3.ukz
                                                       / 100
                                                       / (lct3.sh * lct3.sh * ln_tr),
                                                       0);
                                        END IF;
                                    END IF;
-- *****************************************
                                END LOOP;   -- конец цикла по всем параметрам 3-х обмоточного тр
                            ELSE   -- ************************ иначе все остальные параметры
                                -- расход актива для расчета потерь
                                ln_cons_a := get_par_consum (lc.nconnectionparam, ad_stdate, ad_findate, 1, av_sum_table, 1);
                                -- расход реактива для расчета потерь
                                ln_cons_r := get_par_consum (lc.nconnectionparam, ad_stdate, ad_findate, 3, av_sum_table, 1);
                                ln_pxx := NVL (lc.pxx, 0);
                                ln_sn := NVL (lc.sn, 0);
                                ln_ixx := NVL (lc.ixx, 0);
                                ln_share_sum :=
                                      ln_share_sum
                                    + get_share_consum (lc.nconnectionparam, ad_stdate, ad_findate, ln_calcreaktlossbyreakt, av_sum_table, 1);

                                -- считаем потери *****************************************
                                IF lc.sn > 0
                                THEN
                                    IF an_etype = 1
                                    -- актив
                                    THEN
                                        ln_sum :=
                                              ln_sum
                                            + NVL ((((ln_cons_a * ln_cons_a) + (ln_cons_r * ln_cons_r))) * lc.pkz / (lc.sn * lc.sn * ln_tr), 0);
                                    ELSE
                                        -- реактив
                                        ln_sum :=
                                              ln_sum
                                            + NVL ((((ln_cons_a * ln_cons_a) + (ln_cons_r * ln_cons_r))) * lc.ukz / 100 / (lc.sn * lc.sn * ln_tr), 0);
                                    END IF;
                                END IF;
--*************************************************
                            END IF;
                        ELSE
                             -- посчитаем потому что из-за Tr = 0 раньше не посчитали
                            -- расход актива для расчета потерь
                            ln_cons_a := get_par_consum (lc.nconnectionparam, ad_stdate, ad_findate, 1, av_sum_table, 1);
                            -- расход реактива для расчета потерь
                            ln_cons_r := get_par_consum (lc.nconnectionparam, ad_stdate, ad_findate, 3, av_sum_table, 1);
                        END IF;

                        -- потери в линии
                        ln_tmp := (((ln_cons_a * ln_cons_a) + (ln_cons_r * ln_cons_r))) * lc.l / 1000 / (lc.un * ln_to);

                        -- прибавляем к потерям холостой ход
                        IF an_etype = 1
                        THEN
                            -- актив + линия
                            ln_sum := ln_sum + ln_pxx * ln_to + NVL (ln_tmp * lc.ro, 0);
                        ELSE
                            -- реактив + линия
                            ln_sum := ln_sum + ln_sn * ln_ixx / 100 * ln_to + NVL (ln_tmp * lc.xo, 0);
                        END IF;

                        -- берем долю от потерь для точки
                        IF ln_share_sum > 0
                        THEN
                            SELECT   util_pg.get_sum (f.mid, ad_stdate, ad_findate,
                                                      DECODE (ln_calcreaktlossbyreakt, 1, 1, 2, 2, 3, DECODE (nratio, NULL, 3, 1), 5, DECODE (nratio, NULL, 5, 1)), av_sum_table)
                                   * DECODE (ln_calcreaktlossbyreakt, 3, NVL (nratio, 1), 5, NVL (nratio, 1), 1)
                              INTO ln_tmp
                              FROM feeders f, recompens r
                             WHERE f.mid = an_mid AND f.nrecompens = r.nrecompens(+);

                            ln_ret := ln_ret + (ln_sum * NVL (ln_tmp / ln_share_sum, 0));
                        END IF;
                    END IF;
                END IF;
            END LOOP;
        END IF;

        IF an_difzone > 0   -- то потери еще и дробим по зоне
        THEN
            SELECT SUM (er), SUM (DECODE (an_difzone, 1, aer, 2, ber, 3, cer))
              INTO ln_all, ln_z
              FROM bill
             WHERE mid = an_mid AND date_time > ad_stdate AND date_time <= ad_findate;

            ln_z := ln_z / ln_all;
        END IF;

        ln_ret := ln_ret * ln_z;
        RETURN ROUND (ln_ret);
    END;
--------------------------------------------------------------------------------
END;
/


