  --наполнение массива для построения дерева (для двух запросов)
  --Ильченко А.В.
 PROCEDURE sqlforpoints (an_par NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  IF an_par IS NOT NULL THEN
   OPEN acur_t FOR
    SELECT   mid, PARENT, NAME, short_name, ind
        FROM points
       WHERE PARENT = an_par AND mid >= 1000 AND ind <> 3
    ORDER BY NAME;
  ELSE
   OPEN acur_t FOR
    SELECT   mid, PARENT, NAME, short_name, ind
        FROM points
       WHERE PARENT IS NULL
    ORDER BY NAME;
  END IF;
 END;
