-- получение узлов дерева точек и групп
-- Kondakov A.G.
 PROCEDURE select_node (an_parent NUMBER, an_in_tbl NUMBER, an_cnt_child OUT NUMBER, acur_t OUT common_pg.tcur) IS
 -- an_parent  - ИД родительского узла, может быть NULL для корневых узлов
 -- an_in_tbl  - 0-тянем из групп, 1-тянем из точек, если an_parent=NULL, то задаем любым
 -- an_cnt_child - количество детей для an_parentы
 -- an_out_tbl - 0-узел из групп, 1-узел из точек
 -- is_point   - 0-папка, 1-точка
 BEGIN
   IF an_parent IS NULL THEN
    OPEN acur_t FOR
        SELECT gid id, parent, NAME, short_name, decode(mid,NULL,0,1) is_point, 0 an_out_tbl
        FROM  GROUPS
        WHERE parent IS NULL
        UNION ALL
        SELECT mid id, parent, NAME, short_name, 0 is_point, 1 an_out_tbl
        FROM  points
        WHERE mid = 1000
        ORDER BY an_out_tbl, is_point, NAME;
    SELECT count(*) INTO an_cnt_child
    FROM   (SELECT gid id FROM  GROUPS WHERE parent IS NULL
            UNION ALL
            SELECT mid id FROM  points WHERE mid = 1000);
   ELSE
    IF an_in_tbl=0 THEN -- тянем из групп
        OPEN acur_t FOR
            SELECT gid id, parent, NAME, short_name, decode(mid,NULL,0,1) is_point, 0 an_out_tbl
            FROM  GROUPS
            WHERE parent = an_parent
            ORDER BY an_out_tbl, is_point, NAME;
        SELECT count(*) INTO an_cnt_child
        FROM  GROUPS
        WHERE parent = an_parent;
    ELSIF an_in_tbl=1 THEN -- тянем из точек
        OPEN acur_t FOR
            SELECT mid id, parent, NAME, short_name, decode(ind,1,0,2,0,1) is_point, 1 an_out_tbl
            FROM  points
            WHERE parent = an_parent
            ORDER BY an_out_tbl, is_point, NAME;
        SELECT count(*) INTO an_cnt_child
        FROM  points
        WHERE parent = an_parent;
    END IF;
   END IF;
 END;
---------------------------------------------------------------------------
 -- возвращает имя узла по его ИД
 -- Kondakov A.G.
 PROCEDURE get_node_name(an_id NUMBER, an_in_tbl NUMBER, av_name OUT VARCHAR2) IS
 BEGIN
   IF an_in_tbl=0 THEN 
       SELECT NAME INTO av_name
       FROM GROUPS
       WHERE gid = an_id; 
   ELSIF an_in_tbl=1 THEN
       SELECT NAME INTO av_name
       FROM points
       WHERE mid = an_id; 
   END IF;
 END;
