 --построение таблицы для профиля день
 PROCEDURE get_day_values (an_id NUMBER, av_date VARCHAR2, an_in_tbl NUMBER, acur_t OUT common_pg.tcur) IS
 BEGIN
  IF an_in_tbl=0 THEN
      OPEN acur_t FOR
       SELECT   TO_CHAR (date_time - 1 / 86400, 'HH24') + 1 i,
                SUM(DECODE( g.inverted, 'y', 
                                 NVL(h.ed * DECODE(g.NPARTLY,1,0,1), 0), 
                                 NVL(h.er * DECODE(g.NPARTLY,2,0,1), 0)) ) er,
                SUM(DECODE( g.inverted, 'y', 
                                 NVL(h.er * DECODE(g.NPARTLY,2,0,1), 0), 
                                 NVL(h.ed * DECODE(g.NPARTLY,1,0,1), 0)) ) ed,
                SUM(DECODE( g.inverted, 'y', NVL(h.q3, 0), NVL(h.q1, 0)) ) q1,
                SUM(DECODE( g.inverted, 'y', NVL(h.q1, 0), NVL(h.q3, 0)) ) q3,
                SUM(DECODE( g.inverted, 'y', NVL(h.q4, 0), NVL(h.q2, 0)) ) q2,
                SUM(DECODE( g.inverted, 'y', NVL(h.q2, 0), NVL(h.q4, 0)) ) q4, 
                NVL (sumqm (NVL (vqm, qm_pg.defqm)), qm_pg.defqm) qm
           FROM halfhour h, GROUPS g
          WHERE g.gid IN (SELECT     gid
                              FROM GROUPS
                        CONNECT BY ((PRIOR gid=parent) OR (PRIOR NROOT2=NROOT2 AND PRIOR nroot1>0 AND nroot1 IS NULL))
                        START WITH gid = an_id )
                AND h.mid=g.mid
                AND date_time > TO_DATE (av_date, 'dd.mm.yyyy') AND date_time <= TO_DATE (av_date, 'dd.mm.yyyy') + 1
       GROUP BY TO_CHAR (date_time - 1 / 86400, 'HH24')
       UNION ALL
       SELECT   0 i, 
                SUM(DECODE( g.inverted, 'y', 
                                 NVL(h.ed * DECODE(g.NPARTLY,1,0,1), 0), 
                                 NVL(h.er * DECODE(g.NPARTLY,2,0,1), 0)) ) er,
                SUM(DECODE( g.inverted, 'y', 
                                 NVL(h.er * DECODE(g.NPARTLY,2,0,1), 0), 
                                 NVL(h.ed * DECODE(g.NPARTLY,1,0,1), 0)) ) ed,
                SUM(DECODE( g.inverted, 'y', NVL(h.q3, 0), NVL(h.q1, 0)) ) q1,
                SUM(DECODE( g.inverted, 'y', NVL(h.q1, 0), NVL(h.q3, 0)) ) q3,
                SUM(DECODE( g.inverted, 'y', NVL(h.q4, 0), NVL(h.q2, 0)) ) q2,
                SUM(DECODE( g.inverted, 'y', NVL(h.q2, 0), NVL(h.q4, 0)) ) q4,
                NVL (sumqm (NVL (vqm, qm_pg.defqm)), qm_pg.defqm) qm
           FROM halfhour h, GROUPS g
          WHERE g.gid IN (SELECT     gid
                              FROM GROUPS
                        CONNECT BY ((PRIOR gid=parent) OR (PRIOR NROOT2=NROOT2 AND PRIOR nroot1>0 AND nroot1 IS NULL))
                        START WITH gid = an_id )
                AND h.mid=g.mid
                AND date_time > TO_DATE (av_date, 'dd.mm.yyyy') AND date_time <= TO_DATE (av_date, 'dd.mm.yyyy') + 1
       ORDER BY 1;
  ELSIF an_in_tbl=1 THEN
      OPEN acur_t FOR
       SELECT   TO_CHAR (date_time - 1 / 86400, 'HH24') + 1 i,
                NVL (SUM (er), 0) er, NVL (SUM (ed), 0) ed, NVL (SUM (q1), 0) q1, NVL (SUM (q2), 0) q2,
                NVL (SUM (q3), 0) q3, NVL (SUM (q4), 0) q4, 
                NVL (sumqm (NVL (vqm, qm_pg.defqm)), qm_pg.defqm) qm
           FROM halfhour
          WHERE mid IN (SELECT     mid
                              FROM points
                        CONNECT BY PRIOR mid = PARENT
                        START WITH mid = an_id)
                AND date_time > TO_DATE (av_date, 'dd.mm.yyyy') AND date_time <= TO_DATE (av_date, 'dd.mm.yyyy') + 1
       GROUP BY TO_CHAR (date_time - 1 / 86400, 'HH24')
       UNION ALL
       SELECT   0 i, NVL (SUM (er), 0) er, NVL (SUM (ed), 0) ed, NVL (SUM (q1), 0) q1, NVL (SUM (q2), 0) q2, NVL (SUM (q3), 0) q3, NVL (SUM (q4), 0) q4,
                NVL (sumqm (NVL (vqm, qm_pg.defqm)), qm_pg.defqm) qm
           FROM halfhour
          WHERE mid IN (SELECT     mid
                              FROM points
                        CONNECT BY PRIOR mid = PARENT
                        START WITH mid = an_id)
                AND date_time > TO_DATE (av_date, 'dd.mm.yyyy') AND date_time <= TO_DATE (av_date, 'dd.mm.yyyy') + 1
       ORDER BY 1;
  END IF;
 END;
