                AND date_time <= ADD_MONTHS (TRUNC (TO_DATE (av_date, 'dd.mm.yyyy'), 'MM'), 1)
       GROUP BY TO_CHAR (date_time - 1 / 86400, 'DD')
       UNION ALL
       SELECT   0 i, NVL (SUM (er), 0) er, NVL (SUM (ed), 0) ed, NVL (SUM (q1), 0) q1, NVL (SUM (q2), 0) q2,
                NVL (SUM (q3), 0) q3, NVL (SUM (q4), 0) q4, NVL (sumqm (NVL (vqm, qm_pg.defqm)), qm_pg.defqm) qm
