       SELECT   0 i, 
                SUM(DECODE( g.inverted, 'y', 
                                 NVL(b.ed * DECODE(g.NPARTLY,1,0,1), 0), 
                                 NVL(b.er * DECODE(g.NPARTLY,2,0,1), 0)) ) er,
                SUM(DECODE( g.inverted, 'y', 
                                 NVL(b.er * DECODE(g.NPARTLY,2,0,1), 0), 
                                 NVL(b.ed * DECODE(g.NPARTLY,1,0,1), 0)) ) ed,
                SUM(DECODE( g.inverted, 'y', NVL(b.q3, 0), NVL(b.q1, 0)) ) q1,
                SUM(DECODE( g.inverted, 'y', NVL(b.q1, 0), NVL(b.q3, 0)) ) q3,
                SUM(DECODE( g.inverted, 'y', NVL(b.q4, 0), NVL(b.q2, 0)) ) q2,
                SUM(DECODE( g.inverted, 'y', NVL(b.q2, 0), NVL(b.q4, 0)) ) q4, 
                NVL (sumqm (NVL (vqm, qm_pg.defqm)), qm_pg.defqm) qm
           FROM bill b, GROUPS g
          WHERE g.gid IN (SELECT     gid
                              FROM GROUPS
                        CONNECT BY ((PRIOR gid=parent) OR (PRIOR NROOT2=NROOT2 AND PRIOR nroot1>0 AND nroot1 IS NULL))
                        START WITH gid = an_id )
                AND b.mid=g.mid
                AND date_time > TRUNC (TO_DATE (av_date, 'dd.mm.yyyy'), 'YYYY')
                AND date_time <= ADD_MONTHS (TRUNC (TO_DATE (av_date, 'dd.mm.yyyy'), 'YYYY'), 12)
       ORDER BY 1;
  ELSIF an_in_tbl=1 THEN
    OPEN acur_t FOR
       SELECT   TO_CHAR (date_time - 1 / 86400, 'MM') + 0 i, 
                NVL (SUM (er), 0) er, NVL (SUM (ed), 0) ed, NVL (SUM (q1), 0) q1, NVL (SUM (q2), 0) q2,
                NVL (SUM (q3), 0) q3, NVL (SUM (q4), 0) q4, NVL (sumqm (NVL (vqm, qm_pg.defqm)), qm_pg.defqm) qm
           FROM bill
          WHERE mid IN (SELECT     mid
                             FROM points
                        CONNECT BY PRIOR mid = PARENT
                        START WITH mid = an_id)
                AND date_time > TRUNC (TO_DATE (av_date, 'dd.mm.yyyy'), 'YYYY')
                AND date_time <= ADD_MONTHS (TRUNC (TO_DATE (av_date, 'dd.mm.yyyy'), 'YYYY'), 12)
       GROUP BY TO_CHAR (date_time - 1 / 86400, 'MM')
       UNION ALL
       SELECT   0 i, NVL (SUM (er), 0) er, NVL (SUM (ed), 0) ed, NVL (SUM (q1), 0) q1, NVL (SUM (q2), 0) q2,
                NVL (SUM (q3), 0) q3, NVL (SUM (q4), 0) q4, NVL (sumqm (NVL (vqm, qm_pg.defqm)), qm_pg.defqm) qm
           FROM bill
          WHERE mid IN (SELECT     mid
                              FROM points
                        CONNECT BY PRIOR mid = PARENT
                        START WITH mid = an_id)
                AND date_time > TRUNC (TO_DATE (av_date, 'dd.mm.yyyy'), 'YYYY')
                AND date_time <= ADD_MONTHS (TRUNC (TO_DATE (av_date, 'dd.mm.yyyy'), 'YYYY'), 12)
       ORDER BY 1;
  END IF; 
END;
