 PROCEDURE getschemeval1 (ad_myid NUMBER, i NUMBER, ad_date VARCHAR2, acur_t OUT common_pg.tcur) IS
 BEGIN
  OPEN acur_t FOR
   SELECT NVL (er, 0) er, NVL (ed, 0) ed, NVL (q1, 0) q1, NVL (q2, 0) q2, NVL (q3, 0) q3, NVL (q4, 0) q4
     FROM halfhourold
    WHERE mid = ad_myid AND date_time > TO_DATE (ad_date, 'dd.mm.yyyy') + (i - 1) / 24 AND date_time <= TO_DATE (ad_date, 'dd.mm.yyyy') + i / 24;
 END;

